pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Reward high fill ratio non-linearly.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 120.0 * fill * fill;

    // Penalize dead space that is too small for typical future items
    // (dead space below the minimum plausible item size is wasted).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 50.0;
        }
        // Penalize if placing here wastes space the next item could use.
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0;
        }
    } else {
        // Last item in the stream: any leftover space is pure waste.
        score += 30.0;
    }

    // Global state: prefer tighter bins when many bins are open
    // (consolidation pressure), less so early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0);
    score += 50.0 * (1.0 - progress) * tightness;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Prefer bins whose residual is small relative to capacity (best-fit core).
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that are small but unusable (dead space).
        let dead_zone = 9.0;
        if (post_residual as f64) < dead_zone {
            score += 50.0 * (dead_zone - post_residual as f64);
        }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if we leave a tempting mid residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste.min(60.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are fragmented / poor fits.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: neutral-ish, tuned against typical residuals.
        score += 30.0;
        // If item is large relative to capacity, new bin is fine.
        score -= 0.3 * item_size as f64;
        // If many open bins have large mean residual, prefer reusing them.
        score += 2.0 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Few fitting bins means poor global fit; new bin more acceptable.
        score -= 40.0 * (fitting_bins_count as f64).min(3.0);
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 60.0 * tightness;
        // Prefer filling older/more-filled bins to keep open count low.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild global pressure to reduce mean residual spread.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are pure waste.
    let min_item = 1u32;
    let look = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < look && post_residual > 0 {
        // Unusable gap for the next item: heavy penalty scaled by how close it is to being useless.
        let waste = (look - post_residual) as f64;
        score += waste * 4.0;
        if post_residual < 10 {
            score += 30.0; // near-total dead space
        }
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    }

    // Reward tight fits relative to capacity (small post_residual fraction).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.5;

    // Mean-residual coupling: if this bin's residual is far below mean, it's already fragmented.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and diversity of bins is valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a decent fit.
        score = bin_capacity as f64 * 0.55;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 15.0;
        // But if the item leaves a good gap for the known next item in a new bin, mild bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Reward leaving room for the lookahead item in an existing bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize bins whose residual is excessively large relative to item (poor consolidation target).
        if bin_residual > item_size * 3 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat gaps < 10 (min item) as fully dead; gaps < 20 as partially dead.
    let dead = (10u32.saturating_sub(post_residual.min(10))) as f64;
    score += 6.0 * dead;

    // Partial dead-space: gap that can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 * (open_bins_count as f64).sqrt();
        // But allow new bin early in stream or when existing residuals are large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0; // existing bins have room; don't open new
        }
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance usage).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste == 0 {
            score -= 900.0;
        } else {
            // partial reward proportional to how well next item fits
            let tightness = 1.0 - (chain_waste as f64) / (bin_capacity as f64);
            score -= 300.0 * tightness;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use the leftover; penalize dead space relative to mean residual
        score += 0.5 * (post_residual as f64 - mean_residual).abs();
        score += (post_residual as f64) * 0.3;
    }

    // Penalize creating tiny unusable gaps (< 10, the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // fresh bin score: base cost of opening a new bin
        score = (bin_capacity as f64) * 0.9;
        // attractive if mean residual is fragmented (low mean residual means open bins are full)
        if mean_residual < item_size as f64 {
            score -= 100.0;
        }
        // if no open bin fits well, opening new bin is fine
        if post_residual > 0 && post_residual < 20 {
            score += 50.0;
        }
    }

    // Late in the stream, be more conservative with open bins (consolidate)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Slight preference for bins below mean residual (keep large residuals for large items)
    if (bin_residual as f64) < mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: polynomial in normalized post_residual modulated by progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 24.0 * poly * cap * (0.5 + progress);
    // Penalize large dead space more as stream progresses (fewer chances to reuse it)
    score += progress * norm_pr * norm_pr * cap * 0.35;
    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 6.0 * (-(pr / cap) * 4.0).exp();
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    }
    // Slight preference for bins below mean residual (keeps balance of usable space)
    score += 0.05 * (mean_residual - pr);
    // New-bin candidate: penalize mildly unless current residuals are all poor
    if bin_residual == bin_capacity {
        let tightness = (-(mean_residual / cap) * 2.0).exp();
        score += 12.0 - 10.0 * tightness;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small to be useful, but nonzero.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Very tight fit (<= 5 left): strong reward.
    else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward if post_residual can still fit the lookahead item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild penalty for stranded space.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items thinly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure;

    // Prefer bins whose residual is close to the mean (balanced packing) early on;
    // later, prefer dumping into low-residual bins.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * (0.5 - 0.4 * progress);

    // New-bin candidate: neutral baseline; only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Baseline slightly above typical good-fit scores, reduced when many bins
        // already open (consolidation pressure) or item is large.
        score = 30.0 + item_size as f64 * 0.3 - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving fresh space for a big follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Large usable residuals are rewarded.
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are already open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if current bins are nearly full.
        score = 70.0;
        if mean_residual < 15.0 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Late in the stream, avoid leaving many almost-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;

        // Lookahead synergy: if the next item fits the post residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // A residual below the minimum possible item size (1) is impossible here, but residuals
    // smaller than the next item (or a generic small threshold) are "dead space".
    let min_useful = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }
    // Also penalize any gap that cannot fit the lookahead item (waste w.r.t. k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness coupling: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current bin fits
    // are poor (large dead space). Default new-bin score is its huge residual, so add a mild
    // bias and only discount it when the current placement would leave bad dead space.
    if bin_residual == bin_capacity {
        // base: residual (=capacity) is already large; add fixed opening cost
        score += 15.0;
        // discount slightly when many bins are open (consolidation pressure reversed:
        // with many open bins, a fresh bin keeps residuals balanced)
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score -= (mean_residual - bin_residual as f64).abs() * -0.0; // neutral placeholder
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Late-stream tightening: as the stream progresses, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0; // no-op placeholder for calibration symmetry
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 25.0; // nearly dead space (rarely usable)
    } else if post_residual < 35 {
        score += 8.0; // moderately wasteful gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (more filled than average).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Lookahead: if next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item cannot fit the post residual, the leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: baseline reference; keep it attractive only when
    // existing placements would be very poor.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/3, 1/4 of C)
    let cap = bin_capacity as f64;
    let half = (cap * 0.5) as u32;
    let third = (cap / 3) as u32;
    let quarter = (cap / 4) as u32;

    // Penalize residuals that fall in "dead" harmonic classes: too small for
    // typical items but not zero. Zero residual is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else {
        // Dead-space class: residual < smallest plausible next item chunk
        if post_residual < 10 {
            score += 25.0;
        }
        // Harmonic bucket: how close post_residual is to a useful fraction
        let pr = post_residual as f64;
        let frac = pr / cap;
        // Residuals in (0.5C, 1.0C) are healthy; in (0.25C, 0.5C) marginal;
        // below 0.25C increasingly dead unless near-zero.
        if frac > 0.5 {
            score -= 8.0;
        } else if frac > 0.25 {
            score += 4.0;
        } else {
            score += 12.0;
        }
        // Integer-division class: post_residual / quarter
        let class = post_residual / quarter.max(1);
        score += class as f64 * 2.0;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual,
    // penalize if next item cannot use post_residual's harmonic class.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0; // chain fit
        } else if (next_item_size as u32) <= post_residual {
            // next item fits here too: mild bonus proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 6.0 * tight;
        } else {
            // next item cannot fit in this residual: dead class penalty
            score += 5.0;
            // modulo harmony: if post_residual % next_item_size is small,
            // a future split could still use it
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit (small post_residual)
        score *= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, prefer it only when all open
    // bins would be badly fragmented. Empty bin gets post_residual = cap,
    // which already scores high (large), so add mild reward scaled by
    // fragmentation of open bins.
    if bin_residual == bin_capacity {
        score -= 10.0 + (open_bins_count as f64).sqrt() * 3.0;
        // but if mean residual is large (open bins have room), discourage new bin
        score += mean_residual * 0.15;
    }

    // Stream progression: early on, be more conservative with new bins;
    // late in stream, accept fragmentation less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin classes balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 18.0;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.5 * next_item_size as f64;
        } else {
            score += 6.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Many fitting bins: can afford to be picky; penalize loose fits harder.
    if fitting_bins_count > 2 {
        score += fit_ratio * 12.0;
    }

    // Global pressure: few bins relative to progress -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 1.5 * (1.0 - progress);
    }

    // Prefer bins whose residual is near the mean (keeps residuals balanced),
    // but only early in the stream; late, prefer filling high-residual bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if progress < 0.5 {
        score += dev * 0.3;
    } else {
        score -= dev * 0.2;
    }

    // New-bin candidate: only attractive when it enables a big item pairing
    // or existing bins are poorly suited.
    if bin_residual == bin_capacity {
        let base = 30.0 + fit_ratio * 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score = base - 15.0; // pair next item in fresh bin
        } else {
            score = base + (open_bins_count as f64) * 2.0;
        }
        if fitting_bins_count > 0 {
            score += 8.0; // existing bins can take it; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual after placement too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += 0.8 * waste + 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain usable for the lookahead item
        score -= 15.0;
        // Extra reward for near-perfect two-item packing
        let two_fit = (item_size + next_item_size) as f64;
        if (bin_residual as f64 - two_fit).abs() <= 5.0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize bins far below mean residual (fragmenting the bin population)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in the stream: be pickier (long horizon ahead -> avoid small residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Many open bins: prefer consolidating into existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: baseline cost of opening a fresh bin
    if bin_residual == bin_capacity {
        // Attractive only late in stream or when many bins are open and item is large
        let new_bin_bonus = 40.0 * progress + 2.0 * open_bins_count as f64 + 0.3 * item_size as f64;
        score = bin_capacity as f64 - new_bin_bonus + 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can also host the next item
        }
        // Never open a new bin if it's the only fitting option and a good fit exists
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that no plausible item can use
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 15.0;
    }

    // Tight-fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // bonus if post_residual + next item leaves near-perfect packing
        let two_left = post_residual as i64 - next_item_size as i64;
        if two_left == 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let mean_r = mean_residual;
        // open new bin only when existing residuals are large/fragmented
        score += 30.0 - 0.5 * mean_r - 2.0 * crowd * (1.0 - progress);
        if mean_r > item_size as f64 {
            score += 10.0; // existing bins clearly have room; discourage new bin
        }
    } else {
        // prefer bins with residual close to item (best-fit flavor)
        score += 0.3 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Prefer bins whose residual is below the mean (compact bins first)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild preference for lower post_residual as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit gets a big bonus.
        score -= 40.0 / (1.0 + diff);
        // Reward small post-residuals that still allow the next item (tight chaining).
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Post-residual too small for the next item: penalize dead space.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: pure tightness objective.
        score -= 10.0;
    }

    // Tight fit reward relative to bin capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Penalize leaving residual far below mean (fragmented leftovers), reward above-mean slack
    // only mildly so we don't hoard large bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are very fragmented
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin when item is huge and would leave a nearly full bin anyway.
        if item_size >= 70 {
            score -= 30.0;
        }
        // More open bins => more fragmentation risk => new bin slightly more attractive.
        score -= 1.5 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for leaving exactly tiny unusable slivers (1..=5 dead space).
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // bonus when next item fits into leftover space
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    } else {
        // last item: prefer fullest packing
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fits exist among open bins
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress);
        // but if item barely fits anywhere (large item), new bin is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 9.0;
        }
        // if mean residual is small, open bins are nearly full -> new bin OK
        if mean_residual < item_size as f64 * 1.1 {
            score -= 12.0;
        }
    }

    // Prefer bins with residual close below the item (best-fit flavor)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 5.0 * tightness;

    // Slight preference to balance residual mass across many open bins
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in stream, encourage compact packing (favor filling);
    // late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress) * (1.0 - fit_ratio);

    // Discourage proliferation of open bins when item fits several
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor for this item
    // (item is large relative to mean residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        score = bin_capacity as f64 - 10.0 * desperation - 5.0 * (fitting_bins_count == 0) as i32 as f64;
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by relative fill achieved.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space (waste), tolerate large leftover space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer filling existing bins over new ones.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large dead space would be created).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases when open bins are numerous
        // or the item is large (poor fit anywhere).
        let waste_elsewhere = (bin_capacity - item_size) as f64;
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else {
            1.0
        };
        score = 60.0 - 20.0 * poor_fit_pressure - 0.3 * waste_elsewhere
            + (open_bins_count as f64).sqrt() * 2.0;
        // Late in stream, avoid opening new bins unless necessary.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 1.5 * progress * progress);
    score += 20.0 * poly;

    // Reward tight fits smoothly (quadratic in item fill fraction)
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) * (0.5 + progress);
    } else if next_item_size > 0 {
        score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * norm_post);
    }

    // Mild penalty for many open bins with high mean residual
    score += 0.5 * (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64).powi(2);

    // New-bin candidate: penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let n2 = norm_pr * norm_pr;
    let n3 = n2 * norm_pr;

    let mut score = pr * (0.6 + 0.5 * progress) - pr * pr / (2.0 * cap) + pr * p2 * 8.0 + n3 * 40.0 * (1.0 - progress);

    // Penalize residuals that cannot fit the next item (lookahead waste)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx).abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.8 * (0.5 + p2);

    // Deviation from mean residual: prefer typical fills
    score += ((pr - mean_residual) / cap).abs() * 10.0 * (1.0 - p3);

    // New-bin candidate handling: empty bin gets a calibrated baseline
    if bin_residual == bin_capacity {
        score = 95.0 - 25.0 * progress - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // allow new bin when nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (tight packing).
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize dead space that is too small for any plausible item.
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // 2-step lookahead: reward bins where the leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Extra reward for a near-perfect chain: leftover just above next item.
        let slack = post_residual - next_item_size;
        score -= (slack as f64).min(30.0) * 2.0;
    } else if next_item_size > 0 {
        // Leftover cannot fit next item; penalize proportional dead space.
        score += 60.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 100.0;
        // Late in the stream, avoid opening new bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size (best-fit core).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still go here; reward proportionally.
            score -= (post_residual as f64 / next_item_size as f64).min(3.0) * 8.0;
        } else {
            // Dead space for the next item: penalize more as stream progresses.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += (next_item_size - post_residual) as f64 * (1.5 + 2.5 * progress);
        }
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // near-perfect fill on last chance
        }
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // which preserves roomier bins for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if bin_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post-fit leftover is very poor and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit_here = (post_residual as f64) > (bin_capacity as f64) * 0.6;
        if poor_fit_here || fitting_bins_count == 0 {
            score -= 15.0; // allow opening a fresh bin
        } else {
            score += 20.0; // discourage wasteful new bins
        }
    }

    // Mild time-horizon modulation: early in the stream, be more conservative
    // about creating fragmented residuals (long future ahead).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item size are worthless; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: post_residual just below typical item sizes is bad,
    // but a residual that still fits a meaningful chunk is good.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item would not fit and post_residual is small, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins with slack -> discourage spreading,
    // favor bins that absorb more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress) * 0.5;

    // Prefer bins tighter than average (concentrate slack).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when fitting_bins_count is high (fragmented slack) or fit is poor.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are chosen only when justified.
        score += 8.0 + open_bins_count as f64 * -0.2;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for lookahead pairing in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste. Penalize "unusable" small gaps quadratically.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 2.5;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward tightness relative to bin capacity (best-fit core, sharpened).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when existing fits are bad
    // (i.e., when the item leaves a large awkward gap in any open bin).
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if post_residual >= 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 0.0 };
        // A fresh bin scores like a mediocre fit: high base, reduced if open bins are
        // already fragmented (high mean residual) and this item is large.
        score = bin_capacity as f64 * 0.75
            - bad_fit_pressure * 25.0
            - fill_ratio * 20.0
            + open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: mild penalty for small leftovers.
        if post_residual < next_item_size && post_residual > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 40.0 * poly;

    // Penalize dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let gate = 1.0 - (-pr / (next_item_size as f64 + 1.0)).exp();
        score += 15.0 * gap * gate;
    } else {
        score += 10.0 * norm_pr * progress;
    }

    // Reward last-chance bins (only one fitting bin) with smooth decay
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins tighter than average
    score += 5.0 * (pr - mean_residual) / cap;

    // Slightly discourage opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted residual
            score += 40.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much of the remaining
            // space it consumes (tight chain packing).
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 250.0 * fill;
        } else {
            // Next item does NOT fit here: penalize, but less if post_residual
            // is small (dead space unlikely to be usable anyway).
            let waste = next_item_size as f64 - post_residual as f64;
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 120.0 * waste / (next_item_size as f64) * (1.0 - dead);
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer placing into them (waste little extra capacity).
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 200.0 - 180.0 * fragmentation - 100.0 * large_item;
        // Early in the stream, opening bins is cheap (future items can fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Mild penalty for very small leftover slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (2-step lookahead core).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Perfect 2-step match: next item exactly fills the remaining space.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > 0 && next_item_size < post_residual {
            // Next item fits inside the post residual: good chaining.
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - chain_left / bin_capacity as f64);
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover space: penalize dead space creation.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to ever be useful (below min item size 1..100 assumption ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins, but relax late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 30.0 * progress;
        // If the next item matches a fresh-bin pairing (item + next <= capacity), opening is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
        // If mean residual is small, existing bins are nearly full; opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Slight preference for fewer open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are unusable for items >=10,
    // so heavily penalize them; zero residual is perfect.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 19 {
            score += 12.0;
        } else {
            // Larger leftovers are more reusable: mild reward relative to mean residual
            score -= 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Reward bins whose residual is just above the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score -= 0.3 * (bin_capacity as f64 - tightness);

    // Open-bin pressure: discourage scattering across many bins,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 9.0 { score -= 30.0; } else { score -= 8.0; }
    }
    // If next item would be stranded by a tiny gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 9 {
        score += 20.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual <= 9;
        let crowded = open_bins_count as f64 > mean_residual / 10.0;
        if bad_fit || crowded {
            score -= 15.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residual that closely matches the lookahead item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 3.0 * (-gap / 20.0).exp();
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely
    // better (no fitting bins, or huge item with no good home).
    if bin_residual == bin_capacity {
        let base_penalty = 12.0 + open_bins_count as f64 * 0.5;
        let scarcity = if fitting_bins_count == 0 { 20.0 } else if fitting_bins_count == 1 { 8.0 } else { 0.0 };
        score += base_penalty - scarcity;
        // Early in stream, be more willing to open bins (diversify).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into below-average-residual bins preserves large residuals elsewhere.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for very large leftover chunks that waste capacity.
    if post_residual > 40 {
        score += 0.2 * (post_residual - 40) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 400.0 - slack * 8.0;
    }
    // Next item does NOT fit in the residual: penalize proportionally
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize leaving dead space (residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // If item perfectly halves a fresh bin, opening may be attractive
        if item_size * 2 == bin_capacity {
            score -= 80.0;
        }
        // If nothing else fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for good structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (sizes >= 1), so penalize them harshly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
