    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate handling: opening a fresh bin should only win when
    // the fit into existing bins is poor. Make the empty bin moderately
    // attractive by default but let dead-space penalties / last-chance
    // bonuses of real bins dominate.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 2.0;
        // Lookahead: if next item is large, a fresh bin is less useful.
        if next_item_size > 0 {
            score += next_item_size as f64 * 0.15;
        }
    } else {
        // Reward bins whose residual stays compatible with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
        // Slight preference for tighter bins (below-mean residual).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

