    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, non-linearly (quadratic + cubic for dead-space penalty)
    let mut score = x.powi(2) * 30.0 + x.powi(3) * 40.0;

    // Stream-progress coupling: early on, mild waste is tolerable (explore);
    // later, waste becomes increasingly costly.
    let urgency = 0.5 + 1.5 * progress * progress;
    score *= urgency;

    // Reward tight fits more strongly as stream progresses (smooth interaction).
    let tight = (1.0 - x).powi(2);
    score -= 12.0 * tight * (0.4 + 0.8 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Penalize bins that are far below the mean residual (poor relative fit),
    // smoothly scaled by progress.
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - x) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space proportionally to how unusable it is.
        score += 5.0 * x * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin gets neutral-ish score that becomes
    // attractive only when open-bin fits are poor (large post residual late in stream).
    if bin_residual == bin_capacity {
        score = 0.55 * cap - 4.0 * progress * cap;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Mild penalty for too many open bins, smoothed.
    score += (open_bins_count as f64).sqrt() * (0.3 + 0.7 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into octiles.
    let octant = post_residual / (bin_capacity / 8).max(1);
    let class_penalty: f64 = match octant {
        0 => -60.0,                 // near-perfect fit
        1 => -25.0,
        2 => 10.0,
        3 => 25.0,
        4 => 30.0,
        5 => 15.0,
        6 => 0.0,
        _ => -5.0,                  // almost empty bin, roomy
    };
    score += class_penalty;

    // Dead-space class: post_residual that no typical item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 90.0;              // unusable sliver
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0;
            // harmonic match: next item fills post_residual to a low octant
            let pr2 = post_residual - next_item_size;
            if pr2 < 10 { score -= 25.0; }
        } else {
            score += 20.0;
        }
    } else {
        // last item: prefer minimal residual strongly
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive if all fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, relaxed as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin guarantees a follow-up fit
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else if fitting_bins_count >= 1 {
        // slight preference for tighter existing bins via residual-to-mean deviation
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Reward filling large fractions of the bin with the current item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Modulo harmonic: post_residual divisible by common item sizes is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 4 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Mid-range gaps (11..=25) are also risky for typical item sizes.
    if post_residual > 10 && post_residual <= 25 {
        score += (26.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual near zero but not tiny dead space).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 2.5;

    // Mean-residual coupling: placing into a bin already above mean residual
    // helps consolidate space.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 15.0 * (1.0 - progress) + open_bins_count as f64 * 1.5;
        score -= new_bin_bonus;
        // A fresh bin wastes space if the item is small relative to capacity.
        score += (bin_capacity - item_size) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;

        if next <= pr {
            let match_quality = 1.0 - (pr - next) / bin_capacity as f64;
            // Strong reward when post_residual exactly hosts the next item
            score -= 60.0 * match_quality * match_quality;

            // Exact chain: item + next item fills bin perfectly
            if next == pr {
                score -= 500.0;
            }
        } else {
            // Penalize post_residual that can't host next item but is awkwardly small
            let dead = pr / next;
            if pr < next && pr < 10.0 {
                score += 40.0 * (1.0 - dead);
            }
        }

        // Compare post_residual against mean residual: keep bins near the packable band
        let band_low = mean_residual * 0.4;
        let band_high = mean_residual * 1.6;
        if pr < band_low {
            score += 25.0 * (band_low - pr) / bin_capacity as f64;
        } else if pr > band_high {
            score += 15.0 * (pr - band_high) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        // Open a new bin for large items or when open bins have large residuals already
        if big_item > 0.6 || (open_bins_count > 0 && fragmentation > 0.5) {
            score -= 120.0 * big_item;
        } else {
            score += 150.0;
        }
    }

    // Slight preference for bins with larger residual (waste less of tight bins)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild exploration of bin-count balance early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tight fit reward: post residual too small for any future item (min size 1)
    if post_residual > 0 && post_residual < 5 {
        score -= 25.0;
    }

    // Fill ratio: prefer bins where item occupies a large fraction of residual
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening new bins when many bins are already open with slack
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
        // but allow new bin if mean residual is very low (nothing fits well anywhere)
        score -= 2.0 * mean_residual;
    }

    // Global slack balancing: penalize bins whose residual deviates from mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.2 * dev.abs();

    // Time horizon: early in stream, be conservative (keep residuals flexible);
    // late in stream, pack greedily
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * t * fill;

    // Dead-space penalty: residual left is large but less than typical item sizes
    if post_residual >= 1 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual cost, non-linearly warped by stream progress.
    // Early on, tight fits matter less; late, small residuals are penalized heavily.
    let warp = 0.5 + 1.5 * progress * progress;
    let mut score = pr * warp;

    // Smooth quartic coupling: penalize mid-range residuals (awkward dead space),
    // reward near-zero residuals, mildly tolerate large residuals (still usable).
    let x = norm_pr;
    score += 40.0 * (x * x * x * x - 2.0 * x * x * x + x * x) * (1.0 + progress);

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        let fit_reward = (1.0 - fit_gap / cap).max(-1.0);
        score -= 15.0 * fit_reward * fit_reward * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))).ln().max(0.0);
    score += 5.0 * pressure * (0.3 + 0.7 * progress);

    // New-bin candidate: smooth sigmoid-like bias so a fresh bin is chosen only
    // when existing residuals are poor fits relative to the item.
    if bin_residual == bin_capacity {
        let mean_fit = (mean_residual - item_size as f64) / cap;
        let badness = 1.0 / (1.0 + (-8.0 * mean_fit).exp());
        score += 30.0 * badness - 10.0 * (1.0 - progress);
    }

    // Global smooth progress scaling of residual waste.
    score += 10.0 * norm_pr * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small moduli reveal
    // "usable" leftover classes (e.g. divisible by 10, 20, 25 are more
    // likely to be filled by future items drawn from typical grids).
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;
    let r25 = (pr % 25) as f64;
    let r50 = (pr % 50) as f64;

    // Reward post-residuals in harmonically clean classes.
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Penalize dirty residues proportionally to how far off-grid they are.
        score += (r10 * 0.6 + r20 * 0.3 + r25 * 0.2 + r50 * 0.1);
    }

    // Dead-space penalty: small-but-nonzero post_residual is wasted space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Coupling with lookahead: if next item fits exactly into the
    // post-residual (same harmonic class), strongly reward.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= pr {
            if ni == pr {
                score -= 25.0;
            } else if pr % ni == 0 {
                score -= 10.0;
            } else if ni % 10 == 0 && pr % 10 == 0 {
                score -= 6.0;
            } else {
                score += (pr - ni) as f64 * 0.3; // mismatch leaves more debris
            }
        } else {
            // Next item won't fit here anyway; slight penalty for hoarding space.
            score += 3.0;
        }
    }

    // Integer-division threshold: classify post_residual into octiles of capacity.
    let octile = (pr * 8) / bin_capacity.max(1);
    score += match octile {
        0 => -5.0,
        1 => 2.0,
        2 => 0.0,
        3 => 1.0,
        4 => 0.0,
        5 => -1.0,
        6 => -2.0,
        _ => -3.0,
    };

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e. mean residual is low relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 20.0 + mean_residual * 0.4 + open_bins_count as f64 * 1.5 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    // Mild preference to keep bins balanced with mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item are unusable "dead space" — penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 12.0; // risky gap: only fits tiny items
    } else if post_residual <= 25 {
        score += 4.0;
    } else {
        // Usable residual: reward proportionally to how reusable it is.
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave a gap able to host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size / 2 {
            score -= 5.0;
        } else {
            score += 10.0; // gap too small for the known next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins are congested
    // (low mean residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score = 45.0
            + (mean_residual / bin_capacity as f64) * 30.0
            + (open_bins_count as f64).sqrt() * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // reserving a fresh bin for the big next item
        }
    }

    // Mild pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.6;

    // Late-stream tightening: favor consolidation as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Post residual can host next item: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
        } else {
            // Next item cannot fit in the leftover: penalize dead space, worse when
            // the miss is small (wasted potential) relative to next item size
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Compare against mean residual across open bins: prefer bins that end up
    // tighter than average (good consolidation), penalize loose leftovers
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Penalize opening a new bin mildly, but
    // reward it if the current item would leave a tiny unusable sliver or if
    // next item is large and no bin can chain.
    if bin_residual == bin_capacity {
        let mut penalty = 15.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // next item needs a fresh bin anyway: opening now is fine
            penalty -= 20.0;
        }
        if item_size >= 90 {
            penalty -= 10.0; // huge item: fresh bin is natural
        }
        score += penalty;
    }

    // Prefer filling existing bins more as the stream progresses (less fragmentation late)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual - item_size) as f64 / bin_capacity as f64;

    // Slight preference to keep number of open bins low
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to the smallest plausible item (1).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // nearly-full bin: great outcome
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize more if we waste a lot of space
            score += 0.05 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0));
        }
    } else {
        // last item: any placement is fine, prefer fullest packing
        score -= 10.0;
    }

    // Scarcity pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large item, poor fit_ratio) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (fit_ratio - 0.6).max(0.0) * 40.0;
        score += 30.0 + 20.0 * progress - desperation - 2.0 * open_bins_count as f64;
        // early in the stream, new bins are cheap
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global balance: prefer bins whose residual is below the mean (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer reducing the number of very open bins by filling laggards.
    score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with a non-linear penalty for tiny dead space
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth interaction: dead space matters more as the stream progresses
    let dead_penalty = (1.0 - norm_pr).powi(3) * (1.0 - progress);
    score -= 12.0 * dead_penalty;

    // Lookahead coupling: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx) / cap;
        let fit_kernel = 1.0 / (1.0 + (fit_gap * 6.0).powi(2));
        score -= 25.0 * fit_kernel * (1.0 + 0.5 * progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 8.0 * scarcity * (1.0 - norm_pr);

    // Crowd-aware: mildly penalize contributing to residual imbalance across many open bins
    let imbalance = (mean_residual - pr).abs() / cap;
    score += 5.0 * imbalance * (open_bins_count as f64).ln();

    // New-bin candidate: make empty bins slightly less attractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small,
    // "dead space" classes (tiny gaps) are penalized unless post_residual == 0.
    let pr = post_residual;
    if pr > 0 {
        // mod-10 classes: residuals in [1,10] are hard to fill -> penalty
        let class = pr % 10;
        if class > 0 && pr <= 20 {
            score += 8.0 + (10 - class) as f64;
        }
        // mod-25 classes: residuals leaving exact quarter gaps are good
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 50 == 0 {
            score -= 4.0;
        }
    } else {
        // perfect fit
        score -= 15.0;
    }

    // Integer-division threshold on next_item_size: does the next item
    // fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            // harmonic compatibility: next item leaves a small residual again
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 5.0;
            }
            if nxt_post < 10 {
                score += 4.0; // creates fresh dead space
            }
        } else {
            // next item cannot use this residual: dead space likely
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless current bin is badly fragmented
    if bin_residual == bin_capacity {
        score += cap_f * 0.5;
        // allow fresh bin early in stream or when many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 {
            score -= 20.0;
        }
        if open_bins_count as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Prefer tight fills relative to mean residual
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // if new-bin candidate (residual == capacity), add pressure when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for using existing bins as the stream progresses.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect or near-perfect fit (low dead space).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward proportional to how snugly
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead potential
            score += 15.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare bin residual against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when item is small enough to fit elsewhere comfortably.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * item_size as f64;
        if fitting_bins_count >= 1 && item_size <= 50 {
            score += 80.0;
        }
        // Opening a new bin is fine if item is huge (near full bin usage).
        if item_size >= 90 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate: favor filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be more conservative about filling bins poorly
    // (many items remain); later, accept imperfect fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> discourage opening more,
    // encourage consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
        score -= (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: penalize more when open bins are roomy on average.
        score += 10.0 * (mean_residual / bin_capacity as f64);
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in stream, opening a new bin is less costly.
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: prefer tight fits (small post_residual) with quadratic sharpening
    let x = pr / cap;
    score += 40.0 * x * x;

    // If the next item fits into the post-residual, reward this bin strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 30.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize non-linearly
        let gap = (next_item_size - post_residual).min(next_item_size) as f64 / cap;
        score += 25.0 * gap * gap;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Stream-progress coupling: early on tolerate imperfect fits to build bins,
    // late in stream demand tightness (higher weight on post_residual)
    score *= 1.0 + 0.5 * progress * x;
    score -= 10.0 * progress * (1.0 - x);

    // Prefer bins below mean residual (consolidate waste), smooth coupling
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: mild penalty so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as dead-space classes.
    let post = post_residual;
    let residue_class = (post % 10) as f64;
    score += residue_class * 0.35; // prefer post-residuals aligned to decade boundaries

    // Integer-division thresholds: classify leftover capacity into usable slabs.
    let slab = post / 10; // 0..10 slabs of size 10
    score -= slab as f64 * 2.0;

    // Perfect-fit harmonic classes: post_residual in {0} is ideal.
    if post == 0 {
        score -= 60.0;
    }
    // Small unusable remnants (1..=5) are dead space.
    if post >= 1 && post <= 5 {
        score += 25.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            let next_class = (next_item_size % 10) as f64;
            // Reward if next item leaves another clean class (post - next) % 10 == 0
            if (post - next_item_size) % 10 == 0 {
                score -= 18.0;
            } else {
                score -= 6.0 - next_class * 0.1;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overflow gap.
            let gap = (next_item_size - post) as f64;
            score += gap.min(40.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when mean residual is tight
    // relative to item size, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 20.0 + open_bins_count as f64 * 1.5;
        }
    }

    // Penalize bins whose residual deviates from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..=10)
    // are unusable dead space -> heavy penalty for tiny leftover gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward keeping residual large enough to host future mid-size items.
    if post_residual >= 40 {
        score -= 15.0;
    } else if post_residual >= 20 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 3.0;

    // Compare against mean residual: bins far above mean are better targets
    // (they are the "emptiest", so filling them balances residuals).
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    // (chain packing); if not, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the item is large or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = item_size as f64 * 0.5 + 40.0;
        // Prefer opening a new bin for large items that would leave poor gaps.
        if item_size >= 60 {
            score -= 50.0;
        }
        // If several bins fit, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Soft lookahead: next item fits into the post-residual comfortably.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover space: penalize dead space proportionally.
        score += (post_residual as f64) * 0.3;
    }

    // Penalize small unusable post-residuals (dead space) more than large ones,
    // unless the next item can fill it.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large and no good fit exists; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= bin_capacity / 2 {
            score -= 120.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten packing (less willingness to open new bins).
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Penalize opening bins early; accept more readily when open bins are cluttered.
        score += 25.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 10.0; // open bins are nearly full, new bin is fine
        }
    }

    // Mild preference for fuller bins among open ones (reduce bin count pressure).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * fill;

    // Slight penalty when many bins are open, encouraging consolidation.
    score += 0.05 * open_bins_count as f64;

    // Time-horizon modulation: early in the stream, be pickier about tight fits.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= (1.0 - progress) * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement, scaled non-linearly
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, tight fits matter more -> penalize large residuals more
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_term * pr * 1.5;

    // Reward near-perfect fits with smooth decay
    let fit_quality = 1.0 - (pr / cap);
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // post residual too small for next item: penalize proportionally
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidating emptier bins)
    score += 0.3 * (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small item friendly" classes (multiples of common item sizes) are valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Penalize dead space quadratically, but reward residuals that are
    // exactly usable by the next item (perfect lookahead fit).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit: post_residual becomes dead space
            score += 10.0 + 0.5 * pr as f64;
        }
    }

    // Modulo-harmonic reward: residuals divisible by 10 or 25 pair well
    // with typical item sizes.
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.0; }
    }

    // Integer-division thresholds: classify residual into coarse bands.
    let band = pr / 20; // 0..=5
    score -= match band {
        0 => 2.0,           // nearly full bin: great closure
        1 => 1.0,
        2 => 0.0,
        3 => -0.5,          // mid residual: mildly attractive
        _ => 1.5,           // large residual: wasteful unless needed
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well or
    // stream is early and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 25.0 - 10.0 * progress - 2.0 * crowded.min(10.0);
        if next_item_size > 0 && next_item_size <= pr {
            score -= 5.0; // fresh bin fits next item too
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * ((mean_residual - bin_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: many open bins -> favor filling existing ones,
    // penalize opening new bins.
    score += open_bins_count as f64 * 3.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New-bin candidate: only attractive if no good option exists.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0; // exact fit for next item
        } else if post_residual < next_item_size {
            // Dead space: next item cannot use this bin's remainder.
            score += 25.0 + diff * 0.8;
        } else {
            // Next item fits but leaves further slack: mild penalty scaled by gap.
            score += diff * 0.35;
        }
    }

    // Prefer bins whose residual is already below the mean (tight bins absorb items well).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize leaving very small unusable slivers (dead space nothing can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.10 * next_item_size as f64;
        // Extra reward for a tight two-item fit
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 / (1.0 + slack)).min(8.0);
    } else if next_item_size > 0 {
        // Penalize creating dead space that blocks the next item
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasteful large post-residuals, more so early when consolidation matters
    let waste = post_residual as f64;
    score += 0.20 * waste * (1.0 - 0.5 * progress);

    // Reward packing into bins with small residuals (tighten existing bins)
    score += 0.10 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere (large residual elsewhere) or many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        score = poor_fit + 10.0 - 30.0 * pressure - 15.0 * crowding * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: tolerate moderate residuals to keep bins flexible.
    // Late stream: penalize wasted residual quadratically to force tight packing.
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let tightness = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += tightness * cap * 0.8;

    // Reward near-perfect fits with a smooth non-linear bonus.
    let fit_quality = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 25.0 * fit_quality * fit_quality * (1.0 + progress);

    // Last-chance bin: strong smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64 / cap;
        score -= 15.0 * nxt * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize leaving a residual close to next item size.
        let gap = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score += 8.0 * gap * gap;
    }

    // Prefer bins below mean residual (tighter bins) with smooth coupling.
    let mean_dev = (pr - mean_residual) / cap;
    score += 10.0 * mean_dev * mean_dev - 5.0 * mean_dev;

    // Discard-fraction term: penalize residuals that are unusable for typical items.
    score += 6.0 * norm_pr * norm_pr * norm_pr;

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division thresholds.
    // Class 0: post_residual < 10  -> near-perfect fill, strong reward.
    // Class 1: 10..=20             -> usable for smallest items, mild reward.
    // Class 2: 21..=35             -> moderate dead space.
    // Class 3: >35                 -> large dead space, penalize.
    let class = if post_residual < 10 { 0u32 }
        else if post_residual <= 20 { 1 }
        else if post_residual <= 35 { 2 }
        else { 3 };

    score -= match class { 0 => 30.0, 1 => 12.0, 2 => 0.0, _ => 0.0 };

    // Penalize dead space quadratically beyond the class-2 threshold.
    if pr > 35.0 {
        score += 0.02 * (pr - 35.0) * (pr - 35.0);
    }

    // Harmonic compatibility: does next_item_size fit exactly into post_residual?
    // Perfect lookahead fit -> big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if the lookahead leaves another small residual (chain fit).
        let next_post = post_residual - next_item_size;
        if next_post < 10 {
            score -= 14.0;
        } else if next_post <= 20 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot use this residual: penalize proportionally to how
        // much of the residual would be wasted (harmonic modulo term).
        let m = post_residual % next_item_size.max(1);
        score += 0.15 * m as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when this item is large and no tight
    // fit is available elsewhere; otherwise penalize opening fresh bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 {
            score -= 5.0 + 8.0 * progress;
        } else {
            score += 20.0;
        }
    }

    // Mild preference for filling bins that are already relatively empty
    // (keeps tight bins free for small items), scaled by mean residual.
    let frac = bin_residual as f64 / cap;
    score += 4.0 * (frac - mean_residual / cap).max(0.0);

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    }
    // Medium gaps are mildly penalized (hard for future mid-size items).
    if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: reward leaving a gap that fits the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack * 0.15);
        } else {
            // Gap too small for next item: dead space.
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 200.0
            - (if fitting_bins_count == 0 { 250.0 } else { 0.0 })
            - (open_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that cannot fit the next item (2-step lookahead)
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            } else {
                // Reward residuals that can accommodate the next item
                score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(50.0);
            }
        }
        // Penalize small unusable residuals relative to item domain (min item ~1..10)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no tight fit exists
        let waste = post_residual as f64; // = capacity - item_size
        score += 60.0;
        if waste < 5.0 {
            score -= 80.0; // near-full new bin is fine
        }
    }

    // Early in stream, be slightly more conservative about fragmenting bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that no plausible item can use
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 15.0;
    }

    // Tight-fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // bonus if post_residual + next item leaves near-perfect packing
        let two_left = post_residual as i64 - next_item_size as i64;
        if two_left == 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let mean_r = mean_residual;
        // open new bin only when existing residuals are large/fragmented
        score += 30.0 - 0.5 * mean_r - 2.0 * crowd * (1.0 - progress);
        if mean_r > item_size as f64 {
            score += 10.0; // existing bins clearly have room; discourage new bin
        }
    } else {
        // prefer bins with residual close to item (best-fit flavor)
        score += 0.3 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Prefer bins whose residual is below the mean (compact bins first)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild preference for lower post_residual as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins tightly (minimize post). Late: tolerate larger residuals
    // since consolidation matters less; scale reward down with progress.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    let coupling = tightness * (1.0 + 0.9 * prog2 + 0.6 * prog3) * 8.0;
    score -= coupling;

    // Reward near-exact fits with a smooth quadratic term.
    let exact = (post / cap) * (post / cap);
    score -= (1.0 - exact) * 6.0;

    // Penalize residuals that are too small to be useful later (dead space),
    // smoothly: small-but-nonzero residuals are the worst.
    let dead = 1.0 - (post / 10.0).min(1.0);
    score += dead * dead * 5.0 * (1.0 - prog2);

    // Lookahead: bonus if the next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = ((post - nxt).abs()) / cap;
        if nxt <= post {
            score -= (1.0 - fits * 4.0).max(0.0) * 4.0 * (1.0 - progress);
        } else {
            score += (nxt - post) / cap * 3.0;
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 7.0 * (1.0 - prog3 * 0.3);
    }

    // Slight penalty when many bins are open (encourage consolidation),
    // smoothly modulated by mean residual closeness to this bin's residual.
    let res_gap = (post - mean_residual).abs() / cap;
    score += (open_bins_count as f64).ln() * 0.4 + res_gap * 2.0;

    // New-bin candidate: keep it neutral-ish but slightly discouraged unless
    // no open bin fits well (handled by last-chance / coupling terms).
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Harmonic classes: classify post_residual into residue classes modulo 10
    // (typical item size quantum). Residues that are "dead" (small, unusable)
    // are penalized more than multiples of 10 which future items can fill.
    let pr = post_residual as u32;
    let class = pr % 10;
    let dead_penalty = match class {
        0 => 0.0,                    // perfectly reusable slot
        1 | 2 | 3 => 18.0,           // near-dead slivers
        4 | 5 | 6 => 9.0,            // marginal
        _ => 4.0,                    // moderately reusable
    };
    // Scale dead-space penalty down when bin is nearly full anyway.
    let fill_frac = 1.0 - (pr as f64) / (bin_capacity as f64);
    score += dead_penalty * fill_frac;

    // Harmonic fraction thresholds on post_residual relative to capacity.
    let pr_frac = pr as f64 / bin_capacity as f64;
    if pr_frac < 0.05 {
        score += 6.0; // essentially closed bin, fine — but tiny residue is waste
    } else if pr_frac < 0.1 {
        score += 3.0;
    } else if pr_frac >= 0.5 {
        score -= 4.0; // half-empty bins remain flexible
    }

    // Lookahead: if the next item fits exactly in the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // reward proportional to how well next item uses the leftover
            let usage = next_item_size as f64 / pr as f64;
            score -= 15.0 * usage;
            // harmonic match: next item leaves a multiple-of-10 residue
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residue: penalize large leftover less
            // if residue is in a "friendly" class, more if sliver.
            if class != 0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if pr_frac >= 0.2 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: the empty bin has post_residual == capacity - item.
    // Make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit, below a bad fit.
        score += 12.0;
        // Early in the stream or many open bins with big mean residual:
        // prefer reusing open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // If next item is large and this bin would be fresh, slight bonus.
        if next_item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Congestion control: many open bins → favor consolidating into existing ones.
    if open_bins_count > 4 {
        if bin_residual != bin_capacity {
            score -= 3.0;
        } else {
            score += 6.0 * ((open_bins_count as f64) / 10.0).min(2.0);
        }
    }

    // Mean residual coupling: when open bins are on average roomy, tighten selection
    // (weight post_residual more); when bins are tight, be lenient.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score *= 0.7 + 0.6 * tightness;

    // Small integer-division threshold: exact halving fits are classically good.
    if item_size * 2 == bin_residual {
        score -= 8.0;
    }
    if bin_residual % item_size == 0 && item_size > 0 && bin_residual / item_size >= 2 {
        score -= 4.0; // divisible residual → future identical items tile perfectly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are impossible, but tiny gaps relative to typical items are near-wasted.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 1000.0;
    } else if pr < 5.0 {
        // Unusable dead space: severe penalty.
        score += 500.0;
    } else if pr < 20.0 {
        // Tight gap: quadratic dead-space penalty scaled by gap smallness.
        score += (20.0 - pr) * (20.0 - pr) * 0.5;
    } else {
        // Usable residual: mild reward proportional to tightness.
        score -= pr * 0.15;
    }

    // Reward tightness relative to bin capacity (fill ratio of this placement).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score += pressure;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is justified when item fits poorly everywhere else
        // or when open bins are already numerous/fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 25.0 + fragmentation * 60.0;
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    }

    // Lookahead (k=2): favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 {
            // This placement strands space the next item cannot use.
            score += (next_item_size as f64 - pr).min(30.0) * 0.6;
        }
    }

    // Mild preference for bins whose residual is close to item size (best-fit core).
    score += ((bin_residual - item_size) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward exact two-item fills (post_residual == next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            // next item fits too: reward proportional to how snugly it fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 * (waste / bin_capacity as f64);
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins below mean residual (tighter) are preferred targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin gives a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins early in the stream / when many bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 5.0 * (open_bins_count as f64).sqrt();
        }
        // But if next item is large and this item leaves nothing usable, new bin is fine
        if next_item_size > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // If this bin is the last chance option is false (new bin can't be last chance), keep penalty.
    }

    // Mild penalty for leaving tiny unusable slivers (1..10) unless next item matches
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;

    // Perfect fit: strongly reward zeroing out the bin.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the leftover space still host the next item?
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 3.0; // residual remains useful
        } else {
            // dead-space penalty scaled by how much of next item cannot fit
            score += (nxt - post_residual as f64) * 0.6;
        }
    }

    // Tightness: prefer bins where the item fills a large fraction of residual.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 6.0;

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Consolidation pressure: using existing bins is good when few are open.
    score -= (open_bins_count.min(12) as f64) * 0.25;

    // Time horizon: late in the stream, waste matters more (fewer future items to fill gaps).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 4.0 * (post_residual as f64 / cap);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 18.0; // default: prefer existing bins
        if item_size >= 60 {
            score -= 12.0; // large items are hard to place later; fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if mean_residual < it {
            score -= 8.0; // open bins are nearly full; fresh capacity is valuable
        }
        if next_item_size > 0 && next_item_size as f64 + it > cap {
            score -= 5.0; // next item can't share with current one anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let norm_r = r / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = r;
    score += 30.0 * norm_r * norm_r * (1.0 - progress);
    score -= 20.0 * norm_r * progress;

    // Reward tight fits smoothly (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: prefer leaving room for the next item
    if next_item_size > 0 {
        let gap = r - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Slight preference for filling existing bins when many are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_r;

    // Mean residual drift: avoid bins far from the mean residual
    let drift = (r - mean_residual).abs() / cap;
    score += 10.0 * drift * drift;

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 180.0 * tight * tight;

    // Penalize "dead" residuals that are too small for the smallest plausible item (<=10).
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Harmonic class logic on post_residual via capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Quarter classes: which quarter of the bin does the residual fall into?
    let quarter = (pr / (cap / 4.0)).floor() as i32; // 0..=4
    score -= match quarter {
        0 => 40.0,                       // residual < 25%: nearly full, great
        1 => 20.0,                       // 25-50%
        2 => 0.0,                        // 50-75%
        3 => -12.0,                      // 75-100%: roomy, mild penalty
        _ => -20.0,                      // empty-ish bin
    };

    // Integer division threshold: residual divisible by common item sizes is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0) {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / cap);
        // Perfect chain fit
        if post_residual == next_item_size {
            score -= 45.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize proportionally to leftover waste.
        score += 0.25 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin; scaled by how many bins are already open.
        score += 55.0 + 3.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening is necessary: cancel penalty.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
        // If the item would leave a well-structured residual (harmonic class), opening is more attractive.
        let new_post = bin_capacity - item_size;
        if new_post % 10 == 0 || new_post % 20 == 0 || new_post % 25 == 0 {
            score -= 18.0;
        }
        // If next item would fit perfectly into the fresh bin's post residual, encourage opening.
        if next_item_size > 0 && new_post >= next_item_size && (new_post - next_item_size) < 10 {
            score -= 25.0;
        }
    }

    // Mild stream-progression effect: later in stream, be slightly more conservative about waste.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (pr / cap);
    }

    // Prefer filling bins that are already below the mean residual (balancing).
    score -= 0.15 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
    }

    // Mean residual alignment: prefer bins near the mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight progression bias: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
