pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential.
        score += 0.05 * (next_item_size as f64).min(post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating small dead space that few items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item or many bins are open.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when open bins are fragmented (high mean residual, many bins).
        score += 15.0 + 10.0 * avg_pressure + 0.3 * open_bins_count as f64 - 10.0 * progress;
        // If no open bin fits at all, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Mildly favor reusing bins as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Coupling: prefer bins whose residual is far from the mean (consolidation).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted space (dead space grows quadratically worse).
    let mut score = post * post / cap;

    // Smooth interaction: waste tolerance shrinks as stream progresses.
    // Early stream: tolerate residual; late stream: punish it harder.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * post;

    // Reward tight fits: item filling most of the bin gets a strong subtraction.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Interaction between fill and post-residual: a full bin with small remainder is best.
    score -= 10.0 * fill * (1.0 - post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, scaled by how many.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - nxt / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Context: penalize bins deviating from mean residual (keep residuals homogeneous),
    // smoothly weighted by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild bonus for using open bins vs opening new ones (new bin has residual == cap).
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division thresholds.
    // Classes: [0..=5] perfect fit, (5..15] great, (15..30] ok, (30..50] poor, >50 dead space.
    let class = match post_residual {
        0..=5 => 0.0,
        6..=15 => 1.0,
        16..=30 => 2.0,
        31..=50 => 3.0,
        _ => 4.0,
    };
    score += class * 12.0;

    // Perfect-fit bonus (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo arithmetic: residuals congruent to small multiples of common item
    // sizes (10/20/25/50) are reusable; odd residues are dead space.
    let r = post_residual;
    if r % 10 == 0 { score -= 10.0; }
    if r % 25 == 0 { score -= 8.0; }
    if r % 20 == 0 { score -= 6.0; }
    if r > 0 && r < 10 && r % 2 == 1 { score += 15.0; } // odd tiny residue = waste

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            // Harmonic class of leftover after the lookahead placement.
            let post2 = post_residual - next_item_size;
            score -= 10.0 - (post2 as f64 / 8.0).min(10.0);
        } else {
            // Next item won't fit here: penalize by how much it overshoots,
            // scaled by whether this is a last-chance bin.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.6;
            if fitting_bins_count == 1 {
                score += 20.0; // don't burn the only fitting bin on a bad chain
            }
        }
    }

    // Last-chance bin logic: strongly favor using the sole fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
        // Unless the fit is terrible AND a fresh bin would be better.
        if post_residual > 55 {
            score += 25.0;
        }
    }

    // New-bin candidate: an empty bin has huge residual; make it lose unless
    // every open-bin fit would create large dead space. We give the empty bin
    // a moderate baseline that beats poor fits (class 3/4) but loses to any
    // decent fit (class 0/1/2).
    if bin_residual == bin_capacity {
        score = 45.0
            - if next_item_size > 0 && next_item_size <= bin_capacity {
                // if next item is large, having a fresh bin is valuable
                (next_item_size as f64 / 100.0) * 20.0
            } else {
                0.0
            }
            + open_bins_count as f64 * 0.5;
        // Late in the stream, closing out with fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild pressure against hoarding many open bins with large mean residual.
    if mean_residual > 50.0 && open_bins_count > 3 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: eliminate the bin, strongly favored.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (small usable gap left behind) are desirable.
    if post_residual > 0 && post_residual < 10 {
        score -= 18.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Dead-space penalty: large post_residual means most of the bin was wasted
    // on this item; the bigger the leftover, the worse the placement.
    if post_residual > 60 {
        score += 25.0;
    } else if post_residual > 40 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only open bin that fits the item,
    // strongly prefer using it rather than fragmenting capacity elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin, with pressure that grows
    // with the number of already-open bins (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
        // But if no open bin leaves a reasonable gap, allow the new bin:
        // large post_residual on existing bins already penalized above.
        if post_residual < 25 {
            score -= 20.0;
        }
    }

    // Lookahead coupling (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 5.0; // gap too small for the known next item: mild dead space
        }
    }

    // Global pressure: bins with large residuals relative to the fleet mean
    // should absorb items to keep residual distribution tight.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream urgency: as the stream ends, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next item size (perfect two-item packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-item closure
        } else if next < post {
            // next item fits after placement: reward proportional fill
            score -= 25.0 * (next / post) - 0.15 * diff;
        } else {
            // next item won't fit: penalize leftover dead space
            score += 0.35 * diff;
        }
    } else {
        // last item: minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Prefer tight fits relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin when the item would leave a large
    // residual elsewhere; new bin only attractive for large items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 0.2 * item_size as f64 + 10.0 * progress;
    }

    // Mild penalty for creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.5 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: bonus if the next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 20.0 * next_fit;
        } else {
            // Next item cannot follow here; slight penalty for wasting a good bin.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }
    // Many fitting bins: mildly prefer spreading load (avoid over-concentrating).
    else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state: if mean residual is low, preserve bins with large residuals.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap;

    // Time horizon: early in stream, encourage opening bins for flexibility;
    // late in stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);
    score -= progress * 10.0 * tightness;

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 * (1.0 - large_item);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) - pr_norm * progress;
    score += 30.0 * poly;

    // Tight fits are good, especially late in the stream.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.05 * slack;
        } else {
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize so we prefer reusing bins, more so early.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (large enough to host a typical next item) are rewarded.
    let post = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post_residual is an exact "harmonic divisor" of capacity
    // (100, 50, 25, 20, 10) -> perfectly reusable residual.
    let harmonic_divisors: [u32; 5] = [100, 50, 25, 20, 10];
    if harmonic_divisors.contains(&post) {
        score -= 6.0;
    }

    // Class B: modulo arithmetic on post_residual — residues near 0 mod 10
    // are "round" leftovers that pair well with decadal item sizes.
    let r10 = post % 10;
    score -= (5 - (r10 as f64 - 5.0).abs()) * 0.4; // reward r10 near 0 or 10

    // Dead-space penalty: tiny unusable leftovers (post_residual < 10,
    // minimum item size) are pure waste.
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Coupling with lookahead: does post_residual fit next_item_size exactly?
    if next_item_size > 0 {
        if next_item_size <= post {
            let gap = post - next_item_size;
            // exact fit for next item is excellent
            score -= 8.0 - gap as f64 * 0.15;
            if gap == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot follow in this bin: penalize proportionally
            let overflow = (next_item_size - post) as f64;
            score += overflow * 0.05;
        }
        // Harmonic class of next_item_size relative to capacity thirds/halves
        let n = next_item_size as f64;
        if (n - cap * 0.5).abs() < 1.0 || (n - cap / 3.0).abs() < 1.0 {
            score -= 2.0;
        }
    }

    // Integer-division thresholds on post_residual: quartile classes.
    let q = post / 25; // 0..4 quartile class
    match q {
        0 => score += 4.0,          // nearly full bin: good if fit, but risk
        1 => score -= 1.0,          // 25-49 leftover: decent
        2 => score -= 2.0,          // 50-74 leftover: very reusable
        _ => score -= 0.5,          // mostly empty bin: weak commitment
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer filling bins that deviate below the mean residual (tighter bins).
    score += (mean_residual - post as f64) * 0.03;

    // New-bin candidate handling: empty bin is a fallback; make it mildly
    // unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.2;
    } else if post == 0 {
        // perfect closure of a bin
        score -= 20.0;
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space harshly (strict dead-space avoidance).
        if post_residual < 10 {
            score += (10.0 - post_residual as f64) * 12.0;
        } else if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 3.0;
        }

        // Reward residuals that can still host a typical future item.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure proportional to number of open bins: consolidate when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Opening a brand-new bin should be penalized unless it yields a great future profile.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 1.5;
        // Slight relief late in the stream when consolidation matters less.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild tie-break: prefer bins whose residual is far from the mean (more "specialized").
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain completion: two items perfectly fill the bin
        } else if next_item_size <= post_residual {
            // next item fits too: penalize proportional to leftover dead space after both
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.8;
            score -= 40.0; // mild bonus for keeping bin useful
        } else {
            // next item cannot use the leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.6;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidate unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // allow opening a new bin early in the stream or when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0 + (open_bins_count as f64 * 2.0).min(60.0);
        // if next item is large, a fresh bin may be valuable
        if next_item_size >= 60 {
            score -= 80.0;
        }
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly as the stream matures.
    let tight_bonus = 12.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(3);
    score -= tight_bonus;

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }
    // Penalize leaving a gap that almost-but-not-quite fits the next item (dead space).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        let gap_waste = post_residual as f64 / next_item_size as f64;
        score += 4.0 * gap_waste * (1.0 - gap_waste);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 8.0 * progress;
    }

    // Penalize placements that fragment bins relative to the global mean residual.
    let frag = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * frag;

    // New-bin candidate logic: attractive early or when existing bins fit poorly.
    if is_new_bin {
        let mut nb = 30.0; // base reluctance to open a new bin
        nb -= 25.0 * (1.0 - progress); // cheaper to open early in the stream
        nb += 2.0 * open_bins_count as f64 * (1.0 - progress); // many open bins -> discourage
        // If this is the only fitting option, opening a new bin is necessary and cheap.
        if fitting_bins_count == 0 {
            nb -= 40.0;
        } else if fitting_bins_count == 1 {
            // Compete with the last-chance bin only if its post-residual is very wasteful.
            if post_residual == bin_capacity {
                nb -= 3.0;
            }
        }
        // Lookahead bonus: a fresh bin can host both current and next items.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            nb -= 5.0;
        }
        score = nb + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, non-linearly (quadratic coupling)
    let mut score = post + 0.0045 * post * post;

    // Reward tight fits relative to capacity (smooth normalized term)
    let fill_ratio = item_size as f64 / cap;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates from the mean residual landscape
    score += 0.08 * (post - mean_residual).abs();

    // Last chance: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
        score -= 10.0 * progress;
    }

    // Lookahead: penalize if post residual can't fit next item (dead space risk)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 + 0.10 * (nxt - post);
        } else {
            // smooth reward proportional to how well post residual matches next item
            let slack = post - nxt;
            score -= 4.0 * (1.0 - slack / cap).max(0.0);
        }
    } else {
        // Last item in stream: minimize waste aggressively
        score += 0.01 * post * post;
    }

    // Stream-progress coupling: early on, slightly favor opening bins with big residual;
    // later, consolidate into existing bins (penalize new-bin tendency smoothly)
    score += 8.0 * progress * (post / cap);

    // Many open bins: discourage spreading, favor tightest fit
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Class leftover into harmonic bands: exact-fit (0), tiny (1..=5),
    // small (6..=15), medium (16..=35), large (36..=60), huge (>60).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit: strongly favored
    } else if pr <= 5 {
        -25.0
    } else if pr <= 15 {
        -10.0
    } else if pr <= 35 {
        5.0
    } else if pr <= 60 {
        15.0
    } else {
        25.0
    };
    score += class_bonus;

    // --- Modulo arithmetic on residual: residues that pair well with common item sizes ---
    // Items 1..100; a leftover that is a multiple of 10 or matches next_item_size exactly
    // is more reusable.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // next item fits exactly
        } else if next_item_size < pr {
            // residue mod next item: small remainder means good future fit
            let r = pr % next_item_size.max(1);
            score -= (next_item_size - r) as f64 * 0.3;
        } else {
            score += 8.0; // next item cannot fit here anyway
        }
        // harmonic pairing: leftover + next item divisible by 10 => clean future state
        if (pr + next_item_size) % 10 == 0 && next_item_size <= pr {
            score -= 6.0;
        }
    }

    // --- Integer division thresholds on item_size (harmonic size classes) ---
    let size_class = item_size / 20; // 0: tiny, 1: small, 2: mid, 3: large, 4: huge
    match size_class {
        0 => score -= 5.0,   // tiny items: keep them out of fresh bins
        1 => score -= 2.0,
        2 => score += 0.0,
        3 => score += 3.0,   // large items prefer roomy bins
        _ => score += 6.0,
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0; // avoid opening a new bin if this is the only fit
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: competitive only when open bins are fragmented or item is huge
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 12.0 + fragmentation * 0.2 - progress * 8.0
            - (if item_size > 70 { 10.0 } else { 0.0 });
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // --- Waste relative to mean residual: penalize bins far above average fill ---
    score += (mean_residual - bin_residual as f64) * 0.15;

    // --- Mild penalty for leaving residue in awkward mod-10 classes (dead space) ---
    if pr > 0 && pr < 10 {
        score += 4.0; // sub-10 slivers are hard to fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residuals that nothing can ever fit into (min item is 1) are fine at 0,
    // but small nonzero gaps are the worst outcome.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // unless the fit is excellent.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or fit is loose.
        score += 30.0 + 10.0 * open_pressure;
        if post_residual > 50 {
            score += 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    } else {
        // Mild bonus for filling existing bins when pressure is high.
        score -= 3.0 * open_pressure * tightness;
    }

    // Lookahead: if next item fits perfectly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: dead space risk.
        score += 8.0 * (post_residual as f64 / 100.0);
    }

    // Early in the stream, be slightly more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && item_size >= 50 && progress < 0.3 {
        score -= 15.0;
    }

    // Penalize residuals far from mean (fragmentation indicator) when not a new bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // next item fits exactly -> chain reward
            if diff == 0.0 {
                score -= 150.0;
            } else {
                score -= (60.0 * (1.0 - diff / 100.0)).max(0.0);
            }
        } else {
            // next item cannot use the leftover space -> penalize dead space
            score += 0.5 * (nxt - post);
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 100.0;
    }

    // Relative residual vs mean: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when plenty of space exists elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline high, reduced only when current bins are tight
        score += 30.0;
        score += 0.4 * mean_residual;
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Small bonus for filling more of the bin (fractional fill reward)
    score -= 0.2 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Reward high fill ratio non-linearly.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 120.0 * fill * fill;

    // Penalize dead space that is too small for typical future items
    // (dead space below the minimum plausible item size is wasted).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 50.0;
        }
        // Penalize if placing here wastes space the next item could use.
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0;
        }
    } else {
        // Last item in the stream: any leftover space is pure waste.
        score += 30.0;
    }

    // Global state: prefer tighter bins when many bins are open
    // (consolidation pressure), less so early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0);
    score += 50.0 * (1.0 - progress) * tightness;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Prefer bins whose residual is small relative to capacity (best-fit core).
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space quadratically (dead space grows super-linearly in cost)
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, leftover space matters less; late, we want bins packed very tight.
    let progress_coupling = 1.0 + 2.5 * progress * progress + 1.5 * progress * (1.0 - progress);
    score *= progress_coupling;

    // Interaction: post_residual relative to mean residual — prefer bins tighter than average
    let mean_norm = mean_residual / cap;
    score += 4.0 * (post / cap - mean_norm) * (0.5 + progress);

    // Perfect fit reward (smooth via exponential decay of post_residual)
    score -= 12.0 * (-post / 8.0).exp();

    // Last-chance bin: strongly reward using it (avoids opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 10.0).exp();
    }

    // New-bin candidate: neutral baseline, slightly worse late in the stream
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 1.5 * progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity-fraction buckets (0, (0,25], (25,50], (50,75], (75,100)).
    let cap = bin_capacity as f64;
    let q = |x: u32| (x as f64 / (cap / 4.0)) as i32; // integer division threshold class
    let post_class = q(post_residual);
    let pre_class = q(bin_residual);

    // Reward residual classes that are "harmonically useful": residuals that are
    // exact fractions of capacity (0, 25, 50, 75) are reusable by typical items.
    let harmonic = |x: u32| {
        let x = x % (bin_capacity + 1);
        (x == 0 || x == 25 || x == 50 || x == 75) as f64
    };
    score -= 18.0 * harmonic(post_residual);

    // Dead-space penalty grows super-linearly in the awkward middle class (1..=2 quarters)
    if post_class == 1 || post_class == 2 {
        score += 12.0 * (1.0 - (post_residual as f64 / cap));
    }

    // Perfect fit: zero post residual is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact harmonic match of next item to post residual is a double reward
        let nx_class = q(next_item_size);
        score -= 10.0 + 4.0 * nx_class as f64;
        if post_residual - next_item_size == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportional to wasted potential
        score += 6.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins whose residual is below the mean (tightening crowded bins)
    score += 0.05 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to spread items (penalize near-empty bins less later)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pre_class == 4 && progress < 0.3 {
        score += 5.0; // discourage opening many bins early
    }

    // Small tie-breaker toward bins with larger pre-fit residual usage
    score += 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it cannot fit even the smallest plausible item (<= 10)
    // or cannot fit the lookahead item that will likely follow.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0; // tiny unusable sliver -> heavy penalty
    }

    // If the next item cannot fit into the post residual, this bin will
    // likely be stranded; penalize proportionally to the shortfall.
    if next_item_size > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also absorb the lookahead item (chaining).
        score -= 8.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 10.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (packing is cheap to consolidate); encourage opening when many bins
    // are open and this bin would leave a bad gap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few open bins / early stream.
        score += 15.0 + 10.0 * (1.0 - progress) + 0.5 * (open_bins_count as f64);
    } else {
        score -= 3.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // filling below-average-residual bins keeps large gaps available.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += 0.05 * dev; // below-mean residual slightly penalized
        } else {
            score -= 0.05 * dev; // above-mean residual (large gap) preferred to fill
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Near match: next item fits with small waste.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tighter slack, decaying with slack size.
        score -= (25.0 * (-slack / 20.0).exp()).max(0.0);
        // Penalize large leftover slack that is unlikely to be reused.
        if slack > 40.0 {
            score += (slack - 40.0) * 0.3;
        }
    }
    // Dead space: next item cannot fit in the post residual.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Penalize creating tiny unusable residuals relative to the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below the mean residual (tighter bins first, best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Late in the stream, be more conservative: avoid leaving scattered residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // Slight penalty for opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let alt_penalty = if fitting_bins_count > 0 { 12.0 } else { -5.0 };
        score += alt_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below a
    // plausible minimum item size is nearly unusable — penalize it extra.
    if post_residual > 0 {
        let dead_weight = if post_residual < 10 { 40.0 } else if post_residual < 20 { 12.0 } else { 0.0 };
        score += dead_weight;
    } else {
        // Perfect fill — strong reward.
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly; if next item can't fit here at all,
    // leaving a large post_residual is wasteful unless it's near-capacity.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 60.0; // perfect chain
        } else if next_item_size as u32 <= post_residual {
            score -= 15.0; // chainable
        } else {
            // next item won't fit here; prefer compact leftovers
            score += post_residual as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (keep residuals
    // flexible); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Global pressure: many open bins with low mean residual => prefer
    // filling existing bins rather than fragmenting further.
    if open_bins_count > 2 && mean_residual < 30.0 {
        score -= 8.0;
    }
    // A bin far below mean residual is a good "garbage collector" target.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 6.0;
    }

    // New-bin candidate guard: opening a new bin should only win when the
    // item is huge relative to capacity and nothing fits well.
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count > 0
            && (bin_residual - item_size) > 40
            && item_size < 60;
        if tight_elsewhere {
            score += 120.0; // discourage new bin when decent fits exist
        } else {
            score += 25.0; // mild default penalty for new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Tight-fit reward: smooth quadratic in post_residual, scaled by item size.
    let tightness = (1.0 - post / cap).powi(2);
    score -= 30.0 * tightness * (item / cap);

    // Penalize large dead space with a cubic term, stronger later in the stream.
    let waste = (post / cap).powi(3);
    score += 60.0 * waste * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next > 0.0 && post > 0.0 {
        let gap = (post - next).abs();
        let fits_next = if post >= next { 1.0 } else { 0.5 };
        score -= 15.0 * fits_next * (1.0 - gap / cap).powi(2);
    }

    // Last-chance bonus: strongly favor this bin when it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize mildly, more when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * (1.0 - (mean_residual / cap).min(1.0));
    } else {
        // Prefer bins with below-average residual (keep big holes for big items).
        score += 8.0 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);
    }

    // Smooth progress coupling: as stream progresses, weight tightness more.
    score *= 1.0 - 0.2 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead zone" classes.
    let residue = post_residual % 10;
    // Penalize small nonzero residues (unusable slivers), reward exact zero residue.
    if post_residual == 0 {
        score -= 45.0; // perfect closure
    } else {
        let deadness = match residue {
            1..=4 => 14.0 - (residue as f64) * 2.0,
            5..=9 => 3.0 + (9 - residue as f64) * 1.2,
            _ => 0.0,
        };
        score += deadness;
    }

    // Capacity fraction classes: how full the bin becomes (integer division on capacity).
    let fill_class = (item_size * 4) / bin_capacity; // 0..3 quarters
    score -= fill_class as f64 * 6.0; // reward high fill fraction

    // Lookahead harmony: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nres = post_residual - next_item_size;
            score -= 8.0 + (nres % 10) as f64 * 0.4;
        } else {
            // next item cannot use this bin's remainder: penalize leftover size
            score += (next_item_size.min(post_residual.wrapping_sub(next_item_size).wrapping_mul(0).max(0)) as f64) * 0.0;
            score += (post_residual as f64) * 0.15; // leftover likely dead for next item
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 25.0;
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very empty
    // or stream is early and we need parallel capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (open_bins_count as f64) * 3.0;
        score += 40.0 - scarcity - progress * 10.0;
        // A new bin is fine if the item is huge (harmonic class 3/4+)
        if fill_class >= 3 { score -= 20.0; }
    } else {
        // Favor tighter existing bins: compare residual to mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.25;
    }

    // Mild entropy: reward bins whose residual is in harmonic multiples of item class
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (min size 1, but practically < ~15) are dead space.
    let dead_threshold = 14.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0; // heavy penalty for near-dead gaps
    }

    // Reward tight fits: the closer post_residual is to 0 without being dead, the better.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward bins whose residual closely matches the item (best-fit flavor)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when pressure is low,
    // but allow it when open bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        score += 20.0 + pressure * 3.0;
        // If next item could combine with current item in a fresh bin, slight bonus
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones harder
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post_residual cannot serve next item; mild penalty scaled by gap
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when post_residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(0.0);
        // Strong reward for exact match
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    score -= 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it and avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    // Mild preference for tight fits early vs late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post residual.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.15;

    // Penalize dead space that is too small for the smallest item (1..100 range):
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills
            let leftover_after_next = post_residual - next_item_size;
            score -= 12.0 - (leftover_after_next as f64) * 0.1;
        } else {
            // next item does not fit: penalize more if we created a large unusable gap
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += (next_item_size as f64 - gap) * 0.08;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, allow opening new bins slightly more readily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 10.0 * progress;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus dynamic adjustment.
        score = bin_capacity as f64 - new_bin_bonus;
        // Avoid opening new bins when plenty of residual capacity exists in open bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If no open bin fits at all, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Prefer bins whose residual is below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
        // Many open bins: encourage filling existing ones.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Exact fill perfection reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Non-linear penalty for awkward residuals (dead space), smoothly modulated by progress.
    let awkward = (pr_norm * (1.0 - pr_norm)).powi(2); // peaks mid-range
    score += 30.0 * awkward * (0.5 + progress);

    // Tight fits are good: subtract for small post-residual, stronger late in stream.
    score -= 25.0 * (-pr / 20.0).exp() * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Many open bins: discourage spreading; few open bins: encourage filling.
    let spread = (open_bins_count as f64).ln_1p();
    score += 4.0 * spread * pr_norm;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - pr / (pr + next_item_size as f64));
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a large unusable gap.
        score += 8.0 * pr_norm * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (eighths). Residuals in "nice" classes
    // (small multiples of common item sizes) are more reusable.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor(); // 0..8
    score -= class * 2.5; // reward bins whose leftover falls in a higher class (larger leftover = more flexible)

    // Dead-space penalty: leftover that is neither ~0 nor large enough to be useful.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny useless sliver
        } else {
            // modulo arithmetic: leftover divisible by common item sizes is valuable
            let mut div_bonus = 0.0;
            for d in [10u32, 20, 25, 40, 50] {
                if post_residual % d == 0 {
                    div_bonus += 12.0;
                }
            }
            score -= div_bonus;
            // leftover just below a common size is a trap (e.g. 39 can't take 40)
            for d in [11u32, 21, 26, 41, 51] {
                if post_residual % d == 0 && post_residual < 60 {
                    score += 15.0;
                }
            }
        }
    } else {
        score -= 80.0; // perfect closure, strongly favored
    }

    // Integer-division threshold on next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 - tight * 0.3;
            if post_residual % next_item_size == 0 {
                score -= 20.0; // exact harmonic match
            }
        } else {
            // next item won't fit here: penalize mildly, more if residual becomes stranded
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // current bin would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual > 0 && post_residual < 10;
        if progress < 0.15 || bad_fit {
            score -= 25.0;
        } else {
            score += 30.0; // prefer reusing open bins mid/late stream
        }
    }

    // Coupling with mean residual: bins far below mean waste capacity; prefer
    // placing into bins whose residual is close to the item (tight fit reward).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;
    let dev = (mean_residual - bin_residual as f64).abs();
    score += dev * 0.15;

    // Many open bins: encourage consolidation into emptier bins.
    if open_bins_count > 4 {
        score -= (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A leftover gap is "dead" if no plausible future item (1..=100) can use it well.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual as f64);
    }

    // Medium gaps that can't hold the next item are also wasteful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }
    // Reward when the next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 300.0;
        // If existing bins are congested, new bin becomes more attractive.
        score -= 20.0 * open_bins_count as f64;
        // If the mean residual of open bins is small (they're full), new bin helps.
        score -= 4.0 * mean_residual;
        // Early in the stream, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * (1.0 - progress);
    }

    // Open-bins pressure: mildly discourage spreading across many bins
    // unless the fit is tight.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness;
    score += 3.0 * open_bins_count as f64;

    // Prefer bins whose residual was already close to the item size (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        // Reward perfect 2-step lookahead match: post_residual equals next item size
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - lookahead_gap / 100.0).max(0.0);

        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 25.0;
        }

        // Penalize post_residual that is too small for next item but not tiny (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful fit)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless item is large or stream is early
    if is_new_bin {
        let base_penalty = 45.0 * (1.0 - progress);
        score += base_penalty + item_size as f64 * 0.2;
        // If next item could pair with leftover, opening new bin is less attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Late in stream, prefer tight fits more aggressively
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 18.0;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.5 * next_item_size as f64;
        } else {
            score += 6.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Many fitting bins: can afford to be picky; penalize loose fits harder.
    if fitting_bins_count > 2 {
        score += fit_ratio * 12.0;
    }

    // Global pressure: few bins relative to progress -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 1.5 * (1.0 - progress);
    }

    // Prefer bins whose residual is near the mean (keeps residuals balanced),
    // but only early in the stream; late, prefer filling high-residual bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if progress < 0.5 {
        score += dev * 0.3;
    } else {
        score -= dev * 0.2;
    }

    // New-bin candidate: only attractive when it enables a big item pairing
    // or existing bins are poorly suited.
    if bin_residual == bin_capacity {
        let base = 30.0 + fit_ratio * 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score = base - 15.0; // pair next item in fresh bin
        } else {
            score = base + (open_bins_count as f64) * 2.0;
        }
        if fitting_bins_count > 0 {
            score += 8.0; // existing bins can take it; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress interaction: later in the stream, dead space matters more
    score += 30.0 * progress * norm_pr * (1.0 - norm_pr);

    // Perfect fit reward (smooth gaussian-like bump around zero residual)
    score -= 25.0 * (-(norm_pr * norm_pr) / 0.005).exp();

    // Last-chance bin: reward using it (penalize alternatives indirectly)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly unless current bin would leave large dead space
    if bin_residual == bin_capacity {
        let waste = norm_pr; // equals 1.0 for new bin
        let lookahead_waste = if next_item_size > 0 {
            ((bin_capacity - next_item_size.min(bin_capacity)) as f64) / cap
        } else {
            0.0
        };
        score = pr + 20.0 * (1.0 - progress) * waste - 10.0 * progress * lookahead_waste;
        // discourage opening new bins when many fit elsewhere
        score += 8.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward residual that still fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mean residual context: bins far below mean residual get slight penalty (fragmentation)
    score += 2.0 * ((mean_residual - pr) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "reusable"
    // residue classes (multiples of 10, i.e. class 0 mod 10) are preferred.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0; // perfectly aligned leftover, easy to fill later
    } else if class <= 3 {
        score += 6.0;  // small awkward dead space
    }

    // Dead-space penalty: tiny unusable leftovers (cannot fit even min item)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Integer-division threshold on post_residual: quarter-capacity bands
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score -= 8.0; // bin nearly full: good consolidation
    } else if post_residual > 3 * quarter {
        score += 4.0; // barely dented bin: wasteful placement
    }

    // Lookahead coupling: does next item fit the harmonic leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 14.0; // next item then closes/aligns the bin
            } else {
                score -= 6.0; // next item fits at all
            }
        } else {
            score += 10.0; // this placement blocks the lookahead item
        }
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement is bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits elsewhere: must open
        }
        // late in the stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean-residual coupling: avoid bins far from the fleet average
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post-residual too small for next item: dead space penalty scaled by waste
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste, slight bonus for tight fit
        score -= 10.0;
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Favor tight fits overall (small relative waste)
    score += 0.2 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 10.0;

    // Early in stream: prefer keeping bins flexible (moderate residuals); late: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item is worse.
            score += 4.0 + 0.5 * (post_residual as f64);
        }
        // Bonus if post_residual exactly matches next item (perfect chain).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        // Penalize if using it creates large unusable residue anyway.
        if post_residual > 0 && post_residual < 10 {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when the item
    // is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Early stream: opening bins is cheap; late stream: consolidate.
        let new_bin_bonus = 6.0 * (1.0 - progress) + 10.0 * item_frac;
        score -= new_bin_bonus;
        // If many bins are open and mean residual is high, discourage yet another bin.
        score += 0.15 * open_bins_count as f64 + 0.10 * mean_residual;
        // But if no open bin can fit (fitting_bins_count==0), new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with residual close to item (exactness reward).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    // Time-horizon modulation: as stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;

    // Base: squared post-residual penalizes wasted space super-linearly.
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling with stream progress: late in the stream,
    // tight fits matter more (dead space is harder to recover).
    let tightness = 1.0 - pr_n;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Reward bins whose residual closely matches the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 15.0 * (-50.0 * diff * diff).exp();
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when this bin's residual deviates from mean residual
    // (encourages balanced residual profiles across open bins).
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for fewer open bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 5.0 + 25.0 * (1.0 - scarcity) - 10.0 * pr_n;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds
    let class = post_residual / 10; // 0..=10 harmonic classes
    // Reward small post_residual (tight fit), non-linearly
    score -= match class {
        0 => 40.0,
        1 => 22.0,
        2 => 12.0,
        3 => 6.0,
        4 => 2.0,
        _ => 0.0,
    };

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: post_residual too small for any plausible item (1..100 unknown dist)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with next item: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Harmonic bonus: next item leaves a good class residual too
        let next_post = post_residual - next_item_size;
        if next_post / 10 <= 2 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty proportional to leftover
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin ~ near-full residual
        score = bin_capacity as f64 - 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        // open new bin if mean residual of open bins is fragmented
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    // Progress modulation: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Prefer filling bins with higher residual (reduce fragmentation) mildly
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Reward using bins with small residual (tight packing), scaled by fit tightness.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: if mean residual is small, opening new bins wastes space.
    if mean_residual < item_size as f64 {
        score += 10.0;
    } else if mean_residual > 50.0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; otherwise penalize leaving a gap that nothing can use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 12.0;
        }
    }

    // New-bin candidate: moderate default score; only chosen when open bins score worse.
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 2.0 - (post_residual as f64);
        // Late in the stream, opening a new bin is more acceptable.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward scaled by tightness of fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * slack;
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.25 * dead;
        }
    }

    // Compare post_residual to mean residual: leaving less than average is good (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize wasteful placements into very roomy bins when many bins are open.
    if post_residual as f64 > mean_residual + 30.0 {
        score += 10.0;
    }

    // Slight early-stream preference to keep bins tight; late-stream consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate: neutral-ish baseline, only chosen if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual that no future item can plausibly use.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0; // exact fit, great
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many bins fit; prefer the one with the least waste.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin (chain placement); otherwise penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni <= post_residual as f64) {
            score -= 8.0 * (1.0 - ni / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize more if post_residual is
            // small-but-unusable (dead space trap).
            score += 4.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    } else {
        // Last item: just minimize post_residual waste.
        score += 0.5;
    }

    // Global state: if mean residual across open bins is high, we have slack;
    // prefer reusing bins and avoid opening new ones (penalize new-bin candidate).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let slack = mean_residual / (bin_capacity as f64);
        score += 6.0 + 10.0 * slack;
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading, favor consolidation.
    score += 0.15 * (open_bins_count as f64).powf(0.8);

    // Prefer filling bins that are already relatively full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill;

    // Non-linear coupling of item size and residual: big items into big residuals.
    let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    if ratio > 1.0 {
        score += 100.0; // shouldn't happen (item doesn't fit), guard
    } else {
        score -= 6.0 * ratio * ratio; // reward using a large fraction of residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (waste minimization), non-linearly warped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Polynomial coupling: penalize large post residuals more as stream progresses
    score += (x * x) * cap * (0.5 + progress);
    score -= (x * x * x) * cap * 0.6;

    // Reward tight fits (small post residual) with smooth cubic falloff
    let tightness = (1.0 - x).max(0.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Dead-space avoidance: post residual too small for typical future items
    let dead = ((20.0 - pr).max(0.0)) / 20.0;
    score += 15.0 * dead * dead;

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for bins below mean residual (balancing load)
    score += 0.15 * (mean_residual - pr);

    // Late stream: mild penalty for opening new bins (via new-bin candidate being empty)
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of small divisors) are more likely
    // to be filled exactly by future items, so reward them.
    let cap = bin_capacity as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Modulo / integer-division harmonic classes on post_residual.
    let r10 = (post_residual % 10) as f64;
    let r25 = (post_residual % 25) as f64;
    let q10 = (post_residual / 10) as f64;

    // Residuals divisible by 10 or 25 are "harmonic" -> likely reusable.
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect closure, best outcome
    } else if post_residual % 25 == 0 {
        -25.0
    } else if post_residual % 10 == 0 {
        -15.0
    } else if post_residual % 5 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space: tiny residuals that almost nothing can use
    // (items >= 1, but small residuals under ~10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Coupling with lookahead: if the next item fits the post residual,
    // strongly reward this bin (chained placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item uses the leftover
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty scaled by overshoot class
            let over_class = (next_item_size / 10) as f64;
            score += 2.0 * over_class;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins would leave bad residues or when
    // the item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: empty bin leaves post_residual = cap - item.
        // Prefer it for large items or when all open bins would be badly fragmented.
        let fragmentation = (mean_residual - post_frac * cap).abs();
        let large_item_bonus = if item_size >= 50 { 20.0 } else { 0.0 };
        let many_open = if open_bins_count > 8 { 5.0 } else { 0.0 };
        score -= large_item_bonus + many_open - 0.1 * fragmentation;
        // Keep new bins from winning when a harmonic residual is achievable elsewhere.
        if post_residual % 10 == 0 || post_residual % 25 == 0 {
            score += 8.0;
        }
    }

    // Tight-fit reward: near-exact fills are excellent.
    let tight = 1.0 - (post_frac - (post_frac.floor()));
    if post_frac > 0.0 && post_frac <= 0.1 {
        score -= 10.0 * (1.0 - post_frac * 10.0);
    }
    let _ = tight;
    let _ = fill_frac;
    let _ = q10;
    let _ = r10;
    let _ = r25;
    let _ = mean_residual;
    let _ = step_index;
    let _ = total_items;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward large usable post-residual (keeps bin flexible).
    score -= 0.15 * (post_residual as f64).powf(0.5);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (consolidation heuristic).
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when the item is large and would leave
    // a small dead gap in any existing bin.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score -= 20.0 * tightness;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0; // opening fresh bin also risks dead space
        }
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives: new bin is wasteful
        }
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect wrap: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving residual that is too small to ever be useful
        // (less than the minimum plausible next item) but nonzero.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
        // If next item also fits after this placement, mild extra reward.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are tighter, prefer them.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer consolidation into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 30.0;
        }
    }

    // Discard near-empty leftovers as dead space.
    if post_residual > 0 && post_residual < 5 {
