    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus for small post_residual (perfect fit gets big discount)
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can't hold the next item (lookahead coupling)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward bins whose leftover exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless it's a clearly better option
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening new bins is more attractive early (more future to fill) and when open bins are crowded
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 - 20.0 * progress - 3.0 * crowding;
        // If the new bin can chain with the next item, soften penalty
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 8.0;
        }
    }

    // Mild penalty for leaving residuals near awkward mid-range values (hard to fill later)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0; // tiny unusable slivers
    } else if pr >= 10.0 && pr <= 20.0 {
        score -= 3.0; // residuals in the common small-item range are useful
    }

    // Encourage balancing residuals across bins: prefer bins near the mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for bins with more residual (keep small bins for small items)
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (fewer chances to fill it).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Strong reward for tight fits (small post_residual), smooth via quadratic term.
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize post_residual that is small-but-nonzero relative to typical item sizes:
    // dead space that no future item can use. Smooth interaction with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = pr - nxt;
        if waste > 0.0 {
            score += 0.9 * (waste / cap) * (waste / cap) * cap;
        } else {
            // next item fits perfectly into the resulting residual: big reward
            score -= 6.0 * (-waste / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer fuller bins relative to the fleet average (smooth coupling).
    score += 0.35 * (pr - mean_residual);

    // Slight preference for bins with more residual when many bins are open
    // (consolidation pressure), smooth in open_bins_count.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    // New-bin candidate handling: neutral baseline with mild progress-dependent cost
    // so early on we prefer opening bins, late we prefer filling.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.45 * progress) - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual (mod arithmetic) ----
    // Class residuals into buckets of 10: 0..9 (near-full, great), 10..19, ..., 90..99.
    let residue_class = (post_residual % 10) as f64;
    let residue_decade = (post_residual / 10) as f64;

    // Reward being in a "harmonically useful" class: residuals that are
    // multiples of small divisors of capacity are more reusable.
    // post_residual % 25 == 0 or % 20 == 0 or % 10 == 0 => subtract bonus.
    if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 20 == 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    } else {
        // Non-aligned residual: small penalty proportional to misalignment.
        score += (10 - residue_class) * 0.3;
    }

    // ---- Dead-space penalty via integer-division thresholds ----
    // Residual in (0,10) is nearly dead but acceptable; residual in
    // [10, next_item_size) is the WORST class: too big to waste, too small to use.
    if next_item_size > 0 && post_residual >= 10 && post_residual < next_item_size {
        score += 15.0 + 0.2 * (post_residual as f64);
    }

    // If next item fits exactly into post_residual, big reward (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits with some slack: mild reward scaled by leftover harmony.
        let chain_left = post_residual - next_item_size;
        score -= 6.0 - 0.1 * (chain_left % 10) as f64;
    }

    // ---- Capacity-fraction thresholds ----
    // Filling past 3/4 of capacity is desirable (bin nearly closed).
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.75 {
        score -= 8.0 * fill_frac;
    } else if fill_frac < 0.5 && post_residual > 0 {
        // Low fill of an already-open bin: waste of capacity.
        score += 5.0 * (0.5 - fill_frac);
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that can take the item; strongly prefer it
        // over opening a new bin, unless the fit is terrible (large dead space).
        if post_residual < 15 || post_residual % 10 == 0 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Empty candidate bin: baseline score = full capacity.
        // Make it attractive only when all existing fits would leave bad residue.
        // It should lose against any decent fit, so add a moderate penalty
        // that scales with how many alternatives exist.
        score = bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 10.0 + 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Early in the stream, opening bins is cheap-ish; late, prefer closing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // ---- Global context couplings ----
    // If mean residual across open bins is high, we have slack everywhere:
    // be pickier (penalize loose fits more).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Many open bins: discourage spreading, reward tight placements more.
    if open_bins_count > 3 {
        score -= (post_residual < 20) as i32 as f64 * 4.0;
        score += 0.3 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
