        }
        // Penalize if gap is just barely too small for the next item (near-dead).
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(8) {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Tightness reward: filling most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: encourage closing bins out when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Deviation from mean residual: prefer bins that are already well-used.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate should only win when all open fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
        // Allow new bin early in stream or when item is large.
        if progress < 0.15 || item_size > 70 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: strongly reward when next item exactly fills the remainder.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: reward proportional closeness of the fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize dead space created.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Compare post_residual against mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        // Tighter than average: good consolidation.
        score -= 0.3 * (mean_residual - pr);
    } else {
        // Looser than average: mild penalty.
        score += 0.15 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins (keep residuals flexible);
    // late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it normally, less so early on.
        score += 30.0 - 15.0 * progress;
        // If no open bin fits well (large post residual), new bin becomes attractive.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
    } else {
        // Favor existing bins more as stream progresses.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small post_residuals that are still "dead" relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers are worse than exact fits
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 6.0 + 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 5.0 * (1.0 - (post_residual as f64) / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin whose post-residual is most "usable".
        score += 2.0 * fitting_bins_count as f64;
    }

    // Global state: when many bins are open and mean residual is high, prefer
    // consolidating into already-open bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    score += 0.05 * pressure;

    // New-bin candidate handling: empty bin should win only when the item fits
    // no open bin well (low fill ratio) or late in the stream with high mean residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = mean_residual / bin_capacity as f64;
        score += 30.0 - 20.0 * (1.0 - fill_ratio) - 15.0 * openness - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: new bin is mandatory
        }
    }

    // Mild time-horizon modulation: early in the stream, be greedy about tight fits;
    // late in the stream, prioritize minimizing bin count via last-chance usage.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 + 0.1 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 25.0 * coupling;

    // reward tight fits
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tight * tight;

    // lookahead: penalize wasting space needed by next item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.3 * gap;
        if pr >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // new-bin candidate: penalize slightly unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
        if mean_residual > 30.0 && open_bins_count > 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes
    let cls = post_residual / (bin_capacity / 8).max(1); // class 0..8 of residual size
    score += cls as f64 * 2.5; // larger residual class -> worse (waste)

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + (post_residual - next_item_size.min(post_residual)) as f64 * 0.15;
        } else {
            score += 12.0;
        }
        // modulo harmony: residual % next_item_size small means near-perfect chaining
        if next_item_size > 0 && post_residual >= next_item_size {
            let m = post_residual % next_item_size;
            score += m as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless they fit badly
    if bin_residual == bin_capacity {
        // brand-new bin: baseline cost of consuming fresh capacity
        score = 55.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // reward tight fits relative to capacity fraction
        let fill = 1.0 - (post_residual as f64) / cap;
        score -= fill * 20.0;
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Mid-range leftovers (10..20) are moderately wasteful too.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward excellent fits (post_residual that can still host typical items).
    if post_residual >= 20 {
        score -= 15.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage scattering into many bins unless fit is great.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit here, mild penalty for hoarding space it won't use.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is more attractive early in the stream (more future items to place).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // Attractive when open bins are nearly full on average (mean_residual small).
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    }

    // Mild tie-break toward fuller bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item size -> perfect chain
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match to next item (within small slack)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff <= 10.0 {
            score -= 15.0 * (1.0 - diff / 10.0);
        } else {
            // penalize wasted space relative to what next item could use
            score += 0.15 * diff;
        }
    }

    // Penalize dead space below minimum item size
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Reward filling bins tighter than the current mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Early in stream: prefer keeping residuals flexible (larger post_residual ok)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Relative tightness: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Dead-space penalty: post_residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        score -= 50.0 + (next_leftover as f64) * 0.5;
    }
    // If next item is slightly larger than post_residual, mild penalty for teasing.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins instead of spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > 30.0 && open_bins_count > 2 {
        score -= (mean_residual - 30.0) * (0.3 + 0.4 * progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well, or late in stream with
    // many bins and low mean residual.
    if bin_residual == bin_capacity {
        let good_reason = (item_size >= 50 && fitting_bins_count == 0)
            || (open_bins_count > 0 && mean_residual < 15.0);
        if good_reason {
            score -= 120.0;
        } else {
            score += 250.0 + 100.0 * (1.0 - progress); // discourage premature opening
        }
    }

    // Slight preference for bins with larger residual when item is small
    // (keeps small items from fragmenting tight bins).
    if item_size <= 25 {
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Mild time-horizon shaping: as stream ends, waste matters less.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Non-linear tightness reward: strongly reward small post_residual via quadratic shaping.
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, tight fits matter more (less room for future correction).
    let progress_coupling = (0.5 + 1.5 * progress) * (2.0 * tightness - tightness * tightness);
    score -= 12.0 * progress_coupling;

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let nx_norm = nx / cap;
        // If next item fits exactly in post_residual, big reward (smooth kernel).
        let gap = (post - nx).abs() / cap;
        score -= 10.0 * (-8.0 * gap * gap).exp() * (1.0 + progress);
        // Penalize post residuals that are small but not small enough to be useful.
        let useless = if post < nx { post / cap } else { 0.0 };
        score += 14.0 * useless * useless * (1.0 - progress * 0.5);
        // Reward post residual that can hold next item with room to spare (flexibility).
        if post >= nx {
            let flex = 1.0 - (post - nx) / cap;
            score -= 4.0 * flex * nx_norm;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many bins; encourage consolidation.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins below mean residual (consolidate fullness) with smooth coupling.
    score += 3.0 * (post - mean_residual) / cap;

    // New-bin candidate handling: empty bin has post_residual == cap - item_size.
    // Penalize opening a new bin, more so early and when other bins fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score += 30.0 + 15.0 * open_pressure * (1.2 - progress);
        // Allow opening when the item is large relative to capacity (poor fit anywhere).
        score -= 10.0 * (fit / cap) * (fit / cap);
    }

    // Mild global preference for fuller bins late in the stream.
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space in classes
    // 1..=9 is partially recoverable by small items; class 0 is "harmonic".
    let pr = post_residual as i64;
    let cls = pr % 10;
    let class_bonus: f64 = match cls {
        0 => 6.0,                      // perfectly harmonic leftover
        1 | 2 | 3 => 2.0,              // tiny dead space, low value
        4 | 5 | 6 => 0.0,
        7 | 8 | 9 => -2.5,             // awkward gap, penalize mildly
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: post_residual in [50,60) is a half-bin
    // sweet spot — very reusable.
    let half_zone = (post_residual >= bin_capacity / 2) && (post_residual < bin_capacity / 2 + 10);
    if half_zone { score -= 5.0; }

    // Dead-space penalty: post_residual below smallest plausible item (1)
    // is impossible here, but very small residuals (< 10) are near-dead.
    if post_residual < 10 { score += 8.0; }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 4.0 - (slack as f64 / 10.0).min(3.0);
        } else {
            // next item won't fit here anyway; slight penalty for wasting
            // a large residual on an item that could go elsewhere
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening fresh bins when a decent fit
    // exists; reward it when residual is very tight everywhere.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        if tight && open_bins_count > 0 {
            score -= 4.0;
        } else {
            score += 9.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit reward).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps (below the plausible
    // minimum item size) are effectively unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate dead space: penalize proportionally to how far it is from
    // fitting the lookahead item (wasted space the next item can't use).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Pressure from open bin count: when many bins are open, discourage
    // opening yet another bin (new-bin candidate gets penalty), and mildly
    // encourage consolidation into existing bins.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 6.0;
    } else {
        score -= open_bins_count as f64 * 0.8;
    }

    // Prefer bins tighter than the current mean residual (good packing).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // reward proportionally to how much room remains for the next item
            score -= 150.0 * (post_residual as f64 / (post_residual as f64 + (post_residual - next_item_size) as f64 + 1.0));
        } else {
            // dead space relative to the incoming item: penalize unusable slack
            let waste = next_item_size - post_residual;
            score += 2.0 * waste as f64;
        }
    }

    // Penalize small dead space that nothing (min size 1, but practically small) can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins whose post residual stays near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin good for a known pair
        }
    }

    // Late in the stream: prefer tighter packing, discourage opening bins
    let progress = step_index as f64 / total_items as f64;
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Waste that blocks the next item: penalize proportionally to how much it blocks.
            let block = (next_item_size - post_residual) as f64;
            score += 0.8 * block;
        } else {
            // Reward leaving space exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.5 * (1.0 - slack / bin_capacity as f64);
        }
    } else {
        // Last item: maximize fill, pure best-fit.
        score -= 10.0;
    }

    // Strongly penalize opening a new bin when other bins already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 25.0 + 3.0 * (fitting_bins_count as f64);
            // Late in the stream, opening new bins is especially costly.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 30.0 * progress;
        } else {
            // Forced new bin: neutral, slight bonus to prefer it over bad fits.
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, reward using it heavily
    // to avoid opening a bin for a single item.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate emptier bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for keeping fewer open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * (open_bins_count as f64).ln().max(0.0);

    // Tiny tie-break favoring larger item_size placements (harder to place later).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: waste after placement, mildly damped by progress
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth non-linear coupling: polynomial in post-residual fraction
    let pr_frac = pr / cap;
    score += 18.0 * pr_frac * pr_frac * (1.0 + progress);

    // Reward tight fits (post_residual near zero) more strongly late in stream
    score -= 25.0 * (1.0 - pr_frac).powi(3) * (0.5 + progress);

    // Penalize bins whose residual deviates far from mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins, unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * progress - 40.0 * fit;
    }

    // Mild preference for fuller bins (small residual before placement)
    score += 0.15 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "useful"
    // residue classes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals divisible by common item granularities.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        // Penalize awkward small dead space classes.
        if pr < 10 { score += 15.0; }
        else if pr < 20 { score += 6.0; }
        // Modulo-4 coupling: residuals near quarter-capacity classes are decent.
        let quarter = (bin_capacity / 4) as u32;
        let dist_q = ((pr as i32 - quarter as i32).abs()) % 8;
        score -= (8 - dist_q) as f64 * 0.5;
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Integer-division threshold coupling with lookahead item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward, scaled by leftover class after lookahead.
            let after2 = pr - next_item_size;
            score -= 10.0;
            if after2 % 10 == 0 { score -= 4.0; }
            if after2 == 0 { score -= 8.0; }
        } else {
            // Lookahead won't fit here: mild penalty unless this is a tight fit now.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good class.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.15;
        if pr >= item_size && pr <= 30 { score -= 5.0; }
    }

    // Tightness reward: small positive post_residual relative to item size.
    let tight = post_residual as f64 / cap;
    score -= (1.0 - tight) * 3.0;

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.05;

    // Penalize bins far from mean residual (fragmentation spreading).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (<= 10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual as i32).pow(2) as f64 * 3.0;
    }

    // Gaps that could still hold a mid-size item are fine; gaps that only fit
    // tiny items are risky. Penalize the "awkward zone" 1..=20 non-linearly.
    if post_residual >= 1 && post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins / spreading across bins).
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current bin
    // would leave a large dead gap AND lookahead item could use fresh capacity.
    if bin_residual == bin_capacity {
        let gap_waste = post_residual as f64 / bin_capacity as f64;
        let lookahead_helps = next_item_size > 0 && next_item_size <= bin_capacity;
        score -= 8.0; // mild baseline attraction for a fresh bin
        if gap_waste < 0.25 {
            score += 40.0; // tight fit available elsewhere: do NOT open new bin
        }
        if !lookahead_helps {
            score += 10.0;
        }
        score += mean_residual * 0.3; // if open bins have lots of room, avoid new bin
    }

    // Lookahead synergy: if the post_residual exactly accommodates the next item,
    // reward this placement strongly (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins early in the stream to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 45.0; // perfect 2-step match: this bin will be exactly filled next
        } else if post_residual >= next_item_size {
            // slack after next placement; penalize proportional to leftover dead space
            let after_next = post_residual - next_item_size;
            score += (after_next as f64) * 0.6;
            // bonus if next item then fits snugly relative to mean residual
            if (after_next as f64) < mean_residual * 0.25 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; residual becomes final dead space
            score += (post_residual as f64) * 0.35;
        }
    } else {
        // last item: prefer minimal leftover
        score += (post_residual as f64) * 0.2;
    }

    // Penalize residuals that are unusable for typical future items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Relative-to-mean adjustment: bins tighter than average are precious
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is huge or no good fits exist
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild stream-progression pressure: as stream advances, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Penalize small-but-nonzero dead space that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the fit elsewhere is terrible (post_residual very small).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late, avoid fragmentation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below average (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Slight pressure to keep number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * p2;
    score += 8.0 * coupling;

    // Reward tight fits: subtract when post_residual is small relative to item.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 5.0 * (1.0 - pr / cap) * (0.5 + p2);
    } else if next_item_size > 0 {
        score -= 3.0 * (pr / cap);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly discouraged early, more acceptable late.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) - 2.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate waste).
    score += 2.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality depends on which
    // "capacity fraction" class the leftover falls into.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Class boundaries: post_residual in {0, <=10, <=25, <=50, >50}
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 12.0; // near-closure, tiny dead space
    } else if post_residual <= 25 {
        score -= 3.0; // usable for small items
    } else if post_residual <= 50 {
        score += 4.0; // awkward mid-class
    } else {
        score += 10.0; // large leftover = wasteful placement
    }

    // Modulo arithmetic on post_residual: leftovers that are "nice" sizes
    // (multiples of 10 or 5) are more likely reusable by future items.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 5.0;
    } else if m10 == 5 {
        score -= 2.5;
    } else {
        score += (m10 as f64) * 0.4;
    }

    // Integer-division threshold: how many "small items" (size<=10) fit in leftover
    let slots = post_residual / 10;
    score -= (slots.min(5) as f64) * 2.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_waste as f64 / c);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tighter existing bins over the fresh empty bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins are badly fragmented.
        score += 25.0 - (mean_residual / c) * 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> must open
        }
    } else {
        // Tight-fit reward: fraction of bin consumed by this item.
        score -= 10.0 * (item_size as f64 / c);
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // Prefer bins with residual close to item (best-fit flavor) via mean coupling.
    score += ((bin_residual as f64) - (item_size as f64) - mean_residual).abs() * 0.05;

    // Mild penalty for proliferating bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space: residuals too small for any plausible item (assume min size 1,
    // but small gaps < item_size are hard to reuse; penalize sub-usable gaps).
    // A residual gap smaller than the smallest plausible follow-up item is waste.
    let min_plausible = 1u32;
    if post_residual < min_plausible.max(next_item_size.min(item_size)) {
        score += 500.0;
    }

    // Penalize gaps that cannot fit the known next item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0; // perfect two-item packing
    }

    // Reward tight fits generally: prefer small post_residual relative to bin capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would be left with large usable residual anyway. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive when few bins are open (pressure to consolidate),
        // cheaper when many open bins exist and residual fragmentation is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * (1.0 - progress);
        score += 40.0 + pressure;
        // If current bin fit would leave a decent gap for the next item, prefer open bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 50.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // this bin's post_residual is below the mean residual (fragmenting).
    if (post_residual as f64) < mean_residual {
        score += 0.15 * open_bins_count as f64;
    } else {
        score -= 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 120.0;
        } else {
            // post residual too small for next item: penalize dead space
            score += 60.0 * (1.0 - (post_residual as f64) / 100.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = 150.0 + (item_size as f64);
        if fitting_bins_count == 1 {
            score -= 300.0; // still prefer the last open bin over a new one
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < item_size as f64 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively (dead space minimization).
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 15 {
        score -= 10.0;
    } else if post_residual < 30 {
        score -= 4.0;
    }

    // Penalize bins whose leftover would be a known-hard gap (small unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item could still fit into the post-residual,
    // reward preserving that compatibility; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 3.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.2 * next_item_size as f64;
        }
        // Perfect two-item packing: current + next exactly fill this bin.
        if next_item_size as u32 == post_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are very full on average or the item fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Reward new bin when existing bins are quite full or few bins are open.
        let opening_bonus = 8.0 * avg_fill + 6.0 * progress - 2.0 * open_bins_count as f64;
        score += 45.0 - opening_bonus; // base penalty keeps new bins conservative
    }

    // Mild preference for fuller bins among open candidates.
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight global regularization: avoid scattering residual mass.
    score += 0.02 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Penalize large residuals more as stream progresses (less time to fill them)
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward near-perfect fits smoothly
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_item) * norm_item;

    // Lookahead coupling: reward residual that fits the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 10.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            score += 6.0 * ((n - pr) / cap) * (n / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mildly discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - norm_item) * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    score += 3.0 * (pr - mean_residual) / cap;

    // Slight preference for fuller bins (smaller post_residual) via non-linear term
    score += 4.0 * norm_pr * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions)
    let post_class = post_residual % 10;
    // Dead-space penalty: residuals in (0,10) are unusable for min-size items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // reward post-residuals in reusable harmonic classes (multiples of 5/10)
        if post_class == 0 {
            score -= 12.0;
        } else if post_class == 5 {
            score -= 6.0;
        }
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 25; // capacity quarter classes
    score -= q as f64 * 8.0;

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
            // harmonic class match: post_residual % 10 aligned with next size class
            if (post_residual % 10) >= (next_item_size % 10) && post_residual >= next_item_size {
                score -= 5.0;
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    } else {
        // last item: prefer perfect closure
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer tighter bins among open ones (relative to mean residual)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: only attractive late in stream or when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0
            - 25.0 * progress
            - 3.0 * (open_bins_count as f64)
            + (mean_residual - item_size as f64).abs() * 0.3;
        // discourage new bin if a good harmonic fit exists elsewhere
        if post_residual == 0 {
            score += 50.0;
        }
    }

    // Mild pressure to close bins as stream progresses
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Residuals too small for the lookahead item are semi-dead if the next
    // item cannot use them either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual relative to what was consumed).
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 12.0;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 8.0 + open_bins_count as f64 * 2.5 + progress * 15.0;
        // But if no open bin fits well, opening may be warranted: soften penalty
        // when the only fitting bin would leave a bad dead space.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 20.0;
    }

    // Prefer bins whose residual is below mean residual (denser bins first),
    // keeping a spread of residuals for future items.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: prefer filling a bin completely.
        score -= 40.0 * tightness;
    }

    // Relative to mean residual: bins tighter than average are good targets.
    let diff = (post_residual as f64) - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize new-bin candidate mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no real competition for tight fits, opening fresh is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small post-residual,
    // with a superlinear penalty for large dead space.
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Perfect / near-perfect fits get a big bonus.
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 25.0;
    } else if post <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this bin
    // retains future value; if post-residual is dead space for the next item,
    // penalize slightly (unless it was a perfect fit anyway).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0 * (1.0 - post / bin_capacity as f64);
        } else {
            score += 4.0 * (nxt - post as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (few fitting bins) or residuals are low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (fitting_bins_count as f64).max(1.0);
        // Base penalty so a new bin is chosen only when fits are poor.
        let mut new_bin_score = 18.0 + 10.0 / crowding;
        // Later in the stream, prefer consolidating into open bins.
        new_bin_score += 15.0 * progress;
        // If mean residual across open bins is high, prefer reusing them.
        new_bin_score += 0.25 * (mean_residual - post).max(0.0);
        // Reward new bin when item is large and would leave near-zero residual
        // elsewhere but large residual here (fresh space for big future items).
        if item_size >= bin_capacity * 7 / 10 {
            new_bin_score -= 8.0;
        }
        score = new_bin_score + post;
    } else {
        // Mild bonus for using bins whose residual is below the mean
        // (consolidate small leftovers, keep large residuals flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Slight penalty when many bins fit the item: prefer the tightest,
        // letting looser bins stay flexible — handled via post_residual already,
        // but add a tie-breaker scaled by number of options.
        score += 0.5 * (fitting_bins_count as f64).min(10.0);
    }

    // Time horizon: early in stream, keep bins flexible (mild dead-space
    // tolerance); late in stream, punish any waste harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post / bin_capacity as f64);

    // Penalize leaving residuals in the awkward 40..=60 band that few
    // typical items can use efficiently.
    if post >= 40 && post <= 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;

    // Base: wasted space, mildly non-linear (quadratic) coupling with stream progress.
    let mut score = pr_norm * (1.0 + 0.6 * pr_norm) * (0.7 + 0.6 * progress);

    // Perfect fits are always excellent.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Tight fits (small post residual) rewarded more strongly as stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= 2.5 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residual too small for typical items (smooth sigmoid-like).
    let small = (pr_norm * 4.0).min(1.0);
    score += 3.0 * (1.0 - small) * (1.0 - small);

    // Lookahead coupling: reward leaving room for the next item, penalize near-misses.
    if next_item_size > 0 {
        let ni = next_item_size as f64 / cap;
        let gap = (pr_norm - ni).abs();
        if gap < 0.15 {
            score -= 1.5 * (1.0 - gap / 0.15);
        } else if pr_norm < ni {
            score += 1.2 * (ni - pr_norm);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 0.4 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // New-bin candidate: make it unattractive unless all fits are poor.
    if bin_residual == bin_capacity {
        score = 6.0 + 2.0 * (1.0 - progress) - (fit - 1.0) * 0.3;
        if post_residual == 0 { score -= 10.0; }
    }

    // Mild penalty for bin fragmentation relative to mean residual.
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Small exploration tie-breaker with smooth progress coupling.
    score += 0.01 * ((step_index as f64 * 0.618).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is excellent.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Dead-space penalty: residual too small to ever fit a future item
    // (min item size is 1, but small slivers are hard to use).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.15 * fit_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: penalize proportional to wasted potential.
        score += 4.0 + 0.1 * (post_residual as f64);
    }

    // Harmonic class: mod-10 bucketing of post_residual to prefer
    // "clean" residuals that pair well with typical item sizes.
    let pr = post_residual % 10;
    if pr == 0 {
        score -= 3.0;
    } else if pr >= 7 {
        score += 2.0;
    }

    // Last-chance bin: only one open bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins with larger mean residual (consolidate emptiness).
    score -= 0.05 * mean_residual;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (large items benefit from a fresh bin) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size >= 50 { 20.0 } else { 0.0 };
        let scarcity_bonus = if open_bins_count <= 2 { 15.0 } else { 0.0 };
        score += 40.0 - large_item_bonus - scarcity_bonus + 10.0 * progress;
    }

    // Mild preference for keeping open-bin count low.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item (>=10) are wasted. Penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Larger dead space in the "awkward" band is also costly.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * fill_ratio;

    // Perfect or near-perfect closure of a bin is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    }
    // If next item would leave a tiny dead space here, penalize.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // (penalize the new-bin candidate implicitly by rewarding reuse).
    score -= open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate should only win when all open bins are nearly full:
    // make the empty-bin call (bin_residual == bin_capacity) expensive unless
    // mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual < 10.0 && open_bins_count > 0 {
            score -= 35.0;
        }
    }

    // Mild stream-progression adjustment: later in the stream, be slightly
    // more conservative about residual waste.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead matching ---
    // Reward residuals that closely match the next item's size (perfect follow-up fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 5.0 {
            // next item will fill this bin nearly perfectly
            score -= 25.0;
        } else if post_residual as f64 >= nxt {
            // next item fits with some slack: mild reward proportional to tightness
            let slack = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space that grows tighter
            let waste = nxt - post_residual as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: prefer leaving zero residual (perfect closure)
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // --- Dead-space penalty ---
    // Small, hard-to-use residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // --- Relative-to-mean coupling ---
    // Prefer bins whose post residual deviates favorably (lower) from the mean.
    score += 0.35 * (mean_residual - post_residual as f64);

    // --- Last-chance bonus ---
    // If this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is generally costly; discourage unless existing fit is terrible.
        score += 15.0;
        // Late in the stream, new bins are even less desirable (fewer chances to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility for it.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // --- Tightness reward ---
    // Filling a bin more completely is good in general.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed (dynamic time horizon).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Penalize dead space that is too small to be reusable by typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0; // usable mid-range residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Global state: when many bins are open with large mean residual, prefer
    // filling existing bins rather than spreading; when few bins, new bins are cheaper.
    let mean_resid_penalty = (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score += mean_resid_penalty * (1.0 - progress * 0.5);

    // New-bin candidate handling: empty bin gets a base penalty that shrinks
    // late in the stream or when it is the only option.
    if bin_residual == bin_capacity {
        let base = 25.0;
        let scarcity = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let late = progress * 10.0;
        let crowd = (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += base + scarcity + late + crowd;
    } else {
        // Existing bin: slight reward for keeping bin count low.
        score -= 3.0;
    }

    // Mild exploration term: non-linear coupling of fit ratio and progress.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (fit_ratio - 1.0).abs() * 5.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified as stream progresses
    let mut score = pr * pr / cap + pr;

    // Smooth non-linear coupling: waste hurts more later in the stream
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Reward tight fits (small post_residual) with a cubic bonus
    score -= (cap - pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Penalize bins far from mean residual (encourage balanced residual profile)
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 2.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    } else if next_item_size > 0 {
        score += 1.5;
    }

    // Mild penalty for opening new bins when many already open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Penalize residuals in "dead zones" that few item sizes can fill.
    // Items are 1..100, so residuals of 1..9 are nearly unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 34 {
        score += 6.0;
    }

    // Reward residuals that are exact divisors / near-multiples of common
    // item-size classes (10, 20, 25, 33, 50): modulo arithmetic harmony.
    if post_residual > 0 {
        let harmonic_bonus = if post_residual % 50 == 0 {
            25.0
        } else if post_residual % 25 == 0 {
            18.0
        } else if post_residual % 10 == 0 {
            12.0
        } else if post_residual % 20 == 0 {
            10.0
        } else if post_residual % 33 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits; residual after that item decides quality
            let r2 = post_residual - next_item_size;
            if r2 == 0 {
                score -= 25.0;
            } else if r2 < 10 {
                score += 5.0; // leaves a tiny dead remnant
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 4.0 + (next_item_size as f64 - pr).min(30.0) * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: tighten selection by rewarding tighter fits
        score -= (fitting_bins_count as f64).min(5.0) * 1.5;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item is huge relative to capacity or no good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 55.0;
        // large items pack cleanly in fresh bins
        let size_frac = item_size as f64 / cap;
        if size_frac > 0.6 {
            score -= 40.0;
        } else if size_frac > 0.4 {
            score -= 15.0;
        }
        // if many bins fit the item, discourage opening another
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // reward using bins whose residual is already small (tight packing)
        score -= (1.0 - frac) * 8.0;
        // mildly discourage scattering across many open bins
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 0.3;
        }
        // bins far below mean residual are underused; slight bonus to
        // fill the emptiest bins first (balance residuals)
        if (pr - mean_residual).abs() < 15.0 {
            score -= 3.0;
        }
    }

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger leftovers are less "dead"; slight reward for keeping flexibility.
        score -= 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading across many bins when not needed.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: baseline cost of opening a bin, modulated by how
    // poorly the item would otherwise fit (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the best alternative leaves a big gap, opening fresh is attractive.
        if post_residual == bin_capacity {
            score -= 10.0 + (mean_residual / 10.0).min(20.0);
        }
    }

    // Lookahead: if next item could use the remaining space, reward small gaps.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mild time decay: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            // Extra reward if next item then fits with small leftover again.
            if slack_after_next < 10 {
                score -= 6.0;
            }
        } else {
            // Dead space: post_residual too small for next item.
            score += 10.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 5.0;
    }

    // Compare against mean residual: bins with more room than average are better targets.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins can fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 0 {
            score += 25.0 + 10.0 * progress;
        } else {
            score -= 5.0;
        }
        // More open bins -> prefer reusing.
        score += 2.0 * open_bins_count as f64;
    }

    // Reward near-perfect fills.
    if post_residual < 5 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: residual below the smallest plausible item.
    if post_residual < 10 {
        score += 22.0;
    } else if post_residual < item_size.max(10) {
        // residual smaller than current item size class — likely wasted
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: when many bins are open relative to progress,
    // prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) / (1.0 + 50.0 * (1.0 - progress + 0.05));
    score += 4.0 * pressure;

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // prefer bins that are closer to being filled (below mean residual).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 28.0 * desperation - 12.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (fill * std::f64::consts::PI).sin();
    let mut score = pr * (1.0 + 0.6 * progress * progress);
    score -= 18.0 * tight * (0.5 + 0.5 * progress);
    // lookahead coupling: reward residuals that fit the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 6.0;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }
    // penalize deviation from mean residual (keeps bin profile homogeneous)
    score += 0.35 * (pr - mean_residual).abs();
    // smooth penalty for large dead space, amplified late in stream
    score += 0.05 * pr * pr / cap * (0.3 + 0.7 * progress);
    // mild preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * (pr / cap);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits and near-perfect fits rewarded.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Exact-fit harmonic classes on post_residual (dead space = 0 is ideal)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 15.0;
    } else if post_residual <= third {
        score -= 7.0;
    } else if post_residual <= half {
        score -= 2.0;
    } else {
        // Large residual: potentially useful, but penalize mildly to prefer tighter fills
        score += 3.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonic" with
    // common item sizes (multiples of 10, 20, 25, 50) are more reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd, awkward residuals get a small penalty
    if post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 4.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - slack / cap_f);
            if (post_residual - next_item_size) == 0 {
                score -= 10.0; // perfect chain
            }
        } else {
            // Next item won't fit here: this residual is dead for the lookahead
            score += 6.0;
            // Harmonic mismatch: post_residual mod next_item_size small means
            // the residual is nearly a multiple of the next size (partially reusable)
            let m = post_residual % next_item_size.max(1);
            if m <= 5 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into tighter fills to close bins
    if open_bins_count > 4 {
        score -= 2.0 * (post / cap_f); // favor small residuals more when busy
    }

    // Mean-residual coupling: placing here should pull mean residual down
    if post < mean_residual {
        score -= 4.0 * (mean_residual - post) / cap_f;
    } else {
        score += 3.0 * (post - mean_residual) / cap_f;
    }

    // Stream progression: late in the stream, avoid leaving large residuals
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (post / cap_f);
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Give the empty bin a moderate score so it
    // beats only genuinely bad fits.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: residual after placement = cap - item
        score = (bin_capacity - item_size) as f64;
        // Late stream or many open bins: discourage opening more bins
        if total_items > 0 {
            score += 10.0 * (step_index as f64 / total_items as f64);
        }
        if open_bins_count > 4 {
            score += 12.0;
        }
        // If next item is large and would fit better in a fresh bin, slight relief
        if next_item_size > 0 && next_item_size > half {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps that can never fit typical items (1..100 unknown, assume ~>=10) are worst.
    if post_residual > 0 {
        // Non-linear penalty: tiny residuals are disproportionately bad.
        let pr = post_residual as f64;
        let unusable = if pr < 10.0 { 1.0 } else { 0.0 };
        score += 60.0 * unusable * (1.0 - pr / 10.0);

        // Penalize residuals too small for the lookahead item (dead for next step).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Reward near-perfect fits (post_residual small but nonzero).
    score -= 8.0 * (-post_residual as f64 / 8.0).exp();

    // Reward exact closure of the bin (post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation unless dead space is avoided.
    score += 0.35 * open_bins_count as f64;

    // Slight preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Progress coupling: later in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only allow opening a new bin when the item is
    // large relative to capacity or no reasonable fit exists.
    if bin_residual == bin_capacity {
        // Base handicap so open bins with decent fits win.
        score += 30.0;
        // But if the item is huge, opening fresh is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If mean residual across open bins is small, new bin is justified.
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills this bin afterwards.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here later: scale reward by closeness of fit.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * tightness * tightness;
            // Extra reward if the two items together nearly fill the bin.
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * combined * combined;
        } else {
            // Next item cannot use the residual: penalize dead space, worse if large.
            score += 0.35 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average means better packing.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // But if the item is large relative to mean residual, new bin is less bad.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64) * (mean_residual / bin_capacity as f64);
    }

    // Early in the stream, tolerate new bins slightly more (future packing freedom).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item also fits here: mild bonus proportional to leftover after it.
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit after placement: penalize, scaled by how wasteful.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize opening a new bin when existing bins can fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 40.0 + mean_residual * 0.5;
    }
    // Favor new bin if it's the only real option late in the stream.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to the item (tight packing) via non-linear term.
    let slack = (bin_residual - item_size) as f64;
    score += slack * slack * 0.01;

    // Time horizon: later in the stream, be more conservative (avoid many tiny slacks).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.3;

    // Global state: many open bins with high mean residual -> prefer filling those.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * 2.0 - mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress
    // Early stream: tolerate residual (bins can still be filled later).
    // Late stream: penalize residual quadratically to force tight fits.
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * pr * (x * x);

    // Smooth dead-space penalty: residuals that cannot host mid-size items
    // (next item lookahead) get a smooth cubic bump.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 40.0 * gap * gap * gap;
        // Reward bins that can also fit the next item (smooth coupling)
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 25.0 * fits_next * (1.0 - t);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x) * (1.0 - x);
    }

    // Mild preference for bins tighter than average (smooth interaction)
    score += 0.3 * (mean_residual - pr) * (1.0 - t);

    // New-bin candidate: keep neutral baseline, slight late-stream penalty
    // so opening fresh bins is discouraged unless residuals are terrible.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * t) - 0.5 * mean_residual * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/3, 1/4 of C)
    let cap = bin_capacity as f64;
    let half = (cap * 0.5) as u32;
    let third = (cap / 3) as u32;
    let quarter = (cap / 4) as u32;

    // Penalize residuals that fall in "dead" harmonic classes: too small for
    // typical items but not zero. Zero residual is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else {
        // Dead-space class: residual < smallest plausible next item chunk
        if post_residual < 10 {
            score += 25.0;
        }
        // Harmonic bucket: how close post_residual is to a useful fraction
        let pr = post_residual as f64;
        let frac = pr / cap;
        // Residuals in (0.5C, 1.0C) are healthy; in (0.25C, 0.5C) marginal;
        // below 0.25C increasingly dead unless near-zero.
        if frac > 0.5 {
            score -= 8.0;
        } else if frac > 0.25 {
            score += 4.0;
        } else {
            score += 12.0;
        }
        // Integer-division class: post_residual / quarter
        let class = post_residual / quarter.max(1);
        score += class as f64 * 2.0;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual,
    // penalize if next item cannot use post_residual's harmonic class.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0; // chain fit
        } else if (next_item_size as u32) <= post_residual {
            // next item fits here too: mild bonus proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 6.0 * tight;
        } else {
            // next item cannot fit in this residual: dead class penalty
            score += 5.0;
            // modulo harmony: if post_residual % next_item_size is small,
            // a future split could still use it
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit (small post_residual)
        score *= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, prefer it only when all open
    // bins would be badly fragmented. Empty bin gets post_residual = cap,
    // which already scores high (large), so add mild reward scaled by
    // fragmentation of open bins.
    if bin_residual == bin_capacity {
        score -= 10.0 + (open_bins_count as f64).sqrt() * 3.0;
        // but if mean residual is large (open bins have room), discourage new bin
        score += mean_residual * 0.15;
    }

    // Stream progression: early on, be more conservative with new bins;
    // late in stream, accept fragmentation less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin classes balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual) more aggressively than plain best-fit
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 5.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.05 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }

    // Late in stream: prefer packing into existing bins more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin {
        score -= 3.0 * progress;
    }

    // Prefer bins with below-average residual (keeps large-residual bins flexible)
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chaining fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.8; // reward decays with leftover slack
        } else {
            // next item cannot follow here: penalize residual that is too small to be useful
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    } else {
        // last item: prefer minimal residual strongly
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow opening a new bin early in stream when many bins are open and residual mean is high
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 35.0 && progress < 0.5 {
            score -= 200.0;
        }
    }

    // Mild preference for filling larger bins first when few bins open
    if open_bins_count > 1 {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Fractional fill of the bin after placement (higher fill = better).
    let fill = 1.0 - post / cap;
    score -= 25.0 * fill * fill; // superlinear reward for tight fits

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it mildly unattractive unless the fit
    // in existing bins would be very poor (large dead space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0;
        // If no existing bin fits, this call is the only option anyway;
        // reward a large enough residual for future items.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheap; late, prefer packing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits but not perfectly: mild bonus scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap
            // relative to what the next item needs.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Global state coupling: many open bins with high mean residual =>
    // prefer filling existing bins rather than spreading.
    if open_bins_count > 0 {
        let mr = mean_residual / cap;
        score += 10.0 * mr * (open_bins_count as f64).ln().max(0.0) - 5.0 * fill * mr;
    }

    // Penalize dead space in a nonlinear way (small residuals are fine,
    // medium residuals are worst since few items fit them).
    let dead = post;
    let mid_zone = (dead - 40.0).abs(); // residuals near 40-50 are least reusable
    score -= 0.2 * mid_zone * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: penalize wasted residual, with smooth non-linear coupling to stream progress.
    // Early: prefer tight fits (low post_residual). Late: dead space is costlier.
    let mut score = pr * (0.5 + 1.5 * t * t);

    // Non-linear polynomial coupling: small post_residuals are rewarded super-linearly.
    score -= 40.0 * (1.0 - norm_pr).powi(3) * (1.0 + t);

    // Penalize when this is the last fitting bin (opening a new bin would be forced otherwise).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t);
    }

    // Mild penalty for spreading across many open bins.
    score += 2.0 * open / (open + 5.0);

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let slack_ratio = ((pr - nxt) / cap).max(0.0);
        score -= fits_next * 15.0 * (1.0 - slack_ratio).powi(2);
        // Penalize leaving residual just below the next item (unusable gap).
        score += 10.0 * (nxt / cap) * (1.0 - fits_next) * (1.0 - t);
    }

    // Smooth deviation from mean residual: prefer bins near the mean to balance.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" classes (multiples of common item sizes / large chunks) are favored.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        // Perfect closure: ideal, reward heavily.
        -60.0
    } else if pr <= 10 {
        // Tiny dead space: nearly perfect, small reward.
        -25.0
    } else if pr % 10 == 0 {
        // Residual aligned to decade grid: highly reusable.
        -18.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr >= 50 {
        // Large residual: still very usable, treat like fresh-ish space.
        -15.0
    } else {
        // Awkward mid-range fragment: penalize by how "orphan" it is.
        let orphan = (pr % 10) as f64;
        orphan * 1.5
    };
    score += class_bonus;

    // Last-chance logic: if this is the ONLY bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        // If the next item would also fit in the post residual, extra reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Lookahead: reward bins whose post residual accommodates the next item,
    // scaled by how snugly it fits (small leftover after next item is good).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 + (slack_after_next / cap) * 20.0;
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 10.0;
        }
    } else {
        // Last item of the stream: strongly prefer closing bins exactly.
        if pr == 0 {
            score -= 80.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual),
    // classic best-fit pressure, but only when the fit is decent.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 45.0;
        // If few fitting bins exist and the item is large, opening a new bin
        // is reasonable (large items deserve roomy bins).
        if fitting_bins_count <= 1 || item_size >= 60 {
            score -= 55.0;
        }
        // Early in the stream, keeping bins open and flexible is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Mild preference to keep the number of open bins bounded: spread load
    // when many bins are open, concentrate when few.
    score += (open_bins_count as f64) * 0.4;

    // Deviation from mean residual: bins far below mean residual are already
    // "used up"; placing there keeps other bins flexible.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Integer-division threshold on next item: chunk the next item into
    // capacity quarters; if the post residual matches a quarter class of the
    // next item, this bin chains perfectly.
    if next_item_size > 0 {
        let quarter = next_item_size / 4;
        if quarter > 0 && pr >= quarter && pr < next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading when open_bins_count is high.
    score += 2.5 * (open_bins_count as f64).sqrt();

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item size (good match) rather than wildly larger.
    let match_quality = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * match_quality;

    // New-bin candidate logic: opening a fresh bin is attractive when the item
    // would leave a large dead gap in every existing bin, or when no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when few bins are open (early stream).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * (1.0 - progress);
        // If the item would fit snugly in a fresh bin (small item), a new bin wastes less.
        new_bin_score -= 0.2 * (bin_capacity - item_size) as f64;
        // If the item is large relative to mean residual, existing bins fit poorly.
        if item_size as f64 > mean_residual + 15.0 {
            new_bin_score -= 20.0;
        }
        // If this item is the only one that can use a lookahead item, keep bins flexible.
        if next_item_size > 0 && next_item_size <= post_residual.min(bin_capacity) {
            new_bin_score += 10.0;
        }
        return new_bin_score;
    }

    // Lookahead synergy: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // This bin's remainder becomes dead space for the known next item.
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match reward ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // This bin will be exactly filled by the next item: extremely desirable.
            score -= 60.0 + 40.0 * progress;
        } else if post_residual > next_item_size {
            // Next item still fits afterwards: mild bonus scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the remainder: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(50.0);
        }
    }

    // --- Penalize dead space: residuals too small to ever be useful ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // --- Tight fit reward: small post_residual is good (unless dead) ---
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // --- Relative-to-mean coupling: prefer bins below mean residual (more filled) ---
    score += 0.4 * (post_residual as f64 - mean_residual);

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && post_residual <= bin_residual.saturating_sub(item_size) {
        score -= 20.0;
    }

    // --- New-bin candidate handling: brand-new empty bin ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when current bins are crowded or fit is bad,
        // and the next item is large enough that a fresh bin keeps flexibility.
        let crowded = open_bins_count as f64 * 8.0;
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 15.0 } else { 0.0 };
        // Base penalty makes new bins lose against decent fits; relax late in stream.
        score = 45.0 + crowded * (1.0 - progress) - bad_fit - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

