        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if we leave a tempting mid residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste.min(60.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are fragmented / poor fits.
    if bin_residual == bin_capacity {
