        score += 30.0;
        // If item is large relative to capacity, new bin is fine.
        score -= 0.3 * item_size as f64;
        // If many open bins have large mean residual, prefer reusing them.
        score += 2.0 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Few fitting bins means poor global fit; new bin more acceptable.
        score -= 40.0 * (fitting_bins_count as f64).min(3.0);
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 60.0 * tightness;
        // Prefer filling older/more-filled bins to keep open count low.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild global pressure to reduce mean residual spread.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = post_residual as f64;
    let mut score = res;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals are more valuable (bins nearly closed),
    // so penalize large residuals more as progress grows.
    let norm_res = res / cap;
    score += progress * norm_res * norm_res * cap * 0.5;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= (1.0 - norm_res).powi(3) * (1.0 - progress) * 8.0;

    // Lookahead: reward residuals that can still host the next item,
    // penalize residuals that waste space relative to the lookahead need.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if res >= nxt {
            score -= 4.0 * (1.0 - nxt / cap);
        } else {
            score += 2.0 * (nxt - res) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): keep it neutral-to-slightly-high so we
    // only open a new bin when existing fits are poor; scale with open bins.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.4 * open_bins_count as f64;
    }

    // Mild pressure to prefer bins below mean residual (consolidation).
    score += 0.05 * (res - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" bands.
    let r = post_residual % 10;
    // Residues 1..9 (small nonzero) are least reusable; 0 is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly reward
    } else {
        let dead_penalty = match r {
            0 => -20.0,          // multiple of 10: likely fits small items
            1 | 2 | 3 => 30.0,   // nearly unusable slivers
            4 | 5 | 6 => 12.0,
            7 | 8 | 9 => 22.0,
            _ => 0.0,
        };
        score += dead_penalty;
    }

    // Capacity fraction classes: post_residual as fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 && post_residual > 0 {
        score += 40.0; // tiny unusable remainder
    } else if frac > 0.5 {
        score += 15.0; // wasteful: left more than half empty
    }

    // Integer division threshold: does next item fit harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item slots in: reward, more if it nearly fills
            let gap = post_residual - next_item_size;
            score -= 25.0 + (10 - (gap % 10)) as f64;
        } else {
            score += 10.0; // lookahead won't fit here
        }
    } else {
        score -= 15.0; // last item: prefer closing bins tightly
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): only attractive when existing fits are poor
    // or many bins are open with fragmented residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 20.0; // lookahead suggests fresh capacity
        }
        score += 55.0 * pressure; // default: prefer reusing open bins
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Stream progression: late in stream, tighten packing (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - frac);

    // Tie-break: prefer bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual <= 10 {
        score += 40.0; // tiny dead gap, nearly useless
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 35 {
        score -= 5.0; // moderate gap still useful for mid items
    } else {
        score -= 10.0; // large residual remains flexible
    }

    // Reward exact or near-exact fits proportionally.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.95 {
        score -= 50.0;
    } else if fit_ratio > 0.8 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // blocks the next item -> dead space for lookahead
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // strongly discourage opening new bins when open count is low.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + open_pressure * 6.0 + progress * 10.0;
        // But if all open bins would leave tiny dead gaps, opening a new bin
        // becomes attractive: reduce penalty when mean residual is small.
        if mean_residual < 15.0 {
            score -= 45.0;
        }
    } else {
        // Using an existing bin slightly rewarded when many bins are open.
        score -= open_pressure.min(10.0) * 0.5;
    }

    // Mild preference for tighter bins overall (residual proximity to item).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // next item fits: reward tight match
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 400.0; // perfect chain: post_residual == next_item_size
            }
        } else {
            // next item does NOT fit: penalize leaving residual just below next size (dead space)
            let waste = nxt - post;
            if waste <= 20.0 {
                score += 60.0 * (1.0 - waste / 20.0);
            }
        }
    }

    // Compare post_residual against mean residual: leaving less than mean is good
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins
    if bin_residual == bin_capacity {
        let fit_quality = (bin_capacity - item_size) as f64;
        score += 80.0 + 0.8 * fit_quality;
        // opening new bin is acceptable only if nothing fits well elsewhere
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Slight pressure to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with slight non-linear penalty on large waste
    score += 0.35 * (post_residual as f64).powf(1.35) / bin_capacity as f64;

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.85 {
        score -= 18.0 * tightness;
    } else if tightness < 0.25 {
        score += 6.0 * (0.25 - tightness); // penalize squandering large residuals on tiny items
    }

    // Exact or near-exact fill
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 22.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0;
        // extra reward if next item fills the remaining space nearly exactly
        let next_tight = next_item_size as f64 / post_residual as f64;
        if next_tight > 0.8 {
            score -= 10.0 * next_tight;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space the next item can't use
        score += 5.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: competition high, mild penalty to spread load
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global residual state: penalize bins far from mean residual (fragmentation control)
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early in stream, keep bins roomy; late, fill aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large and no good fits exist
    if bin_residual == bin_capacity {
        if item_size >= 60 && (fitting_bins_count == 0 || tightness > 0.75) {
            score -= 12.0;
        } else {
            score += 20.0; // discourage opening bins when open bins suffice
        }
    }

    // Mild open-bins pressure: fewer open bins preferred early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;
    let dead = if pr > 0.0 { (pr / cap).powi(3) } else { -2.0 };

    // smooth polynomial coupling of post_residual with progress
    let coupling = pr * (0.5 + progress * progress) * (1.0 + tightness * tightness);

    // lookahead: penalize residual that wastes next item's fit
    let nxt = next_item_size as f64;
    let look = if nxt > 0.0 {
        if pr >= nxt { -1.5 * (1.0 - pr / cap) } else { 0.8 * (nxt - pr) / cap }
    } else { 0.0 };

    // last-chance bonus
    let last = if fitting_bins_count == 1 { -1.0 } else { 0.0 };

    // prefer filling bins with low mean residual deviation
    let dev = (pr - mean_residual).abs() / cap;

    let mut score = coupling + dead * 10.0 + look + last + dev * 2.0 - tightness * 1.0;
    // new-bin candidate: mildly penalize unless residuals are tight
    if bin_residual == bin_capacity {
        score += 2.0 + progress * 3.0 - tightness * 0.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it matches common item sizes
    // (1..100 unknown distribution, so classify by divisibility / magnitude bands).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fill
    } else if pr < 10 {
        -30.0 // near-perfect: dead space almost unusable anyway
    } else if pr % 10 == 0 {
        -25.0 // aligns with typical size granularity
    } else if pr % 5 == 0 {
        -12.0
    } else {
        8.0 // awkward residue
    };
    score += harmonic_bonus;

    // Penalize large awkward residuals that few future items can use.
    let prf = pr as f64;
    if pr > 0 && pr < 100 {
        let usable = ((pr as f64) / 10.0).floor(); // items >=10 in original regime
        score += (prf - usable * 10.0) * 0.8;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > pr {
            score += 10.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the bin with the tightest fit
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a perfect existing fit always wins.
        score = 55.0 + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the last-chance bin
        } else {
            // If all fitting bins would leave bad residue, allow opening fresh.
            let tight_fit_exists = (bin_capacity - item_size) % 10 == 0;
            if !tight_fit_exists {
                score -= 30.0;
            }
        }
        // Late in stream, fewer open bins is better: consolidate.
        if next_item_size > 0 && next_item_size <= item_size {
            score += 5.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to fill emptier bins when many are open (balance load).
    if !is_new_bin && open_bins_count > 3 {
        let rel = (bin_residual as f64) / cap;
        if rel > mean_residual / cap {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if it is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < 25 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * pressure;

    // Lookahead: if next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap too small for the next item: dead space
    }

    // Prefer bins whose residual is below the mean (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 10.0 * pressure };
        score += escape_bonus;
        // Early stream: opening bins is cheap; later: discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the wasted lookahead potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Perfect fit bonus for the current item.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect fit leaves almost no dead space
    }

    // Penalize small unusable residual relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.1 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees lookahead fit
        }
    }

    // Mild late-stream consolidation: prefer tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: quadratic discount as post_residual approaches zero.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness * tightness;
    }

    // Lookahead: strongly favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            let waste = post_residual as f64;
            score += 0.10 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_gap = mean_residual - item_size as f64;
        if avg_fit_gap < 4.0 {
            score -= 5.0; // existing bins are tight; a fresh bin is fine
        } else {
            score += 12.0 + 0.15 * avg_fit_gap; // discourage wasteful new bins
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins already below the mean residual (consolidating emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Smooth non-linear coupling: dead-space penalty grows quadratically as stream progresses
    let dead_penalty = norm_pr * norm_pr * (0.5 + progress);
    score += dead_penalty * cap;
    // Reward tight fits, stronger later in the stream
    let fit_reward = (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 2.0 * progress);
    score -= fit_reward * cap;
    // Lookahead: reward residuals that accommodate next item exactly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 4.0 * (1.0 + progress);
    }
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Penalize spreading across too many open bins relative to mean residual
    score += (open_bins_count as f64).sqrt() * (mean_residual - pr).max(0.0) * 0.1;
    // New-bin candidate: mildly discourage unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarters of capacity: residuals near multiples of 25 are reusable.
    let quarter = (pr / 25.0).round();
    let quarter_dist = (pr - quarter * 25.0).abs();
    score += quarter_dist * 0.6; // penalize off-grid residuals

    // Reward residuals that are exact harmonic divisions of capacity.
    if post_residual % 50 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 10 == 0 { score -= 1.0; }

    // Dead space penalty grows super-linearly for tiny residuals.
    if post_residual < 10 {
        score += 15.0 * (10.0 - pr);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let nxt_quarter = (nxt / 25.0).round() * 25.0;
            // Reward when post_residual is harmonic with next item size.
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
            let gap = (pr - nxt).abs();
            score += gap * 0.15;
            if (pr - nxt_quarter).abs() < 1.0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot fit here regardless; slight penalty for blocking.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += cap * 0.9 + open_bins_count as f64 * 0.5;
        // But if the item is large and would leave a harmonic residual, allow it.
        if item_size % 25 == 0 || item_size % 50 == 0 {
            score -= cap * 0.35;
        }
    }

    // Tight fits are excellent.
    if post_residual == 0 {
        score -= 8.0;
    } else if post_residual <= 5 {
        score -= 3.0;
    }

    // Mild preference for bins below mean residual (conserving large gaps).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Stream progression: late in stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage opening new ones
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin, scaled by how many bins already fit the item
        score = bin_capacity as f64 * 0.6 + 8.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, new bin is fine
        }
        // early stream: opening bins is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item would fit in the post-residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and this placement would strand it, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits snugly
    // into the post-residual space (post_residual == next_item_size),
    // penalize when next item cannot use the leftover space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nx).abs();
        if nx <= pr {
            // Next item fits into this bin's remainder: reward closeness.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to
            // how much dead space remains relative to the next item.
            score += 0.6 * (pr / nx);
        }
    }

    // Penalize creating dead space below the minimum plausible item size
    // (items >= 1, so tiny slivers are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins that stay close to the mean
    // residual keep the fleet balanced; deviations are mildly penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins (spread items);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for accumulating many open bins (encourage packing).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
