pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward small post-residual with a convex (quadratic) coupling
    let mut score = pr * pr / cap;

    // Smooth stream-progress coupling: later in stream, tolerate less waste
    let waste_penalty = pr / cap;
    score += 20.0 * waste_penalty * (0.5 + progress);

    // Reward near-perfect fits with a smooth saturating term
    let tightness = 1.0 - pr / cap;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead: bonus if post-residual matches next item well (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 12.0 * (-gap / 25.0) * (0.5 + 0.5 * progress);
        // Penalize leaving residual that neither fits next item nor is tiny
        if gap > 5.0 && pr < nxt {
            score += 8.0 * (1.0 - (-gap / 40.0));
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening bins when decent fits exist,
    // but allow it early or when open bins are already fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 18.0 - 10.0 * fragmentation - 8.0 * (1.0 - progress);
        // Opening a new bin is attractive if it will be tightly used
        score += 0.3 * item;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation control)
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let mut score = post;

    // Harmonic classes: reward post_residuals that fall into "usable" residue classes.
    // Small residues (< 10) are dead space; residues matching common item sizes are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect closure
    } else if pr < 10 {
        score += 8.0; // dead space penalty
    } else {
        // Residue class bonus: post_residual divisible by small harmonics is flexible.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        // Integer-division thresholds: how many "average" items still fit.
        let slots = pr / 20;
        score -= slots as f64 * 2.0;
    }

    // Lookahead pairing: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let npost = pr - next_item_size;
            if npost < 10 { score -= 10.0; } else { score -= 4.0; }
            if npost % 10 == 0 { score -= 4.0; }
        } else {
            score += 5.0; // next item won't fit here; bin likely closes
        }
    } else {
        // Last item: prefer closing bins, avoid new bins.
        if bin_residual == bin_capacity { score += 100.0; }
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and mean residual across open bins is large.
    if bin_residual == bin_capacity {
        score += 40.0;
        score += mean_residual * 0.3;
        if fitting_bins_count > 0 { score += 20.0; }
        // Early in stream, new bins are cheaper (need spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure to consolidate into few bins.
    score += open_bins_count as f64 * 0.5;

    // Fraction-of-capacity coupling: reward placing into bins with small relative residual.
    let rel = bin_residual as f64 / cap;
    score += rel * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold future items (typical item sizes 10..80) are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // nearly unusable
        } else if post_residual < 35 {
            score += 8.0;  // marginal gap
        }
    } else {
        // Perfect fill: reward heavily.
        score -= 120.0;
    }

    // Reward tight fits (low waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Dead-space coupling: penalize when the leftover gap cannot host the
    // lookahead item, but reward when it can exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidation;
    // when few are open, allow spreading slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual < bin_capacity {
        score -= pressure.min(30.0);
    } else {
        // New-bin candidate: only attractive when existing bins would leave
        // large dead space or no bins fit well.
        score += 55.0 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 40.0; // existing bins too full anyway -> open new bin
        }
    }

    // Mild preference for bins below mean residual (balance loads).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 400.0 - slack * 8.0;
    }
    // Next item does NOT fit in the residual: penalize proportionally
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize leaving dead space (residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // If item perfectly halves a fresh bin, opening may be attractive
        if item_size * 2 == bin_capacity {
            score -= 80.0;
        }
        // If nothing else fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for good structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: bonus when post_residual is small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be filled by the next item
    if post_residual < next_item_size && next_item_size > 0 {
        score += 0.8 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item
        score -= 3.0 * (next_item_size as f64 / 100.0);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Compare against mean residual state: prefer bins below mean residual (more filled)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Global pressure: many open bins -> consolidate into existing bins
    score += 0.4 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Late in stream: tighten packing, avoid waste
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > 0.7 * bin_capacity as f64);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 15.0 + 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream: value tight fits (low post_residual) more strongly.
    let tight = (post / cap).powf(2.0 + 2.0 * progress);
    score += 30.0 * tight;

    // Reward near-perfect fills, increasingly with progress.
    let fill = 1.0 - post / cap;
    score -= 20.0 * fill * fill * (0.5 + progress);

    // Lookahead: penalize leaving a residual that neither fits next item nor is useful.
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        let gap = (next_item_size as f64 - post) / cap;
        score += 15.0 * gap * gap * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward leaving exactly enough room for the next item (chaining).
        let chain = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= 12.0 * chain.max(0.0) * chain.max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - post / cap);
    }

    // New-bin candidate: prefer opening a new bin only if post_residual of existing
    // bins would be large (poor fits) or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let mean_tight = (mean_residual / cap).powi(2);
        score = post - 8.0 - 10.0 * mean_tight - 15.0 * progress * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        if next_item_size > 0 && next_item_size as u32 <= bin_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modulo arithmetic) ---
    // Residuals divisible by 8 (harmonic with small items) are "good" dead space.
    let harmonic_class = post_residual % 8;
    let harmonic_bonus: f64 = match harmonic_class {
        0 => 14.0, // perfectly harmonic residual
        1 | 2 => 2.0,
        3 | 5 | 7 => -1.5, // prime-ish residues: mildly awkward
        4 => 6.0,          // quarter-capacity class
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if frac < 0.05 {
        score -= 10.0; // near-perfect fill
    } else if frac < 0.15 {
        score -= 4.0;
    } else if frac > 0.7 {
        score += 6.0; // leaving >70% free: wasteful unless bin was fresh
    }

    // --- Lookahead coupling (k=2): does next item harmonically fit the residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item nests exactly into the leftover: strong reward.
        score -= 12.0;
        // Extra reward if next item exactly matches the residual (perfect chain).
        if next_item_size == post_residual {
            score -= 8.0;
        }
        // Modulo chain: next item leaves a harmonic residual again.
        if (post_residual - next_item_size) % 8 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize stranded mid-size gaps.
        if post_residual < 20 {
            score += 4.0;
        }
    }

    // --- Last-chance logic: this is the only bin that fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are badly fragmented
        // (mean residual low => nothing useful left) or nothing fits well.
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        // Base penalty: prefer reusing open bins.
        score += 25.0;
        // Reward opening when existing residuals are small/unharmonic.
        score -= (1.0 - fragmentation) * 30.0;
        // If the item fits a fresh bin with harmonic leftover, boost the option.
        if post_residual % 8 == 0 {
            score -= 5.0;
        }
        // Late in the stream, consolidate: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // --- Mild pressure against spreading across too many open bins ---
    score += (open_bins_count as f64) * 0.15;

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the fleet balanced, preserves large residuals for large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are unusable for items >=10,
    // so heavily penalize them; zero residual is perfect.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 19 {
            score += 12.0;
        } else {
            // Larger leftovers are more reusable: mild reward relative to mean residual
            score -= 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Reward bins whose residual is just above the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score -= 0.3 * (bin_capacity as f64 - tightness);

    // Open-bin pressure: discourage scattering across many bins,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 9.0 { score -= 30.0; } else { score -= 8.0; }
    }
    // If next item would be stranded by a tiny gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 9 {
        score += 20.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual <= 9;
        let crowded = open_bins_count as f64 > mean_residual / 10.0;
        if bad_fit || crowded {
            score -= 15.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
