pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of residual with stream progress: later in stream,
    // small residuals are penalized more (dead space hurts more).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * (0.5 + progress);

    // Reward tight fits via smooth saturating term
    let fit_quality = 1.0 - norm_pr;
    score -= 20.0 * fit_quality * fit_quality;

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving residual compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score += 0.35 * diff;
        // bonus if next item fits perfectly in post residual
        if nxt <= pr {
            score -= 8.0 * (1.0 - diff / cap);
        }
    }

    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    // New-bin candidate handling: neutral-ish baseline, penalize if a good
    // open bin exists
    if bin_residual == bin_capacity {
        score = pr + 25.0 - 20.0 * fit_quality * fit_quality;
        if fitting_bins_count > 0 {
            score += 12.0 * (mean_residual / cap).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item sizes (mod classes) are more
    // likely to be filled later, so reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit, strongly favored
    } else if pr <= 10 {
        -20.0 // small dead space, nearly perfect
    } else {
        let mut h = 0.0;
        if pr % 10 == 0 { h -= 8.0; }
        if pr % 20 == 0 { h -= 6.0; }
        if pr % 25 == 0 { h -= 5.0; }
        if pr % 30 == 0 { h -= 4.0; }
        if pr % 15 == 0 { h -= 3.0; }
        h
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item fits but leaves another residual: penalize proportional
            // to the second-order waste.
            let second_waste = (pr - next_item_size) as f64;
            score += second_waste * 0.4;
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this residual at all: mild penalty scaled
            // by how much of the next item the residual could have covered.
            let coverage = pr as f64 / next_item_size as f64;
            score += coverage * 4.0;
        }
    } else {
        // Last item: waste is final, penalize heavily.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is justified only if the item fits poorly everywhere
    // else (large post_residual in existing bins). Penalize the new bin
    // mildly so it loses to decent fits, but keep it competitive against
    // terrible fits by bounding existing-bin advantage.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheaper than fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Cap the effective advantage of existing bins so a very poor fit
        // (huge residual) can still lose to a new bin.
        if score > 100.0 {
            score = 100.0 + (score - 100.0) * 0.3;
        }
    }

    // Prefer bins whose residual is already small relative to the mean:
    // packing tight bins first keeps big residuals available for big items.
    if bin_residual < bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= tightness * 5.0;
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Integer-division threshold on post_residual: class leftovers into
    // "usable" (>= next typical small size) vs "dead" space.
    let dead_threshold = 10u32;
    if pr > 0 && pr < dead_threshold {
        score += 10.0; // dead space under any item's minimum size
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, or smaller than
    // the minimum conceivable item) are heavily penalized quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Gaps too small for the lookahead item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual close to 0 but valid).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0 - 4.0 * post_residual as f64;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and mean residual is healthy; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already hold slack.
        score += 30.0 + 5.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 40.0;
        }
    } else {
        // Reward using existing bins, more so when bins are numerous.
        score -= 3.0 * open_bins_count.min(12) as f64;
    }

    // Last-chance bin: strongly favor filling it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Late in stream: prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild preference for bins with residual near mean (balance spread).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match => strong bonus (subtract a lot).
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item could still fit here: mild reward proportional to closeness.
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot fit: penalize dead space, worse when diff is small (wasted near-fit).
            score += 10.0 + 20.0 * (1.0 - diff / (bin_capacity as f64));
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual far above the mean wastes capacity elsewhere; penalize.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 8.0 * rel.max(-2.0);
    }

    // Tight packing reward: very small post_residual is good (unless it blocks next item, handled above).
    if post_f <= 5.0 {
        score -= 25.0;
    } else if post_f <= 15.0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist that fit well enough.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_f > 20.0 {
            score += 40.0;
        } else if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    // Slight progression scaling: later in stream, prefer tightening existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * (item_size as f64);

    // Exact or near-exact fills are extremely valuable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize large leftovers slightly.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into
    // bins with small residuals (below mean) to close them out.
    if open_bins_count > 1 {
        let dev = mean_residual - post_residual as f64;
        score += 0.1 * dev;
    }

    // Time horizon: early in the stream, keep bins roomy (favor larger post
    // residual slightly); late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 5.0 * tightness;

    // New-bin candidate: make it attractive only when no open bin offers a
    // decent fit (post_residual would be small in an open bin anyway). Give
    // the empty bin a mild baseline penalty so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.1 * item_size as f64;
        // Late in the stream, opening fresh bins is less costly.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * poly;

    // Penalize tight fits more strongly later in the stream (wasted dead space)
    let tight = (pr / cap) * (pr / cap);
    score -= 12.0 * tight * (0.5 + 0.5 * progress);

    // Reward filling a bin nearly exactly
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 25.0 * (1.0 - progress);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 6.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Deviation from mean residual: prefer bins close to mean (balanced packing)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and "harmonic" residuals
    // (values that combine well with common item sizes) are rewarded.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect fit: huge reward.
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for any plausible item (min size 1,
    // but tiny residuals < 10 are nearly useless for typical streams).
    if post > 0 && post < 10 {
        score += 40.0 * (10 - post) as f64;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair well with
    // typical item sizes; odd/prime-ish residuals create fragmentation.
    let class = post % 10;
    score -= match class {
        0 => 12.0,
        5 => 6.0,
        2 | 8 => 3.0,
        _ => 0.0,
    };

    // Fraction-of-capacity harmonic classes: residual near 1/2, 1/3, 1/4 of
    // capacity are "composable" with common item fractions.
    let half = cap / 2;
    let third = cap / 3;
    let quarter = cap / 4;
    if post == half { score -= 15.0; }
    if post == third { score -= 10.0; }
    if post == quarter { score -= 8.0; }
    if post >= half { score -= 6.0; } // large residual still useful

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size as i64 == post {
            score -= 200.0;
        } else if next_item_size as i64 <= post {
            // next item fits: prefer leaving a residual in a good class for it
            let next_post = post - next_item_size as i64;
            if next_post % 10 == 0 { score -= 10.0; }
            if next_post < 10 && next_post >= 0 { score += 15.0; }
        } else {
            // next item won't fit here: penalize residuals that trap us
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (item leaves large post_residual anyway, or nothing fits well).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // opening a new bin is penalized when open bins are already roomy
        score += 25.0 + 50.0 * pressure;
        if post == 0 { score -= 500.0; } // fresh bin perfect fit (impossible) — no-op guard
        if next_item_size > 0 && (next_item_size as i64) > post { score += 30.0; }
    }

    // Stream progression: later in stream, waste matters more; tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Many open bins: discourage spreading; reward consolidation into tighter bins.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: if this bin is tighter than average, favor it.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small to hold even the smallest item (<= 5)
    // are pure waste, so punish them heavily and non-linearly.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    } else if post_residual > 5 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // If this is the ONLY bin that can fit the item, strongly prefer using it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing residuals are large
    // (item likely fits nowhere well) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0;
        score += 1.5 * open_bins_count as f64;
        // If the next item could use this bin's leftover, opening is worse.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with below-average residual (consolidating waste).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: if the next item fits the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        if post_residual == next_item_size {
            score -= 12.0; // perfect chain: item then next item fill bin exactly
        } else if post_residual > next_item_size {
            // next item can also fit here; slight reward proportional to leftover after both
            let both = post_residual - next_item_size;
            score -= (both as f64).min(10.0) * 0.4;
        }
    } else {
        // Last item: prefer minimal post residual strongly
        score *= 1.5;
    }

    // Relative to mean residual: penalize bins far above mean residual (wasteful big holes)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score -= (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize dead space that no plausible item (min size 1, typical >= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when stream is late
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100, so any residual is usable, but very small residuals are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - next_tight);
        } else {
            // Next item won't fit here after placement; penalize unless residual is near zero anyway.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for bins with fewer alternatives competing.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: when many bins are open, encourage consolidation (prefer filling existing bins over new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to the item (near-mean keeps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) * 2.0;
        let waste_if_new = item_size as f64; // empty bin loses item_size immediately
        score = bin_capacity as f64 - 20.0 + open_pressure + waste_if_new * 0.3;
        // Late in the stream, discourage opening new bins even more.
        score += 30.0 * progress;
        // If next item is large and current item small, new bin may be justified: reduce penalty.
        if next_item_size > item_size + 20 {
            score -= 25.0;
        }
        // If this is the only viable option, allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: early stream, be more exploratory (slightly favor new bins / spread); late stream, consolidate.
    score -= 10.0 * (1.0 - progress) * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on, prefer tight fills (low post_residual); late in the stream,
    // leaving moderate residual is slightly less penalized to keep bins usable.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) * (1.0 - 0.35 * progress);

    // Smooth cubic interaction: penalize large residuals more as stream advances.
    score += 12.0 * norm_pr.powi(3) * progress;

    // Reward tight fits: bonus when post_residual is small relative to capacity.
    score -= 10.0 * (1.0 - norm_pr).powi(2) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 8.0 * fit_quality * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        // Smooth penalty if next item cannot use the leftover space.
        score += 4.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild penalty when this bin's residual deviates from the mean residual
    // (encourages balanced residual profiles across open bins).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline with slight early-stream openness.
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.3 * progress) + 15.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: items 1..100, capacity 100.
    // Class A: post_residual <= 9  -> nearly dead space, excellent placement.
    if post_residual <= 9 {
        score -= 60.0 + (9 - post_residual) as f64 * 3.0;
    }
    // Class B: 10 <= post_residual <= 19 -> still usable for small items.
    else if post_residual <= 19 {
        score -= 25.0;
    }
    // Class C: 20..29 marginal
    else if post_residual <= 29 {
        score -= 8.0;
    }
    // Class D: 30..49 awkward zone: big enough to tempt, small enough to waste.
    else if post_residual <= 49 {
        score += 10.0;
    }
    // Class E: >= 50 : large residual, fine but not urgent to fill.

    // Modulo coupling: post_residual mod small integers as dead-space risk signal.
    let pr = post_residual as f64;
    let mod10 = (post_residual % 10) as f64;
    // Residuals that are near-multiples of 10 pair well with the 10..80 item range.
    score += (5.0 - mod10) * 0.4; // small mod10 -> slight bonus

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus, stronger the tighter the future fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
            // Harmonic pair: post_residual % next_item_size small => future reusability.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize leaving a residual in a dead zone.
            score += 12.0;
            // If post_residual is in awkward class D and next item is large, extra penalty.
            if post_residual >= 30 && post_residual <= 49 && next_item_size > 50 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: bin_residual == bin_capacity means untouched bin.
    // Only open a new bin when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 90.0;
        // But if this bin is the last chance (no fitting bins), opening is necessary.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // If item is huge relative to capacity, a fresh bin gives clean packing.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
        // Lookahead: if next item also large, fresh bin allows pairing.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Progress-based calibration: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Integer-division threshold: residual divisible by common item sizes (10,20,25,50)
    // leaves clean slots for future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to ever be useful (unusable dead space) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        // dead space: quadratic penalty scaled by how "wasted" the gap is
        let waste = (dead_threshold as f64 - post_residual as f64 + 1.0);
        score += 25.0 * waste * waste;
    }
    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead coupling: penalize leaving a gap that cannot host the next item
    // unless the gap is large enough to be reusable later.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            if post_residual <= dead_threshold {
                score += 40.0; // gap is both dead and blocking
            } else {
                score += 8.0;  // mild penalty, gap still reusable
            }
        } else if post_residual >= next_item_size && post_residual > 0 {
            score -= 6.0; // gap can absorb the lookahead item
        }
    }

    // --- Tight-fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // --- Open-bin pressure: discourage spreading across many open bins
    score += 0.35 * open_bins_count as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is a last resort: penalize, but relax when no
        // existing bin fits (fitting_bins_count == 0 means only this candidate).
        let base_penalty = 30.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // last-chance bin exists: opening new bin only if fit is terrible
            score += base_penalty - 10.0;
        } else {
            score += base_penalty;
        }
    }

    // --- Last-chance bonus: if this is the ONLY bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating space into few bins rather than fragmenting).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.15 * (mean_residual - resid);
    } else {
        score += 0.05 * (resid - mean_residual);
    }

    // --- Stream progression: as stream nears end, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus if next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that no plausible next item can use (too small).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Favor bins whose residual is tight relative to the current item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize bins far above the mean residual (wasteful big-hole usage),
    // reward bins below mean residual (conserving large spaces).
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.6 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or early in the stream, unless the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 + 20.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64).ln().max(0.0);
        score -= 25.0 * big_item; // still allow new bin for very large items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space below the minimum plausible item size (1 here, but
    // penalize residuals too small to be useful relative to mean item mass).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let lfit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * lfit;
        } else {
            // Next item won't fit here; slightly penalize leaving large gaps
            // that will go unused by the lookahead item.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    } else {
        // Last item: strongly prefer filling bins completely.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (item_size as f64 / bin_capacity as f64) * 30.0
            + (fitting_bins_count as f64) * 2.0
            + (1.0 - progress) * 5.0;
        score += 20.0 + openness;
    }

    // Prefer consolidating into bins with below-average residual (denser bins),
    // keeping high-residual bins flexible for future items.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * prn * prn * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual), stronger later in the stream
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize if next item fits well in this post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 18.0 * (1.0 - gap / cap) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // dead space: next item cannot use the leftover
        score += 10.0 * prn * (0.5 + progress);
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.6 + 0.4 * progress);
    }

    // Prefer bins below mean residual (more filled bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes mod 10 and integer-division thresholds.
    let residue_class = (post_residual % 10) as f64;
    let class_div = (post_residual / 10) as f64; // number of full "decades" left

    let mut score = post;

    // Non-linear waste shaping: small-but-nonzero leftovers are the worst
    // (dead space). Penalize leftovers in 1..=9 hard, reward exact 0.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongest reward
    } else if post_residual < 10 {
        score += (10.0 - residue_class) * 3.0; // nearly-full is still decent
    } else {
        // Dead-space penalty grows for mid-range leftovers that few future
        // items (min size 1, but typical 10..80) can use.
        if post_residual < 20 {
            score += 6.0;
        } else if post_residual < 35 {
            score += 2.0;
        } else if post_residual >= 50 {
            score -= 3.0; // roomy leftovers remain useful
        }
    }

    // Lookahead coupling: does the next item fit in the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: leftover mod 10 class compatible with next item
            let harmonic_bonus = if (next_item_size % 10) == (post_residual % 10) { 8.0 } else { 4.0 };
            score -= harmonic_bonus;
        } else {
            // Leftover too small for the next item -> likely dead space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5; // slight spread preference
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes (bin_capacity - item_size) immediately.
        // Penalize by the unused capacity fraction, unless the stream is
        // early and many bins will amortize it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        let mut nb = 30.0 + waste * 0.5;
        if progress < 0.25 { nb -= 8.0; } // early stream: cheaper to open bins
        if open_bins_count == 0 { nb = 0.0; } // no alternative at all
        score += nb;
    }

    // Mild preference toward fuller bins relative to fleet mean residual.
    score += (mean_residual - post) * 0.3;

    // Small tie-breaker by decade class to keep deterministic structure.
    score += class_div * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Non-linear penalty for small-but-usable gaps: a residual of 1..20 is
    // unlikely to be filled exactly, so discourage leaving it behind.
    if post_residual > 0 && post_residual <= 20 {
        score += 0.6 * (20 - post_residual) as f64;
    }

    // Reward tight fits (post_residual near zero but still valid).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that can exactly accommodate the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins when mean residual
    // is low (bins are nearly full), favor consolidating into fuller bins.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Slight preference for bins whose residual is close to the current mean
    // (keeps residual distribution balanced).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: opening a fresh bin is penalized mildly so it
    // is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // But if no open bin fits at all, the new bin is the only option;
        // make sure it wins by lowering the penalty when fitting bins is 0
        // (handled implicitly since open bins that fit get real scores).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild time decay: as the stream progresses, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * next_item_size as f64;
            // Extra bonus if the pair nearly fills the bin.
            let combined = item_size + next_item_size;
            if combined >= bin_capacity {
                score -= 150.0;
            }
        } else {
            // Penalize leaving residual that the next item cannot use,
            // scaled by how far off it is relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(80.0);
        }
    }

    // Relative to mean residual: prefer bins whose post residual is below average
    // (concentrating waste in fewer bins), penalize above-average leftovers.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // relative to capacity and current open bins are crowded.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let penalty = 250.0 - 180.0 * item_frac - 8.0 * crowded.min(10.0);
        score += penalty.max(0.0);
        // If no open bin can fit at all, opening is inevitable: soften penalty.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Slight stream-progression pressure: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * (1.0 - tightness * 2.0).max(0.0);

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual < 10 {
        score -= 4.0; // perfect fill, great
    } else if post_residual < item_size.min(20) {
        score += 8.0; // small unusable sliver
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; prefer tightest residual relative to mean.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in stream, slightly prefer keeping residual large for flexibility;
    // late in stream, prefer compact fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * tightness * 5.0;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 + 4.0 * fitting_bins_count as f64 };
        let scarcity = (mean_residual - item_size as f64).max(0.0) * 0.2;
        score += 30.0 + pressure + scarcity - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty on post-residual
    let mut score = norm_pr * norm_pr * cap;

    // Smooth progress coupling: later in stream, penalize residuals less aligned with future items
    let phase = progress * std::f64::consts::PI;
    let coupling = (pr - next_item_size as f64).abs() / cap;
    score += 40.0 * coupling * (progress + 0.2) * (1.0 - fit_ratio * 0.5);

    // Sinusoidal stream modulation of residual cost
    score += 8.0 * norm_pr * (1.0 + (phase * 0.5).sin());

    // Last-chance bin reward (smooth, not piecewise)
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 30.0 * last_chance * (1.0 - progress * 0.5);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 12.0 * dev * dev;

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // Perfect fit bonus (smooth exponential)
    score -= 20.0 * (-norm_pr * 6.0).exp();

    // New-bin candidate: neutral baseline, slightly favored early
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 15.0 * (1.0 - progress) + 5.0 * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly host a future item. Classify residuals by capacity fractions
    // and modulo buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space classes: residuals < 10 are essentially unusable
    // (items are >= 1 but tiny residuals waste bin slots).
    if post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes on post_residual modulo 10: residuals congruent to
    // 0 mod 10 are "round" and more reusable.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 12.0;
    } else if residue_class <= 3 {
        score += 8.0;
    }

    // Capacity-fraction thresholds: reward leaving room for half/quarter
    // capacity chunks, which are common item sizes.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 7.0;
    } else if post_residual < bin_capacity / 8 {
        score += 10.0;
    }

    // Coupling with next item: if the lookahead item fits exactly into
    // post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Favor residuals that leave a harmonic-friendly gap for the
            // next item (post_residual - next_item small or round).
            let gap = post_residual - next_item_size as f64;
            if gap <= 10.0 {
                score -= 20.0;
            }
            if (gap as u32) % 10 == 0 && gap > 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here; slightly penalize tight bins that
            // will strand this residual anyway.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad
    // fit; a new bin may be preferable.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 15.0;
    }

    // Early in the stream, prefer consolidating into fewer bins to keep
    // mean_residual high and options open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 && post < mean_residual {
        // Bins with below-average residual are the fullest; prefer filling them.
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: empty bin has full residual. Make it attractive only
    // when no good fit exists (post_residual small relative to capacity means
    // this call is for an open bin, not the new-bin candidate).
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: neutral-ish, slightly above
        // a perfect fit but below a wasteful placement.
        score = cap * 0.45;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits (waste fraction near zero).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is dead space for the future.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, allow new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure; becomes attractive only
        // when existing fits are poor (handled by other bins' penalties).
        score += 20.0 + pressure * 2.5;
        // Early in stream, opening a fresh bin is cheap.
        score -= (1.0 - progress) * 15.0;
    } else {
        // Reward using existing bins, scaled by how much residual this bin keeps.
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers creating fragmented capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits (tiny post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 / post_residual as f64;
    }

    // 2-step lookahead: reward when next item fits the residual left behind
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + 30.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // penalize leaving residual that next item cannot use
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + gap * 0.5;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose remaining space ends up closer to the average (balanced)
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Penalize very large dead space that likely becomes waste
    if pr > bin_capacity as f64 * 0.5 {
        score += (pr - bin_capacity as f64 * 0.5) * 0.8;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 25.0 };
        score += 30.0 + poor_fits + open_bins_count as f64 * 0.5;
    }

    // Slight late-stream tightening: prefer compact fills as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize post-residual dead space, especially small unusable slivers
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny sliver is wasted capacity
    }
    score += 0.3 * pr * pr / bin_capacity as f64;

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + gap);
        } else {
            score += 8.0;
        }
        // If post_residual is a sliver smaller than next item, penalize
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (favor large post_residual);
    // late in stream, prefer tight packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> favor consolidating into bins
    // below mean residual (i.e., fuller bins) to balance load.
    if bin_residual as f64 > mean_residual && open_bins_count > 2 {
        score += 6.0;
    } else if bin_residual as f64 <= mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_open_fullness = bin_capacity as f64 - mean_residual;
        let pressure = avg_open_fullness / bin_capacity as f64;
        // Keep score above typical good-fit scores unless pressure is high
        score = 40.0 + 60.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress * 0.5);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - post) / cap;
        if gap > 0.0 {
            score += 25.0 * gap * gap * (1.0 + progress);
        } else {
            score -= 8.0 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_item);
    }

    // Mild penalty when bin diverges from mean residual (fragmentation signal).
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Early stream: encourage keeping bins balanced; late stream: prioritize filling.
    score += 10.0 * (1.0 - progress) * norm_post * norm_item;

    // Slight penalty for opening a new bin when many bins could fit.
    if bin_residual == bin_capacity {
        score += 15.0 * (fitting_bins_count as f64).max(0.0) * 0.1 + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes in integer division bands.
    let class = post_residual / 10; // 0..10 harmonic class
    // Penalize mid classes (5..9) which are hard to fill; reward near-perfect fits.
    match class {
        0 => score -= 25.0,           // perfect / near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 2.0,            // awkward half-ish gap
        5 => score += 6.0,
        6 => score += 10.0,
        7 => score += 14.0,
        8 => score += 18.0,
        _ => score += 22.0,           // large gap left behind
    }

    // Lookahead coupling: does the leftover class accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can slot into the leftover: reward proportionally.
            let slack = post_residual - next_item_size;
            score -= (10.0 - (slack as f64 / 10.0).min(10.0)) * 1.5;
        } else {
            // Leftover unusable by next item: penalize dead space.
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if many bins already open
        // (amortize) or if this bin would leave the current bin in a bad class.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 10.0 * progress;
        // If the best alternative leaves a nasty mid-class gap, opening is fine.
        if class >= 4 && class <= 8 {
            new_bin_score -= 15.0;
        }
        // Small items early: keep bins flexible, prefer existing bins.
        if item_size <= 20 {
            new_bin_score += 20.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: slight preference for fuller bins (best-fit flavor),
        // modulated by how crowded the bin pool is.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 8.0;
        if open_bins_count > 6 {
            score -= 3.0; // encourage consolidation when many bins are open
        }
    }

    // Mean-residual coupling: if mean residual is large, prefer bins below mean
    // (balance load); if small, just chase tight fits.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Zero post-residual is a perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable "dead space": small gaps that few future items can use.
    // Items range 1..=100, so gaps below ~10 are almost certainly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gaps.
        score += 6.0;
    }

    // Reward tight fits: post_residual small relative to item_size.
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidation
    // (fill existing bins); when few are open, be less restrictive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement strongly (sets up a chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; slightly penalize leaving a gap the
            // next item can't use.
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin moderately so real
    // bins win, but less when the stream is early (exploration) or when the
    // mean residual of open bins is large but fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 35.0 + 30.0 * progress;
        // If open bins are mostly full (low mean residual), new bin is fine.
        score = base - mean_residual * 0.2;
        // With many open bins, discourage opening yet another.
        score += pressure * 8.0;
        // If only one bin fits and it's a bad fit, the new-bin call shouldn't
        // be overly punished.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: when the average open residual is small,
    // squeeze harder into whatever fits (avoid waste across the board).
    score += (mean_residual / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            // next item fits: small penalty proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score += 0.3 * after_next as f64;
        } else {
            // next item cannot fit: penalize leaving dead space
            let dead = next_item_size - post_residual;
            score += 0.8 * dead as f64;
        }
    }

    // Relative to mean residual: prefer bins that stay near the mean (balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when good open bins exist (new-bin candidate has residual == capacity).
    if bin_residual == bin_capacity {
        // New bin: base cost, softened if few bins open or stream near end.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress);
        // If next item is large and this new bin could chain, slightly reduce cost
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild preference for using more-open-bins states efficiently.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);
    }

    // Penalize creating dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (fill emptier bins first keeps big gaps available)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage using existing ones rather than spreading
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || post_residual as f64 > 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 35.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 18.0 * norm_pr * norm_pr
        - 12.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, dead space matters more
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score *= progress_coupling;

    // Perfect-ish fit reward (smooth, non-linear)
    let fit_quality = (pr / cap).powi(4);
    score -= 30.0 * fit_quality * (1.0 - progress * 0.5);

    // Penalize large residuals relative to mean residual (fragmentation risk)
    score += 4.0 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0).exp();
    } else {
        // Last item: minimize residual aggressively
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild penalty for too many open bins (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are bad
    if bin_residual == bin_capacity {
        score = pr + 6.0 + 10.0 * progress + 2.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual divisible by common small sizes is reusable
    let reusable_divisors: [u32; 6] = [10, 20, 25, 50, 5, 100];
    let mut reusability = 0.0;
    for (i, &d) in reusable_divisors.iter().enumerate() {
        if post_residual % d == 0 && post_residual > 0 {
            reusability += 50.0 * (reusable_divisors.len() - i) as f64;
        }
    }
    score -= reusability;

    // Penalize awkward dead space: residual in awkward mid-range (e.g., 1..10 or 21..24 style gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // harmonic decade class
    score += (class as f64) * 2.0; // prefer smaller decade class

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward if next item fits with reusable leftover
        let nxt_left = post_residual - next_item_size;
        if nxt_left % 10 == 0 {
            score -= 60.0;
        }
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize leaving a blocking residual
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when open bins have bad residuals
    if bin_residual == bin_capacity {
        // base penalty so new bins are used only when needed
        score += 150.0;
        // if current open bins are fragmented (mean residual low but many bins), allow new bin
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 120.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Mild preference for tighter bins when many are open
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect preparation: post_residual matches the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 15.0; // gap too small for the next item
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when the item leaves a large usable residual
    // or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0; // base reluctance to open new bins
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins with larger mean residual (consolidation).
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward perfect two-step chaining.
    if next_item_size > 0 {
        let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the leftover space.
        score -= 60.0 * (1.0 - chain_gap / bin_capacity as f64).max(0.0).powi(3);
        // Penalize post-residuals that can never host the next item.
        if post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // filling them is good (consolidation), leaving them empty wastes them.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item is large
    // or no open bin fits well. Penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is big and lookahead is large, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for creating tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let pr = post_residual as f64;
    score -= (1.0 - pr / bin_capacity as f64).powi(3) * 30.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bins compete with open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 * (1.0 - 0.5 * progress);

        // More open bins already -> cheaper to just open another vs. fragmenting.
        score -= (open_bins_count as f64).sqrt() * 2.0;

        // If no open bin fits well, opening is more attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Lookahead synergy: fresh bin can hold item + next item comfortably.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    } else {
        // Prefer reusing bins with larger residuals when mean residual is high
        // (keeps many medium bins alive rather than one big one).
        score += 0.3 * (mean_residual - bin_residual as f64).abs() / bin_capacity as f64;
    }

    // Time horizon: early in stream, be conservative about tight fits that
    // strand space; late in stream, exploit tight fits aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= pr * 0.2; // late: small residuals are fine, waste less matters
    } else {
        score += pr * 0.1; // early: keep bins flexible
    }

    // Mild penalty for very large items into nearly-full bins (fragmentation risk).
    if item_size >= 60 && post_residual > 0 && post_residual < item_size / 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - 2.0 * t) + x * (0.5 + t);
    let mut score = pr + 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (30.0 + 40.0 * t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 15.0 * (gap / cap) * (1.0 - t);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for residual far from mean (fragmentation)
    score += 0.1 * (pr - mean_residual).abs();

    // Discourage opening new bins early when fitting bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits strongly rewarded
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic classes: dead-space classes based on post_residual modulo small integers
    let pr = post_residual;
    if pr > 0 {
        // post_residual divisible by 10 leaves room for typical small items
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 20 == 0 {
            score -= 6.0;
        }
        // odd residuals are less reusable
        if pr % 2 == 1 {
            score += 3.0;
        }
        // small odd slivers are nearly dead
        if pr < 10 && pr % 2 == 1 {
            score += 15.0;
        }
        // post_residual in (10,20) band: awkward class
        if pr > 10 && pr < 20 {
            score += 6.0;
        }
        // exact quarter/third classes
        if pr == bin_capacity / 4 || pr == bin_capacity / 3 || pr == bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Next-item lookahead: reward residuals that can host the next item
    if next_item_size > 0 && pr >= next_item_size {
        score -= 12.0;
        // bonus if both current leftover classes align (pr - next also small or classed)
        let nr = pr - next_item_size;
        if nr == 0 {
            score -= 40.0;
        } else if nr % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // creating a gap smaller than next item: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, but discourage opening new bins
    // when the item fits well elsewhere (post_residual large on empty bin)
    if bin_residual == bin_capacity {
        score += 20.0;
        // open a new bin only for large items or when many bins already fit poorly
        if item_size >= 50 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer fuller bins: relative fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Slight preference to balance as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 15 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual).
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when pressure is low (few open bins).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins as open bin count grows.
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward keeping that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot fit in post_residual but could fit elsewhere (dead space creation).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: as stream progresses, penalize waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (2-step lookahead match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial credit if next item still fits in the post-residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual as f64 - next_item_size as f64);
    }
    // Penalize dead space that the next item cannot use.
    else if next_item_size > 0 {
        score += 8.0;
    }

    // Reward tight fits (small post residual) nonlinearly.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable gap
    // or the bin is fresh/empty. Penalize opening new bins when mean residual is high.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Discourage scattering across many open bins when mean residual is large.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);

    // Mild phase bias: later in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

