    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead: if next item fits into post_residual, strongly reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // Penalize leaving residual that is too small for typical future items (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: only bin that fits the item -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor (large post_residual) or bins are very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        let fragmented = mean_residual > 45.0 && open_bins_count > 2;
        if poor_fit || fragmented {
            score -= 10.0 + 8.0 * progress;
        } else {
            score += 25.0; // prefer reusing a well-fitting open bin
        }
    }

    // Prefer bins below mean residual (fills emptier bins, keeps tight ones flexible)
    score -= 0.08 * (mean_residual - bin_residual as f64);

    // Slight preference for filling nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let isn = item_size as f64 / cap;
    let nn = next_item_size as f64 / cap;

    let mut score = prn;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (0.6 + 0.8 * progress) - 0.5 * prn * (1.0 - progress) * (1.0 - progress);
    score += poly;

    // Reward tight fits, stronger later in the stream (smooth cubic progress)
    score -= isn * isn * (0.8 + 1.2 * progress * progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    let unusable = (prn - nn).max(0.0);
    score += unusable * unusable * (0.5 + progress);

    // Reward using bins when few fitting bins remain (last chance)
    if fitting_bins_count == 1 {
        score -= 0.4 * (1.0 - progress) + 0.2;
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual
    score += 0.05 * (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0);

    // New-bin candidate: only attractive when residuals are mostly consumed
    if bin_residual == bin_capacity {
        score += 0.3 + 0.6 * (1.0 - progress) - 0.5 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    // Residue 0 is perfect packing; residue 1..=5 is nearly dead; residue 6..=9 is reusable.
    let residue = (post_residual % 10) as f64;
    if post_residual > 0 {
        score -= 12.0 * (1.0 - residue / 10.0).powi(2); // reward low residues
    } else {
        score -= 20.0; // perfect fill
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0; // tiny sliver: mostly dead space, penalize unless residue was great
    } else if post_residual < 2 * quarter {
        score -= 4.0; // sweet spot: fits half-size items
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_residue = ((post_residual - next_item_size) % 10) as f64;
            score -= 10.0 * (1.0 - next_residue / 10.0);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep empty bins competitive only when current bin
    // would leave a bad harmonic class or next item is large.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && residue >= 6.0 && next_item_size > post_residual;
        if bad_fit {
            score -= 8.0; // open fresh bin rather than fragment
        } else {
            score += 25.0; // prefer existing bins generally
        }
    }

    // Stream progression: early on, tolerate more open bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse early when bins are plentiful and reusable.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Open bins pressure: discourage spreading across many open bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only mildly, so dead-space logic dominates.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits but not quite, this creates future dead space.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline, only chosen when open bins look bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.8 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item's size (perfect 2-step fill).
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 60.0 / (1.0 + lookahead_gap);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        let dead = post_residual as f64;
        score += dead * (next_item_size as f64 / bin_capacity as f64);
    }

    // Penalize tiny unusable residuals (wasted capacity).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, encourage opening new bins to build a diverse pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (min item size 1, typical larger).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prioritize closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64 - item_size as f64) * 0.1;
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with below-average residual (larger fill).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += dev * 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += pressure + open_bins_count as f64 * 2.0;
        // Late stream: reusing existing bins is cheaper.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 60.0 * x * x * (0.5 + progress)
        - 25.0 * x * (1.0 - progress) * (mean_residual / cap);

    // Reward near-perfect fits with smooth polynomial term
    score -= 40.0 * (1.0 - x).powi(3) * (1.0 + progress);

    // Last-chance bonus: penalize alternatives when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 30.0 * gap * gap;
        // Penalize if post_residual is just barely below next item size (dead space)
        let shortfall = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * shortfall * (1.0 - shortfall);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic classes: classify post_residual by modulo classes of 10.
    let class = post_residual % 10;
    match class {
        0 => score -= 10.0,       // clean class: residual reusable by common sizes
        1..=3 => score += 6.0,    // awkward sliver dead space
        4..=7 => score += 2.0,    // mildly awkward
        _ => score -= 4.0,        // 8-9: close to next clean class
    }

    // Penalize leaving residual smaller than the minimum plausible item (dead space),
    // but reward residuals that can host medium items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current item + next item
    // cannot combine well with existing residuals, or when the fit here is poor.
    if bin_residual == bin_capacity {
        // brand-new bin: neutral base, penalize slightly so only chosen when open bins are bad
        score += 15.0;
        // If lookahead item is large and this item is large, a fresh bin may be better
        if next_item_size > 50 && item_size > 50 {
            score -= 25.0;
        }
        // Early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here afterwards: good chaining
        score -= 8.0;
        // harmonic class match between next item and post_residual
        if post_residual % 10 >= next_item_size % 10 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportional waste
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.2 * (mean_residual - res_f);
    } else {
        score += 0.1 * (res_f - mean_residual);
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // gap too small for any item (min size 1..100 stream, but small gaps rarely reusable)
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (best-fit coupling)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // If this is the only bin that fits, strongly favor using it (avoid new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and current bins have poor residual structure.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 3.0 * open_bins_count as f64;
        // lookahead: if next item is small, a fresh bin is attractive
        let lookahead_bonus = if next_item_size > 0 && (next_item_size as u32) <= 30 {
            -10.0
        } else {
            0.0
        };
        // if the item leaves a large residual in a fresh bin, that's fine
        score += base_penalty + lookahead_bonus
            - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Lookahead synergy: reward if post_residual accommodates next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0; // next item will perfectly consume the gap
        } else {
            score -= 8.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a laggard; prefer filling it
    if (bin_residual as f64) > mean_residual + 10.0 {
        score -= 5.0;
    } else if (bin_residual as f64) < mean_residual - 10.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly / well.
    if next_item_size > 0 && post_residual > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 500.0; // chain a perfect follow-up fit
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // reward proportional to how well the next item fills the remainder
            score -= 80.0 * (1.0 - slack as f64 / post_residual as f64);
            // extra bonus if the next item fills most of the remainder
            if slack <= 5 {
                score -= 120.0;
            }
        } else {
            // next item won't fit: residual is likely dead space
            let waste = next_item_size - post_residual;
            score += 30.0 * (waste as f64 / next as f64);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early/many open bins.
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        // but if item is large relative to mean residual of open bins, allow it
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > mean_residual * 0.9 {
            score -= 90.0 * (0.5 + progress);
        }
    }

    // Mild preference for tighter fits overall.
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead (k=2): favor bins whose post-residual can host the next item,
    // scaled by how snugly the next item would fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 10.0 * snug;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space: leftover too small for the next item.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // discourage opening yet another bin (handled via new-bin penalty below)
    // and encourage consolidation into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual >= item_size && (post_residual as f64) < mean_residual {
        score -= 3.0 + 4.0 * progress;
    }

    // New-bin candidate: only attractive when existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high unless no open bin fits well.
        score = 60.0 + item_size as f64 * 0.5 - (mean_residual * 0.2);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // keep the last-chance bin alive
        }
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 5.0; // fresh bin leaves room for lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64
        - 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x)   // reward very tight fits
        + 8.0 * x * x * cap;                          // penalize large dead space quadratically

    // Stream-progress coupling: later in the stream, dead space matters more
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score += prog_coupling * (x * x) * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - x);
    }

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0));
        }
    }

    // Prefer bins with residual below mean (consolidate waste)
    score += 0.3 * (pr - mean_residual);

    // Mild penalty for proliferating open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 30.0 * progress - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions capacity
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual / quarter; // 0..=4 integer division class

    // Reward tight fits (small post_residual), extra reward for exact fit
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo logic: residuals that are multiples of small item sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Penalize dead space: post residual too small for any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Class-based coupling with next item lookahead
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too: strong reward, scaled by leftover after both
            let two_step_left = post_residual - next_item_size;
            score -= 10.0 + 8.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            if two_step_left % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize more in low classes (wasted big residual)
            score += 4.0 + 3.0 * (class as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // open new bin if mean residual is fragmented
        if mean_residual < quarter as f64 && fitting_bins_count > 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > quarter {
            score -= 8.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild stream-phase adjustment: consolidate early, tighten late
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..25) are semi-dead: moderate penalty scaled by gap smallness.
    if post_residual >= 10 && post_residual < 25 {
        score += 0.8 * (25.0 - post_residual as f64);
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bin's residual being well used relative to item size (tight packing).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from open bins count: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current bins are nearly full on average
    // or nothing fits well.
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual / bin_capacity as f64;
        score += 30.0 + 50.0 * (1.0 - mean_tightness);
        // Allow new bin early when many bins open anyway (fragmentation control).
        score -= 5.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how much slack remains after that.
            let after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 * (after_next / bin_capacity as f64);
        } else {
            // Next item does NOT fit in this bin after placement: penalize dead space
            // that the next item cannot use.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / 100.0).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins whose residual is below the mean residual (filling fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Mild preference for keeping the number of open bins bounded early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 8 && progress < 0.5 {
        score += 4.0;
    }

    // New-bin candidate: make opening a new bin only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so an existing reasonable fit is preferred.
        score += 20.0;
        // But if the item is large relative to typical residuals, a fresh bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= 2.5 * (bin_capacity as f64 - post_residual as f64).abs() / bin_capacity as f64 * 10.0;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that can't fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += (post_residual as f64) * 0.05; // next item won't fit here
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * open_pressure.min(5.0);
    } else {
        // New bin candidate: penalize unless current fit is poor
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && fit_quality > 0.5 {
            score += 25.0; // keep using existing bins when fit is decent
        } else {
            score += 5.0 * (1.0 - fit_quality);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, be more selective; later, fill greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual interacts with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Smooth interaction: tight fits (small post_residual) rewarded more as stream progresses.
    score -= (1.0 - pr_norm) * (1.0 + progress) * 12.0;

    // Penalize mid-range residual (dead space) via cubic term.
    score += pr2 * (1.0 - pr2) * 20.0 * (0.5 + progress);

    // Cubic decay for large residuals: favor bins that keep usable space early on.
    score += pr3 * 8.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward.
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        let tightness = 1.0 - ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64).abs();
        score -= next_fits * tightness * 10.0;
    }

    // Slight preference toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual alignment: prefer bins near the mean to preserve spread.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead-space classes".
    let pr = post_residual;
    let class = pr % 10;
    // Residues 1..9 (non-multiples of 10) are awkward dead space; penalize proportionally.
    if class != 0 {
        let awkwardness = if class <= 5 { class as f64 } else { (10 - class) as f64 };
        // Small awkward residues (1,2) are worst: nearly unusable slivers.
        score += (10.0 - awkwardness) * 2.5;
    } else {
        // Perfect decade fit: strong reward.
        score -= 15.0;
    }

    // Integer division thresholds on post_residual: does it still host another item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here too: reward chain placement, scaled by tightness.
            let tight = (pr - next_item_size) as f64;
            score -= 20.0 - 0.15 * tight;
            // Harmonic pairing: (next_item_size + item_size) % capacity classes
            let pair_class = (item_size + next_item_size) % 20;
            if pair_class == 0 { score -= 8.0; }
            else if pair_class >= 15 { score += 4.0; }
        } else {
            // Next item cannot follow: this bin becomes terminal; penalize if pr is large.
            score += 0.10 * pr as f64;
            // But if pr is tiny (< 10) it's acceptable closure.
            if pr < 10 { score -= 5.0; }
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Capacity fraction coupling: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Last-chance bin: only one bin fits item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins are open with usable mean residual.
        score += 30.0 + 1.5 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter-than-average bins.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // If a future item can still fit into the post-residual gap, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host the next item: potential dead space.
        score += 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Slightly prefer bins with below-average residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // New empty bin candidate: penalize mildly so it is only chosen when
    // open bins have terrible fits, scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0);
        if slack == 0.0 {
            score -= 200.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Relative to mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins looser than average.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize creating small unusable dead space (below min item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 90.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 80.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that likely cannot be reused (small odd gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * chain_fill;
        } else {
            // Next item won't fit here; slight penalty for leaving big gap.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than average residual.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - residual_f);
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize cramming into open bins less later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    // New-bin candidate: make it attractive only when fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if many items remain.
        score = 55.0 - 20.0 * progress;
        // If current item is large, new bin is natural.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If few fitting bins and lookahead is large, opening fresh is good.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: squared post-residual normalized, weighted by progress
    let tight = (pr / cap).powi(2) * (1.0 + progress);
    score += tight * cap * 0.5;

    // Penalize leaving residual close to next item's size complement mismatch
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * 0.3 * progress;
        // Reward if next item fits exactly in post residual
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless residuals are all tight
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / cap;
        let threshold = 0.35 - 0.2 * progress;
        if mean_tight < threshold {
            score += 25.0 * (threshold - mean_tight);
        } else {
            score -= 5.0 * (mean_tight - threshold);
        }
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small dead space classes
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 30 {
        score += 5.0;
    } else {
        score += 12.0; // large dead space
    }

    // Harmonic classes: post_residual divisible by common item size bands
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // residual aligns with decimal item classes -> likely reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportionally to tightness
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / pr.max(1) as f64);
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0; // harmonic divisibility: perfect future fill
            }
        } else {
            // next item won't fit here: penalize more if residual is dead space
            score += 6.0 + 0.1 * (pr as f64);
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score += 15.0; // an open bin would serve the future too
        }
    }

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Many open bins: favor filling existing ones
    if open_bins_count > 4 {
        score += if bin_residual == bin_capacity { 0.05 * open_bins_count as f64 } else { -0.05 * open_bins_count as f64 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

