    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += 10.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive to fragment.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 120.0 + (open_bins_count as f64) * 8.0 - 60.0 * progress;
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: strongly reward small post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into the post_residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here: penalize dead space relative to gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit (post_residual already does this).
        score -= 50.0;
    }

    // Relative to mean residual: bins with residual below average are
    // "small holes" — using them is good if the item fits.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight option exists. Scale penalty with stream progress (late in
    // stream, consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 200.0 * progress;
        // Exception: large items leave big residuals anyway; slightly soften
        // if item is large.
        if item_size >= 60 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 range that
    // most items (>=10) can never use.
    if post_residual >= 1 && post_residual <= 9 {
        score += 0.5 * post_residual as f64;
    }

    // Many open bins: encourage filling existing ones to limit bin sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be more willing to open new bins;
    // later, prefer filling existing bins tightly.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Perfect fit bonus: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space non-linearly; small residuals are dangerous
        // (unusable), large residuals are still somewhat usable.
        let pr = post_residual as f64;
        let dead = if pr < 10.0 { 30.0 - pr * 2.0 } else { 0.0 };
        score += dead * (0.5 + 0.5 * progress);

        // Reward tight fits relative to capacity.
        score -= 20.0 * (1.0 - pr / bin_capacity as f64) * (1.0 - pr / bin_capacity as f64);
    }

    // Lookahead: if the next item could exactly use this bin's post-residual,
    // reward heavily; if post-residual is too small for the next item,
    // penalize proportionally.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            let slack = pr - nx;
            if slack == 0.0 {
                score -= 40.0; // chains a perfect pair
            } else if slack < 10.0 {
                score += 15.0; // would create tiny dead space next step
            }
        } else {
            // post-residual can't host next item: waste grows
            score += 8.0 * (nx - pr) / nx;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have high mean
    // residual fragmentation or early in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 30.0 * fragmentation * (1.0 - progress) + 10.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // Opening bins when many are already open is wasteful late.
        score += open_bins_count as f64 * 2.0 * progress;
    }

    // Mild pressure to spread load across bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    // Encourage using bins whose residual is close to the item size.
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, modulated by smooth polynomial in progress
    let mut score = pr * (0.5 + 0.9 * progress * progress + 0.6 * (1.0 - progress) * progress);

    // Non-linear coupling: squared normalized post-residual penalizes dead space
    score += 12.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: only one bin fits, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Penalize deviation from mean residual (keeps bins balanced)
    score += 0.3 * (pr - mean_residual).abs();

    // Mild penalty for many open bins
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // New-bin candidate: neutral-ish, slightly penalized so it's chosen only when bad fits otherwise
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes
    // into "typical" item sizes (multiples of 10 dominate many streams).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit, ideal
    } else if pr % 10 == 0 {
        -12.0 // leftover aligns with decimal class, easily reusable
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward leftover class
    };
    score += harmonic_bonus;

    // Dead-space penalty: small unusable residuals are bad.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Prefer residuals that leave room for the next item,
            // reward tighter co-fit (post_residual - next) small.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // current item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // open new bin if item is big and open bins are fragmented
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        score = if big_item && fragmentation < 0.35 {
            -5.0
        } else {
            40.0 + 30.0 * (1.0 - progress)
        };
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: post_residuals that are too small to be useful later
    let min_useful = 10.0; // smallest item size
    if (post_residual as f64) < min_useful {
        score += 60.0;
    }

    // Reward tight fits strongly
    score -= 25.0 * (item_size as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // If this is a new empty bin candidate, penalize mildly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits well in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is near/below mean (avoid leaving outliers)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals too small for the smallest plausible item (1..100 unknown,
    // but tiny residuals are rarely reusable). Penalize residuals below ~10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual exactly or well.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let slack = (post - nxt).abs();
            // Next item fits: reward tight follow-up fits.
            score -= 80.0 * (1.0 - slack / post.max(1.0));
            if post_residual == next_item_size {
                score -= 500.0; // chained perfect fit
            }
        } else {
            // Next item cannot follow: penalize proportionally to the overflow gap.
            score += 0.5 * (nxt - post);
        }
    }

    // Compare against mean residual: prefer bins whose post residual stays near/below mean
    // (keeps residual distribution tight, avoids many half-empty bins).
    let post_f = post_residual as f64;
    score += 0.4 * (post_f - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Discourage opening a new bin unless the item is large relative to capacity
    // (large items are hard to place later, so a fresh bin is fine).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin when others could fit.
        score += 150.0;
        // But if item is big, opening a fresh bin is more acceptable.
        score -= 200.0 * frac * frac;
        // If many bins are open and none fit well, new bin gets less penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild progression term: later in the stream, prefer tighter packing (lower post residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_f * progress;

    // Slight preference for fuller bins overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Chain fit: post_residual fits next item with room to spare.
        if post_residual >= next_item_size + 10 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // or fits are poor, otherwise make the empty bin unattractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.55;
        if (item_size >= 70 || (poor_fit && next_item_size > post_residual)) && open_bins_count > 0 {
            score -= 10.0 + 10.0 * progress;
        } else if open_bins_count > 0 {
            score += 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            score -= 100.0; // must open first bin
        }
    }

    // Global state coupling: spread load when many bins are open with high mean residual.
    if open_bins_count > 2 {
        let mean_gap = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * mean_gap;
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Time horizon: late in stream, be conservative (favor exact fills).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr_norm.powf(1.0 + 0.8 * t) * cap;

    // Tight-fit reward: quadratic coupling of post_residual with item size
    let item_frac = item_size as f64 / cap;
    score -= 30.0 * (1.0 - pr_norm).powi(2) * item_frac;

    // Stream-progress coupling: penalize waste more strongly later in the stream
    score += 12.0 * t * pr_norm * pr_norm * cap;

    // Dead-space penalty: residual too small for typical future items
    let dead = (1.0 - pr_norm / (80.0 / cap)).clamp(0.0, 1.0);
    score += 8.0 * dead * pr_norm * (1.0 - t);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual divergence: prefer bins near the mean to preserve spread
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline with smooth pressure to reuse bins
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * t) - 6.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define
    // "dead zones" of capacity that few item sizes (10..80) can fill exactly.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.7;

    // Perfect fit is a jackpot: reward strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize heavily.
        score += 40.0;
    }

    // Integer-division thresholds on post_residual: how many standard
    // item classes (10,20,...,80) still fit.
    let fit_classes = post_residual / 10;
    score -= fit_classes as f64 * 2.5;

    // Coupling with lookahead item: does next_item_size land in a harmonic
    // class compatible with post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here exactly -> strong chaining reward.
            if next_item_size == post_residual {
                score -= 90.0;
            } else {
                let chain_post = post_residual - next_item_size;
                // Reward chains whose second post-residual is a clean class.
                score -= 25.0 + (chain_post % 10) as f64 * -0.5;
                if chain_post < 10 {
                    score += 15.0;
                }
            }
        } else {
            // Next item cannot follow here: mild penalty scaled by gap.
            let gap = next_item_size - post_residual;
            score += (gap % 20) as f64 * 0.4;
        }
    } else {
        // Last item: only exactness matters.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate (empty bin): neutralize base residual and apply
    // a fixed opening cost so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 100.0 - (post_residual as f64) * 0.3;
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If next item is huge, fresh bin keeps flexibility.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Tight bins (small residual) are precious: penalize wasting them on
    // small items when a looser bin could serve.
    if bin_residual < item_size + 10 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mean-residual coupling: when open bins are generally loose, discourage
    // fragmenting; when tight, consolidation is valuable.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use (1..10)
    // are heavily penalized, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "tight" relative to mean residual
    // (prefer filling the fullest bins first, best-fit style).
    score -= (bin_residual as f64 - mean_residual) * 0.6;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // a dead gap or when residual is very tight; otherwise penalize
    // opening a new bin.
    if bin_residual == bin_capacity {
        let dead_after = item_size < 10;
        if post_residual >= 10 && !dead_after {
            score += 30.0 + open_bins_count as f64 * 2.0;
        } else {
            score += 5.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0; // creating a gap the next item cannot use
    }

    // Early in stream, allow slightly more liberal bin opening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post > nxt {
            // next item fits; reward tighter residual coupling
            score -= 25.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // dead space: next item cannot fit here; penalize proportionally
            score += 12.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Penalize large waste relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins unattractive unless the item is huge
    // and nothing sensible can hold it.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > bin_capacity * 2 / 3 {
            score -= 40.0; // big items may justify a fresh bin
        }
        if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
            score -= 30.0; // fresh bin enables a perfect next fit
        }
    }

    // Slight late-stream tightening: prefer compact fits as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into this bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Penalize large dead space after placement (nonlinear).
    score += 0.35 * (post_residual as f64).powf(1.4);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item won't fit here anyway; slight penalty if we leave a big unusable gap.
            let gap_waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * gap_waste;
        }
    }

    // Time horizon: early in the stream, be more liberal about opening bins
    // (more future flexibility); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins when open bins fit well.
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + 8.0 * open_pressure - 15.0 * progress;
        // Opening a new bin is attractive if the item is large and would leave
        // existing bins with awkward gaps.
        if item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mildly prefer bins below mean residual (keeps balance).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Many open bins: encourage consolidation into existing bins.
        score -= 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: post-residual value modulated by stream progress
    let coupling = norm_pr * (1.0 - norm_pr) * (1.0 + progress);
    score -= 30.0 * coupling;

    // Polynomial penalty on small post-residuals (dead space), amplified late in stream
    let dead = (1.0 - norm_pr).powi(3);
    score += 25.0 * dead * (0.5 + progress);

    // Reward tight fits, stronger when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post-residual fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (pr - nxt) / cap;
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins below mean residual early, above late
    score += (mean_residual - pr) * (0.3 - 0.4 * progress);

    // New-bin candidate: penalize opening new bins unless residual is essentially empty
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - norm_pr) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (dead-space classes). Small post_residual is good.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual: bins whose leftover falls
    // into "usable" harmonic classes (can still host common small items)
    // get rewarded; true dead space gets penalized.
    let class = post_residual / 10; // 10-wide harmonic buckets
    match class {
        0 => score -= 60.0,                 // near-perfect fit (0..10 left)
        1 => score -= 40.0,                 // excellent (10..20)
        2 | 3 => score -= 20.0,             // good (20..40)
        4 | 5 => score -= 5.0,              // moderate (40..60)
        6 | 7 => score += 10.0,             // wasteful (60..80)
        _ => score += 25.0,                 // very wasteful (80+)
    }

    // Modulo coupling: does the leftover align with typical small-item sizes?
    // If post_residual mod common sizes is 0, a future small item fits exactly.
    for m in [10u32, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let new_res = post_residual - next_item_size;
            score -= 15.0 + (new_res as f64).min(20.0) * 0.5;
        } else {
            // Next item cannot follow in this bin: penalize if we "waste" space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Only prefer a fresh bin when all existing fits are poor and the
        // item is large relative to capacity.
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.6 && mean_residual < item_size as f64 {
            score -= 10.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - item_frac);
        }
    }

    // Progress-based mild pressure: later in the stream, tighten packing
    // (prefer filling existing bins rather than spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 30.0 * progress;

    // Prefer bins with residual close to the item (tight fit reward).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it cannot hold any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    }

    // Moderate gaps: penalize proportionally more if next item can't use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap is reusable by lookahead item: reward.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: penalize spreading across many open bins slightly,
    // encouraging consolidation into tighter bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with below-mean residual (tighter bins) to keep big gaps free.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: default mild penalty so open bins are used,
    // but allow opening a new bin when remaining gaps would be dead space.
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual < 10 {
            score += 500.0; // never open a bin that immediately dead-ends
        } else if next_item_size > 0 && next_item_size > bin_residual && bin_residual < 40 && fitting_bins_count > 0 {
            // Opening a new bin is reasonable when all fitting bins would leave bad gaps
            score -= 120.0;
        } else {
            score += 80.0;
        }
    }

    // Slight preference to fill earlier-opened (tighter) bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: does next item fit into the post residual?
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            // Perfect 2-chain: place item, next item exactly fills the rest
            score -= 300.0;
        } else if gap > 0 {
            // Next item fits: reward proportionally to how tight the fit is
            let tightness = 1.0 - (gap as f64 / post_residual as f64);
            score -= 150.0 * tightness;
        } else {
            // Next item does NOT fit: penalize dead space left behind
            let dead = (-gap) as f64;
            score += 0.5 * dead;
            // Small items left as dead space are worse
            if dead < 10.0 {
                score += 40.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild preference for using existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Progression-aware: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small residuals that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward if next item fits into the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * next_fit;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 3.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large relative to mean residual state, or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items, late in stream, or when open bins are mostly full.
        let open_bias = (open_bins_count as f64 / 20.0).min(1.0);
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        let new_bin_urge = big_item * (0.5 + 0.5 * progress) + 0.3 * fullness + 0.2 * open_bias;
        score += 25.0 - 25.0 * new_bin_urge.min(1.0);
        // A fresh bin wastes nothing now; baseline small score so it wins only when urged.
        score = score.min(24.0);
    }

    // Global state coupling: when mean residual is low, preserve large-residual bins
    // for future large items; penalize consuming big residual with small items.
    let waste = (bin_residual as f64 - item_size as f64) - mean_residual;
    if waste > 0.0 {
        score += 0.05 * waste;
    } else {
        score -= 0.05 * (-waste);
    }

    // Mild diversity pressure: many open bins -> prefer consolidating into fullest bins.
    score += 0.1 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let n2 = norm_pr * norm_pr;
    let n3 = n2 * norm_pr;

    let mut score = pr * (0.6 + 0.5 * progress) - pr * pr / (2.0 * cap) + pr * p2 * 8.0 + n3 * 40.0 * (1.0 - progress);

    // Penalize residuals that cannot fit the next item (lookahead waste)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx).abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.8 * (0.5 + p2);

    // Deviation from mean residual: prefer typical fills
    score += ((pr - mean_residual) / cap).abs() * 10.0 * (1.0 - p3);

    // New-bin candidate handling: empty bin gets a calibrated baseline
    if bin_residual == bin_capacity {
        score = 95.0 - 25.0 * progress - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // allow new bin when nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 classify "perfect fit" zones.
    let residue_class = post_residual % 10;
    if post_residual == 0 {
        score -= 200.0; // perfect closure: best possible outcome
    } else if residue_class == 0 {
        score -= 40.0; // residual is a multiple of 10 -> highly reusable by typical item sizes
    } else if residue_class >= 7 {
        score += 25.0; // awkward sliver: 7..9 units of dead space
    }

    // Integer-division thresholds: how many items of the lookahead size could still fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = (post_residual / next_item_size) as f64;
        score -= 12.0 * fits_next;
    } else if next_item_size > 0 {
        // Lookahead cannot land here; penalize proportionally to how close we came.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Capacity fraction coupling: reward bins whose fill fraction is in the "high" harmonic band.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let band = (fill_frac * 4.0).floor(); // quarters of capacity
    score -= match band as u32 {
        3 => 30.0,
        2 => 12.0,
        1 => 0.0,
        _ => 6.0,
    };

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when plenty of fitting bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But allow a fresh bin if the item would leave an ugly remainder everywhere:
        if post_residual > 0 && post_residual % 10 >= 7 {
            score -= 35.0;
        }
    }

    // Stream progression: early on, be conservative with tight fits; later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Mean-residual coupling: if mean residual is large, prefer consolidating into existing bins.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // near-zero gaps are worst
    }

    // Reward very tight fits (post_residual near 0 or exactly 0 is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 2.0;
    }

    // Penalize large leftover gaps that waste capacity (dead space hoarding).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.6;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (especially last-chance bins) over opening new ones.
    score += open_bins_count as f64 * 1.5;

    if fitting_bins_count == 1 {
        score -= 20.0; // this is the only bin that fits: strong preference
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: this bin may become dead space
        score += 8.0;
    }

    // Mild stream progression: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins whose residual is below average (tighter bins close out faster).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post-residual exactly fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack); // tight match for next item strongly favored
        // chain bonus: next item also leaves room for a third hypothetical (size ~ mean residual)
        if slack >= 10.0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        score += (next_item_size as f64) * 0.15;
    }

    // Tight fit now: small post_residual is good
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when item is large or residuals are fragmented
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * bin_capacity as f64;
        if large {
            score -= 10.0;
        } else {
            score += 40.0 + mean_residual * 0.3;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize large unusable dead space: if post_residual is small but positive,
    // it's fine; if it is moderate (hard to fill later), penalize.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste > 0.25 {
            score += 10.0 * (waste - 0.25);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // This bin becomes dead space for the next item; slight penalty unless it's a near-perfect fit now.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else or open bins are already crowded.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its score is essentially its post_residual.
        // Slightly discourage opening new bins when good fits exist.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            let avg_fit = mean_residual / open_bins_count.max(1) as f64;
            if avg_fit >= item_size as f64 {
                score += 8.0;
            }
        }
        // Early in the stream, prefer consolidating; later, allow more bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score += 6.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidation strategy):
    // bins with less space than average get priority for fitting.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: quadratic polynomial in normalized post residual.
    let mut score = 4.0 * x * (1.0 - x); // concave, peaks at x=0.5 (bad: half-empty bin)

    // Smooth cubic coupling with stream progress: late in the stream,
    // prefer tight fits more aggressively (penalize residual super-linearly).
    let late = progress * progress;
    score += late * (x * x * x) * cap * 0.05;

    // Early stream: tolerate loose fits slightly (exploration of bins).
    score -= (1.0 - progress) * x * 0.5;

    // Dead-space penalty: post residual too small to ever fit typical items.
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * 3.0;

    // Lookahead: reward residual that can still fit the next item.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 2.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * x * 0.3;

    // Mean residual coupling: if this bin's residual is below average, it's tighter -> favor.
    score -= (mean_residual - pr) / cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity/4
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let pr = post_residual;

    // Dead-space penalty for very small residuals (unusable slivers)
    if pr > 0 && pr < quarter / 2 {
        score += 12.0;
    }

    // Reward exact-fill classes: residual divisible by 25 (harmonic of capacity)
    if pr % 25 == 0 {
        score -= 6.0;
    }
    // Reward residuals that are multiples of 10 (common item granularity)
    if pr % 10 == 0 {
        score -= 3.0;
    }
    // Penalize awkward odd residuals
    if pr % 2 == 1 {
        score += 1.5;
    }

    // Integer-division thresholds on post_residual
    let pr_class = pr / quarter; // 0..4
    match pr_class {
        0 => score -= 4.0,           // near-full bin: excellent
        1 => score += 0.0,           // 25-49 left: neutral
        2 => score -= 1.0,           // 50-74: decent
        _ => score += 2.0,           // mostly empty: wasteful
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward good match: next item slots in snugly
            let slack = pr - next_item_size;
            if slack <= quarter / 2 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
            // harmonic class match: both multiples of 10
            if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: penalize unless post residual tiny
            score += 4.0;
            if pr < quarter / 2 {
                score -= 6.0; // but a tiny residual is fine since nothing fits anyway
            }
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin required
        } else if fitting_bins_count == 1 {
            score -= 10.0; // weak alternative exists
        }
        // Early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild open-bins pressure
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest possible item (1) but awkwardly small relative to
    // typical item sizes are "dead space". Penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead gap: nothing can ever use it
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit: eliminate dead space entirely
    }

    // Penalize post_residual that cannot fit the lookahead item while a
    // slightly larger gap could: prefer bins whose remainder stays useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // gap remains usable for the next item
        } else if bin_residual >= next_item_size {
            score += 12.0; // this placement kills the only bin that fits next item
        }
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones; penalize the new-bin
    // candidate (bin_residual == bin_capacity) more heavily as open_bins grows.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count.min(20)) as f64 * 0.5;
    }

    // Prefer bins whose residual is below the mean (denser bins first),
    // keeping the spread of residuals tight.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * fit_ratio;

    // 2-step lookahead: if the next item fits exactly in post_residual,
    // this bin is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: mild reward proportional to tightness.
            let nxt_fit = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 60.0 * nxt_fit;
        } else {
            // Next item cannot use post_residual: dead space risk, penalize
            // proportionally to how much space would be stranded.
            let stranded = post_residual as f64;
            score += 0.35 * stranded;
            // Extra penalty if stranded space is just below next item (near-miss).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0 * (1.0 - gap / 10.0);
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: bins with residual far below mean are
    // "cramped"; placing here preserves larger residual bins for future items.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless current fits are terrible
    // (large post_residual waste) or stream is nearly empty of open bins.
    if bin_residual == bin_capacity {
        let waste_penalty = 25.0 + 0.8 * (post_residual as f64);
        score += waste_penalty;
        // Early stream: slightly prefer consolidating into few bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin anyway
        }
    }

    // Mild preference to keep number of open bins low when few bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical items (1..=100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 50 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0 * (next_item_size - post_residual as u32) as f64 / 100.0;
        }
    }

    // New-bin candidate handling: only prefer opening a new bin when the current bin
    // fit is poor and there is slack in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.6;
        if poor_fit && open_bins_count > 0 {
            score -= 10.0 + 15.0 * (1.0 - progress);
        } else {
            score += 18.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild preference for placing into bins among many open bins (reduce bin count pressure).
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Quadratic dead-space penalty: small post-residuals are good, large ones bad.
    score += 40.0 * pr_norm * pr_norm * cap;

    // Smooth cubic coupling with stream progress: late in the stream, tolerate tight fits more.
    score -= 25.0 * pr_norm * pr_norm * pr_norm * cap * progress;

    // Reward tight fits (small post_residual relative to item size) smoothly.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus: smooth sigmoid-like term on fitting_bins_count.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates from mean residual (fragmentation balancing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 20.0 * (1.0 - fit_gap).max(0.0) * (1.0 - fit_gap).max(0.0);
        // Penalize post_residual that is too small for the next item (smooth soft barrier).
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for bin proliferation: prefer filling existing bins.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make empty bin score neutral-high so it's chosen only when open bins are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty: residuals that are unusable (small but nonzero) are bad.
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Perfect fit reward via modulo classes on post_residual.
    if post_residual == 0 {
        score -= 200.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0; // residual aligned to typical item granularity
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..=10
    score -= (class as f64) * 4.0;  // larger usable residual is better

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // Harmonic bonus if next item fits leaving an aligned residual again
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 {
                score -= 15.0;
            }
            if r2 == 0 {
                score -= 60.0;
            }
        } else {
            score += 30.0; // next item won't fit here; penalize unless last-chance
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; make it slightly unattractive unless
        // the alternative residuals would be dead space (handled by penalties above).
        score += 12.0 - frac * 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln() * 2.0;

    // Progress-aware tightness: later in stream, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * progress * 30.0;

    // Deviation from mean residual: prefer bins near/below mean to balance.
    score += ((post - mean_residual) / cap).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..=10 range, conservatively < 12) are almost unusable dead space.
    if post_residual < 12 {
        score += 60.0; // heavy penalty for creating tiny unusable gaps
    } else if post_residual <= 25 {
        // Small gaps only fit small items; penalize proportionally.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (waste minimization) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // New-bin candidate: only attractive when this bin would leave a bad gap
    // or when the item fits poorly everywhere; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual < 12) as i32 as f64;
        let no_alternative = (fitting_bins_count == 1) as i32 as f64;
        score += 45.0 - 50.0 * bad_fit - 20.0 * no_alternative;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward leaving that gap; if next item is large and gap is small, penalize.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0; // perfect chaining
        } else if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score += 8.0; // gap likely dead for the next item too
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate waste into few bins rather than spreading it).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // Late in the stream, be conservative: prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post-residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Perfect chain: next item exactly fills the remaining space.
            let gap = pr - nxt;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // Small residual left after the chain is wasted space; penalize tiny leftovers.
            if gap > 0.0 && gap < 10.0 {
                score += 25.0 * (1.0 - gap / 10.0);
            }
        } else if pr == 0.0 {
            // Bin perfectly closed now — excellent.
            score -= 60.0;
        } else {
            // Next item cannot use this residual: dead space until future items.
            let dead = pr;
            score += 0.15 * dead;
        }
    } else {
        // Last item: strongly prefer exact closure.
        if post_residual == 0 {
            score -= 80.0;
        }
    }

    // Compare residual against the mean residual of open bins:
    // prefer bins that are already "low" (well filled) to consolidate waste.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.3 * ((post_residual as f64) - mr);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = open_bins_count as f64;
        // Penalize new bins when many open bins exist (prefer consolidation),
        // unless the item is huge (near-full utilization potential).
        let large_item = (item_size as f64) / bin_capacity as f64;
        score += 15.0 + 2.0 * tightness - 40.0 * large_item;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space quadratically (unusable gaps).
    score += 0.015 * (post_residual as f64).powi(2);

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward if next item fits almost exactly too.
            let next_gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - next_gap as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use.
            score += 0.25 * next_item_size as f64 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // (large post_residual everywhere) or many bins are open (fragmentation).
    if bin_residual == bin_capacity {
        let waste_of_best_open = if fitting_bins_count > 0 { 0.0 } else { 60.0 };
        let fragmentation = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score = 100.0
            - waste_of_best_open
            - 8.0 * fragmentation
            - 5.0 * (mean_residual / bin_capacity as f64).max(0.0);
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for fuller bins when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly discounted early (bins stay flexible)
    let mut score = pr * (1.0 - 0.25 * (1.0 - progress));

    // Non-linear polynomial coupling of residual with progress
    let poly = norm_pr * norm_pr * (3.0 - 2.0 * progress) + norm_pr * (1.0 - norm_pr) * progress;
    score += 40.0 * poly;

    // Reward near-perfect fits with smooth cubic falloff
    let fit = 1.0 - norm_pr;
    score -= 25.0 * fit * fit * fit * (1.0 + progress);

    // Lookahead: penalize if next item cannot use this residual
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // Reward if next item fits well in the post-residual
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (1.0 - ((pr - next_item_size as f64) / cap));
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean residual coupling: penalize bins far from the fleet mean
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Many open bins: prefer consolidating (tighter fits)
    score += 3.0 * open_bins_count as f64 * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: post_residual too small to fit typical small items (1..=10 min).
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill, strongly reward
    } else {
        // Harmonic class of post_residual: which standard item classes can still fit?
        let class = (post_residual / 10).min(10) as f64; // 0..10 decile of capacity
        score += class * 4.0;

        // Non-linear: penalize residuals in awkward middle zone (30..60) — hard to fill later.
        if post_residual >= 30 && post_residual <= 60 {
            score += 12.0 * (1.0 - ((post_residual as f64 - 45.0).abs() / 15.0));
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 100.0); // tight fit for next item rewarded
        } else {
            // next item won't fit here: mild penalty, worse if this bin was the only option
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline tied to fill fraction achieved.
    if bin_residual == bin_capacity {
        // Opening new bin: prefer when current item is large (less waste risk later)
        score = bin_capacity as f64 - item_size as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        // Late in stream, consolidate rather than open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Modulo-arithmetic harmonic bonus: post_residual divisible by common item sizes
    // (10,20,25,50) means future items can tile it perfectly.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier-relative bins tight)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure against bin sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps are residuals too small for
    // the smallest plausible future item. Penalize them hard.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Slightly favor tight fits (small positive post_residual) beyond raw value.
    if post_residual > 0 {
        score -= 3.0 * (1.0 - (post_residual as f64) / 40.0).min(1.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins; penalize the new-bin candidate implicitly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // the item fits poorly everywhere else; make it moderately costly.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and this bin would be nearly full after,
        // a fresh bin keeps flexibility — soften the penalty.
        if next_item_size > 60 && post_residual < 20 {
            score -= 12.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) == post_residual {
        score -= 12.0;
    }
    // If next item cannot fit post_residual but would fit a fresh bin, mildly
    // penalize leaving a bin that strands the lookahead.
    if next_item_size > post_residual && post_residual < 10 {
        score += 4.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: penalize opening a new bin unless
    // no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, opening fresh bins is fine.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 20.0;
        }
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect two-step fit: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Near-perfect two-step fit.
        let gap = if post_residual > next_item_size { post_residual - next_item_size } else { next_item_size - post_residual };
        if gap <= 3 {
            score -= 18.0 - gap as f64 * 4.0;
        }
        // Penalize residuals that cannot fit the next item (dead space
        // relative to lookahead).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits in general (small post_residual is good, but
    // only if it's not a lookahead mismatch, handled above).
    score -= 0.15 * (bin_residual as f64 - post_residual as f64);

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small unusable leftovers (dead space < 10).
    if post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        let waste = post_residual as f64;
        score += 0.08 * waste * waste / (bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves residual; mild reward scaled by snugness.
            let snug = (post_residual - next_item_size) as f64;
            score -= 150.0 - 0.5 * snug;
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.4 * overshoot;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer bins with residual below the mean (consolidate fuller bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening new bins early when open bins can fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus a term growing with open bins able to fit.
        score += 120.0 + 15.0 * (fitting_bins_count as f64);
        // Later in the stream, be more willing to open new bins (avoid overpacking chaos).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty
    let mut score = pr * pr / cap;

    // Smooth interaction of post_residual with stream progress:
    // early on, keep bins flexible; later, tolerate tight fits (low post_residual)
    let progress_tilt = progress * norm_pr * cap * 0.5;
    score += progress_tilt;

    // Non-linear reward for tight fit (small post_residual), stronger later in stream
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bonus: only fitting bin -> strong reward, scaled by fit quality
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize bins deviating from mean residual (prefer balanced residuals), smooth coupling
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 8.0;

    // Lookahead: reward if next item fits into post_residual (smooth affinity)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 4.0 * norm_pr;
    }

    // New-bin candidate: penalize unless it is a perfect fit (post_residual == 0)
    if bin_residual == bin_capacity {
        score += 60.0 - 60.0 * (1.0 - norm_pr).powi(2);
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit reward: prefer tight packing.
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Harmonic class of post_residual: waste buckets by modulo classes of capacity fractions.
    let cap = bin_capacity as u32;
    let quarter = cap / 4;   // 25
    let fifth = cap / 5;     // 20
    let tenth = cap / 10;    // 10

    // Dead-space penalties: residual in "unusable" harmonic zones gets punished.
    if post_residual > 0 {
        if post_residual < tenth {
            score += 30.0; // tiny sliver, nearly dead space
        } else if post_residual <= quarter {
            score += 12.0; // small but possibly fillable by min-size items
        } else if post_residual <= 2 * fifth {
            score -= 5.0;  // sweet spot: can host a mid-size item
        }
    }

    // Perfect harmonic fit bonus: post_residual divisible by 10 or 20 -> likely reusable.
    if post_residual % tenth == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % fifth == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 - 0.15 * slack as f64; // reward exact lookahead fit
        if slack % tenth == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        score += 4.0; // lookahead cannot use this bin's remainder
    }

    // Last-chance pressure: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: fresh empty bin should only win when alternatives are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by stream progression and crowding.
        score += 20.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pair large items into fresh bins
        }
    }

    // Mild preference for balancing residuals across open bins.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are pure waste.
    let min_item = 1u32;
    let look = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < look && post_residual > 0 {
        // Unusable gap for the next item: heavy penalty scaled by how close it is to being useless.
        let waste = (look - post_residual) as f64;
        score += waste * 4.0;
        if post_residual < 10 {
            score += 30.0; // near-total dead space
        }
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    }

    // Reward tight fits relative to capacity (small post_residual fraction).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.5;

    // Mean-residual coupling: if this bin's residual is far below mean, it's already fragmented.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and diversity of bins is valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a decent fit.
        score = bin_capacity as f64 * 0.55;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 15.0;
        // But if the item leaves a good gap for the known next item in a new bin, mild bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Reward leaving room for the lookahead item in an existing bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize bins whose residual is excessively large relative to item (poor consolidation target).
        if bin_residual > item_size * 3 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/tight fits: small post_residual is good.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2);

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // heavily reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward if next item fits with small slack afterwards.
            let after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 10.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is large and this item is small, new bin may be fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let has_lookahead = next_item_size > 0;

    // Lookahead coupling: reward bins whose leftover can host the next item,
    // penalize bins that strand dead space unusable by the next item.
    if has_lookahead && !is_new_bin {
        if next_item_size <= post_residual {
            // leftover stays useful: reward proportional to how well next item fits
            let next_waste = post_residual - next_item_size;
            score -= 12.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // dead space: penalize small unusable leftovers harder
            let waste = post_residual as f64;
            score += 3.0 + 0.15 * waste * (1.0 + progress);
        }
    }

    // Tight fit reward: near-zero post residual is ideal (unless it's dead space)
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Global fragmentation pressure: when many bins are open and mean residual
    // is low, discourage opening new bins / spreading items.
    if !is_new_bin {
        score -= 0.5 * mean_residual / (open_bins_count.max(1) as f64);
    } else {
        // New bin baseline: competitive only when open bins are nearly full
        let avg_open_residual = mean_residual;
        let pressure = (bin_capacity as f64 - avg_open_residual) / bin_capacity as f64;
        // higher pressure (open bins full) => lower score for new bin
        score = bin_capacity as f64 - 25.0 * pressure - (1.0 - progress) * 5.0;
        if has_lookahead {
            // a fresh bin always fits the next item
            score -= 6.0;
        }
        if fitting_bins_count <= 1 {
            // no real alternative: new bin is fine
            score -= 15.0;
        } else {
            // good alternatives exist: discourage opening new bin
            score += 10.0 + 2.0 * fitting_bins_count as f64;
        }
    }

    // Late-stream conservatism: squeeze existing bins harder near the end.
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Smooth progress-modulated quadratic term: penalize large residuals late, less early
    let poly = x * x * (1.0 - progress) + x * (1.0 + progress);
    score += poly * cap * 0.5;

    // Reward tight fits (small post_residual) with smooth cubic discount
    let tight = (1.0 - x).powf(3.0);
    score -= tight * cap * (0.6 + 0.4 * progress);

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        // Perfect lookahead fit bonus (smooth gaussian-like)
        score -= (-6.0 * gap * gap).exp() * cap * 0.5 * (1.0 - progress);
        // Penalize wasted space that next item cannot use
        if gap < 0.0 {
            score += (-gap) * cap * 0.4;
        }
    }

    // Last-chance bin: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= cap as f64 * (0.5 + 0.5 * progress);
    }

    // Mean-residual deviation coupling (smooth)
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * cap * 0.3;

    // Mild penalty for opening new bins when many are open
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if new_bin {
        score += cap * (0.2 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division (capacity fraction thresholds).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 12) as f64; // 12-unit harmonic bins (100/12 ~ 8 classes)
    score += class * 3.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // leftover in the awkward band (small but not tiny) is wasted.
    if post_residual > 10 && post_residual < 25 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic alignment: next item leaves another clean class
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; slightly penalize leaving big gaps
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when the fit into open bins would leave large dead space, or
    // when open bins are already crowded (high mean residual usage).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score -= 5.0;
        // more attractive if existing bins are tight on average
        score -= (cap - mean_residual) * 0.3;
        // less attractive early in the stream when consolidation is easy
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 10.0;
        // if the item would fit an open bin with small leftover, discourage new bin
        if item_size <= bin_capacity && item_size >= 90 {
            score += 30.0;
        }
    }

    // Mild penalty for spreading across many open bins: encourage packing
    // into fewer bins when item is large relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Modulo-flavored tiebreak: prefer post_residuals that are multiples
    // of common item sizes (harmonic divisibility).
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 9.0; // gaps below the smallest item (size 1..100, small gaps are waste-prone)
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize moderately large post-residuals that no typical item can use well.
    if post_residual > 50 {
        score += 0.5 * (post_residual as f64 - 50.0);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0 || (post_residual > 0 && (post_residual as f64) < dead_threshold);
        if poor_fit {
            score -= 45.0; // prefer a fresh bin over a wasteful placement
        } else {
            score += 20.0; // keep using open bins when the fit is decent
        }
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced filling).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack: good lookahead fit.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the leftover: penalize dead space relative to mean.
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0 + 0.5 * (mean_residual - post_residual as f64).abs();
    }

    // Penalize unusable dead space (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-ish, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item can't use remaining space; penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Prefer fuller bins when many bins are open (contain fragmentation).
    let openness = open_bins_count as f64 / (1.0 + total_items as f64);
    score += fit_ratio * openness * 50.0;

    // Prefer bins below mean residual (encourage balancing toward fuller bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    // Early in the stream, be more willing to open bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large relative to capacity
        // or nothing fits well.
        let large_item = item_size as f64 / bin_capacity as f64;
        score = post_residual as f64 - large_item * 20.0 + (1.0 - progress) * 5.0;
        if fitting_bins_count > 0 && fit_ratio < 0.2 {
            score += 60.0; // existing bin fits well; don't open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = (pr - 0.5).powi(2) * 4.0;          // penalize extremes of leftover space
    let skew = (pr * progress).powi(3) * 2.0;     // smooth cubic interaction over time
    let wave = (pr * std::f64::consts::PI).sin() * (1.0 - progress) * 0.5;

    let mut score = base + skew - wave;

    // Favor tight fits: reward small post_residual smoothly
    score += pr * 1.5;
    score -= (item_size as f64 / cap).powi(2) * 0.8;

    // Last-chance bonus: strong reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 2.0 * ((nxt - post) / cap);
        } else {
            score -= 1.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Prefer bins with below-mean residual (concentrate waste), smoothed
    score += (bin_residual as f64 - mean_residual) / cap * 0.4;

    // Mild preference for keeping open bin count low late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.1 * progress;

    // New-bin candidate: neutral-ish baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 1.2 + pr * 2.0 - progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 classify "dead space quality".
    let residue_class = post_residual % 10;
    // Perfect fits (residue 0) are highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if residue_class == 0 {
        score -= 30.0; // round residual, likely reusable by future items
    } else if residue_class >= 5 {
        score += 5.0 + (residue_class as f64 - 5.0);
    } else {
        score += 10.0 - residue_class as f64; // small awkward residues penalized
    }

    // Integer-division thresholds: residual divided into item-size-sized slots.
    let slots = if item_size > 0 { post_residual / item_size } else { 0 };
    score -= slots as f64 * 8.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (next_item_size as f64) * 0.2;
        } else {
            // next item won't fit here; penalize wasted capacity but reward tight fills
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic pair: item + next_item exactly divides capacity
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fills are bad.
    if bin_residual == bin_capacity {
        score += 120.0
            - (fitting_bins_count as f64) * 5.0
            + mean_residual * 0.3;
        if post_residual == bin_capacity {
            // empty-bin call: keep it competitive only if stream is early
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 100.0 * (1.0 - progress);
        }
    }

    // Favor bins below mean residual (tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Small nudge toward using more of the bin early in the stream.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: residuals below the minimum item size are worthless
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space relative to smallest plausible item (1..100 unknown dist): use graded penalty
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += (100.0 - dead) * 0.05;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave a tiny gap, penalize
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 5 {
        score += 20.0;
    }

    // New bin candidate: make it mildly unattractive unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Prefer bins whose residual is close to item (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Mean residual coupling: when mean residual is high, discourage wasting space
    score += dead * (mean_residual / 100.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        if post_residual < 10 {
            score += 50.0 * (10 - post_residual) as f64;
        }
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: strong bonus for tight chain.
            score -= 80.0 - 1.5 * gap;
        } else {
            // Next item won't fit in this bin after placement: mild penalty
            // proportional to leftover dead space.
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when the current bin would
    // leave a very poor fit (large post_residual) or the fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if the item is large
        // (large items are hard to place later, so a fresh bin helps).
        let mut nb = 120.0 - 0.5 * item_size as f64;
        // If lookahead chains nicely into a fresh bin, discount more.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 5 {
            nb -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 40.0 * progress;
        score = score.max(nb.min(score)) + nb - score.max(nb.min(score)); // keep nb comparable
        score += nb;
        score -= 0.0; // no-op guard
        score = score - nb + nb; // neutralize double counting
        score += nb;
        score -= 2.0 * nb;
        score += nb; // final: score includes nb once
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; if post_residual is large, this is wasted potential.
            let waste = post_residual as f64 - fit_ratio * 0.0;
            score += waste * 0.05;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and open bins have scattered residuals.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins mildly; more when few bins open or item is small.
        score += 20.0 + 0.3 * item_size as f64 * (1.0 - progress) - fragmentation * 0.1;
        if item_size >= 60 {
            score -= 18.0; // large items pair well with fresh bins
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit shaping).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.15;

        // Prefer bins below mean residual (consolidate emptiness).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild pressure to use many open bins when count is high (avoid sprawl).
    score += open_bins_count as f64 * 0.05;

    // Dynamic time horizon: early in stream, encourage tight packing;
    // late in stream, tolerate slack to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: residual left behind (lower is tighter fit).
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic decay of residual scaled by capacity.
    score -= 2.5 * (1.0 - (pr / cap).powi(2));

    // Cubic penalty for small unusable dead space (residual too small for typical items).
    let dead = (1.0 - pr / cap).max(0.0);
    score += 1.2 * (pr / cap) * (1.0 - pr / cap) * (1.0 + dead);

    // Stream progress coupling: later in stream, favor tighter packing more strongly.
    score *= 1.0 + 0.6 * progress * (pr / cap);

    // Lookahead: if next item fits into post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (next_item_size as f64 / cap) * (1.0 + progress);
    }
    // If next item almost fits (within small gap), mild penalty for wasting the chance.
    if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 10.0 {
        score += 0.5 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // New empty bin candidate: penalize opening a new bin unless it's early
    // or all existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let avg_gap = (mean_residual - pr).max(0.0);
        score = cap * (0.9 + 0.3 * progress) + 2.0 * open_bins_count as f64 * (1.0 - progress)
            - 1.5 * avg_gap / cap;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, must open
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean (fragmentation).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets by modulo of capacity fractions.
    let pr = post_residual;
    // Perfect fit classes: residual exactly 0, or small harmonics (<=5) are great.
    if pr == 0 {
        score -= 200.0;
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 40.0;
    }

    // Dead-space harmonic: residuals in (10, 20) are wasteful — smallest items are 10
    // (interface note allows 1..100, so use modulo classes instead).
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if pr > 0 && pr < quarter {
        // penalize small-but-unusable gaps, scaled by how far from a harmonic multiple
        let m = pr % (quarter / 5).max(1);
        score += 30.0 + m as f64;
    }

    // Modulo class of post_residual w.r.t. 10 (classic harmonic granularity)
    let mod10 = pr % 10;
    score += mod10 as f64 * 2.5; // prefer residuals that are multiples of 10

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 60.0 - slack.min(60) as f64; // reward close lookahead fits
            // harmonic match: next_item_size divides post_residual evenly
            if pr % next_item_size.max(1) == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: penalize leaving a gap smaller than next item
            if pr < next_item_size {
                score += (next_item_size - pr) as f64 * 0.8;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins with good fits, but bonus if open bins are tight.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 2.0;
        // if mean residual is large, reusing is easy; keep new-bin penalty
        score += mean_residual * 0.1;
    }

    // Progress-based mild pressure to close bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Prefer bins with residual close to item size (tight fit) via ratio term.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        score -= ratio * 20.0;
    }

    // Tie-break: prefer bins whose residual is above mean (keep tight bins for later).
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the smallest possible
    // item are pure waste; penalize them extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for typical mid-size items are semi-dead.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Exact fit is gold: reward heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits proportionally to how full the bin becomes.
        let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // If lookahead item could exactly use the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual - next_item_size < 10 {
            score += 8.0; // would leave another dead gap
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // lookahead cannot fit here; mild penalty since bin will likely close
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; slightly attractive when
        // item is large and current fit would be wasteful.
        score += 15.0 + 8.0 * pressure - 10.0 * (item_size as f64 / bin_capacity as f64);
        // Discourage opening a new bin when an existing bin gives a tight fit
        // (post_residual small) — handled implicitly since those scores are low.
    } else {
        score -= 4.0 * pressure; // favor reusing open bins under pressure
    }

    // Late in the stream, dead space matters more (less chance to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (low dead space) non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 60.0;
        } else if nxt <= pr {
            // next item fits: reward proportionally to how well it fills remainder
            let fill = nxt / pr.max(1.0);
            score -= 25.0 * fill;
        } else {
            // next item cannot use the remainder: penalize dead space
            let gap = (pr - nxt).abs();
            score += 0.25 * gap;
        }
        // If next item won't fit anywhere else well, prefer conserving big residuals
        if nxt > pr && pr < mean_residual {
            score += 10.0;
        }
    }

    // Relative-to-mean residual coupling: bins below mean residual are more "used up";
    // prefer packing into them to consolidate space.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the current
    // item is large or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / cap;
        // Penalize opening new bins mildly; more late in stream or for small items
        let penalty = 12.0 + 20.0 * (1.0 - large_item) + 10.0 * progress;
        // But if no open bin fits well (post_residual large relative to item), allow it
        let poor_fit = (pr as f64) > 0.6 * cap;
        if poor_fit {
            score -= 18.0;
        }
        score += penalty;
        // If next item is small, a fresh bin can chain two items
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild consolidation pressure: fewer open bins is better; discourage spreading.
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind, nonlinearly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead * dead) / bin_capacity as f64;
    }

    // Perfect fit: huge bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Small residual bins are precious: penalize wasting a nearly-full bin on a small item.
    if bin_residual <= 30 && item_size < bin_residual {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into this bin's post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * chain;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Competition: mild penalty to keep exploration of alternatives.
        score += 3.0 * (fitting_bins_count as f64).min(8.0);
    }

    // Global state: many open bins with high mean residual → prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    }

    // New bin candidate: penalize opening a new bin, more so early and when alternatives exist.
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        // Early stream: opening bins is cheap-ish; late stream: consolidate.
        penalty *= 1.2 - 0.7 * progress;
        // If other bins fit, discourage new bin more.
        if fitting_bins_count > 0 {
            penalty += 15.0;
        }
        // If next item is large and this item is small, a fresh bin may be useful.
        if next_item_size > 60 && item_size < 30 {
            penalty -= 20.0;
        }
        score += penalty.max(0.0);
    }

    // Time horizon: as the stream ends, avoid leaving scattered tiny residuals.
    if progress > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let item_n = item_size as f64 / cap;
    let mean_n = mean_residual / cap;

    // Base: prefer low post residual (tight fit), with non-linear shaping
    let mut score = r;

    // Smooth non-linear coupling of tightness with stream progress:
    // early on, keep bins flexible (mild penalty for very tight fits);
    // later, reward tight fits more aggressively.
    let tightness = 1.0 - rn * rn; // in [0,1], high when residual small
    score -= 40.0 * tightness * (0.5 + progress);

    // Penalize large unusable residuals relative to typical item sizes
    let dead = (rn - item_n).max(0.0);
    score += 25.0 * dead * dead * cap;

    // Lookahead: reward residual that can still fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = 1.0 - ((rn - nxt) / cap).abs().min(1.0);
        score -= 12.0 * fit_next * fit_next * (1.0 - progress);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Fragmentation pressure: many open bins with high mean residual
    let frag = (open_bins_count as f64).ln() * mean_n;
    score += 8.0 * frag * (0.3 + 0.7 * progress);

    // Mild pull toward bins whose residual is near mean (keep balance)
    score += 6.0 * (rn - mean_n).abs() * (1.0 - progress);

    // Smooth non-linear progress term modulating overall residual weight
    score *= 1.0 + 0.15 * (progress - 0.5) * (progress - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and capacity fractions
    let r = post_residual;
    let residue = (r % 10) as f64;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward residuals that fall into "harmonic" classes likely reusable
    // (exact multiples of common item-size buckets: 0, 10, 20, 25, 50)
    if r == 0 {
        score -= 60.0; // perfect fit
    } else if r % 25 == 0 {
        score -= 25.0;
    } else if r % 10 == 0 {
        score -= 15.0;
    } else if r <= 10 {
        // dead space below minimum item size is nearly wasted
        score += 40.0;
    } else if r < quarter {
        score += 20.0 - residue; // small awkward residual
    } else if r >= half {
        score -= 10.0; // large residual still flexible
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 18.0 + (next_item_size as f64) * 0.15;
            // extra bonus if next item exactly fills or harmonically divides residual
            if r % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is unusable
            score += (next_item_size - r) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately attractive only when
    // open-bin residuals are low on average.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).sqrt();
        let mean_gap = (mean_residual - r as f64).abs();
        score -= 8.0 - openness.min(6.0) + mean_gap * 0.1;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Mild tie-break: prefer bins whose residual is closest to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 12.0;

    // Small pressure toward fewer open bins when many are open
    score += (open_bins_count as f64) * 0.05;

    // Integer-division threshold on post_residual quartiles
    let q = r / quarter.max(1);
    score -= match q {
        0 => 0.0,
        1 => 3.0,
        2 => 6.0,
        3 => 9.0,
        _ => 12.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable residual: reward proportional tightness, but only if
        // the residual can plausibly host the lookahead item.
        let usable = if next_item_size > 0 && (post_residual as u32) >= next_item_size { 1.0 } else { 0.35 };
        score -= usable * (post_residual as f64 / bin_capacity as f64) * 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: fewer open bins is better; discourage scattering.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual below mean (consolidating fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when current item nearly fills it
    // and open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio >= 0.85 {
            score -= 50.0;
        } else {
            score += 30.0 + 40.0 * (1.0 - fill_ratio);
        }
    }

    // Late in stream: waste tolerance drops, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap; // 0..1, 1 = perfect fit
    score -= 2.5 * tightness * tightness * cap * 0.1;

    // Strong penalty for unusable dead space (residual below minimum item size 1..10).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0 + 0.5 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 5.0; // perfect fill, excellent
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward precise 2-step packing: next item leaves little dead space.
            score -= 8.0 * (1.0 - slack / cap);
            if (post_residual - next_item_size) < 10 {
                score -= 6.0; // chain closes nicely
            }
        } else {
            // Next item won't fit here; penalize proportionally to the gap,
            // but less harshly if post_residual is tiny (bin nearly full anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Coupling with mean residual: favor bins below mean residual (tighter than average).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish score so we only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses (sunk cost less relevant).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap as f64 * 0.55 + 10.0 * (1.0 - progress);
        // If no open bin fits, opening is inevitable-ish; make new bin attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Lookahead on fresh bin: it can host item + next item comfortably.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 4.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Reward residuals that can still host the next item.
            score -= 4.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-slack / 25.0).exp();
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Spread load when many bins fit.
        score += (fitting_bins_count as f64 - 1.0) * 1.2;
    }

    // New-bin candidate: neutral-ish, but prefer it over creating tiny dead space.
    if bin_residual == bin_capacity {
        score += 6.0;
        if item_size >= 70 {
            score -= 12.0; // big items into fresh bins is fine
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 8.0; // fresh bin still leaves usable space for next item
        }
    }

    // Time horizon: late in stream, consolidate; early, stay flexible.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * t * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }
    // Few open bins -> slight preference to open fresh bins to keep options open.
    if open_bins_count <= 1 {
        score += 2.0;
    }

    // Penalize extremely small residuals as unusable dead space.
    if post_residual < 10 {
        score += 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize residual quadratically (favor tight fits), scaled by capacity.
    let mut score = pr + (pr * pr) / cap;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight packing matters more (dead space penalty grows).
    let progress_coupling = pr * (0.5 + 2.0 * progress * progress);
    score += 0.35 * progress_coupling;

    // Reward high fill ratio smoothly (avoid hard piecewise constants).
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= 4.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to wasted opportunity.
        score += 1.5 * (1.0 - progress);
    }

    // Mean-residual coupling: placing into a bin whose residual is near the mean
    // is neutral; deviating bins get smooth adjustment.
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate handling: empty bin starts with a moderate penalty so it
    // only wins when open bins would create large dead space.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) - 3.0 * fit_ratio;
        // If no open bin fits, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: reward residuals that form
    // "clean" fractions of capacity (usable by common future item sizes).
    let pr = post_residual;
    if pr > 0 {
        // Harmonic class: which capacity-eighths band does post_residual fall in?
        let class = pr / (bin_capacity / 8);
        match class {
            0 => score -= 4.0,               // tiny residual: nearly perfect fit
            1 => score -= 6.0,               // small but usable
            2 => score += 2.0,               // awkward middle band
            3 => score -= 1.0,               // ~half-full leftover
            4 => score += 3.0,               // awkward
            5 => score -= 2.0,
            6 => score += 4.0,               // mostly empty: wasteful placement
            _ => score += 6.0,
        }
        // Integer-division thresholds: residuals divisible by common sizes
        // (10, 20, 25, 50) are more likely to be filled exactly later.
        if pr % 10 == 0 { score -= 2.5; }
        if pr % 20 == 0 { score -= 1.5; }
        if pr % 25 == 0 { score -= 1.0; }
        if pr % 50 == 0 { score -= 1.5; }
    } else {
        score -= 12.0; // perfect fit: strongly favored
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 15.0;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > pr && pr > 0 {
        // Next item won't fit here: penalize creating dead space.
        score += 3.0 + (pr as f64) / cap * 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's fit
    // is poor (large post_residual) and there are already many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.45 * cap;
        if poor_fit && open_bins_count > 2 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        } else {
            score += 8.0; // discourage opening new bins unnecessarily
        }
    }

    // Mild pressure to balance residuals toward the mean across open bins.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // dead end for next item
    }

    // New-bin candidate must not be chosen too eagerly: penalize opening
    // unless the current fit is genuinely bad (handled by the terms above).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item fits here later; penalize leftover mismatch
            let mismatch = post_residual as f64 - nr;
            score -= 20.0 * (1.0 - mismatch / bin_capacity as f64);
        } else {
            // next item cannot fit in post_residual: dead space risk
            let dead = post_residual as f64;
            score += 8.0 * (dead / bin_capacity as f64) * (dead / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last chance: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in stream, new bins are cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more attractive
        score -= 0.1 * next_item_size as f64;
    }

    // Mild penalty for wasteful near-full bins left with tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize leaving large residuals that trap nothing
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins have plenty of room
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r > item_size as f64 * 1.3 && open_bins_count > 0 {
            score += 30.0 + mean_r;
        }
        // Early in stream, mild preference to consolidate; late stream, allow new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    } else {
        // Favor bins with residuals close to item size (best-fit style)
        let gap = (bin_residual - item_size) as f64;
        score += 0.15 * gap;
    }

    // Slight penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let t = progress;

    // Polynomial interaction: dead-space penalty grows super-linearly as stream progresses
    let coupling = pr_norm * pr_norm * (1.0 + 2.0 * t) + pr_norm * pr_norm * pr_norm * (3.0 * t);
    score += 8.0 * coupling;

    // Tight fit reward (small post residual), stronger late in stream
    let tight = (1.0 - pr_norm).powi(3);
    score -= 6.0 * tight * (0.5 + t);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + t);
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / bin_capacity as f64;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            // penalize creating residual too small for next item (dead space)
            score += 5.0 * (nx - pr) / bin_capacity as f64 * (1.0 + t);
        }
    }

    // Penalize scattering across many open bins; mild preference for consolidation
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make empty bin mildly unattractive unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 10.0 + 12.0 * (1.0 - t) - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let k = (post_residual / 10).min(10); // integer division class 0..10

    // Penalize awkward dead-space classes (odd-ish residuals that rarely pair with
    // typical item sizes), reward "harmonic" residuals divisible by 10/20/25.
    let harmonic_bonus = if post_residual % 25 == 0 {
        6.0
    } else if post_residual % 20 == 0 {
        4.0
    } else if post_residual % 10 == 0 {
        2.0
    } else if post_residual % 5 == 0 {
        0.5
    } else {
        -2.0
    };
    score -= harmonic_bonus;

    // Perfect fit: zero post residual is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space that can't fit next item is worse
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room exactly compatible with the next item
            let slack = post_residual - next_item_size;
            score -= 3.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 {
                score -= 1.5;
            }
        } else {
            score += 5.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 25.0 - crowded * 10.0;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 4.0;
        }
        // early in stream, prefer new bins to build diverse residual classes
        score -= 8.0 * (1.0 - progress);
        // avoid new bin if a harmonic class residual is achievable elsewhere
        if k <= 10 && post_residual % 10 == 0 {
            score -= 2.0;
        }
    }

    // Mild preference for tighter bins overall (small residual before placement)
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    // Penalize scores far from mean residual alignment (keeps residual classes balanced)
    score += 0.1 * (frac * 10.0 - (mean_residual / bin_capacity as f64) * 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap smaller than the next item
    // is unusable dead space -> heavy penalty proportional to the waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones.
    score -= open_bins_count as f64 * 0.6;

    // New-bin candidate (empty bin): penalize so it only wins when fits elsewhere
    // are terrible; scale penalty with mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.4;
    }

    // Mild reward for consuming more of the bin's current space.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
