pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1); early on we explore, late we consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core fit-quality: reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residual that is small but unusable (<10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item consumes leftover
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual too small for next item: penalize more as stream progresses
            // (late in stream, keeping usable residual matters less; but early it hurts).
            score += 10.0 * progress * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate small leftovers),
    // which reduces the number of scattered partial bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 3.0 * residual_gap;

    // Mild preference for using existing bins over opening new ones as stream progresses.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless it enables a perfect chain.
        let mut penalty = 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size == post_residual {
            penalty -= 25.0; // fresh bin perfectly fits the lookahead chain
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    } else {
        // Reward using open bins, more so when many are open (reduce bin count).
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Time-horizon coupling: late in the stream, prioritize exact fills aggressively.
    if progress > 0.7 {
        score -= 6.0 * tightness * (progress - 0.7) / 0.3;
    }

    // Small deterministic tie-breaker based on residual parity structure.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with a smooth non-linear penalty on mid-range waste
    let mut score = pr;

    // Non-linear coupling: dead-space penalty grows quadratically with normalized residual,
    // modulated by stream progress (late in stream, waste matters more).
    let waste_curve = norm_pr * norm_pr * (3.0 - 2.0 * norm_pr); // smoothstep-like in [0,1]
    score += 30.0 * waste_curve * (0.5 + progress);

    // Reward tight fits: item filling most of residual gets smooth discount
    let fill = it / bin_residual.max(1) as f64;
    let tight = fill * fill * (3.0 - 2.0 * fill.min(1.0));
    score -= 25.0 * tight * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits the post-residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let nxn = nx / cap;
            let prn = norm_pr;
            let coupling = nxn * prn * (1.0 - nxn);
            score -= 40.0 * coupling;
        } else {
            // next item won't fit: penalize large residuals smoothly
            score += 10.0 * norm_pr * (1.0 - progress);
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward to avoid new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: mild pressure to fill existing ones (smooth in count)
    let obn = open_bins_count as f64;
    score -= 5.0 * (obn / (obn + 5.0)) * (1.0 - norm_pr);

    // Mean residual context: prefer bins deviating below mean residual (consolidate waste)
    score += 3.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: empty bin gets a smooth opening cost, cheaper early in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 8.0 * (1.0 - (obn / (obn + 3.0)));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "nice" residue classes (multiples of 10 / 20) are more reusable.
    let residue_class = post_residual % 10;
    let class_penalty = match residue_class {
        0 => -14.0,
        5 => -6.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: leftover in [1,9] is nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: next item exactly consumes leftover class.
            if post_residual % 20 == 0 && next_item_size >= 10 {
                score -= 12.0;
            }
            score -= 8.0;
        } else {
            // Leftover too small for next item: penalize proportionally.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 10.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Progress-coupled tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Mean residual coupling: avoid bins far below mean residual (hoarding space).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Prefer bins that leave residue in the same harmonic class as item size.
    if post_residual % 10 == item_size % 10 && post_residual >= item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use
    // are pure waste -> heavy penalty scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Small gaps (10..20) risk becoming dead space if next item is larger.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: lower score when item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward;
    // if next item cannot fit, the residual is likely dead -> penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, opening is cheaper.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Penalize bins whose residual deviates far below mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be slightly more willing to open new bins
    // (long horizon amortizes); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus late-stream consolidation pressure.
        score += 30.0 + progress * 40.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // exact 2-step chain
        } else if post_residual >= next_item_size {
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead potential
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize new-bin opening unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 150.0 - 0.5 * waste;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open new bin
        }
    }

    // Late-stream consolidation: fewer open bins is better near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is already low; amplify via quadratic.
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap) * 8.0;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit
    }

    // Penalize creating dead space that nothing can use later.
    // Dead space: post_residual smaller than the minimum plausible item (assume ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well it fits
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fit_ratio;
        } else {
            // next item cannot use the leftover; penalize proportionally to wasted space
            score += 6.0 * (pr / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when existing bins are crowded,
        // but wasteful when open bins have plenty of room.
        let crowd = mean_residual / cap; // average free space fraction
        score += 20.0 + 30.0 * crowd;
        // Early in the stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many bins are already open, discourage fragmentation.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for fuller bins overall (best-fit bias).
    score += 4.0 * (bin_residual as f64 / cap);

    // Coupling: if mean residual is high, keep using existing space.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = post / cap;

    // Smooth polynomial base: reward tight fits (low post_residual), with
    // a non-linear penalty that grows superlinearly for large dead space.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: early on, be more tolerant of slack (favor
    // filling fresh bins); later, tighten preference for small residuals.
    let progress_coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Non-linear interaction between item size and post residual:
    // medium items leaving small residuals are strongly favored.
    let coupling = (fit_ratio * (1.0 - norm_post)) * 20.0;
    score -= coupling;

    // Lookahead: reward bins whose post_residual fits the next item,
    // penalize when post_residual is awkwardly close to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual alignment: prefer bins near the mean residual state
    // (keeps residual distribution balanced), smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty on opening new bins when many are open with room.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction left over

    // Perfect-fit reward: post residual exactly fills a harmonic class
    if post_residual == 0 {
        score -= 60.0;
    }
    // Residuals that are multiples of 10 are "friendly" classes (likely future fits)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Dead-space penalty: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Integer-division thresholds: penalize residuals that cannot host
    // any plausible item (>= next item or >= 10 minimum)
    if post_residual < next_item_size && next_item_size > 0 {
        score += 12.0;
    }
    // Reward residuals that can host the lookahead item exactly or with slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0; // lookahead perfect fit
        } else if slack < 10 {
            score += 6.0; // lookahead creates dead space
        } else {
            score -= 5.0;
        }
    }

    // Modulo coupling: post_residual mod item_size reveals harmonic alignment
    let m = if item_size > 0 { post_residual % item_size } else { 0 };
    if m == 0 && post_residual > 0 {
        score -= 10.0; // bin residual is an exact multiple of item size
    } else if m > 0 {
        score += (m as f64) * 0.3;
    }

    // Capacity-fraction band penalties on the leftover fraction
    if frac > 0.0 && frac < 0.1 {
        score += 15.0 * (1.0 - frac * 10.0); // tiny sliver
    } else if frac >= 0.1 && frac < 0.5 {
        score -= 4.0; // useful half-bin class
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { 0.0 } else { 10.0 + mean_residual * 0.2 };
        score += penalty;
        // early stream: opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
