pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but soften so near-perfect fits dominate.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match for next item is a jackpot: strong subtraction.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward proportional to closeness.
            score -= 0.5 * (30.0 - diff).max(0.0);
        } else {
            // Next item would NOT fit after this placement: penalize dead space
            // scaled by how much of the residual is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(80.0);
        }
    } else {
        // Last item: pure tightest-fit behavior.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" bins;
    // filling them is good if the fit is tight, bad if it leaves odd dead space.
    let tightness = mean_residual - post_residual as f64;
    if tightness > 0.0 {
        // This bin is tighter than average: reward filling it tightly.
        score -= 0.2 * tightness.min(50.0);
    } else {
        // Looser than average: slight penalty to avoid dumping into loose bins
        // when a tighter option exists.
        score += 0.1 * (-tightness).min(50.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin moderately, but less when
    // many bins are open and mean residual is large (fragmented state).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 - 15.0 - 20.0 * fragmentation;
    }

    // Late-stream consolidation: as the stream progresses, favor closing out
    // existing bins over spreading items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual after placement too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += 0.8 * waste + 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain usable for the lookahead item
        score -= 15.0;
        // Extra reward for near-perfect two-item packing
        let two_fit = (item_size + next_item_size) as f64;
        if (bin_residual as f64 - two_fit).abs() <= 5.0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize bins far below mean residual (fragmenting the bin population)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in the stream: be pickier (long horizon ahead -> avoid small residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Many open bins: prefer consolidating into existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: baseline cost of opening a fresh bin
    if bin_residual == bin_capacity {
        // Attractive only late in stream or when many bins are open and item is large
        let new_bin_bonus = 40.0 * progress + 2.0 * open_bins_count as f64 + 0.3 * item_size as f64;
        score = bin_capacity as f64 - new_bin_bonus + 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can also host the next item
        }
        // Never open a new bin if it's the only fitting option and a good fit exists
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate looser fits
    // since consolidation matters more than dead space minimization.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + 2.0 * progress) - 0.5 * prn * progress;
    score += 60.0 * poly;

    // Penalize the brand-new empty bin candidate smoothly: opening a new bin is
    // only attractive when existing residuals are poor relative to the item.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let waste = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 30.0 * (1.0 - progress) * (1.0 - waste);
        score += 8.0 * fitting_bins_count as f64 / (1.0 + open_bins_count as f64);
    }

    // Reward bins whose post residual matches the next item (lookahead coupling).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - 0.5 * progress);
    } else if next_item_size > post_residual {
        // Dead space that the next item cannot use: penalize superlinearly.
        let dead = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for bins tighter than the current mean residual.
    score += 5.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: post_residual divisible by a common item quantum -> highly reusable.
    let quantum: u32 = 10;
    let harmonic_class = post_residual % quantum;
    let class_penalty = match harmonic_class {
        0 => -12.0,                              // perfectly reusable leftover
        1..=3 => 6.0,                            // near-dead sliver
        4..=7 => 2.0,                            // mildly awkward
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: leftover large enough for a "big" item (>=50)
    // is valuable; leftover that can only host tiny items is semi-dead.
    let big_slot = post_residual / 50;
    score -= big_slot as f64 * 8.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves its own residue; penalize by its awkwardness
            let next_left = post_residual - next_item_size;
            score -= 10.0 - (next_left % quantum) as f64 * 0.5;
        } else {
            // next item cannot fit here: slight penalty proportional to overshoot class
            let overshoot = (next_item_size - post_residual) / 20;
            score += overshoot as f64 * 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly discourage
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when open bins are badly fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: keep open bins tight, prefer filling them
        // late stream: opening fresh bins is cheaper than fragmenting
        let new_bin_bonus = 20.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bonus + 0.05 * fragmentation;
    }

    // Prefer bins whose residual deviates strongly below the mean (tight fit
    // relative to the fleet), a fractional capacity coupling.
    let frac_fit = (bin_residual as f64) / (bin_capacity as f64);
    score += 5.0 * (frac_fit - 0.5).abs();

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (but nonzero) are pure waste -> heavy penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    } else if post_residual < 20 {
        // Marginal gap: moderate penalty scaled by how unusable it is.
        score += 25.0 * (20.0 - pr) / 20.0;
    }

    // Reward residual that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 80.0;
        } else if pr >= nxt && pr - nxt < 10.0 {
            // Would leave near-dead space for the next item -> penalize.
            score += 20.0 * (10.0 - (pr - nxt)) / 10.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins unless the
    // fit is genuinely good; encourage consolidating when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the resulting residual is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Prefer bins whose residual is already small (tight packing).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for filling fuller bins relative to capacity.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
