    // Base: prefer tight fits (small post_residual)
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits: reward tightness of the follow-up fit
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 0.15 * post_residual as f64;
        }
        // perfect chaining bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Compare against mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: keep it neutral-ish but penalize when decent fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize wasting large residual capacity on small items
    if post_residual > 60 {
        score += 0.2 * (post_residual - 60) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
