    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 10.0 * chain;
        } else {
            // Penalize residuals that just barely fail the next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 { score += 0.6 * miss; }
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) * 0.05);
    score -= 4.0 * pressure.min(3.0) * tightness;

    // Prefer bins whose residual is close to the mean (keep balance),
    // but only mildly, so tight fits still dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev.min(50.0);

    // New-bin candidate: only attractive when nothing fits well
    // (large post_residual on existing bins means poor fits everywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_score = cap * 0.55;
        // Cheaper to open a bin early in the stream or when bins are scarce.
        let progress = (step_index as f64) / (total_items as f64).max(1.0);
        new_score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 { new_score -= 100.0; }
        // If the current candidate fits terribly, opening a bin looks better.
        if post_residual > item_size as f64 * 0.9 { new_score -= 15.0; }
        // If lookahead item is huge, a fresh bin may serve it.
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.7 && item_size as f64 <= cap * 0.3 {
            new_score -= 12.0;
        }
        score = score.min(new_score);
        // Ensure a genuinely good existing fit always beats a new bin.
        if post_residual <= 15.0 { score = new_score + 1000.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: post residual, with smooth non-linear penalty on large unusable gaps
    let mut score = pr
        + 40.0 * fit_frac * fit_frac * (1.0 - fit_frac) * cap
        - 30.0 * fit_frac * (1.0 - fit_frac);

    // Perfect fit reward (smooth)
    score -= 25.0 * (-fit_frac * 30.0).exp();

    // Progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.5 * progress * fit_frac;
    score -= 10.0 * progress * fit_frac;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // New-bin candidate: penalize slightly so we prefer filling open bins,
    // but relax when open bins are crowded / residuals are poor
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 20.0 - 15.0 * crowd - 10.0 * progress;
    } else {
        // Prefer bins whose residual is close to mean (balance)
        score += 2.0 * (pr - mean_residual).abs() / cap;
        // Prefer fuller bins among many open bins
        score += 3.0 * (open_bins_count as f64).ln() * (1.0 - fit_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base best-fit: prefer smallest post_residual
    score = post_residual as f64;

    // Harmonic class of the residual after placement (integer division into classes of 10)
    let res_class = post_residual / 10;
    // Harmonic class of the next item
    let next_class = if next_item_size == 0 { 0 } else { ((next_item_size - 1) / 10) + 1 };

    // Reward when post_residual exactly matches the next item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Reward when next item fits into post_residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
    }
    // Penalize dead space: post_residual too small for anything useful (below min item size)
    if post_residual < 10 {
        score += 25.0;
    }
    // Penalize wasting large residuals on tiny items: modulo-based coupling
    if post_residual >= 40 && item_size <= 20 {
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // If no open bin fits (fitting_bins_count == 0 means only new bin candidate), accept
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual deviates from mean residual (consolidate similar bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Harmonic threshold: residuals in class 3 (30-39) are awkward; penalize slightly
    if res_class == 3 {
        score += 5.0;
    }
    // Residual class 0 is perfect; reward strongly
    if post_residual == 0 {
        score -= 20.0;
    }

    // Coupling: when many bins are open, tighten selection toward exact fits
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += (10 - post_residual as i32) as f64 * 25.0;
    }
    // Medium gaps (10..=19) are moderately wasteful.
    if post_residual > 9 && post_residual <= 19 {
        score += (19 - post_residual as i32) as f64 * 4.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward bins that can also host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize bins whose post-residual becomes just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // New-bin candidate: only attractive if this bin would be a poor host.
    if bin_residual == bin_capacity {
        score += 45.0 - open_bins_count as f64 * 3.0;
        // If current bin leaves a tiny dead gap, opening a new bin is more appealing.
        if post_residual > 0 && post_residual <= 9 {
            score -= 55.0;
        }
    }

    // Slight preference for bins below mean residual (balancing load).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (tight packing).
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize dead space that is too small for any plausible item.
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // 2-step lookahead: reward bins where the leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Extra reward for a near-perfect chain: leftover just above next item.
        let slack = post_residual - next_item_size;
        score -= (slack as f64).min(30.0) * 2.0;
    } else if next_item_size > 0 {
        // Leftover cannot fit next item; penalize proportional dead space.
        score += 60.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 100.0;
        // Late in the stream, avoid opening new bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still host the next item.
            score -= 2.5;
        }
        // Exact lookahead fit is very valuable.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a nearly-full bin on a small item when alternatives exist.
    if fitting_bins_count > 1 && post_residual as f64 > mean_residual * 1.5 {
        score += 3.0;
    }

    // Prefer placing into bins with above-average residual (consolidate emptiness).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: open a fresh bin only when fits are poor or stream is late
    // and open-bin count is low relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if poor_fit || (progress > 0.7 && open_bins_count < 3) {
            score -= 10.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild time-horizon pressure: early on, be conservative with open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut poly = norm_pr * (1.0 + 2.5 * t * t + 1.5 * t);

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = (1.0 - norm_pr).powi(3);
    poly -= 18.0 * tightness * (0.5 + t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            poly += 8.0 * (nxt - pr) / cap * (1.0 + t);
        } else {
            poly -= 3.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        poly -= 12.0 * (1.0 - t * 0.5);
    }

    // Mild pressure from open bin count and mean residual
    poly += 0.15 * open_bins_count as f64 * norm_pr;
    poly -= 2.0 * (mean_residual / cap - norm_pr);

    // New-bin candidate: slightly penalize so we prefer reusing bins unless fit is poor
    if bin_residual == bin_capacity {
        poly += 6.0 + 10.0 * t;
    }

    poly
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define
    // "harmonic classes". Residues in {0} are perfect closures; residues
    // near 0 are good; mid-range residues (4..6) are dead-space traps.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => { score -= 25.0; }               // perfect harmonic closure
        1 | 2 | 3 => { score -= 8.0; }        // near-closure, still usable
        4 | 5 | 6 => { score += 12.0; }       // dead-space trap class
        7 | 8 => { score -= 2.0; }            // mildly useful
        _ => { score -= 5.0; }                // residue 9, nearly closed
    }

    // Integer-division thresholds: post_residual buckets of size 20.
    // Buckets below 20 are nearly useless; large buckets are valuable.
    let bucket = pr / 20;
    score += match bucket {
        0 => 18.0,
        1 => 6.0,
        2 => 0.0,
        3 => -6.0,
        _ => -12.0,
    };

    // Coupling with next item: if the post-residual can hold the next item,
    // reward chaining; if it *almost* holds it (within 5), penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as f64) >= nx {
            score -= 10.0 * (nx / cap);
        } else if (pr as f64) >= nx - 5.0 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin unless post-residual is tiny.
    if fitting_bins_count == 1 {
        score -= 22.0;
        if pr < 10 { score += 15.0; }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should win only when the item fits badly everywhere else, i.e.
    // when placing here leaves a trap-class residual.
    if bin_residual == bin_capacity {
        // Fresh bin score: baseline of item's complement plus mild openness.
        let mut fresh = (bin_capacity - item_size) as f64;
        if open_bins_count == 0 { fresh -= 30.0; }
        // Penalize opening a new bin late in the stream.
        fresh += 8.0 * (step_index as f64 / total_items.max(1) as f64);
        // If current bin leaves a good residual, discourage the new bin.
        if class == 0 { fresh += 20.0; }
        if class >= 4 && class <= 6 { fresh -= 15.0; }
        score = score.min(fresh);
        return fresh.min(score);
    }

    // Mild global pressure: many open bins -> tighten packing.
    score += 0.35 * open_bins_count as f64;
    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (>=1) can use are pure waste.
    if post_residual > 0 {
        // Dead space: residual too small for even the smallest item (1).
        // Weight grows steeply as gap shrinks into the "unusable" zone.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Gap too small for the NEXT item is also likely waste (lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 80.0;
    }

    // Reward tight fits (low post_residual relative to capacity) super-linearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64).sqrt()).min(3.0);
    score += 8.0 * pressure;

    // Mean residual coupling: prefer bins with residual near the mean
    // (keeps a balanced spread of gap sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this bin's fit would leave a large awkward gap, or when few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when open_bins_count is low
        // or the current placement would waste a lot.
        let awkward = if post_residual > 0 && post_residual < 20 { 1.0 } else { 0.0 };
        let discount = 30.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
        score += 25.0 - discount - 20.0 * awkward;
        // If the next item is huge, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual (tight fit).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        // Perfect chain bonus: post_residual == next_item_size
        if gap < 0.5 {
            score -= 30.0;
        } else if nx <= pr {
            // Next item fits here: reward proportional to how well it chains,
            // leaving an even smaller residual afterwards.
            let chained = pr - nx;
            score -= 20.0 * (1.0 - chained / cap);
        } else {
            // Next item cannot fit in post_residual: penalize wasted chain potential.
            score += 5.0 + 10.0 * ((nx - pr) / cap);
        }
    } else {
        // Last item: pure tightness.
        score -= 15.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    let dead = pr - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.25 * dead; // slight reward for being below-average residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if it enables a very tight fit now,
    // otherwise discourage proliferation when decent fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        // But if item is large, a fresh bin is naturally good (small post_residual).
        if item_size as f64 >= 0.7 * cap {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (pr / cap);

    // Non-linear penalty for small-but-annoying residuals (hard to fill later).
    if pr > 0.0 && pr < 10.0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating small unusable dead space (< next item or < 10).
    if post_residual > 0 {
        let min_future = if next_item_size > 0 && next_item_size <= post_residual {
            next_item_size as f64
        } else {
            10.0
        };
        if (post_residual as f64) < min_future {
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight bonus for consuming slack.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current bins are nearly full
    // or many bins are open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64) * 0.5 + early * 0.5;
        score += 12.0 * (1.0 - pressure);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer filling bins with larger residuals when many bins are open.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual);

    // Slight time-dependent aggression: pack tighter early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let t = progress;
    let coupling = prn * prn * (1.0 - t) + prn * t * t;
    score += 2.5 * coupling;

    // Reward tight fits (small post_residual), stronger late in stream.
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness * tightness * (0.5 + t);

    // Last-chance bonus: avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - pr / (next_item_size as f64 + pr)).max(0.0);
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Penalize bins with residuals far from mean (fragmentation signal).
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are golden; tiny
    // unusable slivers (<10) are dead space and heavily penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Modulo-10 harmonic class: residual divisible by 10 stays "usable"
        // for the typical integer item sizes; odd residues are worth less.
        let class = post_residual % 10;
        score -= match class {
            0 => 30.0,
            5 => 10.0,
            _ => (class.min(10 - class)) as f64 * 1.5,
        };
    }

    // Integer-division thresholds on post_residual: can it host the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain potential: reward proportional to how snugly next item fits.
            let slack = post_residual - next_item_size;
            score -= 25.0 - (slack.min(40)) as f64 * 0.4;
            if post_residual == next_item_size {
                score -= 40.0; // perfect 2-chain
            }
        } else {
            // Lookahead cannot fit here: penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: discourage opening fresh bins mid-stream unless
    // nothing sensible fits; early stream slightly favors new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - progress * 25.0 - (item_size as f64) * 0.2;
        if item_size >= 70 {
            score -= 10.0; // big items start fresh bins happily
        }
    }

    // Prefer tighter bins overall (relative fill ratio).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Many open bins with high mean residual: encourage consolidation.
    if open_bins_count > 3 && mean_residual > 0.0 {
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < item_size as f64 * 0.15 {
        score -= 15.0;
    }

    // Penalize gaps that cannot host the lookahead item if it could otherwise fit here.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when fit is decent.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate: make it unattractive unless the best existing fit would leave
    // severe dead space (handled above via penalties); otherwise add a strong bias.
    if bin_residual == bin_capacity {
        score += 45.0;
    } else {
        // Mild preference for fuller bins (smaller residual before placement).
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Slight alignment with the fleet's average residual to balance loads.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already encoded).

    // Lookahead: if next item fits exactly or well into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: bin closed after next item
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward decreasing with leftover slack after the lookahead item
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; mild penalty for stranding residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize leaving residuals that are hard to reuse (small but nonzero),
    // scaled against mean residual across open bins.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare post_residual relative to mean residual: leaving less than average
    // means this bin was used efficiently; leaving more than average is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin has large post_residual,
    // so it naturally scores high; add extra penalty unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= item_size + next_item_size {
            // pairing current+next in fresh bin can be good
            score -= 20.0;
        }
    }

    // Slight preference to fill older/more crowded bin sets early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Penalize creating awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits perfectly in the post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here; penalize leaving large unusable remainder.
            score += (post_residual as f64).min(30.0) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // relative to capacity or current open bins are already tight on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        let tight_state = (mean_residual - item_size as f64) * 0.5;
        score += 25.0 - large_item_bonus - tight_state * 0.3 - progress * 5.0;
        // If no open bin fits, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are large.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Global state: prefer bins close to the mean residual (balance loads).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: dead-space penalty grows quadratically with residual size
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= 8.0 * (1.0 - pr_norm).powi(3);

    // Perfect fit reward: post_residual zero or exactly matching next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: smooth interaction between post_residual and next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx; // >0 means next item also fits
        let s = slack / cap;
        // mildly reward leaving room for next item, penalize leaving awkward mid-size gaps
        score += 4.0 * s * s - 3.0 * s;
    }

    // Late-stream pressure: favor filling existing bins as stream progresses
    score -= 10.0 * progress * (1.0 - pr_norm);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a smooth opening cost that
    // shrinks as the item is large or mean residuals across open bins are high
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let openness = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        let mean_gap = (mean_residual / cap - pr_norm).abs();
        score += 10.0 * openness + 5.0 * mean_gap - 6.0 * (it / cap);
    } else {
        // Slight preference for bins with residual close to item (smooth)
        let fit_gap = (bin_residual as f64 - it) / cap;
        score += 3.0 * fit_gap * fit_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" vs "dead" space
    let residue = post_residual % 10;
    let harmonic_penalty = match residue {
        0 => -15.0,                       // perfectly harmonic residual
        1 | 2 | 3 => 8.0,                 // nearly dead space
        4 | 5 | 6 => 2.0,                 // marginal
        _ => -5.0,                        // 7..9 still roomy
    };
    score += harmonic_penalty;

    // Integer division thresholds: post_residual classes by quarter capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 20.0; // tiny residual, likely wasted
    } else if post_residual <= quarter {
        score -= 6.0;  // tight but productive fit
    } else if post_residual > 3 * quarter {
        score -= 3.0;  // large residual, bin still flexible
    }

    // Lookahead coupling: does the next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward exact/near chain fits
            let gap = post_residual - next_item_size;
            score -= 10.0 + (gap <= 5) as i32 as f64 * 8.0;
        } else {
            // next item won't chain: penalize proportional to overflow severity
            let overflow = next_item_size - post_residual;
            score += (overflow as f64) * 0.35;
        }
    } else {
        // last item: maximize packing tightness
        score -= 12.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate: only attractive when current item is large and mean residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 25.0 * large_item - 15.0 * fragmentation / bin_capacity as f64 - 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 8.0; // fresh bin can chain next item
        }
    }

    // Mild preference to consolidate into fewer bins late in the stream
    score += 0.4 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Exact fill bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Minimum item size is 1; gaps below the smallest plausible next item are dead.
        let dead_threshold = 10u32.min(bin_capacity / 10);
        if post_residual < dead_threshold {
            score += (dead_threshold - post_residual) as f64 * 12.0;
        }
        // Smooth quadratic penalty on residual wastefulness relative to capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 40.0;
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good
    // consolidation candidate; penalize picking bins with residuals much above mean.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + snug);
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no open bins can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, opening fresh bins is less attractive.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

