    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host next item: mild reward proportional to tightness.
        let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 50.0 * tightness;
    } else if next_item_size > 0 && post_residual < next_item_size {
