        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize bins far below mean residual (poorly filled bins kept open).
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Prefer filling bins when many bins are open (reduce fragmentation).
    if open_bins_count > 3 {
        score -= 10.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 500.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin still fits next item
        } else {
            score += 60.0; // discourage opening new bin otherwise
        }
    }

    // Slight late-stream bias toward consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * nxt_fill;
        } else {
            // leftover too small for next item: penalize dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is bad unless existing
    // residuals are fragmented / mean residual is low relative to item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // if mean residual across open bins can't fit item well, new bin ok
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // many open bins: discourage another
        score += open_bins_count as f64 * 2.0;
    } else {
        // reward using bins whose residual is close to item (good packing)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * tightness * tightness;
    }

    // Global fragmentation pressure: high mean residual => pack existing bins harder
    score -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;

    // Penalize leaving residuals that are awkwardly small (dead space < 10)
    if post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

