    // reward if post_residual exactly or nearly accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let dead = post_residual as f64 / cap;
            score += 20.0 * dead * dead * (0.5 + progress);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Stream-progress coupling: late in the stream, be more aggressive at filling open bins
    // (penalize opening/spreading), early on allow exploration.
    score += 15.0 * progress * (post_residual as f64 / cap);

    // Mean residual interaction: prefer bins close to the mean residual for balanced packing.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    // New-bin candidate handling: only attractive early or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 40.0 * (1.0 - progress) + 25.0 * (1.0 - avg_fill).max(0.0);
        if fitting_bins_count > 0 && post_residual == bin_capacity {
            score += 30.0; // discourage new bin when open bins fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: prefer residuals in friendly classes
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,           // perfectly reusable residual
        1 | 2 => score -= 6.0,
        3 | 4 | 6 | 7 => score -= 2.0,
        8 => score += 4.0,            // awkward near-full residual
        9 => score += 8.0,
        _ => {}
    }

    // Integer-division threshold on post_residual: large leftover chunks are valuable
    if post_residual >= 50 {
        score -= 15.0;
    } else if post_residual >= 30 {
        score -= 5.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 10.0; // dead space penalty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64 / 10.0).min(6.0);
        } else {
            score += 3.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening new bins unless stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress;
        if open_bins_count > 0 && post_residual >= 60 {
            score -= 6.0;
        }
    }

    // Tight-fit reward: filling bin almost completely
    if post_residual <= 5 {
        score -= 14.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (predictable reuse)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Slight preference for already-open bins over creating sprawl
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size) are pure waste -> heavy penalty.
    let dead = post_residual < 10 && post_residual > 0;
    if dead {
        score += 60.0 + 2.0 * (10 - post_residual) as f64;
    }
    // Small-but-usable residuals are risky too: mildly penalize gaps < 25.
    if post_residual > 0 && post_residual < 25 && !dead {
        score += (25 - post_residual) as f64 * 1.2;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fill of an existing bin's residual.
    if item_size == bin_residual {
        score -= 50.0;
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover -> dead space risk
            score += (next_item_size - post_residual).min(30) as f64 * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // the item is large relative to typical residuals.
        score = 100.0 + pressure - (item_size as f64 / bin_capacity as f64) * 80.0
            - if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
    } else {
        score += pressure * 0.5;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, simplifying future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted residual
            score += 40.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when post_residual is small
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Exact fit is excellent
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use
        score += 0.3 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last chance: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer fuller bins over emptier ones when residuals are similar
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New bin candidate: only attractive when existing fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        let late_stream = step_index as f64 / total_items.max(1) as f64 > 0.5;
        if bad_fit && next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 25.0; // open fresh bin to preserve big residuals
        } else if late_stream && bad_fit {
            score -= 5.0;
        } else {
            score += 15.0; // default: prefer existing bins
        }
    }

    // Encourage consolidation when many bins are open
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: post residual, with non-linear dead-space penalty (residuals that
    // are small but nonzero are the worst waste).
    let x = pr / cap;
    let mut score = x - 0.9 * (1.0 - x).powi(2) + 0.35 * x.powi(3);

    // Smooth progress coupling: later in stream, value tight fits even more
    // and penalize leaving medium residuals.
    score += 0.5 * progress * x * (1.0 - x);
    score -= 0.4 * progress * (1.0 - x).powi(3);

    // New-bin candidate: opening a bin is costly; penalize smoothly, less so
    // if this is the only fitting option.
    if is_new_bin {
        let scarcity = if fitting_bins_count >= 1 { 1.0 / (fitting_bins_count as f64 + 1.0) } else { 1.0 };
        score += 1.2 - 0.9 * scarcity - 0.3 * progress;
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 0.8;
        }
        // Lookahead: reward if next item fits the post residual.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx <= pr {
                let snug = 1.0 - ((pr - nx) / cap).powi(2);
                score -= 0.5 * snug;
            } else {
                score += 0.3 * ((nx - pr) / cap);
            }
        }
        // Coupling with mean residual: placing into bins far from the mean
        // residual balances the pool (smooth quadratic attraction).
        let dev = (pr - mean_residual) / cap;
        score += 0.25 * dev * dev;
    }

    // Mild pressure to close out nearly-full bins as stream progresses.
    score -= 0.2 * progress * (1.0 - x).powi(4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let q = post_residual * 4 / bin_capacity; // 0..3 class index
    let class_penalty = match q {
        0 => 0.0,          // near-perfect fit
        1 => 6.0,          // small dead space
        2 => 14.0,         // awkward half-empty
        _ => 22.0,         // mostly empty after placement
    };
    score += class_penalty;

    // Modulo arithmetic: residuals divisible by small integers are more reusable.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 5.0; }
        else if r % 5 == 0 { score -= 2.5; }
        if r % 3 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and post residual
            let nq = next_item_size * 4 / bin_capacity;
            if nq == q { score -= 8.0; }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here regardless; slight penalty for wasting slot
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= (bin_capacity as f64 - item_size as f64).max(0.0) * 0.35;
        if good_fit && next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 35.0;
        }
    }

    // Stream progression: later in stream, prefer tighter packing (larger residual penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    // Congestion: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Mean residual alignment: bins deviating far from mean residual are less attractive.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when residuals
    // are already low; encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large, reusable gap in an existing bin, or when no
    // decent fit exists (fitting bin leaves a dead gap).
    if bin_residual == bin_capacity {
        // Baseline competitiveness for a fresh bin.
        score -= 5.0;
        // Attractive when the current item is large (better to dedicate fresh space)
        if item_size >= 60 {
            score -= 12.0;
        }
        // Unattractive if there are several bins that fit with decent residuals.
        if fitting_bins_count > 1 {
            score += 18.0;
        }
        // Lookahead: if the next item is large, a fresh bin preserves room.
        if next_item_size >= 50 && post_residual == bin_capacity as u32 {
            score -= 8.0;
        }
    }

    // Slight preference for bins with residuals below the mean (use up the odd ones).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post_residual is already favored by base).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, strongly reward this placement (creates a perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item would not fit here: penalize leaving a gap smaller
            // than the next item (likely dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual relative to the mean residual of open bins:
    // leaving less than average residue is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize the new-bin candidate unless open bins are badly fragmented
    // or the item barely fits anywhere (encourage consolidation otherwise).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 120.0 - 40.0 * fragmentation - 20.0 * progress;
        // If the next item is large and current bins are tight, new bin is fine.
        if next_item_size >= 60 && mean_residual < next_item_size as f64 {
            score -= 60.0;
        }
    }

    // Mild penalty for wasting a large bin residual on a small item.
    score += 0.1 * (bin_residual.saturating_sub(item_size * 2)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize score by how well item fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is hard to reuse (small post_residual is good,
    // but very large post_residual wastes a bin).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect closure bonus
    }
    if post_residual > 60 {
        score += 10.0; // large leftover penalty
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            score += 8.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Global residual pressure: if mean residual is low, protect bins with big residuals
    // for future items; if mean residual is high, use this bin up.
    let t = step_index as f64 / total_items.max(1) as f64;
    let mean_diff = bin_residual as f64 - mean_residual;
    score += 0.1 * mean_diff * (1.0 - t);

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score += 12.0 + 25.0 * t - desperation - (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * (0.5 + t * t);
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * t);

    // Penalize waste relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual) * (0.5 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).abs()) * (0.5 + t);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Discourage opening new bins when many bins are already open and fit exists
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (open_bins_count as f64).sqrt() * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band do we land in?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fits are golden: heavy reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (1) don't exist,
    // but small residuals below the harmonic threshold are near-dead.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic classes: residuals divisible by common item sizes are reusable.
    // Reward if post_residual is a multiple of small harmonic bases (5, 10, 20, 25, 50).
    for base in [5u32, 10, 20, 25, 50] {
        if post_residual % base == 0 {
            score -= 8.0 * (base as f64 / 5.0);
        }
    }

    // Integer-division threshold: how many "average items" fit in the leftover?
    let avg_item = 40.0f64;
    let slots = (post / avg_item).floor();
    score -= slots * 12.0;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how tightly the next item fills this bin's remainder.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 40.0 * tightness;
        } else {
            // Next item cannot use this residual: penalize large residuals that will strand.
            score += (post / 10.0).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline; penalize opening new bins when
    // open bins exist with healthy residual and the item fits reasonably.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in the stream, opening bins is fine; later, be conservative.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * (1.0 - progress);
        // If many open bins already, discourage yet another.
        score += open_bins_count as f64 * 5.0;
    } else {
        // Prefer bins with residual close to the item (tight fit) — best-fit flavor.
        score += (bin_residual as f64 - item_size as f64) * 0.3;
        // Slight preference for bins below the mean residual (consolidate fuller bins).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Modulo phase coupling between item size and post residual (harmonic resonance).
    let phase = (item_size as i64 - post_residual as i64).rem_euclid(10) as f64;
    score += phase * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild new-bin aversion: opening a fresh bin should only win on poor fits.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact or near-exact match
    // between the post_residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual exactly consumed by next item
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            // Proximity bonus: closer gap -> bigger discount
            score -= 25.0 / (1.0 + gap);
        }
        // Penalize post_residual that is too small to fit the next item
        // (creates dead space relative to lookahead)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins; using them is good, leaving them is wasteful.
    let tightness = mean_residual - bin_residual as f64;
    score += 0.12 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item is large (poor fit elsewhere would waste more).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0; // large items are fine in fresh bins
        }
        // Early in stream, new bins are cheaper; later, consolidation wins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for bins that will end up very full (low post_residual)
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Slight penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

