    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        let mut new_bin_score = bin_capacity as f64 - 0.4 * item_size as f64;
        // Exploration bonus early, penalty later.
        new_bin_score += 10.0 * (1.0 - progress);
        // Penalize opening new bins when many open bins already exist late.
        new_bin_score += 0.3 * open_bins_count as f64 * progress;
        score = new_bin_score;
    } else {
