        if bin_residual > 0 {
            score += 0.2 * ((bin_residual - item_size) as f64 / bin_residual as f64).abs();
        }
    }

    // Global state coupling: high mean residual -> can afford looser fits;
    // low mean residual -> pack tighter.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight preference to keep the number of open bins manageable.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 0.35 * post * (1.0 - progress) + 0.25 * post * post / cap * p2 + 0.15 * post * p3;
    score += poly;

    // Tight-fit reward: near-zero post residual is excellent
    let tight = (1.0 - post / cap).powi(4);
    score -= 12.0 * tight;

    // Penalize dead space that no small item can fill
    let waste = post * post / cap;
    score += 0.6 * waste * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit: slight penalty proportional to wasted opportunity
        score += 2.0 * (1.0 - post / cap);
    }

    // Many open bins: prefer filling existing ones over spreading
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.4 * (post / cap) * crowd.min(10.0);

    // New-bin candidate: make empty bin mildly attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score = post + 8.0 - 6.0 * progress - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that lie in "useful" bands
    // (multiples of common small item sizes / capacity fractions).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is always excellent
    } else if pr % 10 == 0 {
        -18.0 // residual in multiples of 10 is reusable by small items
    } else if pr % 5 == 0 {
        -9.0
    } else if pr >= 10 {
        -2.0
    } else {
        25.0 // tiny dead space (<10) is unusable
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: how many minimum items fit?
    let fits_small = pr / 10;
    score -= 4.0 * fits_small as f64;

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + 0.3 * (next_item_size as f64);
            // harmonic match: next item exactly consumes residual classes
            if pr % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            score += 10.0 + 0.2 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless stream is early
    // or current fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        score += 35.0 - 20.0 * (1.0 - progress) - openness.min(8.0) * 2.0;
        // opening a fresh bin wastes nothing, but discourage when open bins fit well
        if post_residual as f64 >= cap * 0.2 {
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer fuller bins: fraction of bin already used.
    let used_frac = 1.0 - (bin_residual as f64) / cap;
    score -= 15.0 * used_frac;

    // Late-stream pressure: consolidate harder as stream progresses.
    score -= 8.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

