        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * post_residual as f64;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 8.0 + 10.0 * (1.0 - progress) + 2.0 * crowded;
        // If item fits snugly in the fresh bin and no better option, new bin is fine.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 10.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling fatter bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild preference for keeping fewer open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr;

    // Smooth polynomial penalty on dead space, amplified as stream progresses.
    let dead = norm_pr * norm_pr;
    score += dead * (20.0 + 60.0 * progress * progress);

    // Reward tight fits (low post residual) more strongly later in the stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (5.0 + 25.0 * progress);

    // Last-chance bonus: strongly favor this bin if it is the only one that fits.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Coupling with mean residual: prefer bins near the mean (keeps flexibility).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: penalize if post residual is too small for the next item
    // but reward if it perfectly accommodates it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // New-bin candidate: mildly penalize early, allow later when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 15.0 - 25.0 * progress * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that align with common
    // item sizes (multiples of 10 and halves of capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Residuals that are exact multiples of 10 are highly reusable.
    if post % 10 == 0 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Fractional-capacity classes: residuals equal to quarter/half/three-quarters
    // of capacity are prime targets.
    if post == half {
        score -= 10.0;
    } else if post == quarter || post == 3 * quarter {
        score -= 7.0;
    }

    // Dead-space penalty: tiny residuals (below smallest plausible class) are waste.
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Integer-division coupling: does post_residual's class match next_item_size's class?
    if next_item_size > 0 {
        let post_class = post / 10;
        let next_class = next_item_size / 10;
        if post >= next_item_size {
            score -= 8.0;
            // Exact class match: next item fits perfectly into the residual class.
            if post_class == next_class {
                score -= 6.0;
            }
            // Perfect closure: next item exactly fills the bin.
            if post == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 5.0 + (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when the stream is early and
    // open bins exist; reward it slightly late in the stream (consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight fit bonus: leaving very little behind is excellent.
    if post == 0 {
        score -= 25.0;
    }

    // Mean-residual coupling: bins far from the fleet mean are either hoarders or
    // nearly full; prefer bins whose residual is close to the mean (balanced use).
    let dev = (post as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Prefer filling fuller bins (smaller residual) mildly.
    score += (post as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for the smallest plausible item (>0 but tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the lookahead item (wasted for the next step).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: exact fill is best.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Mild bonus for placing into bins below mean residual (balancing residuals).
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for filling fuller bins as the stream progresses.
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 + step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        // Reward bins whose post-residual matches the next item size (perfect 2-step chain)
        score -= 25.0 * (1.0 - diff / cap);
        // If the next item will NOT fit here, penalize proportionally to the gap
        if post < nxt {
            score += 0.15 * (nxt - post).min(cap);
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Loose fits (above mean residual) waste space: penalize gently
    if post > mean_residual {
        score += 0.10 * (post - mean_residual);
    } else {
        // Tighter-than-average fits get a small extra reward
        score -= 0.05 * (mean_residual - post);
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Base waste penalty for ignoring existing open capacity
        score += 20.0 + 10.0 * fitting_bins_count as f64;
        // Large items waste less when placed in a fresh bin
        score -= 0.05 * item_size as f64;
        // Relieve penalty if the fresh bin yields a perfect 2-step match
        if next_item_size > 0 && (post - nxt).abs() < 1e-9 {
            score -= 30.0;
        }
    }

    // --- Last-chance bonus: sole fitting open bin should beat opening a new bin ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // --- Late-stream consolidation: near the end, prefer tightest closures ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if next_item_size == 0 || progress > 0.9 {
        score += 0.05 * post; // extra pressure toward minimal dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already the base score.

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small for typical future items,
        // scaled by stream progress (late in stream, dead space matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual < 10 {
            score += 30.0 * (0.5 + progress);
        } else {
            score += (post_residual as f64) * 0.15 * (0.5 + progress);
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer any fit, close bins fully.
        score -= 20.0;
    }

    // Last chance: this is the only open bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 25.0;
    }

    // Many open bins: prefer filling existing bins rather than spreading.
    score += open_bins_count as f64 * 0.5;

    // Compare against mean residual: bins with residual far above mean are
    // better candidates for absorbing this item.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.1;

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream
        // (fewer future conflicts) and when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin can hold both this and next item comfortably.
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += poly * 6.0 * norm_pr * norm_pr * cap * 0.05;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap * cap * (0.5 + 0.5 * poly);
        } else {
            // Reward residual that nicely fits next item
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 4.0 * fit_quality * poly;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + poly);
    }

    // New-bin candidate handling: penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += (2.0 + 6.0 * (1.0 - poly)) + 0.3 * open * poly;
        // If item is huge relative to capacity, new bin is fine
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Reward tight fits (small post residual) more as stream progresses
    score -= poly * 3.0 * (1.0 - norm_pr);

    // Coupling with mean residual: prefer bins deviating from mean to balance
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev * cap * 0.1 - 1.0 * dev * (1.0 - poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Penalize leftovers by class: mid-size leftovers (eighth..half) are dead space
    if post_residual > 0 {
        if post_residual <= eighth {
            score -= 6.0; // tiny leftover is fine
        } else if post_residual < quarter {
            score -= 2.0;
        } else if post_residual < half {
            score += 10.0; // worst class: awkward mid residual
        } else {
            score -= 4.0; // large leftover reusable
        }
    }

    // Modulo coupling: post_residual divisible by common item sizes is more usable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        } else if post_residual % 2 == 0 {
            score -= 0.5;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use leftover: penalize proportionally to waste
            score += (next_item_size.saturating_sub(post_residual)) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer tight fits overall
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_tightness * 5.0;

    // New-bin candidate handling: only attractive when no good open option / early stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64;
        // Opening new bin is penalized more when many bins open or mean residual is large
        score += 18.0 + crowding * 1.5 + mean_residual * 0.1 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0; // fresh bin can serve next item too
        }
    }

    // Mild dispersion penalty: avoid draining bins far below mean residual
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps smaller than the smallest plausible item (or next item).
    let min_useful = next_item_size.max(1) as f64;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // Dead space that can't fit the next item is wasted forever.
        score += 40.0 + 0.5 * (min_useful - post_residual as f64);
    } else if post_residual > 0 {
        // Reward leaving a gap that exactly accommodates the lookahead item.
        let gap_diff = (post_residual as f64 - min_useful).abs();
        score -= 8.0 * (1.0 - gap_diff / bin_capacity as f64).max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual is far below the mean residual (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a new bin costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * fill_ratio;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that
            let second_residual = post_residual - next_item_size;
            score += second_residual as f64 * 0.3;
            if second_residual == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: penalize wasted residual relative to mean
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.4;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        // base penalty so new bins are used only when worthwhile
        score += 30.0;
        // if no other bin fits, this penalty is effectively removed
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // early in stream, allow more new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Slight preference for tighter bins when many bins are open
    score += (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead: if the next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // Dead space risk: penalize residuals that no plausible item can use.
        score += 0.08 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full
    // or the item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score = 60.0
            - 40.0 * mean_fullness
            - 10.0 * progress
            - if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
    }

    // Slight penalty for proliferating open bins when residuals are large.
    if open_bins_count > 4 && mean_residual > 40.0 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: residual squared scaled by stream progress
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64 * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual) non-linearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item could have fit better elsewhere / in this residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post_residual as f64 {
            // dead space relative to next item
            score += 0.15 * (nxt - post_residual as f64);
        } else {
            // next item fits in residual: reward chain packing
            score -= 4.0 * (1.0 - (nxt / post_residual as f64)) * (1.0 - progress);
        }
    }

    // Penalize opening a new bin (residual == capacity) unless few alternatives
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
    score += is_new_bin * (20.0 + 15.0 * progress) * scarcity;

    // Mild penalty if this bin is much emptier than average (waste of a large bin)
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Encourage consolidation as stream progresses: favor bins with less residual
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (minimize score).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: residual classes by capacity/8 (12 or 13 wide classes).
    // Reward when post_residual falls into a "harmonic" class that pairs well
    // with common item sizes (items 1..100, so small residuals are reusable).
    let class = (post_residual / 13) % 8;
    score -= (7 - class) as f64 * 3.0; // lower class (smaller residual) is better

    // Dead-space penalty: residuals that no plausible item (>=1) can use are fine,
    // but residuals just above small items create awkward gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver residual = nearly dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 100.0; // near-perfect chaining
            }
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize wasting large residuals
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base new-bin score: current item's footprint as residual cost.
        score = (bin_capacity - item_size) as f64;
        // Prefer keeping bins open when mean residual is large (bins still usable).
        score += mean_residual * 0.8;
        // Early in stream, opening new bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 30.0;
        // Never open a new bin when a perfect fit exists elsewhere is handled by
        // the -1000 on existing bins; add mild penalty to avoid premature opening.
        score += 40.0;
        // If next item is large and current item is small, new bin wastes capacity.
        if next_item_size >= item_size * 2 {
            score += 15.0;
        }
    }

    // Mild preference for filling bins with larger residual first (best-fit-like),
    // scaled by how many alternatives exist.
    score += (bin_residual as f64) * 0.05;

    // Tie-break: fewer open bins is better.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (1..=100 interface, min item 1) are worthless.
    // Penalize unusable gaps hard; treat post_residual <= 12 as near-dead.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual <= 12 {
        score -= 25.0; // effectively sealed bin, great
    } else if post_residual < item_size.min(20) {
        // gap smaller than typical next item -> likely dead space
        score += 18.0;
    }

    // Reward tight fits: residual consumed as a fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 35.0;
        } else if leftover <= 12 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover -> dead space risk
        score += 10.0 * (next_item_size as f64 / post_residual as f64).min(2.0);
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual
    // is still healthy; encourage consolidation.
    score += (open_bins_count as f64) * 1.5;
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge flexibility; penalize
    // it mildly so decent fits into open bins win, but let it win when the
    // alternative wastes most of an open bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // later in the stream, prefer filling existing bins even more
        score += 20.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Mild stream progression: early on, keep bins flexible (favor emptier
    // placements); later, maximize filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = (post_residual as f64) - nxt;
            // Perfect chain match: strong reward.
            if slack == 0.0 {
                score -= 60.0;
            } else if slack <= 10.0 {
                score -= 40.0 - 2.0 * slack;
            } else {
                // Next item fits but leaves big gap: mild penalty scaled by gap.
                score += 0.15 * slack;
            }
        } else {
            // Next item cannot use post_residual: dead space risk grows with gap.
            let gap = (post_residual as f64) - nxt;
            score += 0.5 * gap.abs();
        }
    } else {
        // Last item: prefer tightest fit (small post_residual).
        score += 0.1 * (post_residual as f64);
    }

    // Penalize post_residual that is unusably small (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are better targets
    // for large items; below-mean bins should be filled tightly.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.2 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * (bin_capacity as f64);
        if poor_fit {
            // Opening fresh is fine for very large items.
            score -= 5.0;
        } else {
            score += 40.0;
        }
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Slight preference to keep number of open bins small when many are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward near-zero post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize post_residual that is small but unusable by the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with lower-than-mean residual (denser bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more willing to consolidate into open bins;
    // late in the stream, keep flexibility for remaining items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when many bins are open but sparse.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // A fresh bin is attractive if the next item pairs well with the current one.
            if item_size + next_item_size <= bin_capacity {
                score -= 10.0;
            }
        }
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * (1.0 - progress) * norm_pr * norm_pr);

    let mut score = poly * cap;

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly prefer using a bin if it's the only one that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting space when next item could use the residual
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * waste;
        // Reward residual that exactly accommodates next item
        if next_item_size as u32 == post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: minimize residual directly
        score += 0.5 * pr;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But allow new bins early in stream
        score -= 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins that deviate from mean residual to balance
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" fractions of capacity (multiples of 5, 10, 20, 25)
    // are more reusable; penalize awkward residuals.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            // awkward residue: penalize more as it deviates from multiples of 5
            let dev = (pr % 5) as f64;
            score += dev * 0.8;
        }
        // Dead-space threshold: tiny unusable residuals are terrible
        if pr < 10 {
            score += 15.0;
        }
        // Integer-division harmonic classes: pr / 25 tiers
        let tier = pr / 25;
        score -= tier as f64 * 2.5;
    } else {
        // Perfect fill — best possible outcome
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect next fit
        } else if next_item_size < pr {
            let nxt_left = pr - next_item_size;
            // reward leaving room for next item, penalize bad leftover classes
            score -= 8.0;
            if nxt_left % 10 == 0 { score -= 4.0; }
            if nxt_left < 10 && nxt_left > 0 { score += 6.0; }
        } else {
            // next item won't fit here: mild penalty scaled by overflow amount
            let over = (next_item_size - pr) as f64;
            score += over * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a good fit. Give the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score = 55.0;
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
        // if open bins are already fragmented, discourage another bin
        score += open_bins_count as f64 * 1.2;
        // if mean residual is large, an open bin likely fits well
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // small next item still fits an empty bin nicely
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Tightness reward: bins that end up nearly full are good
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * fill_frac * 10.0;

    // Slight preference for bins tighter than the average residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat gaps < 10 (min item) as fully dead; gaps < 20 as partially dead.
    let dead = (10u32.saturating_sub(post_residual.min(10))) as f64;
    score += 6.0 * dead;

    // Partial dead-space: gap that can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 * (open_bins_count as f64).sqrt();
        // But allow new bin early in stream or when existing residuals are large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0; // existing bins have room; don't open new
        }
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance usage).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
