    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 / (1.0 + diff);
        // Penalize leaving residuals that are too small for any future item (dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 60.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when plenty of open bins exist and residual is generous.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference for tighter packing as stream progresses.
    score += 0.1 * (post_residual as f64) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can fill (items >= 1).
    // If post_residual is small but nonzero, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large awkward residual.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
