    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening yet another.
    if open_bins_count > 2 {
        score -= 4.0 * (open_bins_count.min(20) as f64) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing residuals are all small.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * item_frac;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If mean residual across open bins is small, new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: reward small post-residual (tight fit) with smooth non-linear shaping.
    let mut score = pr;

    // Polynomial coupling: post-residual interacts with stream progress.
    // Early on, moderate waste is tolerable; late, waste is heavily penalized.
    let waste_penalty = pr * pr / cap * (0.5 + 1.5 * progress);
    score += 0.8 * waste_penalty;

    // Reward perfect-ish fits (post residual near zero) with a smooth dip.
    score -= 12.0 * (1.0 - x).powi(3) * (1.0 + progress);

    // Penalize large dead space (x near 1) super-linearly, worse late in stream.
    score += 25.0 * x.powi(3) * (0.6 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr;
            // smooth reward peaking when next item consumes most of remaining space
            score -= 20.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += 0.05 * (nxt - pr);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // Prefer new bin only when the item is large relative to capacity
        // and existing residuals are already tight (mean residual small).
        let item_frac = item_size as f64 / cap;
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let openness = 1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // Baseline cost of opening a bin, discounted when beneficial.
        score = cap * (1.0 - item_frac) * (1.0 - 0.5 * tightness) + 30.0 * openness;
        // Early in the stream, opening bins is cheaper; late, expensive.
        score += 40.0 * progress * (1.0 - item_frac);
    } else {
        // Mild global pressure: more open bins -> prefer packing into existing ones.
        score -= 0.5 * (open_bins_count as f64).sqrt();
        // Slight preference for bins whose residual is above average (balance).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals in fine-grained classes (multiples of 10) are more likely to
    // accept future items; odd/small fragments are dead space.
    let frag = post_residual % 10;
    score += (10 - frag) as f64 * 0.35; // penalize ragged residuals

    // Class A: residual divisible by 10 -> highly reusable leftover.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: residual divisible by 5 but not 10 -> moderately reusable.
    if post_residual % 10 != 0 && post_residual % 5 == 0 {
        score -= 2.5;
    }
    // Class C: tiny unusable fragment (< 10) -> heavy dead-space penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / 20.0).max(0.0);
        } else {
            // next item does not fit here: leftover must serve later items;
            // scale penalty by how much it overshoots.
            let over = (next_item_size - post_residual) as f64;
            score += 0.25 * over.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit here would be awful.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let bad_fit = post_residual as f64 > 50.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if bad_fit && crowding > 8.0 {
            score -= 5.0 + crowding * 0.3;
        } else {
            score += 25.0 + crowding * 0.5;
        }
    }

    // Prefer filling bins with low residual relative to the fleet mean
    // (keeps residual distribution harmonic, avoids many half-empty bins).
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.15;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    // Late in the stream: tighten packing, favor exact closures more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - res_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space trap: residuals in (0, 10) can never be filled (min item = 1 here,
    // but very small gaps are statistically unusable). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but fillable gaps: mild penalty unless next item fits exactly.
        if next_item_size > post_residual {
            score += 15.0;
        } else if next_item_size == post_residual {
            score -= 40.0; // perfect lookahead fit: strongly reward
        } else {
            score += 5.0;
        }
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Pressure from open bins count: more open bins -> discourage new bins.
        score += 4.0 * open_bins_count as f64;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Open-bin pressure: with many open bins, favor placements that consolidate.
        score += 0.3 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        if diff == 0.0 {
            score -= 45.0; // exact chain fit
        } else if post < nxt {
            // dead space relative to lookahead: penalize proportionally
            score += 12.0 * (1.0 - post / nxt);
        } else {
            // post >= next: reward closeness to exact match
            score -= 20.0 * (1.0 - diff / nxt);
        }

        // Two-step chain: post_residual could hold next item and leave usable space
        if post >= nxt {
            let chain_left = post - nxt;
            if chain_left == 0.0 {
                score -= 10.0;
            } else if chain_left < 10.0 {
                score += 8.0; // tiny unusable fragment after chain
            }
        }
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) relative to bin capacity
    score -= 15.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Compare against mean residual: prefer bins that are already below-average residual
    // (more filled bins get priority), penalize using bins with above-average space for small items
    if (post_residual as f64) > mean_residual {
        score += 6.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when it enables a good future fit
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) as f64 <= next_item_size as f64 {
            // opening new bin yields perfect lookahead fit
            score -= 22.0;
        } else {
            // discourage opening new bins when open bins fit fine
            score += 18.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild stream-progression pressure: later in stream, tighten packing more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Lookahead (k=2): if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 3.0 * next_fit_quality;
    }
    // If next item cannot fit here, mild penalty proportional to wasted potential.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Penalize very small post_residuals that create unusable dead space,
    // unless next_item_size can use it.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        if post_residual < 10 {
            score += 6.0;
        } else if post_residual < 20 {
            score += 2.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    }

    // New-bin candidate logic: empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins and stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 15.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) + 5.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_cost += 0.05 * mean_residual;
        // If item is large, new bin gives more room for follow-ups; soften cost.
        new_bin_cost -= 0.05 * (item_size as f64);
        // If no open bin can fit (fitting_bins_count==0 for open bins), new bin is necessary.
        if fitting_bins_count == 0 {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    // Slight global-state coupling: prefer spreading load when many bins are open with high mean residual.
    if bin_residual < bin_capacity {
        score += 0.02 * (mean_residual - bin_residual as f64).abs();
    }

    // Time-horizon modulation: early in the stream, be more conservative (prefer filling existing bins);
    // late in the stream, allow slightly more aggressive tight-fit chasing.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual

    // Base: quadratic in post residual, modulated smoothly by progress.
    // Early stream: prefer tight fits (low post residual) mildly.
    // Late stream: tighten preference more strongly.
    let mut score = r * (1.0 + 1.5 * progress) + 40.0 * rn * rn * (1.0 + progress);

    // Non-linear coupling: post_residual interacts with mean residual across bins.
    // If this bin's residual is far below mean, it's a "cramped" bin -> reward using it.
    let dev = (mean_residual - r) / cap;
    score -= 12.0 * dev * (1.0 + progress);

    // Penalize dead space that no future item (sizes 1..100, unknown) can plausibly fill:
    // smooth penalty growing when post_residual is in a mid-range "awkward" zone.
    let awkward = rn * (1.0 - rn); // peaks at rn = 0.5
    score += 25.0 * awkward * (1.0 - 0.5 * progress);

    // Last chance: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead (k=2): if next item fits exactly into post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - perfect / cap);
    }
    // If next item cannot fit into post residual, mild penalty for wasting space.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0 * (1.0 - rn);
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins are heavily fragmented and item is large,
        // or when few bins fit the item.
        let fragmentation = mean_residual / cap;
        let urgency = (item_size as f64 / cap) * (1.0 + 2.0 * (1.0 - fitting_bins_count as f64 / (fitting_bins_count.max(1) + 2) as f64));
        score = 55.0 + 45.0 * fragmentation - 40.0 * urgency + 20.0 * progress * fragmentation;
        // Late in stream, opening new bins is less costly than fragmenting.
        if progress > 0.7 {
            score -= 15.0 * (progress - 0.7);
        }
    } else {
        // Mild penalty when many bins are open (discourage bin proliferation).
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: mod-10 buckets ---
    let post = post_residual as i64;
    let class = post % 10;
    // Dead-space penalty: residuals that are small and awkward (1..=9 mod 10)
    // are hard to fill later; residuals that are exact multiples of 10 or 25
    // are "harmonic" and easy to reuse.
    if post > 0 {
        if class == 0 {
            score -= 6.0; // perfectly harmonic residual
        } else if class == 5 {
            score -= 3.0;
        } else if class <= 3 {
            score += (10 - class) as f64 * 1.5; // tiny awkward sliver
        }
    }

    // --- Integer-division thresholds on post_residual ---
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter && post_residual > 0 {
        score += 8.0; // creating a sub-quarter dead zone is bad
    } else if post_residual >= (3 * quarter) {
        score -= 4.0; // leaving a big reusable cavity is good
    } else if post_residual > half {
        score -= 2.0;
    }

    // --- Perfect fits ---
    if post_residual == 0 {
        score -= 25.0; // bin closed exactly: ideal
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: strong reward, scaled by snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + slack * 0.05;
            // harmonic bonus if next item leaves a multiple of 10 too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item will NOT fit here; penalize if this bin becomes a dead bin
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.08;
        }
    } else {
        // last item: just close bins tightly
        score -= 5.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0; // only bin that fits: avoid opening a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: attractive early when few bins open, unattractive
        // when many open bins already have usable residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_f = open_bins_count as f64;
        let waste = mean_residual / (bin_capacity as f64);
        score = 40.0 * (1.0 - progress) + open_f * 3.0 + waste * 10.0;
        // Never open a new bin when a perfect/harmonic fit exists elsewhere;
        // that is handled by those bins getting large negative bonuses.
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // nothing fits anywhere anyway
        }
    }

    // --- Mild preference for tighter bins overall ---
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score -= (bin_capacity - bin_residual) as f64 * 0.02; // fuller bins favored

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item size are unusable -> heavy penalty proportional to wasted space.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Zero residual is a perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2) after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for a near-exact match with the next item.
        let gap = post_residual - next_item_size;
        score -= (20 - gap.min(20)) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use -> penalize, harder for small gaps.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is relatively cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 4.0;

    // Prefer bins whose residual is already below average (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    // New-bin candidate: penalize moderately so it is only chosen when no open bin
    // gives a decent fit (tight fits and last-chance bins beat it).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, new bins are more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty on dead space: squared residual normalized by capacity
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward exact match between post_residual and next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect fit for the next item: chain placement
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to tightness
            let tightness = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 40.0 * tightness;
        } else {
            // Next item cannot fit here: penalize, worse if gap is small (near-miss)
            let gap = next_item_size - post_residual;
            score += 20.0 + 0.5 * gap as f64;
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer more-filled bins early-to-mid stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: only attractive when existing bins would leave huge waste
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin; beat it only if best open fit is bad
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that can never hold a typical next item.
    if next_item_size > 0 {
        let dead = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.6 * dead;
        // Bonus if the next item fits exactly into the post residual.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Global fragmentation pressure: prefer bins below mean residual (consolidate slack).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, be more conservative with new bins and
    // favor tighter packing; early on, allow more exploration.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tightness;
    if bin_residual == bin_capacity {
        score += 20.0 * t;
    }

    // Mild penalty for very small post-residuals that waste capacity unless exact.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Quadratic penalty on large post-residual (dead space), modulated by progress
    let norm_post = post / cap;
    score += 20.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: item nearly fills residual
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits post-residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - post) / cap;
    }

    // Smooth interaction: post_residual x progress polynomial
    score -= 8.0 * (1.0 - norm_post) * progress * (1.0 - progress) * 4.0;

    // Penalize spreading across many open bins with large mean residual
    score += 3.0 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: mod-10 buckets punish awkward dead space
    let post_mod = post_residual % 10;
    if post_residual > 0 {
        score -= 6.0 - (post_mod as f64); // residuals ending near 9 are more reusable
        if post_mod == 0 {
            score -= 8.0; // perfectly aligned residual (e.g. 50, 60, 70) is prime
        }
    } else {
        score -= 40.0; // perfect closure is best
    }

    // Integer-division thresholds: residual that can host common size classes
    let half = (bin_capacity / 2) as f64;
    if post >= half {
        score -= 12.0; // still "half-open", very valuable
    } else if post >= (bin_capacity / 3) as f64 {
        score -= 6.0;
    } else if post < 10.0 && post > 0.0 {
        score += 15.0; // tiny dead strip
    }

    // Lookahead coupling: does the residual fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when current bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) * (mean_residual / cap);
        // prefer new bin if existing residuals are small and many bins open
        score += 30.0 - congestion * 3.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 6.0; // pairing big item into fresh bin helps lookahead
        }
    }

    // Mild tight-fit bonus: waste = residual - item, already in `post`,
    // but reward near-exact fills relative to item size
    score -= (item_size as f64) * 0.05;

    // Mean-residual context: if this bin is far below mean, it's the "worst" bin -> use it
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 {
        // A gap is "dead" if the smallest plausible item (1) still wastes it,
        // but practically we treat gaps < 10 as unusable dead space.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 12.0;
        }
        // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // Perfect fit bonus: reward zero-waste placements strongly.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin residual (relative waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual != bin_capacity {
        // Existing bin: subtract pressure-scaled bonus to favor reuse.
        score -= 3.0 * pressure * (0.5 + 0.5 * progress);
        // Extra urgency when this bin is the last chance to fit the item.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    } else {
        // New-bin candidate: penalize opening bins, more when many are open.
        score += 5.0 + 2.0 * pressure;
        // Late in the stream, opening new bins is especially wasteful.
        score += 20.0 * progress;
        // If no existing bin leaves a good residual, new bin is less bad.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is close
    // to the item (keeps the fleet of open bins homogeneous).
    let dev = (mean_residual - bin_residual as f64).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in stream -> be tighter about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: perfect or near-perfect match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 50.0 + 30.0 * progress; // exact fit for next item
        } else if next_item_size <= post_residual {
            // next item still fits after this placement: strong bonus
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64) * (0.5 + progress);
        } else {
            // next item won't fit here afterwards: mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over.min(60.0);
        }
    }

    // Penalize dead space that no plausible item (>=1) can use; waste is worst late.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * (4.0 + 8.0 * progress);
    }

    // Relative-to-mean residual shaping: prefer bins whose residual deviates
    // usefully from the mean (tighten outlier bins, keep roomy bins roomy).
    let cap = bin_capacity as f64;
    let rel_mean = mean_residual / cap;
    let rel_post = post_residual as f64 / cap;
    score += 3.0 * (rel_post - rel_mean);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (high mean residual usage would be wasted) or
    // the stream is early and future flexibility matters.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let poor_fit = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).clamp(0.0, 2.0)
        } else { 1.0 };
        // New bin cost grows with number of open bins and shrinks when open bins fit badly.
        score += 12.0 + 0.6 * crowd - 10.0 * (poor_fit - 1.0) - 8.0 * (1.0 - progress);
        // If next item is large and would fit nicely in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize dead space that cannot fit even the smallest plausible item
    if post_residual < next_item_size && next_item_size > 0 {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Lookahead synergy: residual after placement that fits next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins relative to mean residual of open bins
    score += 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, consolidate into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate
        let early_bonus = (1.0 - progress) * 20.0;
        score -= early_bonus;
        // Penalize new bins when many bins are already open late in stream
        score += 0.05 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= progress * 5.0;
    }

    // Mild preference for bins whose residual is close to item size (best fit)
    let gap = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: smooth quadratic coupling of post_residual with capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that the next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0) / cap;
        score += 25.0 * waste * waste * (1.0 + progress);
        // Bonus if post_residual exactly accommodates next item.
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 12.0 * snug * snug;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: penalize proportional to how well existing bins cluster.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 0.05 * open_bins_count as f64 * mean_residual.max(0.0) / cap;
        // Late in stream, prefer closing out open bins rather than expanding.
        score += 25.0 * progress * progress;
    } else {
        // Slight preference for bins below mean residual (consolidate slack).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes are more reusable, so reward them (subtract from score).
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 50.0;
    } else {
        // Reusability dividend: how many "harmonic" divisors (10..=50) divide pr.
        let mut divisors = 0u32;
        for d in [10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                divisors += 1;
            }
        }
        score -= 4.0 * divisors as f64;

        // Dead-space penalty: small, non-harmonic residuals are wasted space.
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 && pr % 10 != 0 {
            score += 12.0;
        }

        // Coupling with lookahead: if next item fits exactly into post_residual,
        // strongly reward; if next item cannot ever fit post_residual, penalize.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0;
            } else if next_item_size < pr {
                // fraction of post residual consumed by next item
                let frac = next_item_size as f64 / pr as f64;
                score -= 10.0 * frac;
                // harmonic match: next item divides post residual evenly
                if pr % next_item_size == 0 {
                    score -= 8.0;
                }
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin when open bins fit well,
    // but allow it when existing residuals are fragmented relative to item.
    if bin_residual == bin_capacity {
        score += 20.0;
        // more willing to open new bins early in the stream (future flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if current item is large and mean residual is low, new bin is fine
        if (item_size as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // Mild pressure against bin sprawl: many open bins -> prefer consolidation.
    score += 0.05 * open_bins_count as f64;

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual (capacity-fraction logic).
    if bin_residual > 0 {
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 1000.0; // impossible gap (defensive)
        }
        // Dead space that cannot fit the smallest plausible item is heavily penalized.
        // Items can be as small as 1, so any gap >= 1 is technically usable, but
        // tiny gaps relative to typical item sizes are practically dead.
        let typical = 40.0f64;
        let gap_ratio = post_residual as f64 / typical;
        if gap_ratio < 0.25 {
            score += (0.25 - gap_ratio) * 120.0; // near-dead gap penalty
        }
        // Perfect fit is gold.
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual <= 5 {
            score -= 80.0; // near-perfect fit, effectively sealed
        }
    }

    // Reward residual that can host the lookahead item (chaining fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 25.0; // gap blocks the next item: dead-end risk
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> prefer tightening existing ones
    // and discourage opening new bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when mean residual is very tight.
        let threshold = 12.0 + pressure * 2.0;
        score += 90.0 + threshold; // default penalty for opening a new bin
        if mean_residual < 8.0 && open_bins_count > 2 {
            score -= 110.0; // existing bins are nearly full: open a fresh one
        }
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 20.0;
        score += pressure * 1.5;
    }

    // Early stream: be slightly more liberal with new bins to build structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Next item fits into the post-residual: strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: post-residual too small for the lookahead item.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize leaving very small unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild bias toward filling bins early in the stream; later, prefer tight fits
    // and allow opening fresh bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Opening a new bin: neutral-ish baseline; encourage when current fit is bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it if placing here would waste a lot,
        // or if the item nearly fills a fresh bin.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if post_residual > 0 && post_residual < 10 {
            score -= 90.0; // near-perfect fill of a new bin
        } else if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0; // poor fit anywhere -> fresh bin is fine
        } else {
            score += 40.0 * (1.0 - fill_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving tiny unusable slivers (dead space) that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for a chain: next item then still leaves useful space.
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score -= 4.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with slack -> consolidate into existing bins.
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= 2.0 * pressure;

    // Time horizon: early in the stream, be conservative (favor existing bins);
    // late in the stream, tight fits matter most (already covered by fill_ratio).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is genuinely bad (large item, poor fill ratios).
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is huge relative to typical residuals, opening
        // a fresh bin is more attractive.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: post residual, scaled by smooth non-linear progress coupling
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - progress) * 4.0);

    // Non-linear quadratic reward for tight fits (small post_residual)
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * tightness;

    // Cubic interaction: residual vs stream progress (prefer filling bins later)
    score -= 15.0 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Dead-space penalty: post_residual too small for typical next item
    if next_item_size > 0 && post_residual > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr) / cap;
        if waste > 0.0 {
            score += 40.0 * waste * waste * (0.5 + progress);
        } else {
            // next item fits: reward smooth
            score -= 10.0 * (pr / ns.min(cap)) * (1.0 - is_new_bin);
        }
    }

    // Last-chance bin bonus (avoid opening new bin when only one fits)
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize opening new bins when open bins have large mean residual
    score += is_new_bin * (mean_residual / cap) * 25.0 * (1.0 + progress);

    // Mild penalty for many open bins when creating more fragmentation
    score += (pr / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Smooth sigmoid-like adjustment for medium residuals (unusable zone)
    let mid = (pr / cap - 0.4) / 0.15;
    score += 8.0 * (mid * mid);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does it fall into?
    // Residuals in the smallest bands (near 0) are "dead space"; penalize them.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual < sixteenth {
        score -= 25.0; // nearly perfect: tiny sliver, acceptable
    } else if post_residual <= eighth {
        // 7..13: hard-to-fill dead zone for unknown future items
        score += 18.0;
    } else if post_residual < quarter {
        // 14..24: mid dead zone
        score += 8.0;
    } else if post_residual == quarter {
        // exact quarter: harmonically useful class
        score -= 12.0;
    } else if post_residual < quarter * 2 {
        score += 2.0;
    } else if post_residual == quarter * 2 {
        score -= 10.0; // exact half: many item sizes fit later
    }

    // Modulo-10 harmonics: residuals that are multiples of 10 align with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Residuals that are multiples of 5 but not 10: semi-compatible
    else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does next_item_size fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // guaranteed perfect follow-up placement
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < sixteenth {
                score -= 20.0; // near-perfect two-item chain
            } else if nxt_post <= eighth {
                score += 6.0; // chain leaves a dead sliver
            }
            // fractional fit quality of the lookahead
            let fit_frac = next_item_size as f64 / post_residual as f64;
            if fit_frac > 0.7 {
                score -= 8.0 * fit_frac;
            } else if fit_frac < 0.3 {
                score += 4.0 * (1.0 - fit_frac);
            }
        } else {
            // next item cannot fit here regardless; slight penalty for blocking it
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin gets neutral baseline;
    // make it attractive only when open bins are congested (low mean residual).
    if bin_residual == bin_capacity {
        score = 0.5 * cap;
        // congestion: if mean residual of open bins is small, opening fresh is good
        if mean_residual < 0.2 * cap {
            score -= 15.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage opening yet another
        score += 3.0 * open_bins_count as f64;
    }

    // Small global tie-breaker toward tighter fits (smaller post_residual already dominates)
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 40.0 * (10 - pr) as f64; // hardest dead space penalized most
    } else if pr == 0 {
        score -= 30.0; // perfect fit strongly rewarded
    } else if pr >= 10 && pr < 25 {
        score += 4.0; // mildly awkward gap
    }

    // Reward bins whose residual is "shaped" for the next item (lookahead coupling).
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 6.0; // this bin's leftover won't help the next item
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins with large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Prefer bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: neutral baseline, slightly favored early, penalized if open bins are tight.
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when only one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match: next item fits with small leftover after it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 12.0 - (after_next as f64) * 0.25;
    }

    // Penalize dead space that the next item cannot use, scaled by tightness.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += dead * 0.35;
        // If this is the last chance bin, avoid stranding space.
        if fitting_bins_count == 1 {
            score += dead * 0.25;
        }
    }

    // Reward tightening bins whose residual is far below the mean (good packing).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.08;
    }

    // Late in the stream, prefer closing bins out (lower residual priority).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && fitting_bins_count > 0 {
            let best_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            score += 20.0 + best_gap as f64 * 0.1;
        } else if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold the smallest plausible item.
    if post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose residual after placement can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 6.0 * chain_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (large item relative to mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let reluctance = 20.0 + 25.0 * (1.0 - progress) - 10.0 * pressure.min(3.0);
        score += reluctance.max(-5.0);
    } else {
        // Mild preference for filling bins that are already relatively empty
        // (consolidate waste into few bins).
        let emptiness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * emptiness;

        // Spread load when many bins are open (avoid over-concentrating).
        if open_bins_count > 8 {
            score += 0.05 * (open_bins_count as f64);
        }
    }

    // Global balance: prefer bins near the mean residual to keep residuals uniform,
    // easing future packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized residual
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with cubic coupling to progress
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * tight * (0.5 + progress);

    // Penalize residual that is too small to plausibly hold a future item
    let min_item = 1.0;
    let unusable = ((min_item - pr).max(0.0)) / cap;
    score += 40.0 * unusable * unusable;

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (1.0 - ((pr - nxt) / cap)) * (0.6 + 0.4 * progress);
        } else {
            score += 10.0 * (nxt / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + 12.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Mild diversity pressure: favor bins deviating from mean residual
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Smooth stream-progress coupling
    score += 8.0 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that cannot host
    // any plausible item (small sizes) is heavily penalized.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class boundaries via integer division thresholds on post_residual.
    let dead_class = post_residual / 10; // 0..10 harmonic buckets
    let dead_penalty = match dead_class {
        0 => 0.0,                                  // perfect fit
        1 => 1.5,                                  // 10..19 residual
        2 => 3.0,
        3 => 4.5,
        4 => 6.0,
        5 => 5.0,                                  // mid-range still usable
        6 => 4.0,
        7 => 3.0,
        8 => 2.0,
        9 => 1.0,
        _ => 0.0,                                  // nearly empty bin, fine
    };
    score += dead_penalty;

    // Reward when the next item fits exactly into the post-residual
    // (harmonic pairing between consecutive items).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Exact pairing (slack 0) is ideal; decay with slack.
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
            // Modulo harmony: next item divides into residual class nicely
            if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty scaled
            // by how far off (wasted harmonic slot).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.03 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter bins when many bins fit the item (best-fit pressure).
    if fitting_bins_count > 1 {
        let tightness = 1.0 - post_frac;
        score -= 2.0 * tightness * ((fitting_bins_count as f64).ln() + 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are
    // fragmented (high mean residual spread) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening new bins is good when existing bins are cluttered with
        // large residuals and few bins are open.
        let open_bias = (open_bins_count as f64).ln().max(0.0);
        let new_bin_score = 20.0 + 15.0 * fragmentation - 8.0 * (1.0 - progress) - 2.5 * open_bias;
        // If a perfect fit exists elsewhere, new bin should lose.
        if post_residual == 0 && bin_residual == bin_capacity {
            // this is the new-bin call itself; post_residual == capacity
        }
        score = new_bin_score;
        // Penalize new bin if next item could pair with current one in an open bin.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size.min(bin_residual) {
            score += 3.0;
        }
    }

    // Small tie-breaker on exact fills anywhere.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave a gap large enough to be reusable
    // (>= typical small item size), scaled by how reusable it is.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: bonus if the post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to the known next item
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.35 + 0.65 * progress);

    // Prefer bins with below-average residual (tighter bins first),
    // i.e. reward this bin if its residual is smaller than the mean.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.4;

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // would create severe dead space; the pressure term above scales this
    // with stream progression and open-bin count.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // ideal: bin closed exactly by next item
        } else if post_residual > next_item_size {
            // next item still fits: reward tight remaining slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item will NOT fit: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * gap / 20.0;
        }
    }

    // Penalize small unusable residuals (dead space), except exact matches
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins with less slack than average are
    // better candidates (fill tight bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item leaves a large, reusable residual (i.e., current bins fit badly).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_here = (bin_capacity - item_size) as f64;
        let open_pressure = open_bins_count as f64;
        // Penalize new bins mildly; more when many bins are open (fragmentation risk)
        score += 30.0 + 2.0 * open_pressure * (0.5 + progress);
        // But if item is small relative to capacity, new bin keeps big residuals:
        if waste_here > 40.0 {
            score -= 35.0;
        }
    }

    // Mild preference for keeping residual diversity: avoid leaving residuals
    // near the middle (hard to fill later).
    let pr = post_residual as f64;
    if pr > 20.0 && pr < 60.0 {
        score += 5.0 * (1.0 - ((pr - 40.0).abs() / 20.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect/near-perfect fills get a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space penalty: residuals too small for typical items are wasted.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 18.0 - 8.0 * t;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize leftovers that are just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 * (1.0 - openness) + 8.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, prefer closing out existing bins.
        score += 10.0 * t;
    }

    // Mild preference for bins below mean residual (balancing).
    score += 0.05 * (mean_residual - post_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: post residual, mildly discounted as stream progresses
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear coupling: polynomial in normalized post-residual
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0;
    score += 18.0 * poly * (1.0 + progress);

    // Perfect / near-perfect fit reward
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead: does post residual fit next item?
    if next > 0.0 {
        if next <= pr {
            let tight = (pr - next) / cap;
            score -= 12.0 * (1.0 - tight * tight) * (1.0 - 0.5 * progress);
        } else {
            score += 6.0 * ((next - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residuals near mean (harmonic packing)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Penalize opening new bins when many fit and residual is small
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild open-bin consolidation pressure
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are multiples
    // of common item-size classes (mod 10 buckets), since future items likely
    // match them.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        if class == 0 {
            score -= 12.0; // perfectly divisible residual: highly reusable
        } else if class <= 2 || class >= 8 {
            score += 6.0; // awkward sliver residual
        } else {
            score += 2.0;
        }
        // Harmonic coupling with next item: exact fit for the lookahead item
        if next_item_size > 0 {
            if pr == next_item_size {
                score -= 25.0; // post-residual exactly matches next item
            } else if next_item_size <= pr {
                let slack = pr - next_item_size;
                if slack % 10 == 0 {
                    score -= 8.0;
                } else {
                    score += slack as f64 * 0.15;
                }
            } else {
                score += 5.0; // next item cannot use this residual
            }
        }
    } else {
        score -= 30.0; // perfect closure: zero waste
    }

    // Integer-division thresholds on bin_residual
    let half = bin_capacity / 2;
    if bin_residual >= half {
        score -= 4.0; // roomy bin preferred
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        let tight_fit = if fitting_bins_count > 0 {
            (bin_capacity as f64 - mean_residual) / bin_capacity as f64
        } else {
            0.0
        };
        score += 20.0; // default: prefer reusing open bins
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0; // existing bins would leave unusable slivers -> open new
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big lookahead item benefits from fresh bin
        }
        let _ = tight_fit;
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.05;
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that nothing (>=10) can use are dead.
    // Penalize unusable gaps harshly, scaled by how "wasted" the bin is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Prefer leaving gaps that can accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // lookahead-friendly gap
        } else if post_residual > 0 {
            score += 6.0; // gap too small for lookahead -> likely dead space
        }
    }

    // Reward tight fits (small post_residual relative to bin size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open,
    // but allow it early in the stream or when residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        if fragmentation > 20.0 {
            score -= 10.0; // existing bins fragmented; new bin may help
        }
    } else {
        score -= open_bins_count as f64 * 0.5; // mild reward for using open bins
    }

    // Prefer bins with residual close to item size (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches of
    // post_residual with the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain fit: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize wasted space relative to the lookahead item.
            score += diff * 0.35;
            // Bonus if next item still fits in the post-residual (chainable).
            if post_residual >= next_item_size {
                score -= 12.0 * (1.0 - diff / (post_residual as f64 + 1.0));
            } else {
                // Dead space the next item cannot use; scale with tightness.
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }
    } else {
        // Last item: strongly reward tight fills.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residuals far below the mean
    // are scarce-capacity bins; prefer filling those.
    let rel = post_residual as f64 - mean_residual;
    score += 0.20 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the current fit leaves large unusable space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline new-bin cost: prefer existing bins with decent fits.
        score += 15.0;
        if post_residual as f64 > mean_residual + 20.0 {
            // Poor fit in existing bins: opening a new bin is reasonable.
            score -= 45.0;
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild preference to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 8.0 * waste_ratio;
    }
    // Reward when post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are more acceptable early; penalize more as stream progresses.
        score += 20.0 + 25.0 * progress;
        // If many open bins have large mean residual, discourage opening another.
        score += 0.15 * mean_residual;
        // If no open bin can fit (fitting_bins_count == 0 refers to open bins only),
        // the new bin is necessary; soften the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild load-balancing: prefer bins whose residual deviates favorably from mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer filling nearly-full bins to close them out.
    if post_residual <= 10 && post_residual > 0 {
        score -= 5.0;
    }

    // Slight preference for bins that can still hold medium items afterwards.
    if post_residual >= 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: quadratic + cubic interactions with progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Early stream: prefer tight fits (low post_residual) more aggressively;
    // late stream: tolerate larger residuals to avoid opening bins.
    let tightness_weight = 1.0 + 1.5 * prog2 + 2.0 * prog3;
    score += tightness_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward near-perfect fills with a smooth exponential bonus
    let fill = 1.0 - norm_pr;
    score -= 6.0 * fill * fill * fill * fill;

    // Dead-space penalty: residual too small to fit the mean item (~55) is wasted
    let dead = ((pr - 55.0) / cap).max(0.0);
    score += 4.0 * dead * dead * cap * 0.1;

    // Lookahead coupling: smooth reward if next item fits into post residual
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let fit_quality = gap / cap;
            score -= 5.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: penalize opening a new bin smoothly, more so late in stream
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post-residual: small residues near common item
    // sizes are more reusable than odd dead-space values.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo arithmetic on post_residual relative to typical item classes.
    let residue_class = post_residual % 10;
    let class_bonus: f64 = match residue_class {
        0 => 6.0,           // multiple of 10: highly reusable
        5 => 3.0,           // multiple of 5: moderately reusable
        _ => -1.5,          // odd dead space
    };
    score -= class_bonus;

    // Integer-division thresholds: how many "average" items still fit.
    let avg_item = if next_item_size > 0 { next_item_size as f64 } else { 45.0 };
    let fits_count = (pr / avg_item).floor();
    score -= fits_count * 4.0;

    // Lookahead coupling: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder; penalize proportionally.
        score += 5.0;
    }

    // Fraction-of-capacity dead-space penalty (quadratic for small residues).
    let frac = pr / cap;
    if frac < 0.1 {
        score += (0.1 - frac) * 150.0; // tiny unusable slivers are bad
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is crowded
    // and future stream is long enough to justify it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0;
        // Open a new bin when open bins are nearly full on average and stream
        // still has runway (keeps future items' options open).
        let mean_fullness = 1.0 - mean_residual / cap;
        if mean_fullness > 0.7 && progress < 0.9 {
            score -= 45.0;
        }
        // Don't open new bin for a single-item future need when a fit exists.
        if fitting_bins_count > 0 && item_size >= 60 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight preference for tighter bins overall (post_residual already does
    // this; scale it a bit for separation).
    score += pr * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 2.0 } else { 0.0 };
        score += dead * post_residual as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - tightness.min(1.0)) * 15.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open;
    // favor filling existing bins, but allow new bins when residuals are tiny.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / 8.0).min(3.0) * (1.0 - 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: keep it competitive only when all open
    // residuals are poor fits for the item.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        if mean_gap < 5.0 {
            score -= 10.0; // existing bins are nearly full anyway
        } else {
            score += 30.0 + 2.0 * mean_gap.min(50.0); // prefer open bins
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Mean residual coupling: bins deviating far below mean are good fill targets.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 45.0; // perfect chain: next item exactly fills this bin
        } else if post >= nxt {
            score -= 20.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here: dead space penalty scaled by wasted capacity
            score += 0.35 * (nxt - post);
        }
    } else {
        // last item: minimize leftover as strongly as possible
        score += 10.0;
    }

    // Penalize residual far above the mean residual (poorly utilized bin kept open)
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.15 * (res - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when reasonable fits exist, especially early in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from number of open bins
        score += 25.0 + 2.0 * open_bins_count as f64 - 15.0 * progress;
        // opening a new bin is attractive only if no open bin leaves a near-perfect fit
        score += 0.05 * res;
    } else {
        // tight fits (small post_residual) are good
        score -= 0.05 * (bin_capacity as f64 - res);
    }

    // Reward filling bins very tightly (post_residual below smallest possible item)
    if res > 0 && res < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 24.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // still usable for small items
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly/well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        score -= 10.0 + 0.25 * next_fit as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize consuming space it could have used.
        score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fill_ratio;

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual < item_size as f64 {
        score -= 5.0;
    }
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling: empty bin should lose to decent fits,
    // but win when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = waste_if_open + 20.0; // baseline handicap
        if next_item_size > 0 && waste_if_open >= next_item_size as f64 {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping in [0,1]
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (favor spreading items);
    // later, penalize wasted space more aggressively.
    let shape = 1.0 + 0.8 * progress - 1.2 * progress * progress;
    score += 30.0 * x * x * shape;

    // Penalize residuals that cannot fit the lookahead item (dead space),
    // smoothly scaled by progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 40.0 * unusable * unusable * (0.5 + 0.5 * progress);
        // Reward if post-residual still fits the next item exactly-ish
        let fits_next = (pr - nx).max(0.0) / cap;
        score -= 15.0 * (1.0 - fits_next * cap / cap) * (fits_next * cap / nx.max(1.0)).min(1.0) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild preference to keep mean residual balanced (avoid fragmenting).
    score += 0.3 * (pr - mean_residual).abs();

    // Slight bias toward filling existing bins over opening new ones,
    // increasing with the number of open bins.
    score += 0.15 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 buckets) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are multiples of 10 are "harmonic" — likely reusable by
    // future items whose sizes are multiples of 10. Reward them.
    if class == 0 && pr > 0 {
        score -= 12.0;
    } else if class <= 2 {
        // Tiny dead space (0..=2) is effectively waste; mild penalty already
        // encoded by post_residual itself, add a small nudge.
        score += 2.0;
    } else if class >= 8 {
        // Large awkward remainder near a multiple of 10: slightly penalize.
        score += 1.5;
    }

    // --- Perfect fit reward ---
    if pr == 0 {
        score -= 50.0;
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can follow: strong reward, scaled by tightness.
            let tight = (pr - next_item_size) as f64;
            score -= 8.0 + 0.15 * tight;
        } else {
            // Next item won't fit in the leftover: penalize proportionally
            // to how much space is wasted relative to the next item.
            score += 0.10 * (next_item_size - pr) as f64;
        }
        // Harmonic match: next item size shares the same mod-10 class as pr
        if next_item_size % 10 == class && pr > 0 {
            score -= 6.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable when current bins are quite full
        // (mean residual small) or few bins fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_r_norm = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is low (bins are packed tight)
        score += 25.0 * mean_r_norm;
        // Early in the stream, be slightly more willing to open bins.
        score -= 5.0 * (1.0 - progress);
        // If many bins fit, discourage opening a new one.
        score += 3.0 * (fitting_bins_count as f64).min(10.0);
        // Harmonic bonus: new bin leaves a full 100-capacity harmonic state.
        if item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // --- Fill-ratio coupling: reward filling a larger fraction of the bin ---
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill;

    // --- Bin-count pressure: when many bins are open, prefer consolidating
    //     into tight fits rather than spreading. ---
    if open_bins_count > 4 {
        score += 0.02 * (open_bins_count as f64) * (pr as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (gap < 10, or gap < next_item_size) are pure waste.
    if post_residual < 10 {
        score -= 1000.0; // perfect/near-perfect fill, strongly reward
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap unusable even by the known next item -> dead space
        score += 40.0 + 2.0 * (post_residual as f64);
    } else {
        // Usable gap: mild preference for tight fits (small post_residual already
        // in base score), but penalize mid-range fragmentation.
        let frag = 1.0 - ((post_residual as f64) / (bin_capacity as f64));
        score += 5.0 * frag * frag;
    }

    // Reward filling bins that are already mostly full (tight fit bonus).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so its base
    // score is high; add extra penalty proportional to open_bins_count).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64);
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Slight reward for keeping bin count low by using existing bins.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below the mean (consolidate emptiness).
    score += 0.1 * (mean_residual - post_residual as f64);

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement strongly (sets up a perfect follow-up).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward near-exact fits (waste-based penalty, superlinear).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: perfect chaining of next item into this residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to the shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 8.0 * (shortfall / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a tight future chain.
    if bin_residual == bin_capacity {
        let new_penalty = 25.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        score += new_penalty;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin supports a good 2-item cascade
        }
    }

    // Small late-stream tightening.
    score -= 3.0 * progress * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward near-perfect fits aggressively.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the residual left behind,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; leftover dead space is riskier.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins with high mean residual: prefer consolidating into
    // already-loose bins rather than fragmenting more.
    if open_bins_count > 2 {
        let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness * ((open_bins_count as f64).ln() + 1.0);
    }

    // Penalize placing into bins whose residual deviates wildly from mean
    // (keeps residual distribution compact, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: reserve it for large items or when no open bin fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items late in the stream,
        // or when the item fits poorly in every open bin.
        if item_frac > 0.6 || (fitting_bins_count <= 1 && post_residual > 40) {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 25.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild time-horizon shaping: early stream, be conservative with tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Smooth polynomial coupling: penalize mid-range waste more as stream progresses
    let quad = x * (1.0 - x); // peaks at x=0.5
    score += 12.0 * quad * (0.5 + progress);

    // Cubic term: reward near-zero residual increasingly over time
    score -= 20.0 * (1.0 - x).powi(3) * (0.3 + 0.7 * progress);

    // Dead-space penalty: residuals too small for typical future items
    let small_gap = ((x * cap) / 30.0).min(1.0); // gap under ~30 is likely dead space
    score += 15.0 * (1.0 - small_gap) * (1.0 - small_gap) * (0.4 + 0.6 * progress);

    // Lookahead: bonus if next item fits in post residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain_fit = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 10.0 * chain_fit * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild pressure to consolidate into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * x * 2.0;

    // Deviation from mean residual: prefer bins below mean (fill fuller bins)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // "harmonic" divisors of capacity are more reusable.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for d in [50u32, 25, 20, 10, 5] {
        if pr > 0 && pr % d == 0 {
            harmonic_bonus += cap / d as f64 * 0.35;
        }
    }
    score -= harmonic_bonus;

    // Perfect fit reward
    if pr == 0 {
        score -= 500.0;
    }

    // Penalize dead space: small nonzero residuals that no typical item fits
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr >= 10 && pr < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            score -= 40.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: slight penalty scaled by wasted potential
            score += 10.0 * (next_item_size as f64 - pr as f64).min(cap) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer fuller bins (tight packing) via residual fraction
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 25.0 * fill * fill;

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin is a fresh empty one with no competition.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / cap;
        // base penalty for opening a new bin
        score += 90.0;
        // but if existing bins are fragmented (high mean residual) and many are open,
        // opening fresh is less bad
        score -= 30.0 * (mean_residual / cap).min(1.0);
        // early stream: opening bins is cheap; late stream: discourage
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        let _ = pressure;
    }

    // Mild preference to keep number of open bins from exploding
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual can still host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if this placement kills the bin while the next item is large.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when item is large or no bin fits well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalation with open bins count.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If the item is huge relative to mean residual, new bin becomes reasonable.
        if (item_size as f64) > mean_residual {
            score -= 45.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        score += progress * 20.0;
    }

    // Prefer tighter existing bins (small residual before placement).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            // reward small leftover after the lookahead placement
            score -= (post_residual as f64 - rem2 as f64) * 0.25;
            if rem2 < 10 {
                score -= 15.0; // near-perfect two-item packing
            }
        } else {
            // next item cannot fit here: penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 10.0; // tiny dead space is wasted
            }
        }
    }

    // Relative-to-mean coupling: favor bins already below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.10;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so tight fits beat it,
        // but allow it when post_residual would be very small (item ~ fills new bin)
        // or when open bins are all loose.
        score += 25.0;
        if item_size >= 90 {
            score -= 30.0; // near-full item: fresh bin is ideal
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && next_item_size >= 50 {
            score -= 10.0; // big next item may want a fresh bin anyway
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: penalize bins whose post-residual is small relative to capacity.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (item_size as f64 / cap);

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 { score -= 30.0; }
    else if post_residual <= 5 { score -= 18.0; }

    // Dead-space penalty: post-residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual; penalize proportionally to wasted space
            score += 6.0 * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / cap;
        // prefer new bin when mean residual is low (fragmented) or many bins open
        score += 40.0 * pressure + 2.0 * (open_bins_count as f64).sqrt() - 10.0 * progress;
        // opening a new bin wastes the current item's potential pairing
        if next_item_size > 0 && next_item_size <= item_size {
            score += 8.0;
        }
    } else {
        // Prefer bins with residual close to item size (best-fit style), scaled by global mean.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 4.0 * gap / cap;
        // Favor bins below mean residual (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) - x * x * x * (0.5 + 0.5 * t);
    score += 20.0 * poly;

    // Tight fits are rewarded more as the stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * (1.0 + t) * 8.0;

    // Penalize dead space relative to mean residual across open bins
    score += (pr - mean_residual).abs() * 0.05 * (1.0 + t);

    // Last-chance bonus: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - t * 0.5);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            score -= 6.0 * gap * (1.0 - gap);
        } else {
            score += 3.0 * gap.abs();
        }
    }

    // Mild pressure to consolidate into fewer bins early on
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - t);

    // New-bin candidate: penalize slightly unless post residual is large
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Residuals in small bands (dead space) are penalized; large residuals are fine.
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds: 0..10
    match class {
        0 => score += 25.0,          // 0-9: nearly full, tiny dead space -> reward
        1 => score += 12.0,          // 10-19
        2 => score += 4.0,           // 20-29
        3 => score -= 2.0,           // 30-39: still flexible
        4 => score -= 4.0,           // 40-49
        5 => score -= 5.0,           // 50-59
        6 => score -= 4.0,           // 60-69
        7 => score -= 2.0,           // 70-79
        _ => {}                      // 80+: mostly empty anyway
    }

    // Modulo-arithmetic harmony: does post_residual align with a plausible future item slot?
    // If post_residual is divisible into useful chunks (mod 10 == 0), it's more reusable.
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }
    // Odd residuals that are 1..9 are the worst dead space (nothing of size >=10 fits)
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = post_residual as f64 / cap;
        score -= 20.0 * (1.0 - fit_quality);
    }

    // New-bin candidate handling: an empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = mean_residual / cap;
        // penalize new bin, less so when existing residuals are small or stream is early
        score += 35.0 - 20.0 * crowdedness - 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0; // nothing open can likely take the next item either
        }
    }

    // Mild preference to balance load across many open bins: favor bins whose
    // residual deviates from the mean in a useful direction.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Tie-break with harmonic class of item size (integer division thresholds)
    let iclass = item_size / 20; // 0..4
    score -= iclass as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are worthless. Penalize "unusable" gaps aggressively (non-linearly).
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0; // perfect fill, ideal
    } else if post_residual <= 10 {
        // tiny gap: likely dead space -> strong penalty on top of small raw value
        score -= 20.0 - (post_residual as f64) * 2.0;
    } else if post_residual > 50 {
        // large leftover: bin was under-filled, mild penalty relative to alternatives
        score += 5.0;
    }

    // Perfect fit is supreme.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward fitting the item into a bin whose residual was exactly tight.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with stream progress and open-bin pressure.
        score = 60.0 + 0.5 * open_bins_count as f64 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the next item could combine with current one in this fresh bin, slightly cheaper.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // If many bins already fit the item, new bin is very unattractive.
        score += 15.0 * fitting_bins_count as f64;
    }

    // Open-bin pressure: spreading across many open bins fragments capacity;
    // prefer bins below mean residual (larger residuals) slightly less.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the leftover gap -> dead space likely
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item also fits after this placement -> reward chained fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward for tight chains (small slack).
        if slack < 10.0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize creating dead space, worse if large.
        let dead = post_residual as f64;
        score += 0.15 * dead;
        if dead < next_item_size as f64 {
            score += 5.0;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Compare against mean residual across open bins: prefer bins with below-mean residual
    // (i.e. filling fuller bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream: be more conservative with residual space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when open bins can fit, especially many open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if current bin would leave tiny unusable residue.
        if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual preferred)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global congestion: many open bins with large mean residual -> favor consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 * 1.5 {
        score -= 8.0 * mean_residual / bin_capacity as f64;
    } else {
        score += 5.0;
    }

    // Late in stream: discourage opening new bins, prefer filling existing ones
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses and when fits exist elsewhere
        let new_bin_penalty = 40.0 + 60.0 * progress + 5.0 * open_bins_count as f64;
        score += new_bin_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
    }

    // Mild preference for bins with lower residual among equals
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), non-linearly.
    let mut score = pr_norm * pr_norm * 40.0 + pr_norm * 10.0;

    // Smooth polynomial coupling with stream progress: late in the stream,
    // waste tolerance shrinks (tighter packing valued more).
    let late = progress * progress;
    score += (1.0 - late) * pr_norm * 15.0 - late * pr_norm * 20.0;

    // Dead-space penalty: residual that is too small to be useful.
    let dead = if next_item_size > 0.0 as u32 { (next_item_size as f64 - pr).max(0.0) } else { 0.0 };
    score += (dead / cap) * (dead / cap) * 60.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: reward bins whose residual accommodates the next item.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= fits_next * 12.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln() * 2.0 - mean_residual / cap * 5.0;

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fraction classes).
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Classify post_residual into harmonic buckets: exact-fit, tiny, small, medium, large.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible
    } else {
        // Integer-division thresholds on post_residual (harmonic classes of C=100)
        let class = post_residual / 10; // classes 0..10
        score += (class as f64) * 3.0; // larger dead space penalized progressively

        // Tiny unusable slivers (< 10, smallest item class) are near-wasted space.
        if post_residual < 10 {
            score += 8.0;
        }

        // Reward if the lookahead item can fit into the leftover space (chaining).
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 18.0; // next item chains perfectly into this bin
                // Extra reward for tight chain (post_residual - next_item_size small)
                let chain_slack = post_residual - next_item_size;
                score -= (10 - (chain_slack / 10).min(10)) as f64 * 0.8;
            } else if next_item_size <= post_residual + 10 {
                score += 4.0; // near-miss chain: slightly risky
            }
        }
    }

    // Modulo-arithmetic coupling: residual in "sweet spot" classes (multiples of 20)
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: comparable to a mediocre fit.
        score = 45.0;
        // Opening a new bin is more attractive early (many items remain to fill it)
        // and when open bins are already crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 12.0;
        score -= (open_bins_count as f64).min(20.0) * 0.5;
        // If next item is small, a fresh bin can absorb it well.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 6.0;
        }
        // Many fitting bins exist -> prefer reusing; make new bin less attractive.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when an existing one is the only fit
        }
        return score;
    }

    // Reuse pressure: prefer bins with residuals close to the item (tight fit measure).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Slight preference to fill bins below mean residual (balance the pool).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable "dead space": gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to item size.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item would be stranded by this placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward if next item fits snugly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }

    // Make brand-new bins unattractive unless nothing sensible fits elsewhere:
    // an empty bin wastes capacity, so add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item is large and would leave a big gap anyway, opening fresh is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Slight stream-position adaptation: later in the stream, be greedier about
    // filling existing bins (avoid ending with many half-empty bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (2-step lookahead core).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Perfect 2-step match: next item exactly fills the remaining space.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > 0 && next_item_size < post_residual {
            // Next item fits inside the post residual: good chaining.
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - chain_left / bin_capacity as f64);
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover space: penalize dead space creation.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to ever be useful (below min item size 1..100 assumption ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins, but relax late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 30.0 * progress;
        // If the next item matches a fresh-bin pairing (item + next <= capacity), opening is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
        // If mean residual is small, existing bins are nearly full; opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Slight preference for fewer open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Last-chance bonus: if this is the only open bin that fits, strongly favor using it
    // (avoids opening a fresh bin when a viable one exists).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead (k=2): reward placements that leave room for the next item;
    // penalize proportionally to how much the next item overflows this residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Dead-space penalty: tiny unusable leftovers waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate penalty: scaled by how many bins are already open,
    // the average residual slack (fragmentation), and early-stream pressure.
    if is_new_bin {
        score += 5.0 + 0.3 * open_bins_count as f64 + 0.1 * mean_residual;
        if progress < 0.3 {
            score += 4.0 * (0.3 - progress);
        }
    }

    // Prefer bins that are tighter than the fleet average (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) - prn * progress * (1.0 - prn);
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly late in the stream
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            // reward leaving room exactly for the next item
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).powi(2));
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Slight penalty when many bins are open and this fit is wasteful
    let waste = prn * prn;
    score += 15.0 * waste * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Pull toward mean residual: prefer bins whose residual stays near average
    score += 5.0 * ((pr - mean_residual) / cap).powi(2);

    // New-bin candidate handling: make empty bin mildly attractive only for large items
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score -= 20.0 * size_frac * size_frac * (1.0 - progress);
        score += 10.0 * (1.0 - size_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in low classes is very costly.
    // Class boundaries via integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    if post_residual > 0 {
        // Dead-space penalty grows super-linearly for tiny unusable residuals.
        if post_residual <= sixteenth {
            score += 18.0; // nearly unusable sliver
        } else if post_residual <= eighth {
            score += 6.0;
        } else if post_residual <= quarter {
            score -= 2.0; // moderately reusable
        } else {
            score -= 6.0 * (pr / cap); // large residual is valuable
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            // Harmonic class match: next item leaves again a "good class" residual.
            let nr = post_residual - next_item_size;
            if nr == 0 || nr >= quarter {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this residual: penalize small residuals more.
            if post_residual < eighth {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 0.25 * cap && open_bins_count > 0;
        if tight {
            score -= 5.0; // allow fresh bin when everything is fragmented
        } else {
            score += 30.0; // prefer packing into existing bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * (open_bins_count as f64).log2().max(0.0);

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic item are nearly worthless — penalize them hard.
    let dead_zone_end: f64 = 12.0;
    if (post_residual as f64) < dead_zone_end && post_residual > 0 {
        score += (dead_zone_end - post_residual as f64) * 6.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "harvested" efficiently relative to mean.
    let waste = post_residual as f64 - mean_residual;
    score += 0.35 * waste;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when this placement would create dead space.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if it avoids a bad fit elsewhere.
        let bad_fit_penalty = if (post_residual as f64) < dead_zone_end && post_residual > 0 { 55.0 } else { 0.0 };
        score += 18.0 + 1.5 * open_pressure - bad_fit_penalty;
    } else {
        // Reusing an existing bin is favored; extra favor for last-chance bins.
        score -= 6.0;
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // Lookahead: prefer bins that still leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual == 0 as u32 as bool) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small post_residual).
    score -= 6.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 5.0 * (1.0 - lookahead_gap / (bin_capacity as f64)).powi(2);
        // Penalize if next item cannot fit in post_residual (dead space risk).
        if next_item_size as u32 > post_residual {
            score += 4.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score += 0.8 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when good open bins exist, unless residual is large.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 2.0;
        }
    }

    // Late-stream tightening: prefer tight fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score -= (1.0 - post_residual as f64 / cap) * 30.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64) > dead {
            score += dead * 0.8;
        }
        if next_item_size > 0 && (next_item_size as f64) <= dead {
            score -= 10.0; // lookahead item can fill this bin next
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can fit, unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // new bin is attractive when open bins are quite full on average
        score += 20.0 - fragmentation * 40.0 - progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // if next item is large, a fresh bin is valuable
        if (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    } else {
        // mild preference for using existing bins
        score -= 2.0;
        // prefer bins with residuals close to the item (best-fit flavor)
        score += (bin_residual as f64 - item_size as f64) * 0.15;
    }

    // Prefer balancing residuals toward mean to keep placement options open.
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;

    // Base: tight fits preferred (low post residual).
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, moderate residuals are tolerable; late in the stream,
    // waste is punished quadratically.
    let progress_weight = 0.5 + 2.5 * t * t;
    score += progress_weight * 40.0 * pr_n * pr_n * cap;

    // Smooth cubic penalty for leaving awkward residual bands
    // (residuals that are neither tiny nor comfortably large).
    let band = (pr_n - 0.35) * (pr_n - 0.35) * (pr_n - 0.35);
    score += 30.0 * band * cap;

    // Reward filling a bin nearly completely (smooth exponential bonus).
    score -= 25.0 * (-(cap - pr).max(0.0) / 12.0).exp();

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but the penalty decays as the stream progresses (consolidation late).
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - t) + 0.05 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * t);
    }

    // Lookahead coupling: if next item fits exactly into post residual,
    // reward this placement (chaining perfect fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 20.0;
        } else if nxt <= pr {
            // next item fits in leftover: mild reward scaled by tightness
            score -= 8.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            // leftover too small for next item: penalize dead space
            score += 10.0 * (1.0 - t) * (pr / nxt);
        }
    }

    // Alignment with mean residual: prefer bins that keep residual
    // distribution balanced (smooth quadratic term).
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: residuals too small for the smallest item (1..=100 unknown dist,
    // assume small items ~ up to 10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Classify residual into harmonic bands via integer division.
    let band = post_residual / 25; // 0..4 classes
    match band {
        0 => score += 15.0,              // tiny residual: nearly dead space
        1 => score -= 5.0,               // 25..49: usable for mid items
        2 => score -= 10.0,              // 50..74: good
        _ => score -= 12.0,              // 75..100: very flexible
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Fraction of next item relative to residual — reward good containment.
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 60.0 * frac;
            // Harmonic alignment: next item leaves a "nice" residual again.
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 150.0;
            } else if next_post % 25 == 0 {
                score -= 30.0;
            } else if next_post < 10 {
                score += 20.0;
            }
        } else {
            // Next item won't fit here; mildly penalize hoarding large residual.
            score += 10.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 80.0;
        // Cheaper to open a new bin late in the stream or when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
        score += 3.0 * (open_bins_count as f64).min(20.0);
        // If mean residual is large, prefer reusing existing bins.
        score += (mean_residual / cap).powi(2) * 60.0;
        // If next item is huge and current bins are tight, new bin is attractive.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward tightness relative to mean residual.
        let diff = mean_residual - pr;
        score += 0.3 * diff;
        // Reward filling bins that are more than half full (harmonic > 1/2 class).
        let used_frac = (cap - pr) / cap;
        score -= 50.0 * used_frac * used_frac;
    }

    // Modulo coupling on item size classes (harmonic item classes).
    match item_size % 20 {
        0 => score -= 8.0,   // "round" items pack well anywhere
        10 => score += 2.0,
        _ => {}
    }

    // Small tie-break noise via deterministic coupling (no RNG).
    score += ((step_index ^ open_bins_count) % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item (size 1..=100, so treat < ~10 as dead) are toxic.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_threshold {
        score += (dead_threshold - pr + 1.0) * 12.0; // heavy penalty for dead space
    }

    // Reward tight fits: bonus grows as post_residual approaches 0.
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= tightness * tightness * 18.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading, favor consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is close to what we consume (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.4;

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = pr - n;
            if slack <= dead_threshold {
                score -= 20.0; // next item seals this bin nicely
            } else {
                score -= 6.0;
            }
        } else if pr > 0.0 && n > pr {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // when open bins are few or when this placement would leave dead space.
    if bin_residual == bin_capacity {
        let dead_penalty = if pr > 0.0 && pr <= dead_threshold { 1.0 } else { 0.0 };
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        // Early stream / low pressure: new bin is attractive.
        score -= 15.0 * (1.0 - pressure) - 20.0 * dead_penalty * pressure;
        // Late stream: consolidate into existing bins instead.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for bins below mean residual (filling emptier bins
    // keeps large residuals available for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect match: post_residual exactly equals next item size -> big reward
        if (post_residual as u32) == next_item_size {
            score -= 40.0;
        } else {
            // Reward if next item can still fit in the residual left behind
            if next_item_size <= post_residual {
                // tighter leftover for the next item is better
                let slack = pr - nxt;
                score -= 15.0 - 0.25 * slack;
            } else {
                // Next item cannot follow: penalize proportionally to overshoot
                score += 0.6 * (nxt - pr);
            }
        }
    } else {
        // Last item: just prefer minimal residual
        score += 0.1 * post_residual as f64;
    }

    // --- Tightness relative to bin capacity ---
    // Reward filling the bin well (low post_residual relative to capacity)
    let fill_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fill_ratio;

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.3 * (mean_residual - post_residual as f64);

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing residuals are large/wasted
        // and this item is small (poor fit into leftover space)
        let waste = mean_residual - item_size as f64;
        if waste > 0.0 {
            score -= 5.0 + 0.2 * waste;
        } else {
            // Existing bins fit well; discourage opening a new bin
            score += 30.0;
        }
        // Early in the stream, allow more bins; late, consolidate
        score += 10.0 * (1.0 - progress);
    }

    // Small penalty for very small unusable residuals (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Mild pressure to keep number of open bins low late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: dead space penalized more heavily later in stream
    let dead_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress * progress);
    score += dead_penalty * cap;

    // Reward tight fits, amplified as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * item_size as f64;

    // Penalize bins far below mean residual (wasteful use of full bins)
    score += ((mean_residual - pr) / cap).abs() * (2.0 + 3.0 * progress) * 5.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let waste_after_next = pr - nx;
            score += (waste_after_next / cap) * (1.0 + 2.0 * progress) * 4.0;
        } else {
            score += 3.0 * (nx - pr) / cap * cap * 0.1;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 + progress) * 0.5;

    // New-bin candidate: penalize mildly early, more later (prefer packing into open bins)
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let res = post_residual as u32;
    let r10 = res % 10;
    let r25 = res % 25;

    // Penalize "dead" residues that rarely fit future items (items are 1..100).
    // Small nonzero residues (1..=5) are near-wasted space.
    if res > 0 && r10 <= 5 {
        score += 8.0 - (r10 as f64) * 1.2;
    }
    // Residues divisible by 10 or 25 are "harmonic" — usable by many item sizes.
    if r10 == 0 {
        score -= 4.0;
    }
    if r25 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds on post_residual: classify into capacity fractions.
    let q = res / 25; // 0..4 quarters
    match q {
        0 => score += 6.0,          // <25: mostly dead space
        1 => score += 1.0,          // 25..49: fits small items
        2 => score -= 1.0,          // 50..74: good
        _ => score -= 2.0,          // 75..100: very flexible
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit harmonically?
    if next_item_size > 0 {
        if next_item_size <= res && next_item_size > post_residual {
            // Next item fits this bin now but not after placing current item.
            score += 5.0;
        }
        if post_residual >= next_item_size {
            // Chain-friendly: next item still fits after placement.
            let slack = post_residual - next_item_size;
            score -= (slack as f64) * 0.15;
            if slack % 10 == 0 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // If item is small relative to capacity, opening a fresh bin wastes potential.
        if (item_size as f64) / (bin_capacity as f64) < 0.35 {
            score += 10.0;
        }
        // But if existing bins are nearly full on average, fresh bin is fine.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // Mild penalty when many bins fit the item: prefer tightest, discourage hoarding spread.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64) * 0.4;
    }

    // Tie-break: prefer bins whose residual is close to item (best-fit flavor).
    score += ((bin_residual as f64) - (item_size as f64)) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // gap smaller than the minimum item size is pure dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
        // penalize gaps just below the next item's size (unusable for lookahead)
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // reward gaps that can exactly host the next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // perfect fit
        score -= 50.0;
    }

    // Reward tight fits: waste ratio of the placement itself
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> avoid spreading; few bins -> keep bins tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 8.0 * (1.0 - progress));
    score += pressure * (mean_residual / 10.0) * 0.5;

    // New-bin candidate: attractive only when current fit is bad or no tight option
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) < 10.0 || fill < 0.5;
        if bad_fit || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
    }

    // mild alignment bonus: residuals that are multiples of 10 are easier to fill later
    if post_residual % 10 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead fit: strong reward.
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here later; reward proportional to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover; penalize dead space.
            score += 12.0 + 0.25 * diff;
        }
    }

    // Tight fits are good: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual of open bins: prefer bins tighter than average.
    if mean_residual > 0.0 {
        score += 8.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the new bin would be a perfect fit).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: mildly penalize so we prefer reusing open bins,
    // unless the fit is very poor (handled implicitly by other terms).
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item would exactly fill a fresh bin, allow opening it.
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) == item_size {
            score -= 40.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linear).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            // leftover can't fit the known next item: mild penalty scaled by gap
            score += 0.5 * (next_item_size as f64 - dead).min(40.0);
        } else if next_item_size > 0 {
            // leftover can fit next item: reward chaining
            score -= 6.0 * (next_item_size as f64 / dead).min(1.0);
        }
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a large item that would strand a bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let big_item = fill_ratio > 0.7;
        if big_item || crowd > 8.0 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 35.0; // discourage wasting fresh bins early
        }
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (balance avoidance).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure to reuse bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr as f64;

    // Smooth non-linear coupling: post_residual polynomial in stream progress
    // Early on, tolerate larger residuals (keep flexibility); later, punish waste harder.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 12.0 * poly * (1.0 - progress);
    score += 15.0 * norm_pr * norm_pr * progress;

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Dead-space penalty: residuals too small for typical future items
    let dead = if norm_pr > 0.0 && norm_pr < 0.1 { 0.1 - norm_pr } else { 0.0 };
    score += 40.0 * dead * dead * 10.0;

    // Lookahead: reward residual that can host next item exactly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 8.0 * tightness * tightness;
    }

    // Crowd penalty: many open bins -> favor closing bins (tight fits) over spreading
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * mean_residual / cap;
    score += 6.0 * crowd * norm_pr;

    // New-bin candidate: neutral-ish but slightly discouraged unless residuals are messy
    if bin_residual == bin_capacity {
        score += 4.0 - 6.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularity are reusable; odd/prime-ish residuals waste space.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 12.0; }
        else if r % 5 == 0 { score -= 6.0; }
        else if r % 2 == 0 { score -= 2.0; }
        else { score += 4.0; }
    } else {
        // Perfect closure is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual admit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 35.0;
        } else if next_item_size < r {
            let slack = r - next_item_size;
            if slack % 10 == 0 { score -= 10.0; } else if slack % 5 == 0 { score -= 5.0; }
            score += (slack as f64) * 0.15;
        } else {
            // Next item cannot fit here; mildly penalize hoarding space.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tight fills relative to capacity fraction.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 20.0;

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    // Prefer bins whose residual is below the open-bin mean (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Small bonus for exact-fit class via integer division threshold.
    if r <= 5 && r > 0 { score -= 8.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Dead space relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // Reward tight fits (exact fill strongly rewarded).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual matches the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            score += 5.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.12 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Mean residual coupling: prefer bins near the mean (keeps bin profile uniform),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild progression term: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress; // penalize opening new bins, more so later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post residual can hold next item at all
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize unusable dead space relative to smallest plausible item
    if post_residual < 1 {
        score -= 10.0; // perfect fill
    } else if post_residual < 10 {
        score -= 6.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good existing fits exist
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big item coming; keep open bins tight
        }
        // Early in stream, opening bins is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Prefer filling larger residuals with larger items (tightness coupling)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals that are too small for the
    // smallest plausible item (1..100 unknown distribution -> treat <15 as dead).
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use leftover space -> mild penalty.
        score += 6.0;
    }

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when a
    // decent fit exists. Make empty-bin score slightly worse than a good fit.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }

    // Time horizon: late in the stream, prefer consolidating (favor existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Many open bins -> prefer filling existing ones over opening more.
    score += (open_bins_count as f64).ln_1p() * 2.0;

    // Global residual pressure: high mean residual means space is abundant
    // elsewhere; be pickier about wasting this bin's space.
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / c;

    // Base: post-residual (waste), with non-linear polynomial shaping.
    let mut score = pr
        - 18.0 * norm_pr * (1.0 - norm_pr)   // reward mid-range residuals (usable space)
        + 12.0 * norm_pr * norm_pr;          // penalize large leftover dead space

    // Tight-fit bonus: smooth polynomial coupling of post_residual with item fit ratio.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit * fit * (1.0 - norm_pr);

    // Stream progress interaction: later in stream, value tight fits more, penalize waste more.
    score += 15.0 * progress * norm_pr;
    score -= 10.0 * progress * fit * fit;

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let nx_fit = nx / pr.max(1.0);
        if nx <= post_residual {
            score -= 8.0 * (1.0 - nx_fit * nx_fit) * (1.0 - progress);
        } else {
            // next item won't fit here; small penalty scaled by how much it overshoots
            score += 6.0 * ((nx - pr) / c) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Crowd effect: many open bins -> prefer filling existing ones over new bins.
    let crowd = (open_bins_count as f64).ln1p();
    score += 3.0 * crowd * norm_pr;

    // Mean residual coupling: if this bin is far from mean residual, slight penalty (balance).
    score += 2.0 * ((pr - mean_residual) / c).abs();

    // New-bin candidate: empty bin gets a mild handicap unless residual shaping favors it.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 2.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste mod small divisors
    let pr = post_residual as u32;
    if pr > 0 {
        // dead-space penalty grows when residual falls into "awkward" classes
        let awkward = (pr % 10 == 1) as f64 * 6.0
            + (pr % 7 == 1) as f64 * 3.0
            + (pr % 3 == 1) as f64 * 2.0;
        score += awkward;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Fractional fill: reward high occupancy
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residual
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 30.0;
        // but if placing here leaves a terrible residual in every fit, new bin is fine
        let next_frac = next_item_size as f64 / cap;
        if next_item_size > 0 && next_frac > 0.5 {
            score -= 15.0; // big next item: fresh bin useful
        }
        if open_bins_count as f64 * mean_residual < item_size as f64 {
            score -= 25.0; // no aggregate room anyway
        }
    } else {
        // penalize leaving residual smaller than typical next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
        // reward if next item fits exactly in post_residual
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Early stream: be slightly greedy toward tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (cap - post_residual as f64) * 0.05;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. A "dead zone" threshold: gaps < 10 (min item) are pure waste,
    // gaps in 10..20 are risky (only small items fit).
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: penalize proportionally to how close to a full waste it is.
        score += (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Risky small gap: mild penalty.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets this penalty
    // via its large post_residual, but add explicit pressure for consolidation).
    if open_bins_count > 3 {
        let pressure = (open_bins_count as f64).ln() * 3.0;
        // New-bin candidate detection: residual equals full capacity.
        if bin_residual == bin_capacity {
            score += pressure;
        } else {
            score -= pressure * 0.5;
        }
    }

    // Lookahead coupling: if the next item could exactly fill this bin's post-residual,
    // reward keeping that residual; otherwise, if next item can't fit in the residual,
    // the residual is likely dead space for the near future.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item completes this bin perfectly
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0; // residual unusable by the immediate next item
        }
    }

    // Late in the stream, prefer closing bins tightly (less future to amortize gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild preference toward bins below mean residual (consolidate fuller bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good, but dead space that
    // cannot hold the next item is doubly bad.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-step match: residual exactly consumed by next item.
            let slack = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use this residual.
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual of open bins:
    // prefer filling below-average (tighter) bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // = capacity - item_size for new bin
        score += 30.0 + 0.3 * open_bins_count as f64 + fit_quality * (0.4 - 0.3 * progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, avoid leaving many nearly-empty bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild penalty for very small residuals left behind (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize awkward dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 10.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this is a great pairing; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted pairing potential.
            score += 5.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins over opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= pressure * 8.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: empty bins should only win when existing
    // fits are poor. Add a base cost to opening a new bin, reduced when
    // open bins are mostly full (pressure low) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_cost = 18.0 + 10.0 * pressure;
        score += base_cost - 10.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild time-horizon effect: late in the stream, avoid creating new bins
    // with large residuals that will go unused.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 12.0 * (progress - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * prn * prn * (1.0 - g);   // early: reward tight fits strongly
    score += 8.0 * prn * g;                  // late: penalize leaving large residuals

    // Dead-space penalty: residuals too small for typical future items.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 6.0 * (1.0 - pr / ni) * (1.0 + g);
        } else {
            // reward residuals that can still host the lookahead item
            score -= 4.0 * (prn * (ni / cap));
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin wastes current open capacity.
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score = pr + 25.0 * (1.0 - g) * waste * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild consolidation pressure toward mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 as a "dead space class"
    let class = post_residual % 10;
    // Residuals that are multiples of 10 are more reusable for items in 10..80 range
    let class_bonus = (10 - class) as f64 / 10.0;
    score -= class_bonus * 3.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size: heavily penalize
        score += 40.0;
    }

    // Fractional capacity coupling: post_residual relative to capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 5.0; // leaving more than half a bin empty is wasteful for a big item
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic divisibility: next item nests perfectly if post_residual % next_item_size == 0
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; residual is terminal
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // open bins have small mean residual (poor fits likely) or many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score = 45.0 - 20.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Integer-division threshold on residual size classes
    let bucket = post_residual / 20; // 0..5
    score -= bucket as f64 * 2.0;

    // Mild tie-break: prefer filling bins with larger current fill (smaller residual)
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are heavily punished.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * 2.0;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin fits well, opening new bin becomes attractive.
        if post_residual >= (bin_capacity as f64 * 0.2) as u32 {
            score -= 10.0;
        }
    }

    // Lookahead: favor leaving space for the next item when it's large.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 5.0;
    } else if next_item_size > 0 {
        score -= 3.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Slight late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64).max(0.0) * 25.0;
        // exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual > 0 && (post_residual as i64 - next_item_size as i64) < 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild penalty for many open bins -> encourage consolidation
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when current item leaves huge post_residual
    // and no open bin fits well; make empty bin mediocre by default
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post-residual and apply non-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space; penalize large dead space.
            score += 3.0 * tightness;
        }
    }

    // Penalize placing into bins whose residual is far from the mean (fragmentation).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty that grows with progress
        // and with the number of open bins (encourage consolidation late).
        score = bin_capacity as f64 * 0.95 + 8.0 * progress + 0.4 * open_bins_count as f64;
        // If no open bin fits well, opening may be fine: soften early.
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin: reward grows with progress to consolidate late.
        score -= 5.0 * progress;
    }

    // Small bonus for keeping many open bins from accumulating dead space:
    // prefer bins with small residuals overall.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - (post_residual as f64 / cap);

    // Base: prefer minimal dead space, amplified smoothly with stream progress
    let mut score = pr * (1.0 + 1.5 * progress);

    // Non-linear reward for tight fits (quartic coupling of fill with progress)
    score -= 30.0 * fill.powi(4) * (0.5 + progress);

    // Penalize residuals that are unlikely to be reusable by the next item:
    // smooth coupling of post_residual with next item size
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score += 0.35 * gap + 0.004 * gap * gap;
        // bonus if next item fits exactly in the post-residual region
        if ns <= pr {
            score -= 6.0 * (1.0 - (ns / pr.max(1.0)));
        }
    } else {
        // last item: strongly prefer filling bins as much as possible
        score -= 20.0 * fill;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when this bin's residual deviates from mean residual
    // (keeps residual distribution coherent), smoothed by progress
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: score relative to how much of it would remain empty
    if bin_residual == bin_capacity {
        // prefer new bin early / when open bins are already fragmented,
        // penalize when item is small (wasteful opening)
        score = cap - item_size as f64
            + 25.0 * fit_ratio
            - 15.0 * (1.0 - progress)
            + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "useful"
    // classes (divisible by common small item sizes 10, 20, 25, 50).
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr < 10 {
        10.0 // tiny dead space, hard to reuse
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 10.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when open bins fit well.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // allow opening new bin late in stream less often
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Prefer bins with residuals close to item size (tight fit) via quadratic term.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += tight * tight * 0.01;

    // Mild preference to balance against mean residual.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward good fits proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / 10.0);

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: avoid bins far from the mean unless it's a new bin.
    if bin_residual != bin_capacity {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // New-bin candidate: only attractive when open bins are nearly full-tight
        // or there are no fitting bins pressure; penalize mildly otherwise.
        score += 20.0 + 0.5 * (open_bins_count as f64);
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Early stream: slightly favor keeping options open (new bins cheap early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // small leftover after two placements is good
            let two_step_left = post_residual - next_item_size;
            score -= 30.0 * (1.0 - (two_step_left as f64 / bin_capacity as f64));
            if two_step_left == 0 {
                score -= 50.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist, unless lookahead suggests it
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty that tight fits overcome
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is attractive if item is large (hard to place later)
            score -= (item_size as f64 / 100.0) * 15.0;
        }
    }

    // Late in stream: be more conservative, avoid creating tiny unusable residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (0.5 + progress);
    }

    // Many open bins: prefer consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Penalize leaving dead space that can only host tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item won't reuse this bin; slight penalty if we waste much space.
            score += 0.05 * (post_residual as f64 - nxt).max(0.0);
        }
        // Perfect chain: next item exactly fills post_residual.
        if nxt == post_residual as f64 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when item is large or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 1.0 };
        // Base cost of opening a bin.
        let mut new_bin_cost = 35.0;
        // If item is large and residuals are small relative to it, opening is reasonable.
        new_bin_cost -= 30.0 * (fill - 0.5).clamp(0.0, 0.5) * 2.0;
        if pressure > 1.0 {
            new_bin_cost -= 10.0 * (pressure - 1.0).min(2.0);
        }
        // Late in stream, avoid proliferating bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost += 25.0 * t;
        // Many open bins with slack: discourage new bin.
        new_bin_cost += (open_bins_count as f64).ln().max(0.0) * 3.0;
        score += new_bin_cost;
    } else {
        // Mild preference for bins with smaller residual (better fill).
        score += 0.05 * (bin_residual as f64);
    }

    // Global balance: prefer bins below mean residual slightly (spread waste evenly).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap; // occupancy after placement
    let tight = 1.0 - (pr / cap).clamp(0.0, 1.0);

    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let poly = tight * tight * (1.0 + t) + 2.0 * tight * (1.0 - tight) * (0.5 + 0.5 * t);
    score -= 0.35 * cap * poly;

    // Smooth dead-space penalty: quadratic in residual, scaled by future need
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (pr - next).abs() / cap;
        score += 0.25 * cap * gap * gap * (1.0 - t);
    }

    // Last-chance bonus (smooth sigmoid on fitting_bins_count)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0_f64.max(fitting_bins_count as f64 - 1.0)).exp());
    let lc = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1) as f64 - 1.5).exp());
    score -= 8.0 * lc;

    // Mean-residual coupling: prefer bins deviating from mean smoothly
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.15 * cap * dev * dev * (1.0 - fill);

    // New-bin candidate: penalize mildly, less so early in stream
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (10.0 + 20.0 * t);

    // Congestion pressure: many open bins -> favor consolidation
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - tight) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward excellent fits (post_residual small relative to capacity).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space in [1,10] is dangerous
    // because future items are >= 1 and small residuals rarely reusable.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 150.0 * (1.0 - post / 10.0);
    }

    // Modulo-class coupling: residuals that are multiples of common small
    // item sizes (10, 20, 25, 50) remain usable — reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 40.0; }
        if post_residual % 25 == 0 { score -= 25.0; }
        if post_residual % 50 == 0 { score -= 20.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves a new residual; penalize tiny leftovers
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 30.0 * (1.0 - next_post as f64 / 10.0);
            } else {
                score -= 20.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin has high raw score already
    // (post_residual == capacity - item). Adjust based on stream phase and
    // fragmentation of open bins.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Early in stream: opening new bins is cheap, keep score high-ish.
        // Late in stream: avoid proliferation of open bins.
        score += 60.0 * (1.0 - progress);
        if open_bins_count > 8 { score += 50.0; }
        // If an open bin gives a decent fit (post_residual small), new bin loses.
        if post_residual <= 15 { score += 250.0; }
    } else {
        // Prefer bins whose residual is close to item (high fill ratio).
        score -= 80.0 * fit_ratio;
        // Prefer bins below mean residual (more fragmented bins get emptied first).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals in (10, 20) as semi-dead space (only tiny items fit).
    if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item barely misses post_residual, slight penalty (fragmentation risk).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., current bin's post_residual would be dead space) or stream is early.
    if bin_residual == bin_capacity {
        let dead = post_residual > 0 && post_residual < 10;
        if dead && fitting_bins_count >= 1 {
            score -= 20.0; // opening fresh bin beats creating dead space
        } else {
            score += 15.0; // default: prefer existing bins
        }
        if step_index == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strong reward for exact fit with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack afterwards.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0); // reward tight two-item packing
    }
    // Penalize residuals too small for any plausible future item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tight fit now (small post residual) is generally good.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        // Opening a bin is penalized more when many bins already fit the item.
        score += 15.0 + (fitting_bins_count as f64) * 8.0;
        // But if mean residual of open bins is much larger than what we'd leave,
        // a fresh bin may preserve flexibility: mild discount.
        if mean_gap > 20.0 {
            score -= 12.0;
        }
        // Early in the stream, having bins open is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer bins whose residual is below average (consolidate large holes).
    if bin_residual < bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let t = post_residual as f64 / cap;

    // Penalize large unusable dead space non-linearly (quadratic in leftover fraction)
    score += 10.0 * t * t;

    // Prefer bins whose current residual is close to the item (tight fit reward)
    let gap = bin_residual as f64 - item_size as f64;
    score += 0.03 * gap;

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize placements that strand residual space the next item could have used
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post_residual as f64 && post_residual > 0 {
            score += 0.06 * nxt;
        } else if nxt <= post_residual as f64 {
            // next item fits in the leftover: reward slightly
            score -= 0.04 * (post_residual as f64 - nxt);
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

        // Reward opening a new bin when the next item can pair with the leftover space
        if next_item_size > 0 && next_item_size as u32 <= post_residual {
            score -= 12.0;
        }

        // Penalize opening new bins when existing bins already hold lots of slack
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);

        // Mild reluctance to open new bins early in the stream (keep bins consolidated)
        score += 5.0 * (1.0 - progress);

        // If several bins fit, opening a new one is rarely worth it
        if fitting_bins_count > 2 {
            score += 8.0;
        }
    } else {
        // Reward using existing bins proportionally to how "full" they already are
        let fullness = 1.0 - bin_residual as f64 / cap;
        score -= 6.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: post residual, non-linearly warped (quadratic dead-space penalty)
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth coupling of residual quality with stream progress:
    // late in the stream, tighten bins more aggressively.
    let progress_warp = progress * progress;
    score *= 1.0 + 0.6 * progress_warp;

    // Reward tight fits: subtract a smooth function of how full the bin becomes.
    let fill = (cap - post) / cap;
    score -= 25.0 * fill * fill * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize when many bins fit (spread items to keep flexibility),
    // scaled smoothly by how much slack remains.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln_1p() * (post_norm + 0.1);
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            let gap_norm = gap / cap;
            score -= 18.0 * (-8.0 * gap_norm * gap_norm).exp();
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 6.0 * (-gap / cap);
        }
    }

    // Divergence from mean residual across open bins: prefer bins that
    // consolidate space (keep residual distribution balanced).
    let dev = (mean_residual - post).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let pressure = 1.0 - (mean_residual / cap).min(1.0);
        score += 12.0 * crowded.ln_1p() - 20.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class logic: classify post_residual by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Reward placements leaving residuals in "useful" harmonic classes.
    // post_residual near 0 is best; residuals just above quarter/eighth
    // thresholds are still reusable for typical items.
    if pr == 0.0 {
        score -= 40.0; // perfect fit
    } else if pr <= eighth {
        score -= 25.0;
    } else if pr <= quarter {
        score -= 12.0;
    } else if pr <= c / 2.0 {
        score -= 4.0;
    } else {
        score += 8.0; // large dead space penalty
    }

    // Integer-division class of post_residual: multiples of 10 pair well
    // with the 10..80 item granularity.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin: strong reward
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / c;
            score -= 15.0 * tightness;
            // extra reward if chain is near-perfect
            if post_residual - next_item_size <= eighth as u32 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's remainder
            score += 5.0;
            // harsh penalty if post_residual is a small unusable sliver
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let baseline = c * 0.5; // average waste of a fresh bin
        score = baseline + 10.0;
        // later in stream / many open bins: prefer consolidation into open bins
        score += 20.0 * progress;
        score += 2.0 * open_bins_count as f64;
        // if item is huge, a fresh bin is actually reasonable
        if item_size >= 70 {
            score -= 25.0;
        }
        // if it's the last chance elsewhere, opening new bin is bad
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // Prefer bins whose residual is closest to the item (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / c;
        score -= 10.0 * tightness;
        // Slight preference for bins below mean residual (denser bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual was already tight before placement (compacting).
    if bin_residual < 40 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 30.0 + 4.0 * obp;
        // If nothing fits well elsewhere (this call context), allow fallback:
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        score -= 2.0 * obp.min(10.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Late in stream: prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (fill emptier-relative bins less; favor tight ones).
    score += 0.15 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Aggressive 2-step lookahead: if the next item can exactly fill the
    // remaining space after this placement, this is a dream pair.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }

    // If the next item fits into the post residual, reward the coupling.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tight-but-viable leftover: closer post_residual to next item
        // is better (leaves less dead space after the follow-up).
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover. Penalize the gap,
        // scaled by how much of the bin's capacity is being stranded.
        let gap = (next_item_size - post_residual) as f64;
        score += 40.0 + 1.5 * gap;
    }

    // Prefer bins whose residual was already tight relative to the mean:
    // placing here consolidates space instead of fragmenting fat bins.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual space available elsewhere (poor fits elsewhere).
    if bin_residual == bin_capacity {
        // Opening a fresh bin is only attractive when the item barely fits
        // anywhere else (i.e., few fitting bins) or the item is huge.
        let openness = if fitting_bins_count > 0 {
            1.0 / fitting_bins_count as f64
        } else {
            1.0
        };
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 250.0 - 200.0 * openness - 120.0 * largeness;
    }

    // Slight stream-progression pressure: as the stream matures, discourage
    // wasteful placements to keep total bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for likely future items (1..100).
    if post_residual > 0 {
        let dead = post_residual as f64;
        let min_item = 1.0;
        if dead < min_item {
            score += 50.0;
        } else if dead < 10.0 {
            score += 8.0 + (10.0 - dead);
        } else {
            // Usable-but-awkward space penalty grows as residual shrinks toward small item sizes.
            score += 3.0 * (1.0 - dead / (bin_capacity as f64));
        }
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin,
    // but only if the fit is not terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Post-residual too small for next item: mild penalty scaled by how close it is.
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 + 4.0 * (1.0 - miss / (bin_capacity as f64));
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // existing fits are poor or many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity as f64) * 0.5;
        // Cheaper to open when few bins are open (early stream / consolidation pressure low).
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Time horizon: late in the stream, avoid opening new bins unless necessary.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If several bins already fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If this is a last-chance situation, new bin is very costly.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item.
        if next_item_size > 0 {
            score -= 4.0;
        }
    } else {
        // Existing bins get a mild global-state coupling: prefer filling bins
        // whose residual is below the mean (compact bins first).
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 2.0 * (mean_residual - res) / (bin_capacity as f64);
        } else {
            score += 1.5 * (res - mean_residual) / (bin_capacity as f64);
        }
        // Progress pressure: as stream advances, favor tighter packing more strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64);
    let norm_post = post / cap;

    // Base: prefer small post residual (tight fit) via smooth non-linear coupling
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins (smooth quadratic)
    let dead = (post - mean_residual) / cap;
    score += 8.0 * dead * dead;

    // Lookahead: bonus if post residual can host the next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last chance: strongly favor using the only bin that fits (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Spread penalty: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * norm_post);

    // New-bin candidate: make it unattractive unless post residual is large relative to typical need
    if bin_residual == bin_capacity {
        score = cap * 0.9 - 4.0 * progress;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score += 10.0 * ((nxt / cap) - 0.5).abs();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 classes (0-19, 20-39, ...)
    let class = post_residual / 20;
    // Reward small classes (tight fits) with non-linear subtraction
    score -= (5 - class as f64) * (5 - class as f64) * 3.0;

    // Perfect fit -> extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Near-perfect fits (dead space <= 4)
    if post_residual > 0 && post_residual <= 4 {
        score -= 120.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and post residual
            let next_class = next_item_size / 20;
            if next_class == class {
                score -= 40.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving large residuals
            score += (post_residual as f64) * 0.4;
        }
    }

    // Modulo harmonic logic on post_residual: residuals divisible by 10 are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Odd small residuals are dead space
    if post_residual % 2 == 1 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // early in stream, opening bins is cheaper (need spread)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // if many bins open and mean residual large, prefer existing bins
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 45.0;
        }
        // if no existing bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // mild preference to fill already-open bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // prefer bins with smaller residual (best-fit flavor) modulated by mean
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are pure waste -> heavy penalty.
    let dead_threshold = 9.0; // below min item size 10 nothing fits
    if (post_residual as f64) < dead_threshold {
        score += 40.0;
    } else if (post_residual as f64) < 20.0 {
        // awkward gap: hard to fill, mild penalty
        score += 12.0;
    }

    // Reward tight fits (post_residual small but still usable by next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (bin_residual as f64 - item_size as f64).min(20.0);
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);
    score += bin_pressure;

    // New-bin candidate: neutral-ish base, but allow it when existing bins
    // would leave large dead space or when the item is large.
    if bin_residual == bin_capacity {
        // New bin leaves residual = capacity - item_size; judge by that.
        score = (bin_capacity - item_size) as f64;
        score += 3.0; // slight bias toward reusing open bins by default
        if item_size >= 60 {
            // large items fit well in fresh bins
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // Early in stream, cheap to open bins.
        score -= (1.0 - progress) * 5.0;
    } else {
        // Prefer bins whose residual is close to item (best fit core signal).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 20.0;
        // Bins far below mean residual are "rich" bins; spending them on a
        // small item wastes capacity.
        if (bin_residual as f64) > mean_residual + 15.0 && item_size < 30 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small leftover.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // post_residual far below typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than mean residual means tighter packing -> reward.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        score -= (1.0 - ratio) * 12.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer filling existing ones rather than
    // fragmenting; new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress + 20.0 * pressure.min(1.0);
    }

    // Mild reward for large items consuming big chunks (low post_residual already
    // captures this, but reinforce coupling with item_size).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus if residual nearly matches next item (chain packing).
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            if gap <= 5.0 {
                score -= 6.0;
            }
        } else {
            // Residual unusable for next item: mild penalty scaled by waste.
            score += 4.0;
        }
    }

    // New-bin candidate logic: opening a new bin is penalized generally,
    // but less so when no good fit exists or mean residual is low.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced: must open new bin
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0; // open bins are nearly full anyway
        }
        // Late in the stream, prefer reusing open bins to avoid stranding.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild preference to fill fuller bins (smaller residual) first.
    score += (bin_residual as f64) * 0.05;

    // Spread across bins when many are open: encourage consolidating into
    // bins below mean residual to balance waste.
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: small residuals late in the stream are valuable
    score += 8.0 * norm_post * norm_post * (1.0 - norm_post);

    // Smooth coupling with stream progress: tighten packing as stream advances
    score -= 6.0 * (1.0 - progress) * (1.0 - norm_post);

    // Lookahead: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 10.0 * (-gap * gap / (cap * cap * 0.02));
    }

    // Last-chance bonus when few fitting bins exist
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Slight pull toward bins near mean residual (keeps residual spread balanced)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild penalty for proliferation of open bins
    score += 0.3 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides the capacity
    let post = post_residual as f64;
    let post_class = (post_residual % 10) as f64;
    let post_quotient = (post_residual / 10) as f64;

    // Reward residuals that align with common item-size classes (multiples of 5/10)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += post_class * 0.4; // penalize awkward off-class dead space
    }

    // Reward small quotients (tight fit) with diminishing returns
    score -= 8.0 / (1.0 + post_quotient);

    // Next-item lookahead: reward residuals that can host the next item exactly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / cap);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 + over * 0.05;
        }
    } else {
        // last item: just minimize waste
        score -= 4.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening fresh bins unless the fit is very tight
    if bin_residual == bin_capacity {
        score += 14.0;
        // But if the item nearly fills a fresh bin, allow it
        if post_residual <= 20 {
            score -= 18.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean (tighten the tight ones)
    score += (post - mean_residual) * 0.08;

    // Stream progression: later in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post / cap);

    // Bin-count pressure: many open bins -> favor filling existing ones
    score -= (open_bins_count as f64).sqrt() * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        // Dead space that cannot fit even the smallest plausible item is nearly worthless.
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 25 {
            // Medium gaps: partially usable, moderate penalty.
            score += 18.0 * (1.0 - post_residual as f64 / 25.0);
        }
    } else {
        // Perfect fill is heavily rewarded.
        score -= 80.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open bins pressure: prefer consolidating into existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward leaving this gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 30.0; // next item almost perfectly consumes the gap
            } else {
                score -= 8.0 * (1.0 - slack / post_residual as f64);
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // gap blocks the known next item
        }
    }

    // Mean residual coupling: if this bin's residual is far above the mean, it's a loose bin;
    // filling loose bins first keeps tight ones for tight items.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early stream: be slightly more willing to open bins (better long-run packing),
    // late stream: consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, new bin is correct
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect 2-chain: bin closes completely
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much remains after
            let second_post = post_residual - next_item_size;
            score -= 30.0 * (1.0 - second_post as f64 / bin_capacity as f64);
            // extra bonus if the second fit is also tight
            if second_post < 10 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow: penalize leaving residual smaller than next item
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // last item: pure tightness
        score -= 10.0;
    }

    // Relative-to-mean residual coupling: prefer bins with residual above mean
    // (keep tight bins tight, drain loose bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when decent open bins exist, but allow it
    // for large items early in the stream (future flexibility)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        // new bin is attractive if item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // avoid new bins when many are open with slack
        score += open_bins_count as f64 * 0.8;
        // if next item is big too, a fresh bin pairs well
        if next_item_size >= 50 && item_size >= 50 {
            score -= 10.0;
        }
    }

    // Penalize creating dead space (residual too small for any plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, but reward near-perfect fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // below-average-residual bins (tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: late in the stream, be more conservative about fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling: opening a new bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately attractive.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when existing bins are very fragmented or few fit.
        let pressure = (fitting_bins_count as f64).max(1.0).ln();
        score = 55.0 - 4.0 * pressure - 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more valuable.
        score -= 0.15 * item_size as f64;
        // If next item is large too, fresh bin keeps flexibility.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear polynomial shaping
    let mut score = pr
        + 20.0 * norm_pr * norm_pr          // penalize large dead space super-linearly
        + 15.0 * norm_pr * norm_pr * norm_pr;

    // Stream progress coupling: as stream advances, favor tighter packing more strongly
    let prog_coupling = 1.0 + 2.5 * progress * progress;
    score *= prog_coupling;

    // Interaction: post_residual vs mean residual — penalize bins with residual far above mean
    let mean_dev = pr - mean_residual;
    score += 0.35 * mean_dev * mean_dev / cap;

    // Lookahead: reward leaving space that could fit the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (-gap / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bins attractive only when current fit is bad
    if bin_residual == bin_capacity {
        let badness = norm_pr_of_fit(item_size, cap);
        score = cap * (0.9 + 0.6 * progress) - 30.0 * badness;
    }

    score
}

#[inline]
fn norm_pr_of_fit(item_size: u32, cap: f64) -> f64 {
    // larger items => opening new bin is more attractive
    (item_size as f64 / cap).powi(2)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (eighths)
    let item_class = (item_size * 8 + bin_capacity / 2) / bin_capacity; // 0..=8
    let next_class = if next_item_size == 0 { 0u32 } else { (next_item_size * 8 + bin_capacity / 2) / bin_capacity };

    // Reward bins whose post_residual matches a harmonic class of the next item (perfect fit ahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        score -= (bin_capacity as f64 / 4.0) * (1.0 - diff as f64 / (bin_capacity as f64 / 4.0).max(1.0)).max(0.0);
        // exact-fit class bonus
        if diff == 0 {
            score -= 25.0;
        } else if diff <= 5 {
            score -= 12.0;
        }
    }

    // Penalize post_residuals in "dead zones": small leftovers unlikely to fit future items
    // Harmonic dead-zone: post_residual in (0, 10) or in awkward modulo bands
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    let m = post_residual % 25;
    if m >= 1 && m <= 4 {
        score += 8.0; // awkward remainder band
    }

    // Prefer filling bins tightly: reward small post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    match post_residual / quarter.max(1) {
        0 => score -= 20.0,      // post_residual < 25: good fill
        1 => score -= 5.0,
        2 => score += 5.0,
        _ => score += 0.0,
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but bonus if current item is large and no tight fit exists
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= bin_capacity / 2 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big items pair badly; fresh bin OK
        }
    }

    // Late in stream: consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: favor reusing bins with large residuals (avoid fragmentation)
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Harmonic pairing: reward if next item's class complements this item's class (sums near capacity)
    if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small
    // to hold even the smallest plausible item (1..=20) are "dead space".
    // Penalize them heavily so bins with unusable remnants are avoided.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it would fit exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < 20 {
            score -= 15.0; // lookahead chains nicely into this bin
        } else {
            score += 5.0; // generous leftover is less valuable than tight chaining
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // by making the fresh empty bin less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the only option, allow opening a new bin.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., closer to being filled), driving consolidation.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) * -1.0
           + 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream urgency: as the stream progresses, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills what remains -> huge reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }

    // Next item fits in the leftover: mild reward for keeping the bin usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Next item cannot use the leftover: penalize proportional dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual as u32) as f64 * 0.3;
    }

    // Perfect closure: bin exactly filled now.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins, less so late in stream
    // or when existing bins are already tight (high mean residual).
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1 - open_bins_count as f64 * 0.5 - progress * 5.0;
    }

    // Prefer bins tighter than the current mean residual (low fragmentation).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Dead-space penalty: very small post_residual that can't fit typical items is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // the lookahead item pairs well with the current item in a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pair = item_size + next_item_size;
        if next_item_size > 0 && pair <= bin_capacity {
            // Perfect pairing potential: reward opening a new bin.
            score -= 25.0 * (1.0 - (pair as f64 / bin_capacity as f64));
        } else {
            // No pairing benefit: discourage opening a new bin when an open bin fits.
            if open_bins_count > 0 {
                score += 60.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly into this bin's post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 5.0;
    }
    // Many open bins: penalize spreading, encourage filling existing bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Time horizon: early in the stream, be slightly conservative (keep bins
    // balanced); late in the stream, prioritize immediate tightness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual is much larger than mean (unbalanced fill).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (0.5 + 0.5 * progress) + prn * (1.0 - progress);

    let mut score = pr * (1.0 + 0.35 * progress) + 12.0 * poly * prn;

    // Penalize dead space that no plausible future item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * (1.0 + progress);
        } else if nxt == post_residual {
            score -= 15.0; // perfect lookahead fit
        }
    } else {
        score += 0.5 * prn * prn * cap;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild penalty when bin diverges from mean residual (keeps bin pool homogeneous)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-to-slightly-high baseline, cheaper late in stream
    if bin_residual == bin_capacity {
        score += 20.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic class 0 (exact fill)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class analysis on post_residual using integer division thresholds.
    // Residuals <= 10 are near-dead space (items are >= 1, but small residuals
    // are hard to reuse); penalize proportionally to how "orphaned" they are.
    let dead_class = post_residual / 10; // integer division: 0..=10 harmonic bands
    score += dead_class as f64 * 3.0;

    // Modulo logic: residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are more reusable by future items.
    let reusable = (post_residual % 10 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves another residual: mild reward scaled by tightness
        let after2 = post_residual - next_item_size;
        score -= 20.0 - (after2 as f64) * 0.3;
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's remainder; penalize leftover
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into an existing bin is poor. Penalize empty-bin selection moderately,
    // but relax when open bins are all fragmented (low mean residual utility).
    if bin_residual == bin_capacity {
        let mean_util = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * mean_util - 30.0 * progress;
        if post_residual == 0 { score -= 1000.0; }
    }

    // Tightness bonus: prefer placements where the item occupies a large
    // fraction of the residual (capacity-fraction coupling).
    let fill_fraction = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_fraction * 25.0;

    // Small coupling: with many open bins, prefer consolidating into fuller bins.
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space too small for any item (min size 1, but tiny gaps waste).
            score += 60.0;
        } else if post_residual <= 20 {
            // Small gap: only usable by small items; penalize moderately.
            score += 25.0;
        } else if post_residual <= 40 {
            score += 8.0;
        }
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Lookahead fits but leaves another dead gap.
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins with residual near mean (balanced packing),
    // penalize outliers.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Only attractive when current bin would leave a bad gap and
    // open bins are few. Penalize new-bin choice generally.
    if bin_residual == bin_capacity {
        // Base penalty grows with number of open bins (their residual is wasted).
        score += 40.0 + open_bins_count as f64 * 3.0;
        // But if the item would leave a large usable gap in any bin anyway,
        // new bin becomes competitive: reduce penalty when item is large.
        if item_size >= 70 {
            score -= 45.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild bonus for filling large residual bins (best-fit tendency already
    // via post_residual, but reinforce for big items).
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit residual is better.
    score -= 0.5 * (bin_residual as f64 - post_residual as f64);

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Perfect chaining: next item exactly fills leftover space.
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward for near-perfect chain (gap <= 5).
            if gap <= 5.0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit: leftover post_residual is likely dead space.
            let waste = nxt - post;
            score += 0.6 * waste.min(post);
        }
        // Chain quality relative to mean residual across open bins.
        let dev = post - mean_residual;
        if dev < 0.0 {
            // Below-average residual = this bin is tighter than average; favor it.
            score += 0.15 * dev;
        } else {
            score += 0.25 * dev;
        }
    } else {
        // Last item: pure best-fit.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize new-bin candidate unless open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = (item_size as f64) < 0.5 * bin_capacity as f64;
        if poor_fit && next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            // Opening a fresh bin is attractive: item + next item pair well in empty bin.
            if (item_size + next_item_size) as f64 >= 0.85 * bin_capacity as f64 {
                score -= 20.0;
            }
        } else if poor_fit {
            score -= 3.0 * crowded.min(3.0);
        } else {
            // Good fit exists in an open bin: discourage new bin.
            score += 25.0;
        }
    }

    // Mild late-stream consolidation: prefer reusing bins as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when the item fits poorly anywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; reduced when item is large.
        let mut nb = 45.0 - 0.35 * item_size as f64;
        // If few bins can fit, opening new bin is more acceptable.
        if fitting_bins_count <= 1 {
            nb -= 25.0;
        }
        // Late in the stream, avoid opening bins for loose fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 20.0 * progress;
        score += nb;
        return score;
    }

    // Reward tight fits strongly (dead space is the enemy).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in this bin's post-residual, reward;
    // if next item would fit better in the residual we leave, penalize waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        }
        // If residual is small but nonzero and next item is large,
        // residual is dead space anyway — mild penalty.
        if next_item_size > post_residual && post_residual < 20 {
            score += 5.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer fewer open bins slightly (encourage packing into existing set).
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins that were already fairly full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear (quadratic + cubic) shaping
    let mut score = x * (1.0 + 0.8 * x + 0.6 * x * x) * cap;

    // Smooth coupling with stream progress: tight fits matter more later
    let tightness = 1.0 - x;
    score -= (1.0 + progress) * 12.0 * tightness * tightness;

    // Non-linear interaction: post residual vs mean residual
    score += 0.15 * (pr - mean_residual) * (1.0 + 0.5 * progress);

    // Last-chance bonus (smooth, exponential in fitting count)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - x) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += 3.0 * x * x * cap * (0.5 + progress);
    }

    // New-bin candidate: neutralize slightly scaled by progress
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.25 * progress) + 0.1 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveal
    // "harmonic" dead-space classes (e.g. residuals that can host common sizes).
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are exactly reusable by common item sizes (harmonic slots)
    for s in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if pr >= s && pr <= 80 {
            if pr == s {
                score -= 12.0; // perfect future fit
            } else if pr % s == 0 {
                score -= 6.0;  // divisibility = multiple future fits
            }
        }
    }

    // Penalize awkward residuals: small but non-zero dead space
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Penalize residuals that cannot host the lookahead item but could have
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 8.0;
    }
    // Reward residuals that can host the next item exactly
    if next_item_size > 0 && pr == next_item_size {
        score -= 10.0;
    }

    // Tight fit reward
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 8.0;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless residual here is hopeless
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.05;
        // Late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty proportional to how far above mean residual this bin sits
    // (prefer filling below-average-residual bins to balance)
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.03;

    // Integer-division threshold: residual in [1,15] band is near-dead
    if pr / 15 == 0 && pr > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Strong penalty for leaving residual smaller than the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
    }
    // Reward tight fits
    score -= 0.5 * item_size as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    } else {
        score -= 0.1 * pressure;
    }

    // Prefer bins with below-average residual (fill fuller bins first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, dead space unlikely usable
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain of tight fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits; penalize leftover after hypothetical next placement
            let second_residual = post_residual - next_item_size;
            score += second_residual as f64 * 0.3;
            if second_residual < 10 {
                score -= 15.0; // two-item near-perfect chain
            }
        } else {
            // next item cannot follow here; penalize larger post_residuals more
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.2;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    // (bins that are already mostly full), avoid wasting space in emptier bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // or no good fit exists. Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large_item && fitting_bins_count > 0 {
            score += 60.0; // discourage new bin when open bins can fit
        }
        // Slight preference for new bins early in stream is neutral.
    }

    // Mild penalty for leaving residuals that are hard to fill (small odd gaps)
    if post_residual > 0 && post_residual < next_item_size.max(10) as u32 {
        score += 8.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // spreading across bins (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt().recip();

    // Prefer bins among many fitting bins that leave least waste (tie-break already
    // via post_residual), and cap the influence of huge residuals.
    if post_residual as f64 > mean_residual * 2.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post residuals below the smallest plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if next item exactly chains (perfect pairing).
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual > 0 {
            // Penalize leaving a sliver the next item cannot use.
            score += 18.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.35 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate handling: mildly discourage opening new bins while
    // open bins have room, but encourage when open bins are fragmented.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score += 35.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // new bin preserves space for larger follow-up
        }
    }

    // Global fragmentation awareness: penalize placements into bins whose
    // residual deviates badly from the mean (keeps residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Time horizon: early in the stream, be frugal with bins (prefer existing);
    // late in the stream, pack greedily into tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (1.0 + open_bins_count as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 40.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize large dead space with a cubic term, softened early in the stream.
    score += 25.0 * norm_pr.powi(3) * (1.0 - 0.5 * progress);

    // Lookahead: reward if next item fits the post residual (smooth interaction).
    if nxt > 0.0 {
        let fits_next = (1.0 - ((pr - nxt) / cap).abs()).max(0.0);
        score -= 15.0 * fits_next * (pr >= nxt) as i32 as f64 * (0.4 + 0.6 * progress);
        // Penalize leaving space that neither fits next item nor is near zero.
        let waste = ((pr - nxt).max(0.0) / cap).powi(2);
        score += 20.0 * waste;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score += 10.0 * open_norm * norm_pr;

    // Deviation from mean residual: prefer bins with residual near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * (1.0 - progress);

    // New-bin candidate: add a threshold-like smooth penalty so new bins are only chosen
    // when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        score += (1.0 - pressure) * (20.0 + 30.0 * (1.0 - progress) * (1.0 - fit));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.5;

    // Dead-space penalty: residual that cannot hold the next item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward leaving exactly enough room for the lookahead item (perfect chaining).
            let gap = post_residual - next_item_size;
            score -= (bin_capacity as f64 / (gap as f64 + 1.0)) * 0.3;
        }
    }

    // Harmonic class logic: classify post_residual by integer division into
    // capacity-fraction bands; small dead-space classes get graded penalties.
    let cap = bin_capacity;
    let class = post_residual / (cap / 4); // 0..4 harmonic classes
    match class {
        0 => score -= 4.0,               // nearly full: excellent closure
        1 => score += 1.0,               // quarter-ish leftover: mediocre
        2 => score += 2.5,               // half-ish leftover: poor
        _ => score += 4.0,               // mostly empty: wasteful placement
    }

    // Modulo arithmetic: residuals that are multiples of small item sizes
    // (10, 20, 25) are more likely reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.0; }
        else if post_residual % 25 == 0 { score -= 1.5; }
        else if post_residual % 5 == 0 { score -= 0.5; }
        else { score += 0.8; }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin would leave big unusable gap) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let would_waste = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 12.0;                       // default: prefer existing bins
        score -= 14.0 * would_waste * (1.0 - progress * 0.5);
        if open_bins_count == 0 { score -= 20.0; }
    }

    // Slight preference for balancing residuals toward the mean.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still hold typical future items (>= 10).
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual exactly, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item nearly fits the dead space, soften the penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score -= 10.0;
    }

    // Slight pull toward the mean residual to keep bins balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: only attractive when the fit would leave tiny dead space
    // or no bin fits well; base cost keeps it as fallback.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // still better than wasting an open bin's space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // anticipates the next item size (perfect chain), penalize near-miss waste.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual == next_item_size -> strong bonus.
        if gap < 0.5 {
            score -= 45.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            // Next item still fits here: mild bonus scaled by tightness.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space.
            score += 18.0 * gap / bin_capacity as f64;
        }
        // Extra reward when the chain closes the bin completely after two steps.
        if post_residual as u32 == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable.
    let tightness = (mean_residual - post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * open_bins_count as f64;
        // But allow new bin if current item would leave a huge unusable gap
        // relative to typical next item sizes.
        if next_item_size > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Late-stream bias: consolidate into existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * 100.0;

    // Reward near-perfect fills strongly.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward; if next
    // item cannot fit in post-residual, penalize wasted space a bit more.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            // dead space too small for anything useful — acceptable
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when fits elsewhere are poor.
        score += 55.0;
        // Prefer opening new bins early in the stream or when few bins open.
        score -= 25.0 * (1.0 - progress);
        if open_bins_count < 3 {
            score -= 20.0;
        }
        // If next item is large and this item is small, a fresh bin keeps room.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && item_size <= 30 {
            score -= 15.0;
        }
    } else {
        // Prefer bins with residual close to the mean (balanced usage) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight preference for fuller bins when many bins are open.
        score -= 0.1 * open_bins_count as f64 * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap; // fraction of bin filled after placement
    let tight = 1.0 - (post / cap).powi(2); // smooth tightness reward

    let mut score = post;

    // Smooth non-linear coupling: tight fills are rewarded more as stream progresses.
    score -= 12.0 * tight * (0.5 + progress);

    // Penalize large post residuals with a quadratic dead-space term.
    score += (post * post) / cap;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits in the post residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score -= 8.0 * (-gap / cap).exp() * (1.0 - progress);
        score += 0.05 * gap;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.02 * (open_bins_count as f64) * ((mean_residual - post).abs() / cap);

    // New-bin candidate: bias toward reusing bins early, allow new bins late.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Dead-space penalty: residual in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: post_residual divisible by small moduli -> reusable slots.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0; // perfect decade slot
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
        if post_residual % 20 == 0 {
            score -= 3.0; // quarter-capacity class
        }
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + (next_item_size as f64 / cap) * 4.0; // chain two items
            // exact chaining bonus
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize leaving large stranded residue
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // existing fits are bad. Make empty-bin mildly unattractive unless residual
    // waste would be large.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 20.0;
        // early in stream, allow more bins (exploration); late, discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if current fit would strand a big residue relative to next item, new bin is fine
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 15.0;
        }
        if post_residual == 0 {
            score -= 30.0; // perfect-fit alternative: opening new bin never better
        }
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.5 * (mean_residual - (bin_residual as f64)).max(-20.0).min(20.0) * 0.3;

    // Mild coupling with open bins count: many open bins -> consolidate.
    if open_bins_count > 4 {
        score += 0.2 * open_bins_count as f64 * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins that can also fit the lookahead item (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that exactly blocks the next item badly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild attraction toward bins tighter than average (good fits cluster).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: penalize opening a new bin, scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * (step_index as f64 / total_items.max(1) as f64);
        // But allow it for very large items where a fresh bin is nearly perfect.
        if item_size >= 80 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0;
        } else if (post_residual as f64 - next).abs() <= 5.0 {
            score -= 200.0;
        }
        // Penalize residuals that are just barely too small for the next item
        // (dead space trap), but slightly less if next item is small anyway.
        if next_item_size > post_residual && post_residual > 0 {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 3.0;
        }
    }

    // Penalize small non-zero residuals (hard-to-use dead space),
    // scaled by how far into the stream we are (dead space hurts more early).
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (10 - post_residual) as f64 * (2.0 + 6.0 * (1.0 - progress));
    }

    // Relative-to-mean coupling: prefer bins whose post_residual stays near
    // the open-bin mean (balanced packing), penalize outliers.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or no good fits exist. Penalize mildly so open bins
    // with decent fits win.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // A new bin is good for big items, bad for small items.
        score += 60.0 * (1.0 - fill_ratio);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // More open bins => prefer filling them rather than growing the fleet.
        score += open_bins_count as f64 * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize residual windows that no plausible item can use.
    // Dead space in (0, 10) is nearly unusable given item sizes >= 1 but small items are rare;
    // treat very small leftover slivers as wasted unless exact.
    if post_residual > 0 && post_residual < 8 {
        score += 12.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item,
    // penalize bins that would strand the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward if next item would then nearly fill the bin too.
            let nxt_left = post_residual - next_item_size;
            if nxt_left <= 10 {
                score -= 12.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when the item is large relative to the bin (poor fits elsewhere) or when the
    // global mean residual suggests open bins are already crowded.
    if bin_residual == bin_capacity {
        let load_frac = (item_size as f64) / (bin_capacity as f64);
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 55.0;
        // Large items pack better in fresh bins; reduce penalty proportionally.
        new_bin_penalty -= 30.0 * load_frac;
        // If mean residual across open bins is small, open bins are crowded -> new bin less bad.
        let mean_load = 1.0 - (mean_residual / (bin_capacity as f64));
        new_bin_penalty -= 25.0 * mean_load.clamp(0.0, 1.0);
        // Late in the stream, opening new bins is less costly than stranding big leftovers.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty -= 15.0 * progress;
        // If the next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Global congestion: many open bins with large residuals -> prefer reusing
    // existing bins to consolidate and close them out.
    if bin_residual < bin_capacity {
        let consolidation = (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        score -= 8.0 * consolidation;
        // Mild penalty scaled by number of open bins to encourage closing bins early.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is closest to item size (best-fit flavor) with
    // a non-linear sharpening term.
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * gap * gap / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress;
    score += 12.0 * poly;

    // Tight fit reward, stronger as the stream progresses
    let tight = (item_size as f64 / cap) * (1.0 - norm_pr);
    score -= 18.0 * tight * (0.5 + progress);

    // Penalize large dead space relative to mean residual
    score += 0.35 * (pr - mean_residual).max(0.0) * (0.5 + progress);

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (pr - nx) / cap;
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Late-stream: prefer consolidating into few bins
    score += 0.6 * (open_bins_count as f64) * progress * norm_pr;

    // New-bin candidate: penalize opening a bin unless residual is tiny
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define "dead zones".
    // Residuals in [1,9] are hard to fill (min item 10 in classic streams), so penalize them.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr == 0 {
        score -= 40.0; // perfect closure
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if pr >= 3 * quarter {
        score += 8.0; // leaving a huge hole wastes the bin
    } else if pr >= quarter {
        score -= 10.0; // comfortable residual, reusable
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect pair
        } else if next_item_size <= pr {
            score -= 12.0;
            // harmonic residue match: next item shares class with post residual
            if pr % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer denser bins relative to the fleet mean.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the fleet is congested with small residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (mean_residual / bin_capacity as f64).min(1.0);
        score = 45.0 + 60.0 * progress - 40.0 * congestion;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin is useful
        }
    }

    // Mild tie-break on capacity fraction of the item itself.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
