pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    // -> chain two items into this bin, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small leftover
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 10 {
            score -= 35.0 - leftover as f64;
        } else {
            // penalize leaving a gap the next item can't use
            score += leftover as f64 * 0.35;
        }
    }
    // Next item won't fit here: dead space penalty grows with wasted capacity
    else if next_item_size > 0 {
        score += (post_residual as f64) * 0.15 + 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling tighter bins relative to the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Avoid opening new bins when a reasonable fit exists in an open bin
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty unless lookahead match is perfect
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Late in stream: prioritize compacting (fewer residual fragments)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but only if it's not
    // an awkward sliver that nothing else can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize unusable dead space: residual too small for the smallest item (1..100 unknown, assume ~10 floor)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 2.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need
    // (avoid wasting the large-residual bins on small items early).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (1.0 - t);

    // New-bin candidate handling: empty bin gets a mild opening cost that shrinks
    // over time / with stream size, so late in the stream we allow opening new bins
    // more freely rather than fragmenting nearly-full bins.
    if bin_residual == bin_capacity {
        let opening_cost = 30.0 * (1.0 - 0.5 * t);
        score += opening_cost;
        // If no open bin fits, opening is necessary: soften cost.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Time horizon: early on, be greedy for tight fits; late, prioritize avoiding new bins.
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.5 * progress);

    // Penalize residuals that are near the awkward middle range (dead space)
    let awkward = (pr_norm - 0.5) * (pr_norm - 0.5);
    score += 30.0 * awkward * (1.0 - progress);

    // Reward tight fits
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 10.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits well in the post-residual, favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 6.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Penalize deviation from mean residual to keep bins balanced
    score += (pr - mean_residual).abs() * 0.15;

    // New-bin candidate: neutral baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (hard to reuse) should be penalized when large.
    let cap = bin_capacity as f64;
    let half = cap / 2.0;
    let quarter = cap / 4.0;

    // Reward filling a bin very tightly (post_residual small).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize leftovers that sit in awkward modulo classes: multiples of 10
    // and values just above common item sizes are reusable; odd small gaps are not.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 8.0; // tiny dead space
    }
    if pr % 10 == 0 && pr >= 10 {
        score -= 6.0; // round leftover, likely reusable
    }
    if pr >= 30 && pr <= 40 {
        score -= 4.0; // can host medium items
    }
    if pr > half {
        score += (pr as f64 - half) * 0.15; // wasteful half-empty placement
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot follow here: mild penalty proportional to overflow
            score += ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if many open bins are fragmented (high mean residual), a fresh bin
        // is more attractive for future large items.
        score -= (mean_residual / cap).min(1.0) * 15.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Tie-break toward fuller bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Slight preference for bins below mean residual (balancing fragmentation).
    score += ((bin_residual as f64) - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever fit another item (min item = 1,
    // but practically small gaps) are wasted. Penalize non-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - pr * 4.0; // tiny gap => large penalty
    } else if post_residual < 25 {
        score += (25.0 - pr) * 1.5;
    }

    // Reward exact / very tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot go here anyway; slight penalty for stranding space
        score += pr * 0.2;
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones over new bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin has full residual. Make it attractive
    // only when the item is large or fits are scarce; otherwise discourage.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - large_item * 30.0 - scarcity * 40.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // laggard bin — favor consolidating into it.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect match leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize if next item cannot fit into post_residual (dead space for lookahead).
        if (post_residual as i64) < (next_item_size as i64) {
            score += 18.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Reward tight fits relative to current bin residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize bins whose residual deviates far below the mean residual (wasting large gaps).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.35 * dev;
    } else {
        score += 0.15 * dev.abs();
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild reward for compacting many bins early (fewer open bins is better).
    score += 1.5 * open_bins_count as f64;

    // Small penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less leftover is better, with superlinear penalty on waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize dead space that nothing could ever use (below minimum item size 1 handled generically).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0;
    }

    // Lookahead: strongly reward bins whose post-residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty scaled by how badly it misses.
            score += 3.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= 0.8 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it costly unless the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 10.0 * progress;
        // If existing bins fit poorly (large post_residual everywhere), opening a new bin is fine.
        let poor_fit = if post_residual >= 0 { (bin_capacity as f64 - item_size as f64) } else { 0.0 };
        let desperation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = base_penalty - 20.0 * desperation - 0.05 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr as f64;

    // Smooth polynomial coupling: waste penalty grows super-linearly,
    // and the curvature intensifies as the stream progresses.
    let curvature = 1.0 + 2.0 * progress;
    score += curvature * (x * x) * cap;

    // Dead-space term: residuals too small to ever fit typical items are bad;
    // penalize smoothly via a bell-like polynomial of x.
    let dead = x * (1.0 - x) * (0.5 - x); // negative in mid-range, positive near edges
    score += 8.0 * dead * cap * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless it's early
    // or the item leaves a very large unusable residual in existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 10.0 * (1.0 - progress) - 12.0 * scarcity * x * x;
    }

    // Slight preference to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - x);

    // Mean residual coupling: penalize deviating far from the fleet average residual.
    let dev = (mean_residual - pr).abs() / cap;
    score += 4.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual (cubic in fill fraction).
    score -= 10.0 * (1.0 - post / cap).powi(3);

    // Harmonic class penalty: awkward leftover remainders (mod-10 classes)
    // create dead space that rarely pairs with future items.
    if post_residual > 0 {
        let m = post_residual % 10;
        if m != 0 && m <= 4 {
            score += 2.0 + 0.5 * (4 - m) as f64;
        }
        // Very small unusable slivers (< 10) are dead weight.
        if post_residual < 10 {
            score += 5.0;
        }
    }

    // Lookahead: penalize if next item cannot use the leftover (dead space chain).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 6.0 + 0.05 * post;
    }
    // Lookahead synergy: reward if next item chains into a near-perfect fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        score -= 5.0 * (1.0 - r2 as f64 / cap);
        if r2 == 0 {
            score -= 5.0; // perfect two-item chain
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it expensive so it is chosen only when
    // all open fits are poor; relax slightly when mean residual is high
    // (open bins are already fragmented).
    if bin_residual == bin_capacity {
        score += 18.0 + 0.3 * mean_residual;
        // If the next item is huge, a fresh bin is more attractive.
        if next_item_size as f64 >= 0.6 * cap {
            score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild diversity pressure: if this bin's residual is far from the mean,
    // slightly discourage (keeps bin states clustered for easier packing).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any realistic item (min item = 1, but practically small gaps < 10
    // are nearly dead) get a steep penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in the 10..20 band are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }
    // Perfect fit: eliminate score entirely to strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity (fraction of bin filled).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: penalize bins when many bins are open, to encourage
    // consolidation; but reward using existing bins vs opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) when the mean is high.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement strongly (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual but post_residual is large,
    // slight penalty for fragmenting space the next item could have used.
    if next_item_size > post_residual as u32 && post_residual >= next_item_size.saturating_sub(0) && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline score
    // so it only wins when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score = 50.0 + post_residual as f64;
        // Late in the stream, opening new bins is less attractive (waste).
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
        // If no bin currently fits, new bin must be chosen: make it cheap.
        if fitting_bins_count == 0 {
            score = 0.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that no future item can use.
        if post_residual < 10 {
            score += 500.0; // tiny unusable sliver
        }
        // Lookahead: if next item fits exactly in the post residual, strong bonus.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 800.0;
            } else if next_item_size < post_residual {
                // Next item fits: reward small leftover after chaining.
                let chain_left = post_residual - next_item_size;
                score -= 300.0 - chain_left as f64 * 2.0;
            } else {
                // Next item does not fit: penalize dead space relative to next item.
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // Reward tightness relative to bin capacity.
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score += tightness * 50.0;

        // Compare post residual against mean residual across open bins.
        // Prefer bins whose residual stays near the mean (balanced packing),
        // but heavily prefer consuming large residuals when few bins fit.
        let dev = post_residual as f64 - mean_residual;
        if fitting_bins_count == 1 {
            // Last-chance bin: strong bonus to avoid opening a new bin.
            score -= 400.0;
        } else {
            // Penalize deviations from mean residual mildly.
            score += dev.abs() * 0.5;
        }

        // Early in stream: encourage filling bins greedily to keep bin count low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * post_residual as f64 * 0.3;

        // Many open bins: discourage spreading, favor bins that become nearly full.
        if open_bins_count > 4 {
            score += (post_residual as f64) * 0.2;
        }
    }

    // New-bin candidate: make empty bins less attractive unless the item is huge
    // (poor fit everywhere else) or no open bin is a good match.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            // Large item: opening a new bin is fine.
            score -= 150.0;
        } else {
            // Prefer using existing bins for small/medium items.
            score += 250.0 * (1.0 - fill_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 8.0;
        }
    }

    // Prefer bins with below-average residual (consolidate emptier space usage).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins already exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, allow new bin when item is large.
        if item_size > 50 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Time horizon: early in stream, be more conservative (favor spreading);
    // late in stream, pack tightly to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // Non-linear penalty for awkward residuals: mid-range dead space is worst
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 12.0 * awkward * awkward * (0.5 + 0.5 * progress);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, compact residuals more aggressively
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward filling bins that fit few candidates (last-chance bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize wasting it
        score += 5.0 * norm_pr * (1.0 - progress);
    }

    // Mean-residual divergence: keep residuals homogeneous
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: only attractive when residuals are large relative to item
    if bin_residual == bin_capacity {
        let squeeze = 1.0 - norm_item;
        score = 25.0 + 30.0 * squeeze - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -40.0,                      // perfect fit
        1..=5 => -25.0,                  // near-perfect
        6..=10 => -10.0,                 // still very usable for small items
        11..=20 => 0.0,
        21..=30 => 6.0,
        _ => 12.0,                       // large leftover: keep it flexible
    };
    score += class;

    // Reward tight fits proportionally (fraction of bin consumed)
    let fill = item_size as f64 / cap;
    score -= 18.0 * fill * fill;

    // Penalize awkward remainders via modulo structure of post_residual
    let m = (pr % 10) as f64;
    if pr > 0 {
        score += 0.6 * (5.0 - m).abs();
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New empty bin candidate: only attractive when item is large or nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let big = item_size as f64 / cap;
        let mean = mean_residual;
        // prefer new bin for big items or when mean residual is small/tight
        let attraction = 30.0 * big + (cap - mean.min(cap)) * 0.15
            + if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // baseline penalty so new bins aren't opened casually
        score += 14.0 - attraction;
    } else {
        // mild bonus for reusing existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    // Prefer bins below mean residual (loose bins) for big items, tight bins for small
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff * if item_size > 50 { 1.0 } else { -1.0 };

    // Slight pressure to close bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that can't fit even the smallest plausible follow-up item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, tolerate opening new bins for bad fits.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        score = bin_capacity as f64 + 20.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // A new bin is good if the current item would leave a large usable gap
        // and no open bin fits well (few fitting bins).
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Lookahead: if next item fits exactly into post_residual, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for blocking.
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward small leftover after the lookahead item
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize wasted capacity that will strand
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.15 * stranded;
        }
    }

    // Compare against mean residual: bins far below mean residual are "sinks";
    // using them for large items is fine, but avoid dumping small items there.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score += 0.10 * (mean_residual - res_f);
    } else {
        score -= 0.05 * (res_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to mean residual of open bins,
        // opening a fresh bin becomes more attractive.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 25.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for diversity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fill_ratio * fill_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            if post_residual - next_item_size < 20 {
                score -= 6.0; // chain of near-perfect fits
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // creates stranded space relative to lookahead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
        // Penalize opening new bins when existing options exist.
        score += 25.0;
        score -= 20.0 * (1.0 - congestion); // relief if few bins fit the item
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual is high, open bins are fragmented; new bin is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 8.0;
        // Large items relative to mean residual favor a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        // Prefer using bins with larger residuals among open bins (best-fit tiebreak).
        score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * 10.0;
        // Slight penalty for spreading across too many open bins.
        score += 0.3 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    }

    // Global balance: keep residuals near the mean to avoid fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
