    let norm_post = post / cap;

    // Base: quadratic penalty on post residual (waste minimization)
    let mut score = post * (1.0 + 0.8 * norm_post);

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits mildly; late, penalize large residuals strongly
    let progress_coupling = norm_post * norm_post * (1.0 + 2.0 * progress);
    score += progress_coupling * cap * 0.35;

    // Interaction: post residual vs mean residual (avoid leaving bins worse than average)
    let mean_coupling = (post - mean_residual) / cap;
    score += 4.0 * mean_coupling * mean_coupling * mean_coupling;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 12.0 * last_chance * last_chance;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Slight preference for keeping many open bins consolidated early
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Smooth new-bin tie-breaker: empty bin gets a mild fixed offset that decays with progress
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: mod-10 buckets.
    let r = post_residual;
    let class = r % 10;

    // Reward residuals that are "clean" harmonic classes (0, 50, 25, 75) —
    // these pair well with common item sizes drawn from integer grids.
    match class {
        0 => score -= 8.0,
        _ => {}
    }
    if r % 50 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 3.0;
    }

    // Penalize residuals in awkward classes (1..=9 small crumbs) heavily.
    if r > 0 && r < 10 {
        score += 15.0;
    }

    // Perfect fit: zero residual is ideal.
    if r == 0 {
        score -= 40.0;
    }

    // Coupling with lookahead: if next item exactly fills post_residual,
    // this placement creates a perfect chain — strong reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 30.0;
    }
    // If next item leaves a clean class after filling post_residual, mild reward.
    if next_item_size > 0 && r >= next_item_size && (r - next_item_size) % 10 == 0 {
        score -= 5.0;
    }
    // If next item cannot fit in post_residual, the leftover is likely dead space
    // unless it's zero — penalize proportionally to crumb size.
    if next_item_size > r && r > 0 {
        score += (r as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin; make it slightly unattractive
        // unless existing bins have poor fits (handled by penalties above).
        score += 5.0;
        // If the item is large relative to capacity, starting fresh is fine.
        if item_size * 2 >= bin_capacity {
            score -= 4.0;
        }
    }

    // Prefer tighter bins overall: penalize bins far above mean residual
    // (they waste capacity if left under-filled).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Late in the stream, be more conservative with open bins: fewer open bins
    // is better, so favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1,
    // but practically gaps below ~10 are dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Unusable gap for the known next item: dead space relative to lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits (small usable post residual).
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open bins pressure: discourage spreading across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // If item leaves large residual in a fresh bin, that's fine early on.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (converging toward uniform fills).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual).abs().min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 40.0; // exact fit for the upcoming item
        }
        // Penalize residuals that are just barely too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility on small items.
    if item_size < 20 && post_residual > 70 {
        score += 10.0;
    }

    // Slight preference to fill bins later in the stream (compaction).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // New-bin candidate: make it unattractive unless it's genuinely better than a poor fit.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty: leftover space that cannot host the lookahead item
        // is likely wasted forever (items are 1..=100).
        if next_item_size > 0 && post_residual > 0 {
            if (next_item_size as u32) > post_residual {
                // unusable gap for the next item; penalize proportionally to gap size
                score += 0.35 * post_residual as f64 * (1.0 + 0.5 * progress);
            } else {
                // lookahead still fits: small reward for keeping usable space
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin — reward, scaled by how well the item fills it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 12.0 + 18.0 * fill;
    }

    // Prefer bins whose residual is close to what we consume (tight fit signal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: the immediate waste plus a fixed overhead.
        let mut new_bin_score = (bin_capacity - item_size) as f64 + 25.0;
        // If no open bin can fit the item, opening is unavoidable-ish: cheaper.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // If the next item can pair with the current one in the fresh bin,
        // opening a new bin enables a clean pairing — reward.
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity - item_size {
            new_bin_score -= 15.0;
        }
        // Late in the stream, waste matters less than bin count; slightly cheaper to open.
        new_bin_score -= 8.0 * progress;
        // Crowding: many open bins with large mean residual → reuse them instead.
        if mean_residual > item_size as f64 {
            new_bin_score += 10.0;
        }
        score = score.max(new_bin_score.min(score)) * 0.0 + new_bin_score;
        return score;
    }

    // Mild penalty for spreading across too many bins when mean residual is small.
    if open_bins_count > 4 && mean_residual < 15.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth penalty for residual that is hard to fill later (near-dead space)
    let deadness = (pr_norm * (1.0 - pr_norm)).sin();
    score += 20.0 * deadness * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 10.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins below mean residual (larger space) slightly
    score += 0.3 * (pr - mean_residual);

    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 5.0 * (nx / cap);
        } else {
            score += 8.0 * (1.0 - pr_norm);
        }
    }

    // Mild pressure against accumulating many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: baseline competitive score with progress-dependent threshold
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - 5.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), with harmonic class bonus
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Harmonic classes: bucket post_residual by capacity/8 segments
    let seg = (post_residual * 8) / bin_capacity;
    match seg {
        0 => score -= 25.0,           // near-perfect fill
        1 => score -= 12.0,           // good fill
        2 => score -= 4.0,
        3 => score += 3.0,            // awkward middle gap
        4 => score += 0.0,
        5 => score += 2.0,
        6 => score -= 2.0,            // roomy bin, still useful
        _ => score -= 6.0,            // nearly empty bin
    }

    // Dead-space penalty: unusable sliver (< 10% capacity)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 18.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead compatibility: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic pairing: next item leaves another usable remainder
            let next_post = post_residual - next_item_size;
            if next_post < bin_capacity / 10 && next_post > 0 {
                score += 5.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0;
        // early stream: prefer opening bins (future flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item if it would fit the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if the next item cannot fit into the post residual (wasted lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild preference toward tighter bins (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make empty bins mildly attractive only
    // when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 8.0;
        }
        return score;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chaining: this bin becomes exactly full next step
        } else if gap <= 5.0 {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // next item can't use this bin; dead space unless post_residual tiny
            score += (post_residual as f64) * 0.3;
        } else {
            score += gap * 0.4;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize leaving large unusable fragments (small dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = post_residual as f64 / bin_capacity as f64;
        score -= 40.0 * (1.0 - tight).exp() * 10.0; // strong bonus for small post residual
        if post_residual < 10 {
            score -= 25.0;
        }
    }

    // Penalize dead space that cannot fit typical small items (min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty proportional to gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // As stream progresses, prefer consolidating into open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * t;
        // If many bins are open, discourage yet another one.
        score += 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
        // But if item is large and mean residual is small, new bin may be justified.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is closest to item size (best fit flavor) beyond post residual.
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack * slack / (bin_capacity as f64);

    // Mild preference for bins with residual below mean (fill the emptier bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: polynomial in normalized post_residual modulated by progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 24.0 * poly * cap * (0.5 + progress);
    // Penalize large dead space more as stream progresses (fewer chances to reuse it)
    score += progress * norm_pr * norm_pr * cap * 0.35;
    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 6.0 * (-(pr / cap) * 4.0).exp();
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    }
    // Slight preference for bins below mean residual (keeps balance of usable space)
    score += 0.05 * (mean_residual - pr);
    // New-bin candidate: penalize mildly unless current residuals are all poor
    if bin_residual == bin_capacity {
        let tightness = (-(mean_residual / cap) * 2.0).exp();
        score += 12.0 - 10.0 * tightness;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of common small item sizes) are worth keeping.
    let pr = post_residual;
    if pr > 0 {
        let mut usable = false;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                usable = true;
            }
        }
        if usable {
            score -= 12.0; // leftover aligns with harmonic classes: easy to fill later
        } else {
            score += 8.0; // awkward leftover, dead-space risk
        }
        // Small leftovers are near-perfect fills regardless of class
        if pr <= 5 {
            score -= 25.0;
        } else if pr <= 15 {
            score -= 10.0;
        }
    } else {
        score -= 40.0; // exact fit: ideal
    }

    // Dead-space penalty: leftover too small for the minimum item size (1..100 interface)
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item exactly
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 30.0;
        } else if pr >= next_item_size {
            score -= 6.0;
        } else {
            score += 10.0; // next item won't fit here
        }
        // Integer-division harmonic: leftover divisible by next item size
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 55.0;
        // Cheaper to open new bin when open bins are already fragmented
        score += open_bins_count as f64 * 1.5;
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If mean residual is large, open bins have room: penalize new bin more
        score += (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
    }

    // Prefer tighter bins (smaller residual before placement) slightly
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 25.0;
    }

    // Reward tight fits relative to the item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if post_residual > 0 {
            // Next item won't fit: post residual becomes dead space.
            score += 8.0;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but encourage filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Favor bins with residual close to mean (balanced usage).
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect fit for the next item
        } else if post_residual as f64 >= nxt {
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // dead space that the next item cannot use
            score += 0.5 * (nxt - post_residual as f64);
        }
        // bonus if placing here leaves room for next item in THIS bin
        if post_residual as f64 >= nxt {
            score -= 10.0;
        }
    }

    // Penalize large leftover waste relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tighter bins (best-fit flavor)
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: make it attractive only when existing bins would leave bad dead space
    if bin_residual == bin_capacity {
        let waste_if_existing = fitting_bins_count.saturating_sub(1) as f64;
        if post_residual as f64 > 0.0 && next_item_size as f64 > post_residual as f64 && waste_if_existing > 0.0 {
            score -= 5.0; // open fresh bin when fits would fragment space
        } else {
            score += 15.0; // default: prefer reusing open bins
        }
    }

    // Late in the stream: consolidate, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if it nearly fits, mild penalty for blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Time horizon: early in the stream, be pickier (prefer new bins for big items);
    // late in the stream, consolidate into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 10.0 * progress;
    if bin_residual < bin_capacity {
        score -= consolidation;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // New-bin candidate: make empty bins less attractive unless the item is large
    // relative to the bin or open bins are scarce/tight.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pn = pr / cap;
    let t = progress;
    score += 8.0 * pn * pn * (1.0 + 2.0 * t) - 6.0 * pn * t * (1.0 - t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 4.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            score -= 2.0 * (pr - nx) / cap;
        }
    }

    // Reward tight fits (small post_residual relative to bin_residual)
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 6.0 * tightness * tightness * (1.0 - t);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - t);
    }

    // Mild penalty proportional to number of open bins (prefer consolidation)
    score += 0.05 * open_bins_count as f64 * (0.5 + t);

    // Coupling with mean residual: prefer bins deviating from mean toward fuller
    score -= 0.3 * (mean_residual - pr) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual in low harmonic classes
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Dead-space penalty: leftovers that few item sizes can use (harmonic classes
    // of capacity that are hard to fill: 51..70 etc.)
    if post_residual > 50 && post_residual < 70 {
        score += 12.0;
    }
    if post_residual > bin_capacity / 2 && post_residual < bin_capacity * 3 / 4 {
        score += 4.0;
    }

    // Modulo coupling: does post_residual combine with next_item_size nicely?
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: reward proportionally to how well it fills leftover
        let nxt_fill = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * nxt_fill;
        // exact harmonic match bonus
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize large unusable residue
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 50.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild preference for fuller bins overall (relative to mean residual)
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: bins whose residual is in the "flexible"
    // class (>= 30) are more reusable
    if post_residual >= 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 25.0; // nearly dead space (rarely usable)
    } else if post_residual < 35 {
        score += 8.0; // moderately wasteful gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (more filled than average).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Lookahead: if next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item cannot fit the post residual, the leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: baseline reference; keep it attractive only when
    // existing placements would be very poor.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: excellent, penalize score proportionally to tightness of chain
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.3 * chain_tightness;
        } else if post_residual >= next_item_size / 2 {
            // partial match: mildly favorable
            score -= 5.0;
        } else {
            // dead space relative to next item: penalize small residuals
            score += 8.0;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could still take it
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    // Early stream: be slightly more conservative with existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large wasted residual: dead space that likely can't be reused.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Reward tight fits (small post-residual) super-linearly.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item also fits here after this placement,
    // reward this bin for chaining compatible items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving residual that barely fails to fit the next item (awkward gap).
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > -10.0 && gap < 0.0 {
            score += 6.0;
        }
    }

    // Prefer bins whose residual deviates from the mean (keep a spread of bin sizes;
    // fill down the most-full usable bins first implicitly via post_residual already).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as more bins are open.
        score += 15.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
        // But if no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else if open_bins_count > 3 {
        score -= 2.0; // mild preference for using existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on wasted space, amplified over stream progress
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = (1.0 + progress).powf(1.0 + norm_post);
    score *= progress_coupling;

    // Reward tight fits: subtract smooth function of normalized fill
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * (1.0 + progress);

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap > 0.0 {
            let gap_frac = gap / cap;
            score += 15.0 * gap_frac * gap_frac * (1.0 + gap_frac);
        } else {
            // next item fits perfectly: reward
            score -= 10.0 * (1.0 - (post / nxt.max(1.0)).abs());
        }
    } else {
        // last item: strongly prefer any bin that fits
        score -= 50.0;
    }

    // Last-chance bin bonus: only one bin can fit the item
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins; smooth in open_bins_count
    let bin_pressure = (open_bins_count as f64).ln_1p();
    score += 2.0 * bin_pressure * (1.0 - norm_post);

    // Encourage bins with residual below mean (consolidation)
    score += 1.0 * (mean_residual - post) / cap;

    // New-bin candidate: penalize unless current bins are all poor fits
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * scarcity - 20.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // coarse classes (multiples of 10) are rewarded; awkward remainders penalized.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // perfectly aligned leftover (class 0) is most reusable
        score -= 12.0 * (1.0 - class as f64 / 10.0);
        // small dead space (<10) is nearly unusable: strong penalty
        if pr < 10 {
            score += 25.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 60.0;
    }

    // Tightness: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the pair leftover
            let pair_left = pr - next_item_size;
            score -= 15.0 * (1.0 - (pair_left % 10) as f64 / 10.0);
            if pair_left == 0 { score -= 20.0; }
            if pair_left < 10 { score += 15.0; }
            score += 0.05 * slack;
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += 0.08 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + 0.3 * waste;
        // opening a new bin is fine late in the stream or when open bins are full-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0;
        }
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    // Prefer bins with residual far from mean (deviation = distinctive fit)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Harmonic threshold on integer division: bins where item_size divides
    // residual evenly get a bonus
    if item_size > 0 && (bin_residual % item_size) == 0 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / 100.0);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: dead space likely
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidation into existing bins.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far below mean residual wastes spread.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // New-bin candidate: only attractive when it enables a large fresh residual
    // (i.e., item is huge and no good fit exists).
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 45.0; // opening fresh bin for big item is fine
        }
        if post_residual >= 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits: reward tight coupling (exact match best).
            score -= 12.0 * (1.0 - diff / cap);
            // Perfect chain: post_residual == next_item_size
            if diff < 0.5 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize by the shortfall magnitude.
            score += 6.0 + 4.0 * (next - post_residual as f64) / cap;
        }
        // Extra reward if next item leaves a still-usable residual (>= 10).
        if post_residual as u32 >= next_item_size {
            let post_next = post_residual as f64 - next;
            if post_next >= 10.0 {
                score -= 3.0 * (post_next / cap);
            } else if post_next > 0.0 {
                // Tiny dead space after next item: slight penalty.
                score += 2.0 * (1.0 - post_next / 10.0);
            }
        }
    } else {
        // Last item: just minimize residual directly (already the base score).
    }

    // Penalize bins with residual far below mean (fragmented bins) unless it's a tight fit.
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    if post_residual as f64 > mean_residual + 20.0 {
        score += 2.0; // wasteful placement relative to average
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; softened when many bins are open or stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 - 10.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 5.0; // discourage ignoring existing fitting bins
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= 2.0 * (1.0 - bin_residual as f64 / cap) * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Penalize large dead space (post residual that is hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are near-useless
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here; mild penalty
        }
    }

    // Global state: when many bins are open, discourage fragmenting further;
    // prefer packing into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.15 * crowding * (1.0 - progress);

    // Relative to mean residual: bins tighter than average are good targets.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the item is large and no tight fit is likely elsewhere.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), smoothly non-linear
    let mut score = post * (1.0 + 0.5 * x * x);

    // Polynomial coupling of post_residual with stream progress:
    // early on, leave room (mild penalty for very tight fits is low);
    // late in the stream, tight fits become critical.
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * progress * progress;

    // Dead-space penalty: post residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let waste = (nxt - post) / cap;
            score += 18.0 * waste * (1.0 + progress);
        } else {
            // reward bins whose post residual still accommodates the next item
            score -= 4.0 * (post / nxt.min(cap)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight preference to keep open-bin count from exploding early
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean-residual coupling: when mean residual is low, conserve large residuals
    let mr = mean_residual / cap;
    score += 6.0 * x * (0.5 - mr) * (0.5 - mr);

    // New-bin candidate handling: empty bin gets a moderate baseline penalty,
    // overcome only when open bins would create severe waste.
    if bin_residual == bin_capacity {
        score = 30.0 + 20.0 * progress - 6.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of common
    // item-size classes (10,20,25,50) are more reusable.
    let pr = post_residual as i64;
    let mut bonus = 0.0f64;
    for m in [10i64, 20, 25, 50] {
        let r = pr % m;
        let dist = r.min(m - r) as f64;
        bonus += (m as f64 / 10.0) * (1.0 - dist / (m as f64 / 2.0));
    }
    score -= 1.5 * bonus;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and post residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            }
            score -= 10.0;
        } else {
            // next item won't fit here: penalize leaving large-but-unusable gaps
            if post_residual > next_item_size * 3 / 2 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer tighter bins when many bins are open (keep mean residual spread low).
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += 20.0 * (frac - mean_residual / bin_capacity as f64).abs();

    // Early in the stream, allow opening fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // mild preference for reusing bins late in the stream
        score -= 5.0 * progress;
    }

    // Integer-division threshold: residuals in [50,100) quarter classes.
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 5.0,
        1 => 2.0,
        2 => 0.0,
        _ => -3.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below minimum item size are worthless
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for tiny gaps relative to capacity (dead space)
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.0 && gap_ratio < 0.1 {
        score += 30.0 * (0.1 - gap_ratio) * 10.0;
    }

    // Reward near-perfect fits (post_residual close to zero but still usable)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (bin_capacity as f64 / 10.0);
    score += pressure * 2.0 * (0.5 + progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit post residual and post residual is small, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Prefer bins with residual below mean (tighter bins) for better packing
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // leftover can still host next item: mild reward proportional to tightness
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, worse if truly unusable
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 50.0 * (10.0 - dead);
            } else {
                score += 20.0;
            }
        }
    } else {
        // last item: strongly prefer minimal leftover
        score += 0.0;
    }

    // Compare against mean residual: prefer filling bins that are below-average residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins when open bins exist that fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 + mean_residual * 0.5;
    }

    // Late in the stream, be more conservative: prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual, reward;
    // if next item is large and post_residual is small, this bin is "done" — fine.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nfit = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - nfit / bin_capacity as f64);
        } else {
            // Bin becomes sealed after this placement — good if post_residual small.
            score += 2.0 * (post_residual as f64 / 10.0);
        }
    } else {
        // Last item in stream: just minimize waste.
        score += 5.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0 * mean_residual / bin_capacity as f64;
    }

    // New-bin candidate logic: empty bin should only win when the item fits
    // poorly everywhere else. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins wastes capacity; penalize more.
        score += 15.0 * progress;
        // If several bins already fit, definitely avoid a new bin.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    }

    // Mild preference for fuller bins (smaller residuals) overall.
    score += 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * t * t) + 0.6 * norm_pr * norm_pr * (1.0 - t);

    // Penalize small-but-nonzero dead space more as stream progresses
    let dead = (pr - 1.0).max(0.0) / cap;
    score += 1.5 * dead * dead * (0.5 + t);

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.0 * fit_ratio * fit_ratio * (1.0 - t);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - 0.5 * t);
    }

    // Lookahead coupling: prefer bins whose post_residual fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.2 * (next_item_size as f64 / cap) * (1.0 + t);
    } else if next_item_size > 0 {
        score += 0.5 * t;
    }

    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Keep new-bin candidate competitive when residuals are poor
    if bin_residual == bin_capacity {
        score = 0.9 + 0.3 * t - 0.5 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 classes map to how reusable
    // the leftover space is for typical item sizes (multiples of 10).
    let pr = post_residual;
    let cls = pr % 10;
    let class_bonus: f64 = match cls {
        0 => 60.0,          // leftover divisible by 10: highly reusable
        1..=5 => 20.0,      // small leftover, near-dead space but small waste
        _ => 0.0,           // awkward leftover
    };
    score -= class_bonus;

    // Dead-space penalty: leftover too small for any plausible item (>=1..100,
    // realistically >= 10): penalize hard.
    if pr > 0 && pr < 10 {
        score += 80.0;
    }

    // Can the bin still fit the lookahead item after this placement?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward leaving room for the next item, scaled by how snugly it fits.
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 + 0.5 * slack;
        } else {
            // Next item won't fit here: mild penalty, worse if it's a big item.
            score += 15.0 + 0.3 * next_item_size as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Integer-division thresholds on post_residual: quantize usability.
    let q = pr / 25; // 0..4 quarters of capacity
    score -= match q {
        0 => 5.0,
        1 => 15.0,
        2 => 25.0,
        3 => 20.0,
        _ => 10.0,
    } as f64;

    // New-bin candidate: prefer it only when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        // Open a new bin if mean residual is large (open bins are full-ish / fragmented)
        score = 45.0 - 40.0 * frag;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can always host the next item
        }
    }

    // Stream progression: later in the stream, be more conservative about
    // opening bins; favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = if next_item_size > bin_capacity { cap } else { next_item_size as f64 };
    let open_f = (open_bins_count as f64).min(40.0);
    let progress = if total_items == 0 {
        0.0
    } else {
        ((step_index as f64) / (total_items as f64)).clamp(0.0, 1.0)
    };
    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.0
    };
    let mean_ratio = mean / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let horizon = 0.85 + 0.30 * progress;

    let mut score = post * (1.0 + 0.012 * open_f);

    score += (residual - mean).max(0.0) * 0.05;
    score -= (mean - residual).max(0.0) * 0.03;

    if post_residual == 0 {
        score -= cap * (0.85 + 0.02 * open_f) + item * 0.20;
    }

    let mut dead_severity = 0.0;
    if next > 0.0 && post_residual > 0 && post < next && post <= cap * 0.38 {
        let missing_frac = ((next - post) / next).clamp(0.0, 1.0);
        let smallness = (1.0 - post / cap).clamp(0.0, 1.0);
        dead_severity = (missing_frac * (0.35 + 0.65 * smallness)).clamp(0.0, 1.0);
        score += cap * (0.95 + 1.05 * dead_severity) * horizon;
    } else if next_item_size == 0 && post_residual > 0 {
        score += post * (0.35 + 0.04 * open_f);
    }

    if next_item_size > 0 && post_residual > 0 && post == next {
        score -= cap * 0.40;
    }

    if !is_new_bin && fitting_bins_count == 1 {
        let dead_block = (dead_severity * 0.90).clamp(0.0, 0.90);
        score -= cap * (0.45 + 0.15 * progress) * (1.0 - dead_block);
    }

    if is_new_bin {
        score += cap * 0.15;

        if fitting_bins_count > 0 {
            let alt_pressure = if fitting_bins_count > 1 {
                0.02 * ((fitting_bins_count - 1) as f64).min(10.0)
            } else {
                0.0
            };

            score += cap * (0.30 + 0.018 * open_f + 0.10 * mean_ratio + 0.12 * progress + alt_pressure);

            if next_item_size == 0 {
                score += cap * 1.50;
            }

            if next_item_size > 0 && post == next {
                score -= cap * 0.25;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild bonus proportional to slack
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space creation
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) == 0 || (post_residual as f64).abs() < 5.0;
        if !tight_fit {
            score += 120.0;
        }
    }

    // Late in stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Chain fit: next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (keep large-residual bins flexible for larger future items)
    let deviation = mean_residual - bin_residual as f64;
    score += deviation * 0.15;

    // Time horizon: early in stream, be more conservative about filling bins tightly;
    // late in stream, squeeze hard to avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // Fragmentation pressure: many open bins -> penalize spreading, favor tight packing
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless current placement is poor
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity
        score += 15.0;
        // If no open bin is a good fit (item leaves big residual elsewhere), new bin is OK
        if post_residual < 20 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear coupling: squared normalized post-residual weighted by stream progress.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction of fill fraction and progress: reward tight fits more as stream advances.
    score -= 60.0 * fit * fit * fit * (0.3 + 0.7 * progress);

    // Smooth dead-space penalty: residual too small to hold typical future items.
    let dead = (norm_pr - 0.2).max(0.0) * (norm_pr - 0.55).max(0.0);
    score += 90.0 * dead * dead;

    // Lookahead coupling: penalize if next item cannot use the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 25.0 * (nx - pr) / cap * (1.0 - progress);
        } else {
            score -= 15.0 * (1.0 - (nx - pr).abs() / cap);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mild diversification: discourage piling into crowded bin sets early.
    score += 3.0 * (open_bins_count as f64).ln() * (1.0 - progress) * norm_pr;

    // Mean-residual attraction: prefer bins near the mean residual (smooth quadratic).
    score += 5.0 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;

    // Reward residual sizes that are "friendly" (small, likely fillable later)
    if post_residual <= quarter / 2 {
        score -= 12.0;
    } else if post_residual <= quarter {
        score -= 6.0;
    } else if post_residual <= 2 * quarter {
        score += 4.0;
    } else if post_residual <= 3 * quarter {
        score += 9.0;
    }

    // Exact-fit and near-exact-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Harmonic resonance: post_residual divisible by small integers is more reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
        if post_residual % 7 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 15.0 + (slack as f64).min(20.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // pairing potential favors new bin slightly
        }
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps in (0, 10) are "unusable dead space" for typical items; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty for any residual smaller than the smallest plausible item (1..=100 range:
    // gaps below ~10 are hard to fill; gaps 10..30 are moderately risky).
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0;
    }

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // --- Last-chance bin bonus ---
    // If this is the only bin that can fit the item, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin should only win when the fit into existing bins is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress
        // (early on, opening bins is cheaper; late, prefer packing).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 25.0 * progress;

        // If some open bin fits the item decently, discourage new bin more.
        if fitting_bins_count > 0 {
            // Lookahead: if next item also fits the leftover here, opening is less bad.
            if next_item_size > 0 && next_item_size <= item_size {
                score -= 10.0;
            }
        }
        // Opening a bin when many bins are already open is wasteful.
        score += (open_bins_count as f64).sqrt() * 4.0;
    }

    // --- Open-bin pressure ---
    // Mildly prefer bins with residual close to mean_residual (keeps bin states uniform),
    // and penalize using bins that are much emptier than average for small items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling emptier bins with larger items (large item into large residual is natural;
    // small item into large residual wastes potential).
    let size_frac = item_size as f64 / bin_capacity as f64;
    let resid_frac = bin_residual as f64 / bin_capacity as f64;
    if size_frac < 0.5 && resid_frac > 0.6 {
        score += 8.0;
    }

    // Lookahead synergy: if the post residual exactly accommodates the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 15.0; // would leave dead space after next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this bin becomes a perfect 2-item chain — reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        let lookahead_fit = post_residual as i64 - next_item_size as i64;
        if lookahead_fit == 0 {
            score -= 800.0;
        } else if lookahead_fit > 0 && lookahead_fit <= 10 {
            score -= 250.0;
        } else if lookahead_fit < 0 && (-lookahead_fit) <= 5 {
            // Next item slightly too big: mild penalty for near-miss chain.
            score += 60.0;
        }
    }

    // Penalize leaving residual that is likely unusable given next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter;
    // prefer filling tight bins first to consolidate space.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 50.0;
        // But if the item is small relative to capacity and mean residual is
        // high, opening a fresh bin may be fine — soften the penalty.
        if (item_size as f64) < 0.3 * bin_capacity as f64 && mean_residual > 40.0 {
            score -= 70.0;
        }
        // Lookahead-aware new-bin decision: if next item is large and would
        // waste this bin, encourage opening a new one.
        if next_item_size > 60 && item_size < 30 {
            score -= 90.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer closing
    // out bins (small post_residual) to avoid stragglers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.5;

    // Tight-bin preference scaled by number of open bins (more bins open =>
    // more aggressive consolidation needed).
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
