pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * pr * norm_pr * (1.0 - progress);

    // Smooth cubic coupling between post_residual and progress
    score += 0.15 * cap * norm_pr * norm_pr * (0.5 + progress * progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dead = (pr - mean_residual).abs();
    score += 0.05 * dead * (1.0 + norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin (smooth sigmoid-like)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 + progress);

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    let next_fits = if (next_item_size as f64) <= pr && next_item_size > 0 { 1.0 } else { 0.0 };
    score -= 8.0 * next_fits * (1.0 - progress * 0.5);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-to-slightly-high baseline unless residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that no small item can use: post_residual below 10 is wasted.
    if post_residual < 10 {
        score += 18.0;
    } else {
        // Harmonic class bonus: post_residual that is a "nice" size (divisible by 10 or 20)
        // is more likely to be filled by future items.
        if post_residual % 10 == 0 {
            score -= 6.0;
            if post_residual % 20 == 0 {
                score -= 3.0;
            }
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score += 20.0,           // unusable sliver
        1 => score += 4.0,
        2 => score -= 3.0,            // sweet spot for small items (20-29)
        3 => score -= 2.0,
        4 => score -= 4.0,            // great slot for mid items
        5 => score -= 1.0,
        6 => score += 0.5,
        7 => score += 1.0,
        8 => score += 2.0,
        9 => score += 3.0,
        _ => score += 1.5,            // nearly empty bin
    }

    // Lookahead: does this post_residual accommodate the next item well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could also land here; slight reward, more if it fits snugly after.
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 5.0; // perfect two-item packing
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when all open bins
    // fit poorly (large post_residual after placement) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it "wastes" the residual of open bins.
        score += 25.0;
        // Encourage opening new bins early in the stream or when open bins are congested.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If existing bins would leave big residue, new bin is relatively better.
        score -= 0.15 * mean_residual;
        // Few open bins => spreading is fine.
        if open_bins_count < 4 {
            score -= 8.0;
        }
        // If the current item is large and would leave bad residue elsewhere,
        // a fresh bin gives a clean slate.
        if fit_ratio > 0.7 {
            score -= 6.0;
        }
    }

    // Mild preference for balanced residual usage across bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 * (10.0 - pr) / 10.0; // tiny gap -> strong penalty
    } else if pr == 0.0 {
        score -= 25.0; // perfect fit: bin closed, ideal
    }

    // Reward good relative fit (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit here, slight penalty for leaving a stranded gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins first).
    score += (pr - mean_residual) * 0.5;

    // New-bin candidate handling: keep it as a neutral fallback, only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
        // If this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Big items prefer fresh bins when residuals are all small.
        if item_size as f64 > mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty: sliver unlikely to be used
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0; // perfect chain: next item seals this bin
        } else if post_residual > next_item_size {
            // next item fits with some slack; reward proportional closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item does NOT fit in post_residual: penalize if next item
            // would have fit in the current residual (we broke a possible chain)
            if next_item_size <= bin_residual {
                score += 5.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // filling them tightly is good, leaving them with large post_residual is bad.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // the item is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // A fresh bin is attractive for large items (they fit almost anywhere,
        // better to dedicate a fresh bin and keep small residuals for small items).
        score -= 8.0 * tightness;
        // But discourage opening new bins when many bins already fit the item.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // Early stream: opening bins is cheap and helps spread capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness).powi(6);

    // Penalize dead space: small post_residuals that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: prefer bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0 * (next_item_size - post_residual.min(next_item_size)) as f64 / 100.0;
        }
    } else {
        // Last item: waste nothing, fill any bin fully.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual as f64 - item_size as f64) / 100.0;
        // Prefer opening a new bin when open bins are fragmented and item is large.
        score += 40.0
            - 25.0 * (mean_residual / 100.0)
            + 20.0 * progress
            - 15.0 * (1.0 - poor_fit).powi(2);
    }

    // Global state: with many open bins, discourage spreading; consolidate.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / 100.0);

    // Mild time-horizon shaping: early stream -> prefer balanced residual use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (mean_residual - post_residual as f64).abs() / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
