    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual); later, tolerate slack.
    let progress_weight = 0.35 + 0.65 * progress;
    score -= progress_weight * (norm_pr * norm_pr) * cap * 0.5;

    // Penalize awkward dead space: post_residual that is small but nonzero
    // (unusable for typical items). Smooth via sin of normalized residual.
    let deadness = (std::f64::consts::PI * norm_pr).sin();
    score -= 6.0 * deadness * (1.0 - progress);

    // Reward tight fits relative to item size (couple item and residual).
    score -= 10.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = norm_pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * gap * (gap - 1.0).abs();
        } else {
            score += 5.0 * gap.abs() * gap.abs();
        }
    }

    // Mean residual coupling: prefer bins deviating from mean toward fullness.
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - norm_item);

    // New-bin candidate penalty scaled by progress and number of open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (mod 10 buckets).
    let class = post_residual % 10;
    // Residues that are "dead space" for typical small items (1..10 unusable).
    if post_residual < 10 {
        score += 40.0; // complete dead space penalty
    } else {
        // Reward residuals that are harmonic multiples of common item sizes.
        let harmonic = match post_residual {
            r if r % 50 == 0 => -30.0,
            r if r % 25 == 0 => -20.0,
            r if r % 20 == 0 => -15.0,
            r if r % 10 == 0 => -10.0,
            r if r % 5 == 0 => -5.0,
            _ => 0.0,
        };
        score += harmonic;
        // Odd classes (1,3,7,9) are harder to fill: mild penalty.
        if class == 1 || class == 3 || class == 7 || class == 9 {
            score += 3.0;
        }
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // next item cannot fit here; penalize proportionally to wasted space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins: reward small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: only attractive when current bin fit is very poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score; subtract if many bins open already (spread load).
        score = 60.0 - (open_bins_count as f64 * 2.0);
        if post_residual == bin_capacity {
            // Prefer opening a new bin for huge items that leave bad residue elsewhere.
            if item_size >= 70 {
                score -= 15.0;
            }
        }
    }

    // Progress-based mild exploration: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (<= 1)
    // are pure waste; penalize gaps in the "unusable" band hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Moderately awkward gaps (10..25) that few items can fill.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow a new bin more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * (2.0 + 3.0 * (1.0 - progress));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity && post_residual < next_item_size {
        // Next item won't fit here afterward: slight penalty unless gap is tiny.
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // New-bin candidate logic: only attractive when it enables a good future fit
    // or no existing bin fits well. Empty bin gets a baseline cost that scales
    // with open bins count so we prefer reusing bins generally.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size >= item_size {
            score -= 10.0; // new bin useful for pairing large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is ideal: next item fills bin completely
        if post_residual == next_item_size {
            score -= 800.0;
        } else {
            // Penalize proportional to distance from a perfect 2-step match
            score += gap * 2.0;
            // If next item cannot fit in the residual, this creates dead space risk
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }
        // Bonus if post_residual can still hold the next item (keeps bin useful)
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 50.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual: prefer bins tighter than average (good fits)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate penalty: only open a new bin when no decent fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 60.0;
        // Large items are hard to place later; opening a fresh bin for them is fine
        if item_size >= 60 {
            score -= 40.0;
        }
        // If existing bins fit poorly (high mean residual vs item), new bin more attractive
        if next_item_size > 0 && item_size as f64 > mean_residual + 10.0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for leaving very small unusable fragments (dead space 1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already helps; amplify it).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (wasted capacity).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 14.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // mild reward: chain placement possible
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; penalize leaving a residual smaller than next item
            score += 4.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins whose residual is already low (consolidate filling).
    let rel_res = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * rel_res * rel_res;

    // Prefer bins below mean residual (fill emptier-relative bins less, keep
    // large residuals available) — i.e. reward bins tighter than average.
    let mean_rel = mean_residual / bin_capacity as f64;
    if rel_res < mean_rel {
        score -= 5.0 * (mean_rel - rel_res);
    } else {
        score += 3.0 * (rel_res - mean_rel);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize new-bin less by adding to open-bin scores late? Actually:
    // penalize new bins early less by reducing base). Use progression factor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: residual == capacity. Prefer it early, discourage late.
    if bin_residual == bin_capacity {
        let new_bin_bias = 8.0 - 20.0 * progress;
        score += new_bin_bias;
        // If many open bins already, discourage yet another new bin.
        score += 0.8 * open_bins_count as f64;
    }

    // Many open bins: encourage closing out existing bins (fill them) rather
    // than spreading items across many.
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64 * tightness;
    }

    // Small-item handling: tiny items should go into small residuals.
    if item_size <= 15 {
        score -= 6.0 * (1.0 - rel_res);
    }

    // Large items: prefer bins with large residual so they don't strand space.
    if item_size >= 60 {
        score += 8.0 * (1.0 - rel_res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;

    // Smooth non-linear coupling: penalize large residuals early, tolerate them late
    let coupling = pr * pr * (1.0 + 2.0 * progress) - pr * progress;
    score += 20.0 * coupling;

    // Reward tight fits with smooth exponential term
    score -= 15.0 * (-pr * 4.0).exp() * (0.5 + 0.5 * progress);

    // Penalize opening a new bin when existing bins fit, scaled by progress
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as i32 as f64;
    score += is_new_bin * (30.0 + 20.0 * progress) * (fitting_bins_count.max(1) as f64).ln();

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = (pr * cap - ns).abs();
        score -= 8.0 * (-compat / 25.0).exp() * (1.0 - progress);
    }

    // Mild diversity pressure via mean residual
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (divisible into common item sizes) are rewarded.
    let cap = bin_capacity as f64;

    // Fractional fill of the bin after placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill with a non-linear boost.
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class penalty: post_residuals that are small but not zero are dead space.
    if post_residual > 0 {
        // Small awkward residuals (< 10) are nearly unusable -> penalize.
        if post_residual < 10 {
            score += 25.0;
        }
        // Residuals that exactly match harmonic classes (multiples of 10/20/25/50)
        // are likely reusable by future items -> reward.
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
        // Integer-division threshold: residual >= half capacity is flexible.
        if post_residual >= bin_capacity / 2 { score -= 12.0; }
        else if post_residual >= bin_capacity / 4 { score -= 4.0; }
        else { score += 6.0; }
    } else {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // Penalize if the leftover after next item is a tiny dead fragment.
            if slack > 0 && slack < 10.0 { score += 18.0; }
        } else {
            // Next item cannot use this residual; if residual is small it's dead space.
            if post_residual < next_item_size && post_residual < 30 {
                score += 10.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If item is large (> half capacity), a fresh bin is reasonable.
        if item_size * 2 >= bin_capacity {
            score -= 35.0;
        }
        // If many bins are open with high mean residual, prefer reusing them.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable by items (min size 1..100, but treat <10 as risky)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead) / 10.0; // heavy penalty for tiny unusable gaps
    }

    // Reward very tight fits (best-fit core)
    if post_residual == 0 {
        score -= 25.0;
    } else {
        score -= 8.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open
    score += (open_bins_count as f64) * 0.15;

    // Lookahead: if next item fits this bin's post-residual, reward using this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit anywhere after this placement, penalize slightly
    if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins with residual far below mean (bigger gaps first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin is decent
    if bin_residual == bin_capacity {
        let decent_exists = mean_residual >= item_size as f64;
        score += if decent_exists { 20.0 } else { 5.0 };
    }

    // Early stream: be slightly more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild nonlinearity
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let gap = pr - next;
            // Perfect chain: post_residual == next_item_size is ideal
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Penalize leftover gap after chaining (dead space)
            score += 0.25 * gap;
        } else {
            // Next item won't fit here; penalize small unusable residuals
            score += 6.0 * (1.0 - pr / next);
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are less attractive
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only good if item is large
    // relative to capacity or no open bin offers decent fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; discount when item is big
        score += 30.0 - 22.0 * fit_ratio;
        if fitting_bins_count <= 1 {
            // No (or one) alternatives: opening may be fine
            score -= 10.0;
        }
        // Early in stream, new bins are cheap; late, avoid sprawl
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for filling more-full bins when many bins are open
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();

    // Penalize leaving residuals that are likely dead zones (very small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity (non-linear).
    let tightness = (post_residual as f64) / cap;
    score += 12.0 * tightness * tightness;

    // Lookahead synergy: if the next item exactly fits the post-residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // next item can fit here: reward proportional to how snugly it will fit
            score -= 6.0 * (1.0 - ((pr - nxt) / cap));
            if (pr - nxt) < 5.0 {
                score -= 8.0; // near-perfect two-item chain
            }
        } else {
            // next item won't fit here; slight penalty if post_residual is a stranded sliver
            if pr > 0.0 && pr < 10.0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state: penalize spreading across many open bins when mean residual is high.
    let mean_fit = (mean_residual - (item_size as f64)) / cap;
    if mean_fit > 0.0 {
        score += 3.0 * (1.0 - mean_fit) * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in stream, be pickier about waste; late, accept decent fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate handling: neutral-ish base so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (item_size as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin anyway
        }
        if next_item_size > 0 && (next_item_size as f64) <= (post_residual as f64) {
            score -= 4.0; // fresh bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = (pr / cap).clamp(0.0, 1.0);

    // Base: reward tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * fit_norm * fit_norm);

    // Stream-progress coupling: later in the stream, tolerate less waste
    let waste_penalty = pr * pr / cap;
    score += waste_penalty * (0.5 + progress);

    // Smooth interaction between post_residual and mean residual of open bins
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    score += 8.0 * fit_norm * mean_norm * (1.0 - fit_norm) * (1.0 - progress);

    // Penalize leaving dead space that no typical item can use
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.5;
    }

    // Lookahead: favor bins whose post residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: mild penalty so it is chosen only when fits are bad
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        score += cap * (0.8 + 0.4 * progress) + 0.1 * mean_residual;
    }

    // Mild dispersion penalty with many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let ni = next_item_size as u32;

    // Exact fit: perfect closure of the bin.
    if pr == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual below the smallest possible item class is unusable.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Harmonic lookahead: reward residuals that pair with the next item.
    if ni > 0 {
        if ni == pr {
            score -= 45.0; // next item exactly closes this bin
        } else if pr >= ni && (pr - ni) < 10 {
            score -= 20.0; // next item nearly closes this bin
        } else if pr > 0 && pr < ni {
            score += 15.0; // next item cannot use this residual
        }
    }

    // Decile class of residual: mildly prefer tighter bins beyond raw residual.
    score += (pr / 10) as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Brand-new bin candidate: fixed baseline, adjusted by lookahead and scarcity.
    if bin_residual == bin_capacity {
        score = 70.0;
        if ni > 0 && ni <= bin_capacity {
            score -= (bin_capacity - ni) as f64 * 0.1;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: opening is necessary
        } else if fitting_bins_count == 1 {
            score += 25.0; // only one fit exists, but it competes with last-chance reward
        }
    }

    // Congestion coupling: many open bins with slack -> favor consolidating.
    if open_bins_count > 0 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.5 + 10.0;
        score += pressure;
        // New bin is acceptable if the item is huge and nothing fits well elsewhere.
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it's not 0 (perfect) vs tiny dead space.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // penalize small-but-nonzero dead space quadratically
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * next_item_size as f64;
        // extra reward if next item fills the bin almost perfectly after placement
        let post2 = post_residual - next_item_size;
        if post2 == 0 {
            score -= 300.0;
        } else {
            score -= 20.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot follow here: mild penalty proportional to how close it was
        score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residual below mean (consolidate waste into few bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0
            - 0.4 * item_size as f64
            + 50.0 * progress
            + 5.0 * open_bins_count as f64;
        // opening a new bin is attractive only if item is huge (leaves small residual)
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual (wasted space), especially super-linearly.
    let t = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * t * t;

    // Reward bins that leave residuals unusable for the next item (dead space penalty).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Exact or near fit for lookahead item: strong reward.
            let gap = post_residual - next_item_size;
            score -= (1.0 - gap as f64 / bin_capacity as f64) * 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0 * (open_bins_count as f64).ln().max(1.0);

    // Deviation from mean residual: prefer bins whose residual is below mean (fuller than average).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate logic: empty bin gets a penalty so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large and current item is small, opening a fresh bin preserves space.
        if next_item_size > item_size * 2 {
            score -= 6.0;
        }
    }

    // Late-stream conservatism: as stream ends, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Small residual bonus: bins that will be nearly closed after placement are valuable.
    if post_residual <= 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits via a smooth non-linear penalty on residual
    let mut score = norm_post * norm_post * cap;

    // Polynomial coupling of residual with stream progress: tight packing
    // becomes more valuable as the stream advances (smooth cubic ramp).
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (progress * (1.0 - progress) * 4.0 + 0.25);

    // Penalize large dead space more than linearly (quartic term), scaled by progress
    score += 6.0 * norm_post * norm_post * norm_post * norm_post * (1.0 + progress);

    // Reward using the bin when it is the last fitting bin (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = (next_item_size as f64) / post.max(1.0);
        score -= 5.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize leaving awkward gaps
        score += 3.0 * (1.0 - ((post - next_item_size as f64).abs() / cap));
    }

    // Mean residual interaction: prefer bins below mean residual (tighter than average)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * dev.signum();

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by residue mod capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Penalize residuals that fall in "awkward" small residue classes
    // (dead space that few item sizes can use).
    if class < 10 {
        score += (10 - class) as f64 * 1.5;
    } else if class > quarter - 10 {
        score -= (class - (quarter - 10)) as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual: prefer residuals that
    // remain "large enough" to host a typical next item.
    let usable = post_residual / 10; // decile class
    score -= usable as f64 * 2.0;

    // Lookahead coupling: reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + (next_item_size as f64) * 0.3;
            // Extra reward if next item leaves a clean harmonic residual.
            let npr = post_residual - next_item_size;
            if npr % 25 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize slightly unless this bin
            // is nearly full (good terminal placement).
            if post_residual <= 15 {
                score -= 10.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless they fit poorly.
        score += 30.0;
        // If many open bins fit, discourage opening a new one further.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If no other bin fits, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer closing out open bins rather than opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for bin divergence from mean residual: keep bins balanced
    // in harmonic classes.
    let div = (bin_residual as f64 - mean_residual).abs();
    score += div * 0.15;

    // Modulo coupling on item_size vs post_residual (harmonic pairing).
    if post_residual > 0 && (item_size % (post_residual.max(1))) == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..=100, min 1)
    // are pure waste; penalize proportionally to how "almost usable" they are.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize hard, scaled by sliver size.
        score += 30.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual < 20 {
        // Marginal gap: only usable by small items; mild penalty.
        score += 8.0;
    }

    // Reward leaving gaps that exactly match the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Would leave an unusable sliver for the next item.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (subtract to favor placement).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bins
    // only when current bins are tight (mean_residual low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln() * 2.0;
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += bin_pressure * (mean_gap / bin_capacity as f64) * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default: slightly discourage opening a new bin...
        score += 6.0;
        // ...unless every open bin would leave dead space with this item.
        if post_residual < 10 && bin_capacity == 100 {
            // item_size == 100 case: perfect fit in fresh bin.
            score -= 45.0;
        }
        if item_size >= 90 && bin_capacity == 100 {
            score -= 20.0;
        }
        // If the item fits poorly in all open bins (many near-full bins),
        // a fresh bin keeps residuals clean for future items.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual: good lookahead chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space, more so if very small.
        let dead = post_residual as f64;
        score += 0.5 * dead;
        if dead < 10.0 {
            score += 25.0; // tiny unusable fragment
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that keep mean residual balanced.
    let cap = bin_capacity as f64;
    let diff = (post_residual as f64 - mean_residual) / cap;
    score += 10.0 * diff;

    // Prefer fuller bins (small post_residual relative to capacity).
    score += 5.0 * (post_residual as f64 / cap);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer filling bins when many are open (avoid bin proliferation)
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * open_pressure;

    // New-bin candidate handling: empty bin should only win for large items
    // or when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if big_item || poor_options > 0.5 {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 45.0; // discourage opening new bins unnecessarily
        }
    }

    // Slight preference for bins below mean residual (balance residuals)
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Time-dependent tightness weight: later in stream, prioritize tight fits more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress.
    let mut score = pr / cap;

    // Non-linear polynomial coupling: as stream progresses, weight residual more heavily.
    let g = 1.0 + 2.0 * progress * progress;
    score += g * (pr / cap).powi(2);

    // Reward tight fits (small post_residual relative to item) via smooth interaction.
    let tightness = item / (bin_residual as f64).max(1.0);
    score -= 0.8 * tightness * (1.0 - progress);

    // Dead-space penalty: residuals too small to fit the smallest plausible item.
    let dead = ((1.0 - pr / cap).max(0.0) - (cap - 1.0) / cap).max(0.0);
    score += 1.5 * dead * dead * (0.5 + progress);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.3 * (1.0 - pr / cap);
    }

    // Last-chance bonus: only one bin fits this item.
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Mild preference for reusing bins over opening new ones, stronger early.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - progress);
    } else {
        score -= 0.2 * (1.0 - progress);
    }

    // Spread-aware term: prefer bins deviating from mean residual in a controlled way.
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter;
    match post_class {
        0 => score -= 12.0,                       // near-perfect fit: strongly reward
        1 => score += 3.0,                        // awkward quarter: penalize
        2 => score += 0.0,
        _ => score -= 4.0,                        // large residual: bin stays reusable
    }

    // Modulo-10 dead-space class: residuals divisible by 10 are "harmonic"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 15.0;                            // tiny dead space is wasted capacity
    }

    // Integer-division pairing: can next item (lookahead) land in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or with small slack
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0;                    // perfect chain
            } else if slack / 5 == 0 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; if this bin is the only fitting one,
            // consuming it now is fine, otherwise keep it roomy
            if fitting_bins_count <= 1 {
                score += 5.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate: only attractive early in stream or when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        if progress < 0.25 && open_bins_count > 0 {
            score -= 5.0;                          // early: fresh bins cheap
        } else if crowding < 0.15 {
            score += 25.0;                         // don't waste nearly-full-bin era
        } else {
            score += 8.0;
        }
    }

    // Mild preference for filling the emptiest bins when many are open
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item are pure waste. Penalize them super-linearly.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual is "consumed well": fraction of bin used
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover gap -> extra dead-space penalty
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins (penalize new-bin candidates implicitly via
    // this term applied to all, but empty bins get extra push-back).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Empty new-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight pull toward bins near the mean residual (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 500.0; // chained perfect fit
        } else {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: post_residual too small for the next item.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * waste_ratio;
        // Extra penalty if this bin was the only fitting option (forced placement).
        if fitting_bins_count == 1 {
            score -= 30.0; // still better than opening a bin for a poor fit elsewhere
        }
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Open a new bin when item is big and existing bins are mostly full/fragmented.
        score += 120.0 - 90.0 * large_item - 60.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
    }

    // Mild stream-progress adaptation: later in the stream, be more conservative
    // about leaving small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin unless fit is bad.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: only attractive when this item would leave a very
    // poor residual in every existing bin, or few fitting bins exist.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 15.0 * (1.0 - fit_ratio);
        if poor_fit || fitting_bins_count <= 1 {
            score -= 8.0 + 0.1 * open_bins_count as f64;
        } else {
            score += 20.0;
        }
    }

    // Time horizon: early in the stream, keep bins flexible; late, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.3;
    score -= progress * 5.0 * fit_ratio;

    // Prefer bins with residual above the mean (keeps a spread of sizes).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: residual waste weighted by stream progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fits rewarded more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= 20.0 * tight * tight * tight * (0.5 + 0.5 * progress);

    // Penalize leaving residual close to next item size mismatch (wasted potential)
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let gap = (pr - nd).abs();
        score += 0.15 * gap * gap / cap;
    }

    // Last-chance bin bonus: strong reward when it's the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate: mild penalty, growing with progress so late stream reuses bins
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small item classes
    // (e.g. 10/20/25/50) are "reusable" residues; penalize awkward residues.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        let reusable = (pr % 10 == 0) as i32 as f64
            + (pr % 20 == 0) as i32 as f64
            + (pr % 25 == 0) as i32 as f64
            + (pr % 50 == 0) as i32 as f64;
        score -= 4.0 * reusable;
        // awkward dead-space classes: tiny unusable slivers
        if pr < 10 {
            score += 25.0;
        } else if pr <= 15 {
            score += 8.0;
        }
        // integer division threshold: pr / item_size class
        let div_class = pr / item_size.max(1);
        score -= 2.0 * div_class as f64;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill * fill;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 35.0;
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        // next item won't fit here: penalize leaving a stranded gap
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bins generally, less so when open bins are nearly full
        score += 55.0 - 45.0 * pressure - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins below mean residual (balance / spread)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize wasting a large residual on a small item (bad fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 {
        score += (0.5 - fill_ratio) * 80.0;
    }

    // Open-bin pressure: encourage closing out bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use the gap -> dead space risk
        score += 10.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when bins are crowded
        // or the mean residual across open bins is small (poor fits available).
        let crowd = (open_bins_count as f64 / 8.0).min(1.0);
        let poor_fits = (1.0 - mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 - 45.0 * crowd - 30.0 * poor_fits - 20.0 * progress;
        // If the current bin would be a perfect fit for the item, never open new.
        if item_size == bin_capacity {
            score = bin_capacity as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly (low post_residual is good).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: post_residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Dead space relative to lookahead item penalized.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + (bin_capacity - post_residual) as f64 * 0.2;
    }

    // Penalize the brand-new empty bin candidate, but less so when the
    // current item is large (big items are better placed in fresh bins)
    // and late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item_bonus = if item_size >= 50 { 30.0 } else { 0.0 };
        score += 80.0 - big_item_bonus - progress * 20.0;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mild preference for keeping many small bins consolidated.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing can use (post_residual < 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 30 {
        // Mid-range residual is useful; reward slightly.
        score -= 8.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and this bin is the only fitting one, discourage wasting it.
    if next_item_size > item_size && fitting_bins_count == 1 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: late in the stream, consolidate; early, allow exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins with high mean residual: favor filling existing bins over opening new ones.
    if bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: penalize when existing mean residual can absorb the item.
        if mean_residual > item_size as f64 {
            score += 18.0;
        }
        // Early stream: opening bins is cheaper.
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer low post residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tighter fits matter more
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Penalize leaving residuals that no typical item can use well (dead space)
    score += 12.0 * x * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 10.0 * (1.0 - nxt / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: make it slightly unattractive unless post residual is large
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual divisible by small powers of 2 is more "usable"
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr % 10 == 0 { 1 } else if pr % 5 == 0 { 2 } else if pr % 2 == 0 { 3 } else { 4 };
    score -= (4 - class as i32) as f64 * 12.0;

    // Dead-space penalty: tiny unusable remainders
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 60.0;
        } else {
            score += 25.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a great fit
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Waste fraction coupling: penalize leaving large fractions of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 50.0;

    // Prefer tighter bins among fitting bins
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Slight preference to fill older bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size = 1, but practically small gaps) are waste.
    // Penalize tiny nonzero post_residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Nonlinear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make the empty bin moderately attractive only when
    // it avoids creating a bad fit elsewhere; base cost keeps existing bins
    // preferred unless their score is worse.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // If next item is large and this item leaves a tiny gap, opening a
        // fresh bin is safer.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
