    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tightness / bin_capacity as f64);
    }

    // Slight preference for bins tighter than the mean residual (better fits).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small post_residual is good).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual,
    // this placement sets up a perfect chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating dead space relative to next item.
        score += 0.4 * (next_item_size - post_residual) as f64;
    }

    // Penalize residual far below mean residual (creating unusable small gap
    // relative to what other bins offer), reward keeping residuals balanced.
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    // among open bins (large residual waste would result from forcing it in).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if waste < 10.0 {
            score -= 20.0; // item nearly fills a fresh bin
        } else if fitting_bins_count <= 1 {
            score -= 10.0; // few alternatives: fresh bin is reasonable
        } else {
            score += 8.0; // prefer existing bins when they can fit
        }
    }

    // Early in the stream, allow opening bins more freely to build a good pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space, especially small post-residuals that are unusable
    // for typical items (items 1..100, so post_residual < some threshold is dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain_quality = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * chain_quality;
        } else {
            // Post residual can't host next item; penalize proportionally to waste.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when the item is large
    // relative to capacity or when open bins have fragmented residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual.
        // Discount when item is big (large items waste less in fresh bins).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * size_frac;
        // If existing bins are highly fragmented, fresh bin looks better.
        let frag = mean_residual / open_bins_count.max(1) as f64;
        if frag < item_size as f64 && bin_residual >= item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps residuals uniform, preserving flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly convex so mid-range residuals are tolerated
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Smooth non-linear coupling with stream progress:
    // early on prefer tight fits less aggressively; late, squeeze harder
    let progress_coupling = (0.5 * progress * progress + 0.5 * progress) * (pr_norm * (1.0 - pr_norm) * 4.0);
    score += 12.0 * progress_coupling;

    // Dead-space penalty: small post-residuals that likely become unusable
    let dead = (1.0 - pr_norm).exp() * (1.0 - pr_norm);
    score += 8.0 * dead * (1.0 + progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize bins far from mean residual (prefer balanced fills) with smooth kernel
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm) * 2.0;

    // New-bin candidate: make empty bins less attractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items in 1..=100, capacity 100.
    // Class post_residual into buckets of 10 — small classes are "dead space".
    let post_class = post_residual / 10;
    score += match post_class {
        0 => -30.0,              // near-perfect fill
        1 => -12.0,              // excellent
        2 => -4.0,
        3 => 2.0,
        4 => 6.0,
        _ => 10.0,               // large leftover: poor packing
    };

    // Modulo-3 harmonic coupling: leftover compatible with next item's class.
    if next_item_size > 0 {
        let nxt = next_item_size.min(bin_capacity);
        if nxt <= post_residual {
            // next item fits exactly in this bin afterwards: strong reward
            let exact = (post_residual as i64 - nxt as i64).abs();
            score -= if exact == 0 { 25.0 } else if exact <= 5 { 12.0 } else { 4.0 };
        } else {
            // next item won't fit here; penalize leaving space it almost fits
            let gap = nxt - post_residual;
            score += (gap as f64).min(15.0) * 0.8;
        }
        // harmonic phase: (post_residual + next) modulo capacity fraction
        let phase = (post_residual + nxt as u32) % 25;
        score -= (phase as f64) * 0.3;
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: must open
        } else if fitting_bins_count == 1 {
            score -= 20.0;  // weak competition
        }
    }

    // Prefer filling bins whose residual deviates below mean (compact bins first)
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    // Slight pressure to reduce open bin count as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 3.0;
    }

    // Integer-division threshold: reward placing large items into tight bins
    let tight = bin_residual / item_size.max(1);
    if tight == 1 {
        score -= 8.0; // item consumes most of the bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the smallest plausible item (<=10)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Non-linear waste curve: penalize mid-range gaps that are hard to fill,
    // unless they can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // reserve space for next item: good coupling
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.9;
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: when many bins are open, discourage new bins / spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.35 + 0.65 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins attractive only when few bins are open
    // or the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.6;
        if poor_fit && open_bins_count > 0 {
            score -= 10.0; // allow opening a new bin for a big item
        } else {
            score += 20.0; // default: prefer existing bins
        }
    }

    // Mean residual coupling: if average residual is large, prefer bins below the mean
    // (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early stream -> be picky about dead space; late -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain: bin becomes perfectly reusable
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of that fit
            let lookahead_tightness = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 40.0 * lookahead_tightness;
        } else {
            // next item will NOT fit: residual becomes dead space
            score += 25.0;
        }
    }

    // Penalize large residual relative to mean (creating outlier dead space).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward using bins that are already fairly full (small residual before placement).
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin for a poor fit elsewhere.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Late in stream: prefer filling existing bins over opening new ones.
    score += progress * 20.0;

    // Penalize opening a new empty bin unless the item is large relative to capacity
    // (better to start fresh bins with big items).
    if bin_residual == bin_capacity {
        score += 10.0 - (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Slight penalty per extra open bin to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on leftover space (dead space aversion).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize leaving residue that wastes the next item's opportunity.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 {
        score -= 8.0 * (mean_residual / bin_capacity as f64) * (1.0 + progress);
    }

    // Late stream: discourage fragmentation, prefer tighter packing as we near the end.
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: baseline preference only when the fit elsewhere is hopeless.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive if the item is large relative to typical residual,
        // or if open bins are nearly full on average.
        let desperation = (mean_residual / bin_capacity as f64).max(0.0);
        score -= 20.0 * desperation * (item_size as f64 / bin_capacity as f64);
        score += 15.0 * (1.0 - desperation);
        // Never open a new bin for a tiny item early on.
        if item_size < 40 && open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 40.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are already fragmented.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small slivers are fine to create if it consolidates elsewhere
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, prefer bins that leave small post residuals more strongly.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * norm_post * norm_post * cap * 0.5;

    // Dead-space penalty: very small post residuals relative to capacity are fine,
    // but mid-range waste is penalized via cubic coupling.
    let waste = norm_post * (1.0 - norm_post);
    score -= 8.0 * waste * (1.0 - progress);

    // Perfect-fit reward (smooth, no hard cutoff).
    if post == 0.0 {
        score -= 30.0;
    }

    // Penalize leaving a residual that exactly matches the next item (good synergy),
    // smoothly scaled by lookahead validity.
    let lookahead = next_item_size as f64;
    if lookahead > 0.0 {
        let diff = (post - lookahead).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
