    }

    // Prefer filling bins that are already well-used (residual close to item size).
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 6.0 * fill_ratio;

    // Mild pressure against spreading across many open bins late in the stream.
    score += (open_bins_count as f64) * 0.05 * progress;

    // Avoid opening new bins when mean residual across bins is large.
    score += 3.0 * (mean_residual / cap) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
