    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += (post_residual as f64) * 0.6; // dead space for lookahead item
        } else {
            score -= (next_item_size as f64) * 0.25; // next item nests perfectly
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * t;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the item is large relative to residual capacity available elsewhere
    // and when many bins are already open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 15.0;
        if item_size >= 50 { new_bin_penalty -= 5.0; }
        if fitting_bins_count == 0 { new_bin_penalty = 2.0; }
        if mean_residual < (item_size as f64) * 0.5 && open_bins_count > 0 {
            new_bin_penalty -= 6.0; // existing bins are cramped
        }
        score += new_bin_penalty;
    }

    // Mild reward for using bins whose residual deviates from the mean
    // (consolidate fragmented space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, be extra greedy about residual to finish compactly.
    score += (1.0 - t) * (post_residual as f64) * 0.1;

    // Penalize extremely small unusable leftovers harder.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let cap_f = bin_capacity as f64;
    let item_frac = item_size as f64 / cap_f;
    let post_frac = post_residual as f64 / cap_f;

    // Penalize post-residuals that fall into "dead" classes:
    // residuals too small to host typical items (mod-10 style classes)
    let post_class = post_residual % 10;
    if post_residual > 0 {
        if post_class != 0 && post_residual < 10 {
            // tiny unusable sliver
            score += 25.0 - (post_residual as f64);
        } else if post_residual < item_size.min(20) {
            score += 6.0; // residual smaller than likely next item
        }
    }

    // Reward near-perfect fits (exact fill or very small remainder)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Harmonic class matching: reward bins whose residual class complements item class
    let item_mod = item_size % 20;
    let res_mod = bin_residual % 20;
    if (item_mod + res_mod) % 20 == 0 || (item_mod + res_mod) % 20 == 19 {
        score -= 8.0;
    }

    // Integer division thresholds on next item size
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead item fits after placement: strong reward
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(15.0) * 0.3;
        } else {
            // lookahead won't fit: penalize more when the leftover is large-ish
            score += ((post_residual as f64) * 0.15).min(8.0);
        }
        // big lookahead: prefer conserving tight bins
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin before opening a new bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap_f);
        // base cost of opening a bin, discounted when many bins with poor residuals
        score += 55.0 - (crowding * 4.0).min(30.0);
        // if mean residual across bins is small (all bins tight), new bin is fine
        score -= (mean_residual / cap_f) * 10.0;
        // big items prefer fresh bins
        if item_frac > 0.6 {
            score -= 12.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Late in stream: prefer consolidating into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32; // interface allows sizes from 1
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(80)) {
        // gap too small for anything useful (especially the lookahead item)
        score += 40.0 + (next_item_size as f64 - post_residual as f64).max(0.0);
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // classic tiny dead space zone
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0; // next item won't fit here; slight penalty unless bin is nearly full
    }

    // Open-bin pressure: prefer spreading when many bins are open (avoid bin proliferation later),
    // but when few bins are open, filling them fully is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is poor
    // (large post_residual relative to capacity) or bin is empty and item is small.
    if bin_residual == bin_capacity {
        // empty bin baseline: neutral-ish, slight penalty so good fits in open bins win
        score += 12.0;
        if item_size >= 70 {
            score -= 10.0; // big items are fine in a fresh bin
        }
    } else if post_residual as f64 > 0.5 * bin_capacity as f64 {
        // poor fit leaving huge waste: make new bin competitive
        score += 15.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalize proportionally to how wasted the leftover space is,
        // but less harsh if this is the last chance bin.
        let waste = (next_item_size - post_residual) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let last_chance_bonus = if fitting_bins_count == 1 { 25.0 } else { 0.0 };
        score += waste * (1.2 + 0.8 * progress) - last_chance_bonus;
    }

    // Next item fits comfortably with room to spare (chainable fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Favor bins whose residual is already below mean (tight bins get filled).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last chance: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mildly discourage opening new bins when many are already open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it attractive only when the item is large relative to capacity
    // or there are no open bins; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            score += (item_size as f64) * 0.3 + 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next_item_size is wasted. Penalize unusable slivers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can still fit here: reward chainability.
            score -= 6.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (-slack / 25.0).exp(); // prefer just-fitting residuals
        } else {
            // Dead space: penalize proportionally to wasted capacity.
            score += 0.8 * post_residual as f64;
        }
    } else {
        // Last item: any residual is pure waste; minimize it.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate logic: empty bin should only win when the item fits
    // poorly everywhere else. Make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, avoid spawning bins that will end mostly empty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global pressure: when many bins are open and mean residual is low,
    // encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 0.05 * pressure;

    // Prefer bins whose residual is close to the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * tightness;

    // Slight reward for filling large items into already-open bins.
    score -= 0.1 * item_size as f64 * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Tight fits rewarded, modulated by progress
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize dead space relative to mean residual
    if pr > 0.0 && pr < mean_residual {
        score += 5.0 * (mean_residual - pr) / cap;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Slight preference for keeping fewer open bins early
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals divisible by 10 (capacity fraction classes) pair well with
    // common item sizes; odd/tiny residuals are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division class of post_residual (harmonic buckets of 10)
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,           // near-full bin: excellent closure
        1 => score -= 15.0,           // 10..19 left: still usable
        2 => score -= 5.0,            // 20..29: mild
        3 => score += 8.0,            // 30..39: mediocre leftover
        4 => score += 15.0,           // 40..49: half-bin waste
        _ => score += 22.0,           // 50+: large leftover penalized
    }

    // Exact modulo-10 harmony: leftover that matches common size classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // fractional fill of the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 12.0 * fill;
        } else {
            // next item won't use this leftover at all
            score += 6.0;
        }
    }

    // Last-chance bonus: only bin that fits avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is huge relative to a fresh bin
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 20.0 * (frac - 0.7);
        } else {
            score += 35.0 * (0.7 - frac);
        }
    }

    // Stream progression: later in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - pr) * 0.05;

    // Penalize spreading when many bins are open
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Gaps below the minimum item size (1..10) can never be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps 10..19 are only usable by small items; mild penalty scaled by tightness.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit reward: fill a bin exactly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open when
    // the stream is early; encourage consolidation as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 40.0 - (slack_after_next as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to how far off
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.3;
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when existing bins fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
        // but allow opening if no good fit exists (large gap)
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 10.0;
        }
    }

    // Small dead-space penalty for leaving tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> avoid spreading waste.
    let pressure = mean_residual / (bin_capacity as f64);
    if bin_residual as f64 > mean_residual {
        score += 3.0 * pressure; // prefer below-average-residual (fuller) bins
    } else {
        score -= 1.5 * pressure;
    }

    // Time horizon: early in the stream, be conservative; late, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let escape_bonus = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        let big_item_bonus = if item_size > bin_capacity / 2 { 6.0 } else { 0.0 };
        score += base_penalty - escape_bonus - big_item_bonus;
    }

    // Mild penalty for using many open bins when a fuller one exists.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr - 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses.
    score -= fit_ratio * fit_ratio * (10.0 + 30.0 * progress);

    // Penalize dead space that is too small for typical future items.
    if pr > 0.0 && pr < next_item_size as f64 {
        score += 15.0 + 10.0 * progress;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for keeping bin count low early, opening bins later.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish, penalized slightly unless residual would be wasted.
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * fit_ratio * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 buckets model dead-space utility.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0, // perfect alignment: residual is a "round" slot
        1 | 9 => 3.0,
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        4 | 6 => 0.5,
        _ => 0.0, // class 5: half-capacity slot, still reusable
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    if post_residual < 10 {
        score += 8.0; // unusable dead space (min item is 10 in classic regime)
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Reward leaving room exactly matching the lookahead item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            // proportional fit quality for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.6 + 20.0 * (1.0 - progress);
        // If no open bin fits, opening is cheap; if many fit, opening is expensive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 10.0 * fitting_bins_count as f64;
        }
        // Discourage new bins when mean residual across open bins is still large.
        score += 0.3 * mean_residual;
    }

    // Slight preference for tighter bins overall (low residual before placement).
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // tiny dead space: nearly worthless leftover
        } else if post_residual <= 20 {
            score += 40.0; // small gap, usable only for tiny items
        } else if post_residual <= 35 {
            score += 10.0; // moderate gap
        } else {
            score -= 15.0; // generous leftover: attractive target
        }
    } else {
        score -= 60.0; // perfect fill: strongly rewarded
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are already open; prefer new bin when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (bin_capacity as f64 / 20.0);
    score += 4.0 * bin_pressure * (1.0 - 0.5 * progress);

    // New-bin candidate: neutral baseline, penalize opening new bins unless
    // existing bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * bin_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and post-residual is a small useless gap, penalize.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Mean residual context: prefer bins below mean residual (tighter bins get filled first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how much of next item cannot fit here.
        score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Prefer tight fits: small post_residual relative to bin capacity.
    score += 8.0 * (post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize bins far below mean residual (wasteful large residual use),
    // reward bins near the mean (keeps a balanced residual pool).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open/use fresh bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless lookahead fits well.
        let lookahead_ok = next_item_size > 0 && next_item_size <= post_residual;
        score += 40.0 - if lookahead_ok { 30.0 } else { 0.0 } + 20.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty tied to number of open bins: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary fit quality: strongly reward tight fits.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * residual_frac * residual_frac;

    // Reward tightness relative to the item itself (small dead space ratio).
    if item_size > 0 {
        score += 6.0 * (post_residual as f64 / item_size as f64).min(2.0);
    }

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item would then fill this bin almost exactly.
        let two_step = post_residual - next_item_size;
        if two_step <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the known next item cannot use.
        score += 4.0 * (next_item_size as f64 / post_residual as f64).min(3.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Crowd penalty: with many open bins, discourage spreading; prefer compacting.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 3.0 * openness * residual_frac;

    // Global state coupling: if mean residual across bins is small (bins nearly
    // full), be more willing to open a new bin for awkward fits; i.e. penalize
    // cramming into already-fragmented bins less, but penalize this bin if it
    // deviates from the mean in a wasteful way.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, tolerate looser fits to avoid spawning bins that will
    // barely be used.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * t * residual_frac;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Base its attractiveness on the item size: opening a new bin is attractive
    // only for large items that would leave big dead space elsewhere, or when
    // many bins exist but none fit well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score += 10.0;
        // Large items justify a new bin more (less future fragmentation risk).
        score -= 0.12 * item_size as f64;
        // If other fitting bins exist but are poor options (high mean residual
        // mismatch), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            score += 5.0; // keep using the last-chance bin instead
        }
        // Late in the stream, a new bin is cheap since few items remain.
        score -= 8.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with smooth non-linear shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth progress coupling: late in stream, penalize residual more strongly
    let progress_coupling = 1.0 + 0.6 * progress * progress;
    score *= progress_coupling;

    // Reward filling bins that also accommodate the lookahead item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compatibility = norm_pr - nx;
        if compatibility < 0.0 {
            score += 0.5 * (-compatibility) * (1.0 - progress);
        } else {
            score -= 0.3 * compatibility * (1.0 - compatibility);
        }
    }

    // Last-chance bonus: avoid wasting a nearly-unique fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * fit_ratio;
    }

    // Slight preference to keep mean residual spread balanced
    score += 0.1 * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: mild penalty so it's chosen only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 0.4 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item granularities are more reusable than odd dead space.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 2 == 0 {
            -1.0
        } else {
            2.0 // odd residual: likely dead space
        };
        score += class_bonus;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 25.0;
    }

    // Penalize large unusable leftovers that no typical item can fill.
    if pr > 0 && pr < 10 {
        score += 8.0; // tiny sliver, nearly dead space
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            score += 3.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): only attractive when current bins fit
    // poorly (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // base penalty so we don't proliferate bins carelessly
        score = bin_capacity as f64 * 0.9;
        let pressure = mean_residual / bin_capacity as f64;
        if pressure > 0.7 || open_bins_count == 0 {
            score -= 15.0; // open bins nearly full or none: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are almost unusable
    // (item sizes >= 10), so they are pure waste. Penalize them hard.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual as i32).abs() as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }
    // Residuals that can still host a large item (>= 40) are valuable; keep them.
    if post_residual >= 40 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Residual too small for the upcoming item -> likely dead space.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only if it is genuinely attractive,
        // i.e. early stream or many open bins with scattered residuals.
        score += 10.0 + pressure * 0.5 - mean_residual * 0.05;
    } else {
        // Slight preference for bins with below-average residual (tighter bins).
        score += (bin_residual as f64 - mean_residual) * 0.03;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but penalize dead space
    // that is too small to be useful for typical items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Next item can follow directly: reward exact or near matches strongly.
            let gap = pr - nxt;
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus for a perfect two-item chain (bin becomes exactly full).
            if gap < 1.0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot fit here: penalize proportionally to how "wasted"
            // the leftover space is relative to the incoming item.
            let waste = nxt - pr;
            score += 12.0 * (waste / bin_capacity as f64);
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins that are either tighter than
    // average (consolidating) or exactly complementary to the stream.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= 6.0 * (mr - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * ((post_residual as f64) - mr) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good 2-step chain; make empty bin mildly costly so
    // it wins only when lookahead matching elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    // Late in the stream, tighten up: leave fewer partially-filled bins behind.
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 {
        let t = post_residual as f64 / bin_capacity as f64;
        let dead_penalty = (0.12 - t).max(0.0) * 60.0;
        score += dead_penalty;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; slight penalty if we leave a big gap anyway.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * pressure;

    // Deviation from mean residual: prefer bins with residuals close to item needs.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early on, be more selective (penalize loose fits); late, fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (1.0 - fit_ratio);

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If item is large relative to capacity and fits poorly elsewhere, opening is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth non-linear reward for tight fits (low post-residual).
    let tightness = (1.0 - fit_ratio).powi(3);
    score -= 12.0 * tightness * (1.0 + progress);

    // Penalize residual that is too small to hold typical future items,
    // with smooth coupling to stream progress.
    let dead = (fit_ratio * (cap / 50.0) - 1.0).powi(2);
    score += 8.0 * dead / (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap).powi(2);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap).powi(2);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild pressure to prefer bins below mean residual (balance spread),
    // smoothly scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (open_bins_count as f64).ln().max(1.0);

    // Slight preference for using existing bins over new bins as stream progresses.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
