    if pr == 0 {
        // Perfect fill: heavily rewarded
        score -= 40.0;
    } else if pr < 10 {
        // Dead-space class: residual too small for most items
        score += 25.0 + (10 - pr) as f64 * 1.5;
    } else {
        // Sub-class within decade: prefer residuals aligned to common item sizes
        let decade_class = (pr % 10) as f64;
        score += decade_class * 0.6;
        // Integer-division threshold: how many "typical" items could still fit
        let slots = pr / 20;
        score -= slots as f64 * 4.0;
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // Next item chains perfectly into this bin
            let chain_tightness = (pr - n) as f64;
            score -= 15.0 + (20.0 - chain_tightness.min(20.0)) * 0.5;
            if pr == n {
                score -= 20.0; // chain to exact fill
            }
        } else {
            // Next item won't fit here: this residual becomes stranded
            score += 12.0;
            // Extra penalty if stranded residual is in awkward modulo class
            if (pr % 25) < 10 {
                score += 8.0;
            }
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if pr <= 15 {
            score -= 10.0; // last chance AND near-perfect fill
        }
    }

    // --- New-bin candidate decision ---
    if bin_residual == bin_capacity {
        score += 45.0; // default: discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open a new bin when existing residuals are poor for this item
        if mean_residual < item_size as f64 * 0.7 && open_bins_count >= 2 {
            score -= 60.0;
        }
        // Late in stream, consolidation matters more
        score += progress * 15.0;
        // If next item is bigger, a fresh bin helps sequence it
        if next_item_size > item_size && next_item_size > 0 {
            score -= 8.0;
        }
        // Many open bins: slight extra reluctance to add another
        score += open_bins_count as f64 * 1.5;
    }

    // --- Mild crowding pressure: prefer filling existing bins when many are open ---
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
