        } else if post_residual <= 20 {
            score += 25.0; // only tiny items can use it
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Reward tight fits (waste ratio relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, prefer reusing existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        score += 55.0 + 2.0 * open_bins_count as f64;
        if post_residual > 0 && post_residual < 10 {
            score += 80.0;
        }
    } else {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward;
    // if post-residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 15.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean
    // (fill fuller bins first, keep sparse bins for future large items).
    score += 0.4 * (mean_residual - post_residual as f64);

    // Late-stream consolidation: near the end, prefer exact fills.
    if progress > 0.8 && post_residual <= 5 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + match_gap);
        // Perfect chain: post residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that can't fit the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 10.0;
    }

    // Compare against mean residual across open bins.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Slight preference for keeping many bins consolidated early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin, but less when the fit
    // elsewhere would be terrible or the next item needs the space.
    if bin_residual == bin_capacity {
        score += 25.0;
        // lookahead: if next item fits perfectly after this placement, new bin is good
        if next_item_size > 0 {
            let r = bin_capacity - item_size;
            if r >= next_item_size {
                score -= 8.0 + (r - next_item_size) as f64 * 0.15;
            } else {
                score += 6.0;
            }
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins already: discourage opening more
        score += open_bins_count as f64 * 1.5;
        return score;
    }

    // Reward tight fits (small post-residual) super-linearly.
    score -= 12.0 / (1.0 + post_residual as f64);

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        score += fitting_bins_count as f64 * 0.8;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 10.0;
            } else {
                score -= 4.0 * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Prefer bins with residual below the running mean (consolidate small spaces).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early on, be exploratory (favor balanced residuals);
    // late, be greedy (minimize post-residual strongly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - mean_residual).abs();
    score -= progress * 2.0;

    // Small penalty for using a very full bin when many bins are open
    // (keeps flexibility), unless fit is near-perfect.
    if bin_residual as f64 > mean_residual && post_residual > 20 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly compressed non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: penalize large post-residuals more as stream progresses
    let coupling = 1.0 + 2.0 * progress * progress;
    score += pr * 0.3 * coupling * norm_pr;

    // Reward tight fits (small post_residual) with a smooth bonus
    score -= (1.0 - norm_pr).powi(3) * 30.0 * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / pr));
    }

    // Penalize bins deviating from mean residual (balance residuals smoothly)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Many open bins: slight preference to fill existing ones rather than open new
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: bias it upward so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (eighths). Small classes are "good" leftovers.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7
    score += match class {
        0 => -18.0,          // near-perfect fit
        1 => -6.0,           // good
        2 => 0.0,
        3 => 4.0,
        4 => 8.0,
        5 => 12.0,
        6 => 16.0,
        _ => 20.0,           // huge waste
    };

    // Exact-fill bonus via modulo arithmetic.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Divisible-by-10 harmonics: residuals that are multiples of 10 pair
    // well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.5;
    }

    // Lookahead: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // harmonic pairing: post_residual and next size in same class of 20
        if post_residual / 20 == next_item_size / 20 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space creation: leftover cannot host next item
        score += 6.0;
        if post_residual < 10 {
            score += 6.0; // tiny dead space is worst
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 22.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no viable open bin, opening is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
    }

    // Late in the stream, tighten packing (avoid opening bins needlessly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty proportional to crowding of open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    // Mean-residual coupling: penalize bins far from mean residual
    // (keeps bin states balanced, enabling future pairings).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; penalize gaps that are small relative to typical items.
    if post_residual > 0 {
        // Dead space below ~10 is nearly unusable for real items; heavy penalty.
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 25 {
            score += 25.0 * (1.0 - (post_residual - 10) as f64 / 15.0);
        }
        // Bonus for exact or near-exact fills.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space shaping against the known next item: if the leftover gap can
    // exactly host the next item, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If leftover gap is smaller than next item but nonzero, it may be dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> consolidate; few open bins -> allow spreading.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual;
        // If mean residual of open bins is large, prefer reusing them.
        if mean_gap > item_size as f64 * 1.5 {
            score += 35.0;
        } else {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are the "nearly full" ones we want to close out).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Chain fit: residual exactly matches next item -> strong reward.
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; prefer smaller leftover slack after chain.
            score -= 120.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize creating near-unusable slivers,
            // but small slivers (<10) are dead space anyway.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 60.0;
            } else {
                score += 0.2 * (waste - next_item_size as f64).abs();
            }
        }
    }

    // Compare against mean residual: prefer bins that are already "tight"
    // relative to the fleet average (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 15.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // current bins are all poor fits (large residual mismatch) or fleet is empty.
    if bin_residual == bin_capacity {
        let poor_fits = next_item_size > 0 && post_residual >= next_item_size;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        } else if fitting_bins_count <= 1 {
            // Only this new bin fits well enough -> prefer it.
            score -= 200.0;
        } else if poor_fits {
            // Fresh bin keeps a clean 100-capacity space for the next item.
            score -= 150.0;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 350.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight late-stream conservatism: squeeze existing bins harder as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that no future item can use
    // (items are >= 1, but small residuals are often wasted)
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasted pairing potential
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 0 {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let slack = mean_residual / bin_capacity as f64;
        score -= 10.0 * crowded * slack * (1.0 - tightness);
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base new-bin cost: opening a bin is expensive
        score += 30.0;
        // but if this bin would leave a huge unusable residual, new bin becomes viable
        let waste = post_residual as f64 / bin_capacity as f64;
        score -= 55.0 * waste * waste;
        // late in the stream, avoid opening new bins more strongly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // if next item is large, opening fresh bin may be good
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early on, be slightly exploratory (favor balanced residuals)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let ideal_residual = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    let dev = (post_residual as f64 - ideal_residual).abs() / bin_capacity as f64;
    score += 20.0 * dev * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 1.5 * progress * progress);
    score += 20.0 * poly;

    // Reward tight fits smoothly (quadratic in item fill fraction)
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) * (0.5 + progress);
    } else if next_item_size > 0 {
        score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * norm_post);
    }

    // Mild penalty for many open bins with high mean residual
    score += 0.5 * (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64).powi(2);

    // New-bin candidate: penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual as fraction of capacity
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - post_frac).powi(3) * (1.0 - post_frac);

    // Harmonic classes: reward post_residual falling in "usable" residue classes.
    // Small post_residuals that are still reusable (multiples of common item
    // granularity) are better than awkward dead space.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = match pr % 10 {
            0 => 18.0,
            5 => 12.0,
            2 | 4 | 6 | 8 => 8.0,
            _ => 0.0,
        };
        // Only useful if some future item could fit: cap at ~max typical small item
        if pr >= 10 {
            score -= class_bonus;
        } else {
            // tiny dead space: penalize
            score += 8.0;
        }
    } else {
        // Perfect fill
        score -= 45.0;
    }

    // Integer-division thresholds: post_residual bucketed by how many
    // "medium" (size ~25) items still fit
    let fits_medium = pr / 25;
    score -= 6.0 * fits_medium as f64;

    // Lookahead: strongly reward bins that can also hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            // chain fit: next item's post residual also small -> harmonic chain
            let chain_res = post_residual - next_item_size;
            if chain_res % 10 == 0 { score -= 6.0; }
        } else {
            // this placement strands the next item elsewhere
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins unless current bin would be a bad host.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins to
        // encourage consolidation, shrinks late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 4.0 * open_bins_count as f64 - 15.0 * progress;
        // But if the item is large and no open bin fits well, new bin is fine
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 0 {
        // item doesn't fit anywhere else? (shouldn't happen since this bin fits)
        score -= 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "leftover" bin — using it up is good (bin cleanup).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.15;
    } else {
        score += (res_f - mean_residual) * 0.05;
    }

    // Prefer filling nearly-full bins entirely: waste metric
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Penalize gaps too small for the smallest plausible item (<= ~10 units dead zone)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost plus pressure
        score += 10.0 + (open_bins_count as f64).sqrt() * 5.0;
        // but attractive if nothing fits well elsewhere
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else if fitting_bins_count == 1 {
        // last chance bin: strongly favor using it
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is big and would not fit here, slightly favor keeping larger residual bins
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Divergence from mean residual: prefer bins that reduce residual spread
    score += ((post_residual as f64) - mean_residual).abs() * 0.5;

    // Mild late-stream tightness pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste == 0 {
            score -= 900.0;
        } else {
            // partial reward proportional to how well next item fits
            let tightness = 1.0 - (chain_waste as f64) / (bin_capacity as f64);
            score -= 300.0 * tightness;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use the leftover; penalize dead space relative to mean residual
        score += 0.5 * (post_residual as f64 - mean_residual).abs();
        score += (post_residual as f64) * 0.3;
    }

    // Penalize creating tiny unusable gaps (< 10, the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // fresh bin score: base cost of opening a new bin
        score = (bin_capacity as f64) * 0.9;
        // attractive if mean residual is fragmented (low mean residual means open bins are full)
        if mean_residual < item_size as f64 {
            score -= 100.0;
        }
        // if no open bin fits well, opening new bin is fine
        if post_residual > 0 && post_residual < 20 {
            score += 50.0;
        }
    }

    // Late in the stream, be more conservative with open bins (consolidate)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Slight preference for bins below mean residual (keep large residuals for large items)
    if (bin_residual as f64) < mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Dead space risk: next item won't fit here.
            score += 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer best-fit competition.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are large (poor fits elsewhere) or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_waste = mean_residual / (bin_capacity as f64);
        // Open new bin if open bins are mostly full (low mean residual).
        score += 20.0 - 25.0 * (1.0 - avg_waste) - 10.0 * progress;
        // If the current item is large, a fresh bin is attractive.
        score -= 0.15 * (item_size as f64);
    }

    // Prefer filling bins that are already partially committed (low residual).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight time pressure: as stream progresses, avoid leaving many half-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // Penalize creating very small unusable residuals (< typical min item 10 scaled).
    if post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Normalize post-residual: dead space as fraction of capacity
    let dead = pr / cap;

    // Smooth non-linear penalty on dead space: quadratic coupling amplified by stream progress
    // Early in stream, dead space is less costly (future items can fill it); later, more costly.
    score += dead * dead * cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (pr / (item_size.max(1) as f64 + pr));
    score -= tightness * tightness * (item_size as f64) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many open bins exist and mean residual is high
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 25.0 * (1.0 - mean_norm).powi(2) + open_bins_count as f64 * 2.0;
        // Lookahead: if next item fits in the new-bin residual, mild reward
        if (next_item_size as f64) <= pr && next_item_size > 0 {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: reward bins whose post-residual can host the next item
        if next_item_size > 0 {
            let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
            score -= fits_next * 10.0 * (1.0 - progress * 0.5);
        }
        // Mild preference for bins with residual near mean (keeps bin pool homogeneous)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * dev * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are near-perfect packs; reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Classify post_residual via integer division thresholds (harmonic bands)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 45.0; // near-perfect: dead space <= min item size
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 35 {
        score -= 10.0;
    } else {
        score += 15.0 * frac; // large residue: penalize wasteful packing
    }

    // Modulo arithmetic on post_residual: residues that pair with common
    // item sizes (multiples of 10) are reusable; odd residues are dead.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 >= 7 {
        score += 6.0; // awkward residue class
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / cap);
        } else {
            // next item cannot follow here; leftover must host something else
            score += 5.0;
        }
    }

    // Last-chance bonus: only one bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tightest, add mild penalty scaled by alternatives
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit. An empty bin has residual == cap,
    // so post_residual == cap here; give it a neutral-to-poor baseline that
    // good fits can beat but bad fits cannot.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 10.0; // baseline: mid-range, beatable by tight fits
        if fitting_bins_count <= 1 {
            // no real alternative: opening new bin is fine
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // big item stream: fresh bin preserves room for large followers
            score -= 15.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Prefer filling bins whose residual is already low relative to mean
    // (keep one "flex" bin large, drain the rest).
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0).min(2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky: penalize proportionally to how little
    // of the item-size space they can still absorb.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual tightly matches the item (snug fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 30.0 / (1.0 + tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains beautifully.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: only attractive when the current bin residual is
    // a bad fit or the mean residual across bins is small (fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 || post_residual < 10 {
            score -= 10.0;
        } else {
            // Keep using existing bins when they are still roomy.
            score += 15.0 + 20.0 * fragmentation;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits (minimize dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (chained perfect fit), or can still fit afterwards.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0; // chain: next item closes this bin perfectly
        } else if next_item_size <= post_residual {
            score -= 60.0;  // next item still fits, keep packing here
        } else {
            // next item cannot fit: post-residual becomes (temporary) dead space
            let waste = next_item_size - post_residual as u32;
            score += waste as f64 * 3.0;
        }
    }

    // Penalize leaving residuals that are too small to ever be useful
    // (items are >= 1, but small slivers relative to mean residual are dead).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.25 {
        score += 40.0;
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Early in the stream, be more willing to open new bins (keep options open).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when open bins are all bad fits,
        // penalized later when bin count grows.
        score += 80.0 * (1.0 - progress) + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin guarantees a home for the next item too
        }
    }

    // Mild late-stream pressure to fill existing bins rather than open new ones.
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin when alternatives exist, scaled by how many bins fit.
    if is_new_bin && fitting_bins_count > 0 {
        score += 25.0 + 10.0 * (fitting_bins_count as f64).ln().max(1.0);
    } else if is_new_bin {
        score += 5.0; // mild cost of consuming a fresh bin
    }

    // Reward tight fits in existing bins (small post_residual relative to capacity).
    if !is_new_bin {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * chain_quality;
        } else {
            // Leftover too small for next item: penalize dead space, more so late in stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 * progress;
        }
    }

    // Global pressure: many open bins with high mean residual -> discourage spreading,
    // prefer consolidating into bins below mean residual.
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Dead-space shaping: residuals < 10 (min item) are wasted; penalize strongly.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothed non-linearly.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    score += 12.0 * norm_pr * (1.0 - progress) * (1.0 - progress) - 8.0 * norm_pr * progress * progress;

    // Reward leaving a residual that could fit the lookahead item smoothly.
    let fits_next = (next_item_size as f64) <= pr && next_item_size > 0;
    if fits_next {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        let shortfall = (next_item_size as f64 - pr) / cap;
        score += 5.0 * shortfall * shortfall;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mild penalty for opening a new bin when many bins are open and mean residual is high.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 4.0 + 6.0 * (mean_residual / cap) * (open_bins_count as f64).sqrt();
    } else {
        // Reward using bins that deviate below the mean residual (consolidation).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let q = bin_capacity as f64;
    let post_class = (post_residual as f64 / (q / 8.0)).floor(); // 0..8 classes
    score -= post_class * 2.5;

    // Strong reward for near-perfect fills (dead space <= 5% of capacity).
    if post_residual <= bin_capacity / 20 {
        score -= 30.0;
    }
    // Penalize awkward middling residuals that few future items can use.
    if post_residual > bin_capacity / 2 && post_residual < bin_capacity {
        score += 6.0;
    }

    // Modulo-style coupling: post_residual divisible into fine slots is reusable.
    if post_residual > 0 && (bin_capacity % post_residual.max(1)) == 0 {
        score -= 4.0;
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 - snug * 0.15; // prefer snug follow-up fits
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // next item won't fit here
    }
    if next_item_size == 0 {
        score -= 5.0; // last item: fill anything, minimize bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > bin_capacity / 2 && next_item_size > post_residual;
        let base = 20.0 + 0.1 * open_bins_count as f64;
        score += if poor_fit { -10.0 } else { base };
    }

    // Prefer tighter bins among fitting candidates as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / q) * (1.0 + progress);

    // Mild pressure to close out bins with large residuals late in stream.
    score += mean_residual * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 10)
    // are the worst outcome. Penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 30.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host a typical item (>= 10),
    // mildly penalize "medium-dead" zones that most items can't use.
    if post_residual >= 10 {
        score -= 5.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Lookahead: if the next item fits in post_residual, this bin stays
    // productive — reward it. If next item is bigger than post_residual,
    // the gap becomes dead space after this placement — penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open;
    // encourage consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are numerous,
        // but relax penalty late in the stream or when this is a last chance.
        score += 25.0 + pressure * 4.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance to use an open bin: strong reward to avoid a new bin.
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (better packing quality).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight late-stream consolidation bonus: fill existing bins harder.
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can serve next item too
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space (< 10) that is nearly unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bins are fragmented (high mean residual spread) or item fits nothing well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: new bins are cheap; late: prefer consolidating.
        score += 10.0 * (1.0 - progress);
        // If many bins can fit, discourage opening a new one.
        score += 3.0 * fitting_bins_count as f64;
        // If mean residual is large (lots of slack around), discourage new bin.
        score += 0.1 * mean_residual;
        // Perfect-fit temptation: if item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (balance slack across bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for using more-open-bin states to close bins out.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement (primary objective)
    let mut score = pr;

    // Smooth non-linear waste shaping: moderate residuals are tolerable,
    // very large residuals (dead space) are quadratically penalized.
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (1.0 - progress);

    // Lookahead coupling: if the next item cannot fit in the resulting residual,
    // penalize smoothly proportional to how much it misses by.
    if next_item_size > 0 {
        let miss = (next_item_size as f64 - pr).max(0.0);
        score += 0.8 * miss * (1.0 - 0.5 * progress);
    }

    // Fragmentation guard: tiny post-residual is good (tight fit) — reward it.
    score -= 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (pr_norm.min(0.2) / 0.2);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless residual waste is huge).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild preference to fill existing bins when many are open.
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // New-bin candidate (empty bin): make it unattractive unless it yields
    // a notably better residual than typical open-bin fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in the "small residue"
    // classes (1..=10) is nearly unusable -> heavy penalty.
    let dead = post_residual.min(10) as f64;
    score += dead * dead * 0.6;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-25 harmonic classes: residuals that are multiples of 25 remain
    // useful for typical item sizes; reward them slightly.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual -> mild reward
            let nres = post_residual - next_item_size;
            score -= 8.0 - (nres.min(10) as f64) * 0.4;
        } else {
            // next item cannot use this bin's remainder -> penalize large waste
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64) * 0.1;
    }

    // New-bin candidate: make the empty bin attractive only when open bins
    // are fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 + fragmentation * 0.3 + (item_size as f64) * 0.15 + progress * 5.0;
    } else {
        // Prefer packing into fuller bins: reward small pre-residual.
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // Slight penalty for opening many bins relative to progress.
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (>=1) can use well
    // are heavily penalized. Gap in (0, 10) is nearly unusable; exact fits are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: strongly favored
    } else if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0; // tiny dead space penalty
    }

    // Reward using a bin whose residual is tight relative to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing ones;
    // with few open bins, spreading is cheaper so slightly favor the new-bin candidate.
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    // New-bin candidate (empty bin): only attractive when the item leaves a large,
    // flexible residual and existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin, offset by pressure to reuse open bins.
        score -= 15.0;
        // Penalize opening a new bin when an existing bin would fit tightly (fit_ratio high).
        score += 35.0 * fit_ratio;
        // If the next item could use this item's post_residual in the fresh bin, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Keeping room for the known next item is valuable in any open bin.
        score -= 12.0;
    }

    // Mean residual coupling: if open bins are already loose on average, avoid
    // creating yet another loose bin; prefer bins that tighten the spread.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly fills the post-residual (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to how tightly next item fits the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
        } else {
            // Next item won't fit here: penalize creating dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 2.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 150.0;
    }

    // Penalize low post-residual that is unusable dead space (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if post_residual == 0 {
        score -= 300.0; // perfect closure
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Compare post-residual relative to mean residual: placing here keeps balance.
    let mean = mean_residual.max(1.0);
    let rel = (post_residual as f64 - mean) / mean;
    score += rel * 20.0;

    // Early in the stream, be more willing to open/use bins flexibly;
    // late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Slight penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it unattractive unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on unusable dead space (small leftovers are very costly)
    if post > 0.0 {
        score += (post / cap).powi(3) * cap * 0.5;
    }

    // Strongly reward last-chance bins (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.75;
    }

    // Lookahead (k=2): penalize if next item cannot fit in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += (nxt - post) * 0.8;
        } else if post >= nxt {
            score -= 2.0;
        }
    } else {
        // Last item of stream: filling any bin is free win
        score -= cap * 0.5;
    }

    // New-bin candidate handling: discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 1 { 0.35 } else { 0.05 };
        score += cap * pressure * (1.0 + 0.05 * open_bins_count as f64);
        // Early in stream, be more reluctant to open bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += cap * 0.2 * (1.0 - t);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with global state)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild consolidation pressure: prefer placing into existing bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but dead-space penalty softens as stream progresses.
    let mut score = pr * (1.0 - 0.45 * progress);

    // Non-linear polynomial coupling of residual with progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * poly * (0.5 + progress);

    // Last-chance bin: strong reward, decaying with progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (nxt / (pr + 1.0))) * (1.0 - 0.4 * progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize bins far from mean residual (fragmentation of the pool).
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // Mild pressure against accumulating too many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Small exact-fit bonus.
    if pr == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = bin_capacity / 4;
    let class = post_residual % q;
    // Residuals in the "dead zone" (small but nonzero) are worst
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if class < 4 {
        score -= 6.0; // near quarter-boundary: good harmony
    } else if class > q - 4 {
        score -= 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
        // harmonic bonus if next_item_size is a divisor-friendly class
        if (post_residual % next_item_size.max(1)) < 3 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        score += 8.0; // next item won't fit here
    }

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0 - 0.5 * mean_residual;
        // early stream: more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Crowding penalty: many open bins with high mean residual -> consolidate
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (unusable gaps).
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize wasteful placements into large-residual bins when item is small
    // (preserve big residual bins for big future items).
    let waste = bin_residual as f64 - item_size as f64;
    if waste > 60.0 && item_size < 40 {
        score += (waste - 60.0) * 0.4;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 30.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.5 + progress * 10.0;
    } else {
        // Slight preference for reusing bins with below-average residual
        // (keeps tight bins for tight fits, spreads load sensibly).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with little waste left afterwards.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after2 = post_residual - next_item_size;
        score -= 25.0 - (after2 as f64).min(20.0);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space.
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize tiny unusable leftovers (dead space) that don't match next item.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Tight fit reward: bin nearly full after placement.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so we don't open bins casually.
        score += 5.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 + 10.0 {
            // Plenty of residual space elsewhere: discourage new bin.
            score += 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference toward bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    score -= (cap - post_residual as f64).sqrt() * 6.0;

    // Penalize dead space that is too small to be useful for typical items,
    // but only when it is nonzero (perfect fit is ideal).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0; // tiny slivers are wasted capacity
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post residual cannot host next item: mild penalty scaled by wasted opportunity
            score += 4.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score -= open_pressure * (1.0 - progress) * 2.0;

    // Prefer bins whose residual is below mean residual (drier bins first),
    // keeping wet bins available for future items.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0 * (mean_residual - res) / cap;
    } else {
        score += 2.0 * (res - mean_residual) / cap;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and would leave a very poor fit in existing bins, or when
    // post_residual in the new bin leaves a highly reusable space.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // Reward new bin if the item is large (hard to place elsewhere cleanly).
        score -= (item_size as f64 / cap) * 20.0;
        // Reward if leftover space in a fresh bin is highly reusable (>= half capacity).
        if post_residual as f64 >= cap * 0.5 {
            score -= 12.0;
        }
        // Late in the stream, discourage opening new bins more strongly.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Tight fits rewarded smoothly (quartic coupling)
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * tight * tight * cap;

    // Stream-progress coupling: late in stream, penalize residual more (waste matters)
    score += 25.0 * progress * norm_pr * cap;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post-residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (nxt / cap);
        } else {
            score += 15.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize bins far below mean residual (unbalanced usage), smooth coupling
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev * cap;

    // Crowding: many open bins, prefer filling existing ones
    score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows for residuals in "unusable" classes.
        // Small residuals (<10, min item size) are dead space; but tiny is fine if stream ending.
        let progress = step_index as f64 / total_items as f64;
        if post_residual < 10 {
            score -= 200.0 * (1.0 - progress); // dead space less costly near end
        }
        // Harmonic class via integer division: which item classes can still fit?
        // Items are 1..100 unknown, so measure divisibility structure of post_residual.
        let mut divisors_fit = 0u32;
        let mut d = 1u32;
        while d <= post_residual {
            if post_residual % d == 0 {
                divisors_fit += 1;
            }
            d += 1;
        }
        // More divisors => more chances a future item exactly fills; reward.
        score -= 15.0 * (divisors_fit as f64).ln().max(0.0);

        // Quantized capacity fractions: residual in (0,25] = worst class (hard to fill),
        // (25,50] = medium, (50,75] = good, (75,100) = great.
        let frac = pr / cap;
        if frac <= 0.25 {
            score += 40.0; // awkward sliver
        } else if frac <= 0.5 {
            score += 10.0;
        } else if frac <= 0.75 {
            score -= 10.0;
        } else {
            score -= 20.0;
        }

        // Lookahead coupling: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size < post_residual {
                let nxt_post = post_residual - next_item_size;
                // reward small leftover after chaining
                score -= (20.0 - (nxt_post as f64 / cap) * 20.0).max(0.0);
            } else {
                // next item cannot follow here; slight penalty scaled by overshoot class
                score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
            }
        }

        // Last-chance bin: strongly favor using it rather than opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate handling: empty bin should only win when open bins are bad.
        if bin_residual == bin_capacity {
            // Penalize opening new bins moderately; mean residual context.
            score += 60.0 + mean_residual * 0.8;
            // Late in stream, avoid proliferation of open bins.
            score += open_bins_count as f64 * 2.0;
        } else {
            // Prefer bins with residual close to item (tight fit) beyond raw post_residual.
            score -= (item_size as f64 / bin_residual as f64) * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 45.0;
    } else {
        // Larger leftovers can still host future items; mild reward scaled by size.
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Reward tight fits (small fill ratio of used space wasted).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; opening new bins is penalized implicitly elsewhere.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has large post_residual; only
    // prefer it when the fit into existing bins would be very poor (large gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If lookahead item can use the leftover of this placement, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean residual coupling: if this bin's residual deviates favorably
    // (below mean), it is a tighter bin; prefer using tight bins first.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that the next item can fill.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = (post_residual as f64 - nxt).abs();
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportional dead space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Penalize creating unusable dead space relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tight fits.
    score += 0.5 * (item_size as f64 / bin_residual.max(1) as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving mid-range gap
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins are open, prefer filling them rather than opening more.
        score += (open_bins_count as f64).sqrt() * 3.0;
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 8.0 * ((res - mean_residual) / bin_capacity as f64);
    }

    // Mild preference for fuller bins overall.
    score -= 6.0 * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled mildly
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling: post_residual vs stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 60.0 * poly * (1.0 - progress);

    // Later in the stream: penalize residual quadratically (waste matters more)
    score += 0.5 * progress * norm_pr * norm_pr * cap;

    // Perfect fit reward (smooth, non-piecewise)
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: reward residual that can host the next item
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = pr - nis;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Many open bins: slight penalty to discourage bin proliferation
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" residue classes (multiples of common item sizes) are reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward leftovers divisible by small harmonic classes (10, 20, 25, 50)
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 20 == 0 {
            score -= 7.0;
        } else if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // Odd residues are dead-space prone
            score += 3.0;
        }

        // Integer-division threshold: leftover smaller than the smallest
        // plausible item class is nearly dead space.
        if pr < 10 {
            score += 15.0;
        } else if pr < 20 {
            score += 6.0;
        }
    } else {
        // Perfect fit: best possible outcome
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportionally to how snugly
            let slack = (pr - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus if post-after-next residual again lands on a class
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 10.0;
            } else if pr2 % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty
            score += 4.0;
        }
    }

    // Capacity fraction thresholds on current residual
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac >= 0.9 {
        score -= 6.0; // nearly empty bin: cheap to use
    } else if frac <= 0.2 {
        score += 5.0; // nearly full: prefer saving it unless tight fit
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        if crowd < 0.25 && open_bins_count > 0 {
            score -= 8.0; // open a fresh bin rather than squeeze
        } else {
            score += 10.0; // prefer existing bins generally
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small to hold even the smallest plausible item
    // (or the lookahead item) are "dead space": heavily penalize them.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit, perfect
    } else if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else {
        // Dead-space zone: post_residual too small for next item or typical items
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Gaps below 15 are rarely usable: strong penalty
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 3.0;
        }
        // Gaps in 15..30 are semi-unusable: moderate penalty
        else if post_residual < 30 {
            score += (30 - post_residual) as f64 * 1.0;
        }
    }

    // --- Reward tight fits (small waste relative to item size) ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // --- Last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; only attractive when existing fits are poor.
        // Base cost of opening a bin:
        score += 55.0;
        // Pressure: many open bins -> discourage opening another
        score += 4.0 * open_bins_count as f64;
        // If lookahead item fits perfectly in the fresh bin, mild discount
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // --- Coupling with mean residual: avoid dumping into bins whose residual
    // is far from the item (poor match), prefer bins near-tight ---
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Prefer bins whose residual is below mean (filling fuller bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // --- Lookahead synergy: if next item exactly fits the post residual,
    // strongly reward this placement ---
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
