    score -= 45.0 * poly * (1.0 - norm_pr * norm_pr);

    // Penalize large residuals early (keep bins flexible), reward mid residuals
    score += 25.0 * (1.0 - poly) * norm_pr * norm_pr;

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
