    }

    // Mean residual alignment: prefer bins near the mean residual to balance load
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals divisible into small chunks (e.g., multiples of 10, 25, 50) are friendlier.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 3.0; }
        if pr >= 10 && pr < 20 { bonus -= 2.0; }  // tiny slivers are near-dead space
        score -= bonus;
    }

    // Dead-space penalty: post residual too small for any plausible next item.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if the next item fits exactly or harmonically in the leftover.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 - slack * 0.05; // exact fit strongly favored
            if (pr % next_item_size) == 0 {
                score -= 3.0; // harmonic subdivision of the leftover
            }
        } else {
            score += 5.0; // next item cannot follow into this bin
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * crowding - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    }

    // Prefer tighter existing bins: relative fill fraction.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fill * fill;

    // Mild pressure when many bins are open: consolidate.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space): gaps too small
    // for the smallest plausible item (<= 5) are wasted forever.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    } else if post_residual > 5 && post_residual <= 12 {
        score += 25.0;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual was already small (compacting strategy).
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        // placing here would leave a dead gap for the next item
        score += 15.0;
    }

    // Open bins pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if few open bins or huge item
        score -= 10.0;
        score += 2.0 * open_bins_count as f64;
        if item_size > 70 && open_bins_count > 0 {
            score -= 5.0;
        }
    } else {
        // mild penalty per open bin to encourage consolidation
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (smaller gaps).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Slight progression tilt: later in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
        // Extra penalty if the leftover is unusably small (below typical minimum item).
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score -= (1.0 - tightness / bin_capacity as f64) * 10.0;

    // Relative-to-mean coupling: bins below mean residual are already well-used;
    // filling them further is good. Bins above mean residual waste space.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 3.0 + open_bins_count as f64 * 0.5;
    }

    // New empty bin candidate: make it costly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If next item is huge and nothing can chain, new bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual.min(100) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly rewarded: low post_residual is good.
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight_fit * tight_fit;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size > post_residual {
                score += 0.35 * (next_item_size - post_residual) as f64;
            } else {
                score -= 0.5 * next_item_size as f64; // lookahead item fits here: bonus
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Reward using bins that are already relatively empty vs mean residual
    // (prefer filling emptier bins first, keeping tight bins for tight fits).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // When many bins are open, encourage consolidating into existing bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (future items unknown); late in the stream, pack tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 0.5 + t;
    score *= horizon;

    // New-bin candidate: reserve it for genuinely bad fits into open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.4 * item_size as f64 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: post residual, with non-linear penalty on mid-range waste
    let mut score = pr;

    // Smooth polynomial coupling: waste that is too large (but not zero) is bad,
    // tiny residuals are good (tight fit). Use quartic of fit fraction.
    let tightness = (1.0 - fit_frac).powi(4); // near 1 when tight fit
    score -= 12.0 * tightness;

    // Penalize residuals that are awkwardly mid-sized relative to future need
    let next_f = next_item_size as f64;
    if next_item_size > 0 {
        let gap = pr - next_f;
        let gap_n = gap / cap;
        // smooth reward when post_residual closely matches next item
        score -= 8.0 * (-gap_n * gap_n * 40.0);
        // penalize residual slightly below next item (dead space)
        if gap < 0.0 {
            score += 0.5 * (-gap);
        }
    }

    // Stream-progress interaction: late in stream, prefer tighter packing
    let late = progress * progress;
    score += 6.0 * late * fit_frac * (1.0 - fit_frac);

    // Last-chance bonus: only fitting bin -> strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln_1p();
        score += 10.0 + 4.0 * crowd + 10.0 * mean_residual / cap;
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward tight fits (small post_residual) extra strongly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 are more
    // likely to be filled exactly by future items (sizes often cluster on 10s).
    if pr >= 10 && pr % 10 == 0 {
        score -= 12.0;
    } else if pr > 0 && pr % 10 != 0 {
        // Non-harmonic dead space penalty, scaled by how "wasted" it is.
        score += (pr % 10) as f64 * 1.5;
    }

    // Lookahead coupling: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_pr = pr - next_item_size;
            if nxt_pr % 10 == 0 || nxt_pr == 0 {
                score -= 10.0;
            }
            score += nxt_pr as f64 * 0.3;
        } else {
            // Next item cannot fit here: mild penalty for leaving large gap.
            if pr > 40 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 3.0;
        // If mean residual across open bins is small, new bin is more attractive.
        score -= (cap - mean_residual).max(0.0) * 0.2;
    }

    // Fraction-of-capacity harmonic threshold on post_residual.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.2 {
        score -= 15.0; // small leftover is good
    } else if frac >= 0.5 {
        score += 10.0; // half-empty bin is wasteful to leave
    }

    // Integer-division threshold: post_residual / item_size quotient classes.
    if item_size > 0 && pr >= item_size {
        let q = pr / item_size;
        if q >= 2 {
            score -= 5.0; // room for multiple more items
        }
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward residuals that can still accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to the next item's need.
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Open-bin pressure: discourage scattering across many bins when few
    // fitting bins exist; encourage using the last-chance bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Penalize bins whose residual is far below the mean (already fragmented),
    // favor bins with more usable room.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 2.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || post_residual >= 60 {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead match: next item fits with small slack
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - 2.0 * slack;
        } else {
            score -= 5.0 * (10.0 / slack);
        }
    }
    // Next item cannot fit in leftover: penalize dead space more when leftover is small-but-useless
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Penalize post_residual that is below the minimum item size (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins tighter than the average residual
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late in stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline, discourage unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 35.0 - 5.0 * (open_bins_count as f64).min(7.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space: residual too small for the smallest plausible next item.
    let min_next = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < min_next {
        score += 15.0;
    }

    // Lookahead coupling: bonus if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= 5.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is below average (tighter bins).
    if mean_residual > 0.0 {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fitting_bins_count == 0;
        if poor_fit {
            score -= 20.0; // must open a bin anyway
        } else {
            score += 25.0 + 30.0 * progress;
        }
    }

    // Mild time decay: late in stream, tighten packing further.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as u32 == bin_capacity) as f64;

    // normalized post-residual and its smooth polynomial couplings
    let x = pr / cap;                          // fraction of space left after placement
    let tight = 1.0 - (item_size as f64) / r.max(1.0); // slack tightness of the fit

    // base: waste, penalized super-linearly (dead space grows quadratically in badness)
    let mut score = pr + 60.0 * x * x * cap;

    // reward tight fits smoothly (tight -> 0)
    score += 40.0 * tight * tight * (1.0 - tight);

    // stream-progress coupling: late in the stream, compactness matters more
    let late = progress * progress;
    score *= 1.0 + 0.8 * late * x;

    // lookahead: bonus if post-residual exactly or nearly fits next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 35.0 * (-gap * gap / 40.0).exp();
    }

    // last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // crowding pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * x;

    // mean-residual coupling: if this bin is below mean residual, it's a good filler
    score -= 6.0 * (mean_residual - r) / cap;

    // new-bin candidate penalty: only open when nothing fits well
    score += is_new_bin * (30.0 + 50.0 * (1.0 - progress) + 20.0 * tight * (1.0 - tight));

    // smooth tie-breaker decaying over the stream
    score += 2.0 * (1.0 - progress) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" class (divisible by common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Class bonus: leftover compatible with next item sizes
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Next item fits in this bin's leftover -> strong reward
                score -= 12.0 + 0.15 * next_item_size as f64;
                // Perfect harmonic match: leftover is a multiple of next item
                if pr % next_item_size == 0 {
                    score -= 6.0;
                }
            } else {
                // Next item cannot fit in leftover -> penalize dead space
                score += 4.0 + 0.10 * (next_item_size - pr) as f64;
            }
        }

        // Small leftovers are dead space; quantize penalty by integer division
        let class = pr / 10; // harmonic decile class
        match class {
            0 => score += 8.0,           // 1..9 : nearly dead
            1 => score += 4.0,           // 10..19: hard to reuse
            2 => score -= 2.0,           // 20..29: fits medium items
            3 => score -= 4.0,           // 30..39
            4 => score -= 5.0,           // 40..49
            _ => score -= 6.0,           // >=50: very reusable
        }

        // Modulo coupling: leftovers divisible by 10 or 25 align with common sizes
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
    } else {
        // Perfect fill
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill_ratio;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate handling: only attractive when no good open fit
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when open bins have slack
        score += 10.0 + 30.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // pairing potential in fresh bin
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps big slots)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (non-linearly).
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Dead space threshold: gaps below ~25% of capacity are hard to reuse.
        let dead_threshold = bin_capacity as f64 * 0.25;
        if pr < dead_threshold {
            let severity = (dead_threshold - pr) / dead_threshold; // 0..1
            score += severity * severity * 60.0;
        }
        // Perfect fit: absolute zero waste is highly rewarded.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits: fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Penalize waste relative to mean residual of open bins (context coupling).
    score += (pr - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it, else item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: more open bins => prefer consolidating into existing ones.
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Post-residual too small for next item: mild penalty for stranded space.
            score += 5.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 35.0;
        // Early in the stream, opening bins is cheaper (room to consolidate later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If many bins are open already, adding another is worse.
        score += open_bins_count as f64 * 1.5;
        // If the current bin would be a very poor fit (huge waste), allow new bin.
        if post_residual > 0 && post_residual < item_size.min(10) {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residuals too small to hold any item (min size 1..100 unknown,
    // assume small items possible but penalize very small leftovers nonlinearly).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chaining: bin fully consumed in two steps
        } else if next_item_size <= post_residual {
            let chained_left = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chained_left as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.05 * overshoot;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual stays
    // close to (or below) the current mean residual to keep residuals homogeneous.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size)
    // immediately. Make the empty bin attractive only when the item is large
    // (little waste) or when many open bins exist and fit is bad.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.5;
        // Prefer reusing open bins early in the stream when they exist.
        if open_bins_count > 0 {
            score += 10.0;
        }
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    }

    // Mild preference to fill already-open bins to reduce bin count.
    if bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: small unusable residual that no typical item fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item exactly fits the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // leftover too small for the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the global mean residual.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Time horizon: early in the stream, be more willing to keep bins flexible
    // (penalize very low post_residual less late, more early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let flexibility_weight = 8.0 * (1.0 - progress);
    score += flexibility_weight * (post_residual as f64 / bin_capacity as f64);

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: make empty-bin attractive only when the current bin fit is poor.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin; adjusted by how bad alternatives would be
        score = 55.0 - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 30.0 * poly * (1.0 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residual that fails to fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize opening a new bin when good fits exist, more so late in stream
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild attraction toward bins with residual near the mean (balance residuals)
    let dev = (pr - mean_residual).abs();
    score += 0.5 * dev * (1.0 - progress);

    // Small smooth shrinkage of dead space late in stream
    score -= 5.0 * (norm_pr * std::f64::consts::PI).sin().abs() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-halves and exact-quarters are premium states.
    let pr = post_residual as u32;
    let cap_u = bin_capacity;
    if pr == cap_u / 2 {
        score -= 12.0; // perfect half residual: most reusable class
    } else if pr == cap_u / 4 || pr == 3 * cap_u / 4 {
        score -= 6.0;
    } else if pr % 10 == 0 {
        score -= 2.0; // decile-aligned residuals pack well
    } else if pr < 10 {
        score += 15.0; // dead space: nearly unusable
    } else {
        // penalize residuals in awkward integer-division classes (mod 3, mod 7)
        if pr % 7 == 0 { score += 3.0; }
        if pr % 3 == 1 { score += 1.5; }
    }

    // Lookahead coupling: reward if next item fits exactly in the post residual class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect follow-up match
        } else if next_item_size <= pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 8.0 * fit_frac; // better fill of remaining space
            // harmonic bonus if next item lands residual on a nice class boundary
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 3.0; }
            if nr == cap_u / 4 { score -= 4.0; }
        } else {
            score += 4.0; // next item cannot use this bin's remainder
        }
    }

    // Waste ratio term: fraction of capacity lost.
    let waste = post_residual as f64 / cap;
    score += 20.0 * waste * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, more when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        // but opening a new bin is fine late in the stream with tight mean residual
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 && progress > 0.5 {
            score -= 10.0;
        }
    }

    // Early stream: prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / cap);

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps (< 10,
    // and even gaps below the typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Penalize waste proportionally to how little is left relative to capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * post_frac * post_frac * (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: this residual becomes dead space.
            score += 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (tighter fills) rather than spreading; also make new bins less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * post_frac * 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, scaled by pressure.
        score += 30.0 + pressure * 15.0;
        // Early in the stream, opening bins is cheaper; late, it is expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If nothing fits well elsewhere (few fitting bins), allow new bin.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for bins already below mean residual (balancing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead can still fit into the leftover space: strong reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    }

    // Lookahead item would NOT fit here: penalize wasting residual on a bin that
    // leaves space unusable for the known next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize small but nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good fills), punish loose bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, prefer keeping flexibility (favor emptier bins less aggressively).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    // Slight preference for consolidating when many bins are open.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size (best-fit core).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still go here; reward proportionally.
            score -= (post_residual as f64 / next_item_size as f64).min(3.0) * 8.0;
        } else {
            // Dead space for the next item: penalize more as stream progresses.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += (next_item_size - post_residual) as f64 * (1.5 + 2.5 * progress);
        }
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // near-perfect fill on last chance
        }
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // which preserves roomier bins for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if bin_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post-fit leftover is very poor and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit_here = (post_residual as f64) > (bin_capacity as f64) * 0.6;
        if poor_fit_here || fitting_bins_count == 0 {
            score -= 15.0; // allow opening a fresh bin
        } else {
            score += 20.0; // discourage wasteful new bins
        }
    }

    // Mild time-horizon modulation: early in the stream, be more conservative
    // about creating fragmented residuals (long future ahead).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, mildly damped
    let mut score = pr * (1.0 - 0.15 * progress);

    // Non-linear coupling: quadratic waste penalty scaled by progress
    score += 4.0 * pr_norm * pr_norm * cap * (0.5 + progress);

    // Reward tight fits: smooth interaction of item size with post residual
    score -= 2.0 * item_norm * (1.0 - pr_norm) * (1.0 - pr_norm) * cap * (0.5 + progress);

    // Lookahead: penalize residuals too small for the next item, reward usable ones
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += 3.0 * (-gap) * (0.5 + progress);
        } else {
            score -= 1.5 * gap / cap * nx / cap * cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Many open bins: prefer filling existing ones over spreading
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Mean residual coupling: prefer bins near mean residual (smooth)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly, more strongly early on
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal post residual.
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 3.0;

    // Dead-space penalty: post residual below the smallest useful class is bad,
    // unless it's exactly zero (perfect closure).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class logic: quantize post_residual into capacity fractions.
    // Residuals that are multiples of common item classes (10, 20, 25, 50) are reusable.
    let res = post_residual as u32;
    if res > 0 {
        let harmonic_bonus = if res % 10 == 0 { 12.0 }
        else if res % 5 == 0 { 6.0 }
        else { 0.0 };
        score -= harmonic_bonus;
        // Integer-division threshold: residual classes near half capacity are very useful.
        if res / 25 >= 2 {
            score -= 8.0;
        } else if res / 25 == 1 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Exact chain fit: next item exactly fills the bin.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't host the next item; penalize proportional to wasted fraction.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin has a good fit,
    // or when open bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // Reward new bin when mean residual of open bins is low (all bins nearly packed).
        score -= (bin_capacity as f64 - mean_r) * 0.4;
        // Penalize opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
        // Penalize if many open bins could fit the item anyway.
        score += fitting_bins_count as f64 * 5.0;
        // A new bin is good if the item is large and next item is large too.
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 3 {
            score -= 10.0;
        }
    }

    // Slight preference to fill fuller bins first (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are pure waste -> heavy penalty.
    let min_item = 1u32;
    let dead = post_residual <= 10 && post_residual >= min_item;
    if dead {
        score += 25.0;
    }

    // Perfect / near-perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fit relative to bin residual (small waste fraction).
    if bin_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += 10.0 * waste_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit in post_residual, mild penalty for tempting gap.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: only attractive when existing bins are crowded
    // (mean residual low) or this bin is a poor fit.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 60.0 + 30.0 * pressure - 0.5 * open_bins_count as f64;
        // Late in the stream, slightly discourage proliferating bins.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            // Slack that can still host the next item: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Dead space relative to next item: penalize proportionally to wasted fraction.
            let waste = (next_item_size - post_residual) as f64;
            score += 40.0 * (waste / bin_capacity as f64);
        }
    }

    // Penalize post residuals that are small but nonzero (unusable dead space for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Compare against mean residual: placing into a bin with residual far below mean
    // fragments the stream; placing into a large-residual bin is cheap.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin fit is poor or
    // next item would be blocked. Encourage opening fresh bins early in the stream
    // or when many bins are open but this one would leave big waste.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; offset if this bin would otherwise create dead space
        // or if the next item doesn't fit the post residual of existing bins.
        let mut new_bin_score = 300.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 100.0; // fresh bin also hosts next item comfortably
        }
        if open_bins_count == 0 {
            new_bin_score -= 300.0; // must open
        }
        // Late in stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 150.0 * progress;
        score = score.min(new_bin_score + score * 0.0 + new_bin_score * 0.0 + new_bin_score);
        // ensure new-bin candidate uses its own score when it should lose:
        score = new_bin_score.max(score.min(new_bin_score));
        score = new_bin_score;
    }

    // Mild scaling of residual by stream position: early on, keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * tightness * (item_size as f64);

    // Lookahead: strongly reward bins where the next item also fits in post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Penalize if next item does NOT fit: dead space becomes more costly.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 4.0 * (1.0 - tightness);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive for small items
    // (which leave a big useful residual) or when open bins have poor mean residuals.
    if bin_residual == bin_capacity {
        let small_item_bonus = 60.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        let poor_alternatives = 30.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        score -= small_item_bonus + poor_alternatives;
        // Discourage opening new bins early in the stream when few bins exist.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 * (1.0 - progress);
    } else {
        // Penalize using bins whose residual is much larger than the mean (save them).
        if (bin_residual as f64) > mean_residual + 10.0 {
            score += 5.0;
        }
        // Reward using bins below mean residual (consolidating waste).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Prefer filling bins that are already fairly full (post_residual small => good).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr.powf(1.0 + 0.9 * progress) * (1.0 + 0.35 * progress * pr_norm);

    // Penalize large dead space late in the stream (wasted capacity becomes costlier)
    let dead_penalty = (pr_norm * pr_norm) * (30.0 + 70.0 * progress);

    // Reward tight fits: small post_residual gets a bonus scaled by item size
    let tight_bonus = (item_size as f64 / cap) * (cap - pr).max(0.0) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it over opening a new bin
    let last_chance = if fitting_bins_count == 1 { -25.0 - 20.0 * progress } else { 0.0 };

    // Lookahead: reward if next item fits the post residual
    let lookahead = if next_item_size > 0 {
        if (next_item_size as f64) <= pr { -6.0 - 8.0 * (1.0 - pr_norm) } else { 4.0 * pr_norm }
    } else { 0.0 };

    // Slight preference to balance residuals relative to mean
    let balance = 0.05 * (pr - mean_residual);

    // New-bin candidate: prefer it only when it would be nearly filled by this item
    let new_bin_adjust = if bin_residual == bin_capacity {
        (item_size as f64 / cap).powi(3) * 40.0 - 10.0
    } else { 0.0 };

    base + dead_penalty - tight_bonus + last_chance + lookahead + balance + new_bin_adjust
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small-dead-space classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Class 0: perfect fit -> huge reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Integer-division classes on post_residual (harmonic bands of the capacity).
        let band = pr / 10; // 0..=10 harmonic classes
        match band {
            0 => score -= 60.0,             // tiny dead space, near-perfect packing
            1 => score -= 25.0,             // still very good
            2 => score -= 8.0,
            3 => score -= 2.0,
            4 => score += 0.0,
            5 => score += 4.0,              // mid dead space mildly bad
            6 => score += 8.0,
            7 => score += 14.0,
            8 => score += 22.0,
            9 => score += 32.0,
            _ => score += 40.0,             // large leftover
        }

        // Modulo-10 resonance: residuals that commonly recur pair well with typical items.
        if pr % 10 == 0 {
            score -= 10.0;
        }
        if pr % 5 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            // next item fits: penalize proportionally to wasted slack after that too
            let second_post = post_residual - next_item_size;
            score -= 20.0 - (second_post as f64) * 0.15;
        } else {
            // next item cannot use the residual: penalize large residuals more
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 95.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 {
            score -= 10.0; // big next item: fresh bin is fine
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / cap);

    // Deviation from mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, minimum item size) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    }

    // Non-linear penalty on moderately small residuals that few future items can use.
    let r = post_residual as f64;
    if r > 0.0 && r < 30.0 {
        score += (30.0 - r) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit here but the bin would be nearly sealed, small bonus.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones; discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow new bin if mean residual is low (existing bins nearly full).
        score -= (mean_residual - 20.0).max(0.0) * 0.5;
    } else {
        // Existing bins: slight reward scaled by open bins pressure.
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably (larger than mean keeps flexibility).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact match: post_residual equals next item size -> perfect 2-step fill.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leftover that next item cannot use at all.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fill now.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (densely packed), penalize consuming space in above-average bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mildly discourage opening a new bin while open bins fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream, pack tighter (future bins matter less).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead k=2)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize very small unusable leftovers relative to capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 15.0 * (0.1 - frac);
    }

    // Prefer filling bins with larger residuals less when many bins are open
    score += 0.05 * open_bins_count as f64 * frac;

    // Late in the stream, be more greedy about tight fits
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 20 {
        score -= 30.0 * t;
    }

    // Mild preference for bins near the mean residual (balance)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically as stream matures
    score += (pr / cap) * (pr / cap) * 30.0 * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth saturating bonus
    score -= 20.0 * (1.0 - pr / cap) * (1.0 - pr / cap) * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    }

    // Penalize placements leaving residual far from mean (fragmentation)
    score += (pr - mean_residual).abs() * 0.3 * (0.5 + progress);

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: prefer it only when residual is small and stream is early
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress - 15.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let post = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Class 0: residual <= C/8 -> near-perfect fit, big reward
    if post <= eighth {
        score -= 30.0;
    } else if post <= quarter {
        // Class 1: usable by most small items, mild reward scaled by exactness
        score -= 12.0 * (quarter - post) / quarter;
    } else if post <= cap / 2.0 {
        // Class 2: half-full band, neutral-ish, slight penalty for waste
        score += 4.0;
    } else {
        // Class 3: more than half wasted -> strong penalty
        score += 15.0 + (post - cap / 2.0) * 0.3;
    }

    // Lookahead harmony: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fits here: reward tighter couplings (harmonic resonance)
            let slack = post - nxt;
            if slack <= eighth {
                score -= 25.0; // exact pairing: excellent
            } else {
                score -= 10.0 * (1.0 - slack / cap);
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally
            score += 6.0 + (nxt - post) * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins -> encourage consolidation into existing bins over new bins
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual is near the mean residual (keeps residuals uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Integer-division threshold: residual mod 10 == 0 means clean multiple of 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Slight stream-phase nudge: late in stream, prefer tighter fills
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += post * 0.05 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space): residuals that are
    // too small to ever fit a typical item (items >= 1, but small gaps < ~20
    // are hard to fill) are worse than exact fits.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    // If next item almost fits (small miss), slight penalty for wasting the gap.
    if next_item_size > post_residual && (next_item_size - post_residual) <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (concentrate filling) when many bins are open.
    if (bin_residual as f64) < mean_residual && open_bins_count > 2 {
        score -= 5.0;
    }

    // Late in the stream, tighten up: prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // 2-step lookahead: strong reward if next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post - next;
            score -= 150.0 * (1.0 - slack / post);
        } else {
            // Next item cannot fit here: penalize leaving gaps that are too small
            // to be useful for typical future items.
            let gap_ratio = post / bin_capacity as f64;
            if post_residual < 10 {
                score += 60.0 * gap_ratio;
            }
        }
    }

    // Prefer bins whose residual is below the mean (pack tighter bins first),
    // penalize bins far above the mean residual (fragmented bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, favor tighter fills even more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to remaining capacity elsewhere; a fresh bin has full residual.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 40.0;
        // But if the item is large, a fresh bin may be best.
        if item_size >= 60 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space quadratically when residual is small.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward high fill ratio of the bin.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // Placing a smaller item here may block a better future fit; mild penalty.
            score += 6.0;
        }
        // Prefer leaving exactly-sized gaps for the next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = waste > (bin_capacity as f64 - item_size as f64) * 0.6;
        // New bin is penalized by default, less so late in the stream or when many bins are open.
        score += 45.0 - 25.0 * progress - (open_bins_count as f64).min(10.0);
        if poor_fit && fitting_bins_count > 1 {
            score += 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Global state coupling: prefer bins with residual near the mean (balanced packing),
    // but when mean residual is high, prefer filling the emptiest bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in stream: encourage consolidation into few bins.
    if step_index < total_items / 4 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear penalty on large leftover space, coupled with stream progress.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Coupling with mean residual: prefer bins close to the mean residual (balance preservation).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: penalize leaving residual that barely fails to fit the next item,
    // reward residual that comfortably fits it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            let fit_q = gap / cap;
            score -= 5.0 * (1.0 - 4.0 * fit_q * fit_q).max(-1.0);
        } else {
            score += 3.0 * (-gap / cap) * (-gap / cap) * cap * 0.1;
        }
    }

    // Last-chance bin bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when the stream is late
    // and open bins exist; smooth in progress.
    if bin_residual == bin_capacity {
        let late = progress * progress;
        score += 10.0 + 25.0 * late + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction slot does it land in?
    let quarters = post_residual / (bin_capacity / 4).max(1); // 0..4 class
    let class_penalty = match quarters {
        0 => -30.0, // near-perfect fill: excellent
        1 => 8.0,   // 25-50 leftover: mildly wasteful
        2 => 14.0,  // 50-75 leftover
        _ => 20.0,  // mostly empty bin: bad placement
    };
    score += class_penalty;

    // Modulo coupling: post_residual divisible by common item sizes (10/20/25/50)
    // leaves future items a chance to fill exactly -> reward.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 18.0 - (npr as f64) * 0.15;
        } else {
            score += 10.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        score += 22.0
            + mean_residual * 0.1
            + (open_bins_count as f64) * 1.5;
    }

    // Prefer bins with tighter residuals (best-fit flavor) scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - post_residual as f64).recip() * -2.0;
    score -= progress * 6.0;

    // Slight preference to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are nearly unusable (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (little waste) are preferred over loose fits.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins below mean residual (fill emptier-but-usable bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when it beats packing into tight space,
    // e.g., large item with poor fit everywhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 40.0 * tightness;
        if fitting_bins_count > 0 {
            score += 20.0; // open bins exist; new bin should lose by default
        }
    }

    // Lookahead: if next item would fit this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post residual, but strongly reward an exact match
    // where the next item fills the leftover space (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> big reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // Next item fits in the leftover: mild reward proportional to tightness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize wasted potential.
            score += 10.0 + 0.2 * diff;
        }
        // Slight preference to leave room proportional to next item size.
        score -= 0.05 * next_item_size as f64;
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins would leave very
    // large unusable leftovers (poor fits). Penalize opening new bins
    // mildly, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if next_item_size > 0 {
            (bin_capacity as i64 - item_size as i64 - next_item_size as i64).max(0) as f64
        } else {
            (bin_capacity as i64 - item_size as i64).max(0) as f64
        };
        // New bin is good only if it promises a tight two-item packing.
        score = 20.0 + poor_fit - 15.0 * (1.0 - progress);
    }

    // Reward tight fits generally (item nearly fills the bin).
    score -= 0.1 * item_size as f64;

    // Mild dispersion: with many open bins, prefer consolidating into
    // already-partial bins rather than spreading.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tight * tight;

    // Perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leaving awkward gaps next_item can't fill well.
            let gap = (post_residual - next_item_size) as f64;
            score += 0.25 * gap;
        } else {
            // next item won't fit here; small bonus for compact residual anyway.
            score -= 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new bins when open bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = mean_residual / bin_capacity as f64;
        score += 10.0 + 20.0 * pressure + 5.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // Mild preference for bins with below-average residual (consolidate emptier bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear reward for tight fits (small post_residual): quadratic coupling
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness;

    // Reward near-perfect fills even more (cubic coupling with progress)
    let perfect = 1.0 - (pr / cap).min(1.0);
    score -= 8.0 * perfect * perfect * perfect * (0.5 + progress);

    // Penalize post_residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else {
            // Reward bins whose leftover accommodates the next item
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly, unless open bins are congested
    if bin_residual == bin_capacity {
        let congestion = mean_residual / cap;
        score += 10.0 - 8.0 * congestion;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin is good for a stream of large items
        }
    }

    // Smooth coupling with mean residual: prefer bins close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * (dev / cap) * (dev / cap);

    // Progress-scaled pressure to fill bins tightly later in the stream
    score += 4.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (mod arithmetic on capacity)
    let frac = (item_size * 4) % bin_capacity; // distance to quarter-capacity classes
    score -= (bin_capacity as f64 - frac as f64).min(frac as f64) * 0.15;

    // Reward near-exact fits strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (>= smallest plausible size) can use
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Harmonic classes of post_residual via integer division thresholds
    let class = post_residual / 10;
    score += match class {
        0 => -40.0,
        1 => 0.0,
        2 => 10.0,
        3 => 20.0,
        _ => 30.0,
    };

    // Lookahead coupling: reward leaving post_residual that next item can consume
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere here anyway; slight bonus for using space
            score -= 10.0;
        }
    } else {
        // last item: minimize waste aggressively
        score += 0.0;
        score -= 25.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (tighter bins get priority)
    score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals too small for the smallest item (1) are pure waste,
    // but residuals in the "hard to fill" mid-range (1..=10) are penalized extra.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 - 2.0 * post_residual as f64; // small gaps are worst
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to bin residual (low wasted fraction).
    if bin_residual > 0 {
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_frac;
    }

    // Lookahead: if next item fits in post_residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item likely can't use this gap
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> prefer consolidating into existing bins;
    // penalize opening new bins when open_bins_count is already high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty growing with number of open bins and stream progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * progress;
        // But if no existing bin fits well (post_residual of others would be dead space),
        // opening a new bin is fine: soften when item is large.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward when open_bins_count is high (encourage reuse).
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins),
    // keeping looser bins for larger future items.
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual already does this).

    // 2-step lookahead: if the next item exactly matches post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size > 0 && post_residual > next_item_size {
            // Next item can also fit here afterwards: partial reward proportional to fit quality.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit in the residual: penalize dead space a bit.
            score += 8.0;
        }
    }

    // Relative residual vs mean: prefer bins with residual below the mean (tighter bins).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize leaving very small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: empty bins are competitive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; increases as stream progresses (less room to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress;
        // Opening a bin is more attractive when few bins fit (fragmentation pressure).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for very full bins early in the stream (keep flexibility), relaxed later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 15 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/tight fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // penalize dead space relative to smallest plausible item
        let dead = post_residual as f64;
        score += 0.15 * dead;
        if dead < 10.0 {
            score -= 12.0; // nearly perfect fit
        }
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0; // residual unusable by next item
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Scarcity: when few bins fit, prefer fitting existing bins over opening new
    if bin_residual < bin_capacity {
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
        // slight preference for existing bins vs new bin baseline
        score -= 3.0;
    }

    // Time horizon: early in stream, be more conservative (prefer filling existing bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Global state: many open bins with high mean residual -> discourage new bins
    if bin_residual == bin_capacity {
        // new-bin candidate baseline: its post_residual equals capacity - item_size
        let openness = (open_bins_count as f64).ln_1p();
        let avg_waste = (mean_residual - post_residual as f64).abs();
        score += 10.0 + 4.0 * openness + 0.05 * avg_waste;
        if progress > 0.8 && open_bins_count > 3 {
            score += 15.0; // late stream: avoid opening bins
        }
    } else {
        // favor bins with residual close to item (harmonic-style tightness)
        let tightness = (item_size as f64 / bin_residual as f64).min(1.0);
        score -= 8.0 * tightness;
    }

    // Penalize leaving residuals in awkward zone (11..=17) that few items fit
    if post_residual >= 11 && post_residual <= 17 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: quadratic penalty on wasted residual, stronger late in stream
    let waste = post_residual as f64 / cap;
    score += 60.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth saturating term
    score -= 40.0 * (1.0 - (waste * 3.0).min(1.0)) * (1.0 - progress * 0.5);

    // Penalize if post_residual cannot fit the next item (dead space), smooth via ratio
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr < nx {
            // dead space penalty scaled by how far short we fall
            let gap = (nx - pr) / cap;
            score += 90.0 * gap * (1.0 + progress);
            // bonus: exact or near fit for next item
            let near = (pr - nx).abs() / cap;
            score -= 50.0 * (-near * 20.0).exp() * 0.5;
        } else {
            // next item fits comfortably: mild reward
            let slack = (pr - nx) / cap;
            score -= 20.0 * (-slack * 8.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0 * (1.0 + 0.5 * progress);
    }

    // Penalize opening a new bin when open bins have plenty of residual capacity
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).max(1.0);
        score += 15.0 + 10.0 * (mean_residual / cap).max(0.0) * (1.0 + 0.5 * progress);
        score -= 5.0 * (-crowd / 8.0).exp();
    } else {
        // Mild reward for consolidating into bins with below-average residual (tighter bins)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev * (0.5 + progress);
    }

    // Smooth stream-progress coupling: late items prefer maximal packing density
    score -= 10.0 * progress * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: perfect fits (post_residual == 0) heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes via integer division of post_residual
    let class = post_residual / 10; // residual decade class
    score += match class {
        0 => -50.0,   // tiny residue: nearly perfect
        1 => 5.0,     // 10-19 residue
        2 => 0.0,     // 20-29 residue: usable by small items
        3 => 10.0,    // 30-39
        4 => 15.0,
        _ => 20.0,    // large residue: wasteful placement
    };

    // Reward when next item fits exactly into post_residual (lookahead harmony)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else if gap <= 10 {
            score -= 100.0;
        } else {
            score -= (10.0 / gap as f64) * 50.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residue: penalize proportionally
        score += 30.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins with residual below mean (tighten tight bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Modulo harmonic: residues that are multiples of common small item sizes are reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 25.0;
    }

    // Late in stream: consolidate, penalize new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 60.0 + progress * 120.0 + (open_bins_count as f64) * 2.0;
    }

    // Many open bins: favor filling existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
