pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits: leftover after next placement matters.
            let post2 = post_residual - next_item_size;
            score -= 20.0 - 0.3 * post2 as f64;
            if post2 == 0 {
                score -= 30.0;
            }
        } else {
            // Next item does not fit: penalize leaving a gap just below next_item_size.
            let gap = next_item_size - post_residual;
            score += 0.4 * gap as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when an open bin could fit, especially early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 20.0 * progress;
        if next_item_size > 0 && bin_residual > next_item_size {
            score -= 5.0;
        }
        // If no other bin fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for keeping many small open bins consolidated.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // dead space is post_residual smaller than the minimum plausible item (1..100 unknown, use item_size as proxy floor)
    if post_residual > 0 && post_residual < item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (item_size as f64));
    }

    // Lookahead: if next item fits into post_residual exactly or well, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins -> less critical which one is used; mild normalization
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins with residual close to mean residual (balance residuals for future flexibility)
    score += 0.4 * ((bin_residual as f64 - mean_residual).abs());

    // Early in stream: encourage filling bins fully (fewer bins long-run)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate handling: penalize opening a new bin unless current item nearly
    // fills it and no open bin fits well; make empty-bin unattractive by default.
    if bin_residual == bin_capacity {
        let base = 30.0
            + 10.0 * (open_bins_count as f64).sqrt()
            + 20.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        // If no open bin fits, opening is forced-ish: reduce penalty
        if fitting_bins_count == 0 {
            score = base * 0.4;
        } else {
            score = base;
        }
        // Large item near capacity makes a fresh bin reasonable
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 25.0;
        }
        return score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog_term = progress * progress * (1.0 - progress);
    score += 12.0 * pr_norm * pr_norm * (1.0 + prog_term);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let margin = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - margin * margin);
        } else {
            let over = (nxt - pr) / cap;
            score += 5.0 * over * over;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items (harmonic classes).
    // Residuals divisible into coarse classes: tiny slivers (<10) are nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Modulo-10 class: residuals that are multiples of 10 pair well with the 10..100 grid.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Integer-division thresholds: post_residual in [10,30] can host mid-size items.
    let pr_class = post_residual / 25; // 0,1,2,3,4 harmonic band
    score -= 3.0 * pr_class as f64;

    // Lookahead: reward bins that can also host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Bonus if the chained placement leaves a clean multiple-of-10 residual.
        let chained = post_residual - next_item_size;
        if chained % 10 == 0 {
            score -= 6.0;
        }
        if chained < 10 && chained > 0 {
            score += 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize proportionally.
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit (high post_residual means poor fit here).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; adjust with stream context.
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slightly prefer new bins late in the stream when mean residual is fragmented.
        score += 5.0 + 10.0 * (1.0 - progress);
        if mean_residual > 40.0 {
            // Plenty of slack spread around: reuse existing bins instead.
            score += 15.0;
        }
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is the only option.
            score -= 100.0;
        }
    } else {
        // Mild bonus for reusing bins, scaled by how full the bin already is.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * used;
    }

    // Spread penalty: prefer bins below the mean residual (consolidate fullness).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in (0, 10] are unusable for future items
    // (min item size is 10 under the classic regime; scale for unknown dists).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space for the known next item
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += desperation + mean_residual * 0.1;
        if post_residual == bin_capacity {
            score -= 10.0; // empty new bin keeps max flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxs {
            // next item fits exactly or nearly: strong reward for tight match
            let match_gap = pr - nxs;
            score -= 14.0 * (1.0 - match_gap / bin_capacity as f64);
            // exact match bonus
            if match_gap < 0.5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit: penalize leaving residual too small to be useful
            let waste_ratio = pr / nxs;
            score += 6.0 * (1.0 - waste_ratio);
        }
    } else {
        // last item: minimize post residual aggressively
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.6 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly prefer using the only bin that fits (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new-bin candidate: score it like its post residual, but penalize if open bins exist
        if open_bins_count > 0 {
            score += 8.0;
            // allow new bin only if next item is huge relative to residual elsewhere
            if next_item_size > 0 && (next_item_size as f64) > 0.7 * (bin_capacity as f64) {
                score -= 6.0;
            }
        }
        // new empty bin keeps full flexibility for future items
        score -= 0.3 * (post_residual as f64);
    }

    // Early in stream: be more willing to open bins / keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score -= 2.0 * (1.0 - progress / 0.3) * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer tighter fits overall (smaller post residual relative to item)
    score += 0.25 * (item_size as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect or near-perfect fit gets strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: penalize if next item could have fit in post_residual
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            // dead space blocking the next item
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual as u32 >= next_item_size {
            // reward leaving room for the next item
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin, reduced when open bins are full-ish
        let mut new_bin_cost = 40.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 {
            new_bin_cost -= 15.0 * (fragmentation / bin_capacity as f64).min(1.0);
        } else {
            new_bin_cost = -100.0; // must open first bin
        }
        score += new_bin_cost;
    }

    // Penalize bins whose residual deviates far below mean (fragmented leftovers)
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Slight preference for filling more-full bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, mildly convex in x
    let mut score = pr + 12.0 * x * x * cap;

    // Non-linear coupling of post residual with stream progress:
    // later in the stream, tight fits (small post residual) matter more
    let tight = (-x).exp();
    score -= 30.0 * progress * tight * pr;

    // Penalize large dead space increasingly with progress
    score += 25.0 * progress * x * x * cap;

    // Lookahead synergy: reward post residual that fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 20.0 * fit_quality * (1.0 - progress);
        } else {
            // post residual too small for next item: penalize proportionally
            score += 15.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (keep large residuals aggregated, avoid spreading slack)
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * (1.0 - progress);

    // New-bin candidate should rarely win unless open bins are nearly full
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo classes
    let class = post_residual % 10;
    let div = post_residual / 10;

    // Reward small, "usable" post-residual classes (multiples of common item sizes)
    match class {
        0 => score -= 8.0,          // perfect multiple of 10: highly reusable
        1 => score += 3.0,          // dead space of 1 is worst
        2 | 3 => score += 2.0,      // small dead space
        4 | 5 | 6 => score -= 2.0,  // medium residual still fits small items
        7 | 8 | 9 => score += 1.0,  // awkward residual
        _ => {}
    }

    // Reward deep fill (low div means bin nearly full)
    score += div as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // harmonic class match: next item size class equals residual class
            if next_item_size % 10 == class {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to waste potential
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // fit is terrible. Penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 10.0;
        // early in stream, new bins are cheap-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 6.0;
        // if many bins open and mean residual high, prefer filling existing bins
        score += (open_bins_count as f64).sqrt() * 1.5;
        score += mean_residual * 0.05;
    }

    // Tight-fit bonus: item fills bin almost exactly
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Slight preference for bins with below-average residual (keep balance)
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item can use are heavily penalized.
    // A residual gap is "dead" if smaller than the next item AND smaller than a plausible
    // minimum item size (assume small items exist down to ~10; below that it's pure waste).
    let min_plausible = 10u32;
    if post_residual < next_item_size && post_residual < min_plausible * 2 {
        score += 60.0; // unusable sliver right now and hard to fill later
    } else if post_residual < next_item_size {
        score += 25.0; // can't take the lookahead item, but small items may fit
    }

    // Reward tight fits (post_residual near zero) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin open
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // with few open bins, tolerate opening a new one (penalize new-bin candidate less).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * (mean_residual / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size,
    // which is large; give it a mild extra penalty so it only wins when fits are awful,
    // but subtract open-bin pressure so it becomes attractive when bins are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 - pressure * 4.0;
    }

    // Slight lookahead coupling: if this bin can also host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but weight it by fill ratio
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score = post_residual as f64 * (1.15 - 0.3 * fill);

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize dead space too small for the next item
        if post_residual < next_item_size.min(10) {
            score += 40.0;
        }
    }

    // Compare against mean residual: bins with residual far below mean are scarcer, prefer filling them
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer compacting into fewer bins when many are open
    score -= open_bins_count as f64 * 2.0;

    // Slight early-stream bias toward keeping bins open for flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        score = if bad_fit { 30.0 + post_residual as f64 * 0.5 } else { 500.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // post_residual can host the next item: reward, scaled by how snugly it fits.
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
            score -= 3.0 * snug;
        } else {
            // Dead space for the next item: penalize proportionally to wasted fraction.
            let waste = (next_item_size as f64 - post_residual as f64) / cap;
            score += 4.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current open bins are mostly full or none fit well.
        // Penalize slightly so we only open when genuinely better than poor fits.
        score += 5.0;
        // If many open bins exist with large mean residual, opening new bins is worse.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > (2.0 * item_size as f64) {
            score += 3.0;
        }
        // Early in the stream, allow new bins more freely to build diversity.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 zone (unusable for items >= 10... but sizes 1..100 allowed).
    if post_residual > 0 && post_residual < 5 {
        score += 2.5;
    }

    // Prefer bins whose residual is already below average (they are the "smaller" bins;
    // filling them consolidates space). Slight pull toward below-mean-residual bins.
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Dead-space penalty grows with stream progress: late in the stream,
    // wasted residual matters more since fewer items remain to fill it.
    let dead = (pr / cap).powi(2);
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward near-perfect fills smoothly.
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness.powi(3);

    // Lookahead coupling: if the next item fits the post residual, reward;
    // smooth interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let compat = 1.0 - gap / cap;
        score -= 15.0 * compat.max(0.0).powi(2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing ones (penalize new bins).
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild pull toward bins with residuals close to the item (smooth coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * fit_gap.powi(2);

    // Mean-residual context: if this bin is far from the mean, slight penalty
    // to keep residual distribution balanced.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev.powi(2) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Base: reward tight fits (small post_residual) ---
    // Harmonic class of post_residual: capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Dead-space penalty: residuals that are too small to hold any
    // plausible future item are almost worthless. Classify post_residual
    // into harmonic bands via integer division thresholds.
    if post_residual == 0 {
        // Perfect fill: strongly favored.
        score -= 60.0;
    } else if post_residual <= 10 {
        // Nearly dead space: heavy penalty scaled by how dead it is.
        score += (11 - post_residual) as f64 * 2.5;
    } else if post_residual <= 20 {
        // Marginal class: mild penalty.
        score += 6.0;
    } else if post_residual <= 33 {
        // "Third-class" residual: can host small/medium items.
        score -= 4.0;
    } else if post_residual <= 50 {
        // "Half-class": quite reusable.
        score -= 10.0;
    } else {
        // Large residual: fine but less urgent to fill now.
        score -= 6.0;
    }

    // --- Lookahead: does post_residual still fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus for leaving room for the lookahead item.
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 + (slack_after_next as f64).min(30.0) * 0.15;
        } else {
            // Penalize blocking the next item, worse if the gap is small
            // (near-miss = wasted potential).
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 + miss * 0.1;
        }
        // Harmonic coupling: if next item would EXACTLY fill post_residual,
        // this is a chain of perfect fits - big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer zero-waste placements.
        score -= 20.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // If this is the only fitting bin and opening a new bin would
        // strand this residual, favor using it - unless the fit is awful.
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.6 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin baseline. It should win only when no open bin offers
        // a good fit. Give it a mid-range score so tight fits beat it,
        // but terrible fits (large post_residual on open bins) lose to it.
        score = cap * 0.55;
        // Early in the stream, opening bins is cheaper (more future items
        // to distribute); later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 12.0;
        // If many bins are open already, discourage opening more.
        score += (open_bins_count as f64).min(20.0) * 1.2;
        // Large incoming items favor fresh bins.
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual deviates
    // from the mean in useful directions (fill below-average residuals
    // first to consolidate small holes). ---
    let dev = post - mean_residual;
    if dev < 0.0 {
        score += dev * 0.05; // below-mean residual: slight penalty (less useful hole)
    } else {
        score -= dev * 0.05; // above-mean residual: slight reward
    }

    // --- Modulo/harmonic tie-breaker on post_residual classes ---
    // Residuals divisible into clean capacity fractions are more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0) {
        score -= 3.0;
    }
    // Odd, awkward residuals (prime-ish gaps like 7, 13, 17..) are dead ends.
    if pr > 0 && pr < 30 && pr % 2 == 1 && pr % 5 != 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..10 band) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Gap unusable by the lookahead item: this residual likely becomes permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tight fit relative to residual: favor bins where item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins;
    // with few bins open, opening a new bin (large residual) is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins are fragmented (high mean residual spread)
    // or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - 2.0 * fragmentation - pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin leaves room for similar/larger next item
        }
    }

    // Slight preference for bins whose residual is close to mean (keep residuals uniform).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: item perfectly fills the bin
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when the next item fits the post_residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here; mildly reward tight chains
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to the next item: penalize proportionally
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating small unusable residual slivers (below typical min item size 1..100
    // treat residual < 10 as dead space, scaled)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins already below-average fullness when
    // the fit is loose, prefer above-average (tighter) bins when fit is tight
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when open bins score badly
        score += 200.0;
        // If no open bin fits at all, opening a new bin is the only option: cancel penalty
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Early in the stream, allow new bins more freely (cheap capacity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * (1.0 - progress);
        // If the next item is huge, keeping current residuals intact may help
        if next_item_size > 60 {
            score -= 50.0;
        }
    }

    // Slight preference for bins whose residual was close to the item (tight fit overall)
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual dead space, scaled by how "unusable" it is
    let dead = post_residual as f64;
    let next_fits = next_item_size as f64;
    if next_item_size > 0 && (next_item_size as f64) > dead {
        score += (next_fits - dead) * 0.35; // next item can't use this bin
    } else if next_item_size > 0 {
        score -= 6.0; // lookahead item fits here after placement
    }

    // Reward tight fits: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidation into existing bins
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += (bin_residual as f64) * 0.05 * pressure / (1.0 + tightness);

    // Global residual alignment: prefer bins whose residual is near the mean
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += dev * 0.08;

    // Time horizon: late in the stream, be greedier about filling bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * tightness;
    score += progress * 3.0 * dead * 0.05;

    // New-bin candidate: make it moderately attractive only when item is large
    // relative to all open residuals (avoids fragmenting early)
    if bin_residual == bin_capacity {
        let crowded = fitting_bins_count == 0;
        let base = 20.0 - 10.0 * progress;
        if crowded { score -= 30.0; } else { score += base; }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 20.0;
        } else if diff > 0 {
            let d = diff as f64 / bin_capacity as f64;
            score -= 6.0 * (1.0 - d) * (1.0 - d);
        } else {
            // next item cannot fit here; slight penalty proportional to wasted space
            score += 4.0 * (-diff as f64 / bin_capacity as f64);
        }
    }

    // Penalize bins whose residual deviates from the mean residual (fragmentation control).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // Mild penalty when many bins are open (prefer consolidating into fewer bins).
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate handling: prefer existing bins unless post residual is very poor.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover falls into
    // "nice" classes (multiples of common item sizes) are more reusable ---
    let class_size: u32 = 10;
    let post_class = post_residual / class_size;      // integer division class
    let post_mod = post_residual % class_size;        // remainder within class

    // Reward post-residuals that are class-aligned (waste = 0 mod class)
    score -= (class_size as f64 - post_mod as f64) * 0.15;

    // Strong reward for perfect or near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_mod == 0 {
        score -= 20.0 * post_class as f64;
    }

    // --- Lookahead coupling: does next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward, more so if post residual is class-matched
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.1;
            if (post_residual - next_item_size) % class_size == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit: penalize creating dead space
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the fit elsewhere would be very poor. Penalize mildly by default.
        score += 15.0;
        if open_bins_count == 0 {
            score -= 50.0; // must open when nothing open
        }
        // Late in stream, opening fresh bins is fine (consolidation unlikely)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 {
            score -= 8.0;
        }
        // If next item is large, a fresh bin keeps flexibility
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // --- Prefer filling bins below mean residual (tighter bins first) ---
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // --- Modulo-threshold penalty on wasted capacity fractions ---
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    if waste_frac > 0.5 {
        score += waste_frac * 10.0; // large holes are bad
    } else if waste_frac > 0.25 {
        score += waste_frac * 4.0;
    }

    // Slight tie-breaker toward fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that can never be used by the lookahead item.
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        // Extra harsh penalty for tiny unusable gaps (classic fragmentation).
        if post_residual < 10 {
            score += 25.0;
        }
    } else if next_item_size > 0 && post_residual == 0 {
        // Perfect closure of the bin is excellent.
        score -= 40.0;
    } else if next_item_size > 0 {
        // Residual still usable by the next item: reward a good fit for it.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack * 0.15;
    }

    // Prefer filling already-open bins: pressure against opening new bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Discourage leaving residuals near the awkward mid-range (hard to fill later).
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Slight early-stream conservatism: keep bins mergeable early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Mild pull toward bins with residuals close to this bin's post state.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // New-bin candidate: only attractive when no open bin offers a decent fit;
    // otherwise penalize so we reuse open capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: strongly reward when next item fits the
    // post residual exactly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well the next item nests.
            if slack <= 10.0 {
                score -= 20.0 - slack * 1.5;
            } else {
                score -= (20.0 - slack * 0.5).max(-15.0);
            }
        } else {
            // Next item does NOT fit after this placement: penalize leaving
            // a residual that is unusable for the known next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(30.0) * 0.8;
        }
    }

    // Penalize creating dead space relative to the mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual + 15.0 {
        score += (pr - mean_residual) * 0.4;
    } else if pr < mean_residual - 15.0 {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins already open
        // (amortized) or early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 45.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin lets both current and next items coexist well.
            if bin_capacity.saturating_sub(item_size) >= next_item_size {
                new_bin_score -= 25.0;
            }
        }
        if open_bins_count > 8 {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    // Mild tie-breaking toward fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect/near-perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space,
            // scaled by how much of the bin is wasted.
            let waste = post_residual as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits or many bins are already open.
    if bin_residual == bin_capacity {
        // Base penalty for fragmentation (opening new bins).
        score += 40.0;
        // But if the item is large and open bins are crowded, ease up.
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score -= 25.0 * crowded;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If no other bin can even fit the item, opening is necessary:
        // handled implicitly since fitting bins would score high otherwise.
    }

    // Penalize bins whose residual is far above the mean (avoid hoarding
    // space in already-large bins when tighter options exist).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Mild preference for using bins with larger residuals when few bins
    // are open (keep small residuals available for small future items).
    if open_bins_count <= 3 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit) with non-linear saturation.
    let mut score = (pr / cap).powi(2) * cap;

    // Dead-space penalty: very small leftovers are wasted; penalize quadratically
    // when below a smooth threshold tied to half the smallest conceivable item.
    let dead = (0.5 * cap - pr).max(0.0) / cap;
    score -= 6.0 * dead * dead * cap; // reward leaving usable mid-range residual

    // Perfect-fill reward (smooth, no piecewise): strongly favor post_residual near 0.
    score -= 10.0 * (-pr / (0.15 * cap)).exp();

    // Stream-progress coupling: later in the stream, tighten preference for tight fits
    // (fewer bins matter more), interact progress with post-residual polynomially.
    score += progress * (pr / cap) * (pr / cap) * 8.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 8.0 * (-diff / (0.1 * cap)).exp();
        // Penalize post-residual that can't fit the next item at all.
        if pr < nx {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline scaled with stream progress and
    // number of open bins (discourage bin proliferation early, allow it when
    // existing residuals are poor).
    if bin_residual == bin_capacity && post_residual == bin_capacity - item_size {
        score = 0.5 * cap + 3.0 * (open_bins_count as f64).sqrt() - 0.3 * mean_residual
                - 10.0 * (1.0 - progress);
    }

    // Mild preference to balance residuals across open bins.
    score += ((pr - mean_residual) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small integers) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward tight fits strongly.
    score -= 40.0 * (1.0 - (post_residual as f64) / cap);

    // Harmonic class bonus: post_residual divisible by small integers
    // leaves room for future small items -> reward.
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 8.0; }
        // Dead-zone penalty: residual in (0,10) is nearly unusable.
        if pr < 10 { score += 35.0; }
        else if pr < 20 { score += 10.0; }
    } else {
        // Perfect fill: excellent outcome.
        score -= 60.0;
    }

    // Integer-division threshold on next_item_size: if the next item
    // fits in post_residual, reward this placement (lookahead chaining).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + 10.0 * ((pr / next_item_size.max(1)) as f64).min(3.0);
        } else {
            // Next item won't fit here; penalize wasting this bin's space.
            score += 8.0 * (1.0 - (pr as f64) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= (open_bins_count as f64) * (1.0 - (post_residual as f64) / cap);

    // Slight preference for bins below mean residual (balance avoidance
    // of many half-empty bins) early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - progress);
    }

    // New-bin candidate: make it unattractive unless item is large and
    // no good harmonic fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gap: likely unusable soon, moderate penalty.
        score += 15.0;
    } else if post_residual >= 40 {
        // Large usable residual is valuable -> reward.
        score -= 12.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Exact match with lookahead item: reserve-free placement is great.
    if post_residual == next_item_size && next_item_size > 0 {
        score -= 30.0;
    }
    // Penalize leaving a gap that exactly tempts the next item only if it
    // would strand us; otherwise slight reward for chain fits.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if post_residual < dead_threshold {
            score -= 20.0; // still better than a fresh bin usually
        }
    }

    // Open-bin pressure: many open bins -> discourage opening new ones and
    // encourage consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow early stream or
        // genuinely bad fits (large dead-space creation elsewhere) to win.
        score += 20.0 + 8.0 * pressure - 10.0 * progress;
        // If no open bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Placing into an existing bin relieves pressure slightly.
        score -= 2.0 * pressure;
    }

    // Prefer bins with residual far from the mean (restore balance) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins as stream progresses.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: perfect match with next item
    if next_item_size > 0 {
        let match_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly or nearly: big reward
            if match_diff == 0.0 {
                score -= 500.0;
            } else if match_diff <= 10.0 {
                score -= 150.0 / match_diff;
            } else {
                score -= 50.0 / match_diff;
            }
        } else {
            // Next item does NOT fit in the leftover: penalize wasted space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare residual against mean residual of open bins
    if mean_residual > 0.0 {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    // Many open bins: discourage spreading, prefer tight fills
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Lookahead: penalize if next item fits exactly into post_residual (we'd waste it),
    // reward if post_residual is useless for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score += 30.0; // perfect future use of this residual, keep it? no: placing here kills it
        } else if next_item_size <= post_residual {
            score += 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score -= 6.0; // residual useless for next item -> dump current item here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many fitting bins: slight penalty for using a scarce-fit bin too eagerly.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Time horizon: early in stream, be picky (penalize waste more); late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * (1.0 - progress);

    // Global residual pressure: if mean residual is high, prefer filling existing bins.
    score -= 10.0 * (mean_residual / bin_capacity as f64 - 0.5);

    // Open bins pressure: many open bins -> favor consolidating into existing ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly * (1.0 + progress);

    // reward tight fits (small post_residual), stronger later in stream
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // discourage scattering across many open bins when residuals are large
    let spread = (mean_residual - pr).abs() / cap;
    score += 5.0 * spread * spread;

    // new-bin candidate: mildly penalized early, competitive late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues divisible by common item sizes (10/20/25/50)
    // are more reusable; odd/dead residues are penalized.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit is ideal
    } else if pr % 50 == 0 || pr % 25 == 0 {
        18.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        4.0
    } else {
        -6.0 // dead space
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / pr as f64;
            score -= 20.0 * frac;
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0; // harmonic divisibility
            }
        } else {
            score += 6.0; // next item cannot follow here
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it is only chosen when open bins are poor fits,
    // unless the item is large relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let fill = item_size as f64 / bin_capacity as f64;
        // large items justify new bins more when open bins are fragmented
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += base_penalty - 25.0 * fill * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Tightness reward: prefer bins where the item fills a large share of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Early in stream: prefer consolidating into fewer bins (mild new-bin penalty growth).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Penalize bins far from mean residual (outliers) to keep bin family homogeneous.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A gap is "dead" if it is smaller than the smallest plausible item
    // (or smaller than the lookahead item). Penalize it super-linearly.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 40.0 + 0.5 * (item_size as f64);
    } else if post_residual < dead_threshold {
        // Unusable small gap: penalize sharply, worse the closer we are
        // to a "just barely wasted" gap.
        let waste_ratio = 1.0 - (post_residual as f64 / dead_threshold as f64);
        score += 25.0 * waste_ratio + 10.0;
    } else {
        // Usable gap: mild reward proportional to how much room remains
        // relative to capacity (encourages balanced residual spread).
        score -= 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;
    }

    // --- Tightness reward: the fraction of the bin consumed by this item ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // --- Open-bin pressure: discourage opening new bins when many are open ---
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // New bin: baseline cost of consuming a fresh bin, modulated by
        // how many bins are already open and how poor the alternatives look.
        score += 30.0 + 2.0 * (open_bins_count as f64);
        // If this bin is the only option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If the next item is large and current mean residual is small,
        // a fresh bin is more attractive.
        if next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Using an existing bin slightly relieves open-bin pressure.
        score -= 1.0;
        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // --- Lookahead coupling: reward leaving a gap that fits the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    }
    // Penalize leaving a gap that almost fits the next item (teasing gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // --- Mild stream-progression calibration: as the stream advances,
    // consolidation into existing bins becomes more valuable. ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left after it
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next <= 10 {
            score -= 35.0 - slack_after_next as f64 * 2.0;
        } else {
            // Next item fits but leaves a big hole; mild reward decaying with slack
            score -= 10.0 - (slack_after_next.min(50) as f64) * 0.1;
        }
    }
    // Next item will NOT fit here: this residual is likely dead space
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (< 10) that waste space
    if post_residual < 10 {
        score += 8.0;
    }

    // Early in stream: be more conservative, prefer opening fresh bins less
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially if below the minimum item size (unusable).
    if post_residual < 10 {
        score -= 15.0; // perfect/near-perfect closure
    } else if post_residual < 20 {
        score -= 6.0;
    } else {
        score += 0.05 * post_residual as f64;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain fill
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (high mean residual spread or item barely fits anywhere).
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (mean_residual / bin_capacity as f64).max(0.0)
        } else {
            0.0
        };
        // Early stream: new bins cheap; late stream: prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 18.0 * desperation - 10.0 * (1.0 - progress);
        // Penalize opening new bins when many are already open with slack.
        score += 0.6 * open_bins_count as f64;
    }

    // Mild consolidation pressure toward bins below mean residual (filler bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Time horizon: late in the stream, reward tighter fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with non-linear shrinkage so small
    // residuals are strongly favored (dead-space avoidance).
    let mut score = 100.0 * norm_pr.powf(1.5 + 0.5 * progress);

    // Smooth interaction: post_residual coupled with stream progress —
    // late in the stream, tight packing matters more.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead bonus: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).abs() as f64) / cap;
        score -= 12.0 * fits_next * (1.0 - gap).max(0.0);
        // Penalize near-miss residuals that almost fit the next item (smooth).
        let near = (-((pr - next_item_size as f64) / 10.0)).exp();
        score += 6.0 * near * (1.0 - fits_next);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Prefer bins whose residual is close to the mean (smooth homogenization).
    score += 4.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference for fuller bins overall (item_size coupling).
    score -= 0.05 * item_size as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which quarter/third of the bin it falls in
    let q = (post_residual * 4) / bin_capacity; // 0..3 class of leftover
    let third = (post_residual * 3) / bin_capacity;

    // Dead-space penalties by harmonic class
    match q {
        0 => score += 6.0,               // tiny leftover: nearly perfect fit
        1 => score -= 4.0,               // small leftover: still usable for small items
        2 => score -= 1.0,
        _ => score += 2.0,               // huge leftover means item barely fits... wasteful
    }
    if third == 0 { score -= 3.0; }      // leftover < 1/3 capacity: class "closed-ish"

    // Modulo classes of post_residual w.r.t. common small item sizes
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 { score -= 2.5; break; }
        }
    }

    // Lookahead: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or modular match with next item is gold
            if post_residual == next_item_size { score -= 12.0; }
            else if post_residual % next_item_size == 0 { score -= 6.0; }
            else { score -= 3.0; }
        } else {
            // next item won't fit here; penalize proportionally to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).max(1.0);
        let mean_fill = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        score = cap * 0.55 + mean_fill * 20.0 - crowded.min(10.0);
        if fitting_bins_count == 0 { score -= 15.0; }
    }

    // Early stream: be slightly greedy toward tight fits; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.05;
    score += progress * 2.0 * (post_residual as f64 / cap);

    // Prefer bins whose residual is near the mean (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are "dead space" — penalize them heavily with a non-linear ramp.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect or near-perfect fills are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here: leftover becomes dead space sooner.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins; discourage opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If no existing bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Favor tighter existing bins (smaller residual before placement).
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // Bins below mean residual are "loose" — slight penalty to spread usage.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: next item exactly fills the bin after this placement.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness of post_residual to the lookahead item.
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // exact two-item fill: bin closed perfectly
        }
        // Penalize leaving a residual that nothing useful can fill later.
        if post_residual > 0 && next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.15 * dead; // slightly reward tighter-than-average bins
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large post_residual waste) or many bins are already open.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.2;
        if open_bins_count > 0 {
            score += 10.0;
        }
        if fitting_bins_count > 0 && waste < 0.5 * bin_capacity as f64 {
            score += 30.0; // discourage new bin when a decent fit exists
        }
    }

    // Mild late-stream tightening: pack harder as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose post-residual can host the lookahead item (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 + 10.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        let dead = (post_residual as f64).min(next_item_size as f64 - 1.0);
        score += 0.3 * dead;
    }

    // Reward near-exact fills: waste below a small threshold is very valuable.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless the current item is large
    // relative to the empty residual (fresh-bin exploitation for big items).
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 35.0 * big;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight preference toward bins tighter than average (keeps large residuals flexible).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse classes of size 10.
    // Wasted space in the lowest class (0..10) is nearly unrecoverable -> reward it heavily.
    let post_class = post_residual / 10;
    match post_class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 8.0,                // small gap, still useful
        2 | 3 => { score += 2.0; }        // medium gaps: neutral/slight penalty
        _ => { score += 6.0; }            // large gap: bin stays too empty
    }

    // Exact harmonic match: post_residual divisible into next item's needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;                // perfect lookahead fit
        } else if next_item_size <= post_residual {
            // how many times next item fits into the gap (integer division class)
            let k = post_residual / next_item_size;
            score -= 10.0 * (k.min(3) as f64);
        } else {
            // gap too small for the next item: dead space risk scaled by how close it is
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 20.0).min(12.0);
        }
    }

    // Modulo-style coupling: residual congruence classes mod 10.
    // Gaps congruent to common item sizes (10,20,30) are more reusable.
    let rmod = post_residual % 10;
    if rmod == 0 {
        score -= 6.0;
    } else if rmod >= 5 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the fit here is terrible
    // or when the stream is early and we want parallel capacity.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 55.0;
        // but a fresh bin is attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // or when existing bins would leave a bad gap anyway
        if post_class >= 3 {
            score -= 20.0;
        }
        // if next item is huge, a fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already below-average residual (consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Many open bins: push toward closing them out (tighter fills rewarded).
    if open_bins_count > 8 {
        score -= 5.0 * post_class.min(2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item
    // (or below the minimum item size) are "unusable" waste — penalize hard.
    let min_item = 10u32;
    let dead_threshold = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < dead_threshold && post_residual > 0 {
        // Fully dead gap: treat as if the space were lost entirely.
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }
    if post_residual < min_item && post_residual > 0 {
        score += 40.0; // below minimum item size: absolute dead space
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward using a bin whose residual was already small (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new ones; with few bins, new-bin option stays attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above good fits, reduced
        // when few bins are open (opening is cheap early on).
        score = 55.0 + pressure * 12.0 + (item_size as f64) * 0.1;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        // Existing bin: mild penalty growing with open-bin count is already
        // captured by new-bin baseline; add tiny mean-residual coupling to
        // prefer bins that deviate from the mean (more extreme residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chaining of next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Perfect fill now: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Penalize leaving tiny unusable dead space (nothing can fit, size>=1)
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates from mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in stream: tighten packing, prefer fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Never prefer a brand-new bin unless existing fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space relative to what the next item needs.
            let dead = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.25 * dead;
        }
    }

    // Last-chance: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean (fill low-residual bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // later, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress;

    // New-bin candidate: penalize opening a new bin unless it's early or nothing fits well.
    if bin_residual == bin_capacity {
        let early_bias = 30.0 * (1.0 - progress);
        let poor_fit_elsewhere = if fitting_bins_count <= 1 { 0.0 } else { 25.0 };
        score += 15.0 + early_bias + poor_fit_elsewhere;
        // If next item is large and current item is small, a fresh bin is okay.
        if next_item_size > 60 && item_size < 40 {
            score -= 30.0;
        }
    }

    // Slight reward for placing larger items into emptier bins.
    score -= 0.05 * item_size as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress) - 12.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 18.0 * (1.0 - pr_norm).powi(3) * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (nxt - pr) / cap;
        } else {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap));
        }
    } else {
        score += 8.0 * pr_norm; // last item: prefer fullest packing
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer balanced residuals early, extremes late
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress) - 5.0 * dev * progress;

    // New-bin candidate handling: penalize slightly so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-based dead-space classification) ---
    // Residuals divisible by common item classes are more reusable.
    let pr = post_residual;
    let mut reusability = 0.0f64;
    if pr == 0 {
        reusability += 60.0; // perfect fit, no dead space
    } else {
        if pr % 10 == 0 { reusability += 14.0; }
        if pr % 20 == 0 { reusability += 8.0; }
        if pr % 25 == 0 { reusability += 6.0; }
        if pr % 50 == 0 { reusability += 6.0; }
        // small residuals (<10) are near-dead space
        if pr < 10 { reusability -= 18.0; }
        else if pr < 20 { reusability -= 8.0; }
    }

    // --- Tightness: reward filling a large fraction of the bin's current residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- Lookahead (k=2): reward leaving exactly the space the next item needs ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // perfect chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; residual becomes harder to use
            score += 6.0;
        }
    }

    // --- Penalize bins far from the mean residual (keep bin states homogeneous) ---
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // --- New-bin candidate: moderate score so it's chosen only when fits are poor ---
    if bin_residual == bin_capacity {
        // base cost of opening a bin; scales down as stream progresses / few open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = 1.0 / (1.0 + open_bins_count as f64);
        score = 55.0 + 20.0 * (1.0 - progress) - 10.0 * open_pressure;
        // if the only alternative is a very loose fit elsewhere, new bin looks better;
        // if it's a last chance elsewhere, that bin wins via its -40 bonus.
    }

    score -= reusability;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can fill
    // are heavily penalized. Gaps >= 10 are potentially usable; below that they
    // are pure waste (and even small gaps 1..10 are near-unusable for the
    // typical item range).
    if post_residual > 0 {
        if post_residual < 10 {
            // Completely unusable sliver: strong penalty.
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else if post_residual < 25 {
            // Small gap: only fillable by very small items; penalize moderately.
            score += 15.0;
        }
    } else {
        // Perfect fit: big reward.
        score -= 30.0;
    }

    // Reward when the next item exactly fills the resulting gap (lookahead).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item still fits after this placement.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing
    // ones (penalize low fill usage less); when few bins are open, allow
    // spreading. Penalize choosing a fresh bin when open bins exist and fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins could still absorb
        // items and the stream is early (more future items to pack).
        let pressure = 10.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        score += pressure;
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    } else {
        // Existing bin: reward bins whose residual is close to mean residual
        // balance, but prefer tighter bins overall.
        score -= 0.5 * open_bins_count as f64;
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight preference for bins with small pre-residual (tighter bins).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> very strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward if bin can also fit the next item after this one (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
    }

    // Penalize dead space: post_residual too small to ever fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize leaving a residual that fits neither next item nor is near-mean useful
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize it moderately so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if no other bin leaves a good residual, new bin is attractive via base residual
    }

    // Prefer bins tighter than the mean residual (filling fuller bins first)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early in stream, slightly prefer compacting into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual penalizes large leftover space more aggressively.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward placements whose leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open (early stream) or the fit would be very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 15.0 + 25.0 * progress;
        // Large items relative to capacity benefit from a fresh bin.
        if (item_size as f64) > 0.6 * bin_capacity as f64 && open_bins_count > 0 {
            penalty -= 20.0;
        }
        // If no other bin fits well (post_residual small in other bins), allow new bin.
        if item_size >= bin_residual && item_size >= 70 {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Global state coupling: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 && (mean_residual as f64) < 0.3 * bin_capacity as f64 {
        score -= 4.0;
    }

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 40.0 * poly;

    // Penalize dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let gate = 1.0 - (-pr / (next_item_size as f64 + 1.0)).exp();
        score += 15.0 * gap * gate;
    } else {
        score += 10.0 * norm_pr * progress;
    }

    // Reward last-chance bins (only one fitting bin) with smooth decay
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins tighter than average
    score += 5.0 * (pr - mean_residual) / cap;

    // Slightly discourage opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that commonly pair with
    // typical item sizes are "usable"; odd/tiny residues are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Dead-space penalty: small post_residual that cannot host next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Exact-fit bonus: next item fills this bin completely
            if pr == next_item_size {
                score -= 30.0;
            } else {
                score -= 8.0;
                // Harmonic bonus: post_residual in coarse classes of 10
                // (divisible residues pair well with a wide item range)
                if pr % 10 == 0 {
                    score -= 6.0;
                }
                // Next item leaves another harmonic residue
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 {
                    score -= 5.0;
                }
            }
        } else {
            // Next item cannot use this bin's residue: penalize dead space
            score += 12.0;
            if pr < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin
        score += 20.0;
        // Cheaper to open a new bin early when stream is young
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If item is large and leaves harmonic residue in fresh bin, ok
        if item_size % 10 == 0 {
            score -= 5.0;
        }
        // Avoid new bin if mean residual across open bins is large
        score += (mean_residual / cap) * 20.0;
    }

    // Prefer bins whose residual is already fragmented (use them up)
    if bin_residual != bin_capacity && post_residual > 0 {
        score -= 3.0;
    }

    // Mild pressure to close bins with many open bins active
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (sizes >= 1), so penalize them harshly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate handling: opening a fresh bin should only win when
    // the fit into existing bins is poor. Make the empty bin moderately
    // attractive by default but let dead-space penalties / last-chance
    // bonuses of real bins dominate.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 2.0;
        // Lookahead: if next item is large, a fresh bin is less useful.
        if next_item_size > 0 {
            score += next_item_size as f64 * 0.15;
        }
    } else {
        // Reward bins whose residual stays compatible with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
        // Slight preference for tighter bins (below-mean residual).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can be placed here afterward -> strong reward
            score -= 60.0 - 1.5 * diff;
            if diff == 0.0 {
                score -= 200.0; // perfect 2-step chain
            }
        } else {
            // Post-residual too small for next item: penalize wasted space relative to next item
            score += 0.5 * (nxt - post_residual as f64).min(30.0);
        }
    }

    // Compare post_residual against mean residual: avoid making bin worse than average
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 150.0;
        // If few fitting bins and item is large, opening new bin is more attractive
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if fitting_bins_count == 1 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidation into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 100.0 * progress;
        // Large items fit perfectly in a fresh bin
        if item_size >= 80 {
            score -= 40.0;
        }
    }

    // Mild preference for filling fuller bins (smaller residual before placement)
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).recip() * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space penalty grows quadratically).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Lookahead synergy: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item fills the bin almost completely afterward.
        let after_next = post_residual as f64 - next_item_size as f64;
        score -= 10.0 * (1.0 - after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a gap just below the next item size (wasted dead space).
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score += 8.0 + gap.abs();
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // opening a new bin is fine when no good alternative exists
        }
        // Later in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // leaving large residuals in other bins for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for bins with residual close to item_size multiples.
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: small post-residual that is hard to fill
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            score += 12.0 * (1.0 - pr / ni.max(1.0));
        } else {
            score -= 8.0 * (pr - ni) / cap;
        }
    }

    // Last-chance bonus: strongly favor using a nearly-exclusive fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + progress);
    }

    // Slight preference to keep mean residual balanced
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small residues are dead space.
    let post = post_residual;
    // Perfect fit reward (residue in tiny classes).
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 30.0;
    } else if post <= 10 {
        score -= 12.0;
    }

    // Modulo classes: residues that are "harmonic" divisors of capacity are reusable
    // by common item sizes (multiples of 10, 25, 50).
    if post % 10 == 0 && post > 0 {
        score -= 8.0 + (post as f64) * 0.05;
    }
    if post % 25 == 0 && post > 0 {
        score -= 6.0;
    }

    // Penalize residues in awkward classes (prime-ish / odd small gaps).
    if post > 0 && post < 10 && post % 2 == 1 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // Harmonic bonus: next item leaves a class-0 residue again.
            if (post - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's residue: mild penalty scaled by gap.
            score += ((next_item_size - post) as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current residue
    // is large (wasteful to stuff) and alternatives are plentiful.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish score = capacity; subtract slightly so it wins
        // only when open bins would leave big residues.
        score = cap - 5.0;
        if fitting_bins_count > 0 && mean_residual < cap * 0.5 {
            score += 15.0; // discourage new bin when mean residual is healthy
        }
    } else {
        // Penalize creating large dead space relative to mean residual.
        if (post as f64) > mean_residual + 20.0 {
            score += 8.0;
        }
        // Favor tighter bins as stream progresses (first-fit-like consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer bins with below-mean residual (compact usage).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to be useful later.
    // Items range 1..100, so gaps below ~10 are nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Moderately risky gap: only valuable if the next item can use it.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            score += 18.0;
        }
    }

    // Reward tight fits (waste minimization core).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (1.0 - fill_ratio);

    // Mean residual coupling: if open bins are already slack-heavy, penalize
    // adding more slack; if bins are tight, a modest gap is fine.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when the
    // item is large and would leave a big gap in an existing bin, or when the
    // next item is large and needs a full bin.
    if bin_residual == bin_capacity {
        let big_gap = post_residual as f64 / bin_capacity as f64;
        if big_gap > 0.5 {
            score -= 25.0 * big_gap;
        }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 15.0;
        }
        // Mild bias against needless bin proliferation late in the stream.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Lookahead: if the next item fits exactly into the post gap, reward it.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain: item then next fills bin completely
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // reward proportional to how full bin will be after both items
            score -= (1.0 - slack_after_next as f64 / bin_capacity as f64) * 25.0;
        } else {
            // next item cannot follow here; penalize leftover dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += (1.0 - dead / next_item_size as f64) * 15.0;
            }
        }
    } else {
        // last item: prefer minimal residual strongly
        score -= 10.0;
    }

    // Relative to mean residual: placing in a bin tighter than average is good
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening new bin normally
        score += 25.0;
        // but if open bins have large residuals (poor packing state) and next item is big,
        // a fresh bin becomes attractive
        if next_item_size > 0 && (next_item_size as f64) > mean_residual * 0.9 {
            score -= 30.0 * avg_fragmentation;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        let _ = progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: smaller post-residual relative to capacity is better.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Wasted lookahead space: penalize leftover that next item can't use.
            score += 0.10 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last chance: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    score -= 0.05 * pressure * (0.5 + progress);

    // New-bin candidate handling: fresh empty bin is a fallback; make it less attractive
    // unless the item is large or open bins are nearly full.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * large_item - 0.5 * pressure * progress;
        // Encourage opening a new bin early on (bins are cheap early).
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for opening bins when many already open with slack.
    if bin_residual == bin_capacity && mean_residual > 40.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling with stream progress:
    // early in stream, tolerate larger residuals (flexibility matters);
    // late in stream, strongly punish wasted space.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Reward near-perfect fills: cubic discount on small residuals
    score -= 30.0 * (1.0 - x).powi(3) * (1.0 - progress);

    // Penalize mid-range dead space (residuals too small for typical items)
    let dead = (x * (1.0 - x)).sqrt(); // peaks at x=0.5
    score += 25.0 * dead * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 20.0 * snug * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * progress;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and this placement leaves waste
    score += 0.05 * open_bins_count as f64 * x * progress;

    // Compare against mean residual: bins with much-above-mean residual are
    // better targets for large items (spread the load)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - progress);

    // New-bin candidate: keep it neutral-slightly-high early, cheaper late
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit (post residual in low harmonic class) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score -= 20.0;
    }

    // Integer-division threshold classes: post_residual / 25 buckets
    let class = post_residual / 25; // 0..4
    score += class as f64 * 15.0;

    // Modulo coupling: residuals that are multiples of common item sizes (10,20,25,50)
    // are "harmonic" and reusable by typical item sizes -> reward.
    if post_residual > 0 && post_residual <= 80 {
        if post_residual % 10 == 0 {
            score -= 30.0;
        }
        if post_residual % 25 == 0 {
            score -= 25.0;
        }
        if post_residual % 20 == 0 {
            score -= 15.0;
        }
    }

    // Dead space: post_residual in awkward zone (1..10) but nonzero is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next fits, but leaves what kind of residue?
            let nr = post_residual - next_item_size;
            if nr == 0 {
                score -= 250.0;
            } else if nr <= 10 {
                score -= 100.0;
            } else {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: slight penalty for stranding residual
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is late
    // and open bins exist that fit; but allow early stream or when current
    // bin fit is very poor (high post_residual waste relative to next item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = pr > 50.0;
        if fitting_bins_count > 0 && !poor_fit {
            score += 150.0; // keep using existing bins
        }
        if progress > 0.8 {
            score += 50.0; // late stream: consolidate
        }
        // new bin has full residual 100, harmonic class 0
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    if mean_residual > 40.0 && open_bins_count > 3 {
        score += 8.0;
    }

    // Fractional tie-break: prefer bins whose residual is closest above item
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

