    }

    // Last chance: only bin that fits -> strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spawning many bins unless necessary.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a great next fit.
        let mut bonus = 0.0;
        if next_item_size > 0 && next_item_size <= item_size {
            bonus -= 5.0;
        }
        score += 15.0 + (open_bins_count as f64) * 2.0 + bonus;
    } else {
        // Reward using tighter bins (small residual before placement).
        score += (bin_residual as f64) * 0.15;
        // Lookahead: if next item fits this bin's post residual, reward.
        if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
