        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; slight penalty proportional to mismatch.
        score += 0.03 * (next_item_size - post_residual) as f64;
    }

    // Global state coupling: when mean residual is high, encourage consolidating into fuller bins.
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Prefer not opening new bins when few bins are open and item is small relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large or open bins are fragmented.
        score += 20.0 - 15.0 * fill_ratio - 2.0 * (open_bins_count as f64).min(10.0);
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Time horizon: late in the stream, be conservative and avoid spreading across bins.
    if progress > 0.8 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer tight fits, but weight dead space more as stream progresses.
    let mut score = prn * (1.0 + 1.5 * progress * progress);

    // Non-linear coupling: small post-residuals are valuable; penalize mid-range slack.
    score += 0.4 * prn * prn * (1.0 - prn) * (1.0 + progress);

    // Lookahead synergy: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 0.8 * fit_quality * fit_quality * (1.0 - progress);
        } else {
            // Residual too small for lookahead: penalize dead space growth.
            score += 0.3 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.2 * (1.0 - prn);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.02 * open_bins_count as f64 * prn;

    // New-bin candidate: penalize unless residual of open bins is genuinely bad.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" classes
    // (multiples of small denominators) are preferred since future items can fill them.
    let classes: [u32; 6] = [10, 20, 25, 50, 5, 100];
    let mut harmonic_bonus = 0.0f64;
    for (k, c) in classes.iter().enumerate() {
        if post_residual % c == 0 && post_residual > 0 {
            harmonic_bonus += 8.0 / ((k + 1) as f64);
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward dead space: residual in (0,10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size exactly (harmonic pair)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            // reward if the chain continues cleanly
            if rem2 == 0 { score -= 12.0; }
            else if rem2 < 10 { score += 6.0; }
        }
        // next item's harmonic class compatibility
        if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity; discourage unless
    // current bin fit is poor (large post_residual spread vs mean) or bin is fresh.
    if bin_residual == bin_capacity {
        // fresh bin: baseline competitive score
        score = (bin_capacity as f64) * 0.5
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            + 3.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening is attractive if next item also pairs with a fresh bin (e.g. two halves)
            if item_size + next_item_size == bin_capacity {
                score -= 18.0;
            }
        }
    } else {
        // mild penalty for spreading across many open bins
        score += 0.05 * open_bins_count as f64;
        // prefer bins tighter than the mean residual (good packing direction)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Stream progression: later in stream, be more conservative about new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the next item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Creating a gap too small for the lookahead item: penalty scaled by gap smallness.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Open-bins pressure: discourage spreading across many bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless existing fits are poor (last-chance logic).
        if fitting_bins_count > 0 {
            score += 25.0 + 3.0 * open_bins_count as f64;
        } else {
            score -= 10.0;
        }
    } else {
        // Slight preference for using existing bins, stronger when many are open.
        score -= 2.0 + 0.5 * open_bins_count as f64;
        // Last-chance bin: strongly favor filling the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual (tighter bins) to keep large gaps consolidated.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early stream: be slightly conservative, favor new bins to build flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: reward proportional to how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * (post_residual as f64 - slack);
            // Extra bonus for near-perfect two-item packing.
            if slack <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize dead space that is small (unusable).
            if post_residual < 10 {
                score += 20.0;
            }
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0;
    }

    // Prefer bins with residuals below mean (compact the tight bins first).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item (poor fit ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 {
        score += 15.0 * (0.5 - fill_ratio);
    } else {
        score -= 10.0 * fill_ratio;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 35.0 + crowding;
        // If item fits poorly everywhere else, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild late-stream conservatism: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize bins that are already relatively empty (fragmentation risk),
    // unless it's the new-bin candidate.
    if bin_residual != bin_capacity {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 15.0;
    }

    // Lookahead coupling: if the next item could fit exactly into the
    // resulting residual, reward this placement; if it would waste the
    // residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // Next item cannot use this residual at all.
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins; squeeze
    // into existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses and
        // when many bins are already open.
        score += 20.0 + progress * 40.0 + open_bins_count as f64 * 1.5;
        // But if mean residual across open bins is small (nothing fits well),
        // opening a new bin becomes more acceptable.
        score -= (mean_residual - item_size as f64).max(0.0) * 0.3;
    } else {
        // Existing bins get progressively favored late in the stream.
        score -= progress * 12.0;
    }

    // Slight preference for bins whose residual is close to the mean
    // (balance load across bins to keep mid-size residuals usable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild penalty for very large dead space that nothing (min size 1..100
    // unknown) could plausibly use later.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 - 0.25 * progress);

    // Penalize dead space more as stream progresses (waste becomes permanent)
    let dead_space_penalty = poly * (1.0 + progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight_fit_bonus = -8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Lookahead: reward residual that could fit the next item (smooth coupling)
    let lookahead = if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
        -3.0 * (fits_next / (1.0 + fits_next))
    } else {
        0.0
    };

    // Mild pressure to consolidate into fewer bins
    let consolidation = -0.05 * (open_bins_count as f64).ln();

    // Mean residual deviation: prefer bins close to mean residual (balanced packing)
    let mean_dev = (pr - mean_residual).abs() / cap;
    let balance = 1.5 * mean_dev * mean_dev;

    pr + dead_space_penalty + tight_fit_bonus + last_chance + lookahead + consolidation + balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that remain "usable"
    // for common small items. Classify post_residual into modulo classes of 10.
    let post_class = post_residual % 10;
    // Residuals that are exact multiples of 10 (or 0) are harmonically clean.
    let clean_bonus = if post_class == 0 { 6.0 } else if post_class <= 3 { 2.0 } else { 0.0 };
    score -= clean_bonus;

    // Dead space penalty: very small post_residual that can't fit typical items
    // (below the minimum item size of 1..100 interface, but small residuals < 10
    // are nearly dead). Penalize residuals in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how well next item fits remaining space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 - (slack / 10.0).min(4.0);
        } else {
            // Next item won't fit here; penalize if this bin becomes nearly dead.
            score += 3.0;
        }
        // Harmonic match: post_residual and next_item_size share a class of 10.
        if (post_residual / 10) == (next_item_size / 10) && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual across open bins is small (bins nearly full).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins unless existing residuals are fragmented.
        score += 20.0;
        let mean_fit = mean_residual / bin_capacity as f64;
        if mean_fit < 0.25 {
            score -= 18.0 * (0.25 - mean_fit) * 4.0;
        }
        // Early in stream, be more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward filling bins tighter than the current mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Integer-division threshold: bins whose residual drops below half
        // capacity are in "dense" mode; encourage consolidating there.
        if post_residual < bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Modulo-5 harmony between item size and residual: aligned sizes pack well.
    if item_size % 5 == 0 && bin_residual % 5 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (perfect fills are best).
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
        score += 10.0 + 5.0 * pressure;
    } else {
        score -= 3.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Slight preference for using existing bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much of the remaining
            // space it consumes (tight chain packing).
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 250.0 * fill;
        } else {
            // Next item does NOT fit here: penalize, but less if post_residual
            // is small (dead space unlikely to be usable anyway).
            let waste = next_item_size as f64 - post_residual as f64;
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 120.0 * waste / (next_item_size as f64) * (1.0 - dead);
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer placing into them (waste little extra capacity).
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 200.0 - 180.0 * fragmentation - 100.0 * large_item;
        // Early in the stream, opening bins is cheap (future items can fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Mild penalty for very small leftover slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially near-perfect ones.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize large dead space relative to the smallest possible item (1..100 range).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty in crowded choice to encourage keeping big-residual bins open.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement;
    // if it nearly fits, mild penalty for blocking it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual + 5 {
            score += 8.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open/spread across bins
    // (new bins get a discount); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin residual == capacity.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // Early: opening a new bin is cheap; late: expensive.
        let new_bin_cost = 20.0 + 60.0 * progress;
        score = new_bin_cost + 0.5 * open_pressure;
        // If no open bin fits, opening is forced anyway; discount it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large and current bin would be nearly full, opening may help.
        if next_item_size > 0 && next_item_size >= item_size && progress < 0.5 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing) early on;
    // prefer below-mean-residual bins (tighter bins) later.
    let dev = bin_residual as f64 - mean_residual;
    score += (if progress < 0.5 { 0.05 } else { -0.05 }) * dev;

    // Slight preference for bins with smaller residual overall (fill tighter bins first).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, with smooth polynomial shaping
    let x = pr / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: reward tight fits (low post-residual) with non-linear decay
    let mut score = x3 * 300.0 + x2 * 60.0 + pr;

    // Progress coupling: later in stream, penalize loose residuals more strongly
    let prog_coupling = progress * (x2 * 120.0 + x * 30.0);
    score += prog_coupling;

    // Penalize near-empty-bin choices mildly to prefer filling open bins,
    // but smooth polynomial in residual so tight fits can still win
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin -> strong reward (subtract)
    if fitting_bins_count == 1 {
        score -= 35.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        // slight penalty when many alternatives exist, scaled by residual waste
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * (8.0 + 12.0 * x2);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0 + 20.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Mean-residual deviation coupling: bins deviating from mean waste get shaped penalty
    let dev = pr - mean_residual;
    score += 0.15 * dev * (1.0 + progress);

    // Open bins count: more open bins -> mildly discourage spreading
    score += open_bins_count as f64 * 0.4 * x2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (eighths).
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let post = post_residual as f64;

    // Dead-space penalty: residuals in awkward small classes are hard to fill.
    if post > 0.0 {
        let class = (post / eighth).floor() as i64;
        let class_penalty = match class {
            0 => 12.0, // (0,12.5) nearly unusable
            1 => 6.0,  // (12.5,25)
            2 => 2.0,  // (25,37.5)
            3 => 0.0,  // sweet spot: fits mid-size items
            4 => 1.0,
            5 => 3.0,
            6 => 4.0,
            _ => 5.0,
        };
        score += class_penalty;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Exact half-fill harmonic bonus.
    if post_residual * 2 == bin_residual {
        score -= 8.0;
    }

    // Modulo harmonic coupling: item size classes vs post residual.
    let m = (post_residual % 10) as f64;
    score += 0.4 * m; // prefer residuals that are round multiples of 10 (common item sizes)

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 0.3 * (next_item_size as f64);
        } else {
            // next item cannot fit here; penalize leaving large residual
            score += 0.2 * post;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer only when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let tight = (mean_residual / cap).max(0.0).min(1.0);
        // Opening new bin is attractive when existing residuals are small (tight bins)
        // and item is large relative to mean residual.
        let fit_badness = (item_size as f64 - mean_residual).max(0.0) / cap;
        score -= 20.0 * (1.0 - tight) * fit_badness;
        score += 2.0 * pressure; // slight preference to reuse bins as stream progresses
        // Late in stream, avoid opening new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
        // If next item is small, new bin wastes capacity potential.
        if next_item_size > 0 && next_item_size < 30 {
            score += 6.0;
        }
    }

    // Mild global regularization.
    score += 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item size (1..=10)
    // are pure waste; punish them harshly, scaled by how close to "unusable" they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward very tight fits (post_residual near zero) beyond the raw value.
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is a chain win; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover; small penalty if leftover is dead space.
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it is one of the "tight" bins — placing here consolidates waste.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.4;
    } else {
        score += (-residual_diff) * 0.15;
    }

    // Slight preference for filling bins early in the stream (keep options open later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current fit would create large dead space
    // or the item is large and no open bin is a good home.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are chosen only on genuine need.
        score += 25.0;
        if item_size >= 50 {
            score -= 10.0; // large items are fine to start fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but with a convex penalty
    // on very small residuals (dead space) that cannot plausibly hold future items.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space penalty grows super-linearly as residual approaches unusable size
        let dead_threshold = 9.0; // smallest item is 1..100, treat <10 as near-dead
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 6.0;
        }
    }

    // 2-step lookahead: strongly reward exact/near match between post_residual
    // and the next item size.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        if pr >= n {
            // next item can fit here afterwards: reward, best when exact
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64)) * (if diff < 5.0 { 2.0 } else { 1.0 });
        } else {
            // next item won't fit after this placement; penalize closeness of miss
            score += 4.0 + (n - pr).min(20.0) * 0.5;
        }
        // bonus if this bin's residual currently matches next item exactly (chain fit)
        if (bin_residual as f64 - n).abs() < 0.5 && bin_residual >= item_size {
            score -= 8.0;
        }
    } else {
        // last item: pure tightest-fit
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual == 0 {
            score -= 15.0; // perfect fill
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Make it attractive only when no good existing option exists:
    // i.e., when item is large relative to capacity or few fitting bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // default mild preference against opening new bins
        score += 10.0;
        // but if item is large (>60% of capacity), a fresh bin is often better
        if frac > 0.6 {
            score -= 20.0 * (frac - 0.6) / 0.4;
        }
        // if many bins fit the item, discourage the new bin
        if fitting_bins_count > 2 {
            score += 8.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // early in stream, opening bins is cheaper; late in stream, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Coupling with mean residual: placing into a bin with residual far below
    // mean (already well-filled) is good; bins above mean residual waste space.
    let bin_res = bin_residual as f64;
    if bin_res > mean_residual {
        score += (bin_res - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_res) * 0.15;
    }

    // Slight preference to keep number of open bins small
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, dead space becomes costlier
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 6.0 * prog_term * norm_pr * norm_pr;

    // Reward tight fits (small post-residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation of packing structure)
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: bonus if next item fits into the resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 3.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild pressure against scattering across many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity fractions (dead-space classes). Small leftovers are perfect fits.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit: leftover in {0} or very tiny -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic dead-space classes: leftovers that are too small for the
    // minimum item size (1..=100, min realistic ~10) are wasted space.
    // Penalize leftovers that can never be filled by any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 300.0; // unusable sliver
    }

    // Modulo-class logic: leftovers near common item-size harmonics
    // (multiples of 10 / 25 / 50) are more likely to be reusable.
    let m10 = post_residual % 10;
    if m10 == 0 && post_residual > 0 {
        score -= 40.0; // aligned with decade-harmonic items
    }
    let m25 = post_residual % 25;
    if m25 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can also go here: excellent chain placement.
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * chain_quality;
        } else {
            // Next item won't fit here after this placement; penalize more
            // the larger the wasted fraction.
            score += 30.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins unless the current bin would be left with
    // a very poor (large, unaligned) residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit badly.
        // Base cost for opening a new bin; adjusted by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 80.0 + 40.0 * progress + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= 50 {
            // Big item coming: a fresh bin gives flexibility.
            score -= 30.0;
        }
    } else {
        // Reusing a bin: reward tighter fits relative to mean residual state.
        score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);
        // Slight preference for bins with lower residual already (compact packing).
        score += 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    // Penalize opening many bins late in the stream if open bins suffice.
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; anything below ~15 is unlikely to be filled later.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0; // dead space penalty
    } else if post_residual >= 15 && post_residual < 30 {
        score += 15.0; // mildly risky gap
    }

    // Perfect fit reward: exact closure of the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 25.0;
        // More open bins -> pressure to fill existing ones rather than open new.
        score += open_bins_count as f64 * 2.0;
        // If the next item could combine with the residual left here, discourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    } else {
        // Reward placing into already-open bins proportionally to congestion.
        score -= open_bins_count as f64 * 1.5;
        // Lookahead: if this placement leaves room for the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 {
            score += 5.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, allow slightly more freedom to open bins (exploration);
    // late in the stream, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect lookahead fit gets a large bonus.
        if diff < 1.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward scaled by tightness.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Placement blocks the lookahead item: penalize proportionally to waste.
            score += 10.0 + 0.3 * (look - post_residual as f64);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Reward tight fits (small dead space) relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual: prefer consuming bins with above-average residual
    // (keeps tight bins available), but avoid leaving tiny unusable slivers.
    if post_residual as f64 > mean_residual {
        score -= 5.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great lookahead fit
    // or no reasonable alternative exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 70.0; // new bin perfectly reserved for next item
        }
        if item_size >= bin_capacity {
            score -= 100.0; // item only fits in a fresh bin
        }
        // As stream progresses, be more willing to open bins (fewer future chances).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins already open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.2 * next_item_size as f64;
    }
    // If next item cannot fit anywhere after this placement, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (balance load, keep big holes available).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Many open bins: encourage closing bins out (favor fuller bins).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_options = fitting_bins_count == 0
            || (fit_ratio < 0.5 && post_residual > 30);
        if poor_options {
            score -= 10.0 + 0.3 * item_size as f64;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling: penalize mid-range residuals more late in stream.
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 40.0 * quad * (0.3 + 0.7 * progress);
    score += 30.0 * cube * progress;

    // Reward near-perfect fits (post_residual small) with a smooth bump.
    score -= 25.0 * (1.0 - norm_pr).powi(6);

    // Lookahead coupling: bonus if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // Next item won't fit here: penalize wasted potential proportionally.
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate (empty bin): make it unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "dead zone" (small, unusable slivers) are penalized.
    let dead_zone = post_residual > 0 && post_residual < 10;
    if dead_zone {
        score += 40.0;
    }

    // Reward leftover sizes that are friendly to future items: multiples of
    // common size classes (harmonic grid of capacity fractions).
    let grid: u32 = bin_capacity / 4; // 25-unit harmonic grid
    if post_residual % grid == 0 {
        score -= 15.0;
    } else if post_residual % (bin_capacity / 10) == 0 {
        score -= 8.0;
    }

    // Integer-division threshold: leftovers in the mid band [10, 30) are
    // moderately useful; leftovers >= 30 are very useful.
    let band = post_residual / 10; // 0..10 harmonic band index
    match band {
        0 => score += if post_residual > 0 { 25.0 } else { 0.0 }, // perfect fit
        1 | 2 => score -= 5.0,
        _ => score -= 12.0,
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    score += open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum item size (1) is impossible here,
    // but small residuals (e.g. < 10) are "dead space" since typical items are >= 10.
    // Use a super-linear penalty on small post_residual.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space zone: residual too small to be useful for most items
        if pr < 10.0 {
            score += (10.0 - pr) * (10.0 - pr) * 2.0; // quadratic dead-space penalty
        } else {
            // mild penalty for larger leftover, scaled by how far from capacity
            score += pr * 0.15;
        }
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but positive).
    if post_residual == 0 {
        score -= 50.0; // perfect fit: bin exactly filled
    } else if post_residual <= 5 {
        score -= 20.0; // near-perfect fit
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 35.0; // next item perfectly fills remainder
        } else if slack < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual cannot host next item: penalize if it's dead space
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize spreading); when few bins open, mild opposite effect.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduce if mean residual across open bins is large
        // (i.e. existing bins are full-ish and a new one is genuinely needed).
        score = 45.0 - mean_residual * 0.4 + open_bins_count as f64 * 0.2;
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is close to mean
    // (balanced packing avoids accumulating many nearly-empty bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 300.0; // next item fits this bin perfectly
        } else if post_residual >= next_item_size {
            // next item fits with leftover: mild reward scaled by tightness
            let slack = post_residual as f64 - next;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space left behind
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: avoid fragmenting bins with much space
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer filling nearly-full bins over sparse ones
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio;

    // Early in stream: be more willing to open new bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize moderately unless item is large or stream is early
        score += 120.0 - 80.0 * progress - 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical future item (min size 1, use lookahead)
    if post_residual > 0 {
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / 100.0);
        }
        // Small residuals are usually wasted; large residuals keep flexibility
        if post_residual < 10 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer tight fits);
    // late in the stream, avoid opening new bins at all costs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses
        score += 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Reward using existing bins more strongly later in the stream
        score -= 10.0 * progress;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score += 2.0; // this bin is relatively tight; using it frees mean residual
    }

    // Prefer bins whose residual is close to a multiple-friendly structure with item
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.05 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late, punish large residuals harder.
    let norm_post = post / cap; // in [0,1]
    let w = 0.5 + 2.5 * progress * progress; // smooth ramping weight
    score += w * cap * norm_post * norm_post;

    // Reward near-perfect fits via smooth cubic term (no piecewise constants).
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Dead-space penalty: residual that no plausible future item can use.
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = post - nx;
        if gap >= 0.0 {
            score += 0.05 * gap * (1.0 + progress);
        } else {
            score += 0.10 * (-gap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - norm_post);
    }

    // Slight preference for bins below mean residual (consolidate space).
    score += 0.02 * (mean_residual - post);

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: fresh bins are attractive unless an open bin fits very well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline: slightly worse than a perfect fit (post_residual == 0)
        score = 30.0;
        // Early in stream, opening bins is cheap (many future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Many open bins with slack -> prefer reusing
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    } else {
        // Reward tight fits (small post_residual) nonlinearly
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

        // Harmonic classes: post_residual modulo classes. Residuals that are "harmonic"
        // with common item sizes (divisible by small integers) are more usable later.
        let pr = post_residual;
        let harmony_bonus = if pr == 0 {
            60.0
        } else if pr % 10 == 0 {
            25.0
        } else if pr % 5 == 0 {
            12.0
        } else if pr % 2 == 0 {
            5.0
        } else {
            0.0
        };
        score -= harmony_bonus;

        // Integer division thresholds: classify dead space
        let dead_threshold = 10; // smallest possible item
        if pr < dead_threshold {
            score += 25.0; // unusable dead space
        } else if pr / 10 == 0 {
            score += 10.0;
        }

        // Lookahead: does next item fit in post_residual? Strong reward.
        if next_item_size > 0 && next_item_size <= pr {
            score -= 20.0;
            // Extra reward if next item nearly fills remaining space
            if pr - next_item_size <= 10 {
                score -= 15.0;
            }
        } else if next_item_size > pr {
            score += 8.0; // next item won't fit here anyway
        }

        // Last-chance bin: if this is the only fitting bin, prefer using it
        if fitting_bins_count == 1 {
            score -= 18.0;
        } else {
            score += 1.5 * (fitting_bins_count as f64 - 1.0);
        }

        // Prefer bins with lower residual overall (best-fit bias), modulated by mean residual
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 9.0; // gaps <= 9 are dead space for items >= 10
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += 40.0 + (dead_zone - post_residual as f64) * 5.0;
    }
    // Perfect fit bonus: subtract to strongly favor zero waste.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if existing bins would leave bad dead space anyway.
        if post_residual as f64 <= dead_zone {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mild mean-residual coupling: bins far below mean residual are attractive.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late-stream consolidation: as stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual near mean are neutral;
    // much larger residuals than mean are attractive targets (consolidate space).
    let res = post_residual as f64;
    if res > mean_residual {
        score -= 0.15 * (res - mean_residual);
    } else {
        score += 0.25 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit well, especially early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score += 20.0 + 0.4 * waste - 15.0 * progress;
        // Opening a new bin is fine if it enables a perfect next-item chain.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that is still too small for typical items is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it heavily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Global residual state: penalize bins far from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more exploratory (favor new bins slightly);
    // late in the stream, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0 * (bin_residual == bin_capacity) as i32 as f64;
    score -= t * 4.0;

    // Slight preference for bins with less residual overall (best-fit flavor).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * prn * prn);

    // Smooth stream-progress coupling: later in the stream, tolerate
    // residual less (dead space becomes costlier as stream ends)
    score += 12.0 * progress * prn * (1.0 - progress) * prn;

    // Encourage tight fits: subtract a smooth bonus proportional to fill ratio
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * (1.0 - prn);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fill;
    }

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (1.0 - pr / n);
        }
    }

    // Penalize bins far from mean residual (keep residual distribution tight)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln() * prn;

    // New-bin candidate: mild penalty so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the item: which capacity fraction it belongs to
    let item_class = (bin_capacity / item_size.max(1)).min(10);
    // Harmonic class of the next item
    let next_class = if next_item_size == 0 { 0 } else { (bin_capacity / next_item_size.max(1)).min(10) };

    // Reward placements whose post_residual is divisible into a useful harmonic class
    if post_residual > 0 {
        let pr = post_residual;
        // post_residual is itself a "nice" size (fits common item sizes)
        if pr % 10 == 0 && pr >= 10 {
            score -= 12.0;
        }
        // post_residual matches next item size exactly -> strong reward
        if next_item_size > 0 && pr == next_item_size {
            score -= 60.0;
        }
        // post_residual can host the next item
        if next_item_size > 0 && pr >= next_item_size {
            score -= 20.0 + (pr - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 {
            // dead space relative to lookahead
            score += (next_item_size - pr) as f64 * 0.8;
        }
        // Integer-division threshold: post_residual in "waste zone" (1..10)
        if pr < 10 {
            score += 25.0;
        }
        // Harmonic compatibility: item class and leftover class align (e.g. halves + quarters)
        let left_class = (bin_capacity / pr.max(1)).min(10);
        if left_class % 2 == item_class % 2 {
            score -= 8.0;
        }
        if next_class != 0 && left_class % 3 == next_class % 3 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins (small residual) mildly beyond raw post_residual
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean residual coupling: avoid scattering waste when mean residual is low
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: consolidate harder, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit
        score += 30.0 + progress * 60.0 + (fitting_bins_count.max(1) as f64) * 15.0;
        // Early stream with small item: a fresh bin is fine
        if progress < 0.2 && item_size < 30 {
            score -= 45.0;
        }
    }

    // Small penalty for opening bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no typical item can use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 25 {
            score += 30.0; // hard-to-fill gap
        } else if post_residual < 50 {
            score += 8.0;  // moderate gap
        }
    } else {
        score -= 25.0; // perfect fit: bin closed completely
    }

    // Reward tight fits (wasted fraction of the bin).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit here, mild penalty proportional to openness pressure.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with below-average residual (fill emptier bins less, pack tighter ones first).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * desperation + 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh space for a big follower can pay off
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
