    // Aggressive 2-step lookahead: reward bins where next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or well into leftover space
            let slack = post_residual - next_item_size;
            if slack == 0 {
