    // Penalize large wasted residuals relative to mean residual (dead space)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: prefer keeping it closed unless no open bin fits well
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // late in the stream, reusing open bins matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild penalty for very tight residuals that become unusable
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
