pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth interaction: small residuals are more acceptable early, penalized late
    score += 12.0 * (1.0 - x) * (1.0 - x) * progress;

    // Reward tight fits (small post_residual) with a saturating non-linear term
    score -= 20.0 * (-3.0 * x).exp();

    // Penalize creating dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) as f64;
        score += 6.0 * (gap / cap) * (1.0 + progress);
        // Reward residual that exactly accommodates the next item
        let fit_err = (pr - nx).abs() / cap;
        score -= 8.0 * (-4.0 * fit_err).exp();
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when current bins are nearly full on average
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (cap * 0.5 - mean_residual).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by 10 is
    // reusable by typical item sizes, odd leftovers become dead space.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0; // perfectly harmonic residual: strongly reward
    } else if class <= 2 {
        score += 6.0;  // tiny sliver, nearly dead space
    } else if class >= 8 {
        score += 3.0;  // large odd chunk, awkward
    }

    // Integer-division thresholds on post_residual: classify leftover
    // into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 30.0; // perfect fit: always best
    } else if post_residual < 10 {
        score += 25.0; // unusable dead space below min item size
    } else if post_residual <= quarter {
        score += 4.0;
    } else if post_residual <= half {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic: next item slots in; extra reward if exact modulo match
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: residual likely wasted
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin starts neutral; make it attractive
    // only when remaining open bins have poor usable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_r = mean_residual.max(0.0);
        // open a new bin when existing residuals are fragmented/small
        score = 45.0 + mean_r * 0.3 + open_bins_count as f64 * 1.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin keeps room for the next item
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (1..=10) are pure waste.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead if next item exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Gaps that can still host the next item are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // rather than spreading; with few bins, opening a new one is cheaper.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * bin_pressure;
    } else {
        // New-bin candidate: penalize when many bins are already open,
        // reward when the stream is early or bins are crowded with waste.
        score += 30.0 + 10.0 * bin_pressure;
        if mean_residual < item_size as f64 {
            score -= 20.0; // open bins are nearly full; new bin is fine
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward closeness of match.
            score -= 300.0 - diff * 2.0;
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += diff as f64 * 1.5;
        }
        // Small bonus if next item could fit tightly in post_residual window.
        let tightness = 1.0 - (diff / bin_capacity as f64);
        score -= tightness * 20.0;
    } else {
        // Last item: just minimize leftover.
        score += 10.0;
    }

    // Prefer bins that are already fairly full (small residual relative to capacity).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize creating very small unusable residuals (< typical min item size 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    }

    // Relative to mean residual: prefer bins below mean residual (fuller than average).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: make opening a new bin only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; slightly higher when many bins already open.
        score = 200.0 + open_bins_count as f64 * 2.0
            - (mean_residual / bin_capacity as f64) * 20.0;
        // If lookahead matches a fresh bin capacity usage, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by relative fill achieved.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space (waste), tolerate large leftover space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
