        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer filling existing bins over new ones.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large dead space would be created).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases when open bins are numerous
        // or the item is large (poor fit anywhere).
        let waste_elsewhere = (bin_capacity - item_size) as f64;
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else {
            1.0
        };
        score = 60.0 - 20.0 * poor_fit_pressure - 0.3 * waste_elsewhere
            + (open_bins_count as f64).sqrt() * 2.0;
        // Late in stream, avoid opening new bins unless necessary.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: dead space penalized super-linearly
    let dead = pr_norm * pr_norm;
    score += 40.0 * dead * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 30.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 10.0 * open_norm * pr_norm;

    // Lookahead coupling: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mean residual interaction: prefer bins below mean residual (tighter bins)
    let mean_norm = mean_residual / cap;
    score += 12.0 * (pr_norm - mean_norm) * (0.5 + progress);

    // Smooth progress-driven exploration: late in stream, avoid opening new bins
    score += 20.0 * progress * (bin_residual as f64 / cap) * (1.0 - (item_size as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
