        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 30.0; // opening fresh makes sense for a near-full next item
        }
    }

    // Stream progression: as stream ends, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - (pr as f64 / bin_capacity as f64));

    // Tie-break toward compacting residuals relative to mean.
    score += (mean_residual - pr as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
