            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize bins that leave awkward middles
            let awkward = (post_residual as f64 - (next_item_size as f64 * 0.5)).abs();
            score += 0.15 * awkward;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are large (poor fits everywhere) or the item is huge.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously
        score += 30.0;
        // If the item is large and would leave a big hole in an existing bin, new bin is fine
        let hole = post_residual as f64;
        if hole > 50.0 {
            score -= 35.0;
        }
        // If many open bins already exist with small mean residual, prefer them
        score += 0.5 * mean_residual;
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer using bins with below-average residual (consolidate emptiness elsewhere)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for large open bin counts to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively (quadratic growth)
    let progress_coupling = 1.0 + 3.0 * progress * progress + 6.0 * progress * progress * progress;
    score *= progress_coupling;

    // Reward exact / near-perfect fills with a smooth term
    let perfect = (norm_pr * (1.0 - norm_pr) * 4.0).max(0.0); // 1 at half, 0 at edges
    score -= 30.0 * (1.0 - perfect) * (1.0 - perfect) * (1.0 + 2.0 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize bins that are outliers vs mean residual (smooth quadratic divergence)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let fit_next = if pr >= ns { 1.0 } else { 0.0 };
        // smooth compatibility: closeness of post_residual to next item size
        let compat = (-gap / cap).exp();
        score -= 15.0 * compat * fit_next * (0.5 + progress);
        // penalize post-residual just barely below next item (dead space)
        if fit_next < 0.5 {
            score += 8.0 * (ns - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for proliferating open bins early; relax later
    score += (open_bins_count as f64).powf(1.3) * 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists; make new bin slightly unattractive otherwise
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 25.0 - 30.0 * large_item * large_item;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual lands on
    // "nice" residue classes (multiples of common item-size divisors) are more
    // reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        // post_residual divisible by 10/20/25 => likely to fit future items exactly
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 3.0; }
        if pr % 50 == 0 { harmonic_bonus += 5.0; }
        // integer-division thresholds: small dead space is bad
        if pr < 10 { harmonic_bonus -= 15.0; }
        else if pr < 20 { harmonic_bonus -= 6.0; }
        score -= harmonic_bonus;
    } else {
        // perfect fit is ideal
        score -= 40.0;
    }

    // Coupling with lookahead item: reward leaving exactly room for next item,
    // penalize leaving room that neither fits next item nor is classically useful.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 8.0; }
            score -= (slack.min(30)) as f64 * 0.2;
        } else {
            // next item cannot follow here: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / cap) > 0.85;
        if tight_fit || (post_residual > 0 && post_residual < 10) {
            score -= 12.0;
        } else {
            score += 25.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Progress-aware tightening: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * (10.0 + 10.0 * progress);

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer tightening existing bins
    // when many are open, but allow opening a new bin when few are open.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += open_pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer bins tighter than the mean residual (better fill quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild progression pressure: late in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // Discourage opening a new bin when an existing bin has a good fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus expected waste.
        score += 25.0 + 0.3 * (bin_capacity as f64 - item_size as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: strongly reward exact or near match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let bonus = 14.0 * (1.0 - gap / bin_capacity as f64);
        score -= bonus;
        // Perfect chaining: next item exactly fills the bin.
        if gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving post_residual too small for the next item (dead space).
        let dead = next_item_size as f64 - post_residual as f64;
        score += 6.0 * dead / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins that keep residual spread balanced.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Late in the stream, prefer filling existing bins harder (avoid tail waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when good existing candidates exist.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large relative post-residual quadratically.
    let frac_post = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac_post * frac_post * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Last chance: this is the only open bin that fits; strongly prefer it
    // over opening a new bin (new bin has residual == capacity, so subtract).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // Extra reward for a chained near-perfect two-item fit.
            let chain = (post_residual - next_item_size) as f64;
            if chain < 5.0 {
                score -= 60.0;
            }
        } else {
            // Post-residual too small for next item: dead space penalty.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is already small (fill nearly-full bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs().signum() * (bin_residual as f64 - mean_residual).abs().min(30.0);
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Late in the stream: consolidate aggressively, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual >= bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // open bins with slack exist; early on allow new bins for exploration.
        score += 20.0 + 120.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0 * (1.0 - progress); // early: big items may justify fresh bins
        }
    }

    // Mild penalty for many open bins to encourage reuse.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, scaled by progress (later in stream -> value tight fits more)
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear coupling: reward tight fits (small post_residual) with a smooth penalty curve
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Dead-space penalty: residual too small to plausibly hold future items
    let dead = (1.0 - norm_pr).tanh();
    score -= 8.0 * dead * dead * norm_pr;

    // Lookahead: bonus if next item fits exactly in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 4.0 * ((pr - nxt) / cap).abs();
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Prefer filling bins with low residual relative to mean (balance consolidation)
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild penalty for many open bins when fit is loose
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate adjustment: make empty bin attractive only when current fit is very poor
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress) - 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "awkward" sizes get penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty: residuals that no future item (1..=100) can pair well with.
        // Small residuals (<10) are near-useless; residues in [50,60] pair only with mid items.
        if pr < 10 {
            score += 40.0;
        } else if pr <= 20 {
            score += 8.0;
        }
        // Modulo-10 class: residuals that are multiples of 10 are "harmonic" and easy to fill.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division threshold: pr/25 classifies quarters of the bin.
        match pr / 25 {
            0 => score += 5.0,          // tiny leftover
            1 => score -= 2.0,          // quarter free: good
            2 => score -= 4.0,          // half free: very good
            _ => score -= 1.0,          // mostly empty (new bin case)
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic pairing: reward if next item fills post_residual well.
            let gap = (pr - next_item_size) as f64;
            if gap < 5.0 {
                score -= 12.0;
            } else if gap < 15.0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is fine when item is large
    // relative to residual or many bins are already open with big mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items late in the stream or when open bins are fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let open_bonus = (open_bins_count as f64 * 0.4).min(6.0);
        let bias = large_item * 30.0 + fragmentation * 15.0 + open_bonus + progress * 5.0;
        score += 25.0 - bias;
        // Never open a new bin for a tiny item when any bin fits.
        if item_size <= 25 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins => prefer existing bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Dead space penalty: small unusable gaps (post_residual < smallest plausible item)
    // are wasted, so penalize them heavily.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0; // residual too small for lookahead item: dead space risk
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidation
    // (make new bins less attractive relative to open ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by open count.
        score += 35.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
        // If the mean residual across open bins is small, opening a fresh bin is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
    } else {
        // Slight preference for bins below mean residual (balance load).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fits (post_residual small relative to item size)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item
            if post_residual == next_item_size {
                score -= 800.0;
            } else {
                // Chainable but leaves slack; reward proportional to tightness
                let slack = (post_residual - next_item_size) as f64;
                score -= 300.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit in the leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += 0.5 * mean_gap;

    // Penalize using a bin that leaves a large unusable fragment relative to capacity
    let frag_ratio = post_residual as f64 / bin_capacity as f64;
    if frag_ratio > 0.0 && frag_ratio < 0.1 {
        score -= 100.0 * (0.1 - frag_ratio) * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 50.0;
        // But if next item chains perfectly with this item in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 400.0;
            }
        }
        // Late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins among equals
    score += 0.1 * residual_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

