    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.35 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that cannot hold typical future items.
    if post_residual > 0 && post_residual < 10 {
