            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty for fragmenting space.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    score += 0.03 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for using already-open bins over creating more.
    if bin_residual != bin_capacity {
        score -= 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; late, demand tightness more strongly.
    let coupling = x * (1.0 - progress) * (1.0 - progress) - 0.5 * x * progress;
    score += 40.0 * coupling;

    // Penalize dead space that cannot fit the next item (lookahead awareness)
    if next_item_size > 0 {
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += 1.5 * gap * (1.0 + progress);
    } else {
        // last item: strongly prefer zero waste
        score += 2.0 * pr;
    }

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * x;

    // Mild pull toward mean residual: bins deviating from mean are less attractive
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod capacity fractions.
    let q = bin_capacity / 4; // 25 for C=100
    let cls = post_residual % q;
    // Penalize small "stub" residuals that are hard to fill (dead space in the lowest harmonic class)
    if post_residual > 0 && cls < 10 {
        score += 12.0 - (cls as f64) * 0.8;
    }
    // Reward residuals that land in "friendly" classes (divisible by common item sizes)
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 {
        score -= 3.0;
    }

    // Integer-division threshold: perfect / near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward; harmonic class of next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // bonus if post_residual after hypothetical next placement is again in a good class
        let p2 = post_residual - next_item_size;
        if p2 % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving large residuals that trap the stream
        score += (post_residual as f64) * 0.05;
    }

    // New-bin candidate handling: only attractive when current bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64;
        // Prefer new bin late in stream or when many bins already open and mean residual is small
        let new_bin_bonus = 20.0 * (1.0 - progress) + 0.5 * crowded - mean_residual * 0.3;
        if new_bin_bonus > 10.0 {
            score -= new_bin_bonus;
        } else {
            score += 15.0; // discourage opening bins early / when residuals are useful
        }
    }

    // Mild penalty for very large residuals wasted on small items
    if (post_residual as f64) > mean_residual * 1.5 && post_residual > q {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small for
    // typical future items are unusable dead space -> heavy penalty.
    // Treat gaps <= 10 as fully wasted; gaps below the smallest useful
    // threshold (e.g. cannot hold anything >= 1) get graded penalties.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        // The smaller the gap relative to the threshold, the worse.
        let waste = dead_threshold - post_residual as f64;
        score += waste * 4.0;
    }

    // Perfect fits are extremely valuable: reward them strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit, still almost dead space but recoverable
    }

    // If the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item fits comfortably, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Creating a gap that the known next item cannot use -> penalize.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items,
    // favor filling existing bins (especially the new-bin candidate gets
    // penalized when many bins are already open).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // unless the fit into existing bins is terrible (large post_residual
        // already reflects that).
        score += pressure + 10.0;
    } else {
        // Existing bin: slight reward scaled by pressure to consolidate.
        score -= pressure * 0.5;
    }

    // Late in the stream, tighten up: waste less, prefer tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Penalize deviation from mean residual: bins far below mean residual
    // (nearly full) are good to keep filling.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is good, but only if the next item can use it (2-step lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            // Reward bins whose leftover exactly (or nearly) accommodates the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 - gap.min(200.0);
            if gap == 0.0 {
                score -= 500.0; // chain perfect fit
            }
        } else {
            // Leftover cannot serve the next item: penalize proportionally to dead space.
            let dead = if next_item_size > 0 {
                post_residual as f64
            } else {
                post_residual as f64 * 0.5
            };
            score += dead * 0.3;
        }
    }

    // Compare against mean residual: bins below mean residual are tighter -> prefer them.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large relative
    // to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // But if the item is big (would leave little residual anyway), a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 60.0;
        // If many bins are open with slack, discourage yet another bin.
        score += open_bins_count as f64 * 5.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into post_residual, this placement is doubly good.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / 100.0) * 8.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item won't fit here after placement: mild penalty proportional to wasted potential.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize leaving dead space that nothing (>= 10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        // Base cost of opening a bin, discounted when bins are crowded / residuals low.
        score += 18.0 + 10.0 * (1.0 - progress) - crowded.min(15.0);
        // If the current bin's post-fit would be very tight, opening a new bin is fine.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Global state: when mean residual is large, prefer bins that reduce fragmentation
    // (i.e., prefer using bins with residual far from mean? favor bins close to mean to balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time pressure: early in stream, keep bins open (avoid over-opening);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual penalized more heavily as stream progresses
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * pr * pr * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to item size)
    let tight = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 6.0 * (-tight * tight).exp();

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 4.0 * (-gap / 20.0).exp();
        } else {
            score += (-gap) * 0.3;
        }
    }

    // Prefer bins with residual below mean residual (better consolidation)
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Penalize opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 * (0.5 + progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Small residuals are dead space -> penalize heavily via quadratic class term.
    score += (10 - class.min(10)) as f64 * (10 - class.min(10)) as f64 * 0.35;

    // Perfect fit: post_residual in {0, 5} (harmonic halves) -> strong reward.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            // Harmonic residue: next_item_size % 10 alignment with post_residual % 10
            let align = (post_residual % 10) == (next_item_size % 10);
            if align {
                score -= 15.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when mean residual across open bins is small
    // (open bins are crowded) or this bin would leave a large usable residual.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        if crowded {
            score -= 40.0;
        } else {
            score += 55.0; // discourage opening new bins when existing space is usable
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progression: later in stream, be slightly greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // Modulo-3 harmonic bonus: residuals divisible by 3 pair well with many sizes.
    if post_residual % 3 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 10.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (favor bins whose residual is close to the mean residual).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of opening a new bin.
        score += 90.0 * desperation + 45.0;
        // If the next item could combine with the residual left here,
        // opening a fresh bin is more acceptable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 55.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly in the resulting gap,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Early in the stream, allow slightly more liberal bin opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills
    // the post residual (perfect chain fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect lookahead match: strongly favor this bin
        } else {
            score += gap * 0.8; // penalize proportional to lookahead mismatch
        }
        // If next item cannot fit here anyway, mild penalty for wasted lookahead
        if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Penalize creating tiny unusable dead space (relative to smallest item ~1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post residual relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual near/below mean are
    // preferred targets (consolidate fullness).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + open_bins_count as f64 * 2.0;
        // If lookahead says next item pairs well with a fresh bin, soften penalty
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fill, unusable for typical items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Dead space that the next item cannot use: penalize.
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Prefer bins with residual close to item_size (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Encourage spreading load when many bins are open with high mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (mean_residual - post_residual as f64).abs() < 15.0 {
        score -= 3.0 * (1.0 - progress); // balance residuals early on
    }

    // Slight preference for filling existing bins over opening new ones
    // when the stream is near its end.
    if bin_residual != bin_capacity {
        score -= 2.0 + 5.0 * progress;
    } else {
        // New bin candidate: penalize mildly unless it would create a very
        // clean residual for the lookahead item.
        score += 6.0;
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    }

    // Reward consolidation when open bins count is large.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post residual (dead space penalty)
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more; quadratic-in-progress weight
    let dead_weight = 0.5 + 1.5 * progress * progress;
    score += dead_weight * (post / cap) * (post / cap);

    // Tight fit reward: cubic falloff as post_residual grows
    let tightness = 1.0 - (post / cap);
    score -= 0.6 * tightness * tightness * tightness;

    // Penalize residual that is too small to fit typical future items (dead space)
    let dead_threshold = 0.12 * cap;
    if post < dead_threshold {
        let d = (dead_threshold - post) / cap;
        score += 0.8 * d * d;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score += 0.4 * gap;
        // bonus if post residual can exactly fit next item
        if post >= nxt {
            score -= 0.3 * (1.0 - gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let mean_gap = (mean_residual - post) / cap;
    score += 0.1 * mean_gap * mean_gap;

    // New-bin candidate handling: empty bin gets a moderate default score so it
    // wins only when open bins are poor fits (large post residual / dead space)
    if (bin_residual as f64 - cap).abs() < 0.5 {
        score = 0.75 + 0.5 * progress - 0.3 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: dead space that is too small for any future item is pure waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 12.0;
    }

    // Harmonic class: how well post_residual decomposes into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Residuals near simple fractions (0.1, 0.2, 0.25, 0.5) are more reusable.
    let targets = [0.0, 0.1, 0.2, 0.25, 0.3, 0.5];
    let mut harm = 1.0f64;
    for t in targets.iter() {
        let d = (frac - t).abs();
        if d < harm { harm = d; }
    }
    score += harm * 20.0;

    // Integer-division harmonic classes on post_residual: multiples of 10 are friendly.
    let class = post_residual % 10;
    if class != 0 {
        score += (10 - class) as f64 * 0.6;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= (bin_capacity as f64 - gap as f64) * 0.15;
        if gap == 0 { score -= 15.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; residual becomes dead weight, penalize mildly.
        score += post_residual as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // or the stream is early and many items remain to fill it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64;
        // Base penalty keeps new bins from winning trivially; eases as stream progresses
        // and mean residual across open bins is small (poor fits everywhere).
        score += 30.0 + crowded * 2.0 - mean_residual * 0.3 - progress * 5.0;
        // Opening fresh bin is good if item is large and next item is large too
        // (pairing large items together in one bin).
        if item_size + next_item_size <= bin_capacity && item_size >= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that can never fit even the
    // smallest item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 200.0;
    }
    // Small-but-not-zero gaps (10..=20) are semi-dead: only tiny items fit.
    if post_residual >= 10 && post_residual <= 20 {
        score += 40.0;
    }

    // Reward exact/near-exact fits (post_residual small but usable).
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (fill existing bins) over spreading; when few bins, allow new ones.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 8.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive if all open bins would
    // leave ugly dead space or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if this bin is the only option (no fitting open bins),
        // opening new is fine.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        // This placement kills the chance for the lookahead item in this bin;
        // mild penalty unless post_residual is dead space anyway.
        if post_residual >= 10 {
            score += 15.0;
        }
    }

    // Prefer bins with below-mean residual (tighter packing).
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.3 * mean_gap;

    // Slight late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins that end with (near) zero residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this bin will be perfectly packed across both steps -> big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_post = post_residual - next_item_size;
        score -= 20.0;
        if second_post == 0 {
            score -= 25.0;
        }
        // Reward chains where remaining space stays small but usable.
        if second_post <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to next item: penalize proportionally.
        let dead = post_residual as f64 / next_item_size as f64;
        score += 10.0 * dead;
    }

    // Compare against mean residual: prefer bins tighter than average.
    let res_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fitting bins exist (mild pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, slightly worse late in the stream
        // when consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 8.0 * progress;
        // But if next item is huge and would fit a fresh bin alone, soften penalty.
        if next_item_size > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Slight preference for placing larger items into fuller bins (tighter packing).
    score += 0.1 * (item_size as f64) * (res_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable leftover space (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving scraps that the next item cannot use.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Perfect closure bonus: exact fill.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // When many bins are open, discourage opening new ones unless the fit is great.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0; // next item needs a fresh bin anyway
        }
    }

    // Slight preference for bins below mean residual (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
