pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10
    let class = (post_residual % 10) as f64;
    score += class * 0.35; // prefer leftovers that fall on clean decade boundaries

    // Fractional fill coupling: reward near-full bins strongly
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * fill * fill;

    // Dead-space penalty: leftovers below the smallest plausible item (class 1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = if post_residual == next_item_size { 14.0 } else { 0.0 };
        score -= exact + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > post_residual {
        // next item cannot use this leftover: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when few bins fit or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else {
            12.0 + mean_residual * 0.2 + 20.0 * (1.0 - progress)
        };
        score += scarcity;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    // Gaps below the minimum item size (1..10) are pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Moderate penalty for gaps that only the smallest items could use.
    else if post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 8.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers
    // a decent fit; base cost rises with open bin count to consolidate.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 1.0;
        // But if the next item is large and current residuals are small,
        // opening fresh space may be better.
        if next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
    }

    // Mild progression pressure: late in the stream, avoid waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: nearly full bins are excellent outcomes.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: mild bonus proportional to leftover after both.
            let two_left = post_residual - next_item_size;
            score -= 150.0 * (1.0 - two_left as f64 / bin_capacity as f64);
            score += 0.5 * two_left as f64;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss.min(100.0);
        }
    }

    // Relative residual coupling: prefer bins whose residual deviates
    // favorably from the fleet mean residual.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening fresh bins is only attractive
    // when the item is large and current residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let tight = (mean_residual / bin_capacity as f64) < item_frac * 0.9;
        if item_frac > 0.5 && tight {
            score -= 80.0 * item_frac + 50.0 * progress;
        } else {
            score += 150.0;
        }
    }

    // Mild penalty for wasting large residuals on small items.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * (100.0 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual gets extra bonus, non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space: residuals too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 / (1.0 + slack as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // wasted opportunity: post-residual can't hold next item
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 - mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure * (0.5 + progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 6.0 * pressure };
        score += escape;
        // A new bin is fine early on or when mean residual is high (fragmented state).
        score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Core: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Reward tight fits, stronger as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness.powf(2.0) * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            // smooth reward when post residual still fits next item
            score -= 6.0 * (1.0 - ((pr - nx) / cap)) * progress;
        }
    }

    // Last-chance bonus: prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.3 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance open bins)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 + progress);

    // Slight preference to use existing bins over opening new ones early
    score += 0.02 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
