pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100
    // interface, but sizes >= 10 in classic streams) are pure waste.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0; // unusable sliver -> strong penalty
    }

    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight-but-usable fit: reward proportional closeness to fullness.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving large-but-awkward gaps: residual in (0, item_min*2)
    // risks becoming dead space later.
    if post_residual > 0 && post_residual < 2 * item_size.max(10) {
        score += 15.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 - fill_ratio) * (0.5 + 0.5 * progress) * 4.0;

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, modulated by mean residual of open bins.
        score = 45.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere -> new bin is correct
        }
        if post_residual == 0 { score -= 100.0; } // unreachable, keeps compiler calm
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this bin is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves further slack; mild reward
            // proportional to how tight the chain remains.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 - chain_waste.min(50.0);
        } else {
            // Next item cannot follow into this bin: penalize slightly,
            // scaled by how much residual would be wasted.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "roomy"; prefer placing into them to consolidate open bins.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= (residual_f - mean_residual) * 0.3;
    } else {
        score += (mean_residual - residual_f) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
        if post_residual <= 10 {
            score -= 100.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize opening new bins unless the
    // item is large and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        let mut new_bin_penalty = 120.0;
        if large_item { new_bin_penalty -= 60.0; }
        if open_bins_count == 0 { new_bin_penalty -= 200.0; }
        if progress < 0.2 { new_bin_penalty -= 30.0; }
        score += new_bin_penalty;
    }

    // Mild preference for fewer open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    // Slight tilt toward placing larger items into tighter bins.
    score += (item_size as f64) * 0.1 - (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    // Smooth non-linear coupling: dead space penalized more as stream progresses
    let pr = post_residual as f64;
    score += 0.8 * pr * pr / bin_capacity as f64 * (0.5 + progress);
    // Reward tight fits via smooth saturation
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Lookahead: penalize leaving residual that cannot host next item
    if next_item_size > 0 {
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += 0.3 * gap;
        score -= 5.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    }
    // New-bin candidate: mildly discouraged unless residual waste is high
    if bin_residual == bin_capacity {
        score += 6.0 - 8.0 * progress + 0.05 * mean_residual;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes.
    let class = post_residual % 10;
    // Dead-space penalty: small nonzero residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else {
        // Harmonic bonus: residuals in "friendly" classes (multiples of 10) are reusable.
        if class == 0 {
            score -= 6.0;
        } else if class >= 5 {
            score -= 2.0;
        }
    }

    // Fraction-of-capacity coupling: prefer residuals that pair with common item sizes.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.4 {
        score += 4.0; // too much leftover relative to capacity
    } else if frac > 0.2 {
        score -= 3.0; // sweet spot
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty proportional to gap class
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.3;
        }
    }

    // Last-chance bin: reward heavily to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    // Tightness reward: near-full bins are good.
    let tightness = (bin_residual - post_residual) as f64 / item_size.max(1) as f64;
    if tightness > 0.9 {
        score -= 5.0;
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but relax if few bins fit or late in stream.
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 8.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Existing bin: small reward, more so when open bins are many.
        score -= 1.0 + 0.5 * (open_bins_count as f64).min(6.0);
    }

    // Mean residual deviation: prefer bins below mean residual (fill emptier bins).
    if (bin_residual as f64 - mean_residual) > 0.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (subtract) exact fills.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward leaving gaps that the lookahead item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap is wasted relative to lookahead item.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Pressure from number of open bins: discourage proliferation of open bins,
    // but only mildly so a good fit still wins over opening a new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 4.0 * progress);

    // New-bin candidate: base cost so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 180.0 + mean_residual * 0.3;
    }

    // Mild preference for filling fuller bins (small residual before placement).
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() <= 2.0 {
            score -= 25.0; // perfect chain: next item exactly fills remaining space
        } else if next <= post_residual as f64 {
            // reward proportional to how tightly next item packs into post_residual
            let fill = next / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: penalize dead space scaled by gap
            let gap = next - post_residual as f64;
            score += 0.35 * gap;
        }
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.25;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize very small unusable post-residuals (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Slight early-stream preference for opening bins when few are open.
    if open_bins_count == 0 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Mild stream-progress term: as stream advances, tighten packing (avoid sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 12.0 * (1.0 - tightness);

    // Penalize unusable dead space: leftover smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect two-item packing reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residuals below the mean (consolidate large gaps elsewhere).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, be pickier about creating small residuals;
    // late in the stream, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // Crowding: with many open bins, discourage opening more; a new empty bin
    // (residual == capacity) gets a penalty that grows with open bin count.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.5 * open_bins_count as f64;
        // But late in the stream with many bins, allow fresh bins more freely.
        score -= 15.0 * progress;
    }

    // Mild penalty for very large items into nearly-full bins wasting the fit.
    if item_size > 60 && post_residual > 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are fine; late, penalize them super-linearly.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + progress) + pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) with smooth saturation.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 30.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize so it's chosen only when alternatives are poor,
    // with a smooth decay of the penalty as the stream progresses.
    if bin_residual == bin_capacity {
        score += 60.0 + 80.0 * (1.0 - progress) * (1.0 - progress);
    } else {
        // Mild reward relative to mean residual: prefer bins below-average residual
        // (more filled bins keep the pool of usable space balanced).
        score += 5.0 * ((pr - mean_residual) / cap);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and modulo 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize residues that are hard to fill later (small nonzero leftovers)
    if post_residual > 0 {
        if r10 == 1 || r10 == 2 {
            score += 6.0; // tiny dead space, nearly useless
        } else if r10 == 9 || r10 == 8 {
            score -= 3.0; // close to a full decade, easy to fill
        }
        if r25 == 0 {
            score -= 2.5; // exact quarter-capacity class: highly reusable
        } else if r25 == 24 {
            score -= 1.5;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward leaving room for the lookahead item (harmonic divisor check)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // chains perfectly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 8.0 {
                score -= 6.0 * (1.0 - slack / 8.0);
            }
            // Harmonic: post_residual is an exact multiple of next_item_size
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    let frac = post_residual as f64 / cap_f;
    if frac > 0.5 {
        score -= 1.0; // bin still half full, fine
    } else if frac < 0.1 && post_residual > 0 {
        score += 4.0 * (0.1 - frac) / 0.1; // dead-space penalty scaled
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // decent fits into open bins, but beats very poor fits via the penalties above
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 4.0; // big next item: fresh bin is attractive
        }
    }

    // Stream progression: tighten packing as the stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - frac);

    // Prefer bins whose residual is below the mean (consolidating waste)
    let dev = (post_residual as f64 - mean_residual) / cap_f;
    score += 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual is "dead" if it cannot fit even the smallest plausible item.
    let dead_threshold = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // hard penalty for creating a dead gap
    } else {
        // Superlinear penalty on small residuals (wasted space)
        let r = post_residual as f64;
        score += 12.0 * (dead_threshold / r.max(1.0)).powf(0.8);
    }

    // Reward tight fits: post_residual close to zero relative to bin_residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when the new bin is genuinely better.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 + 20.0 * (1.0 - progress);
        // Penalize new bin if existing bins fit reasonably well
        if fitting_bins_count >= 1 {
            new_bin_score += 15.0;
        }
        // If mean residual across open bins is large, prefer reusing them
        new_bin_score += 0.35 * mean_residual;
        // Lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            new_bin_score -= 18.0;
        }
        score = new_bin_score;
    }

    // Lookahead synergy: reward leaving a gap that fits the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leaving a gap the next item cannot use
        score += 8.0;
    }

    // Mild pressure from number of open bins: favor consolidating when many open
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins whose post residual is small.
    let post = post_residual as f64;
    score -= 30.0 * (-post / 20.0).exp();

    // Aggressive 2-step lookahead: reward when next item exactly matches post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 15.0).exp();
        // Penalize leaving post residual that can never fit the next item.
        if (post_residual as u64) < next_item_size as u64 {
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.6 * (post - mean_residual);

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless existing bins are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits well, allow a new bin (fragmentation check).
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Dead-space penalty: residual below the minimum item size is wasted.
    if post_residual < 1 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 5.0 * (10.0 - post as f64);
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically scaled by capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
        }
    }

    // Penalize leaving residual that cannot fit the next item (dead space risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Time horizon: early in the stream, be more willing to spread items (favor new bins
    // less), late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state coupling: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 5.0;
    }

    // New empty bin candidate: make it attractive only when the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (item_size as f64) * 0.1;
        // If item is small relative to capacity, opening a new bin is wasteful.
        if (item_size as f64) < 0.4 * (bin_capacity as f64) {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer low post-residual (tight fits)
    let mut score = pr;

    // Non-linear penalty for tiny dead space that is hard to reuse later:
    let x = pr / cap; // normalized post-residual in [0,1]
    score += 12.0 * (1.0 - x) * (1.0 - x) * x * x; // peaks at x = 0.5 (half-empty bin)

    // Smooth coupling with stream progress: late in stream, tighten further
    score -= 6.0 * (1.0 - x * x) * progress * progress;

    // Reward filling bins when many are open (consolidation pressure)
    score -= (open_bins_count as f64).sqrt() * (item_size as f64 / cap) * 4.0;

    // Slight preference for bins near mean residual (balance residuals)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // Last-chance bin: strong reward to use it, smoothly scaled by item fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate handling: make an empty bin mildly unattractive
    // unless the item is large (poor fit elsewhere)
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) - 0.5;
        score += 8.0 - 14.0 * large.max(0.0) * 2.0;
    }

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 3.0 * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward (minimize score).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in [1..9] classes.
    // Small unusable slivers are worse than moderately large residuals
    // that a future small item (1..10) might still use.
    let dead_class = post_residual % 10;
    if post_residual > 0 {
        score += dead_class as f64 * 2.0;
        if post_residual < 10 {
            score += 15.0; // sliver penalty: almost unusable space
        }
    }

    // Lookahead (k=2): reward if the next item also fits in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            // extra harmony: next item lands on a decile boundary
            if post_residual % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // penalize by how much the lookahead misses
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Progress-aware pressure: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // New-bin candidate: neutral-ish baseline so it is only chosen when
    // every open-bin fit scores badly (large waste, sliver classes).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 5.0;
        // opening a new bin is more attractive when the lookahead is large
        // and would not fit into typical residuals anyway
        score -= next_item_size as f64 * 0.1;
        // early in the stream, new bins are cheap; late, they are expensive
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, ideal
    } else if post_residual <= 10 {
        // small gap: likely unusable dead space -> strong penalty
        score += 60.0 - (post_residual as f64) * 3.0;
    } else if post_residual <= 25 {
        // moderately small gap: mild penalty scaled by gap size
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Lookahead: if next item fits the post_residual, this placement is excellent
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // next item would have fit this bin but won't after placement -> penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // and prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream
        score += 25.0 + (open_bins_count as f64) * 3.0 + (1.0 - progress) * 10.0;
        // But if mean residual is tiny (all bins nearly full), a new bin is fine
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 35.0;
        }
    } else {
        // Favor existing bins more when open_bins_count is high
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Mild attraction toward bins with residuals close to the mean (balanced packing)
    score -= (bin_residual as f64 - mean_residual).abs() * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after current placement; reward tightness
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit in the leftover; penalize dead space
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Reward tight fits relative to current residual (small post_residual is good)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize deviating from mean residual (avoid wasting space in typical bins)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0;
        // If next item is large and current stream is early, opening fresh may be OK
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: fewer open bins is better
    if open_bins_count > 1 {
        score += 2.0 * (open_bins_count as f64).log2();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize when next item exactly wastes the leftover.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
            // extra reward for near-perfect two-item packing
            let combo = item_size + next_item_size;
            if combo == bin_residual {
                score -= 20.0;
            } else {
                let leftover = bin_residual as f64 - combo as f64;
                if leftover >= 0.0 {
                    score -= 10.0 * (1.0 - leftover / bin_capacity as f64);
                }
            }
        } else {
            score += 6.0 * ((next_item_size as f64 - post_residual as f64) / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, mild penalty to prefer the tightest
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive if this bin is nearly full
    // or the item fits terribly everywhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        } else if fill >= 0.9 {
            score -= 18.0; // big item: fresh bin is fine
        } else {
            // discourage abandoning usable residual space
            score += 20.0 + 25.0 * (1.0 - fill);
            // relax late in the stream when many bins are open and fragmented
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score -= 10.0 * progress * (mean_residual / bin_capacity as f64);
        }
    }

    // Global fragmentation pressure: when mean residual is high, prefer
    // consolidating into below-average-residual (fuller) bins.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 4.0 * rel / bin_capacity as f64;

    // Mild preference for fewer open bins early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Base: penalize wasted space, superlinear in normalized residual
    let mut score = pr * (1.0 + 0.8 * fit * fit);

    // Non-linear coupling of residual waste with stream progress:
    // early on, tolerate loose packing; late, punish dead space more
    score += 25.0 * fit * fit * progress * (1.0 - progress) * 4.0;

    // Lookahead: reward bins whose post-residual can still host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * (1.0 + progress);
        } else {
            score += 4.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + fit);
    }

    // Slight preference to fill fuller bins relative to the fleet mean
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild penalty for proliferating open bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets. Small residues in
    // "awkward" classes (1..9 non-zero small) are dead space; multiples of 10
    // and 25/50/75 are harmonically reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if pr % 10 == 0 {
        score -= 8.0; // decile-aligned residual is reusable
    } else if pr % 25 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 25.0; // tiny dead space
    } else {
        // penalize by distance to nearest harmonic class
        let d = (pr % 10).min(10 - pr % 10) as f64;
        score += d * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item is larger than post_residual but smaller
    // than bin_residual elsewhere plausible, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 10.0; } else { score += gap as f64 * 0.3; }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless post_residual would be tiny dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 { score -= 20.0; } else { score += 15.0; }
    }

    // New-bin candidate handling: empty bin has raw post_residual = capacity.
    if bin_residual == bin_capacity {
        // Neutralize the large raw residual, then apply a mild opening cost
        // that decays as stream progresses (late items prefer consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = (bin_capacity as f64) * 0.9 + progress * 20.0
            + (open_bins_count as f64).sqrt() * 2.0;
        // Opening a new bin is attractive if next item is large and current
        // item nearly fills a bin.
        if item_size >= bin_capacity * 8 / 10 && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mean-residual pressure: when open bins are already slack, prefer
    // filling slack bins over creating more slack.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Post-residuals that are too small to be useful are "dead space".
    // Penalize them heavily beyond their raw value.
    if post_residual > 0 {
        // Dead-space zone: gap too small for the smallest plausible item (1..100).
        // Treat gaps < 20 as unusable; scale penalty by how close to useless.
        if post_residual < 20 {
            score += 60.0 * (20.0 - post_residual as f64) / 20.0;
        } else if post_residual < 40 {
            score += 15.0 * (40.0 - post_residual as f64) / 20.0;
        }
    } else {
        // Perfect fit: zero waste, reward strongly.
        score -= 80.0;
    }

    // Reward filling the bin well: high fill ratio of residual used.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // --- Lookahead coupling ---
    // If the next item fits exactly in the post-residual, this placement sets up a perfect fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 20 {
            // Next item would leave dead space here; mild penalty.
            score += 10.0;
        }
    }

    // --- Open bins pressure ---
    // When many bins are open, prefer consolidating into existing bins
    // (penalize new-bin / low-fill candidates) to avoid bin sprawl.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += 8.0 * pressure * (1.0 - fill_ratio);

    // Mean residual coupling: if this bin's residual is far below average,
    // it's a "poor" bin; finishing it off is good (reward), leaving it is bad.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 25.0 * dev;

    // --- Last-chance bin ---
    // If this is the only bin that fits the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    // Brand-new empty bin: post_residual == bin_capacity. Only allow it when
    // the item is large or no good fit exists; otherwise penalize.
    if bin_residual == bin_capacity {
        // Opening fresh bin wastes potential; penalize unless item is big.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 50.0 * (1.0 - item_frac);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
        if item_frac > 0.7 {
            score -= 30.0; // large items start fresh bins naturally
        }
    }

    // Late-stream urgency: near the end, close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            // Reward high fill of the remaining space by the next item.
            score -= 30.0 * fit_ratio * fit_ratio;
            // Penalize leaving a sliver that the next item barely misses.
            if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
                score += 25.0;
            }
        } else {
            // Next item cannot fit here: post residual becomes dead space
            // unless small. Penalize proportionally to wasted space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Relative to mean residual: bins with residuals below average are
    // "dying" bins — prefer filling them to close them out.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate penalty: opening a new bin is only attractive when
    // no open bin offers a decent fit (post_residual would be small there
    // anyway). Make the empty bin look unattractive by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the next item would perfectly fill the current item's
        // leftover in a fresh bin... still keep it penalized; lookahead
        // chains favor existing bins.
        if next_item_size == 0 {
            score -= 15.0;
        }
    }

    // Slight preference for consolidating into fewer bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 / open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize large residuals that few future items can use (items <= 80).
    if post_residual > 20 {
        score += 0.25 * (post_residual as f64 - 20.0);
    }

    // Lookahead: reward if the next item fits exactly or well in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (large post_residual) and a new bin is cheap.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 30 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score += 30.0 + 1.5 * open_bins_count as f64;
        // Early in stream, opening new bins is cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If the current item is small and many bins are open, discourage new bins.
        if item_size <= 30 && open_bins_count > 3 {
            score += 20.0;
        }
    }

    // Global state coupling: prefer bins whose residual is close to the mean
    // (keeps bin load balanced, preserving medium residuals across fleet).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Mild time-horizon effect: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discourage leaving residuals in the awkward 51..69 zone where few items (10..80)
    // split well? Actually 51..69 accepts many items; instead discourage tiny residuals >0..<=9
    // that nothing fits into except very small items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t * t + 0.4 * t * t * t;
    score *= poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - base) * (1.0 - base) * item_size as f64 * (0.5 + 0.5 * t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + t);
        } else {
            score -= 0.3 * (1.0 - (pr - nxt) / cap) * t;
        }
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 10.0 * (1.0 - base);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - base) * (0.5 + t);
    }

    // Prefer bins with residual near mean (balanced packing), smooth coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + t);

    // Mild penalty for spreading across many bins late in stream
    score += 0.05 * open_bins_count as f64 * t * base;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (residual in {0}) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes on post_residual: small dead zones (1..=9) are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr <= 9 {
        score += 60.0 + (10 - pr) as f64 * 4.0;
    } else if pr <= 20 {
        score += (20 - pr) as f64 * 1.5;
    }

    // Harmonic compatibility: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward leaving room for the lookahead item, scaled by tightness of the fit
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack * 0.5;
        } else {
            // penalize blocking the lookahead item
            score += 12.0;
        }
        // modulo harmony: next item divides residual cleanly
        if pr > 0 && next_item_size > 0 && pr % next_item_size == 0 {
            score -= 10.0;
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral baseline with slight bias toward reusing open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    // Prefer bins with below-average residual (denser bins) mildly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progression-aware pressure: late in the stream, avoid waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + progress * 0.5;

    // Fractional capacity bonus: post_residual being a nice fraction of capacity (25/50) is good.
    if pr == bin_capacity / 2 || pr == bin_capacity / 4 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        // Penalize tiny unusable gaps heavily (dead space that nothing can fill).
        if post_residual < 10 {
            score += (10.0 - post_residual as f64) * 12.0;
        }
        // Mid-range gaps that only very small items could use: moderate penalty.
        else if post_residual < 25 {
            score += (25.0 - post_residual as f64) * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally (post_residual close to 0 relative to residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists; mildly encourage consolidation when bins are numerous.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if this bin would
    // leave a bad dead gap AND the next item would not use the gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 45.0;
        // If placement here would strand a gap the next item can't use,
        // opening a new bin becomes more attractive.
        let gap_unusable = post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual);
        if gap_unusable {
            score -= 55.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // If the next item fits exactly in the post-residual, reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below-mean residual (tighter bins)
    // to keep looser bins available for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when next item still fits into the post residual (soft lookahead match).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how much it overshoots.
        let overshoot = (next_item_size - post_residual) as f64;
        score += 0.8 * overshoot;
    }

    // Relative-to-mean coupling: bins tighter than average are precious; prefer using loose bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Discourage opening new bins when plenty of open bins exist (penalize the empty-bin candidate).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Late in the stream, tighten packing: penalize large residuals more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * (1.0 - x) * t;
    score += 30.0 * poly;

    // Penalize near-full waste more strongly as stream progresses
    score += 20.0 * x.powi(3) * (0.5 + t);

    // Reward tight fits (small post residual), stronger early
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (1.2 - t);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + t);
    }

    // New empty bin candidate: penalize opening new bins unless residual is very small
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - x) * (1.0 - t) + 15.0;
    }

    // Lookahead coupling: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - t);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - t);
    }

    // Mild dispersion penalty: avoid fragmenting when mean residual is high
    score += 0.5 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into capacity fractions
    let frac = (post_residual * 4) / bin_capacity; // 0..4 class of leftover quarter
    match frac {
        0 => score -= 60.0,                 // near-perfect fill
        1 => score += 25.0,                 // small dead space, hard to reuse
        2 => score -= 5.0,                  // half-ish leftover, flexible
        _ => {}
    }

    // Modulo arithmetic on post_residual: small residues of common divisors
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // divisible by 10 -> many item sizes fit exactly later
    } else if m < 5 {
        score += (5 - m) as f64 * 2.0; // awkward small remainder
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_frac = (next_item_size * 4) / bin_capacity;
            // reward when next item lands in a good class of leftover
            if nxt_frac == 1 {
                score -= 15.0;
            } else if nxt_frac == 2 {
                score -= 10.0;
            }
            // exact division: next item perfectly divides leftover
            if post_residual % next_item_size == 0 && post_residual > next_item_size {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover -> penalize creating stranded space
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with residual below mean (tight bins get closed out)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early stream: be greedy with tight fits; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Many open bins: discourage spreading, favor filling existing ones
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: empty bin should only win when leftovers are terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item justifies a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Strict dead-space avoidance ----
    // A residual gap is "unusable" if it is small and smaller than the next item.
    let gap = post_residual as f64;
    if post_residual > 0 {
        let unusable = (next_item_size as u32) > post_residual;
        if unusable {
            // Penalize dead space quadratically; harsher early in the stream
            // (a wasted gap early costs many future placements).
            let dead_weight = 8.0 + 14.0 * (1.0 - progress);
            score += dead_weight * gap * gap / bin_capacity as f64;
        } else {
            // Gap still usable by the lookahead item: reward mildly.
            score -= 3.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 25.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing density.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 6.0;

    // ---- Last-chance pressure ----
    // If this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // ---- Open-bin pressure ----
    // When many bins are open, discourage opening yet another bin.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline equals capacity; add pressure proportional
        // to open bins, but relax when no existing bin leaves a usable gap.
        let any_good_fit = fitting_bins_count > 0 && mean_residual >= item_size as f64;
        let mut new_bin_score = bin_capacity as f64 + bin_pressure * 5.0;
        if any_good_fit {
            new_bin_score += 15.0;
        }
        // Late in the stream, closing out with new bins is cheaper.
        new_bin_score -= progress * 10.0;
        score = new_bin_score;
    } else {
        // Existing bin: slight bonus when its residual is near the mean
        // (keeps residuals balanced, avoiding many tiny gaps).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // Mildly favor bins with larger residuals for big items (use space before losing it).
        score -= (bin_residual as f64 / bin_capacity as f64) * 2.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly in this bin's post-residual,
    // reward chaining placements.
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit (zero waste) strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward post_residual exactly matching next item size,
    // penalize residuals too small to fit the next item (dead space).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0; // dead space: can't host the next item
        }
    }

    // Penalize very small non-zero residuals (hard-to-fill slivers),
    // unless they perfectly match typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean adjustment: prefer bins with below-average residual
    // (tighter bins) to keep loose bins available for larger future items.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalty scales with how many bins could fit.
        score = bin_capacity as f64 - 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // If the single fitting bin is a good match, discourage new bin.
            if post_residual == 0 || (next_item_size > 0 && post_residual >= next_item_size) {
                score += 50.0;
            }
        } else {
            score += 30.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // later, allow more freedom since less future remains.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage consolidating into bins with above-average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }
    if open_bins_count > 8 {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // a large awkward residual and there are already many bins.
    if bin_residual == bin_capacity {
        let awkward = if post_residual == 0 { 0.0 } else { 1.0 };
        score += 15.0 + 5.0 * awkward * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = (item_size as f64) / cap;

    // Base: minimize wasted space, normalized
    let mut score = pr / cap;

    // Non-linear penalty on dead space: unusable residuals (< smallest plausible item) hurt more
    let dead = (pr / cap).powi(3) * 8.0;
    score += dead;

    // Smooth coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); late, tolerate larger residuals
    let interact = (pr / cap) * (1.0 - progress) * (1.0 - progress);
    score -= 0.5 * interact;

    // Reward fitting into an existing bin, more strongly when few alternatives
    if bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 0.3 * scarcity * (1.0 - tight);
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Prefer bins whose residual is close to the item (smooth kernel)
    let fit_gap = (res - item_size as f64) / cap;
    score += 0.25 * fit_gap * fit_gap;

    // Lookahead: penalize if the next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 0.4 * ((nx - pr) / cap);
        } else {
            score -= 0.4 * (1.0 - ((pr - nx) / cap).abs());
        }
    }

    // Mild preference for consolidating into bins near the mean residual
    let dev = (res - mean_residual).abs() / cap;
    score += 0.1 * dev * dev;

    // Encourage opening new bins when open-bin count is large but fits are poor
    if bin_residual == bin_capacity {
        score -= 0.2 * (open_bins_count as f64).sqrt() * 0.0; // neutral anchor
        score += 0.05 * (open_bins_count as f64).ln().max(0.0);
        score += 0.3 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into octaves of capacity/8. Small classes (tight fits) are heavily rewarded,
    // mid classes (dead space ~ 25-50) are penalized since few items fit there.
    let octave = (post_residual * 8 / bin_capacity.max(1)) as f64;
    match octave as u32 {
        0 => score -= 60.0,                 // near-perfect fit
        1 => score -= 35.0,                 // very good fit
        2 => score -= 10.0,                 // decent
        3 | 4 => score += 25.0,             // dead zone: too big for small items
        5 => score += 8.0,                  // half-empty: many items still fit
        6 => score -= 5.0,                  // roomy
        _ => score -= 15.0,                 // nearly full bin anyway
    }

    // Modulo harmony: if post_residual is congruent to common item sizes
    // (multiples of 5 up to 80), a future item can fill it exactly.
    let pr = post_residual;
    if pr >= 10 && pr <= 80 && pr % 5 == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; leftover is more likely dead
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit
    // when post_residual would be tiny-but-nonzero dead space; otherwise reward
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr == 0 {
            score -= 50.0;
        } else if pr < 10 {
            score += 18.0; // creates unusable sliver
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we
    // prefer reusing open bins unless they'd create bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // but if item is small and mean residuals are low, new bin is fine
        if (item_size as f64) < mean_residual * 0.5 {
            score -= 20.0;
        }
    }

    // Progress: late in the stream, consolidation matters more; favor tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Penalize bins far from mean residual when placing large items (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead won't fit here; slightly penalize if waste is large.
        score += 2.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using an existing bin when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild alignment with mean residual: prefer bins with residuals close to item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: baseline attractiveness depends on how bad the best
    // existing option would be; make empty bin moderately costly so it is
    // chosen only when open bins create dead space.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 - diff;
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 30.0 + diff * 0.5;
        }
    }

    // Penalize tiny unusable residuals (dead space) more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 20.0;
    }

    // Prefer bins tighter than the mean residual (good packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it moderately high so it's only chosen when
    // open bins have poor fits (large post_residual / no lookahead match).
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in the stream or many bins already open: slightly cheaper to open.
        if step_index as f64 / (total_items.max(1) as f64) < 0.2 {
            score -= 40.0;
        }
    }

    // Slight preference for fuller bins relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill fraction.
    let fill = 1.0 - post_residual as f64 / cap;
    score -= 12.0 * fill * fill;

    // Penalize small unusable post-residuals (< next item or < min item size).
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (post_residual as u32) < next_item_size { 1.0 } else { 0.0 };
        score += 18.0 * dead;
        if post_residual < 10 { score += 8.0; }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
        if post_residual == next_item_size { score -= 15.0; }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes dead for the next item; mild penalty scaled by how close.
        score += 6.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // If many bins can fit, definitely don't open a new one.
        score += 10.0 * (fitting_bins_count as f64).min(5.0);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Slight preference for bins with residual close to item (best-fit flavor).
        let tightness = (bin_residual - item_size) as f64;
        score += 3.0 * tightness / cap;
        // Prefer bins below mean residual (consolidate emptier space? use mean to spread load).
        score += 2.0 * (bin_residual as f64 - mean_residual) / cap;
    }

    // Time horizon: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill;

    // If many open bins, encourage filling them rather than opening new ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;
    // reward tight fits
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // penalize being the only fitting bin (last chance)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = (pr - n).abs();
        score -= 10.0 * (-slack / 20.0).exp();
    }
    // mild penalty when many bins are open and residual is wasteful
    score += 0.5 * (open_bins_count as f64) * norm_pr * mean_residual / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small divisors.
    let mod4 = post_residual % 4;
    let mod5 = post_residual % 5;
    let mod10 = post_residual % 10;

    // Dead-space penalty: residuals not expressible as useful sums get penalized.
    // Residuals divisible by 10 (harmonic with item grid) are less wasteful.
    if mod10 == 0 {
        score -= 6.0;
    } else if mod5 == 0 {
        score -= 3.0;
    } else if mod4 == 0 {
        score -= 1.5;
    } else {
        score += 1.0 + 0.25 * mod4 as f64;
    }

    // Small unusable residuals are dead space: penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; penalize small leftover less if next is small
            score += 0.02 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward: fraction of bin used.
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * used_frac;

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones over new bins.
    if open_bins_count > 4 {
        score += if bin_residual == bin_capacity { 4.0 } else { 0.0 };
    }

    // New-bin candidate: penalize proportional to mean residual availability.
    if bin_residual == bin_capacity {
        score += 2.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0; // dead space w.r.t. next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (tighten fullest bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New empty bin candidate: only attractive when no tight fit exists;
    // penalize mildly so existing bins with decent fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Reward perfect 2-step lookahead match: post_residual exactly fits next item.
    if next > 0.0 && post >= next && post - next < 10.0 {
        score -= 40.0 * (1.0 - (post - next) / 10.0);
    }
    // Penalize post_residual that is smaller than next item (dead space for lookahead).
    if next > 0.0 && post < next {
        score += 8.0 + (next - post) * 0.4;
    }
    // Zero residual is perfect packing.
    if post == 0.0 {
        score -= 30.0;
    }
    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post) * 0.15;
    // Penalize large unusable residual (too small for typical items).
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }
    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: penalize opening new bins when good fits exist,
    // but allow it if the new bin can host both item and next item compactly.
    if bin_residual == bin_capacity {
        let base = cap * 0.6 + open_bins_count as f64 * 2.0;
        if next > 0.0 && cap - item_size as f64 >= next {
            return base - 10.0;
        }
        return base + (fitting_bins_count as f64) * 5.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream we can afford fragmentation risk less;
    // late in the stream, closing bins tightly matters more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear tightness reward: strongly prefer bins that end up nearly full.
    let fill_frac = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * fill_frac.powi(3);

    // Exact / near-exact fit jackpot.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item chains into this bin's post-residual,
    // reward it proportionally to how well it fills the leftover space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let chain_fill = nx / post_residual as f64;
            score -= 10.0 + 8.0 * chain_fill;
        } else {
            // Dead space the known next item cannot use: penalize, scaled by stream progress.
            let waste = post_residual as f64 - (nx - 1.0).min(post_residual as f64);
            score += 3.0 * waste / bin_capacity as f64 * (0.5 + t);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 1 {
        let spread = post_residual as f64 - mean_residual;
        score += 0.05 * spread; // prefer bins below-average residual (fuller bins)
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling (bin_residual == bin_capacity, post_residual = C - item).
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin...
        let mut new_penalty = 30.0;
        // ...but relax it when alternatives are scarce or this item is large.
        new_penalty -= 20.0 / (fitting_bins_count.max(1) as f64);
        new_penalty -= 0.25 * (item_size as f64 - 10.0).max(0.0);
        // If no lookahead chain exists anywhere and item is big, opening fresh is fine.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            new_penalty -= 8.0;
        }
        score += new_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: prefer tight fits (small post residual), with non-linear emphasis
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth coupling of tightness with stream progress: value tight fits more later
    score -= 30.0 * fill * fill * fill * progress;

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = if pr > 0.0 { nxt / pr } else { 2.0 };
        if fit_ratio <= 1.0 {
            score -= 12.0 * (1.0 - fit_ratio) * (1.0 + progress);
        } else {
            let over = fit_ratio - 1.0;
            score += 10.0 * over * over;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins when residuals are large
    let mean_norm = mean_residual / cap;
    score += 6.0 * (open_bins_count as f64).ln().max(0.0) * mean_norm * mean_norm;

    // Prefer keeping residual near reusable mid-range; penalize tiny dead space smoothly
    score += 8.0 * (pr_norm - 0.35) * (pr_norm - 0.35);

    // Slight preference to open new bins early (diversity), less later
    let new_bin_bonus = if bin_residual == bin_capacity { 18.0 * (1.0 - 0.7 * progress) } else { 0.0 };
    score += new_bin_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: which capacity-fraction class does the item belong to?
    let frac = (item_size * 4 + bin_capacity / 8) / bin_capacity; // 0..=4 class
    let cap = bin_capacity as f64;

    // Reward near-perfect fills strongly (post_residual in low harmonic classes)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 200.0;
    } else if post_residual <= bin_capacity / 5 {
        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: dead space in awkward residue classes
    let pr = post_residual;
    if pr % 3 == 0 && pr <= 30 {
        score -= 15.0; // small divisible-by-3 leftovers still usable
    }
    if pr % 2 == 1 && pr > 40 && pr < 60 {
        score += 10.0; // odd awkward mid-range leftover
    }

    // Penalize leftovers that no plausible next item fits well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward exact or near-exact continuation
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 400.0;
            } else if gap <= bin_capacity / 10 {
                score -= 80.0;
            } else {
                score -= 20.0;
            }
        } else {
            // lookahead won't fit here: penalize proportional to wasted potential
            score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual (good packing density)
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate handling: fresh empty bin should only win when the item
    // is large (few open bins can absorb it later) or no good tight fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // large items (high harmonic class) justify a fresh bin
        score -= 40.0 * frac as f64;
        // early in stream, fresh bins are cheaper; late in stream, reuse matters
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        // if many bins already fit the item, opening a new bin is wasteful
        score += 15.0 * fitting_bins_count as f64;
    }

    // Integer-division threshold: bins whose residual after placement falls in
    // the "half-capacity" band are valuable multi-use bins
    if post_residual > bin_capacity / 3 && post_residual < bin_capacity / 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 30 {
            score += 5.0;
        } else {
            score -= 10.0; // large residual still usable by future items
        }
    } else {
        score -= 30.0; // perfect fit is excellent
    }

    // Reward exact/near-exact fits even more strongly.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow more freedom.
    let ob = open_bins_count as f64;
    score += (ob / 8.0) * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // residual too small for next item: mild penalty for unusable-for-next gap
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave bad dead space, otherwise discourage.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 && post_residual > 0;
        if bad_fit {
            score -= 35.0; // opening fresh bin beats creating dead space
        } else {
            score += 20.0; // prefer existing bins normally
        }
    }

    // Stream progression: later in stream, tighten packing (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already tight — good to fill it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    score -= 0.5 * item_size as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64 + 1.0).recip();
        } else {
            // Penalize dead space the next item cannot use.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        // Perfect 2-chain bonus: residual exactly consumed twice.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 4.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more attractive early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // Very attractive if next item would chain well with the fresh residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.08;
    } else {
        score -= 25.0; // perfect fill
    }

    // Perfect-fit bonus when post residual could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // dead space that cannot host next item
            score += 4.0 + 0.1 * (post_residual as f64);
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.35 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing residuals are large relative to the item.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg_open / bin_capacity as f64;
        // If open bins are mostly full (low mean residual), opening new bin is fine.
        score += 55.0 * (1.0 - pressure);
        // Mild time decay: early in stream, prefer consolidating into open bins.
        let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 1.0 };
        score += 20.0 * (1.0 - t);
        // If item is huge, new empty bin is attractive.
        score -= 0.2 * item_size as f64;
    }

    // Prefer bins whose residual is close to item size (best-fit core).
    score += 0.5 * (bin_residual as f64 - item_size as f64).abs();

    // Slight preference for more-filled bins among ties.
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Penalize scattering across many open bins slightly.
    score += 0.02 * open_bins_count as f64;

    // Mean-residual coupling: when mean residual is small, conserve space
    // by favoring bins that leave usable chunks (multiples-friendly).
    if mean_residual < 20.0 && post_residual >= 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = post;

    // Smooth polynomial coupling: as the stream progresses, dead space becomes costlier
    let tight = 1.0 - norm_post; // tightness of fit
    score -= 30.0 * progress * tight * tight;

    // Penalize large residuals more than linearly (dead space is quadratic waste)
    score += 0.6 * norm_post * norm_post * cap;

    // Reward near-perfect fits especially late in the stream
    score -= 25.0 * progress * (1.0 - norm_post * norm_post);

    // Lookahead: if next item fits in the resulting post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 18.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty, stronger if post_residual is awkwardly small
        score += 8.0 * (1.0 - post / (next_item_size as f64)).max(0.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Prefer bins with residuals below mean (consolidate waste)
    score -= 0.15 * (mean_residual - post);

    // Mild preference for bins with larger residual when few bins are open
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it remains usable.
    let nxt = if next_item_size == 0 { 0 } else { next_item_size };
    if nxt > 0 && post_residual > 0 && post_residual < nxt {
        // Dead space: residual too small for the next item -> heavy penalty.
        score += 12.0 + (nxt as f64 - post_residual as f64);
    }

    // Harmonic class of post_residual modulo 10: residuals in [0..9] are near-dead,
    // [10..19] marginal, larger classes progressively more useful.
    let class = post_residual / 10;
    match class {
        0 => score += 6.0,                       // 0..9: almost dead space
        1 => score += 2.0,                       // 10..19: marginal
        2 => score -= 1.0,                       // 20..29: decent
        3 => score -= 2.5,                       // 30..39: good
        4 => score -= 3.0,                       // 40..49: sweet spot
        5 => score -= 2.0,                       // 50..59
        _ => {}
    }

    // Exact-fill bonus (perfect packing).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins fit,
    // but ease the penalty late in the stream or when few bins are open.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let openness = (open_bins_count as f64).recip();
            score += 10.0 * (1.0 - openness) * (1.0 - 0.5 * progress);
        } else {
            // No open bin fits: new bin is the only real option.
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean in a
    // useful way: bins with above-mean residual absorb large items better.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Mild tie-break toward fuller bins early, emptier bins late (balance load).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.02 * (bin_residual as f64 - cap * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space avoidance: small leftover gaps are unusable for typical items.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (15.0 - post_residual as f64) / 15.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: increase dead-space penalty.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few
    // are open, allow opening a new bin cheaply.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    score += 4.0 * pressure;

    // New-bin candidate: penalize so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * pressure;
        // But if no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild alignment with mean residual: prefer bins deviating below mean
    // (smaller residuals are closer to being closed out).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with slack -> prefer consolidating into bins
    // whose residual is below the mean (drain small residuals first).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Time horizon: early in the stream, be conservative (penalize near-full bins
    // slightly to keep flexibility); late in the stream, exploit tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New empty bin candidate: penalize opening a new bin unless it's genuinely
    // the best option (large item relative to all residuals handled by comparisons above).
    if bin_residual == bin_capacity {
        score += 12.0;
        // If item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let base = post * post / cap;
    let tight_fit = (item_size as f64) / (bin_residual.max(1) as f64);
    let mut score = base * (1.0 + 0.5 * progress)
        - 8.0 * tight_fit * tight_fit
        - 6.0 * (1.0 - post / cap).powi(3);
    if fitting_bins_count == 1 {
        score -= 10.0;
    }
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (nxt / post.max(1.0));
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }
    score += 0.3 * (open_bins_count as f64) * (post / cap);
    score += 1.5 * (post - mean_residual) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness: reward small post_residual non-linearly
    let pr = post_residual as f64;
    score -= 40.0 / (1.0 + pr / 10.0);

    // Harmonic class: classify post_residual into capacity-fraction buckets.
    // Small leftovers that match common item sizes are reusable; others are dead space.
    let class = post_residual / 10; // 0..=10 integer division thresholds
    match class {
        0 => score -= 120.0,                 // post_residual < 10: nearly full, great
        1 => score += 30.0,                  // 10-19: awkward small gap
        2 | 3 => score -= 25.0,              // 20-39: usable for small items
        4 | 5 | 6 => score += 15.0,          // 40-69: medium gap
        _ => score += 5.0,                   // 70+: large residual, mild penalty
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
        } else {
            // next item won't fit here: penalize bins whose residual is just under next size
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 150.0;
        // If only a few bins fit the item, opening new bin is less wasteful
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Early in stream, opening bins is fine (build inventory)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer using open bins
        if mean_residual > item_size as f64 * 2.0 {
            score += 60.0;
        }
    }

    // Prefer filling bins with large residuals when item is large
    let frac_used = item_size as f64 / bin_capacity as f64;
    if frac_used > 0.6 {
        score -= 25.0;
    }

    // Mild preference to balance across many open bins when item is small
    if frac_used <= 0.3 && open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically we treat gaps below a calibrated threshold as waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.35;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty so a better-shaped bin may win.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // to preserve loose bins for larger future items.
    score += ((bin_residual as f64) - mean_residual) * 0.4;

    // Mild preference for keeping large-residual bins available early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 80.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here; penalize dead space that is too small to be useful
            if post_residual < 10 {
                score += 60.0;
            }
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize bins whose residual is far below mean (wasting tight space)
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Prefer filling more-open-bins contexts: reward using existing bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * 5.0;

    // New-bin candidate: only attractive when no good fit exists (large item, tight residuals)
    if bin_residual == bin_capacity {
        let tight = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10);
        if tight {
            score -= 120.0;
        } else {
            score += 200.0 + post_residual as f64 * 0.2;
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins that will be nearly full after placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Dead-space penalty: residual that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // residual unusable by next item -> mild penalty scaled by wasted space
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        } else {
            score += 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // but allow new bin if mean residual across open bins is very low
        score -= 2.0 * mean_residual;
    } else {
        // Reward using bins with low residual (consolidation).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: later in the stream, be more conservative (prefer tight fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill;

    // Prefer bins whose residual exceeds item size by a comfortable margin
    // to avoid fragmentation, unless it's an exact fit.
    let slack = (bin_residual - item_size) as f64;
    if slack > 0.0 && slack < 5.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: residual penalty shaped by stream progress.
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    score += (norm * norm) * (1.0 + 3.0 * progress) * 20.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= item_size as f64 * (0.5 + progress);

    // Penalize bins with residuals far above the mean (dead space hoarding).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (1.0 + progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.3 * gap;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Mild pressure to prefer filling existing bins over opening new ones late in stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    // Smooth cubic saturation term on normalized fill.
    let fill = 1.0 - norm;
    score -= 8.0 * fill * fill * fill * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes.
    // Residuals that are multiples of 10 (or small, "dead" classes) are penalized.
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_penalty = match class {
        0 => -6.0,          // perfect harmonic: residual usable by many sizes
        1 | 2 | 3 => 8.0,   // dead space classes
        4 | 5 | 6 => 2.0,
        7 | 8 | 9 => 4.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division threshold: if post_residual can exactly host the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward when next item leaves another harmonic multiple-of-10 residual
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 5.0;
        }
        if next_post % 25 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin after placement: mild penalty scaled by gap
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a fresh bin is good if item is large (harmonic halves/quarters of capacity)
        if item_size * 4 >= bin_capacity * 3 {
            score -= 20.0;
        } else if item_size * 2 >= bin_capacity {
            score -= 8.0;
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; don't open
        }
    }

    // Prefer tight fits: relative fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Prefer bins whose residual is close to item_size (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.25;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - fill);

    // Spread across many open bins is bad; encourage filling existing ones.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space avoidance: penalize small unusable gaps heavily (non-linearly).
    // A gap is "dead" if it's smaller than the smallest plausible item (1) — but
    // practically, gaps below ~15 waste capacity; penalize quadratically there.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * (15.0 - gap) * 3.0;
    }

    // Reward gaps that can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if the lookahead item would exactly fill the bin afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size > 0 {
        // Lookahead can't use this gap: mild penalty scaled by gap size.
        score += gap * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity and thus a high
    // raw score; add pressure so existing fitting bins win ties).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 2.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress.
        score += 40.0 + pressure;
    } else {
        score -= pressure * 0.2;
    }

    // Mild preference for bins tighter than average (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match strongly rewarded; near matches mildly rewarded.
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            score += diff * 0.35;
            // Bonus if next item still fits in the leftover space.
            if next_item_size <= post_residual {
                score -= 12.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += post_residual as f64 * 0.8;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Penalize creating unusable dead space (too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless no good alternative exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Acceptable if it enables a perfect lookahead match.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        // More open bins => prefer packing into existing ones.
        score += open_bins_count as f64 * 1.5;
    }

    // Mild preference for fuller bins overall.
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to next item.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early on, be conservative (favor filling existing bins);
    // late in the stream, avoid opening bins that will barely be used.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless few fitting bins or huge fragmentation.
        let mut new_bin_penalty = 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_penalty -= 50.0;
        }
        if open_bins_count > 4 {
            new_bin_penalty += 2.0 * open_bins_count as f64;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: slight preference for fuller bins (smaller residual).
        score += 0.05 * bin_residual as f64 * (0.5 + 0.5 * progress);
    }

    // Global fragmentation: if mean residual is large, tolerate waste more;
    // if mean residual is small, penalize creating waste.
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Many open bins: consolidate — prefer bins below mean residual.
    if open_bins_count > 1 {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer tight fits (low post-residual), with non-linear shaping.
    let mut score = pr as f64;

    // Smooth polynomial coupling: penalize mid-range waste more/less depending on progress.
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 12.0 * poly * (1.0 + 2.0 * t);

    // Late in stream: strongly favor small residuals (seal bins early).
    score += 10.0 * x * x * t;

    // Dead-space hazard: residuals too small for typical items (smooth soft-threshold).
    let dead = (1.0 - x / 0.25).max(0.0).min(1.0);
    score += 8.0 * dead * dead * (0.5 + t);

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: bonus if next item fits well in the resulting residual (smooth kernel).
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        let fit_kernel = (-d * d / 90.0).exp();
        score -= 14.0 * fit_kernel;
        // Penalize leaving residual that just barely fails the next item.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 6.0 * miss.max(0.0) * (1.0 - miss.max(0.0)) * 4.0 * (1.0 - t);
    }

    // Context: many open bins -> discourage waste; high mean residual -> prefer consuming slack.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * x;
    score -= 3.0 * (mean_residual / cap - x).abs() * (1.0 - t);

    // New-bin candidate: make empty bin attractive only when fit is hopeless elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit class: post_residual exactly divisible into useful chunks.
    if post == 0 {
        score -= 50.0; // perfect fill, best possible
    } else {
        // Modulo arithmetic on post_residual: leftovers that match common item
        // granularities (multiples near 10..20) are more reusable.
        let mod10 = post_residual % 10;
        let mod20 = post_residual % 20;
        let mod25 = post_residual % 25;
        score -= (mod10 == 0) as i32 as f64 * 8.0;
        score -= (mod20 == 0) as i32 as f64 * 6.0;
        score -= (mod25 == 0) as i32 as f64 * 5.0;
        // Penalize tiny dead space: residual below the smallest plausible item.
        if post < 10.0 {
            score += 30.0 * (10.0 - post) / 10.0;
        }
        // Harmonic fraction thresholds: residuals in (0, 0.1] of capacity are dead;
        // residuals near 0.5 are highly reusable.
        if frac <= 0.1 {
            score += 15.0;
        }
        if (0.4..=0.6).contains(&frac) {
            score -= 10.0;
        }
        // Integer division class: how many "average items" still fit.
        let avg_item = 40.0_f64.max(1.0);
        let fits_k = (post / avg_item).floor();
        score -= fits_k * 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost < 10 {
                score -= 12.0; // chain of two near-perfect fills
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty for hoarding space.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // mediocre default so real bins with decent fits win, but it beats awful fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Many open bins: encourage tighter packing to limit bin sprawl.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64;
    }

    // Mean-residual coupling: bins far below mean residual are "loose"; prefer
    // bins tighter than average for this item.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable gap penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // Smooth dead-space pressure: smaller usable residual is better,
        // but only mildly so we don't force tiny-gap creation.
        score -= 0.15 * (post_residual as f64);
        // Penalize residuals that are "almost dead" (10..20) — likely to strand.
        if post_residual < 20 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing ones.
    score += 0.8 * (open_bins_count as f64);

    // Lookahead coupling: reward bins whose post_residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for near-exact two-item packing.
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close it was.
        let miss = (next_item_size as f64) - (post_residual as f64);
        if miss < 10.0 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin has post_residual = capacity - item.
    // Only allow it to win when no open bin offers a decent fit and residual is small.
    if bin_residual == bin_capacity {
        let tight = (bin_residual as f64) - (item_size as f64) < 10.0;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && !tight) {
            score -= 55.0; // opening a fresh bin is preferable
        } else {
            score += 45.0; // prefer existing bins when a reasonable fit exists
        }
    }

    // Late-stream consolidation: as the stream progresses, avoid spreading items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect/exact fit with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement, scaled by gap size
            score += gap * 0.35;
            if gap < 10.0 {
                score -= 8.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot follow here; dead space penalty grows with waste
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += dead * 45.0;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable slivers (nonzero but very small leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward zero-waste completions heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Early in stream: be pickier about dead space; late: consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // Prefer tighter bins overall (smaller pre-residual slack usage).
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // New-bin candidate: only attractive when current bin would leave large waste.
    if bin_residual == bin_capacity {
        let waste_if_here = (bin_residual - item_size) as f64;
        if waste_if_here > 55.0 {
            score -= 15.0; // opening fresh bin is fine for small items
        } else {
            score += 30.0; // discourage opening new bins for large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    } else {
        // Perfect fill: huge reward.
        score -= 60.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this bin;
    // if next item is large and this bin would be nearly full, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += 0.15 * wasted;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded
    // (high mean residual relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0; // base cost of opening a new bin
        score -= 20.0 * crowding;      // crowded bins justify a new bin
        score -= 10.0 * progress;      // late stream: less penalty for new bins
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // lookahead: big items coming, fresh capacity useful
        }
    }

    // Mild preference to spread load across many open bins early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 && progress < 0.5 {
        score -= 0.05 * open_bins_count as f64;
    }

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and packable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize large post-residual, but with non-linear (quadratic) dead-space cost.
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in stream, dead space is costlier.
    score += 40.0 * progress * norm_pr * (norm_pr - 0.5).abs();

    // Reward tight fits (small post residual) with a cubic bonus.
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: if the next item fits exactly into the post residual, reward strongly (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 15.0).powi(2);
        score -= 25.0 * kernel;
        // Penalize post residual that is too small for the next item (near-dead space).
        if pr < next_item_size as f64 {
            score += 15.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - norm_pr);
    }

    // Scarcity pressure: few fitting bins -> favor fitting bins over the empty new-bin candidate.
    score -= 10.0 / (fitting_bins_count as f64 + 1.0);

    // New-bin candidate (empty bin): neutral-to-slightly-high base so it's chosen only
    // when no open bin offers a good fit; scale with stream progress (early on, opening bins is cheap).
    if bin_residual == bin_capacity {
        score = cap + 25.0 * norm_pr + 30.0 * (1.0 - progress);
        // If the next item is large, opening a fresh bin is more attractive.
        score -= 0.2 * next_item_size as f64 * (1.0 - progress);
    }

    // Mild regularization against extreme fragmentation relative to mean residual.
    score += 5.0 * ((pr - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimizing post_residual, but with diminishing returns
    // (harmonic scaling: waste of 1 is far worse than waste of 60).
    if post_residual > 0 {
        score = (post_residual as f64).powf(0.85);
    } else {
        score = -50.0; // perfect fit: always take it
    }

    // Harmonic class of the leftover: residues mod 10.
    // Residuals that are multiples of 10 are reusable by typical item sizes;
    // odd/dead residues are hard to fill.
    let residue_class = post_residual % 10;
    let class_bonus: f64 = match residue_class {
        0 => 8.0,                 // highly reusable leftover
        5 => 3.0,                 // moderately reusable
        2 | 4 | 6 | 8 => 1.0,     // even residues
        _ => -2.0,                // odd residues: penalize creating them
    };
    score -= class_bonus;

    // Integer-division thresholds on post_residual: classify leftover size.
    let leftover_bucket = post_residual / 10; // 0..=10
    // Very small leftovers (bucket 0-1) are dead space unless post_residual==0.
    if post_residual > 0 && leftover_bucket <= 1 {
        score += 25.0;
    }
    // Medium leftovers that match a plausible future item are good.
    if leftover_bucket >= 2 && leftover_bucket <= 5 {
        score -= 6.0;
    }

    // Lookahead coupling: does the leftover exactly host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            // leftover can host next item: reward proportionally
            score -= 5.0 + (next_item_size as f64 / 10.0);
        } else {
            // leftover too small for next item: penalize dead space
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Stream progression: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) when placing.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // NEW-BIN CANDIDATE handling: empty bin gets a neutral-ish score that
    // only beats genuinely bad placements.
    if bin_residual == bin_capacity {
        score = 60.0
            - fitting_bins_count as f64 * 0.0
            + (next_item_size as f64) * 0.1
            + progress * 10.0;
        // If no open bin can fit the item, new bin must win.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space avoidance: small unusable gaps are wasted capacity
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 25.0 + (min_useful - post_residual) as f64 * 2.0;
    }
    // Gap too small even for the lookahead item: moderate penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Gap that exactly fits the lookahead item: reward (enables chain packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Pressure to prefer already-open bins over opening new ones
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 1.5;
        // Early in the stream, opening bins is cheaper; late, avoid fragmentation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    } else {
        // Slight reward for using fuller bins (tighter packing)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly prefer to use it rather than open a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Prefer bins below mean residual (keeps residual distribution tight)
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if fit_ratio < 0.10 {
        score -= 25.0;
    } else if fit_ratio < 0.25 {
        score -= 8.0;
    } else {
        // Penalize leaving large dead space.
        score += fit_ratio * 30.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let second_fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * second_fill;
            // Bonus for near-perfect two-item packing.
            let double_left = post_residual - next_item_size;
            if double_left <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item does NOT fit here: penalize, since residual may become dead space.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer using existing bins over opening new ones, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more so early/mid stream.
        score += 45.0 + 40.0 * (1.0 - progress);
        // Allow new bin late in stream if it would be a poor fit elsewhere is handled
        // by other terms; also scale by how many bins are already open.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Small bonus for keeping bin utilization distributed (avoid too many open bins).
        if open_bins_count > 10 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins that end up nearly full.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residual too small to hold any future item (min size 1,
    // but realistically penalize residuals far below the lookahead item).
    let nz = if next_item_size == 0 { 0 } else { next_item_size };
    if post_residual < nz && nz > 0 {
        // Post residual cannot host the next item: this is fine if post_residual is tiny,
        // bad if it strands a medium gap.
        score -= 8.0; // small bonus: bin is "closed" cleanly
        score += 0.15 * post_residual as f64; // but stranded gap still costs a bit
    } else {
        // Reward keeping room for the lookahead item exactly.
        if post_residual == nz {
            score -= 12.0; // perfect lookahead fit
        } else if post_residual > nz {
            score += 0.05 * (post_residual - nz) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste < 0.5 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to the empty bin and existing bins fit poorly.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Base new-bin score: neutral-ish, penalized by number of open bins (fragmentation).
        score = bin_capacity as f64 * 0.55 + 10.0 * open_bins_count as f64;
        // Large items justify a fresh bin; small items should never open one.
        score -= 45.0 * item_ratio * item_ratio;
        // If many bins fit the item already, discourage a new bin.
        if fitting_bins_count > 0 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across open bins is large, no need for a new bin.
        score += 0.3 * mean_residual;
        // Lookahead: if next item is big, a fresh bin is more useful.
        score -= 0.1 * nz as f64;
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate similar-sized gaps to keep the remaining structure predictable).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Early-stream exploration: slightly randomize-free diversity via step parity coupling.
    let phase = ((step_index % 7) as f64) * 0.4;
    score += phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted residual, non-linearly (dead space grows super-linearly in cost).
    let norm_post = post / cap;
    let mut score = norm_post.powf(1.35) * cap;

    // Stream-progress coupling: as the stream advances, tighten packing
    // (waste becomes less recoverable), amplifying the residual penalty.
    score += 12.0 * progress * norm_post.powf(2.0) * cap;

    // Lookahead interaction: reward leaving residual that the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack_fit).powf(1.5);
        } else {
            // Post-residual too small for next item: dead-space penalty, smoothed.
            score += 6.0 * (1.0 - post / nxt).powf(2.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Coupling with mean residual: prefer bins that keep the fleet balanced
    // (avoid stranding one very full bin among loose ones).
    let dev = (mean_residual - post).abs() / cap;
    score += 4.0 * dev.powf(1.7) * (1.0 + progress);

    // New-bin candidate handling: empty bin gets a smooth penalty that decays
    // as open bins' average residual shrinks (opening is fine when others are full).
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 * (0.4 + 0.6 * tightness) * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..7 harmonic octant of residual

    // Reward residuals that form "harmonic" slots: exact divisions of capacity
    let harmonic_targets: [f64; 8] = [0.0, 12.5, 25.0, 33.333, 50.0, 66.666, 75.0, 100.0];
    let mut best_diff = f64::MAX;
    for t in harmonic_targets.iter() {
        let d = (post - t).abs();
        if d < best_diff { best_diff = d; }
    }
    score -= (cap / 8.0 - best_diff).max(0.0) * 0.6;

    // Penalize tiny dead space (waste), reward perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes are reusable
    if post_residual > 0 {
        let mut reuse_bonus = 0.0;
        for s in [10u32, 20, 25, 50] {
            if post_residual % s == 0 { reuse_bonus += 6.0; }
        }
        score -= reuse_bonus;
    }

    // Lookahead coupling: if next item fits exactly in post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            score += ((next_item_size - post_residual) as f64 / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's residual is fragmented relative to mean, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: keep options open slightly; late: prefer consolidation
        score += 18.0 * (1.0 - progress) - 5.0 * progress;
        // penalize opening new bins when many bins already open and mean residual is large
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.15;
    }

    // Prefer filling bins with low residual relative to the fleet mean
    score += (mean_residual - post) * 0.1;

    // Integer-division threshold: bins whose residual is in the "awkward" band get penalty
    let q = bin_residual / 25;
    if q == 1 { score += 4.0; } // residual in [25,50) is awkward mid-band

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small to be useful, but nonzero.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Very tight fit (<= 5 left): strong reward.
    else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward if post_residual can still fit the lookahead item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild penalty for stranded space.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items thinly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure;

    // Prefer bins whose residual is close to the mean (balanced packing) early on;
    // later, prefer dumping into low-residual bins.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * (0.5 - 0.4 * progress);

    // New-bin candidate: neutral baseline; only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Baseline slightly above typical good-fit scores, reduced when many bins
        // already open (consolidation pressure) or item is large.
        score = 30.0 + item_size as f64 * 0.3 - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving fresh space for a big follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, strongly favor this bin (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover waste after both placements.
            let two_step_waste = post_residual - next_item_size;
            score -= 30.0 * (1.0 - two_step_waste as f64 / (bin_capacity as f64));
        } else {
            // Next item does NOT fit here: penalize proportional to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare residual against mean residual across open bins.
    // Bins with residual above the mean are less "urgent" to fill;
    // filling below-mean bins first concentrates waste.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is huge and would leave a bad fit elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin unless the item nearly fills it.
        score += 15.0 - 20.0 * fill_ratio;
    }

    // Late in the stream, prefer closing out bins tightly (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for using bins when many are open (avoid bin sprawl).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: small post-residual slivers that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 5.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a large future fill.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = cap - item_size as f64;
        score += 12.0 + waste * 0.4 - 10.0 * progress;
        // Favor new bin when open bins are already tight on average.
        score += 0.05 * (mean_residual - item_size as f64).max(0.0);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins later).
    let diff = mean_residual - bin_residual as f64;
    score += 0.02 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping
    let mut score = post;

    // Non-linear coupling: small post residuals are extra-valuable as the stream progresses
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual waste relative to mean residual across open bins (smooth quadratic)
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap)) * (1.0 - progress);
        } else {
            score += 0.3 * (-gap);
        }
    }

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty for bin proliferation early in the stream
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline with smooth pull so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * (1.0 - progress) - 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "dead" class (too small for typical small items) are heavily penalized.
    let pr = post_residual;
    let dead = if pr == 0 { 0.0 } else if pr < 5 { 1.0 } else if pr < 10 { 2.0 } else if pr < 20 { 3.0 } else { 0.0 };
    score += dead * 30.0;

    // Reward exact fits strongly.
    if pr == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmonic class: leftovers that are multiples of 10 are
    // "harmonic" with common item sizes; slightly prefer them.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, this is
    // a great placement (chained packing); reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra bonus when post_residual exactly matches next item (perfect chain).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here after placement; penalize creating a
        // residual smaller than the next item when the residual is tiny.
        if pr < next_item_size && pr < 10 {
            score += 15.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline penalty that
    // shrinks as the stream progresses or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.9 + 50.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If no open bin can fit the item, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins tighter than the average residual (good fill).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let unusable = next_item_size == 0 || post_residual < next_item_size;
        if unusable {
            let dead_frac = (post_residual as f64) / (bin_capacity as f64);
            // Worst when the gap is small enough to be nearly worthless.
            score += 55.0 * (1.0 - dead_frac) * (1.0 - dead_frac);
        }
        // If next item fits exactly in the gap, bonus for saving it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: discourage proliferation of many open bins.
    score += 2.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals uniform, easier to pack later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Stream progression: early on, be more willing to keep things tight;
    // later, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit; make the empty bin mildly unattractive otherwise.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 25.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this bin is a perfect 2-item chain.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n == pr {
            score -= 800.0;
        } else if n < pr {
            // Next item fits after this one: reward proportional to tightness.
            score -= 250.0 * (1.0 - (pr - n) / bin_capacity as f64);
            // Extra reward if the double placement leaves a small remainder.
            let pr2 = pr - n;
            if pr2 <= 10.0 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large dead space
            // that the lookahead item cannot use.
            let waste = pr / bin_capacity as f64;
            score += 120.0 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when
    // post-residual is close to the mean (good packing), penalize bins that
    // are much looser than average (fragmentation).
    score += 0.5 * (pr_like(score, post_residual as f64, mean_residual));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // this is early in the stream or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 150.0 + 250.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) >= post_residual as f64 {
            // Opening a new bin lets both current and next item land cleanly
            // only if sizes are small relative to capacity.
            if item_size + next_item_size <= bin_capacity {
                score -= 100.0;
            }
        }
        score += penalty;
    }

    // Mild preference to keep the number of open bins in check.
    score += 2.0 * open_bins_count as f64;

    score
}

fn pr_like(_s: f64, post_residual: f64, mean_residual: f64) -> f64 {
    // Positive when bin is looser than average (penalize), negative when
    // tighter than average (reward).
    (post_residual - mean_residual) * 0.5
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post_residual.
    score += 0.35 * (post_residual as f64 * post_residual as f64) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let mut penalty = 25.0 + 0.4 * waste;
        // Late in the stream, opening new bins is more acceptable (consolidate leftovers).
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 20.0 * progress;
        // If many bins fit, discourage opening a new one.
        penalty += 3.0 * (fitting_bins_count as f64);
        // If next item would fit in the new-bin leftover, soften the penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            penalty -= 12.0;
        }
        score += penalty;
    }

    // Lookahead coupling: favor bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: mild penalty for dead space.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Prefer bins with residuals below the mean (compact the tight bins first).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Encourage using many open bins when few are open (avoid bin proliferation early).
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight time-decay of fit quality importance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * pr_norm * pr_norm * (1.0 + p2) * 100.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (nxt - pr) / cap * (1.0 + p3);
        } else {
            score -= 10.0 * (1.0 - (pr - nxt) / cap) * pr_norm;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Encourage balancing residuals toward the mean early on
    score += 3.0 * (pr - mean_residual).abs() / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets of 10 (capacity fractions)
    let cls = post_residual / 10;
    // Dead-space penalty: residual < smallest plausible item is wasted
    if post_residual < 10 {
        score += 40.0; // unusable sliver
    } else {
        // Reward residuals that form "nice" classes (multiples of 10/20)
        let harmonic = if post_residual % 20 == 0 {
            6.0
        } else if post_residual % 10 == 0 {
            3.0
        } else if post_residual % 5 == 0 {
            1.0
        } else {
            0.0
        };
        score -= harmonic;
        // Penalize awkward mid-range residuals (hard to fill later)
        if cls >= 1 && cls <= 2 {
            score += 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // prefer leaving just enough room
            score -= 10.0 * (1.0 - slack as f64 / post_residual as f64);
            if slack < 10 {
                score += 15.0; // next item would leave another sliver
            }
        } else {
            // next item won't fit here; mildly penalize tight fills that strand the bin
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize so it is chosen only when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        // early in stream, opening bins is cheap-ish; late, consolidate
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    } else {
        // reward filling bins tightly (low post_residual relative to capacity)
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (fill the emptier ones to balance)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are unusable for typical
    // items (sizes >= 1 but streams favor larger items) -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Slightly larger dead zones (11..=20) are also risky.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual as f64 <= 0.15 * bin_capacity as f64 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot use the leftover (dead space ahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones; the empty new-bin candidate has residual == capacity so it gets the
    // full pressure penalty, discouraging premature opening.
    let pressure = 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += pressure + 20.0;
        // But if nothing else fits well, allow opening: last-chance signal.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the bin population homogeneous).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream tightening: as the stream progresses, avoid leaving gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size;
            // Reward chains that end tight too.
            if chain_residual <= 5 {
                score -= 180.0;
            } else {
                // Mild penalty for leaving large space after the hypothetical next placement.
                score += 0.4 * chain_residual as f64;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to wasted space.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual: prefer filling below-average-residual bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 80.0 + 0.1 * open_bins_count as f64;
    }

    // Slight pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize tiny dead space that can never be reused (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // This bin becomes dead after placement; penalize proportionally.
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_gap = mean_residual - item_size as f64;
        // If mean residual barely fits the item, opening a fresh bin is reasonable.
        if avg_gap < 15.0 {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 35.0 + 0.5 * mean_residual;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Late in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual [0,1]
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks mid-range, smooth
    score -= 12.0 * poly * (1.0 + progress);

    // Penalize tiny unusable residuals more strongly as stream advances.
    let tiny = (1.0 - prn).clamp(0.0, 1.0);
    score += 8.0 * tiny * tiny * tiny * (0.5 + progress);

    // Reward tight fits (small post residual) smoothly.
    score -= (1.0 - prn) * (1.0 - prn) * 4.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - pr / cap.max(1.0) );
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Late in the stream, prefer filling existing bins over opening new ones.
    score += progress * (open_bins_count as f64) * 0.3;

    // Slight preference toward bins with residuals near the mean (balance).
    score += (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: keep neutral baseline, mildly penalize early opening.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain classes.
    // Class 0 (exact fill) is perfect; small residues (1..=10) are near-useless.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score += 25.0; // dead space class
    } else if pr <= 20 {
        score += 10.0;
    } else {
        score -= 5.0; // reusable class
    }

    // Modulo harmonic: residues divisible by 10 are more reusable by typical items.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0; // chain placement possible
            // Extra reward if next item also leaves a harmonic residue
            let next_pr = pr - next_item_size;
            if next_pr % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 15.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer filling
    // existing bins unless the fit is poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many bins could fit the item.
        score += 35.0 + 5.0 * fitting_bins_count as f64;
        // But if current bin fit is very poor (large dead space), new bin is fine.
        if item_size <= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Tightness reward: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_frac;

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good "garbage absorber"; if far above, penalize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Stream progression: late in the stream, prefer exact/tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_frac);

    // Harmonic class of item size (mod 20): items in awkward classes create
    // more dead space generally; slightly penalize placements leaving residues
    // in the same awkward class.
    if pr > 0 && (pr % 20) < 10 && item_size % 20 >= 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy nonlinear penalty for small unusable gaps.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Penalize residual below the minimum item size (1) hard.
    if post_residual > 0 && post_residual < 1 {
        score += 50.0;
    }

    // Reward tight fits (post_residual near zero is already low; amplify exact fit).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: prefer spreading when many bins are open,
    // but keep pressure mild so tight fits still dominate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (1.0 - progress * 0.5);

    // Mean residual coupling: bins far below mean residual are "fresher";
    // slight penalty to avoid hoarding space in nearly-full bins unnecessarily.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: penalize leaving a gap that blocks the lookahead.
        score += 4.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Give the empty bin a mild handicap
    // so it is chosen only when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead is large and residuals are all small, opening new bin
        // is attractive: reduce the handicap.
        if next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 150.0 / (post_residual as f64).powf(0.6);
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes perfect over two placements.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) == nr {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward but penalize leftover dead space after both placements.
            let after_two = post_residual - next_item_size;
            score -= 120.0 / (after_two as f64 + 1.0);
            // Bonus if the two-item sequence exactly fills the bin.
            if after_two == 0 {
                score -= 250.0;
            }
        } else {
            // Next item will NOT fit here: post residual becomes dead space
            // unless small enough to be harmless. Penalize medium dead zones.
            let pr = post_residual as f64;
            if pr < 10.0 {
                score += 5.0; // tiny dead space, mild penalty
            } else {
                score += 0.35 * (pr - 10.0).min(60.0);
            }
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 200.0;
    }

    // Compare against mean residual: placing here should move the bin
    // population toward uniform fill; avoid bins far above/below average
    // when it creates imbalance.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count.min(40) as f64;
    }

    // New-bin candidate guard: an empty bin has residual == capacity;
    // make it unattractive unless current bins would waste a lot.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // But if the item is large and existing bins are tight, opening
        // a fresh bin can be right — relax the penalty.
        if item_size > bin_capacity / 2 {
            score -= 45.0;
        }
        // If no other bin fits (fitting_bins_count == 0 here means only
        // the new bin), the +60 stands and it wins by default.
    }

    // Slight stream-progression pressure: later in the stream, be more
    // willing to pack tightly into existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: keep it competitive but slightly worse
        // than a decent fit; scale with stream progress (late stream -> prefer
        // consolidating into open bins).
        score = item_size as f64 * (1.0 + 0.25 * progress) + 2.0;
        // If the item leaves a large hole in a fresh bin and lookahead item is small,
        // opening a new bin is more acceptable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual as f64 - next_item_size as f64) * 0.15;
        }
        return score;
    }

    // Reward tight fits: subtract more as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead item
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else {
            // Bonus if post residual can still host the next item
            score -= 5.0;
        }
    } else {
        // Last item: only tightness matters, no future concerns.
        score -= 10.0;
    }

    // Last-chance bin: strongly reward using it, otherwise a new bin opens.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Mild penalty for leaving residuals far from typical useful sizes:
    // residuals in [next_item_size, next_item_size + 20] are versatile.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 20 {
        score -= 4.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // packing into existing bins to avoid fragmentation.
    if open_bins_count > 1 {
        let fragmentation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= fragmentation * 2.0;
    }

    // Prefer bins whose residual was already partially used (avoid spreading).
    let used_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_fraction * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: post-residual polynomial with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score -= 6.0 * poly * (0.5 + prog);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + prog);
        } else {
            score -= 0.5 * (pr - nxt).min(20.0) * (1.0 - prog);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * prog;
    }

    // New-bin candidate: mild penalty unless existing bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05 + open_bins_count as f64 * 0.1;
    }

    // Mean residual deviation penalty (fragmentation awareness)
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by common item sizes (10,20,25,50) -> reusable.
    let pr = post_residual as u32;
    let mut harmony: f64 = 0.0;
    if pr == 0 {
        harmony = 40.0; // perfect fit
    } else if pr % 50 == 0 {
        harmony = 18.0;
    } else if pr % 25 == 0 {
        harmony = 14.0;
    } else if pr % 20 == 0 {
        harmony = 12.0;
    } else if pr % 10 == 0 {
        harmony = 9.0;
    } else if pr % 5 == 0 {
        harmony = 5.0;
    }
    score -= harmony;

    // Integer-division dead-space threshold: leftover below 10 is dead space.
    if pr > 0 && pr < 10 {
        score += 35.0;
    }

    // Lookahead coupling: does the leftover exactly fit or nearly fit the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 30.0;
        } else if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 15.0; // next item fills bin almost exactly
            } else {
                score -= (slack as f64).recip() * 20.0;
            }
        } else {
            // next item cannot fit here: leftover must serve other items.
            // Penalize small leftovers more.
            score += (10 - pr.min(10)) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish score so we only open when fits are bad.
    if bin_residual == bin_capacity {
        // baseline: opening a bin costs roughly half the capacity in potential waste
        score = 55.0 + 0.1 * open_bins_count as f64;
        // late in the stream, prefer closing out existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall (small residual before placement is good use).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference to spread load when many bins are open.
    if open_bins_count > 1 {
        score += (item_size as f64 / bin_capacity as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable for items >= 10,
    // so punish them far more than their raw size suggests.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Moderate residual is a healthy gap; reward leaving space that can
    // still host typical items.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 5.0;
    }

    // Penalize very large wasted residual only if it is unlikely to be used:
    // if next item can't fit in post_residual, the gap is at risk.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mean residual coupling: if this bin is much emptier than average,
    // it is a good consolidation target.
    let diff = mean_residual - post_residual as f64;
    score += 0.2 * diff;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing fits are poor (large post_residual or
    // dead space), otherwise keep it penalized.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if post_residual < 10 { 55.0 } else if post_residual > 60 { 10.0 } else { 0.0 };
        score = 70.0 + open_bins_count as f64 * 0.2 - poor_fit_penalty;
        // Late in the stream, slightly prefer new bins to avoid fragmentation.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward leaving room exactly for the next item,
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            // post_residual can host the next item: reward proportional to how
            // well the leftover after that hypothetical placement is minimized.
            let chained = post_residual - next_item_size;
            score -= next_item_size as f64 * 1.5 - chained as f64 * 0.3;
        } else {
            // Dead space relative to next item: penalize the gap.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.8;
            // Extra penalty for very small unusable slivers.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): apply a penalty so existing bins are
    // preferred unless their fits are poor (their lookahead penalties will
    // need to exceed this to justify opening a fresh bin).
    if bin_residual == bin_capacity {
        score += 25.0 + item_size as f64 * 0.1;
    }

    // Prefer bins whose resulting residual stays near/below the mean residual
    // (keeps residuals uniform, preserving future packing flexibility).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 30.0;

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize leaving residual too small for the next item (dead space).
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += (next_item_size as f64 - waste) * 0.5;
            }
        }
    }

    // Prefer bins with smaller residuals than the mean (close out nearly-full bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.3;
        } else {
            score += (-diff) * 0.2;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: opening bins is cheap; later: prefer filling existing ones.
        score += 15.0 + 30.0 * progress;
        // If many fitting bins exist, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).sqrt();
        }
        // If mean residual is large and can fit item, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += mean_residual * 0.1;
        }
    }

    // Large items relative to residual: penalize wasteful placements.
    let fill_ratio = item_size as f64 / (bin_residual.max(1) as f64);
    score -= fill_ratio * 10.0;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear coupling: quadratic penalty on post-residual scaled by progress.
    // Late in the stream, dead space is more costly (fewer chances to fill it).
    let norm_pr = pr / cap;
    score += progress * norm_pr * norm_pr * cap;

    // Cubic interaction: penalize large residuals asymmetrically as stream advances.
    score -= (1.0 - progress) * norm_pr * (1.0 - norm_pr) * 10.0;

    // Tight fits rewarded more strongly later in the stream (smooth sigmoid-like weight).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (item_size as f64 / cap) * (0.5 + progress);

    // Last-chance bin: strong smooth bonus, amplified by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidation),
    // with a smooth non-linear (quadratic) divergence term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * (1.0 - progress);

    // Lookahead: reward bins whose post-residual can host the next item,
    // weighted smoothly by progress.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= (next_item_size as f64 / cap) * 20.0 * (0.3 + 0.7 * progress);
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Classes of residual: 0 (perfect), small (<=10), medium (11..30), large (>30).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual <= 30 {
        score -= 10.0 + (30 - post_residual) as f64 * 1.5;
    } else {
        score += 5.0; // large dead space penalty on top of raw residual
    }

    // Integer-division thresholds: residual divisible by small harmonics is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0; // residual in multiples of 10 matches common item sizes
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 40.0 - gap as f64;
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual; penalize small leftovers more
            if post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin; cheaper late in stream when many bins open
        score += 45.0 - 20.0 * progress;
        if open_bins_count > 4 {
            score += 8.0; // avoid bin proliferation
        }
        // perfect-fit item into fresh bin (item == capacity fraction harmonics)
        if item_size % 10 == 0 || item_size % 25 == 0 {
            score -= 5.0;
        }
        // if the item would leave a tiny awkward residual anywhere, new bin is fine
        if bin_capacity - item_size <= 10 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter bins overall (closer to mean-residual balance)
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Penalize bins whose residual deviates strongly from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 1) are pure waste.
    // Penalize any post_residual that is small but nonzero (hard to reuse).
    if post_residual > 0 {
        // dead space in the "hard to fill" band: small gaps are nearly unusable
        let dead_band = 8.0;
        if (post_residual as f64) <= dead_band {
            score += (dead_band - post_residual as f64) * 6.0;
        }
        // gentle linear penalty on any leftover to prefer tight fits
        score += post_residual as f64 * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover cannot host next item: penalize as dead space
        score += (post_residual as f64) * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing bins, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open bins and remaining stream
        score += 15.0 + pressure * 3.0 + progress * 20.0;
    } else {
        // existing bin: mild reward, stronger when many bins are open
        score -= pressure * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit gets a big bonus.
        score -= 40.0 / (1.0 + diff);
        // Reward small post-residuals that still allow the next item (tight chaining).
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Post-residual too small for the next item: penalize dead space.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: pure tightness objective.
        score -= 10.0;
    }

    // Tight fit reward relative to bin capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Penalize leaving residual far below mean (fragmented leftovers), reward above-mean slack
    // only mildly so we don't hoard large bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are very fragmented
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin when item is huge and would leave a nearly full bin anyway.
        if item_size >= 70 {
            score -= 30.0;
        }
        // More open bins => more fragmentation risk => new bin slightly more attractive.
        score -= 1.5 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for leaving exactly tiny unusable slivers (1..=5 dead space).
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, prefer filling existing bins tightly;
    // later, allow opening bins more freely since remaining items are fewer.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else {
        // Reward small residuals non-linearly (dead space penalty grows fast).
        let r = post_residual as f64;
        score += (r * r) / (bin_capacity as f64 * 2.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item would NOT fit here after placement: penalize slightly,
            // less so late in the stream when it matters less.
            score += 30.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: discourage spreading; few open bins: allow new bins.
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below average,
    // it's a "ragged" bin — using it cleans up the state.
    let this_residual = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= (this_residual - mean_residual).abs() * 0.3;
    }

    // New-bin candidate handling: empty bin should only win when no decent
    // existing fit exists. Penalize the new bin, but relax the penalty as
    // the average residual shrinks (existing bins nearly full anyway).
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 150.0 * (1.0 - avg_tightness * 0.8);
        // Late stream: opening a fresh bin is cheaper than fragmenting.
        score -= 80.0 * progress;
    }

    // Prefer bins whose residual is close to the item (snug fit).
    score -= (bin_residual - item_size) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = norm_post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth coupling: as stream progresses, tighten fit preference.
    let tighten = 0.5 + 2.0 * progress;
    score += tighten * norm_post * norm_post;

    // Reward tight fits (post_residual near zero) more strongly late in stream.
    let tightness = 1.0 - norm_post;
    score -= (0.5 + 1.5 * progress) * tightness * tightness * tightness;

    // Lookahead: penalize leaving post residual that cannot fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // post residual can accommodate next item: mild reward scaled by fit ratio
            let ratio = nxt / post.max(1.0);
            score -= 1.5 * ratio * (1.0 - ratio);
        } else {
            // dead space relative to next item
            score += 1.0 + (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Many open bins with high mean residual: encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= pressure * (1.0 - norm_post);

    // Slight bias against opening a brand-new bin when open bins exist.
    if open_bins_count > 0 && bin_residual == bin_capacity && item_size > 0 {
        score += 0.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Dead space classes: (0..=10], (10..=25], (25..=50], (50..=100).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect: dead space negligible
    } else if post_residual <= 25 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += 0.15 * pr; // half-full: moderate penalty
    } else {
        score += 0.35 * pr; // wasteful large residual
    }

    // Modulo harmonic coupling: reward residuals that are "friendly" to the
    // next item via integer-division thresholds.
    if next_item_size > 0 {
        let n = next_item_size;
        if post_residual >= n {
            // next item fits here too: strong reward, scaled by tightness
            let tight = (post_residual - n) as f64;
            score -= 20.0 - 0.1 * tight;
            // harmonic bonus: post_residual % n small => next item fills bin well
            let m = (post_residual % n) as f64;
            score -= 8.0 * (1.0 - m / n as f64);
        } else {
            // next item won't fit in this residual: penalize unusable leftover
            score += 6.0;
            // if next item fits nowhere else, this bin is last chance
            if fitting_bins_count == 1 {
                score -= 30.0;
            }
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: empty bin gets a baseline cost that grows with how
    // many bins are already open and how good the average fit options are.
    if bin_residual == bin_capacity {
        // opening a new bin is wasteful early; allow it late or when crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 20.0 * progress;
        // if mean residual across open bins is small, opening new bin is fine
        score += (mean_residual / cap).min(1.0) * 25.0;
        // if many bins already fit the item, opening a new one is bad
        score += 10.0 * fitting_bins_count as f64;
    }

    // Mild preference for fuller bins (small residual before placement)
    score += 0.05 * (bin_residual as f64 / cap);

    // Slight penalty for hoarding too many open bins
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for typical items are worthless.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating
    // (favor filling existing bins over opening new ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 2.5;
    score += open_bins_count as f64 * progress * 3.0;

    // New-bin candidate: make opening a new bin attractive only when
    // this placement would leave large waste in an existing bin.
    if bin_residual == bin_capacity {
        // New empty bin baseline: post_residual = capacity - item_size.
        score += 5.0;
        if fitting_bins_count > 0 {
            let best_possible = mean_residual;
            if (bin_residual as f64 - item_size as f64) > best_possible * 0.8 {
                // existing bins fit well; discourage new bin
                score += 40.0;
            } else {
                // existing bins fit poorly; encourage new bin
                score -= 20.0;
            }
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill fuller bins first, keep large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leftover exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // If next item cannot fit in the leftover, penalize creating dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.6 * dead;
        // Very small unusable slivers are extra wasteful.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 1.5;
        }
    }

    // Reward bins whose residual deviates favorably from the mean (tighter bin).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // would leave a very tight residual in every existing bin, otherwise
    // discourage opening a new bin.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin pairs well with the next item
        }
    }

    // Late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual
    // (chain packing), penalize dead space that nothing can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            // Dead space: unusable for the next item; worse if very small.
            let dead = post_residual as f64;
            score += 0.8 * dead;
            if dead < next_item_size as f64 * 0.5 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current placements are bad. Make the empty-bin call moderately expensive
    // early on, cheaper late when fragmentation accumulates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        score += 45.0 - 25.0 * progress - 1.5 * open_pressure;
        // If mean residual of open bins is small (all bins nearly full),
        // a new bin becomes attractive.
        if mean_residual < item_size as f64 + next_item_size as f64 {
            score -= 35.0;
        }
    }

    // Prefer filling bins whose residual is close to the item (relative fit).
    if bin_residual > item_size {
        let rel = item_size as f64 / bin_residual as f64;
        score -= 20.0 * rel;
    }

    // Mild preference to balance across many open bins: avoid hoarding
    // placements into few bins when many exist (keeps options open).
    score += 0.05 * open_bins_count as f64;

    // Progress-aware waste scaling: later in the stream, waste is costlier
    // since fewer items remain to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear coupling of post_residual with progress:
    // waste is penalized more quadratically as the stream matures.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 2.0 * pr_norm * pr_norm * progress * cap;

    // Reward tight fits (small post_residual) more strongly late in the stream.
    let tightness = 1.0 - pr_norm;
    score -= 3.0 * tightness * tightness * (0.5 + 0.5 * progress) * item_size as f64;

    // Lookahead: bonus if next item fits into the post-residual (smooth reward).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= (1.0 - fits) * (pr - nxt).max(0.0) * 0.8;
        // Penalize leaving exactly a size that nothing typical can use
        if pr < nxt {
            score += (nxt - pr) * 0.5;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 + progress);
    }

    // Many open bins: discourage spreading; prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * fullness * open_bins_count as f64 * 0.3;

    // Mean residual coupling: prefer bins below mean residual (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor,
    // but relax late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Modulo classes: residuals that are "harmonic" with common item sizes are reusable
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual <= 10 {
        -12.0 // nearly perfect, unusable dead space anyway
    } else if post_residual % 10 == 0 {
        -8.0 // multiple of 10: matches grid-aligned items
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize large leftover fractions quadratically (dead space grows cost)
    score += 20.0 * frac * frac * cap * 0.01;

    // If the next item fits exactly into the post residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // extra reward if next item leaves another harmonic residual
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 4.0 * (next_item_size as f64 - pr).min(cap * 0.5);
        }
    }

    // Last-chance bin: avoid forcing a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are very full
    if bin_residual == bin_capacity {
        // base penalty so new bins are not opened casually
        score += 45.0;
        // but if mean residual is tiny (all bins nearly full), opening is fine
        score -= 40.0 * (1.0 - (mean_residual / cap)).min(1.0).max(0.0);
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tighter bins among equals
    score -= 0.05 * (cap - bin_residual as f64);

    // Reward packing into bins that are already mostly full (best-fit bias)
    score += 0.03 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual that cannot accommodate even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps that can't fit the lookahead item are risky too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero is handled by base score already,
    // but give extra bonus for near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual was already small (consolidating fullness).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins below mean residual (fuller-than-average bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if the alternative creates dead space
        if post_residual == bin_capacity - item_size && item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a decent fit exists in open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 20.0 - 100.0 * progress;
        // Allow new bin if current item is huge relative to capacity and few open bins
        if item_size as f64 > 0.8 * bin_capacity as f64 && open_bins_count > 0 {
            score -= 40.0;
        }
        // If next item is large and no open bin could chain-fit, new bin is safer
        if next_item_size > post_residual && next_item_size > 60 {
            score += 30.0;
        }
    }

    // Mild penalty for very small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to the mean residual of open bins.
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += 0.35 * (dead - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - dead);
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * chain_fit;
        } else {
            // Post-residual too small for next item: penalize wasted potential,
            // scaled by how large the dead space actually is.
            score += 0.25 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large enough that no open bin would be a decent host.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        score += 40.0;
        // Offset when item is large relative to capacity (new bin justified).
        score -= 55.0 * (item_size as f64 / bin_capacity as f64);
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        score += 20.0 * progress;
        // If many bins are open, discourage adding another.
        score += 1.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin gives it room: slight reward.
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual - item_size) {
            score -= 5.0;
        }
    }

    // Mild global pressure: with many open bins, prefer placements that reduce
    // fragmentation (small post_residual) even more.
    score -= 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Small time-dependent tie-breaker for determinism across the stream.
    if total_items > 0 {
        score += 0.01 * (step_index as f64 / total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;

    // Smooth non-linear coupling: residual waste weighted by stream progress
    let waste_coupling = (pr / cap).powi(2) * (0.5 + progress);
    score += waste_coupling * 20.0;

    // Reward tight fits via smooth sigmoid-like term on fill ratio
    let fill = 1.0 - pr / cap;
    let tightness = (fill * std::f64::consts::PI).sin();
    score -= tightness * 8.0;

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (1.0 - gap / cap) * 6.0;
        } else {
            score += (-gap / cap).powi(2) * 12.0;
        }
    }

    // New-bin candidate: prefer opening a new bin early, penalize later
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0 - 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: classify leftover space by which
    // "size classes" of future items it can still absorb.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        25.0 // perfect fit, zero waste
    } else if pr < 10 {
        18.0 // small dead space, likely unusable anyway but minimal
    } else if pr <= 20 {
        12.0 // can absorb a small item class
    } else if pr <= 35 {
        8.0
    } else if pr <= 50 {
        5.0
    } else {
        2.0 // large residual still flexible
    };
    score -= class_bonus;

    // Lookahead coupling: penalize if post_residual cannot fit the next item
    // but was still large enough to be useful; reward if it exactly matches
    // a size class around next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            // next item fits here too: this bin remains attractive
            let slack = pr as f64 - nx;
            score -= 10.0 * (1.0 - slack / cap); // prefer leaving just enough
        } else {
            // next item won't fit: penalty grows with wasted potential
            score += 6.0 + 0.05 * (pr as f64);
        }
        // Harmonic match: post_residual within a small band above next item
        let diff = pr as i64 - next_item_size as i64;
        if diff >= 0 && diff <= 5 {
            score -= 15.0; // near-perfect two-item packing
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current bin
    // would leave an awkward mid-range residual and item is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are used only for good reason
        score += 12.0;
        if item_size > 60 {
            // large items pack better into a fresh bin
            score -= 18.0;
        }
        if post_residual <= 10 {
            score -= 10.0; // item nearly fills a fresh bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild pressure against hoarding many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * progress;

    // Small nudge toward bins with residuals near the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (1..=100, but tiny gaps < ~12 are near-unusable)
    // are heavily penalized. Penalize any post_residual in the "dead zone".
    let dead_floor = 12u32;
    if post_residual > 0 && post_residual < dead_floor {
        score += (dead_floor - post_residual) as f64 * 6.0;
    }
    // Penalize mid-size awkward gaps that few item sizes can use.
    if post_residual >= dead_floor && post_residual <= 20 {
        score += 4.0;
    }

    // Reward perfect / near-perfect packing strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: reward bins where the item fills a large share of residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= fill_ratio * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or no good tight fit exists. Make empty-bin baseline
    // moderately high so open bins with decent fits win.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + item_size as f64 * 0.3;
        // Opening a new bin is fine for big items (they'll fill it well).
        if item_size >= 70 {
            score -= 25.0;
        }
        // If many bins are open, prefer consolidating into them.
        score += open_bins_count as f64 * 1.5;
        // If the next item would pair with the leftover, opening a fresh bin is worse.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0;
        }
        return score;
    }

    // Lookahead: if post_residual exactly accommodates the next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (mild consolidation bias scaled by stream progress).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (close them out) when item fits well.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: item then next item fill the bin
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot use leftover space: penalize proportionally
            score += 0.08 * post_residual as f64;
        }
    }

    // Penalize leaving residuals that are likely dead space (small, awkward).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer bins whose residual is already below mean (denser bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.02 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item leaves large post_residual in every open bin) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = if fitting_bins_count > 0 {
            let worst = (bin_capacity - item_size) as f64;
            0.0
        } else {
            0.0
        };
        // Base new-bin score: leftover space in fresh bin after placing item.
        score = (bin_capacity - item_size) as f64;
        // Encourage opening new bins early, discourage once many bins open.
        score -= 20.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // If many bins fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Small items: don't waste a fresh bin.
        if item_size <= 30 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual nearly vanishes.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize leaving dead space too small for any plausible item.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.4;
        } else if next_item_size > post_residual && post_residual < 10 {
            // Dead space unusable by the known next item: extra penalty.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // the item fits poorly everywhere or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Cost of a new bin grows with fragmentation (many half-empty bins)
        // but shrinks late in the stream when residual space is less useful.
        let new_bin_cost = 60.0 - progress * 25.0 + fragmentation * 40.0;
        // Large items fit a fresh bin perfectly well.
        score += new_bin_cost + (item_size as f64) * 0.3;
        if item_size >= 50 {
            score -= 20.0; // big items justify fresh bins more readily
        }
    } else {
        // Mild preference for bins with residual close to item (minimize slack ratio)
        let slack = (bin_residual - item_size) as f64 / (bin_capacity as f64);
        score += slack * 10.0;
    }

    // Prefer filling bins with lower-than-average residual slightly less
    // (keep some diversity of residuals for future items).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Time horizon: early on, be conservative about creating tiny residuals;
    // later, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 20 && progress < 0.3 {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, favor tight fills; late, penalize dead space super-linearly.
    let prog_sq = progress * progress;
    let prog_cub = prog_sq * progress;
    score += (norm_pr * norm_pr) * (40.0 + 80.0 * prog_sq) + norm_pr * prog_cub * 60.0;

    // Reward near-perfect fits smoothly (quadratic dip around zero residual).
    score -= (1.0 - norm_pr).powi(2) * (item_size as f64) * 0.5;

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= fit_frac * (10.0 + 30.0 * (1.0 - (fit_frac - norm_pr).abs()));
    } else if next_item_size > 0 {
        // Penalize residuals that are dead relative to next item, smoothly.
        score += (norm_pr - next_item_size as f64 / cap).abs() * 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing),
    // smoothly penalizing outliers.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Mild preference for filling already-open bins as stream progresses.
    score += progress * 5.0;

    // New-bin candidate should not win unless residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 12.0 + 40.0 * norm_pr * (mean_residual / cap) + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that cannot fit typical items is costly.
    // Class by integer division thresholds: 0 (perfect), small (<=10), medium (<=25), large.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 25 {
        score -= 5.0;
    } else if pr > 50 {
        score += 10.0; // leaving a huge hole is wasteful
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 are more reusable
    // under typical integer item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: strongly reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 25.0;
        } else if next_item_size > pr {
            score += 8.0; // next item won't fit here; keep residual flexible
        }
        // Harmonic fraction coupling: next item fills a clean fraction of capacity
        let nf = next_item_size as f64 / cap;
        if (nf - 0.5).abs() < 1e-6 || (nf - 0.25).abs() < 1e-6 || (nf - 0.75).abs() < 1e-6 {
            if next_item_size <= pr {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: it has full residual and fitting_bins_count counts it,
    // so penalize opening a new bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty for opening a new bin
        if fitting_bins_count <= 1 {
            score -= 70.0; // no good alternative: open new bin
        }
        if pr == bin_capacity && item_size >= 50 {
            score -= 20.0; // large item into fresh bin is fine
        }
    }

    // Tightness term: prefer bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Prefer bins below mean residual (denser bins) slightly.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful future item are pure waste -> heavy penalty.
    // Items can be as small as 1, but tiny gaps (< ~10) rarely get used
    // before the stream ends; make the penalty super-linear in tightness.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - pr) * 6.0; // dead-space wall: gaps 1..11 are heavily punished
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is always best
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    let tightness = pr / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: discourage spreading into many bins unless the fit
    // is genuinely good; the more bins already open, the stronger the pull
    // toward reusing existing capacity.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "scrappy" bin; prefer bins whose post_residual stays near/below mean.
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the dead-space wall triggers).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // attractive when current bin would leave a big unusable gap or the
    // item nearly fills a fresh bin entirely.
    if bin_residual == bin_capacity {
        // neutral baseline; slightly favor if the item almost perfectly fills it
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 10.0;
        // penalize opening new bins when plenty of open bins already fit
        if fitting_bins_count > 0 {
            score += 12.0 + (fitting_bins_count as f64) * 1.5;
        }
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 3.0;
    }

    // Lookahead (k=2): bonus if the resulting post_residual can exactly
    // accommodate the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // gap too small for the known next item: mild penalty
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // leftover can host next item: mild reward scaled by slack efficiency
            let slack_ratio = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * slack_ratio;
        } else {
            // dead space smaller than next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize tiny unusable residuals relative to the known item-size floor (1..100, mean ~ small items possible).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: default slightly penalized; only chosen when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // late in the stream, prefer consolidation into open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
    }

    // Mild reward for filling large items into bins with large residual (tight coupling).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Slight preference to spread across few bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that cannot hold even the smallest item (1).
    if post_residual > 0 && post_residual < 4 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving residual that wastes capacity for the next item.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a new bin only when it's early,
    // open bins are crowded, or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowdedness = mean_residual / (bin_capacity as f64);
        // Opening a bin is attractive when existing residuals are small (crowded)
        // but discouraged late in the stream.
        score -= 30.0 * (1.0 - crowdedness);
        score += 25.0 * progress;
        // If the item fits well into an existing bin, discourage new bin.
        if tightness > 0.6 {
            score += 20.0;
        }
    }

    // Mild preference for bins with residuals below the mean (consolidate small spaces).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Encourage spreading load when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual) mildly; late, reward them strongly.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 30.0 * poly * (1.0 + 2.0 * progress);

    // Smoothly growing penalty for large residuals as stream progresses.
    score += (pr_norm * pr_norm) * 20.0 * progress;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_gap = (pr_norm - 0.02).abs();
    score -= 15.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64;
        let nxt_fit = (pr - nxt) / cap;
        score -= 12.0 * (1.0 - (nxt_fit * 4.0).min(1.0));
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use.
        score += 6.0 * pr_norm;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // existing bins are very fragmented (mean residual high relative to item).
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        let pressure = 1.0 - (frag * 2.0).min(1.0);
        score += 10.0 + 25.0 * pressure * (1.0 - progress);
        score -= 8.0 * progress;
    }

    // Slight preference for bins with residuals near the item (smooth term).
    let res_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * res_gap * res_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize residuals that are too small to be useful (below min item size)
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Classify post_residual by integer division thresholds (harmonic bands)
    let band = post_residual / 10; // 0..10 bands
    match band {
        0 => score += 40.0,                    // 1..9 : nearly dead
        1 => score += 15.0,                    // 10..19: only tiny items fit
        2 | 3 => score += 0.0,                 // 20..39: moderate
        4 | 5 => score -= 5.0,                 // 40..59: good
        _ => score -= 10.0,                    // 60+: very flexible
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Extra reward if next item leaves another usable residual (chain fit)
        let chain_res = post_residual - next_item_size;
        if chain_res >= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize more if residual is stranded
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a new bin is only good when no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ capacity worth of potential
        score = 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin trivially fits next item; slight bonus
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Mean residual coupling: if open bins are already loose, discourage spreading
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 3.0; // prefer bins with more room than average
        } else {
            score += 3.0;
        }
    }

    // Late-stream tightening: as stream progresses, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Modulo harmonic bonus: residual divisible by common item sizes is reusable
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1) can use
    // are pure waste; penalize small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer placing here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from many open bins: discourage spreading across bins.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is above the mean (large leftovers are
    // more reusable); penalize bins already below mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (residual too small relative to item) or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.05;
        if decent_fit_exists && fitting_bins_count > 1 {
            score += 40.0; // prefer existing bins
        } else {
            score -= 15.0; // opening fresh is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Penalize leaving residuals too small to ever be useful (dead space)
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward bins tighter than the mean residual (good packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if next item is large and no open bin matches well, allow new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size > post_residual {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead synergy: this placement sets up the next item nicely.
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * crowding * (mean_residual / bin_capacity as f64 - fit_ratio).abs();

    // Later in the stream: be more conservative, avoid leaving large residuals.
    score += 20.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { (mean_residual / bin_capacity as f64 - fit_ratio).abs() } else { 0.0 };
        let base = 55.0 + 40.0 * fragmentation;
        // A new bin is worth it if the item is large and no tight fit exists.
        score = base - (item_size as f64 / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(0) {
            score -= 10.0; // next item pairs well with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * progress;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 15.0 * waste * waste * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across too many open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless residuals are low
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: heavily favor small post_residual.
    score += (post_residual as f64 / cap) * 25.0;

    // Harmonic class of post_residual: residuals divisible by common item
    // granularities are more reusable, so subtract a bonus.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 4.0; } // odd primes are dead space
    } else {
        score -= 40.0; // perfect fill is best possible
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // harmonic coupling: next item divides residual exactly
        if pr % next_item_size == 0 { score -= 5.0; }
    } else if next_item_size > pr {
        // residual too small for next item -> dead-space penalty scaled by waste
        let waste = (next_item_size - pr) as f64;
        score += (waste / cap) * 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one, unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing
    // fits are all poor. Scale penalty by stream progress (late stream,
    // consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 30.0 * progress;
        // but if the item is huge relative to mean residual, new bin is fine
        if (item_size as f64) > mean_residual {
            score -= 45.0;
        }
    }

    // Mild preference for filling bins with larger residual gaps
    score -= (bin_residual as f64 - post_residual as f64) * 0.05;

    // Open-bins pressure: many open bins -> encourage consolidation
    score += (open_bins_count as f64) * 0.5;

    // Integer-division threshold on post_residual: bucketed dead-space tiers
    let tier = pr / 20; // 0..=5 buckets of 20 capacity units
    score += tier as f64 * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (min item size is 1, but tiny gaps under 10 are near-unusable)
    // are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Gap that cannot fit the lookahead item is less useful: penalize mildly,
    // but if it fits the next item exactly, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.35 * next_item_size as f64;
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (30.0 + 8.0 * open_bins_count as f64 + 20.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 45.0;
    }

    // Prefer bins whose residual is below mean (tighter packing).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Slight bias toward fuller bins.
    score -= 0.10 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect two-item fill (post_residual == next_item_size) is ideal.
        score += 0.6 * lookahead_gap;

        // Exact two-item completion bonus.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize leaving residuals too small for anything useful (dead space).
        if post_residual < 10 {
            score += 8.0;
        }

        // If this bin cannot host the next item, mild penalty scaled by dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins already tighter than average are better targets.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        score += 20.0 + 0.4 * poor_fit;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0; // fresh bin enables perfect pair
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 20.0 + 0.3 * pair_waste;
    } else if next_item_size > 0 {
        // Penalize leaving a residual too small for the next item (dead space).
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.15 * dead;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize unless it's genuinely attractive.
    if bin_residual == bin_capacity {
        let open_penalty = 25.0 + 2.0 * open_bins_count as f64;
        // If no other bin fits, this call is the only option anyway; soften penalty.
        if fitting_bins_count == 0 {
            score += open_penalty * 0.3;
        } else {
            score += open_penalty;
        }
        // Opening a bin is more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (use bins that are already fuller than average).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild preference to fill bins with many open bins (consolidation).
    score += 0.5 * open_bins_count as f64 * tightness;

    // Time-dependent tightening: later in the stream, prefer minimizing waste more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Core: quadratic penalty on leftover space (tight fits win).
    let mut score = norm_pr * norm_pr * 100.0 + norm_pr * 20.0;

    // Smooth coupling of leftover with stream progress:
    // later in the stream, dead space becomes more costly (bins are harder to close).
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward bins whose residual is close to the item (near-perfect fill).
    let fit_quality = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 15.0 * fit_quality * fit_quality;

    // Penalize leaving post_residual that no plausible next item can use:
    // if lookahead item cannot fit into post_residual, add smooth penalty.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * gap;
        // Bonus if the next item exactly chains into this bin's leftover.
        let chain = 1.0 - ((pr - next_item_size as f64) / cap).abs().min(1.0);
        score -= 8.0 * chain * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_pr);
    } else {
        // Mild penalty spread across many fitting bins to encourage consolidation.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins whose leftover deviates
    // smoothly from the fleet average (keeps residual distribution tight).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Slight preference for more-filled bins among many open bins.
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate (bin_residual == bin_capacity): make it attractive
    // only when the item is large relative to capacity (poor fit elsewhere)
    // or late in the stream where fragmenting small items is wasteful.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let openness = 1.0 - (fitting_bins_count as f64).min(4.0) / 4.0;
        score -= 30.0 * item_frac * item_frac * openness
               + 10.0 * progress * (1.0 - item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10
    let band = post_residual / 10;
    // Reward small bands (tight fits) nonlinearly
    score -= (10 - band.min(10)) as f64 * 3.0;

    // Penalize dead space that cannot fit typical small items (min size 1 unknown, assume ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills residual is golden
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
                // harmonic class match: next item leaves again a small band
                let next_post = post_residual - next_item_size;
                let nband = next_post / 10;
                score -= (5 - nband.min(5)) as f64 * 2.0;
            }
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins whose residual is below mean (fill the emptier-ish / tighter bins first)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    // Modulo-arithmetic class on item_size relative to capacity: items that
    // divide capacity evenly should target near-full bins
    let item_frac = item_size as f64 / cap_f;
    if (item_frac * 100.0).round() as u32 % 25 == 0 {
        // quarter-capacity items: reward near-exact fills
        if post_residual % 25 == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // New-bin candidate: baseline score so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild crowding penalty: too many open bins -> consolidate
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..10) can
    // use are pure waste. Penalize small non-zero residuals super-linearly.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            // unusable gap under the smallest realistic item
            (10 - post_residual) as f64 * 4.0
        } else {
            0.0
        };
        score += dead;

        // general tightness reward: quadratic bonus for small leftovers
        let pr = post_residual as f64;
        score -= (bin_capacity as f64 - pr).max(0.0) * 0.15;
        score += (pr / bin_capacity as f64).powi(2) * 30.0;
    } else {
        // perfect fill is heavily rewarded
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual {
        // next item cannot follow here; mildly penalize if we strand capacity
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on,
    // encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the fleet balanced and reusable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all open
    // bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 * 0.9 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward for a near-perfect match of next item into post residual.
            let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * next_fill * next_fill;
        } else {
            // Penalize creating dead space the next item cannot use.
            let waste = post_residual.min(next_item_size - 1) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual close to item size are better.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer fuller bins relative to capacity.
    let used_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * used_ratio;

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { -12.0 } else { 12.0 };
        let poor_fit = if fitting_bins_count == 0 { -20.0 } else { 0.0 };
        score += base_penalty + large_item_bonus + poor_fit;
    }

    // Mild stream progression adaptation: as stream advances, be more conservative
    // about leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Perfect chaining: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer reusing existing bins over opening new ones.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 6.0 * crowding;

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * progress * fit_ratio;

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps residuals uniform, improving future packing flexibility).
    score -= 2.0 * (-( (bin_residual as f64 - mean_residual).abs() ) / 20.0).exp();

    // Penalize wasting a nearly full bin on a small item.
    if item_size < bin_residual / 3 {
        score += 7.0;
    }

    // New-bin candidate: only attractive when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 14.0 + 10.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling: tight fits (small post_residual) rewarded
    // with a non-linear bonus that grows as the stream progresses.
    let tightness = 1.0 - norm_post;
    let progress_coupling = progress * (1.0 + progress);
    score -= 30.0 * tightness * tightness * (0.5 + progress_coupling);

    // Penalize creating small unusable slivers via a smooth quadratic term.
    let sliver = (norm_post * (1.0 - norm_post) * 4.0 - 1.0).abs();
    score += 15.0 * sliver * sliver;

    // Dead-space penalty: very low post residual wastes capacity when many bins exist.
    score += 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Interaction with mean residual: prefer bins whose post residual stays
    // near the current mean (smooth deviation term).
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving space close to the next item size (smooth kernel).
    if next_item_size > 0 {
        let next = next_item_size as f64 / cap;
        let gap = norm_post - next;
        score -= 12.0 * (-gap * gap * 25.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and remaining stream is long (smooth preference).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 20.0 * norm_item * (1.0 - norm_item) * 4.0 * progress;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit and small-residue classes are prized.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class by residue magnitude relative to capacity fractions.
        if post_residual <= 5 {
            score -= 25.0; // near-perfect, unusable sliver
        } else if post_residual <= 15 {
            score -= 10.0; // small dead space
        } else if post_residual <= 30 {
            score -= 3.0;  // mid residue, still usable for small items
        }
        // Modulo-10 class: residues that are multiples of 10 pair well with
        // common item sizes (multiples of 10 dominate typical streams).
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Reward if the lookahead item fits exactly into the post-residual
    // (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // lookahead fits: residue retains value, scaled by leftover after next
            let second = post_residual - next_item_size;
            score -= (second as f64) / c * 15.0;
        } else {
            // lookahead cannot use this residue: penalize proportionally
            score += ((next_item_size - post_residual) as f64) / c * 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that
    // scales with how many open bins already exist, so we only open when
    // no decent fit exists.
    if bin_residual == bin_capacity {
        score = c * 0.55 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with the larger lookahead
        }
    } else {
        // Slight preference for bins below mean residual (balancing loads).
        score += (pr - mean_residual) * 0.05;
    }

    // Progress pressure: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful are "dead space". Estimate the minimum useful item
    // size conservatively (items can be as small as 1), but treat very
    // small gaps as increasingly wasteful since they are hard to fill.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Dead-space penalty: quadratic blow-up for tiny unusable gaps.
        if pr < 10.0 {
            score += 200.0 * (10.0 - pr) / 10.0 + 50.0;
        } else if pr < 20.0 {
            score += 30.0 * (20.0 - pr) / 10.0;
        }

        // Perfect fit bonus: reward near-exact fills strongly.
        if pr == 0 {
            score -= 150.0;
        } else if pr <= 5 {
            score -= 60.0;
        }

        // If the gap can still hold the lookahead item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot fit the next item: mild dead-space penalty.
            score += 15.0;
        }
    }

    // Tightness reward: fraction of the bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Last-chance pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few open bins, allow
    // more freedom.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so that spreading
        // is penalized when many bins are already open. Also penalize
        // more when the mean residual across open bins is large
        // (existing bins still have plenty of room).
        score += 30.0 + 12.0 * pressure + 0.15 * mean_residual;
        // Opening a new bin is acceptable if the item is large and would
        // leave a good residual in a fresh bin.
        score -= 20.0 * fill_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    } else {
        // Existing bin: small consolidation bonus scaled by pressure.
        score -= 4.0 * pressure;
    }

    // Slight stream-phase adaptation: early on, be a bit more willing to
    // open bins (spread); later, consolidate harder.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - phase);
    } else {
        score -= 8.0 * phase;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: bin becomes exactly usable by next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (-gap / 15.0).exp();
        }
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            let deficit = (next_item_size - post_residual) as f64;
            score += 0.6 * deficit;
        }
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Coupling with mean residual: bins far below mean residual are underused; prefer
    // placing into bins whose residual is already close to the item (reduces spread).
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * spread;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Slightly cheaper to open a new bin late in the stream or with many open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        score += 0.05 * open_bins_count as f64;
        // If next item could exactly fill the remainder of a fresh bin, encourage it.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 40.0;
        }
    }

    // Mild penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fit reward: quadratic bonus as post_residual approaches 0
    score -= 40.0 * (1.0 - post / cap).powi(4);

    // Penalize residuals that are too small to hold the smallest plausible item (dead space)
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, strongly reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if nxt <= post {
            score -= 8.0 * (nxt / post);
        } else {
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, softened when many bins are open or stream is early
        let openness = (open_bins_count as f64).ln().max(0.0);
        let early = 1.0 - t;
        score += 18.0 - 6.0 * openness - 10.0 * early;
        // If the item is large, a fresh bin is fine
        score -= 0.15 * fit;
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // placing into below-mean-residual bins preserves larger free space elsewhere
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev;

    // Mild preference for fewer open bins when stream is late
    score += 0.02 * (open_bins_count as f64) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 30.0 * poly * (1.0 + 0.5 * progress);
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);
    // penalize near-mean residuals (wasted space matching average is uninformative)
    score += 0.1 * (pr - mean_residual).abs() * (0.5 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }
    // lookahead: favor leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 6.0 * (1.0 - pr / nxt.max(1.0));
        }
    }
    // new-bin candidate: prefer opening a bin early, less so late
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress) - 5.0 * progress;
    }
    // mild penalty for many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals in [0..=10] are near-perfect; [11..=20] good; >40 poor.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else if pr > 50 {
        score += 25.0; // large dead space
    }

    // Modulo classes on post_residual: leftovers that are multiples of 10
    // match the classic capacity grid and pair well with future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Odd/awkward leftovers (mod 5 != 0) are harder to fill later.
    if pr % 5 != 0 && pr > 0 {
        score += 4.0;
    }

    // Integer-division thresholds: can next_item_size fit into the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // lookahead chains nicely
            // extra bonus if it fits almost exactly
            if pr - next_item_size <= 5 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins: penalize bins with large residual relative to mean.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * 20.0;

    // Encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln() * 3.0 * frac;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of a new bin, reduced if stream is early (more items to come).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + desperation * 25.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that no plausible future item (min size 1) can use is pure waste;
    // residuals in the awkward band (1..=15) are penalized super-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 15.0 {
        score += (16.0 - pr) * (16.0 - pr) * 1.5;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 10.0 * (fill_ratio - 0.7);
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize opening new bins); when few, allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += pressure * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else {
            // discourage new bin unless best existing fit would leave dead space
            score += mean_residual * 0.5;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // gap too small for next item: mild penalty proportional to waste
        score += (next_item_size as f64 - pr).min(20.0) * 0.3;
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly here -> very desirable.
            if diff <= 2.0 {
                score -= 400.0;
            } else if diff <= 10.0 {
                score -= 150.0;
            } else {
                score -= 50.0 * (1.0 - diff / cap);
            }
        } else {
            // Next item would NOT fit here; penalize leaving awkward small residual.
            let gap = nxt - post_residual as f64;
            if gap <= 10.0 {
                score += 80.0 + gap * 5.0; // tantalizing but unusable dead space
            } else {
                score += 20.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tighter",
    // prefer packing them tighter to consolidate open bins.
    let rel = post_residual as f64 - mean_residual;
    score += 0.6 * rel;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 250.0;
        let pressure = if fitting_bins_count == 0 { -400.0 } else { 0.0 };
        let lookahead_bonus = if next_item_size > 0 && (bin_capacity as u32 - next_item_size) >= item_size { -50.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base + pressure + lookahead_bonus - 100.0 * (1.0 - progress);
    }

    // Mild preference to fill already-open bins to limit bin count growth.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins left with small usable residue.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 22.0 * tight * tight;

    // Dead-space penalty: residue too small for the smallest plausible item (<=10)
    // is unusable; penalize proportionally.
    if post_residual < 10 {
        score += 30.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Mild reward for keeping options open, scaled by how many fit.
        score -= 2.0 * (fitting_bins_count.min(6) as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // decent fitting bins exist and the item is small relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_pen = 12.0 + 20.0 * (1.0 - item_frac);
        if fitting_bins_count == 0 {
            new_bin_pen -= 25.0; // forced to open
        }
        if fitting_bins_count == 1 {
            new_bin_pen += 15.0; // avoid wasting the last-chance bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_pen += 8.0 * progress;
        score += new_bin_pen;
    }

    // Lookahead coupling: if the next item would fit nicely into the post
    // residual, reward this placement; otherwise penalize blocking it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Global pressure: when many bins are open with large mean residual,
    // encourage filling existing bins rather than spreading.
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.05 * spread * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 6.0 * norm_pr * (1.0 - progress);

    // Dead-space penalty: residuals too small for any item (min size 1, but small unusable slivers)
    let dead = (1.0 - norm_pr * 2.0).max(0.0);
    score += 5.0 * dead * dead;

    // Lookahead coupling: reward residuals that fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for spreading across many bins vs mean residual alignment
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Slight preference for tighter fits as stream progresses
    score *= 1.0 + 0.3 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: residues modulo 10
    let r = (post_residual % 10) as f64;
    // Dead space penalty grows quadratically for awkward residues (1..9), zero for 0
    if post_residual > 0 {
        score += r * r * 0.35;
    }

    // Integer-division thresholds: post_residual in harmonic bands
    let band = post_residual / 10; // 0..=9
    score += band as f64 * 4.0;

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 120.0;
        // Harmonic match: next_item_size % 10 == post_residual % 10 => near-exact chain
        if next_item_size % 10 == post_residual % 10 {
            score -= 60.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use leftover: penalize proportional to leftover size
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 150.0;
        // opening new bin is fine late in the stream when bins are crowded
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
        if open_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mild preference for tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Early stream: be less picky (encourage filling first bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.6 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (below typical min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small for a plausible future item (1..=100 range, small items rare).
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits: low post_residual relative to item size.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= 25.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual below mean (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 0.5;
        // But if no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Early stream: be slightly more open to new bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the lookahead item fits exactly into the post residual (perfect 2-chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.9;
        if slack == 0.0 {
            score -= 40.0; // exact 2-step match
        }
    } else if next_item_size > 0 {
        // Lookahead item cannot follow: penalize proportional to how far off it is.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Prefer bins tighter than average (small residual => good packing).
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += (resid - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Penalize creating tiny unusable dead space (< 10).
    if resid > 0.0 && resid < 10.0 {
        score -= 25.0; // near-perfect fill is excellent
    } else if resid == 0.0 {
        score -= 50.0; // perfect closure
    }

    // Mild preference for consolidating into few bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.15;

    // New-bin candidate: make it moderately attractive only when current bin would leave bad waste.
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 120.0; // an open bin handles the 2-chain better; deprioritize new bin
        } else if waste_if_placed < 10.0 && waste_if_placed > 0.0 {
            score += 80.0;
        } else {
            score += 15.0; // slight default preference for reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: leftover that cannot fit the next item is wasted
    // unless it is small enough to be plausibly usable later.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally.
            score += 0.5 * (post_residual as f64) * (1.0 + progress);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Bin remains usable for the next item: reward.
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is justified only when
    // existing bins would create large dead space or fits are plentiful.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 60.0;
        // More willing to open a new bin when many bins already fit the item
        // (placement elsewhere is easy, so a fresh bin keeps options open).
        score -= 6.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (long horizon to fill them).
        score -= 25.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is attractive.
        score -= 0.2 * item_size as f64;
        // If open bins are mostly full (low mean residual), new bin is fine.
        if open_bins_count > 0 && mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
    } else {
        // Slight preference for filling bins that are already mostly used,
        // keeping many medium-residual bins available.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global fragmentation pressure: when many bins are open with scattered
    // residuals, favor placements that consolidate (reduce mean residual).
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // Mild open-bins count pressure: discourage hoarding too many open bins late.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, smoothed by a quadratic term that
    // increasingly punishes large dead space as the stream progresses.
    let mut score = pr + 0.35 * (pr * pr) / cap * (0.5 + progress);

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item is slightly larger than post-residual, penalize wasting space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 4.0 * (1.0 - (diff / cap).abs()) * (1.0 + progress);
        } else {
            score += 2.5 * (-diff / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate: only attractive when existing bins would leave bad dead space
    // or mean residual across open bins is already low (bins nearly full).
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if fitting_bins_count > 0 {
            (pr / cap).powf(1.5) * 10.0
        } else {
            0.0
        };
        score += 15.0 + bad_fit_penalty - 6.0 * (mean_residual / cap) * (1.0 + progress);
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls into.
    let item_class = item_size / 10;          // 0..=10 coarse harmonic class
    let next_class = next_item_size / 10;     // 0 means no lookahead item

    // Reward near-perfect fills: post_residual in the "harmonic residue" set.
    // Residues that are classically reusable (fit small harmonic classes) are less bad.
    let reusable = matches!(post_residual, 0 | 10 | 20 | 25 | 30 | 40 | 50);
    if reusable {
        score -= 4.0;
    } else {
        // Dead-space penalty grows super-linearly for awkward residues.
        score += (post_residual as f64) * 0.15;
    }

    // Exact fill is the dream.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving a residue that nothing from the typical size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward when the leftover post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item's class matches the residue's harmonic band.
        let residue_class = post_residual / 10;
        if residue_class == next_class {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to mismatch.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current bin would be badly fragmented or the item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Large items waste less in a fresh bin; small items should use open bins.
        score -= item_class as f64 * 2.5;
        // If no bin fits well (few fitting bins relative to open bins), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Lookahead: if next item is also large, a fresh bin may serve both poorly;
        // slight penalty to discourage chaining large items into fresh bins.
        if next_class >= 7 && item_class >= 7 {
            score += 6.0;
        }
    }

    // Prefer filling bins that are already far from the mean residual (balance avoidance):
    // tighten bins whose residual is much larger than average.
    if bin_residual as f64 > mean_residual * 1.5 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Early in the stream, allow more freedom to open bins (exploration);
    // late in the stream, be conservative and squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0; // later => opening bins is more costly
    } else {
        score -= progress * 2.0;  // later => favor using open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically >= 10 in classic streams).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits proportionally: fraction of bin consumed by this item.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && !(post_residual > 0 && post_residual <= 10) {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(20.0);
    }

    // New-bin candidate handling: an empty bin should only win when every
    // open bin would produce a bad fit (large dead space or big leftover).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // If the current item would leave a very large unusable remainder
        // in an existing bin, a fresh bin becomes more attractive.
        if post_residual > 0 && post_residual <= 10 {
            score -= 55.0;
        }
        // Lookahead: if the next item fits nicely into the residual this
        // placement would leave, opening a new bin is even better.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: penalize if the next item cannot use the leftover.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // Slight preference for bins whose residual is below the mean
        // (fill the fullest bins first, classic best-fit behavior).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly (or nearly) fills the post_residual of this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item chain completion: this bin becomes exactly full.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
        } else {
            // Next item will not fit after this placement: penalize the
            // unusable leftover, scaled by how large the waste is.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * waste;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual close to the mean wastes the bin's differentiation.
    let pr = post_residual as f64;
    let mean_gap = (pr - mean_residual).abs();
    score += 0.10 * mean_gap;
    // Small residuals are valuable; big ones are dead space.
    if pr > 0.0 && pr < 10.0 {
        score -= 12.0; // nearly-perfect fill
    } else if pr > 50.0 {
        score += 0.20 * (pr - 50.0); // large dead space penalty
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a well-shaped residual; encourage when item is big.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 {
            score -= 25.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin supports the 2-step chain
        }
    }

    // Mild stream-progression modulation: tighten packing early,
    // allow slightly more liberal late-stage fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // Small tie-breaker against fragmentation in crowded bin sets.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Future items are in [1,100]; residuals > 80 are "usable-ish", tiny residuals are waste.
    if post_residual > 0 {
        let waste = 1.0 - (post_residual as f64 / 80.0).min(1.0);
        score += 20.0 * waste * waste;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it packs the remainder.
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * chain_tight;
        } else {
            // Next item won't fit here; slight penalty for fragmenting space.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin when few bins are open (less fragmentation risk)
        // and when the mean residual of open bins is large (existing bins are roomy anyway).
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if mean_residual > (item_size as f64) + 10.0 {
            score += 8.0; // existing bins have plenty of room; don't open a new one
        } else {
            score -= 12.0; // open bins are cramped; a fresh bin is attractive
        }
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // If exactly one bin fits and it would leave a bad residual, new bin is competitive.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }
    }

    // Mild penalty when many bins are open and this bin is far below mean residual
    // (prefer consolidating into fuller bins to close them out).
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * dev;
    }

    // Encourage filling bins toward closure as the stream progresses.
    if bin_residual != bin_capacity {
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score -= 5.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Smooth non-linear coupling: residual cost amplified quadratically as stream progresses
    score += norm_pr * norm_pr * (1.0 + 40.0 * progress);
    // Reward tight fits: cubic decay of score with small post-residual
    score -= (1.0 - norm_pr).powi(3) * 15.0;
    // Last-chance bin: strong bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }
    // Penalize bins far below mean residual (poor consolidation) with smooth term
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / (cap * cap + 1.0);
    // Lookahead: if next item fits into resulting post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 10.0 * progress;
    }
    // Slight preference to keep fewer open bins early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (harmonic class of post_residual).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 20.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item can fill the post_residual exactly or nearly, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= (20.0 - gap as f64) * 1.5;
            } else {
                // next item leaves another residual; mild bonus scaled by gap
                score -= 5.0;
            }
        } else {
            // next item won't fit in post_residual: penalize large leftovers
            let over = next_item_size - post_residual;
            if over <= 10 {
                score += over as f64 * 0.5;
            }
        }
    }

    // Dead-space penalty for mid-range residuals (harmonic class 30..60 is wasteful).
    if post_residual >= 30 && post_residual < 60 {
        score += (post_residual as f64 - 30.0) * 0.4;
    }

    // New-bin candidate handling: opening a new bin should lose unless
    // no other bin fits or the fit is exceptional.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // last-chance bin exists; only open new bin if fit here is perfect
            if item_size == bin_capacity {
                score -= 80.0;
            }
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure against spreading across too many open bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.3 * (1.0 - progress);
    }

    // Slight nudge toward bins below mean residual (balance residuals).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (below typical minimum item size 1..100,
    // treat gaps <= 10 as dead unless nearly zero).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // If this bin can fit the next item too, encourage preserving it for that item
    // when post_residual would otherwise be wasted.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 20.0;
    }
    // Penalize using a bin whose residual is exactly what the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residuals close to the item (tight fit relative to mean).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // New-bin candidate: baseline competitive score; only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 100.0 + open_bins_count as f64 * 0.2;
        // If the only fitting bin would leave bad dead space, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-item packing: item + next item fills bin exactly
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item still fits: penalize proportionally to leftover waste
            let two_step_waste = post_residual - next_item_size;
            score -= 200.0 - (two_step_waste as f64) * 1.5;
        } else {
            // Next item won't fit: penalize dead space more harshly
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.8;
        }
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless current fit is terrible
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin
        score += 120.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 60.0;
        }
        // Fewer open bins -> cheaper to open another
        score -= (10usize.saturating_sub(open_bins_count)) as f64 * 2.0;
    }

    // Mild preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Early in stream: slightly prefer keeping residuals flexible
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap.
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist, unless item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score += 20.0 + 0.3 * open_bins_count as f64 + 0.1 * waste - 10.0 * progress;
        // Allow new bin when existing bins would leave very fragmented space.
        if post_residual < 10 && fitting_bins_count > 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with below-mean residual (consolidate emptier space).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Mild reward for filling bins completely over the stream horizon.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;
    let item_f = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    score += (x * x) * (1.0 + 2.0 * progress) * 20.0;
    score -= (1.0 - x) * (1.0 - x) * 30.0 * (0.5 + progress);

    // Reward tight fits more strongly late in the stream
    score -= (item_f * item_f) * 40.0 * (1.0 + progress);

    // Penalize creating dead space relative to mean residual of open bins
    score += (pr - mean_residual) * 0.5;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x * x);
    }

    // Lookahead: favor residual that can still hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 15.0;
        } else {
            score += 15.0;
        }
    }

    // Mild penalty when many bins are already open (encourage consolidation)
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: make it less attractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead-space classes: tiny leftovers are worthless; quarter/half classes are reusable.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score += 40.0; // dead sliver
    } else if post_residual <= 10 {
        score += 15.0;
    } else {
        // reward residuals that belong to "usable" harmonic classes
        let q = post_residual / 10; // integer division class
        let class_bonus = match q {
            1 => 10.0,          // 10..19
            2 => 6.0,           // 20..29
            3 => 3.0,           // 30..39
            4 => 8.0,           // 40..49 (half-ish, very reusable)
            _ => 0.0,
        };
        score -= class_bonus;
    }

    // --- Coupling with lookahead item ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // next item fits this bin perfectly
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward only if leftover after next item stays in a good class
            if slack <= 10.0 {
                score -= 120.0 - slack * 4.0;
            } else {
                score -= 30.0 - slack * 0.3;
            }
        } else {
            // next item cannot use the leftover: leftover likely dead
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 1.5;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0; // strongly prefer using the only fitting bin
    }
    if fitting_bins_count == 0 {
        score -= 500.0; // must open new bin anyway
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only good if the fit elsewhere is poor (large post_residual)
        // or no existing bin fits. Base cost of a fresh bin:
        score = cap_f * 0.9;
        if fitting_bins_count == 0 {
            score -= 400.0; // forced
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin gives room for large lookahead
        }
    } else {
        // Prefer bins whose residual is close to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64; // == post_residual
        score += (mean_residual - post_f).max(-50.0) * 0.2;
        // mild preference for packing into bins with below-average residual (fill fuller bins first)
        if post_f < mean_residual {
            score -= 5.0;
        }
        let _ = tightness;
    }

    // --- Progression modulation: late in stream, be greedier about tight fits ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // --- Modulo harmonic penalty on post_residual (avoid awkward classes) ---
    let m = post_residual % 7;
    if m == 1 || m == 5 {
        score += 4.0;
    } else if m == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_gap = (mean_residual.max(0.0) / cap).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let open_pressure = open / (open + 5.0);

    let mut score = post;

    // Strongly reward completely closing a bin.
    if post_residual == 0 {
        score -= 0.80 * cap + 0.30 * item;
    }

    // Reward leaving exactly the lookahead item's required space.
    if next > 0.0 && post_residual == next_item_size {
        score -= 0.50 * cap + 0.20 * item + 0.10 * cap * (1.0 - progress);
    }

    // If this is the only existing bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 0.45 * cap + 0.15 * item + 0.10 * cap * (1.0 - progress);
    }

    // Penalize nonzero residuals that are too small for the next item.
    // The penalty is strongest for very tight unusable gaps, but preserves best-fit ordering.
    if next > 0.0 && post > 0.0 && post < next {
        let deficit = next - post;
        let tightness = deficit / next;

        score += deficit * (0.65 + 0.10 * tightness)
            + cap * tightness * (0.15 + 0.10 * progress + 0.10 * open_pressure);
    }

    // Mild consolidation pressure toward existing open bins.
    if !is_new_bin {
        score -= 0.04 * cap * open_pressure * (1.0 - post / cap).max(0.0);
    }

    // New-bin candidate pressure.
    if is_new_bin {
        let can_absorb_next = next > 0.0 && post >= next;

        let mut new_penalty = if can_absorb_next {
            // Opening may be acceptable if it can pair the current item with the lookahead item.
            0.12 * cap + 0.03 * cap * open + 0.08 * cap * (1.0 - progress)
        } else {
            // Opening a bin that cannot even absorb the next item is usually costly.
            0.85 * cap + 0.07 * cap * open + 0.30 * cap * mean_gap + 0.10 * cap * progress
        };

        if fitting_bins_count > 0 {
            let fit_pressure = if can_absorb_next {
                0.30 * cap
            } else {
                0.60 * cap
            };

            new_penalty += fit_pressure + 0.04 * cap * (fits - 1.0);

            if fitting_bins_count == 1 {
                new_penalty += if can_absorb_next {
                    0.12 * cap
                } else {
                    0.35 * cap
                };
            }
        }

        new_penalty += 0.05 * cap * mean_gap * (1.0 - progress);
        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact/near matches between post_residual
    // and next_item_size (the next item can perfectly fill this bin afterwards).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let gap = post_residual as f64 - nx;
            // Strong reward for perfect chain fit (gap 0), decaying with gap size
            let chain_reward = 60.0 * (-gap / 25.0).exp();
            score -= chain_reward;
            // Extra bonus when the chain fit leaves nothing wasted
            if gap == 0.0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot
            let over = next_item_size as u32 - post_residual;
            score += (over as f64) * 0.15;
        }
    }

    // Penalize post_residuals that are small-but-unusable (dead space).
    // Dead space = residual too small for typical items (assume min item ~1,
    // so instead penalize residuals far below mean residual context).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += (mean_residual * 0.5 - pr) * 0.4;
    }

    // Prefer tight fits generally: reward small post_residual relative to bin capacity
    score -= 20.0 * (1.0 - pr / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual is huge, i.e. fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if all existing fits are poor (post_residual high everywhere).
            score += 35.0;
            // Allow new bin early in stream when few bins are open (diversification)
            if open_bins_count <= 2 && progress < 0.3 {
                score -= 30.0;
            }
        }
        // Reward new bin if lookahead chain is impossible in existing bins
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: placing into a bin whose post_residual stays
    // near the mean keeps flexibility; extremes are penalized slightly.
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize large dead space that nothing small could use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is only attractive if the item
    // fits poorly everywhere (low fit_ratio) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fit_ratio < 0.6 {
            score -= 35.0 * (0.6 - fit_ratio);
        }
        // Prefer new bins early when few bins exist; penalize when many open.
        score += (open_bins_count as f64) * 1.5;
    }

    // Lookahead: if next item could fill this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item too big for the leftover: dead space likely.
            score += 4.0;
        }
    }

    // Global state: spread of residuals vs mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Core: prefer low post-residual, with a non-linear polynomial coupling
    // to stream progress (later in the stream, tighter packing is rewarded more).
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward near-perfect fits with a smooth quadratic discount.
    let fit_quality = 1.0 - pr_norm;
    score -= 15.0 * fit_quality * fit_quality;

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0);
        score += 0.4 * waste + 0.02 * waste * waste / cap;
        // Bonus if post-residual still accommodates the next item smoothly.
        let accommodates = (ni / cap) * (1.0 - pr_norm).max(0.0);
        score -= 6.0 * accommodates;
    }

    // Last-chance bin: strongly favor using it (smooth exponential-style term).
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty for opening new bins when many are open (smooth in count).
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins with residual below mean residual (compact bins first).
        score += 0.3 * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Harmonic class of post_residual relative to capacity fractions.
        let cap = bin_capacity as f64;
        let pr = post_residual as f64;

        // Dead-space classes: residuals that no typical item (1..=100) can usefully
        // fill later are penalized. Small residuals (1..=9) are nearly unusable.
        if post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 4.0;
        }

        // Modulo classes on post_residual: residuals that match common item sizes
        // (multiples of 5 / 10) are more reusable.
        if post_residual % 10 == 0 {
            score -= 25.0;
        } else if post_residual % 5 == 0 {
            score -= 12.0;
        } else {
            score += 8.0;
        }

        // Fractional capacity thresholds: classify how full the bin becomes.
        let fill_fraction = (bin_capacity - post_residual) as f64 / cap;
        if fill_fraction >= 0.9 {
            score -= 40.0;
        } else if fill_fraction >= 0.7 {
            score -= 20.0;
        } else if fill_fraction < 0.4 {
            score += 15.0; // leaving a bin barely used is wasteful
        }

        // Lookahead coupling: if the next item fits into the post residual, reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 90.0; // guaranteed chain fit
            } else if next_item_size < post_residual {
                // integer-division threshold: how "deep" the next item sinks in
                let depth = post_residual / next_item_size.max(1);
                if depth >= 2 {
                    score -= 15.0;
                } else {
                    score -= 30.0;
                }
            } else {
                // next item cannot fit here: penalize more if we created dead space
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor it
        // unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 35.0 + pr * 0.2;
        }

        // Many open bins: prefer tighter packing, discourage spreading.
        if open_bins_count > 4 {
            score += pr * 0.05;
        }

        // Compare against mean residual: below-mean residual (tighter than average)
        // is rewarded.
        score -= (mean_residual - pr) * 0.4;
    }

    // New-bin candidate handling: an empty bin gets a baseline score that makes it
    // attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a perfect/tight fit, better than dead space.
        score = cap - (item_size as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // next item can join the fresh bin
        }
    }

    // Mild stream-progression modulation: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Gaps below this threshold are unlikely to ever host a future item ("dead").
    // The zone shrinks as the stream ends (fewer chances left, compactness dominates).
    let dead_thresh = (18.0 * (1.0 - 0.4 * progress)).clamp(2.0, 18.0);

    // Within the dead zone, tighter leftovers are WORSE: a 1-unit sliver is deader
    // than a 15-unit shelf. The penalty must outweigh the base residual ranking so
    // that leaving a usable (>= threshold) gap beats leaving an unusable crumb.
    // A perfect fit (post_residual == 0) is never penalized.
    let mut dead_pen = 0.0;
    if pr > 0.0 && pr < dead_thresh {
        let d = dead_thresh - pr;
        dead_pen = 1.2 * d + 0.05 * d * d;
        // open_bins_count coupling: with many bins open, wasted slivers hurt more.
        dead_pen *= 1.0 + 0.03 * open_bins_count as f64;
    }

    // --- Lookahead coupling (k=2) ---
    let mut lookahead_bonus = 0.0;
    if nis > 0.0 {
        if nis == pr {
            lookahead_bonus = -6.0; // sets up a perfect fit on the next step
        } else if nis <= pr {
            dead_pen *= 0.5; // gap is demonstrably reusable by the next item
            lookahead_bonus = -1.5 * (nis / pr);
        } else if pr > 0.0 {
            // gap cannot host the lookahead item: extra dead-space sting
            score += 0.8 * ((nis - pr) / nis);
        }
    } else if is_new_bin {
        // Last item: opening a bin for the final item is almost always waste.
        score += 10.0;
    }
    score += dead_pen + lookahead_bonus;

    if is_new_bin {
        // --- open_bins_count pressure on the new-bin candidate ---
        // A fresh bin gets costlier as the fleet of open bins grows, and later
        // in the stream (fewer items left to ever fill it).
        let new_penalty = (3.0 + 0.6 * open_bins_count as f64) * (1.0 + 0.5 * progress);
        score += new_penalty;
        if pr >= dead_thresh {
            score -= 2.0; // the fresh gap is genuinely usable, mild discount
        }
    } else {
        // Last-chance bin: the only open bin that can host this item.
        if fitting_bins_count == 1 {
            let usable = pr == 0.0 || pr >= dead_thresh || (nis > 0.0 && nis <= pr);
            score -= if usable { 8.0 } else { 0.5 };
        } else if fitting_bins_count == 2 {
            score -= 1.0;
        }
        // Best-fit tie-break: prefer bins tighter than the fleet average.
        score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: heavy bonus; near match: partial bonus
        if diff == 0.0 {
            score -= 1000.0;
        } else if diff <= 5.0 {
            score -= 100.0 - diff * 15.0;
        } else {
            score += diff * 0.5; // penalize awkward leftover relative to next item
        }
    }

    // If next item cannot fit in post_residual, penalize dead space proportionally
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward filling bins tightly (small post residual) more when many bins are open
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (10.0 + open_bins_count as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer bins with residual below the mean (compact bins get closed out)
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early in the stream, be more willing to open new bins (keep options open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize less early, more late (favor reusing bins late)
        score += 40.0 + progress * 40.0;
    }

    // Mild penalty for wasting a large bin on a tiny item
    if (item_size as f64) < 0.25 * bin_capacity as f64 && bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for chaining badly.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins (reduce bin count pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global state coupling: if mean residual is high, favor closing gaps in emptier bins;
    // if mean residual is low, conserve by preferring tightest fits.
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.15 * deviation;

    // Time horizon: late in the stream, be more conservative (favor tight fits, avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fill_ratio;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let waste = (bin_capacity - item_size) as f64;
        score += 22.0 * desperation + 0.2 * waste - 10.0 * progress;
        // Opening a new bin is fine if the current item is huge (leaves small residual anyway).
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    let progress_term = progress * progress * (1.0 - progress);
    score -= 18.0 * tightness * (0.5 + progress_term * 4.0);

    // Smooth penalty for wasted residual scaled by how much of the bin remains dead.
    let waste = (pr / cap).powi(3);
    score += 10.0 * waste * (1.0 + progress);

    // Penalize the brand-new bin candidate smoothly (residual == capacity).
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (25.0 + 30.0 * (1.0 - progress) + 8.0 * open_bins_count as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly reward it.
    let last_chance = (fitting_bins_count == 1 && is_new == 0.0) as f64;
    score -= last_chance * 40.0;

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap).powf(2.0);
        score -= 12.0 * fits_next * snug * (1.0 + progress);
    }

    // Mild pressure toward consolidating into bins below the mean residual.
    score += 0.15 * (mean_residual - pr).max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space in low-value classes is penalized.
    // Residuals that are multiples of common small item sizes (5,10) remain reusable.
    let pr = post_residual;
    if pr > 0 {
        let class = match pr % 10 {
            0 => -25.0,           // perfectly reusable
            5 => -10.0,           // half-class reusable
            1 | 9 => 12.0,        // awkward slivers
            2 | 8 => 8.0,
            3 | 7 => 5.0,
            _ => 2.0,
        };
        score += class;
    }

    // Dead-space penalty grows quadratically once residual is too small for typical items.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.8;
    }

    // Lookahead coupling: reward leaving room exactly for the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 45.0; // perfect two-item chain
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how badly it misses
            score += 6.0 * (next_item_size - pr).min(30) as f64 / 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual across
    // open bins. Only attractive when existing residuals are large (poor fits)
    // or many bins are open with fragmented space.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin; drop it when fragmentation is high.
        score = 70.0 + waste * 0.5 - 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild global pressure to prefer filling existing bins as stream progresses.
    score += progress_factor(step_index, total_items) * 3.0;

    score
}

fn progress_factor(step_index: usize, total_items: usize) -> f64 {
    (step_index as f64 / (total_items.max(1) as f64)).min(1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (fragmented).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 2 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space relative to capacity (non-linear).
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 200.0 * waste_ratio * waste_ratio;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - 1.5 * slack;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.8 * shortfall;
        }
    }

    // Compare against mean residual: bins deviating far from mean are less attractive
    // unless the fit is tight.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred, reduced when the item is large
        // (poor packing prospects) or many bins are already open with big residuals.
        let mut new_bin_score = 120.0
            - 0.5 * item_size as f64
            + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            // Next item can't fit in a fresh bin either? (impossible for empty bin)
            new_bin_score += 0.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 40.0 * progress;
        score += new_bin_score;
    }

    // Mild bonus for keeping many open bins from proliferating.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fills strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for small dead space: tiny residuals are very valuable
        // only if a future item can use them; otherwise they are dead weight.
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 0.5);
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead coupling: penalize placements that leave a residual that the
    // next item cannot use but that is too small to be generally useful.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx && post_residual > 0 {
            // Dead space relative to the known future demand.
            score += 40.0 + 0.5 * (nx - post_residual as f64);
        } else if (post_residual as f64) == nx {
            // Perfect lookahead pairing: chain fill.
            score -= 300.0;
        } else if (post_residual as f64) >= nx {
            // Residual still usable by next item: mild reward scaled by slack.
            score -= 10.0 * (1.0 - (post_residual as f64 - nx) / bin_capacity as f64);
        }
    }

    // Global state coupling: if many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        let mr = mean_residual;
        if mr > 0.0 {
            // Favor bins tighter than average (below-mean residual = good fit).
            let fit_gap = (bin_residual as f64) - mr;
            score += 0.3 * fit_gap;
        }
        // When many bins are open, discourage adding more fragmentation.
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin's score is its post_residual
    // (= capacity - item_size). Make it attractive only when the item is large
    // (little would remain anyway) or late in the stream; otherwise opening a
    // new bin should lose to a decent existing fit.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress);          // early stream: prefer existing bins
        score += 0.2 * open_bins_count as f64;      // many open bins: don't add another
        if item_size >= 60 {
            score -= 80.0;                          // large item: new bin is fine
        }
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 2.0 * progress * (1.0 - x) - 1.5 * progress * progress * x * (1.0 - x);
    score *= poly;

    // Reward tight fits, more so later in the stream
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't hold the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (pr - nx).max(0.0) / cap;
        score += 4.0 * unusable * unusable * (1.0 + progress);
        // Bonus when post_residual exactly accommodates next item
        if pr >= nx && (pr - nx) < 10.0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and residual is far above mean
    score += 0.05 * (pr - mean_residual).max(0.0) * (open_bins_count as f64).ln().max(1.0);

    // Penalize wasteful new-bin opening unless current bins fit poorly
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 5.0 * waste * waste + 2.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes near 0 are great,
    // mid-range residuals (30..60) are "poison" classes.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect/near-perfect fit -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Poison band: residual that most items (10..80) cannot use efficiently
    if post_residual >= 25 && post_residual <= 60 {
        score += 0.35 * (pr - 25.0);
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // item sizes divisible by 10 (common in many distributions).
    let pr_class = post_residual % 10;
    let item_class = item_size % 10;
    if pr_class == 0 {
        score -= 8.0;
    }
    if item_class == 0 && pr_class == 0 {
        score -= 6.0;
    }

    // Capacity-fraction thresholds: residual below 1/4 of capacity is
    // nearly dead space; reward pushing bins into that regime.
    if pr < c * 0.25 {
        score -= 12.0 * (1.0 - pr / (c * 0.25));
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a harmonic pair -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let after2 = post_residual - next_item_size;
            if after2 <= 10 {
                score -= 20.0;
            }
            // penalize if next item would leave a poison residual
            if after2 >= 25 && after2 <= 60 {
                score += 5.0;
            }
        } else {
            // next item cannot fit here: mildly penalize wasting large residual
            if pr > 50.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): should only win when no open bin fits
    // well. Penalize the empty bin by default; scale penalty with how many
    // bins are already open and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // pairing next big item with fresh bin later is fine
        }
    }

    // Prefer fuller bins relative to fleet mean residual.
    if (pr - mean_residual).abs() > 0.0 {
        score += 0.05 * (pr - mean_residual);
    }

    // Mild pressure to consolidate: fewer open bins -> tighter packing.
    score += 0.5 * open_bins_count as f64 * (pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: proportional fit quality.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; penalize placements that leave large residual when
    // the bin count is already high.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If current item leaves a large residual and next item could use a
        // fresh bin, opening new becomes relatively better.
        if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 15.0;
        }
        // Under heavy open-bin pressure, opening new bins is cheaper than
        // fragmenting; scale cost down.
        score -= pressure * 25.0;
        // Early in the stream, new bins are cheap (few bins committed).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let gap = post_residual - next_item_size;
        if gap <= 9 {
            score -= 20.0;
        }
    }

    // Slight preference toward bins below mean residual (balance load).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect two-step matches. If the next item exactly fills
    // the post_residual, this placement is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead match bonus: the closer next_item comes to filling
        // the leftover, the better.
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match jackpot.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving a gap that no item of plausible size can fill:
        // dead space smaller than the minimum item size is wasted forever.
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: pure tightness packing, prefer minimal post_residual.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize wasteful large leftovers relative to capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Context: compare against mean residual of open bins. Placing into a bin
    // whose residual is far above mean helps consolidate; far below mean is bad.
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or all existing fits would leave big dead space. Otherwise
    // discourage opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 18.0;
            // If the item is large relative to mean residual, opening fresh
            // space can be worthwhile.
            if item_size as f64 > mean_residual {
                score -= 22.0;
            }
        }
    }

    // Slight stream-progression tilt: later in the stream, prefer tighter
    // packing over spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    if item_size > 0 {
        score -= 0.9 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);
    }

    // Penalize dead space: post-residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += 3.0;
        }
    }

    // Time horizon: late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64;
    }

    // Compare against mean residual: bins below-mean residual are precious; keep them.
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: make empty bin slightly less attractive unless residuals are large.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        if mean_residual < 15.0 {
            score -= 10.0; // existing bins nearly full, opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate moderate residuals; late: punish wasted space quadratically.
    let w = 1.0 + 2.0 * progress * progress;
    score += w * 30.0 * pr * pr * (1.0 - fit);

    // Reward tight fits (small post_residual) with smooth cubic reward.
    score -= 20.0 * (1.0 - pr).powi(3) * (0.5 + 0.5 * progress);

    // Penalize when this bin is one of many fitting bins (prefer scarce fits).
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0).powi(2) / (open_bins_count as f64 + 1.0);
    } else {
        score -= 15.0; // last-chance bin: strong reward
    }

    // Lookahead coupling: smooth interaction between post_residual and next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = nx - pr;
        // Perfect lookahead fit bonus (smooth Gaussian-like term).
        score -= 25.0 * (-(gap * gap) / 0.02).exp();
        // Penalize residuals that are uselessly small for the next item.
        score += 12.0 * progress * (1.0 - (pr / (nx + 0.1)).min(1.0));
    } else {
        // Last item: only residual waste matters.
        score += 10.0 * pr * pr;
    }

    // Mean residual coupling: prefer bins deviating smoothly from the mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev * progress;

    // Mild penalty for spreading across many open bins, smoothed by progress.
    score += 1.5 * (open_bins_count as f64).powi(2) / (cap * (1.0 + progress));

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - (fitting_bins_count as f64).recip());
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residues that are "usable"
    // for typical small items are rewarded; awkward residues penalized.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 14.0,           // perfectly round residual, highly reusable
        1 | 2 => score -= 3.0,        // nearly round, decent
        9 | 8 => score += 4.0,        // just below a round number, awkward
        3 | 4 | 5 | 6 | 7 => score += 1.5,
        _ => {}
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits -> great, reward proportional to snugness
            let snug = (pr - next_item_size) as f64;
            score -= 18.0 - snug * 0.35;
            // harmonic bonus if next item lands on a round residual too
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot follow into this bin: penalize if residual is small/dead
            if pr < 10 {
                score += 12.0;
            } else {
                score += (10 - pr.min(10)) as f64 * 0.5 + 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.4;

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Progress-aware tightening: late in the stream, be more conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // New-bin candidate handling: only attractive for big items or when
    // no open bin offers a decent fit
    if bin_residual == bin_capacity {
        if item_size > 70 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + (item_size as f64) * 0.1;
        }
    }

    // Dead-space penalty: residual too small for the minimum item size
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize residuals that are too small
    // to be useful for typical future items (unusable small gaps).
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Gap is "dead" if smaller than the minimum plausible item size.
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.15);
        if pr < dead_threshold {
            score += 40.0 + (dead_threshold - pr) * 6.0;
        }
        // Non-linear penalty for moderately small gaps that few items could use.
        if pr < 30.0 {
            score += (30.0 - pr).powf(1.4) * 0.8;
        }
    }

    // Reward tight fits (post_residual near zero but still "usable" is ideal).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward creating that chain opportunity.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack.min(15.0);
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partially
    // filled bins; prefer consolidating into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 30.0 + open_bins_count as f64 * 2.5 + progress * 20.0;
        // But allow a new bin if no existing bin fits well (fitting_bins_count == 0 handled
        // implicitly since only the new bin call would then be competitive).
    } else {
        // Slight preference for bins with residuals close to the item (tight fit).
        score -= (bin_residual - item_size) as f64 * 0.05;
        // Favor bins whose residual is below mean residual (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already favored by the base term,
    // add an extra bonus when the fit is tight.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 10 {
            score -= 30.0 - 2.5 * diff as f64;
        } else {
            // Penalize leaving residuals that the next item cannot use well
            score += (diff as f64 - 10.0) * 0.5;
        }
        // If next item cannot fit in post_residual at all, mild penalty
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins with residual close to the mean
    // (balanced packing), penalize outliers.
    let res = post_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a new bin costly early, cheaper later,
    // and only attractive when the current bin would leave a large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space = item_size as f64; // would-be post_residual of the best existing bin proxy
        let _ = dead_space;
        // Base cost of a new bin, decaying with stream progress.
        let mut new_bin_cost = 120.0 - 60.0 * progress;
        // If existing bins would leave big residuals (poor fits), new bin is more attractive.
        if res > 0.0 && mean_residual > 40.0 {
            new_bin_cost -= 30.0;
        }
        // Avoid opening too many bins at once early on.
        new_bin_cost += 3.0 * open_bins_count as f64 * (1.0 - progress);
        score = new_bin_cost.max(10.0);
    }

    // Penalize wasting a large bin residual on a small item.
    if item_size < bin_residual / 4 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 10.0).floor() * 10.0;
        score += 0.8 * dead;
    }

    // Lookahead coupling: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize opening new bins when existing bins fit well.
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * mean_residual * (1.0 - progress) * (1.0 - tightness);

    // Mild time-varying tightness pressure: as stream progresses, demand tighter fits.
    score += 10.0 * progress * tightness * 10.0;

    // Fragmentation penalty: small post_residual that is unusable (nonzero but < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: dead-space penalty, weighted by progress
    let mut score = pr * (0.9 + 0.6 * p2 + 0.4 * p3);

    // Smooth polynomial interaction: tight fits rewarded more as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize wasteful low-fill placements late in the stream
    score += 8.0 * norm_pr * norm_pr * progress;

    // Last-chance bin bonus (smoothly scaled by progress)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / pr)) * (0.5 + p2);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leftover more mildly
        score += 3.0 * norm_pr * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: penalize bins deviating from mean residual (fragmentation)
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate handling: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = 25.0 + 15.0 * progress - 5.0 * tightness;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction bands
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class: f64 = if post_residual == 0 {
        -12.0 // perfect fit: strongly reward
    } else if post_residual < eighth {
        -6.0 // tiny dead space
    } else if post_residual < quarter {
        0.0
    } else if post_residual <= 2 * quarter {
        3.0 // half-ish leftover, moderately useful
    } else {
        6.0 // large leftover is fine too (still reusable)
    };
    score += post_class;

    // Modulo arithmetic on post_residual: values divisible by small ints pair well
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 2.5; }
        else if pr % 5 == 0 { score -= 1.2; }
        else { score += 0.8; }
    }

    // Lookahead coupling: reward residuals that can host the next item exactly/nicely
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chaining
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap < eighth as u32 { score -= 7.0; }
            else if gap < quarter as u32 { score -= 3.0; }
            else { score += gap as f64 * 0.03; }
        } else {
            score += 2.0; // next item won't fit here; leftover may be wasted
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so open bins with decent fits win
        score += 20.0;
        // but if current item is huge and would leave awkward residue everywhere, opening is OK
        if item_size as f64 > 0.7 * cap {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Prefer filling bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // A residual below the minimum possible item size (1) is impossible here, but residuals
    // smaller than the next item (or a generic small threshold) are "dead space".
    let min_useful = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }
    // Also penalize any gap that cannot fit the lookahead item (waste w.r.t. k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness coupling: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current bin fits
    // are poor (large dead space). Default new-bin score is its huge residual, so add a mild
    // bias and only discount it when the current placement would leave bad dead space.
    if bin_residual == bin_capacity {
        // base: residual (=capacity) is already large; add fixed opening cost
        score += 15.0;
        // discount slightly when many bins are open (consolidation pressure reversed:
        // with many open bins, a fresh bin keeps residuals balanced)
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score -= (mean_residual - bin_residual as f64).abs() * -0.0; // neutral placeholder
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Late-stream tightening: as the stream progresses, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0; // no-op placeholder for calibration symmetry
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post == 0.0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 0.5 {
            score -= 400.0;
        } else if nxt <= post {
            // next item fits here: mild reward scaled by how well it uses leftover
            score -= 50.0 * (nxt / post.max(1.0));
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.5 * post * (nxt / cap);
        }
    }

    // Compare post_residual against mean residual: prefer leaving typical slack.
    let dev = (post - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        // opening a new bin is attractive when item is large (poor fits elsewhere)
        score -= 150.0 * fit_ratio;
        score += 100.0 * (1.0 - fit_ratio);
    }

    // Slight preference to fill older/more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that no small item can likely fill.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0; // post_residual smaller than item => hard to reuse
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count <= 1 {
            score -= 35.0; // no good alternative, open new bin
        }
        // If mean residual is large, open new bins to rebalance.
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item would exactly fill post_residual, extra reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more conservative (prefer new bins to keep flexibility);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Mild penalty for many open bins with low mean residual (fragmentation).
    if open_bins_count > 4 && mean_residual < 15.0 {
        score += 5.0;
    }

    // Small reward for bins with residual near common small-item sizes.
    for r in [10u32, 20, 25, 30, 40, 50] {
        if post_residual == r {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is penalized more heavily (convex in progress).
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score *= 1.0 + 0.3 * progress_weight;

    // Reward tight fits: subtract a smooth function of normalized fill.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Last-chance bin bonus (only fitting bin): strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item exactly fills this bin's post-residual,
    // reward saving the space; if next item cannot use it, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt).abs();
            score += 0.05 * gap * (1.0 + progress);
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 0.10 * (nxt - pr);
        }
    }

    // Penalize bins far from mean residual (fragmentation signal).
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin when alternatives exist,
    // but relax as stream progresses (avoid trapping late items).
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 15.0 / (1.0 + 3.0 * progress) + 2.0 * alt;
    }

    // Mild penalty for too many open bins early on.
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bins with small post_residual get a discount.
    let tight = if post_residual == 0 {
        -50.0
    } else {
        -30.0 * (1.0 - (post_residual as f64) / cap).powi(3)
    };
    score += tight;

    // Harmonic class logic: classify post_residual by capacity fractions.
    // Dead space thresholds: post_residual < 10 is perfect, < 20 excellent,
    // < 50 half-empty, >= 50 is a "half bin" that pairs with medium items.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -20.0
    } else if pr < 10 {
        -12.0
    } else if pr < 20 {
        -6.0
    } else if pr < 50 {
        0.0
    } else {
        // Large residual: good if a future item (e.g. next_item_size) fits exactly-ish.
        4.0
    };
    score += class_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits but leaves waste: scale by how wasteful
            let waste_after = pr - next_item_size;
            score -= 15.0 * (1.0 - waste_after as f64 / cap);
        } else {
            // next item does NOT fit here: penalize leaving awkward residuals
            // that are just below next_item_size (dead space trap).
            if pr > 0 && pr < next_item_size {
                score += 6.0 * (1.0 - pr as f64 / next_item_size as f64);
            }
        }
    }

    // Modulo / integer-division thresholds on post_residual.
    // Residuals divisible into common item classes (10,20,25,50) are more reusable.
    if pr > 0 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if reusable {
            score -= 3.0;
        }
        // Odd residuals in (0,10) trap small items only; slight penalty otherwise.
        if pr % 10 != 0 && pr < 30 {
            score += 2.0;
        }
        let half = pr / 2;
        if half >= 10 && half <= 40 && pr % 2 == 0 {
            score -= 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (penalize the alternative implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin has residual == capacity. Opening a new bin is
    // only attractive if the item fits poorly everywhere else. Penalize new bin
    // unless item is large relative to capacity and fit here is bad.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // A fresh bin is neutral-to-good for large items, wasteful for small ones
        // when other bins could fit them.
        score += 10.0 - 20.0 * fill_frac;
        if fitting_bins_count > 0 {
            // Other bins exist that can fit: discourage new bin moderately.
            score += 8.0;
        }
    }

    // Stream progression: early in the stream, be frugal with bins (prefer filling
    // existing ones); late in the stream, packing quality matters more than count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (1.0 - (post_residual as f64 / cap));

    // Many open bins: prefer consolidating into bins with below-mean residual
    // (i.e., tighter bins) to leave big bins free for big items.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev; // smaller residual than mean => negative => favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Medium dead space that likely can't fit future items (below typical small item sizes) penalized.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and mean residual is large.
        score += 25.0 + pressure * 4.0 + mean_residual * 0.3;
    } else {
        // Existing bin: slight reward scaled by pressure to keep bin count low.
        score -= pressure * 1.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving residual close to but below next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += gap * 2.0;
            }
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual - item_size) as f64;
    score += (bin_capacity as f64 * 0.5 - tightness).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + 0.5 * (post_residual as f64);
    }
    // Partial lookahead credit: next item can still fit after placement
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.08 * slack;
    }
    // Penalize dead space that next item cannot use
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large post_residual relative to mean residual (wasteful bin)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fits = if next_item_size > 0 { (post_residual as f64 - next_item_size as f64).abs() } else { 0.0 };
        score -= 8.0 + 10.0 * progress - 0.2 * poor_fits;
        // Discourage opening new bins when many are already open with room
        score += 0.5 * open_bins_count as f64;
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins left with zero (or tiny) residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // Dead-space penalty: residual too small to ever fit a future item (min size 1..100 unknown,
    // but assume small items exist; penalize residuals below a "usefulness" band nonlinearly).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let useful = (pr / 20.0).min(1.0);
        score += (1.0 - useful) * (1.0 - useful) * 60.0;
    }

    // Tightness bonus: reward filling a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Lookahead coupling: if the next item fits the post-residual exactly or well, reward;
    // if post-residual can't hold next item, slight penalty for wasting usable space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let chain_fit = 1.0 - (pr - nxt).abs() / cap;
            score -= chain_fit * 35.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (unless fit is terrible, handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // many bins are open with scattered residuals (fragmentation) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let frag = (mean_residual / cap - 0.5).abs(); // dispersion proxy
        score -= 25.0 * (1.0 - progress) + 30.0 * frag * open_bins_count as f64;
        // Discourage new bins when a decent fit exists elsewhere:
        if fitting_bins_count > 0 && pr >= 10.0 {
            score += 15.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Small noise-free time modulation to break ties across the stream horizon.
    score += ((step_index as f64 * 0.017).sin()) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, minimize residual aggressively.
    let waste_weight = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score += waste_weight * (pr / cap).powi(2);

    // Reward tight fits: small post_residual relative to item size (smooth term)
    let tightness = item / (pr + 1.0);
    score -= 0.8 * (tightness / (1.0 + tightness));

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * (gap / cap).powi(2) * (1.0 + progress);
        // Bonus if residual exactly accommodates next item
        let next_fit = next_item_size as f64;
        if pr >= next_fit {
            let closeness = 1.0 - ((pr - next_fit) / cap);
            score -= 0.6 * closeness * closeness;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 * (1.0 + progress);
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless residual would be very usable
    if bin_residual == bin_capacity {
        // opening new bin is attractive when many open bins are fragmented
        let fragmentation = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let new_bin_bonus = 0.9 - 0.5 * (fragmentation / (1.0 + fragmentation));
        // attractive if post_residual is small (item nearly fills a fresh bin)
        score = score * 0.5 + new_bin_bonus + (pr / cap) * 0.3;
    }

    // Mild penalty for accumulating many open bins with high mean residual
    score += 0.1 * (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by small
    // integers are more reusable (items often come in similar sizes).
    let pr = post_residual;
    if pr > 0 {
        let mut harmony: f64 = 0.0;
        for m in [2u32, 4, 5, 10, 20, 25, 50] {
            if pr % m == 0 {
                harmony += 6.0 / m as f64;
            }
        }
        score -= harmony;
    } else {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Dead-space penalty: residual that cannot fit the next item is waste
    // unless it is (near) zero.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward residuals that can host the lookahead item, more so
            // when the fit is tight (small slack).
            let slack = pr - next_item_size;
            score -= 12.0 + 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // Harmonic bonus: post residual exactly matches next item class
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Penalize unusable leftovers, scaled by how dead they are.
            let dead = (next_item_size - pr) as f64;
            score += 0.15 * dead;
            if pr < 10 {
                score += 8.0; // tiny scraps are almost always dead space
            }
        }
    }

    // Integer-division thresholds on post_residual: prefer residuals in
    // "useful bands" (>= half capacity is very flexible).
    let band = pr / 25; // 0..4
    score -= 3.0 * band as f64;

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 25.0 * (1.0 - pressure);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if open_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild preference for bins tighter than the current mean residual
    // (best-fit flavor with mean anchoring).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Small penalty per open bin encourages consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-possibly-usable gaps: moderate penalty scaled by gap size.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect fit of the whole residual.
    if post_residual == 0 && bin_residual == item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the remaining gap -> dead space likely.
        score += (post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist, but keep last-chance bins attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is already well-used; prefer finishing it off.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if all open bins would leave large dead space, new bin wins.
        if post_residual == bin_capacity as u32 - item_size && item_size > 60 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial credit: next item still fits after this placement
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to dead space created
        score += 8.0;
    }

    // Relative-to-mean-residual coupling: bins tighter than average are more valuable
    let tightness = mean_residual - bin_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins exist with good residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress + 0.1 * open_bins_count as f64;
        // But allow new bin if current item leaves a huge unusable gap elsewhere
        if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
            score -= 25.0;
        }
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space reward (non-linear)
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 120.0;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: penalize if next item could use this residual better
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            // next item won't fit here: mild penalty proportional to waste
            score += 15.0;
        } else if (next_item_size as u32) <= post_residual {
            // next item fits after this one: reward tight chain
            score -= 0.5 * nx;
        }
        // exact pairing: item + next fill bin completely
        if item_size as f64 + nx == bin_residual as f64 {
            score -= 400.0;
        }
    }

    // Time horizon: early in stream, be pickier about dead space; late, consolidate
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * t;

    // Global state: many open bins -> discourage opening new bins / spread
    if bin_residual == bin_capacity {
        // new-bin candidate
        let pressure = open_bins_count as f64;
        score += 60.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open new bin
        }
        if next_item_size as u32 >= bin_capacity {
            score -= 100.0;
        }
    } else {
        // existing bin: prefer bins below mean residual (consolidation)
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for tighter bins overall
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Reward bins whose residual is nearly consumed (dead-space avoidance).
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let gap = pr - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here; penalize
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Slight penalty when this bin's residual is far below mean (fragmentation).
    score += 0.5 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: neutral-ish baseline so it wins only over bad fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (small dead space or perfectly reusable chunks).
    let pr = post_residual;
    let class = pr / 10; // integer division class bucket (0..10)
    let within = (pr % 10) as f64;

    // Reward small post_residual strongly (tight fits).
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if class >= 3 && class <= 5 {
        // mid-range residual: mildly penalize, modulated by within-class position
        score += 5.0 + within * 0.3;
    } else if class >= 8 {
        // large residual: bin still very reusable -> reward
        score -= 8.0 - within * 0.2;
    }

    // Coupling with next item: reward if next item fits exactly-ish in post_residual.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 35.0; // perfect chain
        } else if nd > 0 && nd <= 10 {
            score -= 18.0;
        } else if nd < 0 && (-nd) <= 5 {
            score += 6.0; // next item just barely doesn't fit -> dead end risk
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // allow new bin early in stream or when open bins are nearly full on average
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 {
            score -= 25.0; // open bins are crowded; new bin is good
        }
        if progress < 0.1 {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is close to item (best-fit flavor) via harmonic term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fit_ratio * fit_ratio) * 10.0;

    // Slight pressure against proliferating bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 4.0; // tiny gaps are wasted capacity
        } else if dead < item_size as f64 {
            // gap smaller than typical items: likely unusable
            score += dead * 0.8;
        }
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward filling bins tightly when residual shrinks toward zero.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Open-bin pressure: when many bins are open, prefer using existing ones
    // over opening new bins (new-bin candidate has full residual).
    if open_bins_count > 0 {
        let pressure = open_bins_count as f64;
        score -= pressure.min(8.0) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks next item
    }

    // New-bin candidate: penalize opening a bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for future large items
        }
    }

    // Mean residual coupling: if this bin is tighter than average, prefer it.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += (rel - 1.0) * 3.0;
    }

    // Stream progression: late in stream, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: strongly reward when the next item exactly fills this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mild reward proportional to how well it would fit.
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack_after_next * 0.3;
    } else {
        // Next item cannot follow here: penalize creating dead space that won't be used.
        let dead = if next_item_size > 0 {
            post_residual as f64
        } else {
            0.0
        };
        score += dead * 0.5;
    }

    // Relative to mean residual: bins already tighter than average are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bin would leave a very awkward
    // remainder (small unusable post_residual) or when the item fits nothing well.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        if awkward || (next_item_size > 0 && next_item_size > post_residual && post_residual < 10) {
            score -= 200.0;
        } else {
            score += 250.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference to fill bins more completely as the stream progresses.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 20.0 * (step_index as f64 / total_items.max(1) as f64 + 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize bins that are much emptier than average (avoid scattering).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.25 * residual_gap;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_capacity - post_residual {
        // Dead space that the next item cannot use at all.
        score += 10.0;
    }

    // Late in the stream: consolidate aggressively, avoid opening new bins.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    // New-bin candidate: prefer it only when item is large relative to residual
    // spread and many bins already open; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 - 12.0 * crowding + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items in a fresh bin
        }
    }

    // Mild preference for fuller bins (smaller residual) overall.
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial base: reward tight fits via post_residual, mildly non-linear
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress coupling: later in stream, penalize wasted residual more strongly
    let p3 = progress * progress * progress;
    score += 60.0 * p3 * norm_pr * norm_pr;

    // Next-item lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 25.0 * fit_quality * (1.0 - progress);
        } else {
            // next item won't fit: penalize dead space, more so late in stream
            score += 12.0 * (ns / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Mean residual dispersion: prefer bins deviating below mean (consolidate small residuals)
    score += 0.5 * (mean_residual - pr);

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
    }

    // Slight preference for bins with larger residual when many bins open
    score -= 0.05 * (open_bins_count as f64).ln() * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) strongly favored,
    // small dead-space classes penalized via modular arithmetic.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: exact fill -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        // Tiny dead space: nearly perfect, mildly rewarded.
        score -= 60.0 - (post_residual as f64) * 8.0;
    } else {
        // Penalize dead space by its harmonic residue class mod 10:
        // residuals that are "round" multiples (10, 20, ...) are reusable
        // by common item sizes, others are treated as waste.
        let class = post_residual % 10;
        let waste_penalty = match class {
            0 => 0.0,                      // clean multiple, reusable
            1..=3 => 8.0 + class as f64,   // awkward sliver
            _ => 2.0,                      // moderate
        };
        score += waste_penalty;

        // Non-linear dead-space growth: quadratic penalty scaled to capacity fraction.
        let frac = pr / cap;
        score += 40.0 * frac * frac;

        // Harmonic divisibility: if post_residual is divisible by common
        // size classes (25, 20, 10), it is more likely reusable.
        if post_residual % 25 == 0 {
            score -= 25.0;
        } else if post_residual % 20 == 0 {
            score -= 15.0;
        } else if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Integer-division threshold on next item fit: reward if the next item
    // exactly or nearly fits the post residual (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: if this bin would be the only option,
            // penalize leaving a stranded large residual.
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, opening bins is cheaper to build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 45.0 * progress;

        // If many open bins exist and mean residual is large, opening new bins
        // is wasteful.
        score += open_bins_count as f64 * 1.5 + mean_residual * 0.15;

        // Very large items deserve a fresh bin if they'd leave bad residues elsewhere.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild global normalization by mean residual state: prefer bins below mean
    // residual (filling emptier bins keeps a spread of usable gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Favor tight fits relative to item size
    score -= 0.35 * item_size as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_pressure;
    } else {
        score -= 2.0 * open_pressure;
    }

    // Lookahead: if the next item fits into the post residual, reward it
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead space for the known next item
    }

    // Early stream: be slightly more willing to spread items
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Prefer bins with below-mean residual (tighter bins first)
    score += 0.10 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: reward proportional to tightness of chain.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * chain_tightness;
        } else if post_residual >= next_item_size / 2 {
            // Partial lookahead credit: next item may split across bins.
            score -= 8.0;
        } else {
            // Dead space relative to the lookahead item: penalize small slivers.
            let sliver = post_residual as f64 / next_item_size as f64;
            score += 25.0 * (1.0 - sliver);
        }
    } else {
        // Last item: strongly prefer zero waste.
        score -= 200.0;
    }

    // Penalize residuals that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to typical residuals or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        // Base cost of a new bin; reduced when item is large or few fitting bins exist.
        score += 120.0 - 80.0 * pressure - 15.0 * (fitting_bins_count.min(5) as f64);
        // Early in the stream, new bins are cheaper (bins can be reused later).
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (denser bins), keeping
    // high-residual bins available for future items.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 20.0 * dev;

    // Mild preference for bins that are already fairly full (small residual).
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Tie-breaker: prefer fewer open bins being consumed early.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base), amplify.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no realistic item can fill.
    // Items are 1..=100; post_residual below next_item_size is unusable for lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead bonus: this bin can also host the next item.
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * chain_fit;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / item_size.max(1) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has moderate default attractiveness.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; becomes cheaper late in the stream
        // when many bins are already open anyway.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 10.0 * progress;
        // If no open bin fits well (this call is the new-bin candidate and other
        // fitting bins exist), keep it competitive but not dominant.
        if fitting_bins_count == 0 {
            new_bin_score -= 15.0;
        }
        // With many open bins and high mean residual, prefer consolidation.
        new_bin_score += (open_bins_count as f64).sqrt() * 2.0 + (mean_residual / bin_capacity as f64) * 10.0;
        score = score.max(new_bin_score.min(score)) ;
        score = score + (new_bin_score - score) * 0.0; // no-op guard
        score = new_bin_score;
    } else {
        // Slight penalty for wasting space in bins that are already fragmented
        // relative to the average residual.
        if (bin_residual as f64) > mean_residual * 1.5 {
            score += 2.0;
        }
        // Prefer filling bins with small residuals first (reduce bin count pressure).
        score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling: post_residual shaped by progress.
    let x = post / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth polynomial: early stream favors tight fits (low post residual),
    // late stream tolerates moderate residuals but punishes extremes.
    let poly = x * x * (3.0 - 2.0 * p) - x * (1.0 - p) * 0.5 + (1.0 - x) * p * 0.3;
    score += poly * 8.0;

    // Dead-space penalty: residuals too small to ever be useful.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + p);
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 6.0 * fit_quality * (1.0 - p * 0.5);
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.1 + p * 2.0;
    }

    // Mild pressure toward consolidating into existing bins.
    score -= (mean_residual - post).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are highly divisible -> easier to fill later.
        let mut divisibility = 0u32;
        for d in [2u32, 3, 4, 5, 10] {
            if pr % d == 0 {
                divisibility += 1;
            }
        }
        score -= 2.0 * divisibility as f64;

        // Penalize residuals in "dead zone": too small for typical small items.
        if pr < 10 {
            score += 8.0;
        } else if pr < 20 {
            score += 3.0;
        }

        // Harmonic bucket by capacity fraction (integer division thresholds).
        let bucket = pr / 25; // 0..3
        score += match bucket {
            0 => 6.0,           // 0-24: near-full bin, good
            1 => 2.0,           // 25-49
            2 => 4.0,           // 50-74
            _ => 8.0,           // 75-99: awkwardly large residual
        };
    } else {
        score -= 15.0; // perfect fit is best
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 3.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    // or residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - cap * 0.5).max(0.0);
        score = cap as f64 * 0.5 + avg_waste * 0.3 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slightly favor new bin if next item is huge
            score -= next_item_size as f64 * 0.05;
        }
    }

    // Mild progression term: later in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 + (mean_residual / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: residuals that are too small
    // to hold any plausible future item (typical minimum item size ~ 10,
    // but with unknown distribution treat < 12 as near-dead).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on post_residual in the "awkward gap" zone:
    // residuals that are too big to waste but too small for medium items.
    if post_residual > 0 && post_residual < 30 {
        score += 8.0 * (30.0 - post_residual as f64) / 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if post_residual cannot hold the next item but is close (dead space).
    if next_item_size > post_residual && (post_residual as f64) > 0.0 {
        score += 6.0;
    }

    // Open bins pressure: discourage spreading across many open bins
    // unless this placement is very tight.
    score += 2.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave terrible dead space or bins are few.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if all open bins would leave dead space, allow new bin.
        let dead_here = (bin_residual - item_size) < 12;
        if dead_here {
            score -= 55.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // when many bins are open.
    if open_bins_count > 3 {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Slight stream-progression tilt: later in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain match: strong reward, decaying with slack.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward for near-perfect second-step fill.
        if slack <= 2.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted potential.
        let waste = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.5 * waste;
    }

    // Penalize residuals below the minimum item size (dead space).
    if post_residual < 10 {
        score += 25.0;
    }

    // Favor bins with residuals close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Relative to mean residual: prefer filling bins that are more depleted than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * mean_residual;
        // Late in the stream, discourage new bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // bonus when next item fits into leftover space
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    } else {
        // last item: prefer fullest packing
        score -= 8.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fits exist among open bins
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress);
        // but if item barely fits anywhere (large item), new bin is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 9.0;
        }
        // if mean residual is small, open bins are nearly full -> new bin OK
        if mean_residual < item_size as f64 * 1.1 {
            score -= 12.0;
        }
    }

    // Prefer bins with residual close below the item (best-fit flavor)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 5.0 * tightness;

    // Slight preference to balance residual mass across many open bins
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in stream, encourage compact packing (favor filling);
    // late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress) * (1.0 - fit_ratio);

    // Discourage proliferation of open bins when item fits several
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 3.0 * coupling;

    // Penalize tight fits that leave dead space below next item's needs
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / bin_capacity as f64;
        score += 2.0 * gap * gap;
        // Reward when post-residual can host the lookahead item
        if pr >= next_item_size as f64 {
            score -= 1.5 * (pr - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: mildly penalize early, mildly reward late
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.0 * progress;
    }

    // Prefer bins with below-mean residual (concentrating fill)
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 1.0 * (pr_norm - mean_norm);

    // Small reward for larger items placed early (compact streams)
    score -= 0.01 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item classes (10, 20, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals lying on "harmonic" grid points.
    let mut harmonic_bonus = 0.0;
    if post_residual % 50 == 0 { harmonic_bonus += 18.0; }
    else if post_residual % 25 == 0 { harmonic_bonus += 12.0; }
    else if post_residual % 10 == 0 { harmonic_bonus += 8.0; }
    else if post_residual % 5 == 0 { harmonic_bonus += 4.0; }
    score -= harmonic_bonus;

    // Penalize tiny dead space (unusable for typical items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            // next item would leave dead space here
            score += 12.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward scaled by leftover harmonic quality
            let left = post_residual - next_item_size;
            if left % 10 == 0 { score -= 10.0; }
        }
        // If next item is large, prefer keeping large residuals free
        if next_item_size > post_residual && post_residual >= 40 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current
    // residual fit would create large dead space and many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with full residual; make it moderately attractive
        // unless we would waste an almost-empty existing bin.
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count >= 1 {
            // An existing bin fits: penalize opening a new one, unless the
            // best existing fit would be terrible (handled via mean_residual).
            score += 15.0;
            if mean_residual < item_size as f64 * 0.5 {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // big next item benefits from a fresh bin
        }
    }

    // Prefer filling bins that are already mostly full (tight packing).
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= fill_ratio * 10.0;

    // Slight time-decay: early on, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit in the gap: penalize if gap is small.
            if post_residual < next_item_size && post_residual < 25 {
                score += 10.0;
            }
        }
    }

    // Slight preference toward fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: add baseline penalty so it's chosen only when
    // all open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    // Mean residual coupling: if open bins are on average loose, prefer
    // packing into existing bins rather than opening new ones.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild reward scaled by leftover after next
            let after_next = post_residual - next_item_size;
            score -= 50.0 + (after_next as f64) * 0.5;
        } else {
            // next item cannot use the remaining space: penalize dead space
            score += 80.0 + (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare residual to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.6;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 250.0;
        // but if no existing bin gives a good fit, allow opening (handled by comparison)
        if fitting_bins_count == 0 {
            score -= 600.0;
        }
        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 >= 0.0 {
            // a fresh bin can hold the next item well
            score -= 50.0;
        }
    }

    // Late in the stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Penalize creating tiny unusable slivers (items are >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that no future item can plausibly use.
    let min_item = 1.0f64;
    if post_residual as f64 > 0.0 {
        let waste = if (post_residual as f64) < min_item { 0.0 } else { post_residual as f64 };
        score += 0.05 * waste * waste / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins
    // tightly); late in the stream, tolerate spreading since stream end is near.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Many open bins with high mean residual: penalize adding to fragmentation,
    // encourage packing into bins below mean residual (denser bins).
    let residual_dev = mean_residual - bin_residual as f64;
    score += 0.15 * residual_dev;

    // Slight penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Tie-breaker: prefer bins with less residual overall (denser bins).
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (item_size as f64 / cap) * fill * (1.0 + 30.0 * progress);

    // Penalize near-mean residuals (dead space clustering)
    let dev = pr_norm - mean_residual / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead: favor residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0 * pr_norm;

    // New-bin candidate: prefer opening a fresh bin early or for large items
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress) + 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (C/5 classes)
    let item_class = (item_size * 5 + bin_capacity / 2) / bin_capacity; // 0..=5
    let post_class = (post_residual * 5 + bin_capacity / 2) / bin_capacity;

    // Reward tight fits: post_residual near zero is good
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Penalize dead space in harmonic "unusable" zones: post_residual in (0, 10]
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Harmonic pairing: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: penalize proportionally
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin bonus: only fitting bin => strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-to-slightly-high base, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // open new bin if all fits leave bad harmonic dead space
        if post_residual > 0 && post_residual <= 15 {
            score += 20.0;
        }
    }

    // Prefer bins with residual close to item (best-fit coupling)
    score += 0.3 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64).abs() * 10.0;

    // Class match reward: bin residual class equals item class complement
    let residual_class = (bin_residual * 5 + bin_capacity / 2) / bin_capacity;
    if residual_class == item_class + 1 {
        score -= 12.0;
    }

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Discourage spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (fill the fullest first)
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are already handled; residuals below a "usefulness band" are dead space.
    let dead_threshold = 12.0f64.min(mean_residual.max(1.0));
    if (post_residual as f64) < dead_threshold {
        // Unusable gap: heavy penalty proportional to wasted capacity.
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small but still usable residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; adjust with current pressure.
        score += 55.0 + open_bins_count as f64 * 0.3;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this residual anyway; slightly soften dead-space penalty.
        score -= (post_residual as f64) * 0.1;
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual closely matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (next item exactly fills residual) is heavily rewarded.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= (bin_capacity as f64 - gap) * 0.15; // tighter gap => bigger reward
        }
        // Penalize post_residuals that are too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling a bin as tightly as possible.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: bins with residual far above mean waste space.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Progress-aware tightness bonus: early in stream, keep bins flexible;
    // late in stream, prioritize tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * 0.25 * progress;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving large unusable fragments (dead space threshold).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny leftover is fine, bin nearly full
    } else if post_residual >= 10 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0; // small unusable gap
    }

    // New-bin candidate: baseline so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no other bin fits well (many bins but few fitting), allow new bin more readily.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive only when no open bin
    // fits well or the stream is early and we expect many future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Penalize opening new bins when a decent fit exists elsewhere.
        if fit_ratio > 0.5 {
            score += 60.0;
        }
        // Early stream: new bins are cheap insurance against fragmentation later.
        score -= 20.0 * (1.0 - progress);
        // Too many open bins already: discourage spreading.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Using an existing bin keeps open_bins_count down; reward consolidation.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving a large awkward gap.
            score += 0.1 * post_residual as f64;
        }
    }

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (drain the emptiest-first tendency) to reduce fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // Mild time-horizon shaping: late in the stream, prioritize exact packing.
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let base = norm_post * norm_post * (1.0 + 2.0 * progress) + 0.6 * norm_post;

    let mut score = base * 100.0;

    // New-bin candidate: penalize opening a new bin, more so late in stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 55.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Tight fit reward: smooth exponential of normalized fill.
        let fill = 1.0 - norm_post;
        score -= 18.0 * fill * fill * fill;

        // Reward when this bin is the only fitting option (last chance).
        if fitting_bins_count == 1 {
            score -= 30.0;
        } else {
            score += 4.0 * (fitting_bins_count as f64 - 1.0);
        }

        // Lookahead: penalize leaving a residual that barely fails next item.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let gap = (post - nxt) / cap;
            if gap >= 0.0 {
                score -= 12.0 * (1.0 - gap) * (1.0 - gap);
            } else {
                score += 8.0 * (-gap) * (-gap);
            }
        }

        // Coupling with mean residual: prefer bins deviating from mean toward tightness.
        let dev = (mean_residual - post) / cap;
        score += 10.0 * dev * dev - 6.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod capacity fractions
    let frac_quarter = post_residual % (bin_capacity / 4).max(1);
    let frac_eighth = post_residual % (bin_capacity / 8).max(1);
    let frac_tenth = post_residual % (bin_capacity / 10).max(1);

    // Reward residuals that sit exactly on harmonic class boundaries (highly reusable)
    if frac_quarter == 0 { score -= 6.0; }
    if frac_eighth == 0 { score -= 3.0; }
    if frac_tenth == 0 { score -= 2.0; }

    // Penalize dead space in the smallest harmonic band (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits too: strong reward, scaled by harmonic class of next size
            let next_class = next_item_size % 10;
            score -= 12.0 + (next_class as f64) * 0.3;
        } else {
            // Next item won't fit here: penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.15;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: this is the only fitting bin; strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins whose residual deviates from the mean (consolidate waste)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: encourage opening bins to build diversity of residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when open bins fit poorly
        let new_bin_bonus = 18.0 * (1.0 - progress) + (fitting_bins_count as f64) * 2.0;
        score += new_bin_bonus;
    } else {
        score += 4.0;
    }

    // Mild penalty for very tight fits that leave nothing (waste avoidance already handled)
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size) are worthless.
    if post_residual < 10 {
        score += 50.0; // heavily penalize creating a dead gap
    } else if post_residual <= 20 {
        // Moderately small gaps are hard to fill; penalize proportionally.
        score += 0.6 * (20 - post_residual) as f64;
    } else {
        // Reward tight fits: score decreases as post_residual shrinks (baseline already does this),
        // extra reward for very snug placements.
        if post_residual <= 30 {
            score -= 4.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one
    // and encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in the stream,
        // unless the current fit is terrible (large dead space would be created).
        score += 8.0 + pressure;
        if post_residual > 40 || item_size > bin_residual {
            score -= 6.0; // new bin is fine when fit is bad anyway
        }
    } else {
        // Existing bins get a mild baseline advantage, scaled by pressure.
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced),
    // penalize bins that are outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual >= 10 {
            // Post-residual too small for the next item but still usable: mild penalty.
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial reward: next item fits snugly with small slack (<= 10).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0 - slack as f64 * 1.5;
        } else {
            score -= 8.0;
        }
    }

    // Penalize dead space: residual too small for any item (min size 1, practically ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Penalize wasting a large residual on a small item.
    if post_residual as f64 > mean_residual + 30.0 {
        score += 12.0;
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0; // still allow fresh bin if it sets up perfect match
        }
    }

    // Late-stream consolidation: prefer tighter fills as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Wasted capacity relative to the upcoming item.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarcity pressure: when few bins can fit the item, prefer bins that keep capacity usable.
    if fitting_bins_count <= 2 {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state: prefer filling bins when many are open (reduce open-bin count pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (fill the emptier-trending side).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, be greedier about tight fits.
    score -= 10.0 * progress * tightness;

    // New-bin candidate: make it attractive only when no good fit exists (high post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    // non-linear coupling: post_residual penalized more as stream progresses
    score += progress * (norm_pr * norm_pr) * 40.0;
    // reward tight fits (small post_residual) with smooth decay
    score -= (1.0 - norm_pr).powi(3) * 15.0;
    // dead-space penalty if residual can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nxt) / cap).powi(2);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }
    // discourage spreading when many open bins have high mean residual
    score += 0.3 * (mean_residual - pr).abs() / cap;
    // keep new bins from winning too easily early; allow later
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a multiple of 10
    // (or exactly 0) are "clean" states — reward them.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0 {
        score -= 18.0; // divisible leftover, easy to fill later
    } else if class <= 3 {
        score += 22.0; // tiny dead space
    }

    // Integer-division threshold: post_residual bucketed into eighths of capacity.
    let eighth = (pr * 8) / bin_capacity;
    score -= eighth as f64 * 2.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (harmonic pair).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let pair_class = (pr - next_item_size) % 10;
            if pair_class == 0 {
                score -= 14.0;
            }
            score += (pr - next_item_size) as f64 * 0.35;
        } else {
            score += 12.0; // next item cannot follow here
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin on a small item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.35 && bin_residual < bin_capacity {
        score += (0.35 - fill_ratio) * 80.0;
    }

    // New-bin candidate: keep it competitive only when open bins are congested
    // or mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score -= 25.0 + 30.0 * progress + congestion * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild global pressure: prefer denser bins when many bins are open.
    score += mean_residual * 0.05 - open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are pure waste — penalize them hard.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Reward tight fits nonlinearly (small post_residual favored).
        score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 4.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (slack + 1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; a new empty bin should only win on excellent fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to open-bin pressure and
        // mean residual spread, but soften when it's a lone-bin situation.
        score += pressure * 6.0 + (mean_residual / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // A fresh bin is attractive only if the item leaves a large,
        // reusable residual relative to typical open-bin residuals.
        if post_residual as f64 >= mean_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward choosing bins below mean residual
        // (consolidating the emptiest usable space).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Mild late-stream tightening: as the stream progresses, waste matters
    // more since there's less time to fill gaps.
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
