pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could still fit here -> good chaining.
            let slack = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.35;
            if slack == 0 {
                score -= 15.0; // perfect chain
            }
        } else {
            score += (post_residual as f64) * 0.5; // dead space for next item
        }
    } else {
        // Last item: prefer any fit, especially tight ones.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (mean_residual.max(1.0));
    score += crowd * 2.0;

    // Mean residual coupling: large mean residual -> encourage filling bins more.
    score -= mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless existing bins are hopeless fits.
    if bin_residual == bin_capacity {
        score += 55.0 + (fitting_bins_count as f64) * 8.0;
        // If nothing else fits well, allow opening: reduce penalty when post_residual tiny.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Penalize leaving awkward residuals (small unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), with non-linear shrinkage
    let mut score = pr * (1.0 + 0.8 * progress * (pr / cap) * (pr / cap));

    // Reward near-perfect fits with a smooth quadratic bonus
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot host the lookahead item (smooth interaction)
    if nx > 0.0 {
        let waste = (nx - pr).max(0.0);
        score += 0.35 * waste * (1.0 + progress);
        // Reward bins whose post_residual exactly accommodates the next item
        let fit_next = 1.0 - ((pr - nx) / cap).abs();
        score -= 6.0 * fit_next * fit_next * fit_next;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: only attractive when current item is large relative to capacity
    if bin_residual == bin_capacity {
        score = cap - it + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover in coarse quarters of capacity.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter;
    match post_class {
        0 => score -= 40.0,           // tiny leftover: near-perfect fit, reward strongly
        1 => score -= 10.0,           // small leftover
        2 => score -= 0.0,
        3 => score += 15.0,           // large leftover: wasteful placement
        _ => score += 25.0,
    }

    // Modulo arithmetic on post_residual: leftovers divisible by small integers
    // are more likely reusable by future items.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }
    if post_residual % 3 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a harmonic pair — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post < quarter {
                score -= 25.0; // chain of two good fits
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on item_size: big items should prefer tight bins.
    if item_size > bin_capacity / 2 {
        score += (post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly discourage
    // opening a new bin instead (penalize the alternative implicitly by rewarding here).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening fresh bins is only attractive early in the stream
    // or when mean residual across open bins is very low (all bins nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score = 45.0
            + 25.0 * progress          // late in stream, prefer reusing open bins
            - 30.0 * mean_fill          // if open bins are nearly full, new bin is fine
            - 2.0 * open_bins_count as f64;
    }

    // Small global tie-breaker toward bins with residual close to mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize large leftover only if it cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Slight preference for bins already tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-high unless current bin is terrible.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // 2-step lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 3.0;
        }
    }
    // relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // penalize new-bin opening unless residual would be very small
    if bin_residual == bin_capacity {
        score += 12.0;
        if (item_size as f64 / bin_capacity as f64) > 0.9 {
            score -= 15.0;
        }
    }
    // dead-space penalty for tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is wasted; penalize very small scraps.
    if post_residual > 0 {
        let scrap_penalty = if post_residual < 10 { 25.0 } else { 0.0 };
        score += scrap_penalty;
    } else {
        // Perfect fit is excellent.
        score -= 40.0;
    }

    // Reward filling a bin to a high fraction of capacity.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            // Next item won't fit in the leftover; mild penalty for bad chaining.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 45.0;
        // More open bins with high mean residual -> existing bins are fragmented,
        // opening a fresh bin becomes more attractive.
        score -= 0.5 * open_bins_count as f64;
        score -= 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - t);
        // If the item is large relative to capacity, a fresh bin is safer.
        score += 0.2 * item_size as f64;
    }

    // Slight preference for bins with residual close to item (best-fit flavor)
    // already captured by fill_frac; add mild tie-break on residual size.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 1.5 * t * t * (3.0 - 2.0 * t); // smoothstep-ish
    score += progress_weight * norm_pr * norm_pr * cap * 0.3;

    // Penalize dead space relative to mean residual, smoothly
    let mr = mean_residual.max(0.0);
    score += 0.25 * (pr - mr).abs() * (0.5 + t);

    // Reward tight fits: subtract for small post_residual
    score -= 20.0 * (1.0 - norm_pr).powi(4);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: penalize if next item can't fit in post_residual (smoothly)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap * (1.0 + t);
        } else {
            score -= 6.0 * (1.0 - (pr - ns) / cap) * (1.0 - t);
        }
    }

    // New-bin candidate: keep neutral-ish, penalize slightly more late in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * t + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual close to 0 is ideal
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: small dead space classes (< 10) are unusable waste
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable
    let r = post_residual;
    if r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 8.0;
    }

    // Lookahead: penalize if next item cannot fit in post_residual
    if next_item_size > 0 {
        if next_item_size > r {
            score += 10.0;
        } else if next_item_size == r {
            score -= 35.0;
        } else {
            score -= 6.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // but if it's early or many bins open, allow it more readily
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins with below-average residual (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Discourage leaving residuals just above small item sizes
    if r >= 10 && r < 20 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill is highly rewarded
    } else if post_residual <= 20 {
        // Gaps of 10..20 are only usable by small items; mild penalty for likely dead space
        score += 12.0;
    } else {
        // Larger residuals are usable; slight reward proportional to remaining flexibility
        score -= (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward leaving a gap that fits the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // gap can't host next item
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.15;
    }

    // Mean-residual deviation: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fractional waste relative to capacity: penalize large dead space nonlinearly.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 200.0;

        // Aggressive 2-step lookahead: if the next item fits exactly into the
        // post-residual, strongly favor this bin.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                // Next item fits: reward, scaled by how well it matches.
                let leftover_after_next = post_residual - next_item_size;
                score -= 150.0 - (leftover_after_next as f64) * 1.5;
            } else {
                // Next item won't fit here: penalize small residuals that
                // become dead space, scaled by how badly it misses.
                let miss = (next_item_size - post_residual) as f64;
                score += miss * 2.0;
            }
        }

        // Compare post_residual against mean residual across open bins:
        // leaving a residual close to the mean keeps future flexibility.
        let diff_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_mean * 0.5;

        // Last-chance bin: if this is the only bin that fits, avoid opening
        // a new bin unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // New-bin candidate: penalize opening a new bin, more so early in the
        // stream and when many bins are already open but underused.
        if bin_residual == bin_capacity {
            score += 120.0 + 0.5 * open_bins_count as f64
                   + 100.0 * (step_index as f64 / (total_items.max(1) as f64));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (1..100 unknown, assume >=10-ish)
    // but with unknown distribution, penalize only very small unusable space.
    if post_residual > 0 && post_residual <= 5 {
        score += 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 + 35.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin only if we place item here with slack; mild penalty.
        score += 8.0;
    }

    // Last-chance bin: only one open bin fits -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized, more so when many bins are already open
        // and other bins fit the item.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If next item is large, a fresh bin may be valuable anyway.
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins, especially those below mean residual (fill emptier bins).
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer balanced bin usage: penalize placing into already-tight bins when alternatives exist.
    if fitting_bins_count > 2 && post_residual < item_size / 2 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized quantities
    let pr = post_residual as f64 / c;                 // post residual normalized [0,1]
    let ir = item_size as f64 / c;                     // item fill fraction
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r = mean_residual / c;                    // mean residual normalized
    let nxt = if next_item_size > 0 { next_item_size as f64 / c } else { 0.0 };

    // Strongly reward tight fits: non-linear penalty on squared dead space
    score += 40.0 * pr * pr;

    // Reward bins whose post-residual could accommodate the lookahead item
    // (smooth coupling instead of hard threshold)
    let lookahead_fit = (nxt - pr).max(0.0);
    score += 25.0 * lookahead_fit * lookahead_fit;
    // Bonus when post-residual exactly leaves room for next item
    let slack_match = 1.0 - (nxt - pr).abs();
    if next_item_size > 0 {
        score -= 8.0 * slack_match.max(0.0) * (1.0 - pr);
    }

    // Last-resort bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr);
    }

    // As stream progresses, prefer filling existing bins more aggressively
    score -= 15.0 * prog * ir * (1.0 - pr);

    // Penalize bins far from mean residual (favor homogeneity of open space)
    let dev = (mean_r - pr).abs();
    score += 10.0 * dev * dev;

    // Many open bins: discourage keeping residual small and unusable
    let ob_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 12.0 * ob_norm * pr * (1.0 - pr);

    // New-bin candidate: penalize opening a fresh bin when item fits elsewhere,
    // unless current bins are very fragmented
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - prog) - 10.0 * ob_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residues near 0 are "usable slots"
    let pr = post_residual as i64;
    let harmonic = pr % 10;
    let harmonic_bonus: f64 = match harmonic {
        0 => -30.0,                 // perfect fill
        1..=3 => -18.0,             // near-perfect, likely dead space anyway
        4..=6 => 4.0,               // awkward gap
        7..=9 => 10.0,              // large-ish gap but reusable
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Integer-division tiers: how many "typical" small items (<=20) still fit
    let small_slots = pr / 20;
    score -= (small_slots as f64) * 6.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5;
        // exact fit with lookahead
        if slack == 0.0 { score -= 20.0; }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportional to leftover
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins fit poorly
        // and post_residual (full capacity) is genuinely needed for big items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.5 + mean_residual * 0.05;
        // Penalize opening a new bin by default...
        score += 55.0 + pressure;
        // ...unless the item is large and existing space is fragmented
        if item_size > 60 && mean_residual < (item_size as f64) * 0.8 {
            score -= 45.0 * (0.5 + progress);
        }
        // never open a bin for tiny items
        if item_size <= 25 { score += 60.0; }
    }

    // Mild tie-break: prefer bins whose residual deviates least from mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Fractional capacity coupling: reward placements leaving residual in
    // "harmonic fractions" of capacity (1/4, 1/3, 1/2)
    let frac = (post_residual as f64) / (bin_capacity as f64);
    for target in [0.0f64, 0.25, 0.3333, 0.5] {
        let d = (frac - target).abs();
        if d < 0.03 { score -= 12.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Penalize bins whose residual is far above the item (loose fit).
    if bin_residual > item_size + 40 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage new bin
    // only when fit is poor; otherwise mild penalty on opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If lookahead item can use the new bin's full space, slight discount.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Mild reward for consolidating into existing bins when few are open.
        score -= (10.0 - open_bins_count.min(10) as f64) * 1.5;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for lookahead: mild penalty unless near zero.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: later in stream, be slightly more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight coupling: the closer post_residual is to next_item_size, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Exact chain fit (post_residual == next_item_size) is a perfect two-step match.
            if post_residual == next_item_size {
                score -= 300.0;
            }
        } else {
            // Penalize creating dead space that cannot fit the next item.
            score += 40.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score -= 200.0;
    }

    // Prefer bins that are already partially filled (large item usage => small residual relative to mean).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap.max(0.0);
    score -= 0.3 * (-residual_gap).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing reasonable fits.
    if bin_residual == bin_capacity {
        score += 500.0;
        // But if next item chains perfectly into a fresh bin, soften the penalty.
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 350.0;
        }
        // Late in the stream, opening fresh bins is less harmful.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 100.0 * progress;
        }
    }

    // Mild preference for many open bins being consolidated (avoid bin sprawl).
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Lookahead: reward bins that can also host the next item (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 + 6.0 * chain_quality;
    }

    // Penalize small unusable dead space (fragments that likely never get filled).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin, especially early in the stream
    // or when other bins already fit the item.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // A big next item justifies a fresh bin a bit more (it may need full capacity soon).
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Slightly favor bins below mean residual (consolidating emptier bins).
    score += 0.02 * (mean_residual - bin_residual as f64).max(0.0);

    // Crowding: mildly discourage stacking into many already-open bins late in stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits via non-linear polynomial in normalized post-residual.
    let mut score = rn * rn * (3.0 - 2.0 * rn) * cap * 0.5 + r;

    // Smooth coupling of post-residual with stream progress: late in the stream,
    // waste is more costly, so tighten further.
    score += rn * rn * progress * 20.0;

    // Penalize post-residual that is too small to hold any plausible future item,
    // but keep it smooth via a sigmoid-like term on next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - r).max(0.0);
        let fit_smooth = 1.0 / (1.0 + (-(r - nxt) / 10.0).exp());
        score += waste * 0.3 * (1.0 - fit_smooth);
        // Reward leaving exactly the room the next item needs (perfect chaining).
        let chain = 1.0 - ((r - nxt).abs() / cap);
        score -= chain * 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - rn);
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score -= pressure * 10.0 * (1.0 - rn);

    // Mean residual alignment: bins deviating from the mean residual get a mild penalty.
    score += ((mean_residual - r).abs() / cap) * 5.0;

    // New-bin candidate: make it moderately unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * (1.0 - progress) - pressure * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals that are hard to fill later (classic bad zones).
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Harmonic class penalty on post_residual: residuals in awkward modular classes
    // relative to small item sizes are less likely to be filled.
    let pr = post_residual;
    if pr > 0 && pr % 10 != 0 {
        score += (10 - (pr % 10)) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
            // harmonic pair: next item leaves a clean multiple-of-10 residual
            if (pr - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            score += ((next_item_size - pr) as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well. Penalize new bins more when many bins are open and
    // mean residual is large (existing space should be used first).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score += 55.0 + 0.6 * (open_bins_count as f64).min(50.0) + 0.3 * mean_r;
        // If the item is large relative to capacity, a fresh bin wastes less.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Mild pressure to consolidate into bins below mean residual (balance packing).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Slight time-dependence: later in the stream, prefer tighter packing.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= t * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Large usable residuals are rewarded.
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are already open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if current bins are nearly full.
        score = 70.0;
        if mean_residual < 15.0 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Late in the stream, avoid leaving many almost-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;

        // Lookahead synergy: if the next item fits the post residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect chain: item then next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item also fits now alongside current: strong packing potential.
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 25.0;
    }

    // Relative to mean residual: bins tighter than average are better to fill.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin would be
    // left with unusable dead space and the new bin offers a better future.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
        // Late in the stream, closing out bins matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Penalize large dead space (waste) non-linearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Many open bins: prefer consolidating into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit * chain_fit;
        } else {
            score += 8.0; // next item cannot follow here
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if fit_ratio < 0.35 {
            score += 10.0; // but don't force a very loose fit
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // fits well, or late when residual fragmentation dominates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fit = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { mean_residual };
        // Prefer new bin when mean residual across open bins is small (fragmented)
        // or when the item is large relative to typical residual.
        score += 30.0 + 25.0 * (1.0 - progress);
        if avg_open_fit < item_size as f64 {
            score -= 20.0; // open bins are too fragmented; fresh bin is good
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 12.0; // fresh bin can host a nice pair
        }
    } else {
        // Mild preference for reusing bins that are already relatively full.
        let used_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * used_ratio;
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    // Divergence from mean residual: prefer bins whose residual is below average
    // (they are "nearly done"), keep high-residual bins flexible for future items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    // Strongly reward tight fits (small post_residual) via non-linear coupling
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that grows with stream progress (later waste is costlier)
    score += 10.0 * progress * (pr / cap) * (pr / cap);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item exactly fills post_residual, big bonus
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 30.0;
    }
    // If next item could fit into post_residual, mild bonus; else mild penalty
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (pr - next_item_size as f64) / cap;
        } else {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default slightly high, but attractive when residuals
    // across open bins are large and fragmented (many open bins, high mean residual)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * (open_bins_count as f64).sqrt();
        score = 0.5 * cap + 20.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild penalty for spreading across many open bins when residual is average
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions.
    // Post-residuals in "harmonic" classes (multiples of 25, 20, 10) are more
    // reusable for future items, so reward them (subtract).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 25 == 0 {
        score -= 18.0;
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 25.0; // dead space too small for any item
    } else {
        // awkward class: penalize by distance to nearest harmonic anchor
        let d25 = (pr % 25).min(25 - pr % 25) as f64;
        score += d25 * 0.4;
    }

    // Lookahead coupling: does next item fit into the resulting post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: strong reward, scaled by how snugly it fits
            let snug = (pr - next_item_size) as f64;
            score -= 22.0 - snug * 0.25;
            // harmonic bonus if next item lands exactly
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: mild penalty, worse if gap is small
            let gap = (next_item_size - pr) as f64;
            score += (gap * 0.15).min(15.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets baseline score.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; acceptable only if no good fit exists.
        score = cap - item_size as f64; // post_residual of fresh bin
        if fitting_bins_count == 0 {
            score -= 50.0; // forced open
        } else {
            // prefer existing bins unless all fits are poor (large post_residual)
            score += 8.0;
            if post_residual >= 0 && item_size <= 30 && mean_residual > 40.0 {
                score -= 10.0; // plenty of slack elsewhere anyway... keep new bin cheap
            }
        }
        // small items: keep them out of fresh bins
        if item_size <= 20 {
            score += 20.0;
        }
        // lookahead: new bin should reserve room for next item too
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild preference to fill bins with larger mean residual (consolidate slack).
    score -= mean_residual * 0.05;

    // Stream progression: late in stream, be greedier about perfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr == 0 {
        score -= 20.0 * progress;
    }

    // Tie-breaker: prefer bins with tighter current residual (less waste).
    score += (bin_residual - item_size) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap
    // is heavily penalized (dead space = residual that can't fit min item).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 8.0 * progress;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (perfect fills).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        // Fractional fill tightness reward.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
    }

    // Penalize leaving a gap that the lookahead item could not use anyway,
    // but reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Slight penalty if this bin's residual deviates far from mean residual
    // (prefer bins with typical residuals, avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    let perfect_bonus = if post_residual == 0 {
        -500.0
    } else if post_residual <= 5 {
        -150.0
    } else if post_residual <= 15 {
        -60.0
    } else {
        0.0
    };
    score += perfect_bonus;

    // 2-step lookahead: reward if next item fits into the post residual (chaining),
    // penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains perfectly or well into this bin.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += 20.0;
        }
        // Exact 2-step match is gold.
        if post_residual == next_item_size {
            score -= 300.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose post
    // residual is below average (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 250.0
            + open_bins_count as f64 * 5.0
            - (mean_residual - item_size as f64).max(0.0) * 2.0;
        score += new_bin_penalty;
        // If the item is large relative to typical residuals, opening is less bad.
        if item_size as f64 > mean_residual {
            score -= 180.0;
        }
    }

    // Mild preference to fill older bins as the stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small dead space that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: heavily reward using the only bin that fits,
    // otherwise the item forces a new bin anyway
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: usually unattractive, but attractive when no bin fits well
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && fit_ratio < 0.5 && mean_residual < item_size as f64 * 0.6);
        if poor_alternatives {
            score -= 55.0 + 20.0 * (1.0 - progress);
        } else {
            score += 70.0 + 30.0 * open_bins_count as f64;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // post-residual too small for next item: mild penalty
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    // Mild preference to keep mean residual balanced
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // Late in the stream, be more aggressive about tight packing
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear polynomial shaping.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 25.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Tight fits are strongly rewarded (smooth coupling of fill ratio and progress).
    let fill = 1.0 - norm_pr;
    score -= 60.0 * fill * fill * (0.5 + 0.5 * progress);

    // Penalize bins whose residual is unlikely to fit the next item (smooth mismatch term).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        let miss = if next_item_size as f64 > pr { (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += 30.0 * miss * miss;               // can't host next item
        score -= 15.0 * (1.0 - gap) * gap * 4.0 * (1.0 - gap); // near-exact hosting bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 - progress + 0.3);
    }

    // New empty bin candidate: penalize smoothly unless nothing else fits.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.5);
        let emptiness = 1.0 - fill;
        score += 20.0 + 35.0 * emptiness * crowding;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 30.0 * progress;
    }

    // Mild preference for bins already below mean residual (balance preservation).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are preferred.
    let class = post_residual / 10;
    let harmonic_bonus = match class {
        0 => 0.0,                       // perfectly full — ideal
        1 => 3.0,                       // 10-19 leftover: near-perfect fill
        2 => -1.5,                      // 20-29: still very usable
        3 => -2.0,
        4 => -1.0,
        5 => -2.5,                      // 50-59: half-full, fine
        6 => -1.0,
        7 => 1.0,
        8 => 2.0,
        _ => 0.5,
    };
    score -= harmonic_bonus;

    // Penalize dead space that no plausible item can fill: leftover < 10 is
    // already counted, but leftover in (0,10) exclusive of 0 wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward placements whose post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - 0.15 * slack;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover unusable for the next item: mild penalty scaled by waste
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large or the fit elsewhere is terrible. Compare against mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Opening is attractive when item is big (leaves small residual) or
        // existing bins are fragmented (low mean residual relative to item).
        let fragmentation = (mean_residual - item_size as f64) / bin_capacity as f64;
        score += 30.0 - 25.0 * fit_quality - 10.0 * fragmentation.max(0.0) + 5.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin pairs item with next item nicely
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor) via mean residual coupling.
    score += 0.02 * (mean_residual - post_residual as f64).max(0.0);

    // Tie-break: prefer bins with fewer alternatives when residuals are equal.
    if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals just above the minimum item size (1..=9 after interface) are hard to fill.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward very tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual; penalize proportionally to waste
            score += post_residual as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Penalize bins whose residual is far above the mean (fragmented bins).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 20.0;

    // Slight early-stream conservatism: prefer tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 1 {
            // opening a new bin is fine (the only fitting bin is... none other)
            score += 30.0;
        } else {
            score += 80.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Aggressive 2-step lookahead: reward chains where the next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // reward proportional to how well next item packs into the leftover
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chain_fit / cap) * (nxt / cap);
        } else {
            // next item cannot follow: penalize dead space
            score += 6.0 * (post / cap) * (nxt / cap);
        }
    }

    // Tight fit reward relative to bin capacity
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Compare post residual against mean residual of open bins:
    // leaving less than average waste is good
    score -= 0.8 * (mean_residual - post);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).max(1.0);
        let avg_fit = mean_residual / cap;
        score += 10.0 + 8.0 * avg_fit + 2.0 * pressure.ln();
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // new bin guarantees chain for next item
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / cap;
    score += 60.0 * waste_ratio * waste_ratio;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: favor bins whose residual after placement can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (bin_residual as f64 - next_item_size as f64).abs() / cap);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item_size as f64 / bin_residual as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening is attractive when item is small relative to empty bin late in stream
        // or when no bin fits well; otherwise discourage.
        score += 25.0 - 30.0 * fit_quality + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Discourage proliferation of open bins when mean residual is high.
        score += 0.5 * mean_residual.max(0.0) / cap * (open_bins_count as f64).sqrt();
    }

    // Mild preference for bins with residual close to the item (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Slight time-varying exploration term to break ties dynamically.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * ((t * std::f64::consts::PI).sin()) * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins whose residual is much larger than mean (underused bins) slightly.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of wasted space with stream progress:
    // late in the stream, dead space becomes increasingly costly.
    let waste_frac = pr / cap;
    let coupling = waste_frac * waste_frac * (0.5 + 2.0 * progress);
    score += 30.0 * coupling;

    // Reward bins whose residual matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let match_quality = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 6.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Lookahead item won't fit here: mild penalty growing with progress.
        score += 2.0 * progress;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_fit_pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).ln() + 1.0
        };
        score = cap as f64 * (1.2 + 0.6 * progress) + 10.0 * open_fit_pressure;
    } else {
        // Slight bonus for consolidating into bins tighter than the mean residual.
        let mean_diff = mean_residual - bin_residual as f64;
        score -= 0.05 * mean_diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual via quadratic term
    let pr = post_residual as f64;
    score += 0.6 * pr * pr / bin_capacity as f64;

    // Harmonic class of post_residual: small residues (<=10) are near-perfect fits
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 35 {
        score -= 3.0;
    } else {
        // large dead space penalty, super-linear
        score += (post_residual - 35) as f64 * 1.5;
    }

    // Penalize post_residual that no plausible future item can use:
    // if next item is bigger than post_residual, residue is likely dead
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else {
            // residue can host next item: reward
            score -= 8.0;
            // exact-ish reuse
            if post_residual - next_item_size <= 10 {
                score -= 8.0;
            }
        }
    }

    // Last chance bin: must use it or open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open new bin when existing bins have small mean residual (bad fits)
        score -= (100.0 - mean_residual) * 0.4;
        // when many bins already fit the item, discourage opening new
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // early stream: opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins when many bins are open
    score -= open_bins_count as f64 * 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Integer-division harmonic class of residual: prefer residues in "useful" bands
    let band = post_residual / 10;
    match band {
        0 => score -= 5.0,
        1 => score -= 2.0,
        2 => score += 0.0,
        3 => score += 3.0,
        _ => score += 6.0,
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (1..=100) could ever use it well.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit: eliminate the bin entirely
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (placing into a bin already below average residual reduces fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0; // chain perfect fit
            } else if gap < dead_threshold {
                score += 20.0; // next item would create dead space here
            } else {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are open and mean residual is still large; cheap late in the stream or
    // when existing bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 20.0 + 4.0 * open_bins_count as f64 + 0.3 * mean_residual;
        score = new_bin_cost - 10.0 * progress;
        // If the item is large, a fresh bin is naturally attractive.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: tight fit reward (small post_residual is good).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: strongly reward exact-ish match.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 0.5 * diff;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious, use them well.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: avoid wasting it on a loose fit; prefer it only for very tight fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 > 0.35 * bin_capacity as f64 {
            score += 15.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate: prefer opening a new bin only when the item is large
    // relative to typical residuals, or when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        score = 0.45 * bin_capacity as f64
            + 0.6 * (post_residual as f64 - mean_residual).max(0.0)
            - if next_item_size > 0 && post_residual >= next_item_size { 6.0 } else { 0.0 };
    }

    // Late-stream consolidation: keep many small residual bins closed out early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that can't hold typical items (small residual waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover size.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 120.0 - 60.0 * progress;
        // If mean residual across open bins is small, opening a new bin is more acceptable.
        new_bin_penalty -= mean_residual * 1.5;
        // If item is large, opening a new bin wastes less capacity.
        new_bin_penalty -= item_size as f64 * 0.5;
        // Many open bins with large mean residual => keep packing existing bins.
        if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 {
            new_bin_penalty += 50.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_gap * 30.0;

    // Mild time-dependent tie-breaker: as stream progresses, favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, prefer filling bins loosely (keep flexibility);
    // late, strongly punish leftover space.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (post / cap) * (post / cap) * cap * 0.35;

    // Reward tight fits (small post_residual) with smooth non-linear term
    let tightness = 1.0 - (post / cap);
    score -= 6.0 * tightness * tightness * tightness;

    // Dead-space penalty: post_residual that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post) / cap;
        score += 12.0 * waste * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // small reward for leaving room for the next item
        score -= 2.0 * (1.0 - ((post - next_item_size as f64).abs() / cap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize spreading across many open bins mildly
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: attractive early, unattractive late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.55 * progress) + 3.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Reward near-perfect fills strongly
    if post == 0 {
        score -= 60.0;
    } else if post <= eighth {
        score -= 25.0;
    } else if post <= quarter {
        score -= 10.0;
    }

    // Penalize residuals in "dead zones" that few item sizes (1..100) can reuse
    let usable = |r: u32| -> f64 {
        // fraction of item sizes 1..=100 that fit into residual r
        let fit = r.min(100) as f64;
        fit / 100.0
    };
    score += (1.0 - usable(post)) * 20.0;

    // Lookahead: reward leaving exactly the next item's size (perfect chaining)
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 40.0;
        } else if post > next_item_size {
            let slack = post - next_item_size;
            score += (slack as f64) * 0.5;
            if slack <= eighth { score -= 8.0; }
        } else {
            // next item won't fit here: penalize moderately
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin, unless current bin would leave
    // a large unusable residual and no good chaining exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin when existing fit is terrible
        let bad_fit = post > quarter && (next_item_size == 0 || post < next_item_size);
        if bad_fit { score -= 50.0; }
        // early stream: slightly cheaper to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mild pressure toward bins below mean residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Harmonic threshold bump: integer division class of post residual
    let class = post / eighth;
    match class {
        0 => score -= 5.0,
        1 => score -= 2.0,
        2 => score += 3.0,
        _ => score += 6.0,
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    } else if post_residual < 50 {
        score -= 8.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // Prefer bins whose residual is already below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + pressure * 10.0;
        if fitting_bins_count <= 1 {
            score -= 90.0; // no real alternative, opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual small).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // tiny unusable sliver
    }

    // Aggressive 2-step lookahead: reward bins where the next item
    // exactly matches the post_residual, or nearly matches it.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain: next item fills this bin perfectly
        } else if gap <= 10.0 {
            score -= 200.0 - gap * 10.0;
        } else {
            // next item doesn't fit here; mild penalty proportional to leftover waste
            score += gap * 0.5;
        }
        // If next item is large, prefer conserving big residuals.
        if next_item_size >= 60 && post_residual < next_item_size as u32 && post_residual > 30 {
            score += 50.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; placing here is efficient. Bins far above mean are
    // wasteful targets unless fit is great.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
        if post_residual <= 20 {
            score -= 100.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no good fit exists. Penalize fresh bins by default.
    if bin_residual == bin_capacity {
        let base = 150.0;
        // If item is small and many bins are open, discourage new bins.
        let crowd = open_bins_count as f64;
        let mut penalty = base + crowd * 5.0;
        // If the item is huge relative to typical residual, a new bin may be right.
        let mean_r = mean_residual;
        if (item_size as f64) > mean_r + 30.0 {
            penalty -= 120.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += progress * 100.0;
        score += penalty;
    }

    // Mild scaling of residual with stream position: early on, keep bins
    // flexible (large residuals); later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 * (1.0 - progress));

    // Tie-break: prefer bins with fewer siblings fitting (scarcer capacity used).
    score += fitting_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact or near-exact fills are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no plausible future item can use.
    // Items are 1..=100, so residual < smallest item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Bonus if post-residual matches next item almost exactly.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (-gap / 15.0).exp();
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_gap = mean_residual - item_size as f64;
        if avg_fit_gap > 0.0 && avg_fit_gap < 20.0 {
            score += 30.0; // existing bins fit well, don't open new one
        } else {
            score += 4.0; // slight default penalty to prefer reuse
        }
        // Early in stream, opening bins is cheap; late, avoid bin explosion.
        score += 15.0 * progress;
        if open_bins_count > 8 {
            score += 2.0 * (open_bins_count as f64 - 8.0);
        }
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    // Prefer bins below mean residual (consolidate emptier space usage).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Reward tight fits: squared waste penalty (non-linear coupling with progress)
    let waste = post / cap;
    score += waste * waste * cap * (0.5 + 0.5 * progress);

    // Reward filling the bin heavily
    score -= (fit / cap) * (fit / cap) * 20.0;

    // Penalize new-bin candidate (empty bin) unless it's the only option
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 15.0 * (1.0 - scarcity) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Prefer bins with below-mean residual (better packing balance)
    score -= (mean_residual - post) * 0.15;

    // Lookahead coupling: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many bins late in the stream
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else {
        let harmonic_bonus: f64 = if pr % 10 == 0 {
            12.0
        } else if pr % 25 == 0 {
            9.0
        } else if pr % 5 == 0 {
            5.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead-space penalty for tiny unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // guaranteed perfect fit next step
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let over = next_item_size - pr;
            score += (over % 10) as f64 * 0.5;
        }
    }

    // Last chance: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no open bin is a decent fit
    // (i.e., current bin is the empty candidate or mean residual is small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base cost of opening a new bin, discounted when open bins are congested.
        let mean_fit = if item_size as f64 <= mean_residual { 1.0 } else { 0.0 };
        score = cap * 0.9 + open_pressure * 2.0 - progress * 5.0;
        if mean_fit > 0.0 {
            score += 30.0; // an open bin can already take it well; penalize new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large-item stream: fresh capacity useful
        }
    }

    // Slight preference for tighter existing bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Normalize by capacity fraction classes of the item.
    let class = item_size / 25; // 0..3 harmonic class
    score -= class as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else if post_residual < 30 { 8.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few,
    // opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.8;

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post_residual elsewhere) or when the next item pairs well with
    // the fresh residual.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 {
            let pair = if next_item_size <= post_residual_max_hint(item_size) { 1.0 } else { 0.0 };
            // A fresh bin with residual = 100 - item_size can host next item
            let fresh_residual = bin_capacity - item_size;
            if next_item_size <= fresh_residual { score -= 15.0 * pair; }
            if next_item_size == fresh_residual { score -= 25.0; }
        }
        // Late in the stream, prefer closing out existing bins.
        score += progress * 10.0;
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

#[inline]
fn post_residual_max_hint(item_size: u32) -> u32 { 0 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 2.0 * slack.min(15.0);
    }
    // Post-residual too small for next item: dead space penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Penalize residual far below mean residual (poor relative fit).
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow it when the item fits very poorly everywhere (large post_residual).
    if bin_residual == bin_capacity {
        score += 25.0 - 0.15 * item_size as f64;
    }

    // Late in the stream, waste matters more; early on, keep bins flexible.
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness * tightness);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual as f64 / next_item_size as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize bins that are much emptier than the mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Time horizon: early on, keep bins open and flexible; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);
    score -= progress * 4.0;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64 > 0.0 && mean_residual < item_size as f64 * 0.5);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 10.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Prefer filling bins with larger residual proportionally used.
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post_residual (tight fit), non-linearly amplified.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = x * (1.0 + 2.5 * x * x) * cap * 0.1;

    // Strong superlinear penalty for large wasted space (dead space creation).
    score += 12.0 * x.powi(3);

    // Reward tight fits even more as the stream progresses.
    score -= (1.0 - x) * (1.0 - x) * (2.0 + 6.0 * progress);

    // Stream-progress coupling: early on, mild penalty for consuming bins;
    // later, prioritize tight packing more aggressively.
    score += progress * x * 4.0;

    // Lookahead: if the next item fits into the resulting post_residual,
    // reward this placement strongly (smooth interaction with progress).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap; // how snugly next item fills leftover
            score -= (1.5 + 3.0 * progress) * snug;
        } else {
            // Next item won't fit: penalize leaving a residual that is too small
            // to be useful (smooth ramp based on how much is missing).
            let miss = (nxt - pr) / cap;
            score += 3.0 * (1.0 - miss) * (1.0 - miss);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible, handled by base terms).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - x);
    }

    // Many open bins: discourage spreading; few open bins: allow opening new ones.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 0.6 * crowding * x;

    // Penalize new-bin candidate (bin_residual == bin_capacity) smoothly,
    // but less so when mean residual across open bins is already high (poor fits).
    if bin_residual == bin_capacity {
        let mean_excess = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 * (1.0 - 0.7 * mean_excess) * (0.6 + 0.8 * progress);
    } else {
        // Reward choosing bins whose residual is close to the item (good fit ratio).
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 4.0 * fit_ratio * fit_ratio;
    }

    // Mean-residual coupling: if this bin's post residual deviates far above the
    // mean residual, mildly penalize (keeps residual distribution compact).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: how well post_residual composes with
    // typical future items (integer division into capacity fractions).
    let cap = bin_capacity as f64;
    if post_residual > 0 {
        // small leftovers are "dead space"; penalize heavily via inverse
        let pr = post_residual as f64;
        score += 40.0 / pr;
        // residue class of post_residual modulo common item sizes
        let mut class_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                class_bonus += 6.0;
            }
        }
        score -= class_bonus;
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + tight / 10.0);
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += ((next_item_size - post_residual) as f64).min(50.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.8;

    // Encourage opening new bins early vs late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or progress is early
        score -= item_size as f64 * 0.6 + 30.0 * (1.0 - progress);
        // discourage hoarding many open bins
        score += open_bins_count as f64 * 2.0;
    } else {
        // placing in an existing bin reduces fragmentation
        score -= 10.0;
    }

    // Nonlinear tightness coupling
    let fill = 1.0 - (bin_residual as f64 / cap);
    score -= fill * fill * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.6;

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (concentrate filling) when the fit is decent.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: opening a fresh bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; reduced late in the stream when consolidation is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 15.0 * (1.0 - progress);
        // If the only fitting option is bad, make the new bin more attractive.
        if post_residual == 0 {
            score -= 80.0; // unreachable for empty bin, keeps symmetric logic
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the residual left behind can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Leftover can still fit next item: mild reward proportional to slack.
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit in leftover: penalize wasted potential.
            score += 30.0 + 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins.
    let mean_res = mean_residual.max(1.0);
    if (post_residual as f64) < mean_res {
        score -= 0.5 * (mean_res - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_res);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great fit
    // (e.g., item is large or few bins fit the item).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 80.0 * fit_ratio;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 20.0; // discourage wasting a fresh bin when lookahead fits anyway
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
