    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Prefer bins with below-average residual (keep large-residual bins free).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, consolidate harder (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Discourage opening new bins early when open bins can fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    // Slight preference for filling bins with larger current load.
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
