    }

    // Mild penalty for scattering across many open bins late in the stream
    score += 0.15 * open_bins_count as f64 * progress;

    // Penalize large residuals relative to mean residual (fragmentation signal)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (or large enough for
    // typical items) are valuable; tiny prime-ish residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows super-linearly for small residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        } else if pr < 20 {
            score += (20 - pr) as f64 * 2.0;
        }
        // reward residuals that are multiples of common sizes (harmonic classes)
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // perfect fit is ideal
        if pr == 0 {
            score -= 100.0;
        }
    } else {
        score -= 100.0;
    }

    // Perfect-fit bonus when item exactly fills the bin
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
            let rem2 = post_residual - next_item_size;
            if rem2 % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize mildly unless this is the
            // only fitting bin (last chance placement still worthwhile)
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base cost that must be
    // beaten by genuinely good fits into open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // opening a bin is cheaper late in the stream when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // if few bins fit the item, opening fresh space is more attractive
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Tight fit reward: small relative leftover is good
    let tightness = post_residual as f64 / cap;
    score += tightness * 15.0;

    // Prefer bins whose residual is close to the item (minimize fragmentation)
    let frag = (bin_residual as f64 - item_size as f64).abs();
    score += frag * 0.2;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's an outlier; filling it consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 2.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 10 && post_residual <= 60 {
        score -= 6.0;
    } else if post_residual > 60 {
        // Large residual is fine (still versatile).
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist,
    // but relax pressure as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from existing open bins.
        score += 15.0 + open_bins_count as f64 * (8.0 - 4.0 * progress);
        // If nothing open fits well (many fitting bins but none tight), new bin is less bad.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight reward for consolidating into already-open bins.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins whose residual is close to the item (tight fit among open bins).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.05;
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for opening a brand-new empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if !is_new_bin && post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        }
        // Penalize leaving a gap that almost fits the next item (dead space).
        if !is_new_bin && post_residual > 0 && post_residual < next_item_size {
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
        // New bin is attractive when next item also fits well into a fresh bin
        // and current fit is poor (large post_residual on an open bin).
        if is_new_bin && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Prefer tight fits: small post_residual relative to capacity.
    score += 30.0 * (post_residual as f64 / bin_capacity as f64).powf(2.0);

    // Last-chance bonus: this is the only open bin that fits the item.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Encourage filling bins when many bins are open (bin consolidation).
    if !is_new_bin && open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins with residuals near the mean residual (keeps bin balance),
    // slightly stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score += (1.0 + progress) * 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Early stream: slightly favor opening bins to build a good pool.
    if is_new_bin && progress < 0.2 {
        score -= 6.0 * (1.0 - progress / 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let pr = post_residual as f64 / bin_capacity as f64;
    let tightness = (1.0 - pr).powi(3);
    score -= 12.0 * progress * tightness * (item_size as f64 / bin_capacity as f64);

    // Reward bins whose residual can still host the next item (k=2 lookahead).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 8.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize residual dead space that the next item cannot use.
        score += 4.0 * (1.0 - progress) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 6.0 * avg_fit + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    // Prefer bins with residual below mean residual (better consolidation).
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0) * progress;

    // Small smooth tie-breaker against very large wasted space.
    score += 0.05 * (pr * std::f64::consts::PI).sin().abs() * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are more reusable
    let residue = post_residual % 10;
    score += match residue {
        0 => -6.0,
        1 | 9 => 3.0,
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        4 | 6 => 0.5,
        _ => 1.5,
    };

    // Integer-division class: post_residual / 20 quarters of capacity
    let quarter = post_residual / 20;
    score -= quarter as f64 * 2.5;

    // Perfect-fill reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic class match: next item leaves a "nice" residue too
            let nr = (post_residual - next_item_size) % 10;
            let bonus = if nr == 0 { 8.0 } else { 3.0 };
            score -= bonus;
        } else {
            // this bin becomes dead after placement
            let dead = post_residual;
            score += (dead as f64) * 0.4;
            // penalize more if dead space is in an awkward harmonic class
            if dead % 10 != 0 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 60.0;
        // attractive if item is large (fills new bin well)
        score -= (item_size as f64) * 0.45;
        // if no open bin fits well, opening is more reasonable
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // early in stream, keep fewer bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // lookahead: if next item is huge, fresh bin is valuable
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0;
        }
    } else {
        // prefer bins whose residual is close to item (tight fit) among open bins
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // mild penalty for proliferating bins
        score += open_bins_count as f64 * 0.3;
        // prefer bins below mean residual (consolidate emptier space usage)
        score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit the smallest plausible next item
    // (min item 1..10 band; treat <10 as likely dead space).
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // But if mean residual across open bins is very small (all bins tight),
        // opening a new bin is reasonable — reduce penalty.
        score -= (mean_residual / 10.0).min(20.0);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if post_residual can still fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Slight stream-progression term: as stream nears end, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let mut score = post;

    // Perfect fit bonus: strongly reward zero residual.
    if post_residual == 0 {
        score -= 3.0 * cap;
    }

    // Near-perfect fit bonus (residual <= 2).
    if post_residual > 0 && post_residual <= 2 {
        score -= 1.5 * cap;
    }

    // 2-step lookahead: if the NEXT item exactly fits the post_residual,
    // this is a chained perfect fit -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 2.5 * cap;
        } else if next_item_size > 0 && post_residual > next_item_size {
            // Next item fits inside the leftover: mild reward proportional
            // to how well it fills the leftover.
            let fill_ratio = next / post;
            score -= 0.8 * cap * fill_ratio * fill_ratio;
        } else if next_item_size > 0 && next < post {
            // unreachable guard (kept for clarity)
        } else {
            // Next item will NOT fit in leftover: penalize leftover that
            // becomes dead space relative to the mean residual.
            let dead = (post - next).min(cap);
            score += 0.3 * dead;
        }

        // Coupling with mean residual: bins whose leftover is far below the
        // mean residual are "efficient" bins; reward keeping them tight.
        if post < mean_residual {
            score -= 0.4 * (mean_residual - post);
        } else {
            score += 0.2 * (post - mean_residual);
        }
    } else {
        // Last item: just pack as tightly as possible.
        score -= 0.5 * cap * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 * cap;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let item_ratio = item / cap;
        // Large items start fresh bins easily; small items should try open bins.
        if item_ratio > 0.7 {
            score -= 0.8 * cap;
        } else {
            score += 0.5 * cap * (1.0 - item_ratio);
        }
        // If many bins are open, discourage opening more.
        score += 0.15 * cap * (open_bins_count as f64).sqrt();
    }

    // Mild stream-progression tie-breaker: later in the stream, prefer
    // consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 0.2 * cap * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted residual relative to capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 80.0;
    }

    // Lookahead coupling: bonus if the post residual accommodates the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 0.3 * slack.min(60.0);
        } else {
            // Penalize leaving residual too small to be useful for the next item.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize opening a new bin when good open bins exist; scale with open count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).sqrt() * 5.0
            + mean_residual * 0.4
            + progress * 30.0;
        // Only attractive if the item is large and mean residual is small.
        let large_item = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += 60.0 + pressure - large_item;
    }

    // Slight preference for bins with residuals close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.2;

    // Mild time-horizon exploration term: early on, spread slightly; late, consolidate.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap; // 0 = perfect fit, 1 = empty bin
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base cost: quadratic penalty on wasted residual, amplified over time
    let mut score = fit_ratio * fit_ratio * (1.0 + 2.0 * progress) * cap;

    // Dead-space term: residuals too small to be useful later get extra penalty
    let dead_zone = (cap * 0.35).max(0.0);
    if post < dead_zone && post > 0.0 {
        score += (dead_zone - post) * (0.5 + progress);
    }

    // Lookahead coupling: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let can_host = (post >= nxt) as i32 as f64;
        let snug = 1.0 - ((post - nxt).abs() / cap).min(1.0);
        score -= can_host * snug * snug * (3.0 + 4.0 * progress);
        // Penalize leaving a gap the next item nearly-but-doesn't fit (wasted slot)
        let near_miss = ((nxt - post) / cap).max(0.0);
        score += if post < nxt { near_miss * near_miss * cap * 0.8 } else { 0.0 };
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 1.5;
    }

    // Congestion-aware: many open bins with high mean residual -> discourage new bins,
    // encourage consolidating into bins with residual above the mean
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when stream is late or many bins open
        score += cap * (0.6 + 0.8 * progress + 0.05 * open_bins_count as f64);
        // but relax penalty if mean residual is low (existing bins nearly full)
        score -= mean_residual * 0.6;
    } else if post > mean_residual {
        score -= (post - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover space by divisibility
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Small leftovers are dead space; penalize non-linearly
    if post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 40 {
        score += 8.0;
    }

    // Reward leftovers that are likely to be filled by future items:
    // harmonic classes (multiples of 5 / 10 are common landing zones)
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // prefer placements that leave a good class for the item after next
            if nxt_post % 5 == 0 {
                score -= 20.0;
            }
            if nxt_post <= 10 {
                score += 15.0; // but tiny final dead space is bad
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this bin's leftover: mild penalty for wasted harmony
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: opening a bin is expensive when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening early in stream or when few bins fit the item is more acceptable
        score = cap * 0.6 + 30.0 * (1.0 - progress) - 15.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        if fitting_bins_count == 1 {
            score += 40.0; // an open bin exists that is last-chance; prefer it
        }
        return score;
    }

    // Tightness reward: filling most of the bin
    let fill = 1.0 - post / cap;
    score -= fill * 30.0;

    // Mean residual coupling: if this bin is far below mean residual, it's a good absorber
    score -= (mean_residual - post).clamp(-50.0, 50.0) * 0.2;

    // Slight preference to keep many low-residual bins consolidated when stream is long
    if total_items > 100 && open_bins_count > 8 {
        score += post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize spreading across many open bins; pressure to consolidate.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (larger residual bins absorb items).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open.
        score = bin_capacity as f64 - 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in the stream, prefer consolidation over new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to leftover after next
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit: penalize large dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins fit, scaled by stream progress
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 50.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Small waste penalty for large leftover space
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large residuals relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * (bin_capacity as f64) * 0.6;

    // Penalize creating dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when many bins can already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fitting_bins_count as f64;
        score += 15.0 + pressure * 6.0 + progress * 10.0;
        // But allow new bin if mean residual is very low (all bins nearly full).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Global state coupling: when open bins have large mean residual,
    // discourage wasting this bin's space on small items.
    if bin_residual != bin_capacity {
        let waste = (mean_residual - post_residual as f64).abs();
        score += waste * 0.1;
    }

    // Time horizon: early in stream, be more exploratory (favor spreading);
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    // Prefer bins with residual close to item size (minimal slack).
    let slack = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += slack * slack * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_post = post / cap;

    // Base: quadratic penalty on post-residual (dead space), slightly convex.
    let mut score = post * (1.0 + 0.5 * norm_post);

    // Smooth coupling: post-residual penalized more as stream progresses
    // (later dead space is costlier since fewer items remain to fill it).
    let progress_coupling = post * (0.6 * progress * progress + 0.4 * progress);
    score += progress_coupling;

    // Smooth interaction with mean residual: if this bin's post-residual
    // deviates from mean, dampen/balance via cubic smooth term.
    let dev = (post - mean_residual) / cap;
    score += 20.0 * dev * dev * dev.abs().min(2.0) / (1.0 + progress);

    // Lookahead: reward if next item fits snugly into post-residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            let snug = 1.0 - ((post - n) / cap).abs();
            score -= 15.0 * snug * snug;
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += 5.0 * ((n - post) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize proportional to open bins and progress,
    // so we prefer reusing bins unless the fit is genuinely bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    }

    // Tiny fill-fraction reward (smooth): fuller bins preferred.
    score -= 3.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (0, <=10, <=20, <=34, <=50, >50).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 34 { 3 }
        else if post_residual <= 50 { 4 }
        else { 5 };

    // Reward tight fits (small classes), strongly reward exact closure.
    score -= match class {
        0 => 60.0,
        1 => 30.0,
        2 => 14.0,
        3 => 5.0,
        4 => 0.0,
        _ => -3.0,
    };

    // Integer-division harmonic: does next item land cleanly in the leftover?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect pair closure
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // modular closeness of the pair fit
            let m = gap % 10;
            score -= 12.0 - (m as f64);
            if gap <= 10 { score -= 8.0; }
        } else {
            // next item cannot use this leftover: penalize large stranded space
            score += (pr - (next_item_size as f64)).max(0.0) * 0.05;
        }
    }

    // Dead-space penalty: leftover below the minimum item size is stranded.
    if post_residual > 0 && post_residual < 1 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly
    // so existing tight fits win, but keep it competitive when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * (open_bins_count as f64);
    } else {
        // Prefer fuller bins among open ones (normalized fullness bonus).
        score -= (bin_capacity - bin_residual) as f64 / cap * 5.0;
    }

    // Late-stream consolidation: as stream progresses, avoid leaving many
    // open bins with scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr - mean_residual).max(0.0) * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure waste, but tiny gaps that cannot fit
    // the lookahead item are especially harmful if next_item_size is real.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver: heavy penalty
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to capacity.
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open,
    // penalize spreading across bins when few are open.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item barely fits anywhere) or open bins are nearly full.
    if bin_residual == bin_capacity {
        let tight_elsewhere = mean_residual < item_size as f64 + 5.0;
        if tight_elsewhere || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Lookahead synergy: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
    }

    // Mild stream-progression bias: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Distance from mean residual: prefer bins whose leftover tracks the pack mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight 2-step fits heavily
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus for exact match
            if slack == 0.0 {
                score -= 60.0;
            }
        } else {
            // Penalize leaving a residual the next item cannot use
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            // Extra penalty if the leftover is unusable dead space (small residual)
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Reward tight fits relative to mean residual (best-fit flavor)
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // a fresh bin guarantees perfect 2-step chain for big items
            if item_size + next_item_size >= bin_capacity {
                score -= 80.0;
            }
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize unusable dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing for the next item
        } else if post_residual >= next_item_size {
            score -= 6.0;  // next item still fits here
        } else {
            score += 8.0;  // next item would be stranded by this choice
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> consolidate into existing ones.
    let open_bias = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 4.0 * open_bias;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (draining nearly-full bins keeps many roomy bins alive).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If the current bin would leave a large awkward residual, opening fresh is fine.
        if post_residual > 0 && (post_residual as f64) > 0.5 * bin_capacity as f64 {
            new_bin_cost -= 15.0;
        }
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress) + 0.35 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits more as stream progresses
    score -= (1.0 - norm_pr) * (0.5 + 0.6 * progress);

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.25 * (1.0 - pr / (next_item_size as f64)) * progress;
    }

    // Penalize creating dead space below typical item sizes
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 0.4;
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: penalize mildly early, allow late in stream or when few fit
    if bin_residual == bin_capacity {
        score = 1.5 + progress * 0.8 - 0.05 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize post_residuals in "awkward" harmonic classes (small but nonzero leftovers).
    // Classes: 0 (perfect), (0,10] (dead), (10,33] (harsh), (33,50] (half-ish), (50,100] (roomy).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 45.0; // dead space: unusable for items >= 10
    } else if post_residual <= 33 {
        score += 18.0;
    } else if post_residual <= 50 {
        score -= 5.0; // half-bin residual is valuable
    } else {
        score -= 10.0; // roomy residual
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align with item grid.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
            // extra reward if next item fits leaving another useful residual
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 8.0; // chain ending in near-perfect fit
            }
        } else {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    } else {
        // last item: prefer tightest fit
        score = pr;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current bin fit is poor.
    if bin_residual == bin_capacity {
        // neutral baseline; adjust with stream progress and congestion
        score = cap * 0.55
            + (open_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // empty bin naturally fits anything; slight bonus early, penalty late
            score -= 5.0;
        }
        if mean_residual > cap * 0.4 && fitting_bins_count > 1 {
            score += 15.0; // plenty of slack elsewhere: don't open new bin
        }
    }

    // Mild preference for consolidating into bins below mean residual (tighter bins).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else if bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste. Penalize "unusable" small gaps quadratically.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 2.5;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward tightness relative to bin capacity (best-fit core, sharpened).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when existing fits are bad
    // (i.e., when the item leaves a large awkward gap in any open bin).
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if post_residual >= 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 0.0 };
        // A fresh bin scores like a mediocre fit: high base, reduced if open bins are
        // already fragmented (high mean residual) and this item is large.
        score = bin_capacity as f64 * 0.75
            - bad_fit_pressure * 25.0
            - fill_ratio * 20.0
            + open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: mild penalty for small leftovers.
        if post_residual < next_item_size && post_residual > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post residual (perfect chain fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Exact match => big bonus; near match => proportional bonus.
            score -= 60.0 * (1.0 - gap / 100.0).max(0.0);
            // Extra bonus for exact fill of post_residual.
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use this residual: penalize leftover dead space
            // proportionally to how far off it is.
            let excess = next - pr;
            score += 0.5 * excess;
        }
    } else {
        // Last item: just minimize post residual (tightest fit).
        score -= 20.0;
    }

    // Reward bins whose residual is below the mean (already tight bins),
    // penalize bins holding excess slack relative to mean.
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 50.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless no reasonable fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = post_residual as f64; // = capacity - item
        // Opening a new bin is attractive only when the item is large
        // (little waste) or no other bins fit and residual would be badly fragmented.
        score += 70.0;
        score -= 0.4 * (bin_capacity as f64 - waste); // larger items => cheaper new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // New bin could chain the next item too: soften penalty.
            score -= 30.0;
        }
        // Early in the stream, be more willing to open bins.
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for leaving tiny unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer keeping the number of open bins manageable when many bins exist.
    score += 0.05 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly penalized.
    let mut score = post * (1.0 + 0.6 * post / cap);

    // Smooth stream-progress coupling: later in the stream, tighten tolerance on wasted space.
    score += 12.0 * progress * (post / cap) * (1.0 - progress);

    // Reward near-exact fills: quadratic bonus when post_residual is small.
    let tightness = 1.0 - post / cap;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a bin unless the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (post - n).abs();
        score += 0.25 * gap * gap / cap;
        if post >= n && post - n <= 10.0 {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer minimizing final waste.
        score += 5.0 * post / cap;
    }

    // Mild coupling with mean residual: prefer bins deviating from mean (consolidate waste).
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for denser bin populations late in the stream.
    score -= 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into
    // "nice" classes (0, small, or exact quarter-capacity multiples) are
    // more reusable, so reward them; awkward mid-range leftovers penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarter-capacity harmonic classes: r mod (C/4)
    let quarter = cap / 4.0;
    let class = (pr % quarter) / quarter; // in [0,1)
    score -= 6.0 * (1.0 - class);        // closer to a quarter boundary => more reward

    // Eighth-capacity fine structure
    let eighth = cap / 8.0;
    let fine = (pr % eighth) / eighth;
    score -= 2.0 * (1.0 - fine);

    // Integer-division thresholds on post_residual:
    // leftover <= 10 is nearly dead space -> strong penalty.
    if post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual >= 50 {
        score -= 8.0; // roomy leftover can host medium items
    }

    // Lookahead coupling: penalize leftovers that cannot host next_item_size
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // reward proportional to how snugly next item fits afterwards
            let next_post = post_residual - next_item_size;
            score -= 10.0 * (next_post as f64 / cap);
            if next_post == 0 {
                score -= 20.0; // perfect two-item packing
            }
        }
    }

    // Last-chance bonus: only this bin fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline anchored to mean residual
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.2 * (mean_residual - pr);
        // late in the stream, opening new bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees next-item fit
        }
    }

    // Mild penalty for spreading across many bins when residuals are already low
    if open_bins_count > 4 && mean_residual < cap * 0.2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was large (good utilization of space).
    score -= (bin_residual as f64) * 0.05;

    // Open-bin pressure: discourage spreading across many bins mildly.
    score += (open_bins_count as f64) * 0.3;

    // If this bin is the last fitting bin, strongly favor using it
    // (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if the item would leave
    // a large, still-usable residual or no open bin is a good home.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Less costly late in the stream? Slight early-stream encouragement
        // to build a diverse pool of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If the next item could use the leftover of this placement here,
        // opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // If many bins fit but all would leave tiny dead space, new bin wins.
        if post_residual >= item_size {
            score -= 5.0;
        }
    } else {
        // Existing bin that leaves a residual exactly matching next item:
        // reward chaining placements.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Slight penalty if this bin's residual is far above the mean residual
    // (i.e., it is unusually empty; better to fill emptier bins first).
    let resid = bin_residual as f64;
    if resid > mean_residual + 20.0 {
        score += (resid - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize small dead space that nothing (min size 1..10) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item is excellent.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.35;
        }
        // If next item fits exactly after this placement, extra reward.
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 15.0;
        }
        // If placing here leaves a gap that can't fit the next item but the
        // next item is small, mild penalty (wasted lookahead opportunity).
        if post_residual < next_item_size && next_item_size <= 10 {
            score += 8.0;
        }
    }

    // Relative-to-mean-residual coupling: bins tighter than average are
    // preferred to consolidate small residuals.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no tight fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are usually preferred...
        score += 30.0;
        // ...but relax for large items where a fresh bin gives a clean fit.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 25.0 * frac;
        }
        // If no open bin fits well (many fitting bins means plenty of choice),
        // a fresh bin is fine for big items.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
