pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: penalize residual more as stream progresses
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth bonus
    score -= 20.0 * (1.0 - pr) * (1.0 - pr) * progress;

    // Penalize leaving residual that matches next item poorly (smooth interaction)
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += 8.0 * (diff / bin_capacity as f64).sqrt() * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.3 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);

    // Discourage opening new bins early unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 10.0 * (1.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let q = (bin_capacity / 5).max(1); // class width = 20
    let class = post_residual / q;     // 0..5 harmonic class
    // Penalize small-but-unusable residuals (dead space classes 1..2).
    if post_residual > 0 && class <= 2 {
        score += 12.0 * (3.0 - class as f64);
    }
    // Reward large residuals left over (flexible space).
    if class >= 4 {
        score -= 6.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: next item's class matches residual class
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            // next item won't fit here; penalize tight leftovers that strand the bin
            score += 5.0;
        }
        // modulo coupling: same harmonic class between next item and post residual
        let nclass = (next_item_size / q) as f64;
        let rclass = class as f64;
        if nclass == rclass && next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // last item: prefer exact/tight fits
        score -= 3.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins open already
        score = (bin_capacity as f64) * 0.9 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // fresh bin keeps lookahead room
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
    }

    // Progress-aware tightening: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += progress * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous, classic best-fit-with-balance).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Small tie-break toward fuller bins.
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the smallest possible item
    // are pure waste, so weight them heavily.
    if post_residual < 10 {
        score += (10 - post_residual as u32) as f64 * 3.0;
    }

    // Tight fits are rewarded: the smaller the post_residual, the better the packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 4.0;

    // Pressure term: discourage spreading across too many open bins unless the fit is great.
    score += (open_bins_count as f64) * 0.15 * (1.0 - tightness);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item would fit perfectly in the resulting residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover; mild penalty for stranded residual.
        score += 2.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit is bad.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 8.0 - crowding * 10.0;
    }

    // Stream progression: later in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact two-item packing
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-gap / 15.0).exp(); // near-exact follow-up fit
        } else {
            let excess = (next_item_size - post_residual) as f64;
            // next item cannot follow here; penalize residual that is too small to be useful
            score += 10.0 * (excess / 30.0).min(1.5);
        }
        // If post_residual can't fit anything typical anymore (dead space)
        if post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: purely minimize post_residual
        score -= 20.0 * tightness;
    }

    // Compare residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        // prefer bins with below-average residual (fuller bins) mildly
        score += 8.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Last-chance bin bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 25.0 + 15.0 * (1.0 - progress);
        if post_residual as f64 > threshold && fitting_bins_count > 0 {
            score += 35.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer consolidating among many open bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if the next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving a gap that is too small for the next item (dead space).
            let gap = post_residual as f64;
            if gap > 0.0 {
                score += 6.0 * (1.0 - (next_item_size as f64 - gap) / 100.0).min(1.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // Penalize bins far below the mean residual (fragmentation avoidance).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for leaving small unusable residuals (< 10, the minimum item size).
    if post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: default to it only when fits are bad or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        // Prefer new bin when current item is large relative to capacity or many bins are tight.
        let tight = mean_residual < item_size as f64 * 0.5;
        score -= if tight { 5.0 + 10.0 * progress } else { 0.0 };
        score += 4.0 + 2.0 * pressure; // base cost of opening a new bin
    }

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score -= (1.0 - norm_pr).powi(2) * 20.0 * (0.5 + 0.5 * progress);
    score -= (norm_pr * norm_pr) * 15.0 * (1.0 - progress);

    // Penalize tiny dead space (waste) with cubic term
    if pr > 0.0 {
        score += 30.0 * (1.0 - norm_pr).powi(3);
    }

    // Perfect fit reward, smoothly scaled by progress
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild preference against spreading across many bins early
    score += 2.0 * (open_bins_count as f64 / (total_items as f64).sqrt()) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space penalty grows super-linearly as residual shrinks below item sizes
    // that could still arrive (min size 1). Modulo classes: residuals that are
    // "harmonically compatible" with common sizes (divisible by 5 or 10) are
    // easier to fill later -> reward them.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -6.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Non-linear waste curve: penalize small-but-unusable residuals hardest.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below the smallest plausible item
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new
    // bin instead (subtract to favor using it).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin has no urgency. Make it attractive
    // only when current residual is a bad harmonic class or very tight.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 18.0;
        // but if the best existing fit is poor (post_residual tiny/wasted),
        // the caller's other scores will be high, so allow opening.
        if post_residual < 15 {
            score -= 20.0;
        }
        // early in the stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // many open bins with slack: discourage one more
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "tight" bin — prefer filling tight bins first.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 3.0 * (dev / cap).min(1.0);
    } else {
        score += 1.5 * ((-dev) / cap).min(1.0);
    }

    // Integer-division threshold: post_residual in [25,50) is a "half-bin class"
    // that is still quite useful; soften the raw residual preference there.
    if post_residual / 25 == 1 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading items out.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to lookahead
    }

    // Prefer bins with below-average residual (tighter bins) early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * (0.25 - 0.15 * progress);

    // New-bin candidate: mild penalty so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this placement is excellent — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward proportional to match.
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit after this placement: penalize wasted
            // residual relative to the next item's size.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residual relative to mean residual across open bins
    // (avoid creating outlier dead space).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere (small item in a large residual context is fine, but
    // opening new bins for well-fitting items is wasteful).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; scaled by stream progression
        // (early on, opening bins is cheaper; late, consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 + 300.0 * progress;

        // If the item leaves a huge residual in the new bin (small item),
        // discourage even more.
        score += 0.5 * post_residual as f64;
    }

    // Mild penalty for very small leftover slivers (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // chain fit: item + next item exactly fills bin
        } else if gap > 0 {
            score -= 12.0 * (1.0 - (gap as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize small leftovers
            score += 8.0;
        }
    }

    // Prefer fuller bins when many bins are open (bin consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= fill_ratio * 10.0 * (1.0 + open_pressure * 0.15);

    // Penalize bins whose residual deviates badly from mean residual
    // (keeps pool of residuals coherent for future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (score new-bin candidate better); late in stream, consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by item size and remaining stream length.
        score += 25.0 + 0.4 * item_size as f64;
        score -= 30.0 * (1.0 - t);
        // If next item is large and this item is small, new bin may be fine.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight bonus late in the stream.
        score -= 10.0 * t;
    }

    // Discourage creating dead space smaller than the minimum item size
    // (assuming items >= 1; residual < 10 is often unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer bins with small post-residual, non-linearly
    let mut score = pr.powf(1.3);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tight fits matter less; late, dead space is costly.
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += 120.0 * coupling;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    let perfect = (-norm_pr * 8.0).exp();
    score -= 40.0 * perfect * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize bins that are far below mean residual (they are outliers wasting space)
    let mean_norm = mean_residual / cap;
    let dev = mean_norm - norm_pr;
    score += 25.0 * dev * dev;

    // Lookahead: if next item fits exactly in post residual, reward heavily
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_next = (-diff / 12.0).exp();
        score -= 30.0 * fit_next;
    }

    // New-bin candidate: neutral-ish baseline; open new bin only if it beats
    // genuinely poor fits. Slight decay over stream to encourage reuse later.
    if bin_residual == bin_capacity {
        score = 45.0 + 40.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo small integers
    // capture "nice" leftover sizes that pair well with common item sizes.
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Reward when the leftover is exactly usable by the lookahead item.
    if nxt > 0 && post == nxt {
        score -= 60.0;
    } else if nxt > 0 && post >= nxt && post - nxt <= 10 {
        score -= 30.0; // near-perfect two-item packing
    }

    // Penalize dead space: leftover too small for the smallest plausible item.
    if nxt > 0 && post < nxt {
        score += 25.0 + 0.5 * (nxt - post) as f64;
    }

    // Modulo-10 harmonic classes: leftovers divisible by 10 are friendlier.
    let r10 = post % 10;
    if r10 == 0 {
        score -= 12.0;
    } else {
        score += (r10 as f64) * 0.8;
    }

    // Modulo-5 secondary class.
    if post % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: large usable chunks (post >= 40) are good.
    if post / 40 >= 1 {
        score -= 8.0;
    }
    if post / 25 >= 1 {
        score -= 4.0;
    }
    if post < 15 && post > 0 {
        score += 18.0; // awkward sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_frac * 10.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 50) {
            score -= 20.0;
        } else {
            score += 40.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Lookahead compatibility: if next item cannot fit anywhere else, keep room.
    if nxt > 0 && post >= nxt {
        score -= 5.0 + 0.1 * (post - nxt) as f64;
    }

    // Mild stream-progression tiebreak: early on, be slightly conservative.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score += (1.0 - t) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item size are worthless; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: post_residual just below typical item sizes is bad,
    // but a residual that still fits a meaningful chunk is good.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item would not fit and post_residual is small, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins with slack -> discourage spreading,
    // favor bins that absorb more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress) * 0.5;

    // Prefer bins tighter than average (concentrate slack).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when fitting_bins_count is high (fragmented slack) or fit is poor.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are chosen only when justified.
        score += 8.0 + open_bins_count as f64 * -0.2;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for lookahead pairing in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.20;
