pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 - 10.0 * crowded.min(3.0) + 5.0 * progress;
        // If no open bin fits tightly, allow new bin more readily when item is large
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual near mean (balance load) slightly
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress * progress);
    score += 40.0 * poly;

    // Penalize large post-residual late in the stream (wasted space compounds)
    score += (pr * pr / cap) * (0.2 + 0.8 * progress);

    // Reward tight fits (small post-residual) with smooth decay
    score -= 30.0 * (-pr / 15.0).exp() * (1.0 + progress);

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        if fits_next {
            score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 8.0 * (1.0 - (next_item_size as f64 / cap)) * progress;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure against proliferating open bins relative to mean residual
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * progress;

    // New-bin candidate handling: prefer it only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 60.0 - 40.0 * progress + 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Dead-space penalty: leftover too small for typical future items is wasted.
    if post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if frac < 0.10 {
        score -= 6.0; // tight fit, good packing
    } else if frac < 0.30 {
        score += 2.0; // moderately useful leftover
    } else {
        score += 10.0; // large leftover: wasteful placement
    }

    // Lookahead coupling: can the next item also fit here?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: leftover accommodates the next item.
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64).min(10.0) * 0.3;
        } else {
            // Leftover cannot host the next item -> dead space risk.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin roughly neutral-to-poor,
    // only winning when all real bins would leave big dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        // Early in the stream, allow new bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Slight preference for fuller bins relative to the fleet mean.
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Harmonic modulo classes on post_residual: leftovers that are multiples
    // of common item sizes (10,20,25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize unusable dead space: small post_residual gaps that likely cannot
    // host any future item (assuming min item size ~10, but distribution unknown).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // If post_residual can still fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 3.0;
        // Opening a new bin is acceptable if existing residuals are small/tight.
        score += mean_residual * 0.5;
    }

    // Late in the stream, prefer closing bins tightly (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
