pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; slight penalty proportional to wasted lookahead
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual < item_size as f64 {
        score -= 6.0 * (1.0 - progress);
    }

    // Penalize opening new bins early when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins and stream progress.
        score += 25.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        // But if mean residual is very low (all bins nearly full), opening is fine.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score += 0.05 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear tightening as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for awkward residual sizes (hard-to-fill leftovers)
    let awkward = (fit_norm - 0.35) * (fit_norm - 0.35);
    score += 25.0 * awkward * (0.5 + progress);

    // Reward tight fits (small post_residual relative to capacity)
    score -= 12.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Last-chance bonus: only fitting bin => strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into post-residual, reward; else penalize dead space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (pr / cap) * (0.4 + 0.6 * progress);
        }
    }

    // Coupling with mean residual: avoid bins far from the mean (keeps residual spread tight)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * progress;

    // New-bin candidate: penalize opening a new bin unless item is large / fits are poor
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (item_size as f64 / cap) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual into capacity-fraction bands.
    // Small post_residual = tight fit = good (reward). Large = wasteful.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.05 {
        score -= 60.0;          // near-perfect fill
    } else if frac <= 0.15 {
        score -= 40.0;
    } else if frac <= 0.30 {
        score -= 10.0;
    } else if frac > 0.60 {
        score += 40.0;          // large dead space
    }

    // Modulo classes on post_residual: residues divisible by common item
    // sizes are more likely reusable by future items.
    let pr = post_residual;
    if pr >= 10 && pr % 10 == 0 {
        score -= 15.0;          // round residue likely reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 10.0;
    }
    // Odd, awkward residues are dead space.
    if pr > 0 && pr < 10 {
        score += 50.0;          // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 30.0;  // next item nearly fills this bin
            }
        } else {
            // next item cannot use this bin's residue; penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin should be discouraged when a
    // decent fit exists elsewhere; encouraged when mean residual is low
    // relative to item size (fragmented bins).
    if bin_residual == bin_capacity {
        // New bin baseline: leave residual = capacity - item_size.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;     // no alternative, must open
        } else if mean_residual < item_size as f64 * 1.1 {
            score -= 60.0;      // existing bins are too fragmented
        } else if fitting_bins_count == 1 {
            score += 25.0;      // prefer using the single last-chance bin
        } else {
            score += 30.0;      // good fits exist; prefer them
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;      // fresh bin accommodates lookahead too
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0 * (1.0 - frac);
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps are worse than moderate leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Pressure on number of open bins: prefer reusing existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins whose residual is already low (tight bins first).
    score += (bin_residual as f64) * 0.3;

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just below the next item's size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) >= (next_item_size as u32) - 5 {
        score += 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but relax when many bins are open with poor mean residual.
    if bin_residual == bin_capacity {
        score += 40.0 - (mean_residual / bin_capacity as f64) * 30.0;
        // Late in the stream, be more open to new bins.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 35.0;
    }

    // 2-step lookahead: exact match of post_residual to next item is ideal
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = pr - nr;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to the lookahead item
            score += (nr - pr) * 0.8;
        }

        // chain fit: item + next item exactly fill the bin
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // Last-chance bin before opening a new one: strong bonus to avoid waste
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins far tighter than the mean residual (hoarding big gaps)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Prefer using already-open bins over opening new ones when fit is decent
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual after placement is the primary driver,
    // but amplify the reward for near-exact fits (post_residual small).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap);
    score -= 6.0 * tightness * tightness * (item_size as f64 / cap);

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 40.0;
            } else if gap < 10.0 {
                score -= 15.0 * (1.0 - gap / 10.0);
            }
        } else {
            // next item cannot fit here anyway; slight penalty for wasting
            // a bin that could hold the next item via another arrangement.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Penalize the new bin proportionally to how fragmented
    // the current state is (encourage closing out open bins first).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (open_bins_count as f64 / 20.0).min(1.0);
        score += 12.0 + 18.0 * fragmentation + 6.0 * (1.0 - progress);
        // But if the item is large relative to mean residual, opening fresh
        // may be better: relax the penalty.
        let spread = mean_residual - item_size as f64;
        if spread > 20.0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residuals below the mean (consolidate
    // fullness into already-dense bins, keep roomy bins for big items).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 1.5 * dev.min(30.0) / 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred, with non-linear (quadratic) coupling to stream progress.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward bins whose residual is "consumed" well relative to mean residual state.
    let norm_post = pr / cap;
    score += 0.5 * (norm_post - mean_residual / cap) * (1.0 + progress);

    // Lookahead: penalize leaving space that next item cannot use efficiently.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack_waste = (pr - ns) / cap;
            score += 0.6 * slack_waste * slack_waste * cap;
        } else {
            // Next item won't fit here; leftover is likely dead space.
            score += 0.25 * norm_post * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        // Slight penalty when many bins compete: prefer filling more-full bins anyway.
        score -= 1.0 / (1.0 + fitting_bins_count as f64);
    }

    // Mild pressure to consolidate as bins accumulate.
    score += 0.02 * (open_bins_count as f64) * norm_post;

    // New-bin candidate: must not look attractive unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual quantized into capacity fractions (1/8 of C)
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor(); // 0..8 harmonic class
    // Dead-space penalty: residuals below 1/8 capacity are near-unusable
    if class < 1.0 {
        score += 25.0 * (1.0 - frac);
    } else {
        // reward bins whose residual is a "clean" harmonic class (divisible slots)
        let div = bin_capacity / 8;
        if post_residual % div == 0 {
            score -= 6.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // bonus if next item also lands on harmonic class boundary
            let nfrac = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            if (nfrac * 8.0).fract() < 1e-9 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize wasting the lookahead chain
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - frac * bin_capacity as f64).abs();
        score += 35.0 - 10.0 * fragmentation.max(0.0).min(3.0);
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if open_bins_count > 0 {
            score += 12.0;
        }
    }

    // Mild penalty for leaving residual far from mean (keeps bins homogeneous)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Prefer bins with larger residual for larger items (tight packing)
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold anything useful.
    // Treat gaps below the minimum item size as fully wasted.
    let min_item = 1u32;
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual <= 5 {
        score += 15.0; // near-perfect but likely dead
    }

    // Reward filling bins tightly relative to capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Penalize leaving a gap that next item could have used but we spoil.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap exactly fitting the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size && post_residual >= min_item {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering into many bins.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0; // discourage new bin when alternatives exist
        }
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (closing out smaller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early stream: be slightly more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score += (1.0 - fit_ratio) * 8.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Compare against mean residual: avoid wasting space in low-residual bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * (item_size as f64);
        // If no good fit exists elsewhere, allow new bin (handled by penalty size)
        if fitting_bins_count <= 1 && item_size >= 50 {
            score -= 8.0;
        }
    }

    // Late in stream: consolidate harder
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: small post-residuals are valuable, penalize dead space
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Smooth interaction of post_residual with stream progress
    score += 6.0 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Reward near-perfect fills more strongly as stream advances
    if pr == 0 {
        score -= 20.0 * (0.5 + progress);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - (pr / cap));
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = (pr - mean_residual).abs();
    score += 2.0 * (dev / cap).powi(2);

    // Lookahead: favor bins whose residual fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class: post_residual bucketed by capacity fractions.
    let q = (bin_capacity / 4).max(1);
    let post_class = post_residual / q; // 0..=3

    // Dead space: residual too small for typical items (1..=100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Modulo/harmonic coupling: if next item exactly fills post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Harmonic class of the resulting residual.
            let next_class = next_post / q;
            score -= (3 - next_class as i32) as f64 * 10.0;
            if next_post < 10 {
                score += 25.0; // creates dead space for next item
            }
        } else {
            // Next item cannot use this bin's residual anyway; slight penalty
            // for wasting space that could serve smaller future items.
            score += 5.0;
        }
    }

    // New-bin candidate: only open a new bin if existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { mean_residual } else { 0.0 };
        // Prefer new bin when all open residuals are small/dead.
        if mean_residual < 25.0 {
            score -= 70.0;
        } else {
            score += mean_residual * 1.5;
        }
        // Early in stream, slightly discourage hoarding bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
        let _ = frag;
    }

    // Penalize bins whose residual diverges from mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold bonus: residual in [25,50) is a "half-ish" class,
    // still useful; residual in [10,25) is marginal.
    match post_class {
        0 => score += 30.0,   // < 25: near-dead
        1 => score += 10.0,   // 25..50
        2 => score -= 5.0,    // 50..75
        _ => score -= 10.0,   // 75..100
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible
    // item size (1) are never truly dead, but tiny residuals relative to
    // typical item sizes are hard to fill. Penalize the "unusable band":
    // post_residual in (0, 10) is dead space for streams with min size 10;
    // for unknown distributions treat post_residual < item_size/3 as risky.
    let dead_threshold = (item_size / 3).max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the lookahead item could exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the lookahead cannot fit in the post-residual gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64;
    score -= pressure * 0.8;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large or existing bins fit badly.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items justify a fresh bin; small items should use existing space.
        score += (1.0 - fill_ratio) * 30.0;
        // If other bins can fit the item, discourage opening a new one
        // unless the fit there is terrible.
        if fitting_bins_count > 0 {
            score += 18.0;
        }
    }

    // Mean-residual coupling: when mean residual across open bins is high,
    // there is plenty of slack; prefer bins below the mean (tighter fits).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early in the stream, slightly favor opening bins to build diversity
    // of residual sizes for later items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space, weighted by how tight the fit is.
    score += 2.0 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // 2-step lookahead: reward exact/near match between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless residual elsewhere is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if lookahead would perfectly fill a fresh bin, mild discount.
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) == next_item_size {
            score -= 70.0;
        }
    }

    // Prefer filling bins that are already below average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Slight preference for keeping few open bins as the stream progresses.
    score += (open_bins_count as f64) * 0.3 * (step_index as f64 / total_items.max(1) as f64);

    // Small bonus for tight fits (small post_residual relative to item).
    score -= 10.0 / (1.0 + post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer minimal post-residual (tight fit), non-linearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tight * tight;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize dead space that likely can't fit a future item (items >= 1,
    // but typical sizes are larger): residual below half of capacity is risky.
    if post_residual < bin_capacity / 4 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 8.0;
        }
    } else {
        // Last item of the stream: prefer fullest bin.
        score -= 50.0;
    }

    // Prefer filling bins that are already relatively full compared to the mean.
    let fullness = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 20.0 * fullness;

    // If many bins are open, encourage consolidation into existing bins
    // rather than opening new ones.
    if open_bins_count > 3 {
        score += 12.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight option exists; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0 + 40.0 * progress;
        // Large items benefit from a fresh bin more often.
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        // If the mean residual across open bins is small, existing bins are
        // nearly full, so a new bin is less wasteful.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Mild time-horizon coupling: early in the stream, be more conservative
    // about creating small post-residuals (long future to fill them); late in
    // the stream, waste matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 18.0 * tight * (1.0 - progress);

    // Prefer bins whose residual is close to the item (minimal overshoot).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 10.0 * (gap / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual weighted more).
    // Late: post_residual less costly, favor consolidation.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) * 8.0
             + norm_pr * progress * 2.0;
    score += poly * cap;

    // Reward nearly-full bins (small post residual) with smooth falloff.
    let tight = (1.0 - norm_pr).powi(4);
    score -= 10.0 * tight;

    // Penalize last-chance bin waste: if this is the only fitting bin,
    // leaving large post_residual wastes its unique capacity.
    if fitting_bins_count == 1 {
        score += 6.0 * norm_pr * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0;
    }
    // If next item is large and won't fit here, slight penalty for hoarding space.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 2.0 * norm_pr;
    }

    // Mild bias toward bins with smaller residuals relative to mean (compactness).
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: discourage opening a new bin when good fits exist,
    // but allow it late in the stream or when residuals are all tiny.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: dead space below a threshold is strongly penalized
    // in a non-linear (harmonic) way.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fit
    } else {
        // Harmonic penalty: smaller residual classes get bigger discounts.
        let cls = post_residual / 10; // integer division: 0..=9 residual classes
        score -= (10 - cls as i32) as f64 * 1.5;
    }

    // Penalize residual that cannot fit the smallest plausible item (1..100 stream):
    // dead space is only useful if it can host a future item.
    if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this bin is very valuable (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty if we waste space.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (would leave little waste) or no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; discount when item is huge.
        score += 30.0 - fill_frac * 25.0;
        // If many bins already fit the item, opening a new bin is bad.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure toward bins with low residual (best-fit flavor) relative
    // to the mean residual across open bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Small tie-breaker: prefer more-filled bins as stream progresses.
    let used = (bin_capacity - bin_residual) as f64;
    score -= used * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
