    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }
    // Reward tight fits proportionally.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Deviation from mean residual: prefer bins close to mean to keep balance,
    // but slightly prefer filling bins below mean (larger residuals untouched).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: mild bias so a new empty bin is only chosen when
    // open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space penalty (nonlinear)
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward for tight double fit
            if post_residual - next_item_size <= 10 {
                score -= 15.0;
            }
        } else {
            // penalize wasting space that next item could have used elsewhere
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.2 * gap;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize spreading across many bins when mean residual is high
    score += 0.3 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits poorly
    if bin_residual == bin_capacity {
        // opening a new bin should be expensive unless nothing fits well
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score = 60.0 - 40.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for fuller bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
