    let pr = post_residual as f64;
    let t = progress;
    let poly = (1.0 - t) * (1.0 - t) * 0.5 + t * t * 1.5; // smooth weight growing with progress
    score += poly * (pr * pr) / (bin_capacity as f64 * bin_capacity as f64) * 20.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= poly * (item_size as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * t;
    }

    // Penalize bins with residuals far from the mean (wasted spread of dead space).
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: favor bins whose post_residual could fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * t;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions / 10 (items 1..100)
    let item_class = item_size / 10;               // 0..10
    let post_class = post_residual / 10;           // harmonic class of leftover

    // Reward tight fits: residual in the same low class is good.
    // Perfect fit gets a large subtraction.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Prefer small post_residual classes (fewer dead-space deciles)
        score -= (10 - post_class.min(10)) as f64 * 4.0;
    }

    // Penalize awkward leftovers: post_residual in 1..10 (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Leftovers that no typical item (>=1) can ever pair with except tiny ones
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fit quality
        let look = post_residual - next_item_size;
        if look == 0 {
            score -= 60.0;
        } else if look < 10 {
            score -= 25.0;
        } else {
            score -= 12.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover becomes dead space
        score += 8.0;
    }

    // Last usable bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity equal to residual
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its whole residual is "unused" potential
        score += 20.0;
        // opening a new bin is bad if many bins are open (fragmentation)
        score += open_bins_count as f64 * 0.5;
        // but attractive if no open bin fits well: if this is the only candidate
        // fitting_bins_count includes the new bin; if ==1, we must open anyway
        if fitting_bins_count == 1 {
            score -= 500.0;
        }
        // If the current item is large (harmonic class >= 7), fresh bins are fine
        if item_class >= 7 {
            score -= 15.0;
        }
        // Avoid opening new bins early in the stream when mean residual is high
        if mean_residual > (item_size as f64) {
            score += 25.0;
        }
    } else {
        // Reward using existing bins: scale with how much residual we consume
        score -= (item_size as f64) * 0.5;
        // Encourage filling bins with high residual relative to mean (balance)
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Stream progression: later in stream, prefer tighter packing (lower waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Modulo harmonic tiebreak on post_residual: multiples of 10 are cleaner
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else {
        score += (10 - (post_residual % 10)) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below the mean (consolidate fragmented space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., post_residual of a fresh bin is large and gaps elsewhere are bad).
    if bin_residual == bin_capacity {
        score += 18.0; // base cost of opening a new bin
        if fitting_bins_count == 1 {
            score -= 30.0; // no real alternative -> open it
        }
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 20.0; // huge items deserve a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: prefer bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving residual smaller than the smallest plausible next item (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 80.0;
        }
    }

    // Compare against mean residual: favor bins tighter than average (good fits),
    // penalize bins far looser than average only mildly (avoid wasting big residual bins on small items).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or the fit into open bins is bad (large post_residual with small next item).
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) / bin_capacity as f64;
        score = 60.0 + 100.0 * bad_fit;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 50.0; // a fresh bin wastes the chance to chain
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > bin_residual {
            // Next item won't fit this bin anyway; a large residual is wasted here.
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a bin is costly unless open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64);
        // Prefer new bin when existing residuals are large and fragmented, or early stream.
        score += 30.0 - 10.0 * pressure - 15.0 * (1.0 - progress);
    }

    // Mild preference for filling bins with larger residuals relative to mean.
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward tight fits: non-linear decay of residual value
    let tightness = 1.0 - (post / cap);
    score -= 45.0 * tightness.powi(3);

    // Non-linear coupling of residual with stream progress:
    // late in stream, larger leftovers are more costly (less time to fill them)
    let progress_coupling = (post / cap) * (0.5 + 0.5 * progress * progress);
    score += 30.0 * progress_coupling;

    // Dead-space penalty: residuals too small to hold even the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chain)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_fit = 1.0 - ((post - nxt) / cap).abs();
            score -= 20.0 * chain_fit.powi(2);
        } else {
            // penalize if this placement strands a large next item
            score += 12.0 * ((nxt - post) / cap).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins have plenty of mean residual space
    if bin_residual == bin_capacity {
        let mean_pull = (mean_residual / cap).clamp(0.0, 1.0);
        score += 55.0 + 60.0 * (1.0 - progress) + 40.0 * mean_pull;
        // but relax penalty slightly if item is large relative to mean residual
        let large_item = (item_size as f64 / cap).max(0.0);
        score -= 45.0 * large_item * mean_pull;
    }

    // Slight preference for bins with residuals close to the item (best-fit baseline)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10
    let post = post_residual;
    let class = post % 10;
    // Dead-space penalty: residuals that are small but not zero are bad
    if post > 0 && post < 10 {
        score += 15.0;
    }
    // Perfect fits are golden
    if post == 0 {
        score -= 40.0;
    }
    // Harmonic bonus: post_residual divisible by 10 leaves reusable chunks
    if class == 0 && post > 0 {
        score -= 6.0;
    }
    // Class coupling with next item: exact match of post_residual to next_item_size
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / (post as f64).max(1.0);
            score -= 10.0 * fill;
            // harmonic class match modulo 10
            if next_item_size % 10 == class {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize slightly unless residual is large
            score += 3.0;
        }
    }

    // Capacity fraction thresholds on bin_residual
    let residual_frac = bin_residual as f64 / cap;
    if residual_frac < 0.2 {
        score += 8.0; // nearly full bin, fragile
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // prefer new bin when mean residual is low (bins nearly full) or early with few bins
        score = 55.0 - 40.0 * fragmentation - 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mean residual coupling: penalize bins far above mean residual (keep bins balanced)
    let dev = post as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // next item (small gap) are highly wasteful -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize near-miss: gap just below next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 10.0 + 25.0 * (open_bins_count as f64 / 8.0).min(2.0) + 10.0 * progress;
        score += pressure;
        // New bin is acceptable if the item is large and would otherwise
        // create big dead space elsewhere.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild tie-break: prefer bins tighter than the average residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer filling fuller bins (lower post_residual already does this;
    // add slight nonlinearity for very full placements).
    if post_residual as f64 <= 0.1 * bin_capacity as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1e-9 {
            score -= 25.0; // exact refill: excellent
        } else if nxt <= post_residual as f64 {
            let fill_frac = nxt / post_residual as f64;
            score -= 12.0 * fill_frac; // next item fits well here
        } else {
            // next item won't fit: penalize wasted residual proportional to gap
            let gap = nxt - post_residual as f64;
            score += 6.0 * (gap / cap);
        }
    }

    // Compare residual against mean residual across open bins.
    score -= 4.0 * ((post_residual as f64) - mean_residual) / cap;

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when open bins are plentiful, early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 3.0; // fresh bin still has full lookahead flexibility though
            score -= 5.0;
        }
    }

    // Slight penalty for very small dead space that is hard to fill (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to item size.
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Penalize dead space that cannot hold a typical next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Lookahead synergy: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            25.0
        };
        score -= 8.0 * (-gap / 10.0).exp();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or full-ish.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is cheap early or when mean residual is large (fragmented).
        score += 15.0 + 25.0 * fragmentation - 20.0 * progress;
        // If a perfect fit exists elsewhere, discourage new bin.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for wasting large residuals on small items.
    if (item_size as f64) < 0.35 * bin_residual as f64 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear polynomial shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks at x=0.5, vanishes at edges
    score -= 40.0 * poly * (0.5 + t);

    // Dead-space penalty grows with progress (less time to reuse small gaps)
    score += (x * x * x) * cap * (0.2 + 1.5 * t);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 25.0 * t);

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - (next_item_size as f64 / pr).powi(2)) * (0.4 + 0.6 * t);
    } else if next_item_size > 0 {
        // post residual too small for next item: penalize wasted exactness
        score += 5.0 * (1.0 - t) * (pr / cap);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * t;
    }

    // Many open bins: prefer consolidating into bins with large residuals
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += openness * x * 10.0;

    // Prefer bins with residual above the mean (keeps spread balanced)
    score += 3.0 * ((pr as f64) - mean_residual) / cap;

    // New-bin candidate: neutral-ish baseline, penalized mildly so it's
    // chosen only when open bins would leave very bad fits
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and integer-division tiers
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    let tier = (pr / 10) as f64; // integer division: number of full 10-slots left

    // Penalize awkward residues (dead space not divisible into small-item slots)
    score += residue_class * 0.8;

    // Reward post-residuals that sit exactly on harmonic boundaries (multiples of 10/20)
    if pr % 10 == 0 {
        score -= 6.0;
        if pr % 20 == 0 {
            score -= 4.0;
        }
    }

    // Coupling with next item: perfect lookahead fit is a jackpot
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward if next item also lands on a harmonic boundary after placement
        let nn = pr - next_item_size;
        if nn % 10 == 0 {
            score -= 8.0;
        }
        score -= (nn % 10) as f64 * 0.5;
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot fit here: penalize proportionally to wasted capacity
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 30.0;
    }

    // Small residual dead-space penalty scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr > 0 && pr < 10 {
        score += (10.0 - pr as f64) * (1.0 + progress);
    }

    // Mild preference for keeping mean residual balanced
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // Slight bias toward existing bins over opening new ones early in the stream
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        // Dead space = residual too small to fit even the smallest plausible item (1..=100 range).
        // Treat gaps < 10 as near-wasted, gaps < 20 as partially wasted.
        if post_residual < 10 {
            score += 30.0; // fully dead gap
        } else if post_residual < 20 {
            score += 12.0; // mostly dead gap
        } else if post_residual < 35 {
            score += 4.0; // marginal gap
        }
        // Non-linear coupling: squared dead-space pressure scaled down.
        let pr = post_residual as f64;
        score += 200.0 / (pr + 5.0) - 4.0;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * bin_pressure * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave a tempting gap.
        score += 2.0;
    }

    // Prefer bins whose residual is close to item_size (tight fit measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Mild preference for filling fuller bins first.
    score -= 0.02 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use
        score += 0.5 * (post_residual as f64 - (next_item_size as f64).min(post_residual as f64));
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.6 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage leaving tiny unusable residuals (< 10) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for filling existing bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: prefer tight fits.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness;

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Residual below minimum item size is dead space.
        score += 15.0;
    }

    // Lookahead: if next item fits the post-residual, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // If next item nearly fits (within 10), slight bonus.
    else if next_item_size > 0 && next_item_size <= post_residual + 10 {
        score -= 4.0;
    }
    // If next item is large and won't fit anywhere after this placement, avoid wasting.
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when good open bins exist; but allow it when
    // open bins are crowded (low mean residual) and this is a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // A new bin is attractive when mean residual of open bins is small
        // relative to the item (i.e. item barely fits anywhere).
        let crowded = mean_residual / (bin_capacity as f64);
        score += 25.0 * crowded;          // penalize new bin when open bins are roomy
        score -= 10.0 * (1.0 - crowded);  // reward new bin when open bins are crowded
        // Slightly discourage new bins early in the stream to keep bin count low.
        score += 8.0 * (1.0 - progress);
        // If item fits very snugly in the empty bin (item close to capacity),
        // a new bin is natural.
        if item_size as f64 / (bin_capacity as f64) > 0.8 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many open bins (fragmentation control).
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows super-linearly with residual
    // and is modulated by stream progress (tighter packing later in the stream).
    let norm_pr = pr / cap;
    let progress_coupling = norm_pr * norm_pr * (0.5 + progress);
    score += 20.0 * progress_coupling;

    // Fit quality: reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness * (1.0 + progress);

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * (1.0 - pr / cap) * (1.0 + 0.5 * progress);
        } else {
            // reward residual that can still host the next item
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for filling already-open bins vs. opening new ones
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress;
    } else {
        score -= 1.0 + 0.5 * (open_bins_count.min(20) as f64) * 0.1;
    }

    // Alignment with mean residual: prefer bins near the average fill state
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size class via integer division
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Penalize large dead space, with a superlinear kick for tiny residuals
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64).sqrt();
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Modulo-style harmony: does post_residual pair well with next item?
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item exactly fills this bin
        } else if gap > 0 && gap < 10 {
            score -= 12.0; // near-perfect chain
        } else if gap < 0 {
            score += 6.0; // next item won't fit here: chain broken
        }
        // harmonic class match: post_residual mod 10 compatible with next class
        let pr_class = post_residual / 10;
        if pr_class == next_class as u32 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Fraction of capacity wasted relative to capacity
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 20.0;

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive for big items or late stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > cap * 0.6;
        if big_item || progress > 0.7 || open_bins_count > 12 {
            score -= 5.0;
        } else {
            score += 12.0; // prefer reusing open bins early
        }
    }

    // Prefer tighter (smaller-residual) bins among open ones
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward bins whose residual exactly matches the next item (lookahead chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // next item would create a dead gap here
        }
    }

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins tighter than the mean residual (well-packed bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten packing further (less slack for waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // perfect chain: post_residual == next_item_size -> big reward
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot follow: penalize proportionally to wasted potential
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual) relative to mean residual
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;
    if (post_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strong penalty for opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for keeping fewer open bins
    score += 0.5 * open_bins_count as f64;

    // Discourage opening a new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

