        }
        // If next item won't fit here anyway, mild bonus for keeping space flexible.
        if next_item_size > post_residual {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative with new bins; late, allow more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later.
        score += 30.0 * (1.0 - progress) + 5.0;
        // Opening a new bin is more attractive when many bins already open and crowded.
        score -= 0.5 * open_bins_count as f64 * progress;
        // If mean residual across open bins is small, opening a bin is reasonable.
        score -= mean_residual * 0.3;
    } else {
        // Favor filling existing bins more when few bins are open.
        score -= 3.0 / (1.0 + open_bins_count as f64);
    }

    // Global balance: prefer bins whose residual is below the mean (tighter bins first).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild preference for larger items going into fuller bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
