    let norm_pr = pr / cap;
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: cubic decay of penalty as post_residual shrinks.
    score -= 15.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: if the next item fits into the post-residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
