    score += 0.5 * (open_bins_count as f64) * norm_pr;

    // Deviation from mean residual: prefer bins with less residual than average (fuller bins).
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals divisible by 10 are
    // "clean" slots (easy to fill later), penalize them less; odd/prime-ish
    // residues create dead space, penalize more.
    let class = (post_residual % 10) as f64;
    score += (5.0 - class).abs() * 0.8;

    // Capacity fraction coupling: reward tight fills (post_residual small
    // relative to capacity) with a non-linear squash.
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_frac * fill_frac * 12.0;

    // Lookahead harmonic check: if next item exactly divides post_residual
    // into a small remainder, this bin is a perfect two-step chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual % next_item_size;
        if chain < 5 {
            score -= 6.0;
        } else if chain > next_item_size / 2 {
            score += 2.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 10.0 / pressure;
        // Early in stream, allow more bin openings.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 4.0;
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is a laggard bin; using it consolidates waste.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev.min(20.0) * 0.3;
    }

    // Integer division threshold: post_residual in [10, 25] is a dead zone
    // (too small for most items), penalize proportionally.
    if post_residual >= 10 && post_residual <= 25 {
        score += (25 - post_residual) as f64 * 0.4;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

