pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Strongly favor exact / near-exact fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Dead-space penalty: small residual that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: only this bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 80.0;
        }
        // Penalize leaving residual just below next item size (unusable for it).
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Mild base preference against opening new bins.
        score += 30.0;
        // But if many open bins and current fit is loose, new bin becomes attractive.
        if post_residual >= 20 && open_bins_count > 2 {
            score -= 45.0;
        }
        // Early in stream: opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 60.0;
        }
    } else {
        // Slight reward for using already-open bins to consolidate.
        score -= 5.0;
    }

    // Global balance: prefer bins whose residual deviates favorably from mean.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer filling fuller bins when many bins are open (bin-count pressure).
    score -= 0.5 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * post / cap) - 0.3 * (post / cap).powi(2) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger waste is tolerable; later, waste becomes more costly.
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Penalize bins whose residual deviates from the mean residual
    // (prefer bins that are either much fuller or much emptier than average,
    //  avoiding fragmentation of mid-full bins).
    let dev = (residual - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * 0.01 - 4.0 * dev * cap * 0.01;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 + 8.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover unusability.
        score += 3.0 * (post / cap);
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is chosen
    // only when open bins offer poor fits.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = cap * 0.9 + 5.0 * crowd - 15.0 * progress;
        // If no open bin can fit, the new bin is the only choice anyway.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-band classification
    let q = item_size / 25; // 0..3 harmonic class
    let pq = post_residual / 25; // post-residual quarter class

    // Reward tight fits: post_residual in low harmonic class
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Penalize dead space by class: small post-residual classes are reusable
        score += pq as f64 * 8.0;
    }

    // Modulo arithmetic on post_residual: values matching common item sizes are reusable
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 12.0; // divisible by 10 -> likely to fit future items
    } else if mod_class > 5 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item won't fit here; slight penalty for blocking lookahead
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps balance)
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - res_f) * 0.1;
    }

    // New-bin candidate: penalize opening a bin unless existing fit is very poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only opened for large items / bad fits
        score += 120.0;
        // Large items are hard to place later; new bin more acceptable
        score -= q as f64 * 15.0;
        // Early in stream, opening bins is cheaper (more items to come to fill)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If many bins already open, discourage proliferation
        score += open_bins_count as f64 * 2.0;
        // If no other bin fits, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Stream-progress coupling: late in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (100.0 - post_residual.min(100)) as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    let dead_threshold: u32 = 10; // minimum item size is 1..100 range; gaps below ~10 are near-dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 8.0;

    // Penalize large wasted residual left behind when the gap can't fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented or full.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Reward opening a fresh bin when mean residual of open bins is small (poor fits ahead)
        score -= mean_residual * 0.8 + fragmentation * 0.3 + progress * 10.0;
        // Penalize opening new bins when existing bins fit well
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 10.0;
        }
    }

    // Mild lookahead: favor bins whose leftover could still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slightly superlinear.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Also reward leaving at least room for the next item.
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Dead space relative to lookahead item: penalize waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0 / (1.0 + post_residual as f64);
    }

    // Compare against mean residual: bins tighter than average are precious, use them.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 3.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 20.0 + open_f * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin still useful for lookahead
        }
    }

    // Early stream: be more willing to open bins (future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits strongly; later, tolerate larger post_residual.
    let mut score = pr * (1.0 + 0.8 * progress) + 60.0 * pr_norm * pr_norm * (1.0 - progress);

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 25.0 * (ns - pr) / cap;
        } else {
            score -= 10.0 * (1.0 - ((pr - ns) / cap).min(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when mean residual across open bins is still large.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 0.5 * mean_residual;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: small gaps are dead space.
    let gap = post_residual;
    if gap == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if gap <= 10 {
        score -= 25.0; // nearly full, small dead space
    } else if gap <= 20 {
        score -= 8.0;
    } else {
        // Penalize large leftover gaps, scaled by how unusable they are
        score += (gap as f64 - 20.0) * 0.35;
    }

    // Modulo-class logic on post_residual: gaps that pair with common item
    // sizes (multiples of 10 or common halves) are more reusable.
    let gap_mod10 = gap % 10;
    if gap_mod10 == 0 {
        score -= 6.0; // aligned with decade-sized items
    } else if gap_mod10 <= 3 {
        score -= 2.0;
    } else {
        score += gap_mod10 as f64 * 0.4;
    }

    // Next-item lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && gap >= next_item_size {
        score -= 10.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && gap > 0 && gap < next_item_size {
        // this bin becomes dead after placement unless gap is tiny
        if gap > 20 { score += 8.0; }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty: prefer existing bins generally
        score += 15.0;
        // if mean residual across open bins is large, opening a new bin is wasteful
        score += mean_residual * 0.5;
        // but if open bins are nearly full, a new bin is fine
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // late in the stream, consolidating is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Slight preference to spread load when many bins are open and mean residual high
    if open_bins_count > 4 && mean_residual > 40.0 && !is_new_bin {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact/tight fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Reward bins whose residual was already small (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: favor bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage proliferation of bins mid-stream,
    // but allow new bins when many bins are already congested.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Penalize leaving a residual that only very large items could use.
    if post_residual >= 70 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact / near-exact fit: big reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let gap = (post_residual as f64 - nr).abs();
        if gap <= 1.0 {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if post_residual as f64 >= nr {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a stranded gap
            score += 4.0 * (nr - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean
    // (keeps big-capacity bins available for big items)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless current item is large relative to
    // available fits or there are few open bins (fresh-bin candidate case)
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0
            - 0.5 * (open_bins_count as f64)
            - 20.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_penalty;
        // If lookahead suggests next item is large, fresh bin more attractive
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Late-stream bias: consolidate more aggressively toward the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small-but-unusable dead space (< 10 is dead for all items).
    if post_residual < 10 && post_residual > 0 {
        score -= 15.0; // killing a bin completely is fine
    } else if post_residual < 20 {
        score += 8.0; // risky sliver
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the post residual, that's a
    // bonus (chain packing); if next item would leave this residual wasted,
    // mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size > bin_residual {
            score += 5.0;
        }
    }

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post residual) or current bins are very fragmented.
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        // Default neutral-ish score: new bin keeps capacity 100.
        let mut new_bin_score = 55.0 + 0.3 * open_bins_count as f64;
        // Early in stream: slightly discourage hoarding bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_score += 0.6 * avg_fragmentation * 100.0;
        // If this item is large, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 12.0;
        }
        return new_bin_score;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize leaving big residuals around).
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Late in stream: be more greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = pr;

    // Smooth polynomial coupling: small residuals get extra reward,
    // amplified as the stream progresses (later = more waste-averse)
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr); // ~1 for tight fits
    let progress_amp = 0.5 + 2.5 * progress * progress; // grows quadratically with progress
    score -= 40.0 * tightness * progress_amp;

    // Penalize residual that is small enough to be "dead space" but not zero:
    // dead space peaks when norm_pr is small but nonzero (e.g. < next item size)
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += 30.0 * dead;

    // Reward using the bin when it's the last fitting bin (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for bins far below mean residual (keeps balance),
    // scaled by number of open bins
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Encourage compacting large items early: reward large item share
    let item_share = item_size as f64 / cap;
    score -= 15.0 * item_share * item_share * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless item is large or stream is late
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln().max(0.0);
        score += 20.0 + 30.0 * (1.0 - item_share) * (1.0 - progress) + 10.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Penalize dead space: post_residual below the minimum item size is wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Harmonic classes: modulo-10 residue classes of post_residual.
    // Residues that pair well with common item sizes (multiples of 5/10) are favored.
    let r = post_residual % 10;
    match r {
        0 => score -= 12.0,
        5 => score -= 8.0,
        1 | 9 => score += 4.0,
        2 | 8 => score += 2.0,
        _ => {}
    }

    // Integer-division thresholds: how many "typical" items still fit.
    let slots = post_residual / 10;
    if slots == 0 && post_residual > 0 {
        score += 15.0; // bin becomes unusable
    } else if slots >= 5 {
        score += 3.0; // plenty of room; less urgency to fill
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 50.0;
        } else if diff < 10 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - diff as f64 / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; if this bin would be stranded, penalize mildly.
        score += 6.0;
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate logic: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Justify opening when: many open bins already fragmented, or item is large
        // and would leave an awkward remainder in any existing bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count as f64 > mean_residual / 10.0 {
            score -= 10.0; // bins are quite full on average; fresh capacity reasonable
        }
        if item_size >= 60 && post_residual < 20 {
            score -= 15.0; // big item with tiny leftover: prefer fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size && progress < 0.5 {
            score -= 8.0; // stream of large items early: keep fresh bins
        }
    }

    // Slight preference to fill bins with lower residual among comparable options.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: gaps that can never fit a future item (min size 1..~10)
    // are pure waste; penalize small nonzero residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Exact match with lookahead item: reserve-free placement is great.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // If the lookahead item cannot fit here but could fit elsewhere, mild penalty
    // for consuming space the next item might need.
    if next_item_size > 0 && post_residual < next_item_size as u32 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure against proliferation of open bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it attractive only when current fit is poor
    // (large post_residual wasted space relative to capacity) or no good fit exists.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, slightly above good fits.
        score = 55.0 + open_bins_count as f64 * 0.3;
        // If lookahead item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    // Mild tie-breaking: prefer bins with lower residual (tighter fit) via mean alignment.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Item still leaves room for the next item: mild reward scaled by leftover
        score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Kills the next item's fit: penalize dead space
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins are usually preferred
        score += 25.0;
        // But if current bin fit is bad (large post_residual mismatch) and few bins fit, relax penalty
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 18.0 + 10.0 * progress;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    let pr = post_residual as f64;
    score -= 40.0 * (-pr / 15.0).exp();

    // Dead space: post_residual too small for any future item is fine (bin "closed"),
    // but mid-range leftover that nothing can use is wasteful.
    if post_residual < 10 && post_residual > 0 {
        score -= 10.0; // bin effectively sealed: good
    }

    // Lookahead: if the next item fits exactly-ish into post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() <= 3.0 {
            score -= 25.0; // perfect chain fit
        } else if pr >= nxt {
            score -= 8.0; // next item can also land here
        } else if nxt > pr && pr < 10.0 {
            score -= 5.0; // sealing now is fine since next item wouldn't fit anyway
        } else {
            score += 6.0; // leftover too big to seal, too small for next item
        }
    }

    // New-bin candidate: neutral-ish baseline; opening a fresh bin costs capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when existing fits are poor (large post_residual)
        // or when only one bin fits (risky to burn it if fit is bad).
        let poor_fit = pr > 40.0;
        let last_chance_bad = fitting_bins_count == 1 && pr > 25.0;
        if poor_fit || last_chance_bad {
            score -= 15.0;
        } else {
            score += 12.0; // good fits exist: keep using open bins
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state coupling: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 && (mean_residual as f64) < 30.0 {
        score += 5.0; // discourage fragmenting space further
    }

    // Time horizon: late in the stream, pack tighter (avoid leaving semi-empty bins).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * t * (pr / bin_capacity as f64);

    // Slight preference for filling bins with larger residual less when many bins open.
    score += 0.05 * open_bins_count as f64 * (pr / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fills (low post residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (quadratic + cubic terms)
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post_norm * (40.0 * p2 + 60.0 * p3) * cap * 0.1;

    // Reward near-perfect fits with smooth exponential decay
    score -= 15.0 * (-(post_norm * post_norm) * 25.0).exp();

    // Penalize bins with residuals below the smallest plausible item (dead space)
    let dead = (10.0 - post).max(0.0);
    score += dead * dead * (0.05 + 0.15 * progress);

    // Lookahead: reward if next item can fit in post_residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (0.5 + 0.5 * progress);
        // penalize wasting space that is too small for the next item
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.1 * gap * (1.0 + progress);
    }

    // Last-chance bin bonus: strongly favor the single fitting bin to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.3 + 0.7 * progress);
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * post_norm;

    // New-bin candidate: make empty bins less attractive unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.5;
        if poor_fit {
            score -= 5.0 * (1.0 - progress);
        } else {
            score += 6.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);

    // Penalize residuals in "dead" classes (too small to fit typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0; // unusable sliver
    } else if class == 0 {
        score -= 15.0; // perfectly divisible residual is reusable
    } else if post_residual < quarter {
        score += 8.0; // sub-quarter residual is low-value
    }

    // Reward near-perfect fits (harmonic closure: post_residual in {0, small}).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 35.0;
        } else if next_post < 10 {
            score += 5.0; // chains into a dead residual
        } else {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here; penalize proportionally to its size class.
        score += (next_item_size / 20) as f64 * 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Progress scaling: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: prefer reusing bins unless residual is very fragmented.
    if bin_residual == bin_capacity {
        // New bin is attractive only if open bins are highly fragmented or item huge.
        let fragmented = mean_residual < (bin_capacity as f64) * 0.25 && open_bins_count > 2;
        if fragmented || item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        } else {
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: post_residual gaps that are too small to ever
    // hold a realistic item (min item size 1..100, but small gaps < 10 are dead)
    // are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += 40.0 * (10.0 - post) / 10.0;
    }

    // Reward near-exact fits strongly.
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 5.0 {
        score -= 25.0;
    }

    // Prefer bins whose residual was tight relative to mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.5;

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt && post - nxt < 10.0 {
            score -= 15.0;
        }
        // Penalize leaving a gap that neither fits next item nor is dead.
        if post > 0.0 && post < nxt && post >= 10.0 {
            score += 8.0;
        }
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 25.0 + pressure * 2.0 + post * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly-full bins are excellent outcomes.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post-residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0; // next item leaves near-perfect fit too
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to lookahead item: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
        // Favor bins whose post-residual stays large enough for typical next items
        if post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    } else {
        score += (resid - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is huge
    // and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 120.0;
        if item_size >= 60 {
            score -= 60.0; // large items justify fresh bins more readily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 20.0; // keep room to pair items in the fresh bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let next_fits = next_item_size > 0 && (next_item_size as u32) <= post_residual;
        if !next_fits {
            score += dead * 0.9 + 4.0;
        } else {
            score -= 2.0;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    }
    // If next item would leave near-zero residual too, chain bonus.
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        if chain > 0 && chain <= 5 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation (fill existing bins).
    let open_f = open_bins_count as f64;
    score += open_f * 0.4;

    // Mean residual coupling: if this bin is tighter than average, prefer it.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.5;

    // Time horizon: early in the stream, be more selective (favor new bins for big items);
    // late in the stream, pack aggressively into open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 3.0 - t * 3.0;

    // New-bin candidate: only attractive when item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let tightness = fitting_bins_count as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 12.0 - item_frac * 22.0 - (tightness.min(3.0)) * 4.0 + (1.0 - t) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual (waste), with non-linear penalty on tiny residuals
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth interaction: residual usefulness decays with stream progress
    score -= 8.0 * (1.0 - progress) * norm_pr * (1.0 - norm_item);

    // Favor tight fits: post_residual close to zero relative to item size
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead: reward if next item can use post residual (smooth coupling)
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        let smooth = 1.0 / (1.0 + fit_gap * fit_gap / 25.0);
        score -= 10.0 * smooth * norm_next;
    }

    // Penalize when this bin is one of many fitting bins (prefer scarce fits)
    if fitting_bins_count > 0 {
        score += 4.0 * ((fitting_bins_count as f64).ln().max(0.0));
    }
    // Reward last-chance bin usage
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_item);
    }

    // Deviation from mean residual: prefer bins with less residual than mean
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure toward consolidating into fewer bins as stream ends
    score -= 3.0 * progress * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress);
        score -= 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of common
    // item sizes are more reusable. Reward small "harmonic" dead space.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fill
    } else if pr <= 10 {
        -20.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -5.0
    } else {
        3.0
    };
    score += harmonic_bonus;

    // Penalize mid-range residuals that are hard to fill (dead space zones).
    if pr > 30 && pr < 60 {
        score += 8.0;
    }

    // Exact fit of next item into post-residual is very valuable (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size && pr - next_item_size <= 10 {
            score -= 12.0;
        } else if pr < next_item_size && pr > 0 {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // fit is poor (large post_residual) and there are many open bins.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln() * 2.0 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (denser packing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Fractional capacity coupling: reward filling past half capacity.
    if bin_residual as f64 <= bin_capacity as f64 * 0.5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small shortfall), mildly penalize.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress) * 0.5;
    score += pressure;

    // Prefer bins with residual close to mean (keep residuals uniform, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: attractive only when the item is large and open bins are tight.
    if bin_residual == bin_capacity {
        let avg_open_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let tight = avg_open_fit < item_size as f64 + 8.0;
        if tight {
            score -= 20.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for filling fuller bins (smaller residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt).abs();
            score -= (bin_capacity as f64 / (1.0 + gap)) * 1.5;
            // exact match bonus
            if gap < 1.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize dead space
            score += nxt * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual near the mean (balanced packing)
    let post = post_residual as f64;
    let dev = (post - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably well
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= item_size {
            score += 5.0;
        }
    }

    // Tight fits are valuable
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space, especially if unusable by the next item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if next_fits {
            score -= dead * 0.6; // residual is reusable, mild reward
        } else {
            score += dead * 0.9; // dead space penalty
        }
    } else {
        score -= 25.0; // perfect closure is excellent
    }

    // Lookahead: reward bins whose post-residual matches the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: tight packing favored when bins are plentiful.
    let tightness = mean_residual / bin_capacity as f64;
    score -= tightness * (post_residual as f64) * 0.3;

    // Time horizon: early in stream, allow opening new bins (penalize new-bin
    // usage less); late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus discount that shrinks over time.
        score = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else if progress > 0.7 {
        score -= 5.0; // late stream: squeeze into existing bins
    }

    // Prefer filling bins that are already mostly full (small residual before).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic waste penalty on post-residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 120.0 * pr_norm * pr_norm * (0.5 + progress);

    // Smooth cubic coupling: late in stream, small residuals are less tolerable
    score += 40.0 * pr_norm * pr_norm * pr_norm * progress * progress;

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 25.0 * (1.0 - (pr - nx) / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64 * (1.0 - progress);
        // but if existing residuals are all bad fits, allow opening
        score -= 20.0 * (mean_residual / cap).min(1.0) * progress;
    }

    // Tie-break toward tighter fit relative to mean residual
    score -= (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space by harmonic class: small unusable slivers are bad.
        let r = post_residual;
        if r < 10 {
            score += 60.0; // unusable sliver (min item size 1..100 => still likely dead)
        } else if r <= 20 {
            score += 25.0;
        } else if r <= 50 {
            score += 8.0;
        }
        // Integer-division thresholds: reward residuals that are multiples of
        // common item classes (harmonic bins).
        if r % 10 == 0 { score -= 10.0; }
        if r % 25 == 0 { score -= 8.0; }
        if r % 20 == 0 { score -= 5.0; }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let rem_after_next = post_residual - next_item_size;
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
            if rem_after_next < 5 { score += 20.0; } // would create sliver
        } else {
            // next item won't fit here; mildly prefer leaving large residuals
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral-ish, but prefer it when open bins
    // would be badly fragmented and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // base new-bin score ~ half-full residual equivalent, adjusted
        score = bin_capacity as f64 * 0.5
            - 40.0 * (1.0 - progress)
            + 10.0 * open_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            score -= 20.0;
        }
        // discourage opening new bins when a decent fit exists
        if post_residual <= 15 && fitting_bins_count > 0 {
            score += 200.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 3.0 * (mean_residual - bin_residual as f64).max(0.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are "dead space" -> heavy penalty.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Reward tight fits (small relative waste).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Penalize bins whose residual is much larger than needed (wasteful use of big bins for small items)
    if item_size > 0 && post_residual as f64 > mean_residual * 1.5 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual != bin_capacity {
        score -= pressure.min(10.0);
    } else {
        // New-bin candidate: penalize unless it looks genuinely better.
        score += 5.0 + pressure * 0.5;
        // Opening a new bin is fine if item is large and would leave a useful gap elsewhere anyway.
        if item_size >= bin_capacity / 2 && open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent (chains two items).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap < dead_threshold {
            score -= 10.0;
        } else {
            score -= 3.0 * (1.0 - next_gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover -> leftover likely wasted.
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0;
        } else {
            // next item won't fit here; penalize leftover that is too small to be useful
            if post_residual < 10 {
                score += 50.0;
            }
            score += (post_residual as f64) * 0.5;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64) * 2.0;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Lookahead: reward leaving room for the next item, penalize leaving
    // a sliver the next item cannot use (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a placeable item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful when any
    // open bin can fit the item; encourage it only when fits are scarce
    // or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let bonus = 55.0 - 20.0 * scarcity - 30.0 * fragmentation - 8.0 * progress;
        score += bonus.max(-15.0).min(80.0);
    }

    // Mild penalty for leaving residuals too small for the smallest items.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: strongly favor small post residuals (non-linear).
    score -= 2.5 * (1.0 - pr / cap).powi(4) * cap * 0.1;

    // Penalize leaving dead space that can't fit typical future items.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 8.0 * dead * dead;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, waste is more costly; early, spread is fine.
    score += pr * progress * progress * 0.8;
    score -= pr * (1.0 - progress) * 0.15;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New empty bin candidate: penalize opening a new bin, more so when
    // open bins exist and mean residual is large; allow it early in stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        score -= 10.0 * (1.0 - progress);
        if mean_residual > next_item_size as f64 {
            score += 6.0;
        }
    }

    // Lookahead: reward leaving room exactly for the next item.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.6 * diff;
        if pr >= next_item_size as f64 {
            score -= 3.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.4 * (mean_residual - pr).max(0.0);
    score -= 0.2 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by large powers of 10/5
    // are more reusable (items often sized in multiples of 5/10).
    let pr = post_residual as u32;
    let mut class_bonus = 0.0;
    if pr % 10 == 0 { class_bonus += 6.0; }
    else if pr % 5 == 0 { class_bonus += 3.0; }
    if pr % 20 == 0 { class_bonus += 3.0; }
    if pr % 25 == 0 { class_bonus += 2.0; }
    score -= class_bonus;

    // Chain coupling: reward when the lookahead item fits exactly or nearly
    // into the post-residual (harmonic match on integer division).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            let fit_ratio = ni / (pr as f64 + 1.0);
            score -= 8.0 * fit_ratio;                       // tighter chain = better
            if pr % (next_item_size.max(1)) == 0 { score -= 5.0; } // exact divisor match
        } else {
            // post_residual too small for next item: dead space risk
            let gap = (next_item_size - pr.min(next_item_size)) as f64;
            score += 0.08 * gap;
        }
    }

    // Tight packing reward: near-perfect fills strongly favored.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 18.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.10 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate: only attractive when many open bins are fragmented
    // (high mean residual spread) or late in stream with poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = ((mean_residual - post_residual as f64).abs()) / cap;
        score += 25.0;                                    // base penalty: reuse bins
        score -= 15.0 * fragmentation;                    // fragmented state eases opening
        score -= 10.0 * progress;                         // late stream: consolidation matters less
        if open_bins_count == 0 { score -= 60.0; }        // must open
        if fitting_bins_count == 0 { score -= 30.0; }     // no alternative
    }

    // Mild preference for bins whose residual is close to the item (best-fit core).
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item (1)
    // are fine, but gaps that are tiny relative to typical items are dead space.
    // Penalize small nonzero post_residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Dead-space penalty grows sharply as gap shrinks below ~20.
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits generally: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin choice implicitly via its high residual).
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            // Next item cannot fit in leftover gap: gap is likely dead space.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a laggard bin — filling it consolidates waste.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.2;
    }

    // Early in stream, be slightly more willing to open new bins (spread items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover space
    // closely matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills this bin afterwards.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize leftover that is too small to ever be useful
            // (dead space), reward leftovers that can host the next item.
            if (post_residual as f64) < nxt {
                // dead space magnitude relative to next item
                score += 0.8 * (nxt - post_residual as f64);
            } else {
                // next item fits: reward tightness of the match
                score -= 0.5 * (post_residual as f64 - nxt).min(30.0);
            }
        }
        // Coupling with mean residual: prefer bins tighter than average
        score -= 0.3 * (mean_residual - post_residual as f64);
    } else {
        // Last item: minimize final leftover
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless few/no good alternatives.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += 15.0 + pressure + 0.1 * open_bins_count as f64;
    }

    // Prefer filling bins that are already mostly full (tight packing).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Early in the stream, be more willing to open bins for better structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight) * 12.0;

    // Penalize small unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with small residual overall (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual as f64 - post_residual as f64);

    // Many open bins: discourage opening new bins, encourage filling existing ones.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: penalize opening a fresh bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + progress * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic waste penalty with stream-progress coupling
    let mut score = x * x * (1.0 + 2.0 * progress) * cap;

    // Cubic dead-space term: strongly penalize very small residuals,
    // more aggressively as the stream progresses.
    score += (x * x * x) * cap * (0.5 + progress);

    // Interaction with mean residual: prefer bins whose post residual
    // deviates from the mean in a useful (smaller) direction.
    let mr = mean_residual / cap;
    score += (x - mr) * (x - mr) * cap * 0.3;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= (1.0 - (pr - ns) / cap) * 5.0;
        } else {
            score += (ns - pr) * 0.2;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // Slight preference to fill existing bins rather than open new ones,
    // weighted by progress.
    score -= (1.0 - x) * (1.0 + progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    // Residuals in (0, 10] are "dead space" -> heavy penalty; larger leftovers are reusable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if pr <= 5 {
        // Near-perfect fit.
        score -= 500.0;
    } else if pr < 10 {
        // Dead space: unusable for the minimum item size -> penalize heavily.
        score += 250.0;
    } else {
        // Harmonic class via integer division thresholds on post_residual.
        // Classes: [10,25), [25,50), [50,75), [75,100)
        let class = pr / 25; // 0..3
        // Reward larger usable classes; small-but-usable leftovers mildly penalized.
        match class {
            0 => score += 40.0,                 // awkward sliver
            1 => score -= 10.0,                 // decent
            2 => score -= 30.0,                 // good
            _ => score -= 50.0,                 // excellent leftover
        }
        // Fine-grained harmonic subdivision within class using modulo structure.
        let rem = pr % 25;
        // Residuals that are multiples of common item sizes (10, 20, 25, 50) are more
        // likely to be filled exactly by future items -> small reward.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }
        if rem == 0 { score -= 4.0; }
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 300.0;
        } else if next_item_size <= pr {
            // Next item fits: leftover after next placement determines quality.
            let post2 = pr - next_item_size;
            if post2 < 10 {
                score -= 120.0; // two-item near-perfect packing
            } else {
                score -= (post2 as f64).min(60.0) * 0.5;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty since the
            // residual may go to waste relative to the lookahead.
            score += 15.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 60.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (dead space).
    if fitting_bins_count == 1 {
        if pr >= 10 {
            score -= 200.0;
        } else {
            // Only bin fits but creates dead space; still mildly prefer it over a new bin.
            score -= 80.0;
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing reasonable bin; only open a new bin when
        // open bins are crowded or the current fit is bad.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (mean_residual / cap).max(0.01);
        let bad_fit = if pr < 10 && pr > 0 { 1.0 } else { 0.0 };
        score += 120.0
            - 40.0 * bad_fit
            + 30.0 * progress
            + (crowding * 0.05).min(60.0);
        // If mean residual across open bins is small, opening fresh is attractive.
        score -= (mean_residual / cap * 100.0).min(50.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor for this item
    // (item is large relative to mean residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        score = bin_capacity as f64 - 10.0 * desperation - 5.0 * (fitting_bins_count == 0) as i32 as f64;
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            // next item fits here too; reward tightness of the 2-chain
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit; penalize more if post_residual is awkwardly large dead space
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already below average (they're near-full; pack them first)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: only this bin can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a great 2-chain
    if bin_residual == bin_capacity {
        let new_bin_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            -5.0
        } else {
            10.0 + 5.0 * (open_bins_count as f64).sqrt()
        };
        score += new_bin_bonus;
    }

    // Late in the stream: close out bins tightly, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small unusable sliver is fine (already filled tightly)
    } else if post_residual > 0 {
        // reward residuals that could host common item sizes
        let usable = if post_residual >= 80 { 1.0 } else if post_residual >= 50 { 0.6 } else if post_residual >= 20 { 0.35 } else { 0.05 };
        score -= 20.0 * usable;
    }

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits in post_residual, bonus
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and mean residual is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        score += 45.0 * (1.0 - pressure) + 30.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative anyway
        }
    }

    // Mildly discourage fragmenting many open bins when item fits many bins
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Late-stream: prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with non-linear tightening
    let mut score = post * (1.0 + 0.8 * progress) + 12.0 * (post / cap).powi(2);

    // Dead-space penalty: residuals too small to fit any future item (>=1 assumed)
    if post > 0.0 && post < 1.0 {
        score += 100.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0 + 20.0 * progress;
    }

    // Last-chance bin: strong bonus to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 30.0 - 25.0 * fill_ratio * fill_ratio;
        // late in the stream, opening new bins is cheaper than fragmenting
        score -= 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead coupling: reward leaving room shaped like the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score += 6.0 * (diff / cap).powi(2);
        if post >= nxt {
            score -= 8.0;
        }
    }

    // Discourage spreading across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of capacity
    // fractions are more reusable. Classify post_residual by integer division
    // into bands of size 10.
    let band = post_residual / 10;
    let residue = post_residual % 10;

    // Reward post residuals that land in "harmonic" bands (0, 25, 50, 75 style
    // fractions of capacity) since future items are more likely to fill them.
    let harmonic_bonus = match band {
        0 => 12.0,
        2 => 6.0,
        5 => 10.0,
        7 => 5.0,
        9 => 8.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize small awkward residues (dead space that few items can use).
    if residue > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(8.0);
        } else {
            // Next item won't fit here: mild penalty scaled by overflow.
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.15;
        }
        // If next item exactly fills post residual, big reward.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is penalized more when
    // many bins are open and mean residual is large (waste).
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // But if the item is large relative to mean residual, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Prefer tighter fits generally: reward small post_residual relative to item.
    if item_size > 0 {
        score += (bin_residual - post_residual) as f64 * 0.0; // no-op, keep explicit
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 5.0;
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    score
}

