pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post_residual closely matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect 2-step fit: big bonus.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward small leftover gap.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted space.
            score += 0.25 * gap;
        }
    }

    // Perfect closure bonus: bin fully used.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness reward: small post_residual relative to capacity.
    score -= 0.3 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: prefer bins below mean residual (denser bins).
    score += 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are nearly saturated or fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual as f64 - item_size as f64) < mean_residual * 0.25;
        let crowded = fitting_bins_count == 1 && open_bins_count > 0 && mean_residual < 0.5 * bin_capacity as f64;
        if bad_fit || crowded {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    // Late in stream: consolidate harder, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a brand-new bin when open bins could fit.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 6.0 } else { 40.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += scarcity * (0.5 + progress);
    }

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * 15.0;

    // Perfect fill is golden.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving residual that is too small for typical future items
    // (dead space): residual below the smallest useful chunk.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins that are already below-average residual (more filled).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild pressure to keep the number of open bins low early on,
    // relax toward the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 40.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space (residual too small to be useful later)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 15.0 * (1.0 - (next_item_size as f64 / pr).min(1.0));
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for bins with residual near mean (balance load)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with
    // typical item sizes (small, divisible chunks) are "usable" classes.
    let r = post_residual;
    let class_bonus = match r {
        0 => 40.0,                    // perfect fit
        1..=5 => 22.0,                // near-perfect
        6..=15 => 10.0,               // fillable by small items
        16..=30 => 4.0,               // moderately usable
        31..=60 => 0.0,
        _ => -6.0,                    // large dead space risk
    };
    score -= class_bonus;

    // Modulo-10 harmonic structure: residuals divisible by 10 tend to be
    // reusable by common item sizes.
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 5 == 0 && r > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or nearly, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            let gap = r - next_item_size;
            score -= (20.0 - gap as f64).max(0.0) * 0.8;
        } else {
            // next item cannot fit here; slight penalty for wasting space
            score += 3.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large or all existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 30.0;
        // Large items are fine to start fresh bins with.
        new_bin_penalty -= (item_size as f64 - 50.0).max(0.0) * 0.6;
        // If mean residual across open bins is small, opening a bin is
        // more acceptable.
        new_bin_penalty -= (mean_residual / 10.0).min(15.0);
        // Late in the stream, prefer consolidating.
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    } else {
        // Prefer bins whose residual is close to the item (good fit).
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.05;
    }

    // Prefer reusing bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).min(20.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a future item (below the minimum plausible item size) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 50.0; // perfect fit bonus is handled by low post_residual already
    }

    // Penalize "unusable" gaps: post_residual that cannot fit the next item
    // nor a reasonably sized future item is dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight packing: quadratically favor small post residuals.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * tightness * tightness;

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; encourage consolidating into existing bins.
    score += 0.8 * open_bins_count as f64 * tightness;

    // If this is a brand-new empty bin candidate, penalize it unless the
    // item fits very poorly everywhere else (handled via other terms);
    // mild penalty keeps consolidation preferred.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But if the item is huge relative to mean residual, opening a fresh
        // bin may be better; relax the penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 12.0;
        }
    }

    // Slight progression adaptation: late in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item could fit here afterwards -> good chain
            score -= (40.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            // post_residual too small for next item: penalize dead space relative to gap
            score += 0.5 * (nxt - post_residual as f64).min(30.0);
        }
    }

    // Penalize leaving residuals that are awkwardly small (unusable) but nonzero
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the new bin is genuinely better (handled by base score comparison)
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter packing target)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to how snug.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a small useless remainder.
            if post_residual < next_item_size && post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when open bins have decent residuals.
        score += 20.0 + 40.0 * mean_tight;
        // As stream progresses, discourage proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Slight preference to fill bins with larger residuals when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Penalize creating residuals that no plausible item (1..100) pairs well with:
    // residuals in the "dead zone" (1..=9) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tight fits rewarded more strongly as the stream progresses.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that are too small to hold the smallest plausible item,
    // with a smooth quadratic dead-space penalty.
    let dead = (cap * 0.2 - post_residual as f64).max(0.0);
    score += 0.9 * dead * dead / cap;

    // Lookahead coupling: reward residuals that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly.
        score += 4.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.4 + progress);
    }

    // New empty bin candidate: baseline cost that grows with progress and
    // with how many bins are already open, discouraging unnecessary opens.
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mild preference for bins with residuals near the mean (balanced spread).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of small harmonics (5, 10, 20) remain reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fit is always best
    } else if pr % 20 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.5
    } else {
        2.0 // awkward residual
    };
    score += harmonic_bonus;

    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, more so late in the stream / many open bins
        score += 10.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 8.0; // an open bin exists that fits; avoid spreading
        }
        // If next item is huge and current item is small, fresh bin pairs well
        if next_item_size > 0 && next_item_size >= 50 && item_size <= 40 {
            score -= 6.0;
        }
    } else {
        // Reward tight fits in existing bins
        let fill = item_size as f64 / cap;
        score -= 6.0 * fill;

        // Lookahead pairing: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 20.0; // exact chain fit
            } else if next_item_size < pr && pr - next_item_size < 10 {
                score -= 8.0; // near-chain fit
            } else if next_item_size > pr {
                score += 1.5; // next item won't fit here anyway
            }
        }
    }

    // Mild preference for balancing residuals when many bins are open
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight late-stream conservatism: pack tighter as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1) can
    // use efficiently are heavily penalized. Small non-zero gaps are worse
    // than large gaps because they are "dead".
    let pr = post_residual as f64;
    if post_residual > 0 {
        // dead-space penalty grows sharply for small unusable gaps
        score += 12.0 * ((bin_capacity as f64 - pr) / bin_capacity as f64).powi(3);
        // perfect fit bonus
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when few bins are open (early stream) or last-chance fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as open bins grow and stream progresses
        score += 10.0 + 3.0 * open_bins_count as f64 + 15.0 * progress;
    } else {
        // reward using existing bins, especially when they are the only fit
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from mean residual
    // (filling below-average-residual bins consolidates space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: as the stream advances, tighten packing (waste less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward when the next item fits into post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer chains that leave small-but-useful slack afterwards.
            score -= 12.0 + 0.35 * next_item_size as f64 - 0.10 * slack;
        } else {
            // Penalize residuals that cannot host the next item (dead space risk),
            // scaled by how far off the fit is.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.08 * miss;
        }
        // Extra reward for a two-item exact closure (post_residual == next size).
        if next_item_size == post_residual {
            score -= 8.0;
        }
    }

    // Relative fit quality vs. mean residual of open bins.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        // Prefer bins whose post-residual is below average (tighter packing),
        // but don't over-punish when the bin becomes nearly full.
        score += 2.5 * (ratio - 1.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize large leftover dead space, more aggressively late in the stream.
    let dead_threshold = 10.0 + 20.0 * (1.0 - progress);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 3.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // New-bin candidate handling: only attractive early or when item barely fits anywhere.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && next_item_size > post_residual && item_size as f64 > bin_residual as f64 - item_size as f64);
        let early = progress < 0.25;
        if poor_fit_elsewhere || early || open_bins_count == 0 {
            score -= 6.0;
        } else {
            // Late stream: discourage wasting a fresh bin on a partial fill.
            score += 8.0 + 6.0 * progress;
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual grows penalty for wasted space.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit,
    // unless the item is huge relative to capacity (poor fit anywhere).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0 + 10.0 * open_bins_count as f64;
        }
        // Small penalty always, so near-perfect fits in open bins win.
        score += 5.0;
    }

    // Lookahead: penalize bins whose post-residual can't host the next item
    // if the next item would otherwise need a fresh bin anyway.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // leaves room for lookahead item
        } else if post_residual > 0 && next_item_size > bin_capacity / 2 {
            score += 4.0; // dead space likely unusable
        }
    }

    // Time horizon: early in stream, be more conservative with open bins
    // (keep residuals flexible); late in stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tight);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins to consolidate.
    if open_bins_count > 1 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // Prefer bins whose residual is close to item_size (perfect wrap).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // 0..1
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit * fit * (0.5 + t);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Penalize last-chance bins less when fit is decent
    if fitting_bins_count == 1 {
        score -= 6.0 * fit;
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64 * (1.0 - t);
    }

    // Pull toward mean residual to balance load
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" is the leftover space?
    // Residuals that are multiples of small divisors (5, 10, 20) are more reusable.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -5.0
    } else if pr < 10 {
        18.0 // dead space: too small for any item
    } else {
        0.0
    };
    score += class_penalty;

    // Integer-division threshold: residual bucket of 20 units.
    score += ((pr / 20) as f64) * 2.5;

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 45.0; // chain: this placement sets up a perfect next fit
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 15.0; // next fit leaves a clean residual
        } else if pr < next_item_size && pr > 0 {
            score += 8.0; // residual becomes unusable for the known next item
        }
        // Harmonic pair: item and next item sum near capacity fractions
        let sum = item_size + next_item_size;
        if bin_residual == sum {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 - fragmentation.min(25.0);
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // next item can never join this fresh bin anyway
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64 / bin_capacity as f64) * 10.0;

    // Reward tight fits generally (small post_residual relative to item).
    score -= 40.0 / (1.0 + post_residual as f64 / item_size.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful (below min item size 1
    // is impossible, so treat "hardly usable" gaps as worst-case dead space).
    let dead_threshold = 6.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear dead-space curve: mid-size leftovers are semi-usable, tiny ones are not.
    let pr = post_residual as f64;
    score += 0.15 * pr * pr / bin_capacity as f64;

    // Reward tight fits (small post_residual relative to item).
    if item_size > 0 {
        let tightness = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 20.0 * tightness * tightness;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close it is.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; opening a new bin
    // (residual == capacity) gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Slight late-stream conservatism: as the stream progresses, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the remainder -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in post_residual -> strong reward, scaled by tightness of fit.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 0.5;
    }
    // Next item does NOT fit: penalize leaving a residual that is small-but-unusable.
    else if next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0.0 {
            score += 50.0 * (pr / 100.0);
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.8;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 100.0 * tightness;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // Lookahead: if next item also fits in an empty bin alongside, mild bonus.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Mild penalty for very small dead space (fragmentation) vs moderate leftover.
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual dominates).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the emptiest (largest residual) to
        // keep near-full bins from stranding; slight penalty for hogging tight bins.
        score += (bin_capacity as f64 - bin_residual as f64) * 0.15;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else or open-bin residuals are large and
    // fragmented relative to the next item.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        let lookahead_waste = if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            0.5 * (next_item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        // Cost of opening a new bin grows with number of already open bins.
        score = bin_capacity as f64 * (0.6 + 0.05 * open_bins_count as f64)
            - 20.0 * poor_fit
            - 30.0 * lookahead_waste;
        // Early in the stream, opening bins is cheap (builds options).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead pairing: reward leaving a residual that exactly accommodates
    // the next item (nice chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize residuals too small for the next item if next item is big
    // (dead space creation).
    if next_item_size > post_residual && next_item_size > bin_capacity / 2 {
        score += 8.0;
    }

    // Global fragmentation pressure: when mean residual across open bins is
    // high, prefer consolidating into existing bins (penalize new-bin tendency
    // is handled above; here reward using bins with residual >= mean).
    if bin_residual as f64 >= mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Slight preference for filling bins that are already well used
    // (best-fit-like bias beyond raw post_residual).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Small noise-free diversity term using step position to break ties
    // differently over time (exploratory time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (progress * std::f64::consts::PI).sin() * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear (quartic) penalty on dead space
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, dead space matters less; late, tighten aggressively.
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress)
                 + norm_pr * norm_pr * progress * (2.0 - progress);
    score += 40.0 * coupling;

    // Reward placements that leave room for the lookahead item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (gap / cap).powi(2);
        score -= 15.0 * (1.0 - fit_kernel.min(1.0)) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * (open_bins_count as f64).sqrt();

    // Prefer bins that are relatively full (small residual relative to capacity)
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate should be mildly discouraged unless residuals are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;              // 1..=10
    let next_class = (next_item_size / 10) as i64; // 0 if unknown

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64) / cap_f;

    // Reward high fill non-linearly (tight fits prioritized)
    score -= 60.0 * fill * fill;

    // Penalize small dead space that is hard to reuse:
    // post_residual in awkward narrow bands (1..10, 11..20 mod 25)
    if post_residual > 0 {
        let pr_mod = post_residual % 25;
        if post_residual < 10 {
            score += 25.0; // nearly dead space
        } else if pr_mod < 10 && pr_mod > 0 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic match: same or complementary class gets extra reward
        let complement = (item_class + next_class) % 10;
        let mut bonus = 12.0;
        if complement == 0 || next_class == item_class {
            bonus += 10.0;
        }
        score -= bonus;
    } else if next_item_size > 0 {
        // This bin becomes useless for the next item
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += 20.0 + scarcity - 15.0 * (open_bins_count as f64).ln().max(0.0);
        // If the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / cap_f) * 10.0;
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / cap_f));

    // Deviation from mean residual: prefer bins that are outliers (very full)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps that no plausible future item (min size 1..) can pair with well:
    // gaps below the smallest typical item size are near-wasted capacity.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Reward using an existing bin when it is the last fitting bin (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling them rather than opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // extra reward if next item fills the gap almost exactly
        let gap = post_residual - next_item_size;
        score -= (10.0 * (1.0 - gap as f64 / bin_capacity as f64));
    }
    // Penalize if next item does NOT fit in post_residual and gap is small (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening new bins
    // when existing bins have plenty of room and few bins are open.
    if bin_residual == bin_capacity {
        score = 30.0 + 2.0 * open_bins_count as f64 - 10.0 * (mean_residual / bin_capacity as f64);
        // If the current item is large and fits poorly anywhere, new bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's already
    // "full-ish"; placing here consolidates waste.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score += 0.1 * residual_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.6 * match_gap;
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild reward scaled by tightness
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 8.0 * tightness;
        } else {
            // next item won't fit: penalize dead space
            score += 5.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins with residual below mean (tight packing)
    let residual_dev = mean_residual - post_residual as f64;
    score += 0.4 * residual_dev;

    // Penalize very small unusable post-residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * mean_residual;
    }

    // Late-stream consolidation: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly reward this placement (creates a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item reuses leftover space
            let reuse = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * reuse;
        } else {
            // next item cannot use this leftover; penalize large dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 8.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += (post_residual as f64) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item (lots of wasted slack).
    if bin_residual == bin_capacity {
        // Slack across open bins relative to what we'd waste by using one.
        let best_possible_waste = if fitting_bins_count > 0 {
            // approximate: mean residual minus item size
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        // Prefer new bin when open bins have large residuals (bad fits)
        // i.e., when mean_residual is much larger than item_size.
        let pressure = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

        // Base cost of a fresh bin: capacity minus item (its residual).
        score = (bin_capacity - item_size) as f64;
        // If open bins would waste a lot, opening a new bin looks better.
        score -= 70.0 * pressure;
        // Early in the stream, be more willing to open bins (long horizon to fill them).
        score -= 30.0 * (1.0 - progress);
        // Many open bins: discourage spreading too thin.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // Keep the waste term influencing decisions.
        score += 0.05 * best_possible_waste;
        return score;
    }

    // For existing bins: mild penalty for leaving residuals that nothing
    // typical can use (small odd leftovers), reward leaving round residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward filling bins close to full, scaled by how many alternatives exist.
    let fill_ratio = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Slight preference for bins already below mean residual (balance load
    // toward bins with more room when fits are equally tight).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic waste penalty on post_residual
    let mut score = pr + (pr * pr) / cap;

    // Smooth coupling: waste penalty grows with stream progress
    score += (pr * pr) / cap * (progress * (2.0 - progress));

    // Reward bins whose residual after placement matches the next item (lookahead)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap) * (1.0 + progress);
    } else {
        // Last item: minimize waste strongly
        score -= pr / cap * 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins open fit well
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += cap * (0.5 + 0.5 * progress) + 2.0 * fit_pressure;
    } else {
        // Prefer bins tighter than the mean residual (good fit relative to fleet)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 / cap * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 classes.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,                       // perfectly reusable chunk
        1 | 2 => 6.0,                    // nearly dead slivers
        3..=9 => class as f64 * 0.3,     // mild penalty proportional to raggedness
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual (reusability tiers).
    let tier = post_residual / 10;
    score -= (tier as f64).sqrt() * 4.0;

    // Reward tight fits strongly (small post residual).
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= tightness * tightness * 12.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain placement possible
            // extra reward if next item also lands on a good class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = post_residual as f64;
            if gap < next_item_size as f64 * 0.5 {
                score += 4.0; // dead space relative to lookahead
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let spread = mean_residual - post_residual as f64;
        score += 20.0 + spread.clamp(-10.0, 30.0) * 0.5 - progress * 5.0;
        // Opening a bin is more acceptable when many items remain and few bins open.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    } else {
        // Favor bins whose residual deviates from the mean in a useful way.
        let dev = (bin_residual as f64 - mean_residual) / cap_f;
        score -= dev * 6.0;
    }

    // Mild preference to balance load across open bins late in the stream.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum item size (1..100 unknown dist, use 10 as
    // conservative floor) is pure dead space -> quadratic penalty.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // Reward tight fits: perfect fit gets big bonus.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Penalize post_residual that cannot accommodate the lookahead item,
    // but reward if it exactly matches the next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 30.0; // perfect slot for lookahead
            } else {
                score -= 8.0; // still usable for lookahead
            }
        } else {
            score += 12.0; // dead space relative to lookahead
        }
    }

    // Open-bin pressure: discourage spreading into many bins early on,
    // but relax pressure as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (1.0 - progress) * (open_bins_count as f64);
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // new bin baseline; make it slightly worse than a decent fit
        score += 15.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is close to mean
    // (keeps bin states homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item exactly matches the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: mild reward proportional to slack match
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally to wasted size
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving small unusable fragments (dead space) that no typical item fits
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tightness reward: the smaller post_residual relative to bin capacity, the better
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the fit is poor
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it wins only if all existing fits are bad
        score += 25.0;
        if item_size >= bin_capacity * 4 / 5 {
            // Large item: fresh bin is fine (near-full utilization expected)
            score -= 30.0;
        }
    }

    // Contextual coupling with mean residual: prefer bins below mean residual
    // (concentrate filling in emptier bins keeps some bins tight for future items)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight preference to fill older bins first when many bins are open
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 80 {
        score += 4.0; // mildly usable space
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Partial credit for near-miss lookahead fits.
        let miss = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += (miss as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // later, allow more aggressive packing decisions.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // to consolidate, penalize opening/spreading.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        score += 15.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
        // Late in stream, opening a fresh bin is cheaper than fragmenting.
        score -= 20.0 * progress;
    } else {
        // Existing bin: reward when many open bins exist (consolidation pressure).
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // Penalize bins far below mean residual (already fragmented).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically so tight fits dominate.
    let mut score = post * post / cap;

    // Smooth progress coupling: late in the stream, waste becomes costlier.
    score += 0.35 * post * (0.5 + progress) * (post / cap);

    // Reward bins whose post-residual is close to the mean residual
    // (keeps the fleet homogeneous and reusable).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: strongly reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 45.0;
        } else if nxt <= post {
            // next item fits: mildly good, better the tighter the leftover after it
            let second_left = (post - nxt) / cap;
            score -= 12.0 * (1.0 - second_left) * (1.0 - second_left);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.25 * (nxt - post).min(cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: opening a bin is costly; make its score moderate so
    // it only wins when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        score = cap * (1.2 + 0.3 * progress) + 0.5 * open_bins_count as f64;
        // If the next item is small relative to capacity, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) <= 0.5 * cap {
            score -= 15.0;
        }
    } else if bin_residual == bin_capacity {
        // empty-bin-like residual but item placed (shouldn't happen for new bin call)
        score += 5.0;
    }

    // Slight preference for using already-open bins as fleet grows.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly closed -> reward using them.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Perfect fit bonus: exact fill is always optimal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual (capacity fraction classes).
    // Class boundaries at capacity / k for k = 1..6 (harmonic heuristic spirit).
    let mut class_k: u32 = 0;
    for k in 1..=6u32 {
        let bound = bin_capacity / k;
        if post_residual <= bound && post_residual > bin_capacity / (k + 1) {
            class_k = k;
            break;
        }
    }
    // Smaller k = smaller residual class = better packing; reward quadratically.
    score -= (6 - class_k.min(6)) as f64 * 12.0;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown).
    // Penalize residuals in (0, 10) heavily since they may be unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well the next item fills the leftover
            let fill = next_item_size as f64 / post_f.max(1.0);
            score -= fill * 60.0;
            // modulo harmony: next item leaves another clean class boundary
            let npost = post_residual - next_item_size;
            if npost == 0 {
                score -= 150.0;
            }
            for k in 2..=5u32 {
                if npost == bin_capacity / k {
                    score -= 25.0 * k as f64;
                }
            }
        } else {
            // next item cannot use this leftover: penalize large leftovers
            score += post_f * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual.
    if bin_residual == bin_capacity {
        // Penalize opening new bins unless current leftovers are hopeless.
        score += 150.0;
        score += mean_residual * 0.5;
        // But late in stream with many open bins, allow consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor with harmonic twist).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 50.0;

    // Integer-division threshold: reward when item_size divides capacity cleanly
    // into the residual leaving a harmonic boundary.
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 30.0;
    }

    // Mild penalty per open bin to discourage sprawl.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the unusable (1..=9) band are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward if the next item still fits in the leftover space.
        score -= 8.0;
    }

    // Penalize wasteful use of a large residual when the item is small relative to it.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.4 {
        score += (0.4 - fill_ratio) * 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 5.0;
        // But if no open bin fits well (many tight fits), allow a new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Early in the stream, tolerate more open bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for bins whose residual is near the mean (keep balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residual that is too small to ever be useful (dead space).
        // Assume smallest possible future item is 1, but weight by residual size.
        let r = post_residual as f64;
        if r < 10.0 {
            score += 5.0 * (10.0 - r); // tiny dead space penalty
        }

        // 2-step lookahead: reward if next item fits into the post residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64;
            score -= 40.0 + 2.0 * (cap - tight) / cap * 20.0;
        } else if next_item_size > 0 {
            // Next item won't fit here after this placement: mild penalty scaled by waste.
            score += 3.0 * (1.0 - (post_residual as f64) / cap);
        }

        // Compare residual against mean residual of open bins: prefer bins
        // whose residual is below-average (denser bins get emptied first).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0 * (mean_residual - bin_residual as f64).min(50.0);
        } else {
            score += 1.5 * ((bin_residual as f64) - mean_residual).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bins moderately unattractive
    // unless nothing else is good, scaled by stream progress and bin count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small residual is fine, may be filled by tiny items
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_left = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_left as f64 / bin_capacity as f64);
            if next_left == 0 {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // post_residual too small for next item: penalize wasted space.
            score += 0.3 * post_residual as f64;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large mean residual spread / few fitting bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of a fresh bin: its full residual.
        score = bin_capacity as f64 * 0.9;
        // If current item fits badly everywhere, opening a new bin is good.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fit_ratio > 0.6 && post_residual == 0 {
            score -= 30.0;
        } else if mean_residual > item_size as f64 + 20.0 {
            score -= 10.0;
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 15.0;
        // Too many open bins already: prefer reusing.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Mild reward for keeping the number of open bins low.
        score += open_bins_count as f64 * 0.5;
    }

    // Global pressure: when mean residual across open bins is high, prefer
    // placements that reduce it the most.
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Penalize residuals that cannot fit the lookahead item
    let mut score = base;
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + 0.5 * progress);
    }
    // Reward residual that can accommodate the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / cap) * (1.0 - progress) * 4.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (0.5 + progress);
    }

    // Mild penalty for proliferating open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).abs();

    // Slight preference for tight fits (low post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 2.0;

    // New-bin candidate: neutral-ish baseline, only chosen when open bins score worse
    if bin_residual == bin_capacity {
        score += 5.0 + 5.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: exact or near-exact fills are heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class logic: partition post_residual by capacity fractions.
        let cap_f = bin_capacity as f64;
        let pr = post_residual as f64;
        // Quarters of capacity define "harmonic" residual classes.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;

        // Residuals that fall into small harmonic classes are still usable
        // for typical items (1..100), so penalize proportionally less.
        if post_residual <= quarter {
            score -= 0.35 * pr; // small dead space, mild penalty
        } else if post_residual <= third {
            score += 0.05 * pr; // awkward mid-small class
        } else if post_residual <= half {
            score -= 0.10 * pr; // half-capacity class still quite usable
        } else {
            score += 0.15 * pr; // large residual means poor fit here
        }

        // Integer-division threshold coupling: residual mod classes.
        let m = post_residual % 10;
        score -= (5 - ((m as i32) - 5).abs()) as f64 * 0.3; // prefer residuals near multiples of 10

        if post_residual % 2 == 0 {
            score -= 1.0;
        }
    }

    // Lookahead (k=2): reward bins whose post_residual can host next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this leftover: penalize proportional waste.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity - item_size; acceptable when
        // item is large or no good fit exists elsewhere.
        score = (bin_capacity - item_size) as f64 + 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // large items start fresh bins happily
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (mean_residual / bin_capacity as f64).recip().min(4.0);

    // Many open bins: discourage spreading into low-utilization bins.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are pure waste — penalize quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Favor tight fits: reward small (but usable) post residuals.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.35;
    }

    // If the next item can exactly fill this bin's post residual,
    // strongly reward placing here (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover — leftover likely becomes dead space.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins unless the fit is terrible.
    let open_pressure = open_bins_count as f64 * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has huge residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a good fit
        // (large dead space elsewhere) or when the item is large.
        let dead_elsewhere = (mean_residual - post_residual as f64).max(0.0);
        if dead_elsewhere > 25.0 || item_size > 70 {
            score -= 25.0;
        } else {
            score += 30.0;
        }
    }

    // Mild stream-progression term: early on, be more permissive about
    // spreading items; late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Tie-break: prefer bins whose residual is close to the mean residual
    // (keeps the bin set homogeneous and predictable).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Perfect or near-perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly.
            let slack = post_residual - next_item_size;
            score -= 80.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize leaving awkward gaps.
            score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: bins with less residual than average are
    // more "committed"; placing there is fine if fit is tight.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 10.0 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 5.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 40.0 + 60.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // unusable gap for the lookahead item
        }
        // Reward residuals that exactly accommodate the next item.
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
        }
    } else {
        // Last item: filling a bin as full as possible is ideal.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: slight penalty to preserve diversity of residual sizes.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Prefer bins with residuals below the mean (consolidate waste).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, keep bins open and flexible;
    // late in the stream, pack tightly and close bins out.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 1.0 };
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when open bins could fit, unless residuals are large.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let waste_if_skip = avg_open - item_size as f64;
        if waste_if_skip > 0.0 && fitting_bins_count > 0 {
            score += 10.0 + 0.1 * waste_if_skip;
        } else {
            score += 2.0;
        }
        // Opening a bin is cheaper late when residuals are fragmented.
        score -= 3.0 * progress;
    }

    // Mild penalty for many open bins early on (fragmentation control).
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Small coupling: very large items prefer the emptiest bin.
    if item_size > 60 {
        score += 0.05 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t) - norm_pr * (0.5 + t * 0.5);
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual) * (1.0 + t);

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 8.0 * fits_next * snug * (0.6 + 0.4 * t);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate: penalize mildly early, more if it wastes capacity late
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * t;
        // but if no bin fits well, opening new is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0..10] is nearly unusable
    // for typical items -> heavy penalty; exact fit is best.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0;
    } else if pr < 10 {
        score += 12.0; // dead space class
    } else {
        // Integer-division thresholds: reward post_residual that matches
        // harmonic classes of likely next items (multiples of 10).
        let class = pr / 10; // 1..10
        score -= (class as f64) * 0.8;
    }

    // Fractional capacity coupling: reward bins whose fill ratio is harmonically
    // aligned (residual close to a fraction of capacity like 1/2, 1/3, 1/4).
    let res_frac = bin_residual as f64 / cap;
    for denom in [2.0f64, 3.0, 4.0] {
        let target = 1.0 / denom;
        let d = (res_frac - target).abs();
        if d < 0.05 {
            score -= 4.0 / denom;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportionally to how well next item uses the leftover
        score -= 10.0 * (next_item_size as f64 / pr as f64);
    } else if next_item_size > pr && next_item_size > 0 {
        // leftover won't host the next item: mild penalty, worse if large leftover
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        let tightness = if pr < 10 { 0.0 } else { 1.0 };
        score += 18.0 + 10.0 * tightness;
        // early in stream, opening bins is cheaper; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // if many bins already open, discourage another
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small but
    // too large to be safely considered zero) is heavily penalized.
    let dead_zone_low = 1.0;
    let dead_zone_high = 12.0;
    if post_residual as f64 >= dead_zone_low && post_residual as f64 <= dead_zone_high {
        // Peak penalty at the middle of the dead zone
        let mid = (dead_zone_low + dead_zone_high) / 2.0;
        let depth = 1.0 - ((post_residual as f64 - mid).abs() / (dead_zone_high - dead_zone_low));
        score += 40.0 * depth * depth;
    }

    // Perfect fit gets a strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8) * 5.0;
    }

    // Open bins pressure: penalize placing into bins when many bins are open,
    // to encourage consolidation into fewer bins.
    score += open_bins_count as f64 * 0.8;

    // If this is the only bin that can fit the item, strongly favor it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., bins that are more filled) to consolidate.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: make opening a new bin costly unless the current
    // bin residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if the item is large and mean residual is small, opening a new
        // bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - 2.0 * fit_ratio).powi(2).max(0.0) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly accommodates the next item (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - chain_slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving a residual too small for the next item (dead space).
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins that reduce dispersion.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * item_size as f64;
    }

    // Late-stream pressure: consolidate more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}
